window.LEO_TEXTY = {"oddily":{"Favole":"Bajky","Allegorie":"Alegorie a bestiář","Pensieri sulla scienza":"Myšlenky o vědě","Pensieri sulla natura":"Myšlenky o přírodě","Pensieri sulla morale":"Myšlenky o mravnosti","Difesa della pittura":"Obrana malířství","Il pittore e la pittura":"Malíř a malba","Paragone della pittura con la scultura":"Malířství a sochařství","I paesi":"Krajiny","Il viaggio in Oriente":"Cesta na Východ","Le figure":"Postavy","Profezie":"Proroctví","Facezie":"Žerty"},"rukopisy":{"C.A":"Codex Atlanticus (Ambrosiana, Milán)","A":"Rukopis A (Institut de France, Paříž)","B":"Rukopis B (Institut de France)","C":"Rukopis C (Institut de France)","D":"Rukopis D (Institut de France)","E":"Rukopis E (Institut de France)","F":"Rukopis F (Institut de France)","G":"Rukopis G (Institut de France)","H":"Rukopis H (Institut de France)","I":"Rukopis I (Institut de France)","K":"Rukopis K (Institut de France)","L":"Rukopis L (Institut de France)","M":"Rukopis M (Institut de France)","P":"Rukopis F (tisková chyba v Solmim?)","Ash.I":"Ashburnham I (rukopis 2038, Paříž)","Ash.I.A":"Ashburnham I (rukopis 2038, Paříž)","Ash.II":"Ashburnham II (rukopis 2037, Paříž)","Ash.III":"Ashburnham 361 (Laurenziana, Florencie)","T":"Codex Trivulzianus (Milán)","V.U":"Kodex o letu ptáků (Turín)","An.A":"Anatomické listy A (Windsor)","R":"Richter 1883 (číslo úryvku)","Lu":"Pojednání o malířství, vyd. Ludwig 1882 (číslo kapitoly)"},"uryvky":[{"id":"s001","o":"Favole","c":"I","str":3,"ni":"l’irrequietezza","nc":"Neklid","it":["Il torrente portò tanto di terra e pietre nel suo letto, che fu costretto a mutar sito."],"cs":["Bystřina nanesla do svého koryta tolik hlíny a kamení, že byla nucena změnit místo."],"ref":{"s":"R","l":1314,"st":"","z":false,"raw":"R. 1314"},"ca":[],"rr":"Br. M. 42 b"},{"id":"s002","o":"Favole","c":"II","str":3,"ni":"la carta e l’inchiostro","nc":"Papír a inkoust","it":["Vedendosi la carta tutta macchiata dalla oscura negrezza dell’inchiostro, di quello si duole; il quale mostra a essa, che per le parole, che sono sopra lei composte, essere cagione della conservazione di quella."],"cs":["Papír, vida se celý pošpiněný temnou černí inkoustu, si na něj stěžuje; a ten mu ukazuje, že právě slovy, která jsou na něm složena, je příčinou jeho zachování."],"ref":{"s":"R","l":1322,"st":"","z":false,"raw":"R. 1322"},"ca":[],"rr":"S. K. M. III. 66 b"},{"id":"s003","o":"Favole","c":"III","str":3,"ni":"l’acqua","nc":"Voda","it":["Trovandosi l’acqua nel superbo mare, suo elemento, le venne voglia di montare sopra l’aria, e, confortata dal foco elemento, elevatasi in sottile vapore, quasi parea della sottigliezza dell’aria. Montata in alto, giunse infra l’aria più sottile e fredda, dove fu abbandonata dal foco; e i piccoli granicoli, sendo restretti, già s’uniscono e fannosi pesanti, ove, cadendo, la superbia si converte in fuga. E cade dal cielo; onde poi fu bevuta dalla secca terra, dove, lungo tempo incarcerata, fece penitenza del suo peccato."],"cs":["Voda, nacházejíc se v pyšném moři, svém živlu, zatoužila vystoupit nad vzduch; a povzbuzena živlem ohně, vznesla se v jemnou páru a zdála se být téměř tak jemná jako vzduch. Vystoupivši do výše, dostala se mezi vzduch řidší a studenější, kde ji oheň opustil; a drobná zrníčka, stažena, se už spojují a těžknou, a padajíce, mění pýchu v útěk. I padá z nebe; načež ji vypila vyprahlá země, kde, dlouhý čas vězněna, konala pokání za svůj hřích."],"ref":{"s":"R","l":1271,"st":"","z":false,"raw":"R. 1271"},"ca":[],"rr":"S. K. M. III. 93 b"},{"id":"s004","o":"Favole","c":"IV","str":4,"ni":"la fiamma e la candela","nc":"Plamen a svíce","it":["Le fiamme, già uno mese durato nella fornace de’ bicchieri, e veduto a sè avvicinarsi una candela, ’n un bello e lustrante candeliere, con gran desiderio si forzavano accostarsi a quella. Infra le quali una, lasciato il suo naturale corso, e tiratasi d’entro a uno voto stizzo, dove si pasceva, e uscita da l’opposito fori d’una piccola fessura, alla candela, che vicina l’era, si gittò, e con somma golosità e ingordigia quella divorando, quasi al fine condusse; e volendo riparare al prolungamento della sua vita, indarno tentò tornare alla fornace, donde partita s’era, perchè fu costretta morire e mancare, insieme colla candela; onde al fine, con pianti e pentimenti, in fastidioso fumo si convertì, lasciando tutte le sorelle in isplendevole e lunga vita e bellezza."],"cs":["Plameny, které už měsíc hořely ve sklářské peci, uviděly, jak se k nim přibližuje svíce v krásném a lesklém svícnu, a s velikou touhou se snažily k ní přiblížit. Jeden z nich opustil svůj přirozený běh, vtáhl se do dutého polena, jímž se živil, vyšel na opačné straně ven malou škvírou a vrhl se na svíci, která mu byla nablízku; a s nejvyšší chtivostí a hltavostí ji pohlcuje, až ji skoro dovedl ke konci. A chtěje si prodloužit život, marně se pokoušel vrátit se do pece, z níž odešel, neboť byl nucen zemřít a zaniknout spolu se svící; a tak se nakonec s nářkem a lítostí obrátil v protivný dým a zanechal všechny své sestry v zářivém a dlouhém životě a kráse."],"ref":{"s":"C.A","l":67,"st":"r","z":false,"raw":"C. A. 67 r"},"ca":[372,374]},{"id":"s005","o":"Favole","c":"V","str":5,"ni":"quelli che s’umiliano, sono esaltati","nc":"Kdo se ponižuje, bude povýšen","it":["Trovandosi alquanta poca neve appiccata alla sommità d’un sasso, il quale era collocato sopra la strema altezza d’una altissima montagna, e raccolto in sè l’imaginazione, cominciò con quella a considerare, e infra sè dire:","— Or non son io da essere giudicata altera e superba, avere me, picciola dramma di neve, posto in sì alto loco, e sopportare che tanta quantità di neve, quanto di qui per me essere veduta po’, stia più bassa di me? Certo la mia poca quantità non merta quest’altezza, chè bene posso, per testimonianza della mia piccola figura, conoscere quello che ’l sole fece ieri alle mie compagne, le quali in poche ore dal sole furono disfatte; e questo intervenne per essersi poste più alto, che a loro non si richiedea. Io voglio fuggire l’ira del sole, e abbassarmi, e trovare loco conveniente alla mia parva quantità. — E gittatasi in basso, e cominciata a discendere, rotando dall’alte spiagge su per l’altra neve, quanto più cercò loco basso, più crebbe sua quantità, in modo che, terminato il suo corso, sopra uno colle si trovò di non quasi minor grandezza, che ’l colle che essa sostenea; e fu l’ultima che in quella state dal sole disfatta fusse. Detta per quelli, che s’aumiliano son esaltati."],"cs":["Trochu sněhu, které se drželo na vrcholu skály ležící na nejzazší výšině převysoké hory, se zahloubalo do sebe a počalo uvažovat a říkat si:","– Což nemusím být pokládán za zpupný a pyšný, že já, malý drobek sněhu, jsem se usadil na tak vysokém místě a snáším, aby tak veliké množství sněhu, jaké odtud mohu vidět, bylo níže než já? Jistě si má malá hojnost tuto výšku nezaslouží, neboť dobře mohu podle svědectví své nepatrné postavy poznat, co včera slunce udělalo mým druhům, které během několika hodin roztálo; a to se stalo proto, že se usadily výš, než jim příslušelo. Chci uniknout hněvu slunce, ponížit se a najít místo přiměřené své nepatrnosti. – A vrhl se dolů, počal sestupovat a kutálet se z vysokých strání po ostatním sněhu, a čím více hledal nízké místo, tím víc rostl, takže když skončil svou pouť, ocitl se na pahorku sotva menší než pahorek, který jej nesl; a byl posledním sněhem, který to léto slunce rozpustilo. Řečeno o těch, kdo se ponižují a bývají povýšeni."],"ref":{"s":"R","l":1314,"st":"","z":false,"raw":"R. 1314"},"ca":[],"rr":"Br. M. 42 b"},{"id":"s006","o":"Favole","c":"VI","str":6,"ni":"sul medesimo soggetto","nc":"Na totéž téma","it":["La palla della neve, quanto più rotolando discese dalle montagne della neve, tanto più multiplicò la sua magnitudine."],"cs":["Sněhová koule, čím víc se kutálela dolů ze zasněžených hor, tím víc znásobovala svou velikost."],"ref":{"s":"C.A","l":67,"st":"v","z":false,"raw":"C. A. 67 v"},"ca":[373,375]},{"id":"s007","o":"Favole","c":"VII","str":6,"ni":"la pietra","nc":"Kámen","it":["Una pietra, novamente per l’acqua scoperta, di bella grandezza, si stava sopra un certo loco rilevato, dove terminava un dilettevole boschetto, sopra una sassosa strada, in compagnia d’erbe, di vari fiori di diversi colori ornati; e vedea la gran somma delle pietre, che, nella a sè sottoposta strada, collocate erano. Le venne desiderio di là giù lasciarsi cadere, dicendo con seco:","— Che fo io qui con queste erbe? io voglio con queste mie sorelle in compagnia abitare. — E, giù lasciatasi cadere, infra le desiderate compagne finì suo volubile corso.","E stata alquanto, cominciò a essere dalle rote de’ carri, dai pie de’ ferrati cavalli e de’ viandanti a essere in continuo travaglio; chi la volta, quale la pestava, alcuna volta si levava alcuno pezzo, quando stava coperta da fango o sterco di qualche animale, e invano riguardava il loco donde partita s’era, in nel loco della soletaria e tranquilla pace. Così accade a quelli, che dalla vita soletaria contemplativa vogliono venir abitare nella città, infra i popoli pieni d’infiniti mali."],"cs":["Kámen pěkné velikosti, nedávno odkrytý vodou, ležel na jakémsi vyvýšeném místě, kde končil půvabný hájek, nad kamenitou cestou, ve společnosti bylin a rozmanitých květů různých barev; a viděl velké množství kamenů, které byly uloženy na cestě pod ním. I zatoužil spustit se tam dolů a řekl si:","– Co tu dělám s těmi bylinami? Chci bydlet ve společnosti těchto svých sester. – A spustiv se dolů, skončil svou kotoulivou pouť mezi vytouženými druhy.","A když tam chvíli pobyl, počal být v ustavičném soužení od kol vozů, od kopyt podkovaných koní i od nohou pocestných; tu jej kdo převrátil, tu jej kdo rozdrtil, někdy se trochu vynořil, když byl pokryt blátem nebo trusem nějakého zvířete, a marně se ohlížel po místě, odkud odešel, po místě osamělého a tichého pokoje. Tak se stává těm, kdo chtějí z osamělého rozjímavého života přijít bydlet do města, mezi lid plný nesčetných zel."],"ref":{"s":"C.A","l":172,"st":"v","z":false,"raw":"C. A. 172 v"},"ca":[941,943]},{"id":"s008","o":"Favole","c":"VIII","str":7,"ni":"il rasoio","nc":"Břitva","it":["Uscendo un giorno il rasoio di quel manico, col quale si fa guaina a se medesimo, e postosi al sole, vide il sole specchiarsi nel suo corpo; della qual cosa prese somma gloria, e rivolto col pensiero indirieto, cominciò con seco medesimo a dire:","— Or tornerò io più a quella bottega, della quale novamente uscito sono? certo no; non piaccia alli Dei, che sì splendida bellezza caggia in tanta viltà d’animo! Che pazzia sarebbe quella, la qual mi conducesse a radere le insaponate barbe de rustici villani e fare meccaniche operazioni! È questo corpo da simili esercizi? Certo no. Io mi voglio nascondere in qualche occulto loco, e lì con tranquillo riposo passare mia vita. — E così, nascosto per alquanti mesi, un giorno ritornato all’aria, e uscito fori della sua guaina, vide se essere fatto a similitudine d’una rugginente sega, e la sua superficie non rispecchiare più lo splendente sole. Con vano pentimento indarno pianse lo irreparabile danno, con seco dicendo: — Oh! quanto meglio era esercitare col barbiere il mio perduto taglio di tanta sottilità! Dov’è la lustrante superficie? certo la fastidiosa e brutta ruggine l’ha consumata! — Questo medesimo accade nelli ingegni, che in scambio dello esercizio si danno all’ozio; i quali, a similitudine del sopradetto rasoio, perdono la tagliente sua sottilità, e la ruggine dell’ignoranza guasta la sua forma."],"cs":["Jednoho dne vyšla břitva z rukojeti, která jí sloužila za pochvu, a položila se na slunce; i uviděla, jak se slunce zrcadlí v jejím těle. Nesmírně se tím pyšnila, a obrátivši myšlenky nazpět, počala si sama pro sebe říkat:","– Což se ještě vrátím do té dílny, z níž jsem právě vyšla? Jistě ne! Nedejte bohové, aby tak skvělá krása klesla k takové nízkosti ducha! Jaké by to bylo bláznovství, které by mě vedlo holit namydlené vousy hrubých sedláků a konat řemeslnou práci! Je toto tělo pro takovou činnost? Jistě ne. Chci se skrýt na nějakém skrytém místě a tam strávit život v tichém odpočinku. – A tak se skrývala několik měsíců; a když se jednoho dne vrátila na vzduch a vyšla ze své pochvy, uviděla, že se podobá zrezivělé pile a že její povrch už nezrcadlí zářící slunce. S marnou lítostí naříkala nadarmo nad nenapravitelnou škodou a říkala si: – Ach, oč lépe bylo cvičit u holiče své ztracené ostří tak jemné! Kde je ten lesklý povrch? Jistě jej strávila protivná a ošklivá rez! – Totéž se děje s duchy, kteří se místo cvičení oddávají zahálce; ti podobně jako zmíněná břitva ztrácejí svou ostrou jemnost a rez nevědomosti kazí jejich podobu."],"ref":{"s":"C.A","l":172,"st":"v","z":false,"raw":"C. A. 172 v"},"ca":[941,943]},{"id":"s009","o":"Favole","c":"IX","str":8,"ni":"il giglio","nc":"Lilie","it":["Il giglio si pose sopra la ripa di Tesino, e la corrente tirò la ripa insieme col giglio."],"cs":["Lilie se usadila na břehu Ticina, a proud strhl břeh i s lilií."],"ref":{"s":"H","l":44,"st":"r","z":false,"raw":"H. 44 r"},"ca":[]},{"id":"s010","o":"Favole","c":"X","str":8,"ni":"il noce","nc":"Ořešák","it":["Il noce, mostrando sopra una strada ai viandanti la ricchezza de’ sua frutti, ogni omo lo lapidava."],"cs":["Ořešák ukazoval nad cestou pocestným bohatství svých plodů, a každý po něm házel kamením."],"ref":{"s":"C.A","l":76,"st":"r","z":false,"raw":"C. A. 76 r"},"ca":[412,414]},{"id":"s011","o":"Favole","c":"XI","str":9,"ni":"il fico","nc":"Fíkovník","it":["Il fico stando sanza frutti, nessuno lo riguardava; volendo, col fare essi frutti, essere laudato da li omini, fu da quelli piegato e rotto."],"cs":["Když byl fíkovník bez plodů, nikdo si ho nevšímal; když pak chtěl, aby ho lidé chválili za plody, které vydal, ohnuli ho a polámali."],"ref":{"s":"C.A","l":76,"st":"r","z":false,"raw":"C. A. 76 r"},"ca":[412,414]},{"id":"s012","o":"Favole","c":"XII","str":9,"ni":"la pianta e il palo","nc":"Rostlina a kůl","it":["La piante si dole del palo secco e vecchio, che se l’era posto a lato, e de’ pali secchi che la circondano: l’un lo mantiene diritto, l’altro lo guarda dalla triste compagnia."],"cs":["Rostlina si stěžuje na suchý a starý kůl, který jí postavili po boku, a na suché kůly, které ji obklopují: jeden ji udržuje rovnou, druhé ji chrání před zlou společností."],"ref":{"s":"C.A","l":70,"st":"r","z":false,"raw":"C. A. 70 r"},"ca":[386]},{"id":"s013","o":"Favole","c":"XIII","str":9,"ni":"il cedro e le altre piante","nc":"Cedr a ostatní stromy","it":["Il cedro, insuperbito della sua bellezza, dubita delle piante, che li son d’intorno, e fattolesi torre dinanzi, il vento poi, non essendo interrotto, lo gittò per terra diradicato."],"cs":["Cedr, zpychlý svou krásou, má nedůvěru ke stromům, které jsou kolem něho, a dá je odstranit; vítr pak, když mu už nic nestojí v cestě, jej vyvrátil i s kořeny a povalil na zem."],"ref":{"s":"C.A","l":76,"st":"r","z":false,"raw":"C. A. 76 r"},"ca":[412,414]},{"id":"s014","o":"Favole","c":"XIV","str":9,"ni":"la vitalba","nc":"Plamének","it":["La vitalba, non istando contenta nella sua siepe, cominciò a passare co’ sua rami la comune strada, e appiccarsi all’opposita siepe; onde da’ viandanti poi fu rotta."],"cs":["Plamének, nespokojen ve svém plotě, začal svými úponky přerůstat přes veřejnou cestu a zachycovat se protějšího plotu; a proto jej pak pocestní přetrhali."],"ref":{"s":"C.A","l":76,"st":"r","z":false,"raw":"C. A. 76 r"},"ca":[412,414]},{"id":"s015","o":"Favole","c":"XV","str":10,"ni":"la cattiva compagnia trascina i buoni nella propria rovina","nc":"Špatná společnost strhne dobré do vlastní záhuby","it":["La vite, invecchiata sopra l’albero vecchio, cade insieme colla ruina d’esso albero; e fu, per la trista compagnia, a mancare insieme con quella."],"cs":["Réva, zestárlá na starém stromě, padá spolu se zkázou toho stromu; a pro špatnou společnost musela zahynout s ním."],"ref":{"s":"R","l":1314,"st":"","z":false,"raw":"R 1314"},"ca":[],"rr":"Br. M. 42 b"},{"id":"s016","o":"Favole","c":"XVI","str":10,"ni":"sul medesimo soggetto","nc":"Na totéž téma","it":["Il salice, che, per li sua lunghi germinamenti, vol crescere da superare ciascuna altra pianta, per avere fatto compagnia colla vite, che ogni anno si pota, fu ancora lui sempre storpiato."],"cs":["Vrba, která svými dlouhými výhonky chce dorůst tak, aby předčila každý jiný strom, byla, protože se spolčila s révou, kterou každý rok prořezávají, také sama vždy zmrzačena."],"ref":{"s":"R","l":1314,"st":"","z":false,"raw":"R. 1314"},"ca":[],"rr":"Br. M. 42 b"},{"id":"s017","o":"Favole","c":"XVII","str":10,"ni":"il cedro","nc":"Cedr","it":["Avendo il cedro desiderio di fare uno bello e grande frutto in nella sommità di sè, lo mise a seguizione con tutte le forze del suo omore: il quale frutto cresciuto, fu cagione di fare declinare la elevata e diritta cima."],"cs":["Cedr zatoužil vydat na svém vrcholu krásný a veliký plod a vložil do toho všechnu sílu své mízy; ten plod však, když dorostl, způsobil, že se vysoký a rovný vrchol sklonil."],"ref":{"s":"C.A","l":76,"st":"r","z":false,"raw":"C. A. 76 r"},"ca":[412,414]},{"id":"s018","o":"Favole","c":"XVIII","str":10,"ni":"il persico","nc":"Broskvoň","it":["Il persico, avendo invidia alla gran quantità de’ frutti visti fare al noce suo vicino, diliberato fare il simile, si caricò de’ sua in modo tale, che ’l peso di detti frutti lo tirò diradicato e rotto alla piana terra."],"cs":["Broskvoň, závidíc velikou spoustu plodů, které viděla nést svého souseda ořešák, rozhodla se učinit totéž a obtížila se svými plody tak, že ji jejich váha vyvrátila a zlomenou strhla na rovnou zem."],"ref":{"s":"C.A","l":76,"st":"r","z":false,"raw":"C. A. 76 r"},"ca":[412,414]},{"id":"s019","o":"Favole","c":"XIX","str":11,"ni":"l’olmo e il fico","nc":"Jilm a fíkovník","it":["Stando il fico vicino all’olmo, e riguardando i sua rami essere sanza frutti, e avere ardimento di tenere il sole a’ sua acerbi fichi, con rampogne gli disse: — Olmo, non hai tu vergogna a starmi dinanzi? Ma aspetta che i mia figlioli sieno in matura età, e vedrai dove ti troverai. I quali figlioli poi maturati, capitandovi una squadra di soldati, fu da quelli, per torre i sua fichi, tutto lacerato e diramato e rotto. Il quale, stando poi così storpiato delle sue membra, l’olmo lo dimandò dicendo: — O fico, quanto era il meglio a stare sanza figlioli, che per quelli venire in sì miserabile stato!"],"cs":["Fíkovník stál vedle jilmu, a vida, že jeho větve jsou bez plodů, a že se přesto opovažuje zaclánět slunce jeho nezralým fíkům, pravil mu s výčitkou: – Jilme, nestydíš se stát přede mnou? Ale počkej, až moje děti dospějí, a uvidíš, kde se ocitneš. – Když pak jeho děti uzrály, přitáhl tam oddíl vojáků, a ti ho, aby mu vzali fíky, celého rozedrali, olámali mu větve a zpřelámali ho. A když tak stál se zmrzačenými údy, tázal se ho jilm: – Ó fíkovníku, oč lepší bylo zůstat bez dětí, než se kvůli nim dostat do tak bídného stavu!"],"ref":null,"ca":[]},{"id":"s020","o":"Favole","c":"XX","str":11,"ni":"le piante e il pero","nc":"Stromy a hrušeň","it":["Vedendo il lauro e mirto tagliare il pero, con alta voce gridarono: - O pero! ove vai tu? ov’è la superbia, che avevi, quando avevi i tua maturi frutti? Ora non ci farai tu ombra colle tue folte chiome! Allora il pero rispose: — Io ne vo coll’agricola, che mi taglia, e mi porterà alla bottega d’ottimo scultore, il quale mi farà con su’ arte pigliare la forma di Giove Iddio, e sarò dedicato nel tempio, e dagli omini adorato invece di Giove; e tu ti metti in punto a rimanere ispesso storpiata e pelata de’ tua rami, i quali mi fieno da li omini, per onorarmi, posti d’intorno."],"cs":["Když vavřín a myrta viděly, jak kácejí hrušeň, zvolaly hlasitě: – Ó hrušni! Kam jdeš? Kde je pýcha, kterou jsi měla, když jsi nesla své zralé plody? Teď už nám nebudeš dělat stín svou hustou korunou! – Hrušeň tehdy odpověděla: – Odcházím s rolníkem, který mě poráží a odnese mě do dílny výtečného sochaře; ten mi svým uměním dá podobu boha Jova, a budu zasvěcena v chrámu a lidé mě budou uctívat místo Jova. A ty se připrav, že budeš často zmrzačena a olupována o své ratolesti, jimiž mě lidé, aby mi vzdali poctu, budou obkládat."],"ref":null,"ca":[]},{"id":"s021","o":"Favole","c":"XXI","str":12,"ni":"la rete","nc":"Síť","it":["La rete, che soleva pigliare li pesci, fu presa e portata via dal furor de’ pesci."],"cs":["Síť, která chytávala ryby, byla chycena a odnesena zuřivostí ryb."],"ref":{"s":"R","l":1314,"st":"","z":false,"raw":"R. 1314"},"ca":[],"rr":"Br. M. 42 b"},{"id":"s022","o":"Favole","c":"XXII","str":12,"ni":"nasce rovina dal seguire il falso splendore","nc":"Záhuba plyne z následování falešného lesku","it":["Non si contentando il vano e vagabondo parpaglione di potere comodamente volare per l’aria, vinto dalla dilettevole fiamma della candela, diliberò volare in quella, e ’l suo giocondo movimento, fu cagione di subita tristizia. Imperocchè ’n detto lume si consumarono le sottili ali, e ’l parpaglione misero, caduto tutto bruciato a’ piè del candeliere, dopo molto pianto e pentimento, si rasciugò le lagrime dai bagnati occhi, e levato il viso in alto, disse: — O falsa luce! tempi miserabilmente ingannati! Oh. s’i pure volevo vedere la luce, non dovev’io conoscere il sole dal falso lume dello sporco sevo? —"],"cs":["Marnivý a těkavý motýl, nespokojen s tím, že může pohodlně létat vzduchem, přemožen lákavým plamenem svíce, rozhodl se do něho vletět; a jeho radostný pohyb byl příčinou náhlého žalu. Neboť v tom světle shořela jeho jemná křídla, a ubohý motýl, spadnuv celý ožehnutý k patě svícnu, po dlouhém pláči a lítosti osušil slzy z mokrých očí, zvedl tvář vzhůru a pravil: – Ó falešné světlo! Ó časy bídně oklamané! Ach, jestliže jsem už chtěl vidět světlo, neměl jsem rozeznat slunce od falešného světla špinavého loje? –"],"ref":{"s":"C.A","l":67,"st":"r","z":false,"raw":"C. A. 67 r"},"ca":[372,374]},{"id":"s023","o":"Favole","c":"XXIII","str":13,"ni":"il castagno e il fico","nc":"Kaštan a fíkovník","it":["Vedendo il castagno l’omo sopra il fico, il quale piegava in verso se i sua rami, e di quelli ispiccava i maturi frutti — i quali metteva nell’aperta bocca disfacendoli e disertandoli coi duri denti — crollando i lunghi rami, e con tumultuevole mormorio disse: — O fico! Quanto se’ tu men di me obbligato alla natura! Vedi, come in me ordinò serrati i mia dolci figlioli, prima vestiti di sottile camicia, sopra la quale è posta la dura e foderata pelle; e, non contentandosi di tanto beneficarmi, ch’ell’ha fatto loro la forte abitazione, e sopra quella fondò acute e folte spine, a ciò che le mani dell’omo non mi possino nuocere? — Allora il fico cominciò insieme co’ sua figlioli a ridere, e, ferme le risa, disse: — Conosci, l’omo essere di tale ingegno, che lui ti sappi colle pertiche e pietre e sterpi, trarti infra i tua rami, farti povero de’ tua frutti, e quelli caduti, pesti co’ piedi e co’ sassi, in modo che frutti tua escino, stracciati e storpiati, fora dell’armata casa; e io sono con diligenza tocco dalle mani, e non, come te, da bastoni e da sassi.—"],"cs":["Kaštan, vida člověka na fíkovníku, jak k sobě ohýbá jeho větve a trhá z nich zralé plody – které vkládal do otevřených úst a tvrdými zuby je rozmělňoval a ničil – zatřásl dlouhými větvemi a s bouřlivým šumem pravil: – Ó fíkovníku! Oč méně než já jsi zavázán přírodě! Pohleď, jak u mne uložila mé sladké děti pevně uzavřené, nejprve oděné do tenké košilky, na níž je položena tvrdá a podšitá slupka; a nespokojila se tím, že mi tolik prospěla, když jim zřídila pevný příbytek, ale navrch na něm založila ostré a husté bodliny, aby mi lidské ruce nemohly ublížit. – Tu se fíkovník začal se svými dětmi smát, a když přestal, řekl: – Věz, že člověk je tak důmyslný, že tě dovede tyčemi, kamením a klacky, které vrhá mezi tvé větve, připravit o tvé plody, a ty spadlé pak drtí nohama a kameny, takže tvé plody vycházejí rozedrané a zmrzačené ven z obrněného domu; mne se však ruce dotýkají opatrně, a ne jako tebe, holemi a kamením. –"],"ref":{"s":"C.A","l":67,"st":"r","z":false,"raw":"C. A. 67 r"},"ca":[372,374]},{"id":"s024","o":"Favole","c":"XXIV","str":14,"ni":"il rovistico e il merlo","nc":"Lýkovec a kos","it":["Il rovistrico, sendo stimolato nelli sua sottili rami, ripieni di novelli frutti, dai pungenti artigli e becco delle importune merle, si doleva con pietoso rammarico inverso essa merla, pregando quella, che, poichè lei li toglieva i sua diletti frutti, il meno non lo privassi de le foglie, le quali lo difendevano dai cocenti raggi del sole, e che coll’acute unghie non scorticasse e disvestisse della sua tenera pelle. A la quale la merla, con villane rampogne, rispose: — Oh! taci salvatico sterpo! Non sai, che la natura t’ha fatti produrre questi frutti per mio notrimento? Non vedi, che se’ al mondo pei servirmi di tale cibo? Non sai, villano, che tu sarai, nella prossima invernata notrimento e cibo del foco? — Le quali parole ascoltate dall’albero pazientemente, non sanza lacrime, infra poco tempo, — il merlo preso dalla ragna e còlti de’ rami per fare gabbia, per incarcerare esso merlo, — toccò, infra l’altri rami, al sottile rovistrice a fare le vimini de la gabbia; le quali vedendo essere causa della persa libertà del merlo, rallegratosi, mosse tali parole: — O merlo!, i’ son qui non ancora consumato, come dicevi, dal foco; prima vederò te prigione, che tu me bruciato! —"],"cs":["Lýkovec, jehož tenké větvičky, plné čerstvých plodů, trápily ostré drápy a zobák dotěrné kosice, si žalostně stěžoval té kosici a prosil ji, aby, když už mu bere jeho milé plody, ho aspoň nepřipravovala o listí, které ho chrání před žhavými paprsky slunce, a aby ostrými nehty nedrala a nesvlékala jeho jemnou kůru. Kosice mu však s hrubými výčitkami odpověděla: – Ach, mlč, divoký keři! Nevíš, že ti příroda dala nést tyto plody pro mou výživu? Nevidíš, že jsi na světě proto, abys mi takovou potravou sloužil? Nevíš, ty hulváte, že budeš příští zimu výživou a potravou ohně? – Ta slova strom vyslechl trpělivě, ne však bez slz; a za nedlouho – když byl kos chycen do sítě a nařezaly se větve na klec, do níž ho zavřou – připadlo mezi jinými větvemi i tenkému lýkovci, aby dal pruty na klec. A vida, že jsou příčinou kosovy ztracené svobody, zaradoval se a pronesl tato slova: – Ó kose, jsem tu a ještě mě oheň nestrávil, jak jsi říkal; dřív uvidím tebe v zajetí, nežli ty mne spáleného! –"],"ref":{"s":"C.A","l":67,"st":"r","z":false,"raw":"C. A. 67 r"},"ca":[372,374]},{"id":"s025","o":"Favole","c":"XXV","str":15,"ni":"la noce e il campanile","nc":"Ořech a zvonice","it":["Trovandosi la noce essere dalla cornacchia portata sopra un alto campanile, e per una fessura, dove cadde, fu liberata dal mortale suo becco; pregò esso muro, per quella grazia, che Dio li aveva dato dell’essere tanto eminente e magno e ricco di sì belle campane e di tanto onorevole suono, che la dovessi soccorrere; perchè, poichè la non era potuta cadere sotto i verdi rami del suo vecchio padre, e essere nella grassa terra ricoperta delle sue cadenti foglie, che non la volessi lui abbandonare: imperò ch’ella trovandosi nel fiero becco della fiera cornacchia, ch’ella si votò, che, scampando da essa, voleva finire la vita sua ’n un picciolo buco. — Alle quali parole, il muro, mosso a compassione, fu costretto ricettarla nel loco, ov’era caduta. E in fra poco tempo la noce cominciò aprirsi, e mettere le radici infra le fessure delle pietre, e quelle allargare, e gittare i rami fori della sua caverna; e quegli, in breve, levati sopra lo edilizio, e ingrossatele ritorte radici, cominciò aprire i muri, e cacciare le antiche pietre de’ loro vecchi lochi. Allora il muro tardi e indarno pianse la cagione del suo danno, e in brieve aperto, rovinò gran parte delle sue membra."],"cs":["Ořech, kterého vrána zanesla na vysokou zvonici, byl tím, že spadl do jedné škvíry, vysvobozen z jejího smrtícího zobáku; i prosil tu zeď pro onu milost, kterou jí Bůh dal, že je tak vznešená a veliká a bohatá na tak krásné zvony a tak čestný zvuk, aby mu pomohla; protože nemohl spadnout pod zelené větve svého starého otce a být v tučné zemi přikryt jeho padajícím listím, aby ho neopouštěla: neboť když se ocitl v krutém zobáku divoké vrány, zaslíbil se, že unikne-li jí, chce dokonat svůj život v nějaké malé díře. – Na ta slova byla zeď pohnuta soucitem a musela ho přijmout na místě, kam spadl. A za nedlouho se ořech počal otvírat a pouštět kořeny do škvír mezi kameny a rozšiřovat je a vyhánět větve ze své sluje; a ty se brzy vyšvihly nad stavbu, a jak tloustly jeho zkroucené kořeny, počal roztrhávat zdi a vytlačovat staré kameny z jejich dávných míst. Tu zeď pozdě a marně oplakávala příčinu své škody, a brzy rozpukaná zřítila velkou část svých údů."],"ref":{"s":"C.A","l":67,"st":"v","z":false,"raw":"C. A. 67 v"},"ca":[373,375]},{"id":"s026","o":"Favole","c":"XXVI","str":16,"ni":"il salice e la zucca","nc":"Vrba a tykev","it":["Il misero salice, trovandosi non potere fruire il piacere di vedere i sua sottili rami fare over condurre alla desiderata grandezza e drizzarsi al cielo, per cagione della vite e di qualunque pianta li era vicina, sempre egli era storpiato e diramato e guasto; e raccolti in sè tutti li spiriti, e con quelli apre e spalanca le porte alla imaginazione; e stando in continua cogitazione, e ricercando con quella l’universo delle piante, con quale di quelle esso collegare si potessi, che non avessi bisogno dell’aiuto de’ sua legami; e stando alquanto in questa notritiva imaginazione, con subito assalimento li corse nel pensiero la zucca; e crollato tutti i rami per grande allegrezza, parendoli avere trovato compagnia al suo disiato proposito — imperò che quella è più atta a legare altri, che essere legata. — E fatta tal diliberazione, rizzò i sua rami inverso il cielo, attendea aspettare qualche amichevole uccello, che li fusse a tal disiderio mezzano. In fra’ quali, veduta a sè vicina la gazza, disse inver di quella: — O gentile uccello, io ti priego, per quello soccorso, che a questi giorni, da mattina, ne’ mia rami trovasti, quando l’affamato falcone, crudele e rapace, te voleva divorare; e per quelli riposi, che sopra me ispesso hai usati, quando l’ali tue a te riposo chiedeano; e per quelli piaceri, che, infra detti mia rami, scherzando colle tue compagne ne’ tua amori, già hai usato: io ti priego, che tu truovi la zucca e impetri da quella alquante delle sue semenze, e di’ a quelle che, nate ch’elle fieno, ch’io le tratterò non altrementi, che se del mio corpo generate l’avessi; e similmente usa tutte quelle parole, che di simile intenzione persuasiva sieno, benchè a te, maestra de’ linguaggi, insegnare non bisogna. E se questo farai, io sono contenta di ricevere il tuo nido sopra il nascimento de’ mia rami, insieme colla tua famiglia, sanza pagamento d’alcun fitto. Allora la gazza, fatti e fermi alquanti capitoli di novo col salice, e massime che biscie o faine sopra sè mai non accettassi; alzata la coda e bassato la testa, e gittatasi dal ramo, rendè il suo peso all’ali. E quelle battendo sopra la fuggitiva aria, ora qua, ora in là curiosamente col timon della coda dirizzandosi, pervenne a una zucca, e con bel saluto, e alquante bone parole, impetrò le dimandate semenze. E condottele al salice, fu con lieta cera ricevuta; e raspato alquanto co’ piè il terreno vicino al salice, col becco, in cerchio a esso, essi grani piantò. Li quali, in brieve tempo, crescendo, cominciò, collo accrescimento e aprimento de’ sua rami, a occupare tutti i rami del salice, e colle sue gran foglie a torle la bellezza del sole e del cielo. E, non bastando tanto male seguendo le zucche cominciò, per disconcio peso, a tirare le cime de’ teneri rami inver la terra, con istrane torture e disagio di quelli. Allora scotendosi e indarno crollandosi, per fare da sè esse zucche cadere, e indarno vaneggiando alquanti giorni in simile inganno, perchè la bona e forte collegazione tal pensieri negava, vedendo passare il vento, a quello raccomandandosi, e quello soffiò forte. Allora s’aperse il vecchio e voto gambo del salice in due parti, insino alle sue radici, e, caduto in due parti, indarno pianse se medesimo, e conobbe, che era nato per non aver mai bene."],"cs":["Ubohá vrba, vidouc, že nemůže zakusit radost z toho, jak se její tenké větve rozrůstají do vytoužené velikosti a pnou se k nebi, neboť ji kvůli révě a všem stromům, které jí byly nablízku, vždy mrzačili, olamovali a ničili, soustředila v sobě všechny své duchy a jimi otevřela a dokořán rozevřela brány obrazotvornosti; a v ustavičném přemýšlení probírala celý svět rostlin, s kterou z nich by se mohla spojit tak, aby nepotřebovala pomoc jejích pout. A když chvíli setrvala v této živné představě, náhle a prudce jí přišla na mysl tykev; i zatřásla všemi větvemi pro velikou radost, neboť se jí zdálo, že našla společnici pro svůj vytoužený záměr – vždyť ta je spíše způsobilá svazovat jiné, než být sama svazována. – A když se tak rozhodla, vztyčila své větve k nebi a vyhlížela nějakého přívětivého ptáka, který by jí byl v té touze prostředníkem. Mezi nimi spatřila blízko sebe straku a řekla k ní: – Ó vlídný ptáku, prosím tě pro onu pomoc, kterou jsi v těchto dnech jednoho jitra nalezla v mých větvích, když tě chtěl pozřít hladový sokol, krutý a dravý; a pro ony chvíle odpočinku, které jsi na mně často trávila, když tvá křídla žádala odpočinek; a pro ony radosti, které jsi mezi mými větvemi zakoušela, když jsi laškovala se svými druhy ve svých láskách: prosím tě, abys vyhledala tykev a vyprosila si od ní několik jejích semen, a řekni jim, že až vzejdou, budu s nimi zacházet nejinak, než kdybych je zplodila ze svého vlastního těla; a podobně užij všech slov, která by k takovému účelu dovedla přemlouvat, ačkoli tebe, mistryni řečí, učit netřeba. A učiníš-li to, jsem ochotna přijmout tvé hnízdo na místě, kde se mi rozbíhají větve, i s tvou rodinou, bez placení jakéhokoli nájmu. Tu straka, když s vrbou znovu sjednala a stvrdila několik článků smlouvy, a zvláště ten, že nikdy na sebe nepřijme hady ani kuny, zvedla ocas, sklonila hlavu, vrhla se z větve a svěřila svou váhu křídlům. A tlučíc jimi do prchavého vzduchu, hned sem, hned tam se zvědavě kormidlem ocasu řídíc, doletěla k tykvi a pěkným pozdravem a několika dobrými slovy si vyprosila žádaná semena. A když je přinesla vrbě, byla přijata s radostnou tváří; i vyhrabala trochu nohama zem poblíž vrby a zobákem ta zrna zasadila v kruhu kolem ní. Ta za krátký čas vyrostla a počala s růstem a rozvíjením svých úponků zabírat všechny vrbové větve a svými velkými listy jí brát krásu slunce a nebe. A jako by nestačilo tolik zla, tykve počaly svou nemotornou vahou stahovat vršky jejích útlých větví k zemi, za podivného kroucení a trápení. Tu se vrba třásla a marně se zmítala, aby ty tykve sama ze sebe setřásla, a když se několik dní marně namáhala v tomto klamu, neboť pevné a silné spojení takové myšlenky mařilo, vida jít kolem vítr, svěřila se mu, a ten silně zadul. Tu se starý a dutý kmen vrby rozštěpil ve dví až ke kořenům, a padnuvši na dvě strany, marně oplakávala sama sebe a poznala, že se narodila proto, aby nikdy neměla dobře."],"ref":null,"ca":[]},{"id":"s027","o":"Favole","c":"XXVII","str":19,"ni":"l’aquila","nc":"Orel","it":["Volendo l’aquila schernire il gufo, rimase coll’ali impaniato, e fu dall’omo presa e morta."],"cs":["Orel, chtěje se posmívat výrovi, uvázl křídly na lepu a byl člověkem chycen a zabit."],"ref":{"s":"C.A","l":67,"st":"v","z":false,"raw":"C. A. 67 v"},"ca":[373,375]},{"id":"s028","o":"Favole","c":"XXVIII","str":19,"ni":"il ragno","nc":"Pavouk","it":["Il ragno, volendo pigliare la mosca con sue false reti, fu sopra quelle dal calabrone crudelmente morto."],"cs":["Pavouka, který chtěl chytit mouchu do svých záludných sítí, na nich krutě zabil sršeň."],"ref":{"s":"C.A","l":67,"st":"v","z":false,"raw":"C. A. 67 v"},"ca":[373,375]},{"id":"s029","o":"Favole","c":"XXIX","str":19,"ni":"il granchio","nc":"Krab","it":["Il granchio, stando sotto il sasso per pigliar i pesci, che sotto a quello entravano, venne la piena con rovinoso precipitamento di sassi, e, col loro rotolare, si fracellò tal granchio"],"cs":["Krab seděl pod kamenem, aby chytal ryby, které pod něj vplouvaly; přišla povodeň se zhoubným řícením kamenů, a jejich valením byl ten krab rozdrcen."],"ref":{"s":"R","l":1314,"st":"","z":false,"raw":"R. 1314"},"ca":[],"rr":"Br. M. 42 b"},{"id":"s030","o":"Favole","c":"XXX","str":20,"ni":"l’asino e il ghiaccio","nc":"Osel a led","it":["Addormentatosi l’asino sopra il diaccio d’un profondo lago, il suo calore dissolvè esso diaccio, e l’asino sott’acqua, a mal suo danno, si destò, e subito annegò."],"cs":["Osel usnul na ledu hlubokého jezera; jeho teplo ten led rozpustilo, a osel se ke své škodě probudil pod vodou a hned se utopil."],"ref":{"s":"C.A","l":67,"st":"v","z":false,"raw":"C. A. 67 v"},"ca":[373,375]},{"id":"s031","o":"Favole","c":"XXXI","str":20,"ni":"la formica e il chicco di grano","nc":"Mravenec a zrnko obilí","it":["La formica, trovato un grano di miglio, il grano, sentendosi preso da quella, gridò: — Se mi fai tanto piacere di lasciarmi fruire il mio desiderio del nascere, io ti renderò cento me medesimi. — E così, fu fatto."],"cs":["Mravenec nalezl zrnko prosa, a zrnko, cítíc se jím uchvácené, zvolalo: – Prokážeš-li mi tu laskavost a necháš mě užít mé touhy vzklíčit, vrátím ti sto sebe samého. – A tak se stalo."],"ref":{"s":"C.A","l":67,"st":"v","z":false,"raw":"C. A. 67 v"},"ca":[373,375]},{"id":"s032","o":"Favole","c":"XXXII","str":20,"ni":"l’ostrica, il ratto e la gatta","nc":"Ústřice, krysa a kočka","it":["Sendo l’ostrica, insieme colli altri pesci in casa del pescatore scaricata vicino al mare, pregò il ratto, che al mare la conduca; e ’l ratto, fatto disegno di mangiarla, la fa aprire; e mordendola, questa li serra la testa e sì lo ferma: viene la gatta e l’uccide."],"cs":["Ústřice, vyložená spolu s jinými rybami v domě rybáře nedaleko moře, prosila krysu, aby ji dovedla k moři; a krysa, která si umínila, že ji sní, přiměje ji, aby se otevřela; a když ji kousne, ústřice jí sevře hlavu a tak ji zadrží; přijde kočka a zabije ji."],"ref":{"s":"H","l":51,"st":"v","z":false,"raw":"H. 51 v"},"ca":[]},{"id":"s033","o":"Favole","c":"XXXIII","str":20,"ni":"il falcone e l’anitra","nc":"Sokol a kachna","it":["Il falcone, non potendo sopportare con pazienzia il nascondere che fa l’anitra, fuggendosele dinanzi e entrando sotto acqua: volle, come quella, sott’acqua seguitale, e, bagnatosi le penne, rimase in essa acqua: e l’anitra levatasi in aria, schernía il falcone, che annegava."],"cs":["Sokol, nemoha trpělivě snášet, jak se kachna skrývá, když před ním prchá a noří se pod vodu, chtěl ji jako ona pronásledovat pod vodou; a když si smočil peří, zůstal v té vodě; a kachna, vznesši se do vzduchu, se posmívala sokolovi, který se topil."],"ref":{"s":"C.A","l":67,"st":"v","z":true,"raw":"C. A. 67 v"},"ca":[373,375]},{"id":"s034","o":"Favole","c":"XXXIV","str":21,"ni":"l’ostrica e il granchio","nc":"Ústřice a krab","it":["Ostrica. Questa, quando la luna è piena, s’apre tutta, e, quando il granchio la vede, dentro le getta qualche sasso o festuca: e questa non si può risserrare, ond’è cibo d’esso granchio. Così fa chi apre la bocca a dire il suo segreto, che si fa preda dello indiscreto auditore."],"cs":["Ústřice. Ta se za úplňku celá otevírá, a když ji krab spatří, hodí do ní nějaký kamínek nebo stéblo; a ona se pak nemůže zavřít, a tak se stává krabovou potravou. Tak činí ten, kdo otevře ústa, aby vyslovil své tajemství: stává se kořistí nediskrétního posluchače."],"ref":{"s":"C.A","l":67,"st":"v","z":false,"raw":"C. A. 67 v"},"ca":[373,375]},{"id":"s035","o":"Favole","c":"XXXV","str":21,"ni":"i tordi e la civetta","nc":"Drozdi a sýček","it":["I tordi si rallegrarono forte, vedendo che l’omo prese la civetta e le tolse la libertà quella legando con forti legami ai sua piedi! La qual civetta fu poi, mediante il vischio, causa non di far perdere la libertà ai tordi, ma la loro propria vita.","Detta per quelle terre, che si rallegran di vedere perdere la libertà ai loro maggiori, mediante i quali poi perdano il soccorso e rimangono legati in potenza del loro nemico, lasciando la libertà e spesse volte la vita."],"cs":["Drozdi se velice radovali, když viděli, že člověk chytil sýčka a vzal mu svobodu tím, že mu pevnými pouty spoutal nohy! Ten sýček se však pak skrze lep stal příčinou toho, že drozdi ztratili nejen svobodu, ale i vlastní život.","Řečeno o těch zemích, které se radují, když vidí, jak jejich mocnější ztrácejí svobodu, a skrze to pak samy přicházejí o pomoc a zůstávají spoutány v moci svého nepřítele, přičemž ztrácejí svobodu a mnohdy i život."],"ref":{"s":"C.A","l":67,"st":"v","z":false,"raw":"C. A. 67 v"},"ca":[373,375]},{"id":"s036","o":"Favole","c":"XXXVI","str":22,"ni":"la scimmia e l’uccelletto","nc":"Opice a ptáček","it":["Trovando la scimmia uno nido di piccioli uccelli, tutta allegra appressatasi a quelli, i quali essendo già da volare, ne potè solo pigliare il minore. Essendo piena d’allegrezza, con esso in mano se n’andò al suo ricetto; e, cominciato a considerare questo uccelletto, lo cominciò a baciare; e, per lo isviscerato amore, tanto lo baciò e rivolse e strinse, ch’ella gli tolse la vita. È detta per quelli, che, per non gastigare i figlioli, capitano male."],"cs":["Opice nalezla hnízdo malých ptáčků a celá radostná se k nim přiblížila; ale protože už uměli létat, mohla chytit jen toho nejmenšího. Plna radosti odešla s ním v ruce do svého úkrytu; a když si toho ptáčka začala prohlížet, počala ho líbat; a z nezřízené lásky ho tolik líbala, převracela a mačkala, až ho připravila o život. Řečeno o těch, kdo zle pochodí, protože netrestají své děti."],"ref":{"s":"C.A","l":67,"st":"v","z":false,"raw":"C. A. 67 v"},"ca":[373,375]},{"id":"s037","o":"Favole","c":"XXXVII","str":22,"ni":"il cane e la pulce","nc":"Pes a blecha","it":["Dormendo il cane sopra la pelle d’un castrone, una delle sue pulci, sentendo l’odore della unta lana, giudicò quello dovessi essere loco di miglior vita e più sicura da’ denti e unghia del cane, che pascersi del cane; e sanza altri pensieri, abbandonò il cane. E, entrata infra la folta lana, cominciò con somma fatica a volere trapassare alle radici de’ peli: la quale impresa, dopo molto sudore, trovò esser vana, perchè tali peli erano tanto spessi, che quasi si toccavano, e non v’era spazio, dove la pulce potesse saggiare tal pelle. Onde, dopo lungo travaglio e fatica, cominciò a volere ritornare al suo cane; il quale essendo già partito, fu costretta, dopo lungo pentimento, amari pianti, a morirsi di fame."],"cs":["Když pes spal na kůži skopce, jedna z jeho blech ucítila vůni mastné vlny a usoudila, že tam musí být místo lepšího života a bezpečnější před psími zuby a drápy, než je živit se na psovi; a bez dalšího přemýšlení psa opustila. A když vnikla do husté vlny, počala se s nesmírnou námahou prodírat ke kořínkům chlupů; po mnohém potu však shledala, že ten podnik je marný, neboť ty chlupy byly tak husté, že se téměř dotýkaly, a nebylo tam místo, kde by blecha mohla tu kůži ochutnat. A tak se po dlouhém trápení a námaze chtěla vrátit ke svému psovi; ten však už odešel, a tak musela po dlouhé lítosti a hořkém pláči zemřít hladem."],"ref":{"s":"C.A","l":119,"st":"r","z":false,"raw":"C. A. 119 r"},"ca":[652,654]},{"id":"s038","o":"Favole","c":"XXXVIII","str":23,"ni":"il topo, la donnola e il gatto","nc":"Myš, lasice a kočka","it":["Stando il topo assediato in una piccola sua abitazione dalla donnola, la quale con continua vigilanzia attendea alla sua disfazione, e, per uno piccolo spiraculo, riguardava il suo gran periculo. — Infrattanto venne la gatta, e subito prese essa donnola, e immediate l’ebbe divorata. Allora il ratto, fatto sagrificio a Giove d’alquante sue nocciole, ringraziò sommamente la sua deità; e uscito fori della sua buca a possedere la già persa libertà, de la quale subito, insieme colla vita, fu, dalle feroci unghia e denti della gatta, privato."],"cs":["Myš byla obležena ve svém malém příbytku lasicí, která s ustavičnou bdělostí čekala na její zkázu, a malým průduchem pozorovala své veliké nebezpečí. – Mezitím přišla kočka, hned tu lasici chytila a okamžitě ji pozřela. Tu myš obětovala Jovovi několik svých lískových oříšků, nejvýš děkovala jeho božství, a vyšla ze své díry, aby se zmocnila již ztracené svobody; o tu však hned i se životem přišla v divokých drápech a zubech kočky."],"ref":{"s":"R","l":1314,"st":"","z":true,"raw":"R. 1314"},"ca":[],"rr":"Br. M. 42 b"},{"id":"s039","o":"Favole","c":"XXXIX","str":23,"ni":"il ragno e il grappolo d’uva","nc":"Pavouk a hrozen","it":["Il ragno, stando infra l’uve, pigliava le mosche, che in su tali uve si pascevano: venne la vendemmia e fu pestato, il ragno insieme coll’uve."],"cs":["Pavouk, usazený mezi hrozny, chytal mouchy, které se na těch hroznech živily; přišlo vinobraní a pavouk byl rozšlapán spolu s hrozny."],"ref":{"s":"R","l":1314,"st":"","z":false,"raw":"R. 1314"},"ca":[],"rr":"Br. M. 42 b"},{"id":"s040","o":"Favole","c":"XL","str":24,"ni":"sul medesimo soggetto","nc":"Na totéž téma","it":["Trovato il ragno uno grappolo d’uva, il quale per la sua dolcezza era molto visitato da ape e diverse qualità di mosche, li parve avere trovato loco molto comodo al suo inganno. E calatosi giù per lo suo sottile filo, e entrato nella nova abitazione, lì ogni giorno, facendosi alli spiraculi fatti dalli intervalli de’ grani dell’uva, assaltava, come ladrone, i miseri animali, che da lui non si guardavano. E passati alquanti giorni, il vendemmiatore, còlta essa uva e messa con l’altre, insieme con quelle fu pigiato. E così l’uva fu laccio e inganno dello ingannatore ragno, come delle ingannate mosche."],"cs":["Pavouk nalezl hrozen, který pro svou sladkost hojně navštěvovaly včely a mouchy rozličného druhu, a zdálo se mu, že našel místo velmi vhodné pro svou lest. I spustil se dolů po svém tenkém vlákně, vstoupil do nového příbytku a tam každý den, postávaje u průduchů tvořených mezerami mezi bobulemi, přepadal jako lupič ubohé živočichy, kteří se ho nestřežili. A po několika dnech vinař ten hrozen utrhl, dal ho k ostatním a byl s nimi rozmačkán. A tak byl hrozen léčkou a pastí pro podvodníka pavouka stejně jako pro podvedené mouchy."],"ref":{"s":"C.A","l":67,"st":"v","z":false,"raw":"C. A. 67 v"},"ca":[373,375]},{"id":"s041","o":"Favole","c":"XLI","str":24,"ni":"traccia","nc":"Náčrt","it":["Favola della lingua morsa dai denti."],"cs":["Bajka o jazyku pokousaném zuby."],"ref":{"s":"C.A","l":67,"st":"r","z":true,"raw":"C. A. 67 r"},"ca":[372,374]},{"id":"s042","o":"Favole","c":"XLII","str":24,"ni":"il villano e la vite","nc":"Sedlák a réva","it":["Vedendo il villano la utilità, che resultava dalla vite, le dette molti sostentagculi da sostenerla in alto; e, preso il frutto, levò le pertiche, e quella lasciò cadere, facendo foco de’ sua sostentaculi."],"cs":["Sedlák, vida užitek, který réva přinášela, dal jí mnoho podpěr, aby ji držely vzhůru; a když sklidil plody, odstranil tyče a nechal ji spadnout a z jejích podpěr udělal oheň."],"ref":null,"ca":[]},{"id":"s043","o":"Favole","c":"XLIII","str":25,"ni":"leggenda del vino e di maometto","nc":"Pověst o víně a Mohamedovi","it":["Trovandosi il vino, il divino licore dell’uva, in una aurea e ricca tazza, sopra la tavola di Maumetto, e montato in gloria di tanto onore, subito fu assaltato da una contraria cogitazione, dicendo a sè medesimo: — Che fo io? di che mi rallegro io? Non m’avvedo essere vicino alla mia morte e lasciare l’aurea abitazione della tazza, e entrare nelle brutte e fetide caverne del corpo umano, e lì trasmutarmi di odorifero e suave licore in brutta e trista orina? E non bastando tanto male, ch’io ancora debba sì lungamente giacere ne’ brutti ricettacoli coll’altra fetida e corrotta materia uscita dalle umane interiora? — Gridò inverso il cielo, chiedendo vendetta di tanto danno, e che si ponesse ormai fine a tanto dispregio; che, poichè quello paese producea le più belle e migliori uve di tutto l’altro mondo, che il meno elle non fussino in vino condotte. Allora Giove fece che il vino beuto da Maumetto elevò l’anima sua inverso il celebro, che lo fece matto, e partorì tanti errori, che, tornato in sè, fece legge che nessuno asiatico beesse vino. E fu lasciato poi libere le viti co’ sua frutti.","Già il vino, entrato nello stomaco, comincia a bollire e sgonfiare; già l’anima di quello comincia abbandonare il corpo; già si volta inverso il cielo, trova il celebro, cagione della divisione dal suo corpo; già lo comincia a contaminare e farlo furiare a modo di matto; già fa irriparabili errori, ammazzando i sua amici."],"cs":["Víno, božský mok hroznu, nacházejíc se ve zlaté a bohaté číši na stole Mohamedově, a vystoupivši v slávě pro tak velikou poctu, bylo náhle přepadeno opačnou myšlenkou a řeklo si: – Co to dělám? Z čeho se raduji? Nevidím, že jsem blízko své smrti a že opustím zlatý příbytek číše a vejdu do ošklivých a páchnoucích slují lidského těla a tam se z vonného a lahodného moku proměním v ošklivou a bídnou moč? A jako by nestačilo tolik zla, budu ještě tak dlouho ležet v ošklivých nádržích s jinou páchnoucí a zkaženou hmotou, vyšlou z lidských útrob? – I volalo k nebi, žádajíc pomstu za takovou škodu a aby už byl konec takovému pohrdání; a že když ta země rodí nejkrásnější a nejlepší hrozny z celého ostatního světa, aby z nich aspoň nebylo dělano víno. Tu Jupiter způsobil, že víno, které Mohamed vypil, pozdvihlo svou duši k jeho mozku, takže ho pobláznilo, a on se dopustil tolika poklesků, že když přišel k sobě, vydal zákon, aby žádný Asiat nepil víno. A révy s jejich plody byly pak ponechány na pokoji.","Již víno, vešedši do žaludku, počíná kypět a nadýmat se; již jeho duše počíná opouštět tělo; již se obrací k nebi, nachází mozek, příčinu oddělení od jejího těla; již ho počíná nakažovat a přivádět k zuřivosti jako blázna; již páchá nenapravitelné poklesky a zabíjí své přátele."],"ref":{"s":"C.A","l":67,"st":"r","z":false,"raw":"C. A. 67 r"},"ca":[372,374]},{"id":"s044","o":"Favole","c":"XLIV","str":26,"ni":"traccia","nc":"Náčrt","it":["Il vino, consumato da esso ubriaco, esso vino col bevitore si vendica."],"cs":["Víno, pozřené opilcem, se na pijákovi mstí."],"ref":{"s":"C.A","l":116,"st":"v","z":true,"raw":"C. A. 116 v"},"ca":[637,640]},{"id":"s045","o":"Favole","c":"XLV","str":26,"ni":"le fiamme e la caldaia","nc":"Plameny a kotel","it":["Un poco di foco, che, in un piccolo carbone, in fra la tiepida cenere rimaso era, del poco omore, che in esso restava, carestiosamente e poveramente sè medesimo notría. Quando, la ministra della cucina, per usare con quello l’ordinario suo cibario offizio, quivi apparve, e, poste le legne nel focolare — e, col solfanello già resuscitato d’esso, già quasi per morto, una piccola fiammella e, infra le ordinate legne quella appresa e, posta di sopra la caldaia — sanz’altro sospetto, di lì sicuramente si parte.","Allora, rallegratosi il foco delle sopra sè poste secche legne, comincia a elevarsi: cacciando l’aria delli intervalli d’esse legne, in fra quelli con ischerzevole e giocoso transito, se stesso tesseva.","Cominciato a spirare fori dell’intervalli delle legne, di quelli a sè stesso dillettevoli finestre fatto avea; e, cacciate fori di rilucenti e rutilanti fiammelle, subito discaccia le oscure tenebre della serrata cucina; e con gaudio, le fiamme già cresciute, scherzavano coll’aria d’esse circundatrice e con dolce mormorio cantando, creava soave sonito....","Rallegrandosi il foco delle secche legne, che nel focolare trovato avea, e in quelle appresosi, con quelle comincia a scherzare tessendole in sue piccole fiammelle, e ora qua ora là, per li intervalli, che in fra le legne si trova, traeva.","E, scorrendo in fra quelle con festevole, giocoso transito, cominciò a spirare, e fra li intervalli delle superiori legne apparía, facendo di quelli a sè dilettevoli finestre ora qua, ora là.","Vedutosi già fortemente essere sopra delle legne cresciuto e fatto assai grande, cominciò a levare il mansueto e tranquillo animo in gonfiata e insopportabile superbia, facendo quasi a sè credere tirare tutto il superiore elemento sopra le poche legne.","E cominciato a sbuffare, e, empiendo di scoppi e di scintillanti sfavillamenti tutto il circostante focolare, già le fiamme, fatte grosse, unitamente si drizzavano inverso l’aria.... quando le fiamme più altere, percosser nel fondo della superiore caldaia."],"cs":["Trocha ohně, která zůstala v malém uhlíku ve vlažném popelu, se skrovně a chudě živila tou trochou šťávy, jež v něm zbývala. Tu se objevila kuchařka, aby s ním vykonala svůj obvyklý úřad přípravy jídla, a položila do ohniště polena – a sirkou z něho, už skoro mrtvého, vzkřísila malý plamínek, zapálila jím narovnaná polena a nahoru postavila kotel – a bez dalšího podezření bezstarostně odtud odchází.","Tu se oheň zaradoval ze suchých polen, která na něj byla položena, a počíná se zvedat: vyhání vzduch z mezer mezi poleny a s hravým a rozpustilým průchodem se mezi nimi proplétá.","Když počal dýchat ven z mezer mezi poleny, udělal si z nich rozkošná okna, a vypustiv ven zářící a rudé plamínky, rázem zahání temnou tmu zavřené kuchyně; a plameny, už vzrostlé, s radostí laškovaly s okolním vzduchem a sladkým šuměním zpívajíce vydávaly lahodný zvuk....","Oheň, raduje se ze suchých polen, která v ohništi našel, chytil se jich a počíná si s nimi pohrávat, protkávaje je svými plamínky, a hned sem, hned tam se protahoval mezerami, které mezi poleny nachází.","A probíhaje mezi nimi slavnostním, hravým průchodem, začal dýchat a objevoval se v mezerách mezi horními poleny a dělal si z nich rozkošná okna hned tu, hned tam.","Když viděl, že už mocně vyrostl nad poleny a stal se dost velikým, počal povznášet svou mírnou a pokojnou mysl v nafouklou a nesnesitelnou pýchu, takže si skoro namlouval, že stahuje celý horní živel na ta nemnohá polena.","A počal funět, a naplniv celé okolní ohniště praskotem a jiskřivým sršením, už se plameny, zesílené, společně zdvíhaly k vzduchu.... když vtom ty nejvyšší plameny narazily na dno kotle nad nimi."],"ref":{"s":"C.A","l":116,"st":"v","z":false,"raw":"C. A. 116 v"},"ca":[637,640]},{"id":"s046","o":"Favole","c":"XLVI","str":28,"ni":"lo specchio e la regina","nc":"Zrcadlo a královna","it":["Lo specchio si gloria forte tenendo dentro a sè specchiata la regina, e partita quella lo specchio rimase in le...."],"cs":["Zrcadlo se velice pyšní, když v sobě drží odraz královny; a když ona odešla, zrcadlo zůstalo v...."],"ref":{"s":"R","l":1324,"st":"","z":false,"raw":"R. 1324"},"ca":[],"rr":"S. K. M. III. 48 a"},{"id":"s047","o":"Allegorie","c":"I","str":31,"ni":"amore di virtù","nc":"Láska ke ctnosti","it":["Calendrino è uno uccello, il quale si dice, che essendo esso portato dinanzi a uno infermo, che se ’l detto infermo deve morire, questo uccello li volta lato, sta per lo contrario e mai lo riguarda; e, se esso infermo deve iscampare, questo uccello mai l’abbandona di vista, anzi è causa di levarli ogni malattia.","Similmente, l’amore di virtù non guarda mai cosa vile, nè trista, anzi dimora sempre in cose oneste e virtuose, e ripatria sempre in cor gentile, a similitudine degli uccelli nelle verdi selve sopra i fioriti rami; esso dimostra più esso amore nelle avversità che nelle prosperità, facendo come lume, che più risplende, dove trova più tenebroso sito."],"cs":["Kaladrius je pták, o němž se říká, že když ho přinesou před nemocného, a má-li ten nemocný zemřít, odvrátí se ten pták stranou, zůstane obrácen opačně a nikdy na něj nepohlédne; má-li se však nemocný uzdravit, ten pták z něho nikdy nespustí oči, a dokonce je příčinou, že ho zbaví každé nemoci.","Podobně láska ke ctnosti nikdy nehledí na věc nízkou ani zlou, nýbrž prodlévá vždy ve věcech poctivých a ctnostných a vždy se vrací domů do ušlechtilého srdce, jako ptáci v zelených lesích na kvetoucích ratolestech; a tu lásku projevuje víc v protivenství než ve štěstí, počínajíc si jako světlo, které tím víc září, čím temnější místo nachází."],"ref":{"s":"H","l":5,"st":"r","z":false,"raw":"H. 5 r"},"ca":[]},{"id":"s048","o":"Allegorie","c":"II","str":32,"ni":"invidia","nc":"Závist","it":["Del nibbio si legge che, quando esso vede i suoi figlioli nel nido esser di troppa grassezza, che egli gli becca loro le coste, e tiengli sanza mangiare."],"cs":["O luňákovi se čte, že když vidí, že jsou jeho mláďata v hnízdě příliš tlustá, klove je do žeber a nechává je bez jídla."],"ref":{"s":"H","l":6,"st":"r","z":true,"raw":"H. 6 r"},"ca":[]},{"id":"s049","o":"Allegorie","c":"III","str":32,"ni":"allegrezza","nc":"Veselost","it":["L’allegrezza è appropriata al gallo, che d’ogni piccola cosa si rallegra, e canta, con vari e scherzanti movimenti."],"cs":["Veselost přísluší kohoutovi, který se raduje z každé maličkosti a zpívá s rozmanitými a rozpustilými pohyby."],"ref":{"s":"H","l":6,"st":"r","z":true,"raw":"H. 6 r"},"ca":[]},{"id":"s050","o":"Allegorie","c":"IV","str":32,"ni":"tristezza","nc":"Smutek","it":["La tristezza s’assomiglia al corvo, il quale, quando vede i sua nati figlioli essere bianchi, per lo grande dolore si parte, con tristo rammarichio gli abbandona, e non gli pasce, insino che non gli vede alquante poche penne nere."],"cs":["Smutek se podobá havranovi, který, když vidí, že jeho vylíhnutá mláďata jsou bílá, z velikého žalu odletí, s truchlivým nářkem je opustí a nekrmí je, dokud na nich nespatří aspoň několik černých pírek."],"ref":{"s":"H","l":6,"st":"r","z":true,"raw":"H. 6 r"},"ca":[]},{"id":"s051","o":"Allegorie","c":"V","str":32,"ni":"pace","nc":"Mír","it":["Del castoro si legge che, quando è perseguitato, conoscendo essere per la virtù de’ sua medicinali testiculi, esso, non potendo più fuggire, si ferma, e, per avere pace coi cacciatori, coi sua taglienti denti si spicca i testiculi, e li lascia a’ sua nimici. ̂"],"cs":["O bobrovi se čte, že když je pronásledován, ví, že je to pro léčivou moc jeho varlat; a když už nemůže dál utíkat, zastaví se, a aby měl pokoj s lovci, svými ostrými zuby si varlata ukousne a nechá je svým nepřátelům."],"ref":{"s":"H","l":6,"st":"r","z":true,"raw":"H. 6 r"},"ca":[]},{"id":"s052","o":"Allegorie","c":"VI","str":33,"ni":"ira","nc":"Hněv","it":["Dell’orso si dice che, quando va alle case delle ave per tôrre loro il mele, esse ave lo cominciano a pungere, onde lui lascia il mele e corre alla vendetta; e, volendosi con tutte quelle che lo mordano vendicare, con nessuna si vendica, in modo che la sua vita si converte in rabbia, e gittatosi in terra, con le mani e co’ piedi innaspando, indarno da quelle si difende."],"cs":["O medvědovi se říká, že když jde k úlům včel, aby jim vzal med, začnou ho včely bodat; i nechá med a běží se mstít; a chtěje se pomstít na všech, které ho koušou, nepomstí se na žádné, takže se jeho život obrátí v zuřivost, a vrhnuv se na zem, marně se jim brání rukama i nohama, jimiž kolem sebe tluče."],"ref":{"s":"H","l":6,"st":"r","z":false,"raw":"H. 6 r"},"ca":[]},{"id":"s053","o":"Allegorie","c":"VII","str":33,"ni":"misericordia over gratitudine","nc":"Milosrdenství neboli vděčnost","it":["La virtù della gratitudine si dice essere più neLi uccelli detti upica,i quali, conoscendo 11 benefizio della ricevuta vita e nutrimento dal padre e dalla lor madre, quando li vedano vecchi, fanno loro uno nido, e li covano, e li notriscano, e cavan loro col becco le vecchie e triste penne, e con certe erbe li rendano la vista, in modo che ritornano in prospertà."],"cs":["Ctnost vděčnosti prý nejvíce mají ptáci zvaní dudci, kteří, znajíce dobrodiní života i potravy přijaté od otce a od matky, když je vidí staré, udělají jim hnízdo, zahřívají je a živí je, vytrhávají jim zobákem staré a ošuntělé peří a jistými bylinami jim vracejí zrak, takže se navrátí do zdraví."],"ref":{"s":"H","l":6,"st":"v","z":true,"raw":"H. 6 v"},"ca":[]},{"id":"s054","o":"Allegorie","c":"VIII","str":33,"ni":"avarizia","nc":"Lakota","it":["Il rospo si pasce di terra, e sempre sta macro, perchè non si sazia: tanto è ’l timore, che essa terra non li manchi."],"cs":["Ropucha se živí hlínou a je stále hubená, protože se nenasytí: tak veliký má strach, že by jí ta hlína mohla dojít."],"ref":{"s":"H","l":6,"st":"v","z":true,"raw":"H. 6 v"},"ca":[]},{"id":"s055","o":"Allegorie","c":"IX","str":34,"ni":"ingratitudine","nc":"Nevděk","it":["I colombi sono assomigliati alla ingratitudine; imperocchè, quando sono in età che non abbino più bisogno d’essere cibati, cominciano a combattere col padre, e non finisce essa pugna, infino a tanto che caccia il padre, e tolli la mogliera, facendosela sua."],"cs":["Holubi se přirovnávají k nevděku; neboť když jsou ve věku, kdy už nepotřebují být krmeni, začnou bojovat s otcem, a ten boj neskončí, dokud otce nevyžene a nevezme mu ženu a neučiní ji svou."],"ref":{"s":"H","l":6,"st":"v","z":false,"raw":"H. 6 v"},"ca":[]},{"id":"s056","o":"Allegorie","c":"X","str":34,"ni":"crudeltà","nc":"Krutost","it":["Il basalisco è di tanta crudeltà che, quando con la sua venenosa vista non po’ occidere li animali, si volta all’erbe e le piante, e, fermato in quelle la sua vista, le fa seccare."],"cs":["Bazilišek je tak krutý, že když svým jedovatým pohledem nemůže zabíjet zvířata, obrátí se k bylinám a rostlinám, a upřev na ně svůj pohled, nechá je uschnout."],"ref":{"s":"H","l":8,"st":"r","z":true,"raw":"H. 8 r"},"ca":[]},{"id":"s057","o":"Allegorie","c":"XI","str":34,"ni":"liberalità","nc":"Štědrost","it":["Dell’aquila si dice che non ha mai sì gran fame, che non lasci parte della sua preda a quelli uccelli, che le son dintorno; i quali, non potendosi per sè pascere, è necessario che sieno corteggiatori d’essa aquila, perchè in tal modo si cibano."],"cs":["O orlovi se říká, že nikdy nemá tak veliký hlad, aby nezanechal část své kořisti ptákům, kteří jsou kolem něho; ti, protože se nemohou uživit sami, musejí orlovi dělat družinu, neboť tak se nasytí."],"ref":{"s":"H","l":8,"st":"r","z":true,"raw":"H. 8 r"},"ca":[]},{"id":"s058","o":"Allegorie","c":"XII","str":34,"ni":"correzione","nc":"Náprava","it":["Quando il lupo va assentito a qualche stallo di bestiame, e che, per caso, esso ponga il piede in fallo, in modo facci strepito, egli si morde il piè, per correggere tale errore."],"cs":["Když se vlk tiše plíží k nějakému chlévu s dobytkem a náhodou šlápne vedle, takže způsobí hluk, kousne se do nohy, aby ten poklesek napravil."],"ref":{"s":"H","l":8,"st":"r","z":true,"raw":"H. 8 r"},"ca":[]},{"id":"s059","o":"Allegorie","c":"XIII","str":35,"ni":"lusinghe over soie","nc":"Lichocení neboli úlisnost","it":["La serena sì dolcemente canta, che addormenta i marinari, e essa monta sopra i navili, e occide li addormentati marinari."],"cs":["Siréna zpívá tak sladce, že uspí námořníky, a ona vystoupí na lodi a zabíjí spící námořníky."],"ref":{"s":"H","l":8,"st":"r","z":true,"raw":"H. 8 r"},"ca":[]},{"id":"s060","o":"Allegorie","c":"XIV","str":35,"ni":"prudenza","nc":"Opatrnost","it":["La formica, per naturale consiglio, provvede la state per lo verno, uccidendo le raccolte semenza, perchè non rinascino; e di quelle al tempo si pascono."],"cs":["Mravenec z přirozené moudrosti se v létě zásobí na zimu a ničí nasbíraná semena, aby znovu nevyklíčila; a těmi se pak v čas potřeby živí."],"ref":{"s":"H","l":8,"st":"r","z":true,"raw":"H. 8 r"},"ca":[]},{"id":"s061","o":"Allegorie","c":"XV","str":35,"ni":"pazzia","nc":"Pošetilost","it":["Il bo’ salvatico, avendo in odio il colore rosso, i cacciatori vestan di rosso il pedal d’una pianta, e esso bo’ corre a quella, e con gran furia v’inclhioda le corna, onde i cacciatori l’occidano."],"cs":["Divoký tur nenávidí červenou barvu; lovci oblékají do červeného patu stromu, a ten tur k němu přiběhne a s velikou zuřivostí do něj zarazí rohy, načež jej lovci zabijí."],"ref":{"s":"H","l":8,"st":"r","z":false,"raw":"H. 8 r"},"ca":[]},{"id":"s062","o":"Allegorie","c":"XVI","str":35,"ni":"giustizia","nc":"Spravedlnost","it":["E’ si può assimigliare la virtù de la justizia allo re delle ave; il quale ordina e dispone ogni cosa con ragione: imperocchè alcune ave sono ordinate andare per fiori, altre ordinate a lavorare, altre a combattere colle vespe, altre a levare le sporcizie, altre a compagnaie e corteggiare lo re; e, quando è vecchio e sanza ali, esse lo portano, e, se ivi una manca di suo offizio, sanza alcuna remissione è punita."],"cs":["Ctnost spravedlnosti lze přirovnat ke králi včel, který vše řídí a uspořádává podle rozumu: neboť některé včely jsou určeny chodit na květy, jiné jsou určeny k práci, jiné k boji s vosami, jiné k odklízení nečistot, jiné k doprovázení krále a k tvoření jeho družiny; a když je starý a bez křídel, nosí ho, a jestliže některá zanedbá svůj úřad, je bez jakéhokoli slitování potrestána."],"ref":{"s":"H","l":9,"st":"r","z":true,"raw":"H. 9 i"},"ca":[]},{"id":"s063","o":"Allegorie","c":"XVII","str":36,"ni":"verità","nc":"Pravda","it":["Benchè le pernici rubino l’ova l’una all’altra, non di meno i figlioli, nati d’esse ova, sempre ritornano alla lor vera madre."],"cs":["Ačkoli si koroptve navzájem kradou vejce, přece se mláďata, vylíhlá z těch vajec, vždy vracejí ke své pravé matce."],"ref":null,"ca":[]},{"id":"s064","o":"Allegorie","c":"XVIII","str":36,"ni":"fedeltà over lialtà","nc":"Věrnost neboli oddanost","it":["Le gru son tanto fedeli e leali al loro re, che la notte, quando lui dorme, alcune vanno dintorno al prato per guardare da lunga, altre ne stanno da presso; e tengano uno sasso ciascuna in piè, accio che, se ’l sonno le vincessi, essa pietra cadrebbe, e farebbe tal romore, che si ridesterebbono; e altre vi sono, che ’nsieme intorno al re dormano, e ciò fanno, ogni notte scambiandosi, a ciò che ’l loro re non venga mancare."],"cs":["Jeřábi jsou tak věrní a oddaní svému králi, že v noci, když spí, někteří obcházejí kolem louky, aby hlídali zdaleka, jiní stojí nablízku; a každý drží v noze kámen, aby, kdyby je přemohl spánek, ten kámen spadl a způsobil takový hluk, že by se znovu probudili; a jiní tam jsou, kteří spí společně kolem krále; a tak činí, každou noc se střídajíce, aby jejich král nepřišel o život."],"ref":{"s":"H","l":9,"st":"r","z":true,"raw":"H. 9 i"},"ca":[]},{"id":"s065","o":"Allegorie","c":"XIX","str":36,"ni":"falsità.21","nc":"Faleš","it":["La volpe, quando vede alcuna torma di gazze o taccole o simili uccelli, subito si gitta in terra in modo, con la bocca aperta, che par morta, e essi uccelli le vogliali beccaro la lingua, e essa gli piglia la testa."],"cs":["Liška, když spatří hejno strak nebo kavek nebo podobných ptáků, ihned se vrhne na zem s otevřenou tlamou tak, že se zdá mrtvá; a když jí ti ptáci chtějí vyklovat jazyk, chytí je za hlavu."],"ref":{"s":"H","l":9,"st":"r","z":false,"raw":"H. 9 i"},"ca":[]},{"id":"s066","o":"Allegorie","c":"XX","str":37,"ni":"bugia","nc":"Lež","it":["La talpa ha li occhi molto piccioli, e sempre sta sotto terra, e tanto vive, quanto essa sta occulta, e, come viene alla luce, subito more, perchè si fa nota così la bugia."],"cs":["Krtek má velmi malé oči a stále žije pod zemí, a žije tak dlouho, dokud zůstává skryt; a jakmile vyjde na světlo, hned umírá, protože je odhalen; tak i lež."],"ref":{"s":"H","l":9,"st":"v","z":true,"raw":"H. 9 v"},"ca":[]},{"id":"s067","o":"Allegorie","c":"XXI","str":37,"ni":"timore over viltà","nc":"Bázeň neboli zbabělost","it":["La lepre sempre teme, e le foglie, che caggiano dalle piante per autunno, sempre la tengano in timore e, ’l più delle volte, in fuga."],"cs":["Zajíc se stále bojí, a listí, které na podzim padá ze stromů, ho stále drží ve strachu a většinou ho zahání na útěk."],"ref":{"s":"H","l":9,"st":"v","z":false,"raw":"H. 9 v"},"ca":[]},{"id":"s068","o":"Allegorie","c":"XXII","str":37,"ni":"magnanimità","nc":"Velkomyslnost","it":["Il falcone non preda mai, se non l’uccelli grossi, e prima si lascierebbe morire, che si cibassi de’ piccioli, e che mangiasse carne fetida."],"cs":["Sokol nikdy neloví než velké ptáky, a raději by se nechal zemřít, než aby se živil malými a jedl smrdutou mršinu."],"ref":{"s":"H","l":10,"st":"r","z":true,"raw":"H. 10 r"},"ca":[]},{"id":"s069","o":"Allegorie","c":"XXIII","str":37,"ni":"vanagloria","nc":"Ješitnost","it":["In questo vizio, si legge del pagone esserli più che altro animale sottoposto, perchè sempre contempla in nella bellezza della sua coda, quella allargando in forma di rota, e col suo grido trae a sè la vista de’ circustanti animali. E questo è l’ultimo vizio, elio si possa vincere."],"cs":["Této neřesti, jak se čte, podléhá páv víc než kterékoli jiné zvíře, neboť stále rozjímá o kráse svého ocasu, roztahuje jej do podoby kola a svým křikem přitahuje k sobě zraky okolních zvířat. A to je poslední neřest, kterou lze přemoci."],"ref":{"s":"H","l":10,"st":"r","z":true,"raw":"H. 10 r"},"ca":[]},{"id":"s070","o":"Allegorie","c":"XXIV","str":38,"ni":"constanza","nc":"Stálost","it":["Alla constanza s’assimiglia la fenice; la quale, intendendo per natura la sua rennovazione, è costante a sostener le cocenti fiamme, le quali la consumano, e poi di novo rinasce."],"cs":["Stálosti se podobá fénix, který, chápaje ze své přirozenosti své obnovení, stále snáší žhoucí plameny, jež jej stravují, a pak se znovu rodí."],"ref":{"s":"H","l":10,"st":"r","z":false,"raw":"H. 10 r"},"ca":[]},{"id":"s071","o":"Allegorie","c":"XXV","str":38,"ni":"inconstanza","nc":"Nestálost","it":["Il rondone si mette per la inconstanza; il quale sempre sta in moto, per non sopportare alcuno minimo disagio."],"cs":["Za nestálost se klade rorýs, který je stále v pohybu, protože nesnese ani nejmenší nepohodlí."],"ref":{"s":"H","l":12,"st":"v","z":true,"raw":"H.12 v"},"ca":[]},{"id":"s072","o":"Allegorie","c":"XXVI","str":38,"ni":"temperanza","nc":"Střídmost","it":["Il cammello è il più lussurioso animale che sia, e andrebbe mille miglia dirieto a una cammella, e, se usassi continuo con la madre o sorelle, mai le tocca, tanto si sa ben temperare."],"cs":["Velbloud je nejchlípnější zvíře, jaké jest, a šel by tisíc mil za velbloudicí; a třebaže by stále žil s matkou nebo se sestrami, nikdy se jich nedotkne, tak dobře se umí krotit."],"ref":{"s":"H","l":12,"st":"v","z":true,"raw":"H.12 v"},"ca":[]},{"id":"s073","o":"Allegorie","c":"XXVII","str":38,"ni":"intemperanza","nc":"Nestřídmost","it":["L’alicorno overo unicorno, per la sua intemperanza a non sapersi vincere, per lo diletto die ha delle donzelle, dimentica la sua ferocità e salvatichezza; ponendo da canto ogni sospetto va alla sedente donzella, se le addormenta in grembo; e i cacciatori in tal modo lo pigliano."],"cs":["Jednorožec pro svou nestřídmost, protože se neumí přemoci, zapomíná pro rozkoš, kterou má z panen, na svou divokost a plachost; odloží veškerou nedůvěru, jde k sedící panně a usne jí v klíně; a tak ho lovci chytají."],"ref":{"s":"H","l":12,"st":"v","z":true,"raw":"H.12 v"},"ca":[]},{"id":"s074","o":"Allegorie","c":"XXVIII","str":39,"ni":"umiltà","nc":"Pokora","it":["Dell’umiltà si vede somma sperienza nello agnello; il quale si sottomette a ogni animale, e, quando per cibo son dati alli 'ncarcerati leoni, a quelli si sottomettono, come alla propria madre, in modo che, spesse volte, s’è visto i leoni non li volere occidere."],"cs":["Nejvyšší doklad pokory spatřujeme u beránka, který se podrobuje každému zvířeti; a když jsou beránci dáni za potravu uvězněným lvům, podrobují se jim jako vlastní matce, takže se mnohokrát vidělo, že je lvi nechtěli zabít."],"ref":{"s":"H","l":12,"st":"v","z":true,"raw":"H.12 v"},"ca":[]},{"id":"s075","o":"Allegorie","c":"XXIX","str":39,"ni":"superbia","nc":"Pýcha","it":["Il falcone, per la sua alterigia e superbia, vole signoreggiare e sopraffare tutti li altri uccelli, che son di rapina, e sen’ desidera essere solo; e spesse volte s’è veduto il falcone assaltare l’aquila, regina delli uccelli."],"cs":["Sokol chce pro svou zpupnost a pýchu panovat nad všemi ostatními dravými ptáky a přemáhat je, a touží být sám; a mnohokrát bylo viděno, jak sokol napadá orla, krále ptáků."],"ref":{"s":"H","l":12,"st":"v","z":true,"raw":"H.12 v"},"ca":[]},{"id":"s076","o":"Allegorie","c":"XXX","str":39,"ni":"astinenza","nc":"Zdrženlivost","it":["Il salvatico asino, quando va alla fonte per bere e truova l’acqua intorbidata, non arà mai sì gran sete, che non s’astenga di bere, e aspetti ch’essa acqua si rischiari."],"cs":["Divoký osel, když přijde k prameni napít se a najde vodu zakalenou, nebude mít nikdy tak velkou žízeň, aby se nezdržel pití a nepočkal, až se ta voda vyjasní."],"ref":{"s":"H","l":12,"st":"v","z":true,"raw":"H.12 v"},"ca":[]},{"id":"s077","o":"Allegorie","c":"XXXI","str":39,"ni":"gola","nc":"Obžerství","it":["Il voltore è tanto sottoposto alla gola, che andrebbe mille miglia per mangiare d’una carogna; e per questo seguita (li eserciti)."],"cs":["Sup tak podléhá obžerství, že by šel tisíc mil, aby se najedl mršiny; a proto táhne za vojsky."],"ref":{"s":"H","l":12,"st":"v","z":true,"raw":"H.12 v"},"ca":[]},{"id":"s078","o":"Allegorie","c":"XXXII","str":40,"ni":"castità","nc":"Cudnost","it":["La tortora non fa mai fallo al suo compagno, e, se l’uno more, l’altro osserva perpetua castità, e non si posa mai su ramo verde, e non bee mai acqua chiara."],"cs":["Hrdlička nikdy svému druhovi nezahne; a umře-li jeden, druhý zachovává věčnou cudnost a nikdy neusedne na zelenou ratolest a nikdy nepije čistou vodu."],"ref":{"s":"H","l":12,"st":"v","z":true,"raw":"H.12 v"},"ca":[]},{"id":"s079","o":"Allegorie","c":"XXXIII","str":40,"ni":"lussuria","nc":"Smilstvo","it":["Il palpistrelio, per la sua isfrenata lussuria, non osserva alcuno universale modo di lussuria, anzi maschio con maschio, femmina con femmina, sì come a caso si trovano, insieme usano il lor coito."],"cs":["Netopýr pro své nevázané smilstvo nedodržuje žádný obecný řád smilstva, nýbrž samec se samcem a samice se samicí, jak se náhodou sejdou, spolu obcují."],"ref":{"s":"H","l":12,"st":"v","z":true,"raw":"H.12 v"},"ca":[]},{"id":"s080","o":"Allegorie","c":"XXXIV","str":40,"ni":"moderanza","nc":"Umírněnost","it":["L’ermellino, per la sua moderanza, non mangia se non una sola volta il di, e prima si lascia pigliare a’ cacciatori che voler fuggire nella infangata tana per non maculare la sua gentilezza."],"cs":["Hranostaj pro svou umírněnost jí jen jednou za den, a raději se dá chytit lovcům, než by chtěl utéci do zablácené nory, aby nepošpinil svou ušlechtilost."],"ref":{"s":"H","l":12,"st":"v","z":true,"raw":"H.12 v"},"ca":[]},{"id":"s081","o":"Allegorie","c":"XXXV","str":40,"ni":"aquila","nc":"Orel","it":["L’aquila, quando è vecchia, vola tanto in alto che abbrucia le sue penne, e natura consente che si rinnovi in gioventù, cadendo nella poca acqua. E, se i sua nati non po’ sostener la vista del sole, non li pasce. Nessuno uccel, che non vole morire, non s’accosti al suo nido! Gli animali che forte la temano! Ma essa a lor non noce: sempre lascia rimanente della sua preda."],"cs":["Orel, když je starý, vzlétne tak vysoko, že si spálí peří, a příroda mu dopřává, aby se obnovil k mládí, když spadne do mělké vody. A jestliže jeho mláďata nesnesou pohled do slunce, nekrmí je. Žádný pták, který nechce zemřít, ať se nepřibližuje k jeho hnízdu! Zvířata, jak se ho velmi bojí! On jim však neškodí: vždy nechává zbytek své kořisti."],"ref":null,"ca":[]},{"id":"s082","o":"Allegorie","c":"XXXVI","str":41,"ni":"lumerpa, fama","nc":"Lumerpa, sláva","it":["Questa nasce nell’Asia Maggiore, e splende si forte che toglie le sue ombre, e morendo non perde esso lume, e mai li cade più le penne, e la penna, che si spicca, più non luce."],"cs":["Ta se rodí ve Velké Asii a září tak silně, že ruší své stíny; a umírajíc to světlo neztrácí, a nikdy jí už nepadá peří, a pero, které se oddělí, už nesvítí."],"ref":{"s":"H","l":12,"st":"v","z":true,"raw":"H.12 v"},"ca":[]},{"id":"s083","o":"Allegorie","c":"XXXVII","str":41,"ni":"pellicano","nc":"Pelikán","it":["Questo porta grande amore a’ sua nati, e, trovando quelli nel nido morti dal serpente, si punge a riscontro al core, e, col suo piovente sangue bagnandoli, li torna in vita."],"cs":["Ten chová velikou lásku ke svým mláďatům; a když je nalezne v hnízdě zabité hadem, klove se proti srdci a svou crčící krví je skrápí a vrací je k životu."],"ref":{"s":"H","l":14,"st":"r","z":true,"raw":"H. 14 r"},"ca":[]},{"id":"s084","o":"Allegorie","c":"XXXVIII","str":41,"ni":"salamandra","nc":"Salamandr","it":["La salamandra nel foco raffina la sua scorza. Per la virtù: questa non ha membra passive, e non si prende la cura d’altro cibo che di foco, e spesso in quello rinnova la sua scorza."],"cs":["Salamandr v ohni zjemňuje svou kůži. Pro ctnost: ten nemá trpné údy a nestará se o jinou potravu než o oheň a často v něm obnovuje svou kůži."],"ref":{"s":"H","l":14,"st":"r","z":true,"raw":"H. 14 r"},"ca":[]},{"id":"s085","o":"Allegorie","c":"XXXIX","str":42,"ni":"camaleon","nc":"Chameleon","it":["Questo vive d’aria, e in quella s’assubietta tutti li uccelli; e, per istare più salvo, vola sopra le nube, e trova aria tanto sottile, che non po’ sostenere uccello, che lo seguiti.","A questa altezza non va se non a dchi da’ cieli è dato, cioè dove vola il camaleone."],"cs":["Ten žije ze vzduchu a v něm si podrobuje všechny ptáky; a aby byl bezpečnější, létá nad mraky a nachází vzduch tak řídký, že neunese ptáka, který by ho sledoval.","Do této výše nedojde nikdo jiný, než komu to bylo dáno nebesy, totiž tam, kam létá chameleon."],"ref":{"s":"H","l":14,"st":"r","z":true,"raw":"H. 14 r"},"ca":[]},{"id":"s086","o":"Allegorie","c":"XL","str":42,"ni":"alepo pesce","nc":"Ryba alepo","it":["Alepo non vive fori dell’acqua."],"cs":["Alepo nežije mimo vodu."],"ref":null,"ca":[]},{"id":"s087","o":"Allegorie","c":"XLI","str":42,"ni":"struzzo","nc":"Pštros","it":["Questo converte il ferro in suo nutrimento; cova l’ova colla vista. Per l’arme, nutrimento de’ capitani."],"cs":["Ten obrací železo ve svou potravu; vejce zahřívá pohledem. Obrazně o zbraních: potrava vojevůdců."],"ref":{"s":"H","l":14,"st":"r","z":true,"raw":"H. 14 r"},"ca":[]},{"id":"s088","o":"Allegorie","c":"XLII","str":42,"ni":"cigno","nc":"Labuť","it":["Cigno è candido, sanza alcuna macchia e dolcemente canta nel morire; il qual canto termina la vita."],"cs":["Labuť je bělostná, bez jediné skvrny, a v umírání sladce zpívá; a ten zpěv končí její život."],"ref":{"s":"H","l":14,"st":"r","z":true,"raw":"H. 14 r"},"ca":[]},{"id":"s089","o":"Allegorie","c":"XLIII","str":42,"ni":"cicogna","nc":"Čáp","it":["Questa, bevendo la salsa acqua, caccia da sè il male; se truova la compagna in fallo, l’abbandona, e, quando è vecchia, i sua figlioli la covano e pascano, in fin che more."],"cs":["Ten, pije-li slanou vodu, vyhání ze sebe nemoc; přistihne-li družku v nevěře, opustí ji; a když je starý, jeho mláďata ho zahřívají a krmí, dokud neumře."],"ref":{"s":"H","l":14,"st":"r","z":true,"raw":"H. 14 r"},"ca":[]},{"id":"s090","o":"Allegorie","c":"XLIV","str":43,"ni":"cicala","nc":"Cikáda","it":["Questa col suo canto fa tacere il cucco; more nell’olio e rinasce nell’aceto; canta per li ardenti caldi."],"cs":["Ta svým zpěvem umlčuje kukačku; umírá v oleji a znovu se rodí v octě; zpívá v žhavých vedrech."],"ref":{"s":"H","l":14,"st":"r","z":false,"raw":"H. 14 r"},"ca":[]},{"id":"s091","o":"Allegorie","c":"XLV","str":43,"ni":"basalisc0","nc":"Bazilišek","it":["Crudeltà. Questo è fuggito da tutti i serpenti, la donnola, per lo mezzo della ruta, combatte con esso, e sì l’uccide."],"cs":["Krutost. Toho se straní všichni hadi; lasice s ním skrze routu bojuje, a tak ho zabije."],"ref":null,"ca":[]},{"id":"s092","o":"Allegorie","c":"XLVI","str":43,"ni":"l’aspilo, sta per la virtù","nc":"Aspida, znamená ctnost","it":["Questo porta ne’ denti la subita morte, e, per non sentire l’incanti, colla coda si stóppa li orecchi."],"cs":["Ta nosí v zubech náhlou smrt, a aby neslyšela zaříkávání, ucpává si ocasem uši."],"ref":null,"ca":[]},{"id":"s093","o":"Allegorie","c":"XLVII","str":43,"ni":"drago","nc":"Drak","it":["Questo lega le gambe al liofante, e quel li cade adosso, e l’uno e l’altro more. E, morendo, fa sua vendetta."],"cs":["Ten spoutá slonovi nohy, a slon na něj padne, a umírají oba. A umíraje, vykoná svou pomstu."],"ref":{"s":"H","l":15,"st":"r","z":true,"raw":"H. 15 r"},"ca":[]},{"id":"s094","o":"Allegorie","c":"XLVIII","str":43,"ni":"vipera","nc":"Zmije","it":["Quest’ha nel suo, ch’apre bocca, e nel fine strigne’ denti, e ammazza il marito; poi i figlioli, in corpo cresciuti, straccian il ventre, e occidano la madre."],"cs":["Ta má při svém [páření] to, že otevře tlamu a na konci sevře zuby a zabije manžela; pak mláďata, dorostlá v jejím těle, roztrhají jí břicho a zabijí matku."],"ref":{"s":"H","l":15,"st":"r","z":true,"raw":"H. 15 r"},"ca":[]},{"id":"s095","o":"Allegorie","c":"XLIX","str":44,"ni":"scorpione","nc":"Štír","it":["La sciliva sputa a digiuno sopra dello scorpione, l’occide; a similitudine dell’astinenza della gola, che tolle via e occide le malattie, che da essa gola dipendano, e apre la strada alle virtù."],"cs":["Slina, plivnutá nalačno na štíra, jej zabije; podobně jako zdrženlivost v obžerství, která odstraňuje a zabíjí nemoci pocházející z obžerství a otvírá cestu ctnostem."],"ref":{"s":"H","l":15,"st":"r","z":false,"raw":"H. 15 r"},"ca":[]},{"id":"s096","o":"Allegorie","c":"L","str":44,"ni":"cocodrillo, ipocresia","nc":"Krokodýl, pokrytectví","it":["Questo animale piglia Tomo, e subito l’uccide. Poi che l’ha morto, con lamentevole voce e molte lacrime, lo piange, e, finito il lamento, crudelmente lo divora. Così fa l’ipocrito, che, per ogni più lieve cosa, s’empie il viso di lagrime, mostrando un cor di tigre, e rallegrasi in cor dell’altrui male, con pietoso volto."],"cs":["Toto zvíře chytí člověka a hned ho zabije. Když ho usmrtí, oplakává ho žalostným hlasem a mnoha slzami, a když skončí nářek, krutě ho pozře. Tak činí pokrytec, který si pro každou maličkost zaplaví tvář slzami, ukazuje srdce tygra a v srdci se s lítostivou tváří raduje z cizího neštěstí."],"ref":{"s":"H","l":17,"st":"r","z":true,"raw":"H. 17 r"},"ca":[]},{"id":"s097","o":"Allegorie","c":"LI","str":44,"ni":"botta","nc":"Ropucha","it":["La botta fugge la luce del sole, e, se pure per forza è tenuta, sgonfia tanto che s’asconde la testa in basso, e privasi d’essi razzi. Così fa chi è nimico della chiara e lucente virtù, che non po’, se non con insgonfiato animo, forzatamente starle davanti."],"cs":["Ropucha prchá před slunečním světlem, a je-li přece násilím držena, nafoukne se tak, že si skryje hlavu dole a připraví se o ty paprsky. Tak činí ten, kdo je nepřítelem jasné a zářící ctnosti, a nemůže před ní stát jinak než z donucení a s nadutou myslí."],"ref":{"s":"H","l":17,"st":"r","z":false,"raw":"H. 17 r"},"ca":[]},{"id":"s098","o":"Allegorie","c":"LII","str":45,"ni":"bruco, della virtù in generale","nc":"Housenka, o ctnosti vůbec","it":["Il bruco, che, mediante l’esercitato studio di tessere con mirabile artifizio e sottile lavoro intorno a sè la nova abitazione, esce poi fori di quella colle dipinte e belle ali, con quelle lanciandosi in verso il cielo."],"cs":["Housenka, která pilným úsilím, s nímž obdivuhodně umně a jemnou prací tká kolem sebe nový příbytek, z něho pak vychází s malovanými a krásnými křídly a jimi se vznáší k nebi."],"ref":{"s":"H","l":18,"st":"v","z":true,"raw":"H. 18 v"},"ca":[]},{"id":"s099","o":"Allegorie","c":"LIII","str":45,"ni":"ragno","nc":"Pavouk","it":["Il ragno partorisce fori di sè l’artificiosa e maestrevole tela, la quale gli rende, per benefizio, la presa preda."],"cs":["Pavouk ze sebe rodí umnou a mistrnou síť, která mu jako odměnu vrací chycenou kořist."],"ref":{"s":"H","l":18,"st":"v","z":false,"raw":"H. 18 v"},"ca":[]},{"id":"s100","o":"Allegorie","c":"LIV","str":45,"ni":"leone","nc":"Lev","it":["Questo animale col suo tonante grido desta i sua figlioli, dopo il terzo giorno nati, aprendo a quelli tutti l’indormentati sensi: e tutte le fiere, che nella selva sono, fuggano.","Puossi assimigliare a’ figlioli della virtù, che, mediante il grido delle laude, si svegliano, e crescano li studi onorevoli, che sempre più gl’innalzan, e tutti i tristi a esso grido fuggano, cessandosi dai virtuosi.","Ancora, il leone copre le sue pedate, perchè non s’intenda il suo viaggio per i nimici. Questo sta bene ai capitani a celare i segreti del suo animo, acciò che’ nimici non cognoscano i sua tratti."],"cs":["Toto zvíře svým hřmícím řevem budí svá mláďata, třetího dne po narození, a otvírá jim všechny spící smysly; a všechna divoká zvířata, která jsou v lese, prchají.","Lze to přirovnat k dětem ctnosti, které se probouzejí řevem chvály, a rostou v nich čestná studia, která je stále víc povznášejí, a všichni zlí před tím řevem prchají a vzdalují se od ctnostných.","Dále lev zakrývá své stopy, aby nepřátelé nepoznali jeho cestu. To sluší vojevůdcům, aby tajili tajemství své mysli, aby nepřátelé nepoznali jejich záměry."],"ref":{"s":"H","l":22,"st":"v","z":false,"raw":"H. 22 v"},"ca":[]},{"id":"s101","o":"Allegorie","c":"LV","str":46,"ni":"taranta","nc":"Tarantule","it":["Il morso della taranta mantiene l’omo nel suo proponimento, cioè in quello che pensava, quando fu morso."],"cs":["Kousnutí tarantule udržuje člověka v jeho předsevzetí, totiž v tom, na co myslel, když byl kousnut."],"ref":null,"ca":[]},{"id":"s102","o":"Allegorie","c":"LVI","str":46,"ni":"duco o civetta","nc":"Výr neboli sýček","it":["Queste castigano i loro schermidori, privandoli di vita, che così ha ordinato natura, perchè si cibino."],"cs":["Tito trestají ty, kdo se jim posmívají, tím, že je připravují o život; tak to zařídila příroda, aby se nasytili."],"ref":null,"ca":[]},{"id":"s103","o":"Allegorie","c":"LVII","str":46,"ni":"leofante","nc":"Slon","it":["Il grande elefante ha, per natura, quel che raro negli omini si truova, cioè probità, prudenza, equità e osservanza in religione. Imperocchè, quando la luna si rinnova, questi vanno ai fiumi e, quivi purgandosi, solennemente si lavano, e così, salutato il pianeta, si ritornano alle selve. E, quando sono ammalati, stando supini, gittano l’erbe verso il cielo, quasi come se sacrificare volessino.","Sotterra li denti, quando per vecchiezza gli caggiano; de’ sua denti, l’uno adopra a cavare le radici per cibarsi, all’altro conserva la punta per combattere. Quando sono superati da’ cacciatori e che la stanchezza gli vince, percotesi li denti l’elefante e, quelli trattosi, con essi si ricomprano.","Sono clementi e conoscano i pericoli: e, so esso trova l’omo solo e smarrito, piacevolmente lo rimette sulla perduta strada; se truova le pedate dell’omo, prima che veda l’omo, esso teme tradimento, onde si ferma e soffia, mostrandola all’altri elefanti, e fanno schiera, e vanno assentitamente.","Questi vanno sempre a schiere, e ’l piu vecchio va innanzi, e ’l secondo d’età resta l’ultimo, e così chiudono la schiera. Temano vergogna: non usano il loro coito, se non di notte di nascosto, e non tornano, dopo il coito, alli armenti, se prima non si lavano nel fiume; non combattono ma’ femmine, come gli altri animali. È di tanto clemente, che mal volentieri, per natura, non noce ai men possenti di sè, e, scontrandosi nella mandria e greggi delle pecore, colla sua mano le pone da parte per non le pestare co’ piedi, nè mai noce, se non sono provocati. Quando son caduti nella fossa, gli altri con rami, terra e sassi riempiano la fossa, in modo alzano il fondo, ch’esso facilmente riman libero. Temano forte lo stridere de’ porci, e fuggan indirieto, e non fa manco danno poi co’ piedi a’ sua che a’ nimici. Dilettansi de’ fiumi, e sempre vanno vagabondi intorno a quegli, e per lo gran peso non possan notare; divorano le pietre, i tronchi degli alberi son loro gratissimo cibo, hanno in odio i ratti; le mosche si dilettano del suo odore e, posandosele adosso, quello arrappa la pelle e, fra le pieghe strette, l’uccide.","Quando passano i fiumi, mandano i figlioli diverso il calar dell’acqua, e, stando loro inverso l’erta, rompono l’unito corso dell’acqua, a ciò che ’l corso non li menasse via.","Il drago se li getta sotto il corpo, colla coda l’annoda le gambe, e coll’ali e colle branche li cigne le coste, e co’ denti lo scanna, e ’l liofante li cade adosso, e il drago schioppa e così, colla sua morte, del nemico si vendica."],"cs":["Velký slon má od přírody to, co se u lidí nachází jen zřídka, totiž poctivost, rozvážnost, spravedlnost a zachovávání náboženství. Neboť když se luna obnovuje, chodí sloni k řekám, a tam se očišťujíce, slavnostně se omývají, a pozdravivše tak planetu, vracejí se do lesů. A když jsou nemocní, lehnou si na záda a vyhazují byliny k nebi, jako by chtěli obětovat.","Zahrabává své kly, když mu stářím vypadnou; z jeho klů jedním dobývá kořeny, aby se nasytil, druhému šetří hrot k boji. Když je lovci přemohou a když je přemůže únava, uráží si slon kly, a když si je vyrazí, vykupují se jimi.","Jsou mírní a znají nebezpečí; a nalezne-li slon člověka samotného a zbloudilého, vlídně ho uvede zpět na ztracenou cestu; nalezne-li lidské stopy dřív, než člověka spatří, bojí se zrady, a proto se zastaví a funí a ukazuje je ostatním slonům; a ti se seřadí a jdou obezřetně.","Ti chodí vždy v šicích, a nejstarší jde vpředu, a druhý co do věku zůstává poslední, a tak uzavírají šik. Bojí se hanby: páří se jen v noci a skrytě, a po páření se nevracejí ke stádu, dokud se předtím neumyjí v řece; nebojují kvůli samicím jako jiná zvířata. Slon je tak mírný, že od přírody nerad škodí slabším, než je sám; a když se setká se stádem a ovčími houfy, odloží je chobotem stranou, aby je nerozšlapal nohama; a nikdy neškodí, nejsou-li vyprovokováni. Když některý spadne do jámy, ostatní zaplní jámu větvemi, zemí a kamením a tak zvednou dno, že se snadno vysvobodí. Velmi se bojí kvičení vepřů a utíkají nazpět, a pak nohama nenadělají menší škodu svým než nepřátelům. Libují si v řekách a stále se toulají kolem nich, a pro svou velkou váhu nemohou plavat; polykají kameny, kmeny stromů jsou jim nejmilejší potravou, nenávidí krysy; mouchy si libují v jeho pachu, a když na něm usednou, slon nakrčí kůži a v těsných záhybech je zabije.","Když přecházejí řeky, posílají mláďata po proudu, a sami stojíce proti proudu, lámou sevřený tok vody, aby je proud neodnesl.","Drak se mu vrhne pod tělo, ocasem mu spoutá nohy a křídly a pařáty mu sevře boky a zuby mu podřízne hrdlo; a slon na něj padne, a drak praskne, a tak se svou smrtí na nepříteli pomstí."],"ref":null,"ca":[]},{"id":"s104","o":"Allegorie","c":"LVIII","str":48,"ni":"il dragone","nc":"Drak","it":["Questi s’accompagnan insieme, e si tessano a uso di ratiti, e, colla testa levata, passano i paduli, e notano, dove trovan migliore pastura, e, se così non si unissin, annegherebbono. Così fa unione."],"cs":["Ti se sdružují a proplétají se navzájem jako vory, a se zdviženou hlavou přecházejí bažiny a plavou tam, kde nacházejí lepší pastvu; a kdyby se takto nespojili, utopili by se. Tak působí jednota."],"ref":null,"ca":[]},{"id":"s105","o":"Allegorie","c":"LIX","str":49,"ni":"serpente","nc":"Had","it":["Il serpente, grandissimo animale, quando vede alcuno uccello per l’aria, tira a se sì forte il fiato, che si tira gli uccelli in bocca. Marco Reguìo, consulo dello esercito romano, fu col suo esercito da un simile animale assalito e quasi rotto. Il quale animale, essendo morto per una macchina murale, fu misurato 125 piedi, cioè 64 braccia e 1/2: avanzava colla testa tutte le piante d’una selva."],"cs":["Had, převeliké zvíře, když spatří nějakého ptáka ve vzduchu, vtáhne do sebe dech tak silně, že si ptáky vtáhne do tlamy. Marcus Regulus, konzul římského vojska, byl i se svým vojskem napaden podobným zvířetem a téměř poražen. To zvíře, když bylo zabito obléhacím strojem, bylo naměřeno na 125 stop, totiž 64 a 1/2 lokte: hlavou převyšovalo všechny stromy lesa."],"ref":{"s":"H","l":17,"st":"v","z":true,"raw":"H. 17 v"},"ca":[]},{"id":"s106","o":"Allegorie","c":"LX","str":49,"ni":"boa","nc":"Boa","it":["Questa è gran biscia, la quale con sè medesima s’aggrappa alle gambe della vacca, in modo non si mova, poi la tetta, in modo che quasi la dissecca. Di questa spezie, a tempo di Claudio imperadore, sul monte Vaticano ne fu morta una, che aveva un putto intero in corpo, il quale avea tranghiottito."],"cs":["To je veliký had, který se sám sebou ovine kravě kolem nohou, takže se nemůže pohnout, a pak ji saje, až ji téměř vysuší. Z tohoto druhu byl za císaře Claudia na pahorku Vatikánu zabit jeden, který měl v těle celé dítě, jež spolkl."],"ref":null,"ca":[]},{"id":"s107","o":"Allegorie","c":"LXI","str":49,"ni":"macli pel sonno è giunta","nc":"Machlis – spánek mu je záhubou","it":["Questa bestia nasce in Iscandinavia isola, ha forma di gran cavallo, se non che la gran lunghezza dello collo e delli orecchi lo variano; pasce l’erba allo ’ndirieto, perchè ha sì lungo il labbro di sopra che, pascendo innanzi, coprirebbe l’erba. Ha le gambe d’un pezzo, per questo, quando vol dormire, s’appoggia a uno albero, e i cacciatori, intendendo il loco usato a dormire, segan quasi tutta la pianta, e, quando questo poi vi s’appoggia nel dormire, per lo sonno cade; i cacciatori così lo pigliano, e ogni altro modo di pigliarlo è vano, perchè è d’incredibile velocità nel correre."],"cs":["Toto zvíře se rodí na ostrově Skandinávii, má podobu velkého koně, jen ho odlišuje veliká délka krku a uší; pase se pozpátku, protože má tak dlouhý horní pysk, že kdyby se pásl dopředu, zakryl by trávu. Má nohy z jednoho kusu, a proto, když chce spát, opírá se o strom; a lovci, znajíce místo, kde obvykle spí, podříznou ten strom skoro celý, a když se o něj pak ve spánku opře, spánkem padne; tak jej lovci chytají, a každý jiný způsob, jak ho chytit, je marný, neboť běží neuvěřitelně rychle."],"ref":null,"ca":[]},{"id":"s108","o":"Allegorie","c":"LXII","str":50,"ni":"bonaso noce colla fuga","nc":"Bonasus škodí útěkem","it":["Questo nasce in Peonia, ha còllo con clini simile al cavallo, in tutte l’altre parte è simile al toro, salvo che le sue corna sono in modo piegate indentro che non po’ cozzare, e per questo non ha altro scampo che la fuga, nella quale gitta sterco per ispazio di 400 braccia del suo corso — il quale, dove tocca, abbrucia come foco."],"cs":["Ten se rodí v Paionii, má krk s hřívou podobný koni, ve všech ostatních částech se podobá býku, jenže jeho rohy jsou tak zahnuté dovnitř, že nemůže trkat; a proto nemá jiné záchrany než útěk, při němž vyhazuje trus v délce 400 loktů svého běhu – a ten, kam dopadne, pálí jako oheň."],"ref":null,"ca":[]},{"id":"s109","o":"Allegorie","c":"LXIII","str":50,"ni":"palpistrell0","nc":"Netopýr","it":["Questo dov’è più luce, più si fa orbo, e, come più guarda il sole, più s’accieca. Pel vizio, che non po’ stare dov’è la virtù."],"cs":["Ten, čím víc je kde světla, tím víc slepne, a čím víc hledí do slunce, tím víc oslepuje. Pro neřest, která nemůže být tam, kde je ctnost."],"ref":null,"ca":[]},{"id":"s110","o":"Allegorie","c":"LXIV","str":51,"ni":"pernice","nc":"Koroptev","it":["Questa si trasmuta di femmina in maschio, e dimentica il primo sesso, e fura per invidia l’ova all’altre, ma i nati seguitano la vera madre."],"cs":["Ta se proměňuje ze samice v samce a zapomíná na své první pohlaví, a ze závisti krade vejce jiným; ale vylíhlá mláďata následují pravou matku."],"ref":null,"ca":[]},{"id":"s111","o":"Allegorie","c":"LXV","str":51,"ni":"rondine","nc":"Vlaštovka","it":["Questa co’ la celidonia ’lumina i sua ciechi nati."],"cs":["Ta vlaštovičníkem vrací světlo svým slepým mláďatům."],"ref":null,"ca":[]},{"id":"s112","o":"Allegorie","c":"LXVI","str":51,"ni":"ermellino","nc":"Hranostaj","it":["Moderanza raffrena tutti i vizi. L’ermellino prima voi morire che ’mbrattarsi."],"cs":["Umírněnost krotí všechny neřesti. Hranostaj chce raději zemřít, než se pošpinit."],"ref":null,"ca":[]},{"id":"s113","o":"Allegorie","c":"LXVII","str":51,"ni":"leoni, pardi, pantere, tigri","nc":"Lvi, levharti, pantery, tygři","it":["Queste tengano l’unghie nella guaina, e mai le sfoderano, se non è adosso alla preda o nemico."],"cs":["Ti mají drápy v pochvě a nikdy je nevytasí, leda na kořist nebo na nepřítele."],"ref":null,"ca":[]},{"id":"s114","o":"Allegorie","c":"LXVIII","str":51,"ni":"leonessa","nc":"Lvice","it":["Quando la leonessa difende i figlioli dalle man de cacciatori, per non si spaventare dalli spiedi, abbassa li occhi a terra, a ciò che là, per sua fuga, i figli non sieno prigioni."],"cs":["Když lvice brání mláďata před rukama lovců, sklopí oči k zemi, aby se nezalekla kopí, aby tak její mláďata nebyla jejím útěkem vydána do zajetí."],"ref":null,"ca":[]},{"id":"s115","o":"Allegorie","c":"LXIX","str":52,"ni":"leone","nc":"Lev","it":["Questo sì terribile animale niente teme più che lo strepito delle vote carrette e simile il canto de’ galli; teme assai nel vederli e con pauroso aspetto riguarda la sua cresta — e forte invilisce quando ha coperto il volto."],"cs":["Toto tak hrozné zvíře se ničeho nebojí víc než rachotu prázdných vozíků a podobně kohoutího zpěvu; velmi se bojí, když kohouty vidí, a s ustrašeným pohledem hledí na jejich hřebínek – a velmi zmalomyslní, když má zakrytou tvář."],"ref":null,"ca":[]},{"id":"s116","o":"Allegorie","c":"LXX","str":52,"ni":"pantere in africa","nc":"Pantery v Africe","it":["Questa ha forma di leonessa, ma è più alta di gambe e più sottile e lunga e tutta bianca e punteggiata di macchie nere, a modo di rosette; di questa si dilectano tutti li animali di vedere, e sempre le starebbon dintorno se non fussi la terribilità del suo viso: onde essa, questo conoscendo, asconde il viso, e li animali circustanti s’assicurano e fannosi vicini per meglio potere fruire tanta bellezza, onde questa subito piglia il più vicino e subito lo divora."],"cs":["Ta má podobu lvice, ale má delší nohy a je štíhlejší a delší a celá bílá a poseta černými skvrnami v podobě růžiček; na ni se všechna zvířata rádi dívají a stále by stála kolem ní, nebýt hrůzy jejího obličeje; a proto ona, vědouc to, skrývá obličej, a okolní zvířata se uklidní a přiblíží se, aby se mohla lépe kochat takovou krásou; tu ona hned chytí to nejbližší a hned ho pozře."],"ref":null,"ca":[]},{"id":"s117","o":"Allegorie","c":"LXXI","str":52,"ni":"cammelli","nc":"Velbloudi","it":["Quegli Battriani hanno due gobbi, gli Arabi uno; sono veloci in battaglia e utilissimi a portare le some. Questo animale ha regola e misura osservantissima, perchè non si move, se ha più carico che l’usato, e, se fa più viaggio, fa il simile, subito si ferma, onde lì bisogna a’ mercatanti alloggiare."],"cs":["Baktrijští mají dva hrby, arabští jeden; jsou rychlí v bitvě a nadmíru užiteční k nošení břemen. Toto zvíře velmi přísně zachovává pravidlo a míru, neboť se nehne, má-li větší náklad než obvykle; a jde-li delší cestu, činí totéž, hned se zastaví, a kupci tam pak musejí přenocovat."],"ref":null,"ca":[]},{"id":"s118","o":"Allegorie","c":"LXXII","str":53,"ni":"tigre","nc":"Tygr","it":["Questa nasce in Ircania, la quale è simile alquanto alla pantera per le diverse macchie della sua pelle, ed è animale di spaventevole velocità. Il cacciatore, quando truova i sua figli, li rapisce, subito ponendo specchi nel loco donde li leva, e subito, sopra veloce cavallo, si fugge. La pantera, tornando, trova li specchi fermi in terra, ne’ quali, vedendo sè, li pare vedere li sua figlioli, e, raspando colle zampe, scopre lo ’nganno, onde, mediante l’odore de’ figli, seguita il cacciatore, e quando esso cacciatore vede la tigre, lascia uno de’ figlioli, e questa lo piglia e portalo al nido, e subito rigiugne sul cacciatore, e fa ’l simile insino a tanto ch’esso monta in barca."],"cs":["Ten se rodí v Hyrkánii a je poněkud podobný pantheře pro rozmanité skvrny na své kůži, a je to zvíře děsivé rychlosti. Lovec, když najde jeho mláďata, uloupí je, hned položí zrcadla na místo, odkud je vzal, a hned na rychlém koni prchá. Pantera, když se vrátí, najde zrcadla ležet na zemi, a vidouc v nich sebe, zdá se jí, že vidí svá mláďata; a hrabajíc tlapami, odhalí lest, a tak podle pachu mláďat stíhá lovce; a když lovec spatří tygřici, pustí jedno z mláďat, a ona je vezme a odnese do doupěte, a hned zase lovce dostihne, a činí tak, dokud on nevstoupí na loď."],"ref":null,"ca":[]},{"id":"s119","o":"Allegorie","c":"LXXIII","str":53,"ni":"catopleas","nc":"Katoblepas","it":["Questa nasce in Etiopia, vicino al fonte Nìgricapo, è animale non troppo grande e pigro in tutte le membra, e ha ’l capo di tanta grandezza che malagevolmente lo porta in modo che sempre sta chinato inverso la terra, altremente sarebbe di somma peste alli omini, perchè qualunque e veduto da sua occhi subito more."],"cs":["Ten se rodí v Etiopii poblíž pramene Nigris, je to zvíře nepříliš veliké a líné ve všech údech, a má hlavu tak velikou, že ji jen stěží nese, takže ji má stále skloněnou k zemi; jinak by byl lidem nejhorší pohromou, neboť kdokoli je spatřen jeho očima, hned umírá."],"ref":null,"ca":[]},{"id":"s120","o":"Allegorie","c":"LXXIV","str":54,"ni":"basilisco","nc":"Bazilišek","it":["Questo nasce nella provincia Arenaica, e non è maggiore che 12 dita, e ha in capo una macchia bianca a similitudine di diadema; col fischio caccia ogni serpente, a similitudine di serpe, ma non si move con torture, anzi ma ritto dal mezzo innanzi. Dicesi che uno di questi, essendo morto con un aste da uno che era a cavallo, che ’l suo veneno discorrendo su per l’aste, non che l’omo, ma il cavallo morì. Guasta le biade, e, non solamente quelle che tocca, ma quelle dove soffia; secca l’erbe, spezza i sassi."],"cs":["Ten se rodí v kyrenaické provincii a není větší než 12 prstů, a má na hlavě bílou skvrnu podobnou diadému; sykotem zahání každého hada, je podobný hadovi, ale nepohybuje se svíjením, nýbrž jde od poloviny dopředu vzpřímený. Říká se, že když jednoho z nich zabil kopím jakýsi jezdec, jeho jed vystoupil po kopí a zemřel nejen člověk, ale i kůň. Ničí obilí, a nejen to, kterého se dotkne, ale i to, na které dýchne; suší byliny, láme kameny."],"ref":null,"ca":[]},{"id":"s121","o":"Allegorie","c":"LXXV","str":54,"ni":"donnola over bellola","nc":"Lasice","it":["Questa, trovando la tana del basilisco, coll’odore della sua sparsa orina, l’occide; l’odore della quale orina ancora, spesse volte, essa donnola occide."],"cs":["Ta, když nalezne doupě baziliška, zabije ho pachem své rozstříknuté moči; pach té moči ovšem mnohdy zabije i lasici samu."],"ref":null,"ca":[]},{"id":"s122","o":"Allegorie","c":"LXXVI","str":55,"ni":"ceraste","nc":"Cerasti","it":["Queste hanno quattro piccioli corni mobili, onde, quando si vogliano cibare, nascondano sotto le foglie tutta la persona, salvo esse cornicina; le quali movendo, pare agli uccelli quelli essere piccioli vermini, che scherzino, onde subito si calano per beccarli, e questa subito s’avviluppa loro in cerchio, e sì li divora."],"cs":["Ti mají čtyři malé pohyblivé růžky; a proto, když se chtějí nasytit, schovají pod listí celé tělo kromě těch růžků; a když jimi hýbou, zdá se ptákům, že jsou to malí červíci, kteří si hrají, a proto se hned snesou, aby je klovli; a had se jim hned ovine dokola a tak je pozře."],"ref":null,"ca":[]},{"id":"s123","o":"Allegorie","c":"LXXVII","str":55,"ni":"amfesibene","nc":"Amfisbéna","it":["Questa ha due teste, l’una nel suo loco, l’altra nella coda, come se non bastassi, che da un solo loco gittassi il veneno."],"cs":["Ta má dvě hlavy, jednu na svém místě a druhou na ocase, jako by nestačilo, aby vrhala jed z jediného místa."],"ref":null,"ca":[]},{"id":"s124","o":"Allegorie","c":"LXXVIII","str":55,"ni":"iaculo","nc":"Iaculus","it":["Questa sta sopra le piante, e si lancia come dardo, e passa attraverso le fiere, e l’uccide."],"cs":["Ten sedí na stromech a vymršťuje se jako šíp a probodává divoká zvířata a zabíjí je."],"ref":null,"ca":[]},{"id":"s125","o":"Allegorie","c":"LXXIX","str":55,"ni":"aspiro","nc":"Aspida","it":["Il morso di questo animale non ha rimedio, se non di subito tagliare le parti morse. Questo sì pestifero animale ha tale affezione nella sua compagna, che sempre vanno accompagnati; che, se per disgrazia l’uno di loro è morto, l’altro, con incredibile velocità, seguita l’ucciditore; ed è tanto attento e sollecito alla vendetta, che vince ogni difficultà, passando ogni esercito, feol il suo nemico cerca offendere, e passa ogni spazio, e non si può schifarlo, se non col passare l’acque o con velocissima fuga. Ha li occhi in dentro e grandi orecchi, e più move l’audito che ’l vedere."],"cs":["Proti kousnutí tohoto zvířete není léku, leda okamžitě odříznout pokousané části. Toto tak morové zvíře chová takovou náklonnost ke své družce, že chodí vždy spolu; a je-li nešťastnou náhodou jeden z nich zabit, druhý s neuvěřitelnou rychlostí stíhá vraha; a je tak pozorný a dychtivý pomsty, že překoná každou překážku, projde každým vojskem, jen aby mohl svému nepříteli ublížit, a překoná každou vzdálenost; a nelze se mu vyhnout jinak než přechodem přes vodu nebo nejrychlejším útěkem. Má oči vpadlé a veliké uši, a víc ho vede sluch než zrak."],"ref":null,"ca":[]},{"id":"s126","o":"Allegorie","c":"LXXX","str":56,"ni":"icneumone","nc":"Ichneumon","it":["Questo animale è mortale nemico all’aspido nasce in Egitto, e, quando vede presso al suo sito alcuno aspidi, subito corre alla litta over fango del Nilo, e con quello tutto s’infanga, e poi, risecco dal sole di novo di fango s’imbratta, o, così seccando l’un dopo l’altro si fa tre o quattro veste, a similitudine di corazza; e di poi assalta l’aspido, di corazza, e pd poi assalta l’aspido, e ben contrasta con quello, in modo che, tolto il tempo, se li caccia in gola e l’ammazza."],"cs":["Toto zvíře, smrtelný nepřítel aspidy, se rodí v Egyptě; a když spatří blízko svého místa nějakou aspidu, hned běží k nilskému bahnu neboli blátu a celé se jím zablátí, a pak, když je to sluncem vysušeno, znovu se bahnem pomaže, a tak, jednu vrstvu po druhé vysoušeje, udělá si tři nebo čtyři roucha na způsob pancíře; a potom napadne aspidu a statně s ní zápasí, takže, vystihnuv chvíli, vrhne se jí do chřtánu a zabije ji."],"ref":null,"ca":[]},{"id":"s127","o":"Allegorie","c":"LXXXI","str":56,"ni":"coccodrillo","nc":"Krokodýl","it":["Questo nasce nel Nilo, ha quattro piedi, nuoce in terra e in acqua, nè altro terrestre animale si truova sanza lingua, che questo, e solo morde movendo la mascella di sopra; ccrsce insino in 40 piedi, è unghiato, armato di colarne, atto a ogni colpo, e ’l dì sta in terra, e la notte in acqua. Questo, cibato di pesci, s’addormenta sulla riva del Nilo colla bocca aperta, e l’uccello detto trochilo, piccolissimo uccello, subito li corre alla bocca e, saltatoli fra i denti, dentro e fora li va beccando il rimaso cibo, e, così stuzzicandolo con dilettevole voluttà, lo ’nvita aprire tutta la bocca, e così s’addormenta. Questo veduto dal eumone, subito si li lancia in bocca e, foratoli lo stomaco e le budella, finalmente l’uccide."],"cs":["Ten se rodí v Nilu, má čtyři nohy, škodí na zemi i ve vodě, a nenachází se jiné suchozemské zvíře bez jazyka než toto, a jen on kouše pohybem horní čelisti; dorůstá až do 40 stop, má drápy, je obrněn tuhou kůží, odolnou proti každé ráně, a ve dne je na souši a v noci ve vodě. Ten, nasycen rybami, usíná na břehu Nilu s otevřenou tlamou, a pták zvaný trochilus, nepatrný ptáček, hned mu přiběhne k tlamě, a skočiv mu mezi zuby, vyzobává mu uvnitř i venku zbytky potravy, a tak ho lechtaje s rozkošnou slastí, láká ho otevřít celou tlamu, a tak usíná. Když to spatří ichneumon, hned se mu vrhne do tlamy, a provrtav mu žaludek a střeva, nakonec ho zabije."],"ref":null,"ca":[]},{"id":"s128","o":"Allegorie","c":"LXXXII","str":57,"ni":"delfino","nc":"Delfín","it":["La natura ha dato tal cognizione alli animali che, oltre al conoscere la loro comodità, e’ conoscono la incomodità del nimico, onde intende il delfino quanto vaglia il taglio delle sue pinne, posteli sulla schiena, e quanto sia tenera la pancia del cocodrillo, onde nel lor combattere sì li caccia sotto, e tagliali la pancia, e così l’uccide.","Il cocodrillo è terribile a chi fugge, e vilissimo a chi lo caccia."],"cs":["Příroda dala zvířatům takové poznání, že kromě toho, co je jim ku prospěchu, znají i to, co škodí nepříteli; a tak delfín chápe, jakou cenu má ostří jeho ploutví, umístěných na hřbetě, a jak měkké je břicho krokodýla; a proto se při jejich zápase vrhne pod něj, rozřízne mu břicho a tak ho zabije.","Krokodýl je hrozný tomu, kdo prchá, a nanejvýš zbabělý před tím, kdo ho honí."],"ref":null,"ca":[]},{"id":"s129","o":"Allegorie","c":"LXXXIII","str":58,"ni":"hippotamo","nc":"Hroch","it":["Questo, quando si sente aggravato, va cercando le spine o, dove sia,i rimanenti de’ tagliati canneti, e lì tanto frega una vena, che la taglia e, cavato il sangue che li abbisogna, colla litta s’infanga e risalda la piaga. Ha forma quasi come cavallo, l’unghia fessa, coda torta e denti di cinghiale, còllo con crini, la pelle non si po’ passare se non si bagna, pascesi di biade; ne’ campi entravi allo ’ndirieto, acciò che pare ne sia uscito."],"cs":["Ten, když se cítí obtížen, hledá trny nebo, kde jsou, zbytky posečených rákosin, a tam si tak dlouho tře žílu, až ji přeřízne; a když si pustí krev, kolik je mu třeba, zablátí se bahnem a zacelí ránu. Má podobu skoro jako kůň, rozpolcené kopyto, zatočený ocas a zuby kance, krk s hřívou; kůži nelze probodnout, není-li namočená; živí se obilím; na pole vstupuje pozpátku, aby se zdálo, že z nich vyšel."],"ref":null,"ca":[]},{"id":"s130","o":"Allegorie","c":"LXXXIV","str":58,"ni":"ibis","nc":"Ibis","it":["Questo ha similitudine colla cicogna, e, quando si sente ammalato, empie il gozzo d’acqua, e col becco si fa un cristero."],"cs":["Ten se podobá čápu, a když se cítí nemocen, naplní si vole vodou a zobákem si udělá klystýr."],"ref":null,"ca":[]},{"id":"s131","o":"Allegorie","c":"LXXXV","str":58,"ni":"cervi","nc":"Jeleni","it":["Questo, quando si sente morso dal ragno detto falange, mangia de’ granchi, e si libera di tal veneno."],"cs":["Ten, když cítí, že ho kousl pavouk zvaný falanga, jí kraby a zbaví se toho jedu."],"ref":null,"ca":[]},{"id":"s132","o":"Allegorie","c":"LXXXVI","str":59,"ni":"luserte","nc":"Ještěrky","it":["Questa, quando combatte colle serpe, mangia la cicerbita, e son libere."],"cs":["Ta, když bojuje s hady, jí mléč, a jsou osvobozeny."],"ref":null,"ca":[]},{"id":"s133","o":"Allegorie","c":"LXXXVII","str":59,"ni":"rondine","nc":"Vlaštovka","it":["Questa rende il vedere alli inorbiti figlioli col sugo della celidonia."],"cs":["Ta vrací zrak oslepeným mláďatům šťávou vlaštovičníku."],"ref":null,"ca":[]},{"id":"s134","o":"Allegorie","c":"LXXXVIII","str":59,"ni":"bellola","nc":"Lasice","it":["Questa, quando caccia ai ratti, mangia prima della ruta."],"cs":["Ta, když loví krysy, sní nejprve trochu routy."],"ref":null,"ca":[]},{"id":"s135","o":"Allegorie","c":"LXXXIX","str":59,"ni":"cinghiale","nc":"Kanec","it":["Questo medica i sua mali mangiando della edera."],"cs":["Ten léčí své neduhy tím, že jí břečťan."],"ref":null,"ca":[]},{"id":"s136","o":"Allegorie","c":"XC","str":59,"ni":"serpe","nc":"Had","it":["Questa, quando si voi rennovare, gitta il vecchio scoglio, comenciandosi dalla testa; mutasi ’n un dì e una nocte."],"cs":["Ten, když se chce obnovit, svléká starou kůži, počínaje od hlavy; promění se za jeden den a jednu noc."],"ref":null,"ca":[]},{"id":"s137","o":"Allegorie","c":"XCI","str":59,"ni":"pantera","nc":"Pantera","it":["Questa, poi che le sono uscite le ’nteriora, ancora combatte coi cani e cacciatori."],"cs":["Ta, i když jí vyhřezly vnitřnosti, ještě bojuje se psy a lovci."],"ref":{"s":"H","l":17,"st":"v","z":true,"raw":"H. 17 v"},"ca":[]},{"id":"s138","o":"Allegorie","c":"XCII","str":60,"ni":"camaleone","nc":"Chameleon","it":["Questo piglia sempre il colore della cosa, dove si posa, onde, insieme colle frondi dove si posano, spesso dalli elefanti son divorati."],"cs":["Ten přijímá vždy barvu věci, na níž sedí; a proto bývají chameleoni často pozřeni slony spolu s listím, na němž sedí."],"ref":null,"ca":[]},{"id":"s139","o":"Allegorie","c":"XCIII","str":60,"ni":"corbo","nc":"Havran","it":["Questo, quando ha ucciso il camaleone, si purga coll’alloro."],"cs":["Ten, když zabije chameleona, pročistí se vavřínem."],"ref":{"s":"H","l":17,"st":"v","z":true,"raw":"H. 17 v"},"ca":[]},{"id":"s140","o":"Allegorie","c":"XCIV","str":60,"ni":"magnanimità","nc":"Velkomyslnost","it":["Il falcone non piglia se non uccelli grossi, e prima more che mangiare carne di non bono odore."],"cs":["Sokol neloví než velké ptáky a raději zemře, než by jedl maso nepěkného pachu."],"ref":{"s":"H","l":17,"st":"v","z":true,"raw":"H. 17 v"},"ca":[]},{"id":"s141","o":"Allegorie","c":"XCV","str":60,"ni":"gru","nc":"Jeřáb","it":["Le gru, acciò che ’l loro re non perisca per cattiva guardia, la notte li stanno dintorno con pietre in piè.","Amor, timor e reverenza: questo scuvi in tre sassi di gru."],"cs":["Jeřábi, aby jejich král nezahynul pro špatnou stráž, stojí v noci kolem něho s kameny v noze.","Láska, bázeň a úcta: to vytesej do tří kamenů jeřábů."],"ref":{"s":"H","l":17,"st":"v","z":false,"raw":"H. 17 v"},"ca":[]},{"id":"s142","o":"Allegorie","c":"XCVI","str":60,"ni":"cardellino","nc":"Stehlík","it":["Il calderugio dà il tortomalio a’ figlioli ingabbiati. — Prima morte che perdere libertà!"],"cs":["Stehlík dává svým mláďatům v kleci pryšec. – Raději smrt nežli ztratit svobodu!"],"ref":null,"ca":[]},{"id":"s143","o":"Allegorie","c":"XCVII","str":61,"ni":"dell’antivedere","nc":"O prozíravosti","it":["Il gallo non canta, se prima tre volta non batte l’ali; il papagallo, nel mutarsi pe’ rami, non mette i piè, dove non ha prima messo il becco."],"cs":["Kohout nezazpívá, dokud třikrát nezamává křídly; papoušek při přecházení po větvích nepostaví nohu tam, kam předtím nepostavil zobák."],"ref":{"s":"H","l":98,"st":"r","z":false,"raw":"H. 98 r"},"ca":[]},{"id":"s144","o":"Allegorie","c":"XCVIII","str":61,"ni":"per ben fare","nc":"Za dobré skutky","it":["Per il ramo della noce, — che solo è percosso e battuto, quand’e’ ha condotto a perfezione li sua frutti, — si dinota quelli, che, mediante il fine delle loro famose opere, son percossi dalla invidia per diversi modi."],"cs":["Ořechovou větví – kterou tlučou a mlátí jen tehdy, když dovedla své plody k dokonalosti – se označují ti, kdo jsou pro výsledek svých slavných děl rozličně stíháni závistí."],"ref":{"s":"H","l":98,"st":"v","z":false,"raw":"H. 98 v"},"ca":[]},{"id":"s145","o":"Allegorie","c":"XCIX","str":61,"ni":"sul medesimo soggetto","nc":"Na totéž téma","it":["Per lo spino, insiditoli sopra boni frutti, significa quello, che per se non era disposto a virtù, ma mediante l’aiuto del precettore dà di sè utilissime virtù."],"cs":["Trnka, do níž byly naroubovány dobré plody, znamená toho, kdo sám od sebe nebyl ke ctnosti nakloněn, ale s pomocí učitele ze sebe vydává nanejvýš užitečné ctnosti."],"ref":{"s":"G","l":88,"st":"v","z":true,"raw":"G. 88 v"},"ca":[]},{"id":"s146","o":"Allegorie","c":"C","str":61,"ni":"del lino","nc":"O lnu","it":["Il lino è dedicato a morte e corruzione de’ mortali: a morte pe’ lacciuoli delli uccelli, animali e pesci; a corruzione per le tele line dove s’involgano i morti, che si sotterrano, i quali si corrompono in tali tele. E ancora esso lino non si spicca dal suo festuco, se esso non comincia a macerarsi o corrompersi, e questo e quello col quale si deve incoronare e ornare li uffizî funerali."],"cs":["Len je zasvěcen smrti a rozkladu smrtelníků: smrti pro osidla na ptáky, zvířata a ryby; rozkladu pro lněná plátna, do nichž se balí mrtví, kteří se pohřbívají a v těch plátnech se rozkládají. A dále se ten len neoddělí od svého stébla, nezačne-li se máčet nebo rozkládat; a to je ten, jímž se mají věnčit a zdobit pohřební obřady."],"ref":{"s":"G","l":88,"st":"v","z":false,"raw":"G. 88 v"},"ca":[]},{"id":"s147","o":"Allegorie","c":"CI","str":62,"ni":"frammento","nc":"Zlomek","it":["Per il pannolino, che si tien colla mano nel corso dell’acqua corrente, nella quale acqua il panno lascia tutte le sue brutture, significa questo ec."],"cs":["Lněnou tkaninou, kterou držíme rukou v proudu tekoucí vody, v níž ta tkanina zanechá všechnu svou špínu, se označuje toto atd."],"ref":{"s":"G","l":89,"st":"r","z":false,"raw":"G. 89 r"},"ca":[]},{"id":"s148","o":"Pensieri sulla scienza","c":"I","str":65,"ni":"la teoria e la pratica","nc":"Teorie a praxe","it":["Bisognati descrivere la teorica e poi la pratica."],"cs":["Je ti třeba popsat teorii a potom praxi."],"ref":{"s":"R","l":110,"st":"","z":false,"raw":"R. 110"},"ca":[],"rr":"Br. M. 171 a"},{"id":"s149","o":"Pensieri sulla scienza","c":"I","str":65,"ni":"dell’error di quelli, che usano la pratica sanza scienza","nc":"O omylu těch, kdo provozují praxi bez vědy","it":["Quelli, che s’innamoran di pratica sanza scienza, son come ’l nocchiere, ch’entra in navilio sanza timone o bussola, che mai ha certezza dove si vada.","Sempre la pratica dev’esser edificata sopra la bona teorica; della quale la Prospettiva è guida e porta, e, sanza questa, nulla si fa bene ne’ casi di pittura."],"cs":["Ti, kdo se zamilují do praxe bez vědy, jsou jako kormidelník, který vstoupí na loď bez kormidla či kompasu a nikdy neví jistě, kam pluje.","Praxe musí být vždy vystavěna na dobré teorii; jejím průvodcem a branou je perspektiva, a bez ní se ve věcech malířství nic nedaří dobře."],"ref":{"s":"G","l":8,"st":"r","z":false,"raw":"G. 8 r"},"ca":[]},{"id":"s150","o":"Pensieri sulla scienza","c":"III","str":65,"ni":"paragone del pratico","nc":"Přirovnání praktika","it":["Il pittore, che ritrae per pratica e giudizio d’occhio, sanza ragione, è come lo specchio, che in sè imita tutte le a sè contrapposte cose, sanza cognizione d’esse."],"cs":["Malíř, který kreslí podle zvyku a úsudku oka, bez rozumu, je jako zrcadlo, které v sobě napodobuje všechny věci před sebou postavené, aniž je poznává."],"ref":{"s":"C.A","l":76,"st":"r","z":false,"raw":"C. A. 76 r"},"ca":[412,414]},{"id":"s151","o":"Pensieri sulla scienza","c":"IV","str":66,"ni":"precedenza della teorica alla pratica","nc":"Přednost teorie před praxí","it":["La scienza è il capitano, e la pratica sono i soldati."],"cs":["Věda je vojevůdce a praxe jsou vojáci."],"ref":{"s":"I","l":130,"st":"r","z":false,"raw":"I. 130 r"},"ca":[]},{"id":"s152","o":"Pensieri sulla scienza","c":"V","str":66,"ni":"sul medesimo soggetto","nc":"Na totéž téma","it":["Studia prima la scienza, e poi seguita la pratica, nata da essa scienza."],"cs":["Studuj nejprve vědu a potom pokračuj v praxi, zrozené z té vědy."],"ref":{"s":"Lu","l":405,"st":"","z":false,"raw":"Lu. 405"},"ca":[]},{"id":"s153","o":"Pensieri sulla scienza","c":"VI","str":66,"ni":"consiglio al pittore","nc":"Rada malíři","it":["E tu, pittore, che desideri la grandissima pratica, hai da intendere, che, se tu non la fai sopra bon fondamento delle cose naturali, tu farai opere assai con poco onore e men guadagno; e se la farai buona, l’opere tue saranno molte e bone, con grand’onor tuo e molta utilità."],"cs":["A ty, malíři, který toužíš po převeliké zručnosti, musíš pochopit, že nezakládáš-li ji na dobrém základě přírodních věcí, vytvoříš mnoho děl s malou ctí a ještě menším ziskem; a učiníš-li ji dobrou, budou tvá díla četná a dobrá, k tvé veliké cti a s velikým užitkem."],"ref":{"s":"Lu","l":54,"st":"","z":true,"raw":"Lu. 54"},"ca":[]},{"id":"s154","o":"Pensieri sulla scienza","c":"VII","str":66,"ni":"sul medesimo soggetto","nc":"Na totéž téma","it":["Dice qui l’avversario, che non vuole tanta scienza, che gli basta la pratica del ritrarre le cose naturali. Al quale si risponde, che di nessuna cosa è, che più c’inganni, che fidarsi del nostro giudicio, sanz’altra ragione, come prova sempre la sperienza, nemica degli Alchimisti, Negromanti e altri semplici ingegni."],"cs":["Odpůrce zde říká, že nechce tolik vědy, že mu postačí praxe v kreslení přírodních věcí. Tomu se odpovídá, že není věci, která by nás víc klamala, než spoléhat na svůj úsudek bez dalšího důvodu, jak vždy dokazuje zkušenost, nepřítelkyně alchymistů, nekromantů a jiných prostých duchů."],"ref":{"s":"Lu","l":54,"st":"","z":false,"raw":"Lu. 54"},"ca":[]},{"id":"s155","o":"Pensieri sulla scienza","c":"VIII","str":67,"ni":"sul fatto anatomico dello sviluppo grande del cranio nel fanciullo","nc":"O anatomickém faktu velikého vývoje lebky u dítěte","it":["La natura ci compone prima la grandezza della casa dello intelletto, che quella delli spiriti vitali."],"cs":["Příroda v nás nejprve vystaví velikost domu rozumu, a teprve potom domu duchů životních."],"ref":{"s":"Ash.I","l":7,"st":"r","z":false,"raw":"Ash. I. 7 r"},"ca":[]},{"id":"s156","o":"Pensieri sulla scienza","c":"IX","str":67,"ni":"diversità della teorica dalla pratica","nc":"Rozdíl mezi teorií a praxí","it":["Dove la scienza de’ pesi è ingannata dalla pratica.","La scienza de’ pesi ingannata dalla sua pratica, e, in molte parte, essa non s’accorda con essa scienza, nè è possibile accordarla; e questo nasce dalli poli delle bilancie, mediante li quali di tali pesi si fa scienza, li quali poli, appresso li antichi filosofi, furo li poli posti di natura di linia matematica, e in alcun loco in punti matematici, li quali punti e linie sono incorporei: e la pratica li pone corporei, perchè così comanda necessità, volendo sostenere il peso d’esse bilancie, insieme colli pesi sopra di lor si giudicano.","Ho trovato essi antichi essersi ingannati in esso giudizio de’ pesi, e questo inganno è nato perchè in gran parte della loro scienza hanno usati poli corporei, e in gran parte poli matematici, cioè mentali, overo incorporei."],"cs":["Kde je věda o vahách klamána praxí.","Věda o vahách je klamána svou praxí a v mnoha částech se s tou vědou neshoduje, ani ji s ní nelze uvést v soulad; a to pochází z os vah, pomocí nichž se o takových vahách buduje věda; ty osy byly u starých filozofů kladeny jako osy povahy matematické přímky a na některých místech jako matematické body, a tyto body a přímky jsou netělesné; praxe je však klade jako tělesné, protože to tak velí nutnost, má-li nést váhu těch vah spolu se závažími, která se na nich posuzují.","Shledal jsem, že se ti staří v tomto posuzování vah mýlili, a ten omyl vznikl proto, že ve velké části své vědy užívali os tělesných a ve velké části os matematických, totiž myšlených neboli netělesných."],"ref":{"s":"C.A","l":93,"st":"v","z":false,"raw":"C. A. 93 v"},"ca":[510,512]},{"id":"s157","o":"Pensieri sulla scienza","c":"X","str":68,"ni":"sterilità delle scienze senza applicazione pratica","nc":"Neplodnost věd bez praktického užití","it":["Tutte le scienze, che finiscono in parole, hanno sì presto morte, come vita, eccetto la sua parte manuale, cioè lo scrivere, ch’è parte meccanica."],"cs":["Všechny vědy, které končí ve slovech, umírají stejně rychle, jako ožívají, kromě své rukodělné části, totiž psaní, které je částí mechanickou."],"ref":{"s":"Lu","l":9,"st":"","z":false,"raw":"Lu. 9"},"ca":[]},{"id":"s158","o":"Pensieri sulla scienza","c":"XI","str":68,"ni":"sul medesimo soggetto","nc":"Na totéž téma","it":["Fuggi quello studio, del quale la resultante opera muore insieme coll’operante d’essa."],"cs":["Vyhýbej se takovému studiu, jehož výsledné dílo umírá spolu s tím, kdo je vytvořil."],"ref":{"s":"R","l":1169,"st":"","z":false,"raw":"R. 1169"},"ca":[],"rr":"S. K. M. III. 36 b"},{"id":"s159","o":"Pensieri sulla scienza","c":"XII","str":68,"ni":"ricordi di leonardo","nc":"Leonardovy poznámky","it":["Quando tu metti insieme la Scienza de’ moti dell’acqua, ricordati di mettere, di sotto a ciascuna proposizione, li sua giovamenti, a ciò che tale scienza non sia inutile."],"cs":["Až budeš sestavovat Vědu o pohybech vody, nezapomeň pod každou poučku uvést její užitky, aby ta věda nebyla neužitečná."],"ref":{"s":"F","l":2,"st":"v","z":false,"raw":"F. 2 v"},"ca":[]},{"id":"s160","o":"Pensieri sulla scienza","c":"XIII","str":69,"ni":"la distribuzione dei suoi trattati","nc":"Rozvržení jeho pojednání","it":["Da profondare un canale: fa questo nel libro De’ giovamenti, e, nel provarli, allega le proposizioni provate; e questo è il vero ordine, perchè, se tu volessi mostrare il giovamento a ogni proposizione, ti bisognerebbe ancora fare novi strumenti per provar tale utilità, e così confonderesti l’ordine de’ quaranta libri, e così l’ordine delle figurazioni; cioè avresti a mischiare pratica con teorica, che sarebbe cosa confusa e interrotta."],"cs":["Jak prohloubit kanál: to učiň v knize O užitcích, a při jejich dokazování se odvolávej na dokázané poučky; a to je pravý pořádek, neboť kdybys chtěl ukazovat užitek u každé poučky, musel bys ještě dělat nové nástroje, abys ten užitek dokázal, a tak bys zmátl pořádek čtyřiceti knih i pořádek vyobrazení; totiž musel bys míchat praxi s teorií, a to by byla věc zmatená a přerývaná."],"ref":{"s":"F","l":23,"st":"r","z":false,"raw":"F. 23 r"},"ca":[]},{"id":"s161","o":"Pensieri sulla scienza","c":"XIV","str":69,"ni":"valore intrinseco del sapere","nc":"Vnitřní hodnota vědění","it":["L’acquisto di qualunque cognizione è sempre utile allo intelletto, perchè potrà scacciare da sè le cose inutili, e riservare le buone. Perchè nessuna cosa si può amare nè odiare, se prima non si ha cognizicn di quella."],"cs":["Nabytí jakéhokoli poznání je rozumu vždy užitečné, neboť bude moci zapudit věci neužitečné a podržet dobré. Neboť žádnou věc nelze milovat ani nenávidět, nemáme-li o ní nejprve poznání."],"ref":{"s":"C.A","l":223,"st":"r","z":false,"raw":"G. A. 223 r"},"ca":[1202,1204]},{"id":"s162","o":"Pensieri sulla scienza","c":"XV","str":69,"ni":"naturale istinto dell’uomo al sapere","nc":"Přirozený pud člověka k vědění","it":["Naturalmente li omini boni desiderano sapere."],"cs":["Dobří lidé přirozeně touží vědět."],"ref":{"s":"C.A","l":119,"st":"r","z":false,"raw":"C. A. 119 r"},"ca":[652,654]},{"id":"s163","o":"Pensieri sulla scienza","c":"XVI","str":70,"ni":"piacere, che nasce dalla contemplazione della natura","nc":"Radost, která pramení z rozjímání o přírodě","it":["Alli ambiziosi, che non si contentano del benefizio della vita, nè della bellezza del mondo, è dato per penitenza che lor medesimi strazino essa vita, e che non possegghino la utilità e bellezza del mondo."],"cs":["Ctižádostivým, kteří se nespokojí s darem života ani s krásou světa, je uloženo za pokání, aby sami ten život trýznili a aby neměli užitek a krásu světa."],"ref":{"s":"C.A","l":91,"st":"v","z":false,"raw":"C. A. 91 v"},"ca":[496,498]},{"id":"s164","o":"Pensieri sulla scienza","c":"XVII","str":70,"ni":"leonardo contro gli sprezzatori delle sue opere.95","nc":"Leonardo proti těm, kdo pohrdají jeho díly","it":["So che molti diranno questa essere opra inutile, e questi fieno quelli, de’ quali Deometro disse, non faceva conto più del vento, il quale nella lor bocca causava le parole, che del vento, ch’usciva dalla parte di sotto; uomini quali hanno solamente desiderio di corporai ricchezze, diletto, e interamente privati di quello della sapienza, cibo e veramente sicura ricchezza dell’anima: perchè quant’è più degna l’anima che ’l corpo, tanto più degne fien le ricchezze dell’anima, che dei corpo.","E spesso, quando vedo alcun di questi pigliare essa opera in mano, dubito non sì, come la scimmia, se ’l mettine al naso, e che mi domandi s’è cosa mangiativa."],"cs":["Vím, že mnozí řeknou, že toto dílo je neužitečné, a to budou ti, o nichž Démétrios řekl, že nedbá víc o vítr, který v jejich ústech působil slova, než o vítr, který vycházel spodní částí; lidé, kteří touží jen po tělesném bohatství a rozkoši a jsou zcela zbaveni touhy po moudrosti, pokrmu a vpravdě jistém bohatství duše: neboť oč je duše vznešenější než tělo, o to vznešenější budou bohatství duše než bohatství těla.","A často, když vidím někoho z nich brát to dílo do ruky, bojím se, aby si je jako opice nestrčil k nosu a nezeptal se mě, je-li to něco k jídlu."],"ref":{"s":"C.A","l":119,"st":"r","z":false,"raw":"C. A. 119 r"},"ca":[652,654]},{"id":"s165","o":"Pensieri sulla scienza","c":"XVIII","str":71,"ni":"contro gli sprezzatori della scienza","nc":"Proti těm, kdo pohrdají vědou","it":["Demetrio solea dire, non essere differenza dalle parole e voce dell’imperiti ignoranti, che sia da soni o strepiti causati dal ventre, ripieno di superfluo vento. E questo non sanza ragion dicea, imperocchè lui non reputava esser differenza da qual parte costoro inandassino fuora la voce, o da la parte inferiore o da la bocca, che l’una e l’altra eran di pari vaiimento e sustanzia."],"cs":["Démétrios říkával, že není rozdílu mezi slovy a hlasem nevzdělaných nevědomců a zvuky či hřmotem způsobeným břichem plným přebytečných větrů. A neříkal to bez důvodu, neboť nepokládal za rozdíl, kterou částí takoví lidé vypouštějí hlas, zda spodní částí či ústy, neboť jedno i druhé má stejnou cenu i podstatu."],"ref":{"s":"T","l":41,"st":"v","z":false,"raw":"T. 41 v"},"ca":[]},{"id":"s166","o":"Pensieri sulla scienza","c":"XIX","str":71,"ni":"riflessione sulla struttura del corpo umano","nc":"Úvaha o stavbě lidského těla","it":["Non mi pare, che li omini grossi e di tristi costumi e di poco discorso meritino sì bello strumento, nè tanta varietà di macchinamenti, quanto li omini speculativi e di gran discorsi, ma solo un sacco dove si riceva il cibo e donde esso esca; che, invero, altro che un transito di cibo non son da essere giudicati, perchè niente mi pare che essi partecipino di spece umana, altro che la voce e la figura; e tutto il resto è assai manco che bestia."],"cs":["Nezdá se mi, že by lidé hrubí, zlých mravů a chabého rozumu zasluhovali tak krásný nástroj a tolikerou rozmanitost ústrojí jako lidé přemýšliví a velkého rozumu, nýbrž jen pytel, do něhož se přijímá potrava a z něhož vychází; neboť vpravdě je nelze pokládat za nic jiného než za průchod potravy, protože se mi zdá, že z lidského rodu nemají nic než hlas a postavu; a všechno ostatní je mnohem méně než zvíře."],"ref":{"s":"R","l":1173,"st":"","z":false,"raw":"R. 1173"},"ca":[],"rr":"Tr. 32"},{"id":"s167","o":"Pensieri sulla scienza","c":"XX","str":72,"ni":"contro gli uomini, che mirano solo alla vita materiale","nc":"Proti lidem, kteří hledí jen k hmotnému životu","it":["Ecci alcuni, che non altramenti che transito di cibo e aumentatori di sterco e riempitori di destri chiamarsi debbono; perchè per loro non altro nel mondo, o pure alcuna virtù in opera si mette, perchè di loro altro che pieni destri non resta."],"cs":["Jsou někteří, kteří by se neměli nazývat jinak než průchodem potravy, rozmnožovateli hnoje a plniteli záchodů; neboť skrze ně se ve světě nic jiného, ba ani žádná ctnost neuvádí v čin, protože po nich nezůstává nic než plné záchody."],"ref":{"s":"R","l":1179,"st":"","z":false,"raw":"R. 1179"},"ca":[],"rr":"S. K. M. III. 17 a"},{"id":"s168","o":"Pensieri sulla scienza","c":"XXI","str":72,"ni":"i due campi della conoscenza","nc":"Dvě pole poznání","it":["La cognizion del tempo preterito e del sito della terra è ornamento e cibo delle menti umane."],"cs":["Znalost minulého času a polohy země je ozdobou a pokrmem lidských myslí."],"ref":{"s":"C.A","l":365,"st":"v","z":false,"raw":"C. A. 365 v"},"ca":[2035,2037,2038]},{"id":"s169","o":"Pensieri sulla scienza","c":"XXII","str":72,"ni":"il supremo bene è il sapere","nc":"Nejvyšším dobrem je vědění","it":["Cornelio Celso: «Il sommo bene è la sapienza, il sommo male è ’l dolore del corpo: imperò che, essendo noi composti di due cose, cioè d’anima e di corpo, delle quali la prima è migliore, la peggiore è il corpo. La sapienza è della miglior parte, il sommo male è della peggior parte e pessima. Ottima cosa è nell’animo la sapienza, così è pessima cosa nel corpo il dolore. Adunque, sì come il sommo male è ’l corporal dolore, così la sapienza è dell’anima il sommo bene, cioè dell’uom saggio, e niuna altra cosa è da a questa comparare.»"],"cs":["Cornelius Celsus: „Nejvyšším dobrem je moudrost, nejvyšším zlem je bolest těla: neboť jsme složeni ze dvou věcí, totiž z duše a z těla, z nichž první je lepší a horší je tělo. Moudrost náleží lepší části, nejvyšší zlo náleží části horší a nejhorší. Nejlepší věcí v duši je moudrost, tak jako nejhorší věcí v těle je bolest. Tedy jako nejvyšším zlem je tělesná bolest, tak je moudrost nejvyšším dobrem duše, totiž muže moudrého, a nic jiného s ní nelze srovnávat.“"],"ref":{"s":"T","l":2,"st":"r","z":false,"raw":"T 2 r"},"ca":[]},{"id":"s170","o":"Pensieri sulla scienza","c":"XXIII","str":73,"ni":"valore del sapere nella vita","nc":"Cena vědění v životě","it":["Acquista cosa nella tua gioventù, che ristori il danno della tua vecchiezza. E se tu intendi la vecchiezza aver per suo cibo la sapienza, adoprati in tal modo in gioventù, che a tal vecchiezza non manchi il nutrimento."],"cs":["Nabuď v mládí něco, co ti vynahradí škodu tvého stáří. A chápeš-li, že stáří má za svůj pokrm moudrost, přičiň se v mládí tak, aby takovému stáří nechyběla výživa."],"ref":{"s":"A","l":112,"st":"r","z":true,"raw":"A. 112 r"},"ca":[]},{"id":"s171","o":"Pensieri sulla scienza","c":"XXIV","str":73,"ni":"glorificazione della scienza","nc":"Oslava vědy","it":["....Manca la fama del ricco ’nsieme co’ la sua vita, resta la fama del tesoro e non del tesaurizzante: e molto maggior gloria è quella della virtù de1 mortali, che quella delli loro tesori.","Quanti imperatori e quanti principi sono passati, che non ne resta alcuna memoria! e solo cercarono li stati e ricchezze, per lassare fama di loro.","Quanti furon quelli, che vissono in povertà di denari, per arricchire di virtù! e tanto è più riuscito tal desiderio al virtuoso, ch’al ricco, quanto la virtù eccede la ricchezza.","Non vedi tu, ch’il tesoro per sè non lauda il suo cumulatore, dopo la sua vita, come fa la scienza? la quale sempre è testimonia e tromba del suo creatore, perchè ella è figliola di chi la genera, e non figliastra, come la pecunia."],"cs":["....Sláva boháčova pomíjí spolu s jeho životem, zůstává sláva pokladu, a ne toho, kdo jej shromáždil; a mnohem větší je sláva ctnosti smrtelníků než sláva jejich pokladů.","Kolik císařů a kolik knížat odešlo, a nezůstala po nich žádná památka! A hledali jen panství a bohatství, aby po sobě zanechali slávu.","Kolik jich bylo, kteří žili v nouzi o peníze, aby zbohatli ctností! A té touze se ctnostnému dařilo o tolik lépe než boháčovi, oč ctnost převyšuje bohatství.","Nevidíš, že poklad sám o sobě nechválí toho, kdo jej nahromadil, po jeho smrti, jako to činí věda? Ta je vždy svědkyní a polnicí svého tvůrce, neboť je dcerou toho, kdo ji plodí, a ne nevlastní dcerou jako peníze."],"ref":{"s":"Lu","l":65,"st":"","z":false,"raw":"Lu. 65"},"ca":[]},{"id":"s172","o":"Pensieri sulla scienza","c":"XXV","str":74,"ni":"come per tutti viaggi si po’ imparare","nc":"Jak se lze učit na všech cestách","it":["Questa benigna natura ne provvede in modo, che per tutto il mondo tu trovi dove imitare."],"cs":["Tato dobrotivá příroda se o nás stará tak, že po celém světě nalézáš, co napodobovat."],"ref":{"s":"Ash.I","l":31,"st":"v","z":false,"raw":"Ash. I. 31 v"},"ca":[]},{"id":"s173","o":"Pensieri sulla scienza","c":"XXVI","str":74,"ni":"l’inerzia guasta la sottilità dell’ingegno","nc":"Nečinnost kazí bystrost ducha","it":["Siccome il ferro s’arrugginisce sanza esercizio, e l’acqua si putrefà, e nel freddo s’agghiaccia; così l’ingegno, sanza esercizio, si guasta."],"cs":["Jako železo bez užívání rezaví a voda hnije a v mrazu zamrzá, tak se bez cvičení kazí i duch."],"ref":{"s":"C.A","l":284,"st":"v","z":false,"raw":"C. A. 284 v"},"ca":[1545]},{"id":"s174","o":"Pensieri sulla scienza","c":"XXVII","str":74,"ni":"lo studio senza voglia non da alcun frutto","nc":"Studium bez chuti nepřináší žádný užitek","it":["Siccome mangiare sanza voglia si converte in fastidioso notrimento, così lo studio sanza desiderio guasta la memoria, col non ritenere cosa, ch’ella pigli."],"cs":["Jako jídlo bez chuti se mění v protivnou výživu, tak studium bez touhy kazí paměť, neboť neudrží nic, co přijme."],"ref":{"s":"Ash.I","l":34,"st":"r","z":true,"raw":"Ash. I. 34 r"},"ca":[]},{"id":"s175","o":"Pensieri sulla scienza","c":"XXVIII","str":74,"ni":"sul medesimo soggetto","nc":"Na totéž téma","it":["Siccome il mangiare sanza voglia fia dannoso alla salute, così lo studio sanza desiderio guasta la memoria, e non ritien cosa, ch’ella pigli."],"cs":["Jako jídlo bez chuti škodí zdraví, tak studium bez touhy kazí paměť a ta neudrží nic, co přijme."],"ref":null,"ca":[]},{"id":"s176","o":"Pensieri sulla scienza","c":"XXIX","str":75,"ni":"per giudicare l’opera propria bisogna riguardarla dopo lungo in-tervallo","nc":"Odstup od vlastního díla","it":["Sì come il corpo, con gran tardità fatta nella lunghezza del suo moto contrario, torna con più via, dà poi maggior colpo, — e quello, che è di continui e brievi moti, son di piccola valetudine; così lo studio su una medesima materia, fatto con lunghi intervalli di tempo, il giudizio s’è fatto più perfetto, e meglio giudica il suo errore. E ’l simile fa l’occhio del pittore col discostarsi dalla sua pittura."],"cs":["Jako těleso, které se s velikou pozvolností napřáhlo daleko nazpět svým opačným pohybem, se vrací s větším rozběhem a pak udeří silněji – kdežto to, které koná ustavičné a krátké pohyby, má malou sílu –, tak i při studiu téže látky, konaném s dlouhými časovými přestávkami, je úsudek dokonalejší a lépe posoudí svůj omyl. A totéž činí oko malíře, když od svého obrazu poodstoupí."],"ref":{"s":"C.A","l":122,"st":"v","z":false,"raw":"C. A. 122 v"},"ca":[674,676]},{"id":"s177","o":"Pensieri sulla scienza","c":"XXX","str":75,"ni":"antiquitas sæculi iuventus mundi","nc":"Antiquitas saeculi iuventus mundi","it":["La verità sola fu figliola del tempo."],"cs":["Jedině pravda byla dcerou času."],"ref":{"s":"M","l":58,"st":"v","z":false,"raw":"M. 58 v"},"ca":[]},{"id":"s178","o":"Pensieri sulla scienza","c":"XXXI","str":75,"ni":"glorificazione della verità","nc":"Oslava pravdy","it":["Ed è di tanto vilipendio la bugia, che s’ella dicessi ben gran cose di Dio, ella to’ di grazia a sua deità; ed è di tanta eccellenza la verità, che s’ella laudassi cose minime, elle si fanno nobili.","Sanza dubbio, tal proporzione è dalla verità alla bugia, qual’è da la luce alle tenebre; ed è essa verità in se di tanta eccellenzia, che ancora ch’ella s’astenda sopra umili e basse materie, sanza comparazione ell’eccede le incertezze e bugie estese sopra li magni e altissimi discorsi; perchè la mente nostra, ancora ch’ell’abbia la bugia pe ’l quinto elemento, non rosta però che la verità delle cose non sia di sommo notrimento delli intelletti fini, ma non de’ vagabondi ingegni. Ma tu che vivi di sogni, ti piace più le ragion sofìstiche e barerie de’ palari nelle cose grandi e incerte, che delle certe naturali e non di tanta altura!"],"cs":["A lež je tak opovrženíhodná, že i kdyby o Bohu vypovídala velké věci, ubírá jeho božství na milosti; a pravda je tak vznešená, že chválí-li sebenepatrnější věci, stávají se ušlechtilými.","Bezpochyby je mezi pravdou a lží takový poměr jako mezi světlem a tmou; a ta pravda je sama v sobě tak vznešená, že i když se týká pokorných a nízkých látek, bez porovnání převyšuje nejistoty a lži rozprostřené nad velikými a nejvznešenějšími úvahami; neboť třebaže má naše mysl lež za pátý živel, přesto pravda věcí zůstává nejvyšším pokrmem jemných rozumů, ne však těkavých duchů. Ale tobě, který žiješ ze snů, se víc líbí sofistické důvody a šalby žvanilů ve věcech velikých a nejistých než věci jisté, přirozené a ne tak vysoké!"],"ref":{"s":"V.U","l":12,"st":"r","z":false,"raw":"V. U. 12 r"},"ca":[]},{"id":"s179","o":"Pensieri sulla scienza","c":"XXXII","str":76,"ni":"conseguenza delle opposizioni alla verità","nc":"Důsledek odporu proti pravdě","it":["L’impedimenti della verità si convertono in penitenza."],"cs":["Překážky kladené pravdě se obracejí v pokání."],"ref":{"s":"C.A","l":118,"st":"r","z":false,"raw":"C. A. 118 r"},"ca":[648,650]},{"id":"s180","o":"Pensieri sulla scienza","c":"XXXIII","str":76,"ni":"definizione della scienza","nc":"Definice vědy","it":["Scienza è detto quel discorso mentale, il quale ha origine da’ suoi ultimi principii, (oltre) de’ quali in natura null’ altra cosa si può trovare, che sia parte d’essa scienza: come nella quantità continua, cioè la scienza di Geometria, la quale, cominciando dalla superfizie de’ corpi, si trova avere origine nella linea, termine di essa superfizie; e in questo non restiamo soddisfatti, perchè noi conosciamo la linea aver termine nel punto, e il punto esser quello, del quale null’altra cosa può essere minore.","Dunque il punto è il primo principio di Geometria, e niuna altra cosa può essere nè in natura, nè in mente umana, che possa dar principio al punto. Perchè se tu dirai, nel contatto fatto sopra una superfizie da un’ultima acuità della punta de lo stile, quello essere creazione del punto; questo non è vero, ma diremo, questo tale contatto essere una superfizie, che circonda il suo mezzo, e in esso mezzo è la residenza del punto. E tal punto non è della materia di essa superfizie, nè lui, nè tutti li punti dell’universo, sono in potenza, ancorchè sieno uniti — dato che si potessero unire — comporrebbono parte alcuna d’una superfizie. E dato, che tu ti immaginassi, un tutto essere composto da mille punti, qui dividendo alcuna parte da essa quantità de mille, si può dire molto bene, che tal parte sia equale al suo tutto; e questo si prova col zero, ovver nulla, cioè la decima figura de la Aritmetica, per la quale si figura un 0 per esso nullo, il quale, posto dopo la unità, il farà dire dieci, e, se porrai due dopo tale unità, dira’ cento, e così infinitamente crescerà sempre dieci volte il numero, dove esso s’aggiunga; e lui in sè non vale altro, che nulla, e tutti li nulli dell’universo sono eguali a un sol nulla, in quanto alla loro sustanzia e valetudine."],"cs":["Vědou se nazývá ta myšlenková úvaha, která má původ ve svých posledních počátcích, za nimiž nelze v přírodě nalézt nic jiného, co by bylo částí té vědy: jako u spojité veličiny, totiž ve vědě geometrii, která, počínajíc od povrchu těles, shledává, že má původ v čáře, hranici toho povrchu; a tím se nespokojujeme, neboť víme, že čára má hranici v bodě a že bod je to, menšího nad nějž nemůže být nic.","Bod je tedy prvním počátkem geometrie, a nic jiného nemůže být ani v přírodě, ani v lidské mysli, co by mohlo dát počátek bodu. Neboť řekneš-li, že dotyk, který na nějakém povrchu učiní poslední ostří hrotu rydla, je vytvořením bodu, není to pravda; řekneme spíše, že takový dotyk je povrch, který obklopuje svůj střed, a v tom středu je sídlo bodu. A takový bod není z hmoty toho povrchu, a ani on, ani všechny body vesmíru, i kdyby byly spojeny – za předpokladu, že by se daly spojit –, by v možnosti nesložily žádnou část povrchu. A představíš-li si, že nějaký celek je složen z tisíce bodů, a oddělíš-li tu nějakou část od toho množství tisíce, lze velmi dobře říci, že ta část je rovna svému celku; a to se dokazuje nulou neboli ničím, totiž desátou číslicí aritmetiky, kterou se pro to nic píše 0; ta, postavena za jedničku, způsobí, že řekneš deset, a postavíš-li dvě za tu jedničku, řekneš sto, a tak do nekonečna vždy desetkrát zvětší číslo, k němuž se přidá; a sama o sobě nemá jinou hodnotu než nic, a všechna nic vesmíru se rovnají jedinému nic, pokud jde o jejich podstatu a hodnotu."],"ref":{"s":"Lu","l":1,"st":"","z":false,"raw":"Lu. 1"},"ca":[]},{"id":"s181","o":"Pensieri sulla scienza","c":"XXXIV","str":78,"ni":"valore delle regole date da leonardo al pittore","nc":"Cena pravidel, která Leonardo dává malíři","it":["Queste regole sono da usare solamente per ripruova delle figure: imperocchè ogni omo, nella prima composizione, fa qualche errore, e chi non li conosce non li racconcia; onde tu, per conoscere li errori, riproverai l’opera tua, e, dove trovi detti errori, racconciali, e tieni a mente di mai piuùricaderci. Ma, se tu volessi adoperare le regole nel comporre, non verresti mai a capo, e faresti confusione nelle tue opere.","Queste regole fanno, che tu possiedi uno libero e bono giudizio; imperochè ’l bono giudizio nasce dal bene intendere, e il bene intendere diriva da ragione tratta da bone regole, e le bone regole sono figliole della bona sperienza, comune madre di tutte le scienze e arti.","Onde, avendo tu bene a mente i precetti delle mie regole, potrai, solamente coi racconcio giudizio, giudicare e conoscere ogni sproporzionata opera, così in prospettiva, come in figure o altre cose."],"cs":["Těchto pravidel je třeba užívat jen k přezkoušení postav; neboť každý člověk se při prvním komponování dopustí nějaké chyby, a kdo je nepozná, nenapraví je; proto ty, abys chyby poznal, přezkoušíš své dílo, a kde najdeš zmíněné chyby, naprav je a pamatuj si, abys do nich už nikdy znovu neupadl. Kdybys však chtěl pravidel užívat při komponování, nikdy bys nedošel konce a způsobil bys ve svých dílech zmatek.","Tato pravidla způsobí, že budeš mít svobodný a dobrý úsudek; neboť dobrý úsudek se rodí z dobrého porozumění, a dobré porozumění pochází z rozumu odvozeného z dobrých pravidel, a dobrá pravidla jsou dcerami dobré zkušenosti, společné matky všech věd a umění.","Budeš-li mít tedy dobře na paměti předpisy mých pravidel, budeš moci jen napraveným úsudkem posoudit a poznat každé nesouměrné dílo, ať v perspektivě, nebo v postavách či jiných věcech."],"ref":{"s":"C.A","l":218,"st":"v","z":false,"raw":"C. A. 218 v"},"ca":[1172,1174]},{"id":"s182","o":"Pensieri sulla scienza","c":"XXXV","str":79,"ni":"legge, che governa lo svolgimento storico della pittura e delle scienze","nc":"Zákon, jenž řídí dějinný vývoj malířství a věd","it":["Come la pittura va d’età in età declinando e perdendosi, quando i pittori non hanno per autore, che la fatta pittura.","Il pittore avrà la sua pittura di poca eccellenza, se quello piglia per autore l’altrui pitture, ma s’egli imparerà dalie cose naturali, farà bono frutto: come vedemo in ne’ pittori dopo i Romani, i quali sempre imitarono l’uno dall’altro, e di età in età sempre mandaro detta arte in declinazione. Dopo questi venne Giotti, fiorentino, il quale, nato in monti soletari, abitati solo da capre e simil bestie, questo, sendo volto dalla natura a simile arte, cominciò a disegnare su per li sassi li atti delle capre, de le quali lui era guidatore; e cosi cominciò a fare tutti li animali, che nel paese trovava: in tal modo, che questo, dopo molto studio, avanzò non che i maestri della sua età, ma tutti quelli di moiti secoli passati. Dopo questo l'arte ricade, perchè tutti imitavano le fatte pitture, e cosi di secolo in secolo andò declinando; insino a tanto che Tomaso fiorentino, scognominato Masaccio, mostrò con opra perfetta, come quegli, che pigliavano per autore altro, che la natura, maestra de’ maestri, s'affaticavano invano.","Così voglio dire di queste cose matematiche, che quegli, che solamente studiano li autori e non l’opre di natura, son per arte nipoti, non figlioli d’essa natura, maestra de’ boni autori. - Odi somma stoltizia di quelli, i quali biasimano coloro che ’mparano da la natura, lasciando stare li autori, discepoli d’essa natura!"],"cs":["Jak malířství od věku k věku upadá a ztrácí se, když malíři nemají za vzor nic jiného než již hotové malby.","Malíř bude mít svou malbu málo znamenitou, bude-li brát za vzor cizí malby; bude-li se však učit od přírodních věcí, přinese dobré ovoce; jak vidíme u malířů po Římanech, kteří stále napodobovali jeden druhého a od věku k věku tak to umění stále přiváděli k úpadku. Po nich přišel Giotto, Florenťan, který, narozen v osamělých horách obývaných jen kozami a podobnou zvěří, když jej příroda obrátila k tomuto umění, počal kreslit na skalách pohyby koz, jejichž byl pastýřem; a tak počal kreslit všechna zvířata, která v kraji nalézal; takže po mnohém studiu předčil nejen mistry svého věku, ale všechny z mnoha minulých století. Po něm umění opět upadlo, protože všichni napodobovali hotové malby, a tak od století ke století upadalo; až Tommaso Florenťan, přezdívaný Masaccio, dokonalým dílem ukázal, že ti, kdo brali za vzor něco jiného než přírodu, mistryni mistrů, se namáhali marně.","Tak chci říci i o těchto věcech matematických, že ti, kdo studují jen autory a ne díla přírody, jsou v umění vnuky, a ne dětmi té přírody, mistryně dobrých autorů. – Slyš nejvyšší pošetilost těch, kdo kárají ty, kteří se učí od přírody a nechávají stranou autory, žáky té přírody!"],"ref":{"s":"C.A","l":141,"st":"r","z":false,"raw":"C. A. 141 r"},"ca":[770,772,774]},{"id":"s183","o":"Pensieri sulla scienza","c":"XXXVI","str":80,"ni":"contro il principio di autorità nella scienza","nc":"Proti principu autority ve vědě","it":["Molti mi crederanno ragionevolmente potere riprendere, allegando le mie prove esser contro all’autorità d’alquanti omini di gran reverenza, presso de’ loro inesperti judizi; non considerando le mie cose essere nate sotto la semplice e mera sperienza, la quale è maestra vera."],"cs":["Mnozí budou věřit, že mě mohou po právu kárat, uvádějíce, že mé důkazy jsou proti autoritě několika mužů velké vážnosti v očích jejich nezkušených soudů; neuvažují, že mé věci se zrodily z prosté a čiré zkušenosti, která je pravou mistryní."],"ref":{"s":"C.A","l":119,"st":"v","z":false,"raw":"C. A. 119 v"},"ca":[653,655]},{"id":"s184","o":"Pensieri sulla scienza","c":"XXXVII","str":81,"ni":"il seguace della natura e il seguace della autorità degli scrittori","nc":"Následovník přírody a následovník autority spisovatelů","it":["Se bene, come loro, non sapessi allegare gli autori, molto maggiore e più degna cosa a legger è, allegando la sperienza, maestra ai loro maestri. Costoro vanno sgonfiati e pomposi, vestiti e ornati, non delle loro, ma delle altrui fatiche, e le mie a me medesimo non concedono; e se me inventore disprezzeranno, quanto maggiormente loro, non inventori, ma trombetti e recitatori delle altrui opere, potranno essere biasimati."],"cs":["I když bych nedovedl jako oni citovat autory, mnohem větší a důstojnější věc ke čtení je, když se dovolávám zkušenosti, mistryně jejich mistrů. Ti chodí nafouklí a nadutí, odění a ozdobení nikoli svou, nýbrž cizí prací, a mně nepřiznávají ani mou vlastní; a budou-li pohrdat mnou, vynálezcem, oč více budou moci být haněni oni, kteří nejsou vynálezci, nýbrž hlasateli a přednašeči cizích děl."],"ref":{"s":"C.A","l":117,"st":"r","z":false,"raw":"C. A. 117 r"},"ca":[642,644,646]},{"id":"s185","o":"Pensieri sulla scienza","c":"XXXVIII","str":81,"ni":"superiorità degli scopritori del vero sui commentatori delle opere altrui","nc":"Převaha objevitelů pravdy nad komentátory cizích děl","it":["È da essere giudicati, e non altrimenti stimati li omini inventori e ’nterpreti tra la natura e gli uomini, a comparazione de’ recitatori e trombetti delle altrui opere, quant’è dall’obbietto fori dello specchio alla similitudine d’esso obbietto apparente nello specchio, che l’uno per sè è qualche cosa, e l’altro è niente. Gente poco obbligate alla natura, perchè sono sol d’accidental vestiti, e sanza il quale potrei accompagnarli in li armenti delle bestie!"],"cs":["Lidi vynalézavé a tlumočníky mezi přírodou a lidmi je třeba posuzovat a cenit ve srovnání s přednašeči a hlasateli cizích děl nejinak, než jak se má předmět mimo zrcadlo k podobě téhož předmětu, jež se v zrcadle zjevuje: jedno je samo o sobě něčím, a druhé je ničím. Lidé, kteří jsou přírodě málo zavázáni, neboť jsou odění jen nahodilým rouchem, a bez něho bych je mohl přiřadit ke stádům dobytka!"],"ref":{"s":"C.A","l":117,"st":"r","z":false,"raw":"C. A. 117 r"},"ca":[642,644,646]},{"id":"s186","o":"Pensieri sulla scienza","c":"XXXIX","str":82,"ni":"contro gli umanisti","nc":"Proti humanistům","it":["So bene che per non essere io letterato, che alcuno presuntuoso gli parrà ragionevolmente potermi biasimare, coll’allegale io essere omo sanza lettere. Gente stolta! Non sanno questi tali ch’ io potrei, sì come Mario rispose contro a’ patrizi romani, sì rispondere, dicendo: - quelli che dall’altrui fatiche sè medesimi fanno ornati, le mie a me medesimo non vogliano concedere?","Diranno, che per non avere io lettere, non potere ben dire quello, di che voglio trattare. Or non sanno questi che le mie cose son più da esser tratte dalla sperienzia, che d’altrui parole, la quale fu maestra di chi ben scrisse, e così per maestra la piglio, e quella in tutti i casi allegherò."],"cs":["Dobře vím, že protože nejsem učený, zdá se nejednomu domýšlivci, že mě může po právu hanit s poukazem, že jsem člověk bez vzdělání. Pošetilí lidé! Což nevědí, že bych mohl, tak jako Marius odpověděl římským patricijům, odpovědět a říci: – Ti, kdo se zdobí cizí prací, nechtějí mně přiznat mou vlastní?","Řeknou, že protože nemám učenost, nemohu dobře vyložit to, o čem chci pojednat. Což nevědí, že mé věci je třeba čerpat spíše ze zkušenosti než z cizích slov? Ona byla mistryní těch, kdo dobře psali, a tak ji beru za mistryni a ve všech případech se jí budu dovolávat."],"ref":{"s":"C.A","l":119,"st":"r","z":false,"raw":"C. A. 119 r"},"ca":[652,654]},{"id":"s187","o":"Pensieri sulla scienza","c":"XL","str":82,"ni":"reverenza di leonardo per gli antichi inventori","nc":"Leonardova úcta ke starým vynálezcům","it":["De’ cinque corpi regolari. Contro alcuni commentatori, che biasimano li antichi inventori, donde nasceron le grammatiche e le scienze, e fansi cavalieri contro alli morti inventori, e, perchè essi non han trovato da farsi inventori, per la pigrizia e comodità de’ libri, attendono al continuo, con falsi argumenti, a riprendere li lor maestri."],"cs":["O pěti pravidelných tělesech. Proti některým komentátorům, kteří haní staré vynálezce, od nichž se zrodily gramatiky a vědy, a dělají ze sebe rytíře proti mrtvým vynálezcům; a protože sami nenašli, jak se stát vynálezci, pro lenost a pohodlí knih se ustavičně snaží falešnými argumenty kárat své mistry."],"ref":{"s":"F","l":27,"st":"v","z":false,"raw":"F. 27 v"},"ca":[]},{"id":"s188","o":"Pensieri sulla scienza","c":"XLI","str":83,"ni":"valore della autorità","nc":"Cena autority","it":["Chi disputa allegando l’autorità, non adopra lo ’ngegno, ma più tosto la memoria."],"cs":["Kdo se v disputaci dovolává autority, neužívá důvtipu, nýbrž spíše paměti."],"ref":{"s":"C.A","l":76,"st":"r","z":false,"raw":"C. A. 76 r"},"ca":[412,414]},{"id":"s189","o":"Pensieri sulla scienza","c":"XLII","str":83,"ni":"spontaneità della creazione artistica e scientifica","nc":"Spontánnost uměleckého a vědeckého tvoření","it":["Le buone lettere so’ nate da un bono naturale: e perchè si de’ più laudare la cagion che l’effetto, più lauderai un bon naturale sanza lettere, che un bon litterato sanza naturale."],"cs":["Dobrá učenost se zrodila z dobrého přirozeného nadání; a protože je třeba chválit spíše příčinu než účinek, budeš chválit víc dobré přirozené nadání bez učenosti než dobrého učence bez nadání."],"ref":{"s":"C.A","l":76,"st":"r","z":false,"raw":"C. A. 76 r"},"ca":[412,414]},{"id":"s190","o":"Pensieri sulla scienza","c":"XLIII","str":83,"ni":"studio dell’antichità","nc":"Studium starověku","it":["L’imitazione delle cose antiche è più laudabile, che le moderne."],"cs":["Napodobování věcí starých je chvályhodnější než napodobování moderních."],"ref":{"s":"C.A","l":147,"st":"r","z":false,"raw":"C. A. 147 r"},"ca":[794,796]},{"id":"s191","o":"Pensieri sulla scienza","c":"XLIV","str":83,"ni":"necessità della esperienza e della matematica nelle scienze","nc":"Nutnost zkušenosti a matematiky ve vědách","it":["Nessuna umana investigazione si po’ dimandare vera scienza, s’essa non passa per le matematiche dimostrazioni.","E se tu dirai, che le scienze, che principiano e finiscono nella mente abbino verità, questo non si concede, ma si nega, per molte ragioni, e prima, che in tali discorsi mentali non accade esperienza, sanza la quale nulla dà di sè certezza."],"cs":["Žádné lidské bádání nelze nazvat pravou vědou, neprojde-li matematickými důkazy.","A řekneš-li, že vědy, které začínají a končí v mysli, mají pravdivost, to se nepřipouští, nýbrž popírá, z mnoha důvodů, a především proto, že v takových myšlenkových úvahách nedochází ke zkušenosti, bez níž nic nedává o sobě jistotu."],"ref":{"s":"Lu","l":1,"st":"","z":false,"raw":"Lu. 1"},"ca":[]},{"id":"s192","o":"Pensieri sulla scienza","c":"XLV","str":84,"ni":"la esperienza","nc":"Zkušenost","it":["La sapienza è figliola della sperienza.","A torto si lamentan li omini della isperienza, la quale, con somme rampogne, quella accusano esser fallace. Ma lascino stare essa esperienza, e voltate tale lamentazione contro alla vostra ignoranza, la quale vi fa transcorrere, co’ vostri vani e instolti desideri, a impromettervi di quella cose, che non sono in sua potenza, dicendo quella esser fallace. A torto si lamentano li omini della innocente esperienza, quella spesso accusando di fallacie e di bugiarde dimostrazioni."],"cs":["Moudrost je dcerou zkušenosti.","Neprávem si lidé stěžují na zkušenost a s nejtvrdšími výčitkami ji obviňují, že je klamná. Ale nechte tu zkušenost na pokoji a obraťte ten nářek proti své nevědomosti, která vás svými marnými a pošetilými touhami strhuje k tomu, abyste si od ní slibovali věci, které nejsou v její moci, a říkáte, že je klamná. Neprávem si lidé stěžují na nevinnou zkušenost a často ji obviňují z klamů a lživých důkazů."],"ref":{"s":"R","l":1150,"st":"","z":false,"raw":"R. 1150"},"ca":[],"rr":"S. K. M. III. 80 b"},{"id":"s193","o":"Pensieri sulla scienza","c":"XLVII","str":85,"ni":"necessità della successione dell’effetto alla causa","nc":"Nutnost, aby účinek následoval příčinu","it":["La sperienza non falla mai, ma sol fallano i vostri giudizi, promettendosi di quella effetto tale, che ne’ nostri esperimenti causati non sono. Perchè, dato un principio, è necessario che ciò, che seguita di quello, è vera conseguenza di tal principio, se già non fussi impedito: e se pur seguita alcuno impedimento, l’effetto, che doveva seguire del predetto principio, partecipa tanto più o meno del detto impedimento, quanto esso impedimento è più o meno potente del già detto principio."],"cs":["Zkušenost se nikdy nemýlí, mýlí se jen vaše soudy, které si od ní slibují takový účinek, jaký v našich pokusech nenastává. Neboť je-li dán počátek, je nutné, aby to, co z něho následuje, bylo pravým důsledkem toho počátku, ledaže by tomu něco překáželo; a nastane-li přece nějaká překážka, účinek, který měl z řečeného počátku následovat, má na té překážce podíl o to větší či menší, oč je ta překážka mocnější či slabší než řečený počátek."],"ref":{"s":"C.A","l":154,"st":"r","z":false,"raw":"C. A. 154 r"},"ca":[830,832]},{"id":"s194","o":"Pensieri sulla scienza","c":"XLVIII","str":85,"ni":"la certezza delle matematiche","nc":"Jistota matematiky","it":["Chi biasima la somma certezza della matematica si pasce di confusione, e mai porrà silenzio alle contraddizioni delle sofistiche scienze, colle quali s’impara uno eterno gridore."],"cs":["Kdo haní nejvyšší jistotu matematiky, živí se zmatkem a nikdy neumlčí rozpory sofistických věd, s nimiž se člověk naučí jen věčnému křiku."],"ref":{"s":"K","l":49,"st":"r","z":true,"raw":"K. 49 r"},"ca":[]},{"id":"s195","o":"Pensieri sulla scienza","c":"XLIX","str":85,"ni":"generale applicabilità della matematica","nc":"Obecná použitelnost matematiky","it":["La proporzione non solamente nelli numeri e misure fia ritrovata, ma etiam nelli suoni, pesi, tempi e siti, e ’n qualunque potenza si sia."],"cs":["Poměr se najde nejen v číslech a mírách, ale také ve zvucích, vahách, časech a polohách, a v jakékoli síle."],"ref":{"s":"K","l":49,"st":"r","z":false,"raw":"K. 49 r"},"ca":[]},{"id":"s196","o":"Pensieri sulla scienza","c":"L","str":86,"ni":"delle scienze","nc":"O vědách","it":["Nessuna certezza è dove non si può applicare una delle scienze matematiche, over che non sono unite con esse matematiche."],"cs":["Žádná jistota není tam, kde nelze použít některou z matematických věd, ani v tom, co s matematikou není spojeno."],"ref":{"s":"G","l":96,"st":"","z":false,"raw":"G. 96"},"ca":[]},{"id":"s197","o":"Pensieri sulla scienza","c":"LI","str":86,"ni":"leonardo al lettore","nc":"Leonardo čtenáři","it":["Non mi legga chi non e matematico, nelli mia principî."],"cs":["Kdo není matematik, ať mě nečte v mých základech."],"ref":{"s":"R","l":3,"st":"","z":false,"raw":"R. 3"},"ca":[],"rr":"W. An. IV. 163 b"},{"id":"s198","o":"Pensieri sulla scienza","c":"LII","str":86,"ni":"della meccanica","nc":"O mechanice","it":["La Meccanica è il paradiso delle scienze matematiche, perchè con quella si viene al frutto matematico."],"cs":["Mechanika je rájem matematických věd, neboť skrze ni se dochází k matematickému plodu."],"ref":{"s":"E","l":8,"st":"r","z":false,"raw":"E. 8 r"},"ca":[]},{"id":"s199","o":"Pensieri sulla scienza","c":"LIII","str":86,"ni":"la meccanica e la esperienza","nc":"Mechanika a zkušenost","it":["A ciascuno strumento si richiede esser fatto colla sperienza."],"cs":["Každý nástroj musí být zhotoven se zkušeností."],"ref":{"s":"R","l":1156,"st":"","z":false,"raw":"R. 1156"},"ca":[],"rr":"Br. M. 191 a"},{"id":"s200","o":"Pensieri sulla scienza","c":"LIV","str":86,"ni":"accordo fra l’esperienza e la ragione","nc":"Soulad mezi zkušeností a rozumem","it":["La sperienza, interprete in fra l’artifiziosa natura e la umana spezie, ne ’nsegna, ciò che essa natura in fra mortali adopra, da necessità constretta, non altrimenti oprar si possa, che la ragione, suo timone, oprare le ’nsegni."],"cs":["Zkušenost, tlumočnice mezi důmyslnou přírodou a lidským pokolením, nás učí, že to, co ta příroda mezi smrtelníky působí, donucena nutností, nemůže působit jinak, než jak ji to učí rozum, její kormidlo."],"ref":{"s":"C.A","l":86,"st":"r","z":false,"raw":"C. A. 86 r"},"ca":[466,468]},{"id":"s201","o":"Pensieri sulla scienza","c":"LV","str":87,"ni":"la deduzione","nc":"Dedukce","it":["Non è da biasimare lo mostrare, in fra l’ordine del processo della scienza, alcuna regola generale, nata dall’antidetta conclusione."],"cs":["Není třeba hanět, ukáže-li se v pořadí postupu vědy nějaké obecné pravidlo, zrozené z předchozího závěru."],"ref":{"s":"R","l":6,"st":"","z":false,"raw":"R. 6"},"ca":[],"rr":"Br. M. 32 b"},{"id":"s202","o":"Pensieri sulla scienza","c":"LVI","str":87,"ni":"bisogna passare dal noto all’ignoto","nc":"Je třeba postupovat od známého k neznámému","it":["Per dare vera scienza del moto delli uccelli in fra l’aria, è necessario dare prima la scienza de’ venti, la qual proverem mediante li moti dell’acqua in sè medesima, e questa tale scienza sensibile farà di sè scala per venire alla cognizione de’ volatili in fra l’aria e ’l vento."],"cs":["Abychom podali pravou vědu o pohybu ptáků ve vzduchu, je nutné podat nejprve vědu o větrech, kterou dokážeme pomocí pohybů vody v sobě samé; a tato smysly vnímatelná věda bude žebříkem, po němž dospějeme k poznání létajících tvorů ve vzduchu a ve větru."],"ref":{"s":"E","l":54,"st":"r","z":false,"raw":"E. 54 r"},"ca":[]},{"id":"s203","o":"Pensieri sulla scienza","c":"LVII","str":87,"ni":"la legge di natura domina i fatti","nc":"Přírodní zákon vládne jevům","it":["Nessuno effetto è in natura sanza ragione; intendi la ragione, e non ti bisogna sperienza."],"cs":["Žádný účinek není v přírodě bez důvodu; pochop důvod, a nepotřebuješ zkušenost."],"ref":{"s":"C.A","l":147,"st":"v","z":false,"raw":"C. A. 147 v"},"ca":[795,797]},{"id":"s204","o":"Pensieri sulla scienza","c":"LVIII","str":87,"ni":"l’esperienza è il fondamento della scienza","nc":"Zkušenost je základem vědy","it":["Ricordati, quando commenti l’acque, d’allegar prima la sperienza e poi la ragione."],"cs":["Pamatuj, až budeš vykládat o vodách, uvést nejprve zkušenost a potom důvod."],"ref":{"s":"H","l":90,"st":"r","z":false,"raw":"H. 90 r"},"ca":[]},{"id":"s205","o":"Pensieri sulla scienza","c":"LIX","str":88,"ni":"sul medesimo soggetto","nc":"Na totéž téma","it":["Io ti ricordo, che tu facci le tue proposizioni, e che tu alleghi le soprascritte cose per esempli e non per proposizioni, che sarebbe troppo semplice; e dirai così: sperienza."],"cs":["Připomínám ti, abys vytvářel své poučky a abys výše napsané věci uváděl jako příklady, a ne jako poučky, což by bylo příliš prosté; a řekneš takto: zkušenost."],"ref":{"s":"A","l":31,"st":"r","z":false,"raw":"A. 31 r"},"ca":[]},{"id":"s206","o":"Pensieri sulla scienza","c":"LX","str":88,"ni":"dalla investigazione degli effetti si scoprono le cause","nc":"Zkoumáním účinků se odhalují příčiny","it":["Ma prima farò alcuna esperienza avanti, ch’io più oltre proceda, perchè mia intenzione è allegare prima l’esperienza, e poi colla ragione dimostrare, perchè tale esperienza è costretta in tal modo ad operare.","E questa è la vera regola, come li speculatori delli effetti naturali hanno a procedere, e ancora che la natura cominci dalla ragione e termini nella sperienza, a noi bisogna seguitare in contrario, cioè cominciando — come di sopra dissi — dalla sperienza, e con quella investigare la ragione."],"cs":["Ale dřív než postoupím dál, provedu nejprve nějaký pokus, neboť je mým záměrem uvést nejprve zkušenost a potom rozumem dokázat, proč je ta zkušenost nucena působit právě takto.","A to je pravé pravidlo, jak mají postupovat zkoumatelé přírodních účinků; a ačkoli příroda začíná od důvodu a končí ve zkušenosti, my musíme postupovat opačně, totiž začínat – jak jsem řekl výše – od zkušenosti a s ní zkoumat důvod."],"ref":{"s":"E","l":55,"st":"r","z":false,"raw":"E. 55 r"},"ca":[]},{"id":"s207","o":"Pensieri sulla scienza","c":"LXI","str":88,"ni":"bisogna ripetere le esperienze e variare le circostanze","nc":"Pokusy je třeba opakovat a obměňovat okolnosti","it":["Innanzi di fare di questo caso una regola generale, sperimentalo due o tre volte, guardando se le sperienze producono gli stessi effetti."],"cs":["Než učiníš z tohoto případu obecné pravidlo, vyzkoušej jej dvakrát nebo třikrát a sleduj, zda pokusy vyvolávají tytéž účinky."],"ref":{"s":"A","l":47,"st":"r","z":false,"raw":"A. 47 r"},"ca":[]},{"id":"s208","o":"Pensieri sulla scienza","c":"LXII","str":89,"ni":"esempio della precedente regola","nc":"Příklad předchozího pravidla","it":["Se molti corpi, d’egual peso e figura, saranno l'un dopo l'altro, con egual tempo, lasciati cadere, li eccessi de’ loro intervalli saranno infra loro eguali.","La sperienza della predetta conclusione di moto si debbe fare in questa forma, cioè: tolgansi due ballotte d’egual peso e figura, e si faccino lasciare cadere di grande altezza in modo che, nel lor principio di moto, si tocchino l’una l’altra, e lo sperimentatore stia a terra a vedere se ’l loro cadere l’ha ancora mantenute in contatto o no. E questa esperienza si faccia più volte, acciò che qualche accidente non impedissi o falsassi tale prova, che la sperienza fussi falsa, e ch’ella ingannassi o no il suo speculatore."],"cs":["Necháme-li padat mnoho těles stejné váhy a tvaru jedno po druhém ve stejných časových odstupech, budou přírůstky jejich vzdáleností mezi sebou stejné.","Pokus k řečenému závěru o pohybu se má provést tímto způsobem: vezměte dvě kuličky stejné váhy a tvaru a nechte je spadnout z veliké výšky tak, aby se na počátku pohybu navzájem dotýkaly; a pokusník ať stojí na zemi a sleduje, zda je jejich pád ještě udržel ve vzájemném dotyku, či nikoli. A ten pokus ať se provede vícekrát, aby nějaká nahodilost nepřekazila nebo nezfalšovala tu zkoušku, takže by pokus byl falešný, a aby se poznalo, zda svého zkoumatele klame, či nikoli."],"ref":{"s":"F","l":72,"st":"v","z":true,"raw":"F. 72 v"},"ca":[]},{"id":"s209","o":"Pensieri sulla scienza","c":"LXIII","str":89,"ni":"bisogna limitare la ragione alla esperienza, non estendere la ragione al di là della esperienza","nc":"Rozum v mezích zkušenosti","it":["Quanto più si diminuisce il mobile, il suo motore lo caccia più, proporzionevolmente secondo la sua diminuzione in infinito, sempre acquistando velocità di moto.","E’ seguiterebbe che un atomo sarebbe quasi veloce come la immaginazione o l’occhio, che subito discorre alla altezza dello stelle, per conseguente il suo viaggio sarebbe infinito, perchè la cosa, che infinitamente si può diminuire, infinitamente si farebbe veloce, e infinito cammin si moverebbe (perchè ogni quantità continua è divisibile in infinito). La qual opinione è dannata dalla ragione e per conseguente dalla sperienza.","Sicchè voi, speculatori, non vi fidate delli autori, che hanno sol coll’immaginazione voluto farsi interpreti fra la natura e l’omo, ma sol di quelli, che non coi cenni della natura, ma co’ gli effetti delle sue esperienze hanno esercitati i loro ingegni. E riconoscere come l’esperienze ingannano chi non conosce loro natura; perchè quelle, che spesse volte paiono una medesima, spesse volte son di grande varietà, come qui si dimostra."],"cs":["Čím víc se pohyblivé těleso zmenšuje, tím víc je jeho hybatel pohání, úměrně jeho zmenšování až do nekonečna, a stále tak nabývá rychlosti pohybu.","Plynulo by z toho, že atom by byl téměř tak rychlý jako obrazotvornost nebo oko, které rázem dolétne až do výše hvězd; a následkem toho by jeho dráha byla nekonečná, neboť věc, kterou lze nekonečně zmenšovat, by se stala nekonečně rychlou a pohybovala by se po nekonečné dráze (neboť každá spojitá veličina je dělitelná do nekonečna). Ten názor je zavržen rozumem, a tudíž i zkušeností.","A tak vy, zkoumatelé, nedůvěřujte autorům, kteří se chtěli stát tlumočníky mezi přírodou a člověkem jen pomocí obrazotvornosti, nýbrž jen těm, kdo cvičili své duchy nikoli na pokynech přírody, ale na účincích jejích zkušeností. A poznejte, jak zkušenosti klamou toho, kdo nezná jejich povahu; neboť ty, které se často zdají stejné, bývají často velmi rozmanité, jak se zde ukazuje."],"ref":null,"ca":[]},{"id":"s210","o":"Pensieri sulla scienza","c":"LXIV","str":90,"ni":"a coloro che affermano l’acqua trovarsi alla sommità dei monti, perchè il mare è più alto, che la terra","nc":"Voda na vrcholcích hor","it":["Se l’acqua, che surge per l’alte cime de’ monti, viene dal mare, del quale il suo peso la sospignie, per essere più alto d’essi monti; perchè ha così licenza tal particula l’acqua a levarsi in tanta altezza, e penetrare la terra con tanta difficultà e tempo; e non è stato conceduto al resto dell’elemento dell’acqua fare il simile, il quale confina coll’aria, la qual non è per resisterli, che ’l tutto non si elevassi alla medesima altezza della predetta parte? E tu che tale invenzione trovasti ritorna a riimparare naturale, che tu mancherai di tali simili opinioni, del quale tu ha’ fatto grande ammunizione insieme col capitale del frutto, che tu possiedi."],"cs":["Jestliže voda, která vyvěrá na vysokých vrcholcích hor, přichází z moře, jehož váha ji vytlačuje, protože je výše než ty hory, proč má taková částečka vody povolení zvednout se do tak veliké výšky a pronikat zemí s takovou námahou a za tak dlouhý čas, a nebylo dovoleno ostatnímu živlu vody, který hraničí se vzduchem, jenž mu nemůže klást odpor, učinit totéž, takže by se celek nezvedl do stejné výšky jako řečená část? A ty, který jsi takový nápad vymyslel, vrať se a nauč se znovu přírodní vědě, a zbavíš se takových a podobných názorů, jichž sis nadělal velikou zásobu spolu s jměním, které vlastníš."],"ref":{"s":"F","l":72,"st":"v","z":false,"raw":"F. 72 v"},"ca":[]},{"id":"s211","o":"Pensieri sulla scienza","c":"LXV","str":91,"ni":"la prospettiva e la matematica","nc":"Perspektiva a matematika","it":["Intra li studi delle naturali cause e ragioni, la luce diletta più i contemplanti; intra le cose grandi delle matematiche, la certezza della dimostrazione innalza più preclaramente l’ingegno dell’investiganti.","La Prospettiva adunque è da essere preposta a tutte le trattazioni e discipline umane, nel campo della quale la linia radiosa è complicata dai modi delle dimostrazioni, nella quale si truova la gloria non tanto della Matematica, quanto della Fisica, ornata co’ fiori dell’una e dell’altra.","Le sentenze delle quali, distese con gran circuizione, io le ristrignierò in conclusiva brevità, intessendo, secondo il modo della materia, naturali e matematiche dimostrazioni, alcuna volta concludendo gli effetti per le cagioni e alcuna volta le cagioni per li effetti; aggiugnendo ancora alle mie conclusioni alcuna, che non sono in quelle, non di meno di quelle si traggono, come si degnerà il Signore, luce di ogni cosa, illustrare me per trattare della luce."],"cs":["Mezi studiemi přírodních příčin a důvodů těší světlo rozjímající nejvíce; mezi velkými věcmi matematiky povznáší jistota důkazu nejjasněji ducha zkoumajících.","Perspektivu je tedy třeba postavit nad všechna lidská pojednání a učení; v jejím poli je zářící paprsek spleten se způsoby důkazů a nachází se v ní sláva nejen matematiky, ale i fyziky, ozdobená květy obou.","Její výroky, rozvedené s velikou rozvláčností, sevřu do závěrečné stručnosti, protkávaje podle povahy látky přírodní a matematické důkazy, někdy vyvozuji účinky z příčin a někdy příčiny z účinků; a připojím ke svým závěrům ještě některé, které v nich nejsou, a přece se z nich vyvozují, jak se Pán, světlo všech věcí, uráčí osvítit mne, abych pojednal o světle."],"ref":{"s":"C.A","l":200,"st":"r","z":false,"raw":"C. A. 200 r"},"ca":[1072,1074]},{"id":"s212","o":"Pensieri sulla scienza","c":"LXVI","str":92,"ni":"la cognizione ha origine dal senso","nc":"Poznání má původ ve smyslech","it":["Ogni nostra cognizione principia da’ sentimenti."],"cs":["Veškeré naše poznání začíná od smyslů."],"ref":{"s":"T","l":20,"st":"v","z":false,"raw":"T. 20 v"},"ca":[]},{"id":"s213","o":"Pensieri sulla scienza","c":"LXVII","str":92,"ni":"conseguenza del predetto principio","nc":"Důsledek uvedené zásady","it":["Come il senso serve all’anima e non l’anima al senso; e, dove manca il senso offiziale dell’anima, all’anima manca in questa vita la totalità dell’uffizio d’esso senso, come appare nel muto e nell’orbo nato."],"cs":["Jak smysl slouží duši, a ne duše smyslu; a kde chybí smysl, služebník duše, chybí duši v tomto životě úplnost služby toho smyslu, jak je patrno u němého a u slepého od narození."],"ref":{"s":"R","l":838,"st":"","z":false,"raw":"R. 838"},"ca":[],"rr":"W. An. II. 202 a"},{"id":"s214","o":"Pensieri sulla scienza","c":"LXVIII","str":93,"ni":"la testimonianza del senso è il criterio del vero","nc":"Svědectví smyslů je měřítkem pravdy","it":["E se tu dirai, che ’l vedere impedisce la fìssa e sottile cogitazione mentale, co’ la quale si penetra nelle divine scienze, e tale impedimento condusse un filosofo a privarsi del vedere; a questo rispondo, che tal occhio, come signore de’ sensi, fa suo debito a dare impedimento alli confusi e bugiardi, non scienze, ma discorsi, per li quali sempre, con gran gridare e menare le mani, si disputa; e il medesimo dovrebbe fare l’audito, il quale ne rimane più offeso, perchè egli vorrebbe accordo, del quale tutti i sensi s’intricano. E se tal filosofo si trasse gli occhi per levare l’impedimento alli suoi discorsi, or pensa, che tal atto fu compagno del cervello e de’ discorsi, perchè ’l tutto fu pazzia. Or non potea egli serrarsi gli occhi, quando esso entrava in tale frenesia, e tanto tenerli serrati, che tal furore si consumasse? Ma pazzo fu l’omo, e pazzo il discorso, e stoltissimo il trarsi gli occhi!"],"cs":["A řekneš-li, že zrak překáží upřenému a jemnému myšlenkovému rozjímání, jímž se proniká do božských věd, a že taková překážka přivedla jednoho filozofa k tomu, že se připravil o zrak, na to odpovídám, že takové oko, jako pán smyslů, koná svou povinnost, když klade překážky zmateným a lživým nikoli vědám, nýbrž řečem, o nichž se vždy s velkým křikem a rozhazováním rukama disputuje; a totéž by měl činit sluch, který je tím ještě víc uražen, neboť by chtěl souzvuk, do něhož se všechny smysly zaplétají. A jestliže si ten filozof vyloupl oči, aby odstranil překážku svým úvahám, uvaž, že ten čin byl hodný jeho mozku i jeho úvah, neboť to všechno bylo bláznovství. Což si nemohl zavřít oči, když upadal do takového blouznění, a držet je zavřené tak dlouho, až by ta zuřivost vyprchala? Ale blázen byl ten člověk, bláznivá ta úvaha, a nanejvýš pošetilé vyloupnout si oči!"],"ref":{"s":"Lu","l":16,"st":"","z":false,"raw":"Lu. 16"},"ca":[]},{"id":"s215","o":"Pensieri sulla scienza","c":"LXIX","str":94,"ni":"le vere scienze sono quelle che si fondano sulla testimonianza dei sensi","nc":"Pravé vědy jsou ty, které se zakládají na svědectví smyslů","it":["Dicono quella cognizione esser meccanica, la quale è partorita dall’esperienza, e quella esser scientifica, che nasce e finisce nella niente, e quella esser semimeccanica, che nasce dalla scienza e finisce nella operazione manuale.","Ma a me pare che quelle scienze sieno vane e piene di errori, le quali non sono nate dall’esperienza, madre di ogni certezza, e che non terminano in nota esperienza, cioè che la loro origine o mezzo o fine non passa per nessuno de’ cinque sensi.","E se noi dubitiamo di ciascuna cosa, che passa per li sensi, quanto maggiormente dobbiamo noi dubitare delle cose ribelli a essi sensi, come dell’essenza di Dio e dell’anima e simili, per le quali sempre si disputa e contende? E veramente accade, che sempre, dove manca la ragione, supplisce le grida, la qual cosa non accade nelle cose certe. Per questo diremo, che dove si grida non è vera scienza, perchè la verità ha un sol termine, il quale, essendo pubblicato, il litigio resta in eterno distrutto, e s’esso litigio risurge, è bugiarda e confusa scienza e non certezza rinata.","Ma le vere scienze son quelle, che la speranza ha fatto penetrare per li sensi e posto silenzio alla lingua de’ litiganti, e che non pasce di sogno li suoi investigatori, ma sempre sopra li primi veri e noti principi procede successivamente e con vere seguenze insino al fine; come si dinota nelle prime matematiche, cioè numero e misura, dette Aritmetica e Geometria, che trattano con somma verità della quantità discontinua e continua.","Qui non si arguirà, che due tre facciano più o men che sei, nè che un triangolo abbia li suoi angoli minori di due angoli retti, ma con eterno silenzio resta distrutta ogni arguizione, e con pace sono finite dalli loro devoti, il che far non possono le bugiarde scienze mentali.","E se tu dirai tali scienze vere e note essere di spezie di meccaniche, imperocchè non si possono finire se non manualmente, io dirò il medesimo di tutte lo arti, che passano per le mani degli scultori, le quali sono di spezie di disegno, membro della pittura; e l’Astrologia e le altre passano per le manuali operazioni, ma prima sono mentali, com’è la Pittura, la quale è prima nella mente del suo speculatore, e non può pervenire alla sua perfezione sanza la manuale operazione.","Della qual Pittura, li sua scientifici e veri principi prima ponendo, che cosa è corpo ombroso, e che cosa è ombra primitiva e ombra derivativa, e che cosa è lume: cioè tenebre, luce, colore, corpo, figura, sito, remozione, propinquità, moto e quiete, le quali solo colla mente si comprendono sanza opere manuali. E questa fia la Scienza della Pittura, che resta nella mente de’ suoi contemplanti, della quale nasce poi l’operazione, assai più degna della predetta contemplazione o scienza."],"cs":["Říkají, že mechanické je to poznání, které je zrozeno ze zkušenosti, a vědecké to, které se rodí a končí v mysli, a polomechanické to, které se rodí z vědy a končí v ruční práci.","Mně se však zdá, že jsou marné a plné omylů ty vědy, které se nezrodily ze zkušenosti, matky veškeré jistoty, a které nekončí ve známé zkušenosti, totiž jejichž původ, střed ani konec neprochází žádným z pěti smyslů.","A pochybujeme-li o každé věci, která prochází smysly, oč více musíme pochybovat o věcech, které se smyslům vzpírají, jako o podstatě Boha a duše a podobných, o nichž se stále disputuje a hádá? A vskutku se stává, že všude, kde chybí rozum, nastupuje křik, což se ve věcech jistých nestává. Proto řekneme, že kde se křičí, tam není pravá věda, neboť pravda má jediný konec, a když je zveřejněn, spor je navždy zničen; a vzkřísí-li se ten spor znovu, je to věda lživá a zmatená, a ne znovuzrozená jistota.","Pravé vědy jsou však ty, které zkušenost nechala proniknout smysly a umlčela jazyk hádajících se, a které nekrmí své badatele snem, nýbrž vždy od prvních pravdivých a známých principů postupují krok za krokem a v pravých posloupnostech až ke konci; jak je patrno v prvních matematických vědách, totiž v čísle a míře, zvaných aritmetika a geometrie, které s nejvyšší pravdivostí pojednávají o veličině nespojité a spojité.","Zde se nebude dokazovat, že dvakrát tři je víc nebo méně než šest, ani že trojúhelník má úhly menší než dva pravé úhly, nýbrž každý spor zůstává zničen věčným mlčením a jejich ctitelé je pokojně uzavírají, čehož lživé myšlenkové vědy nedokážou.","A řekneš-li, že takové pravé a známé vědy jsou mechanického druhu, protože je nelze dokončit jinak než rukama, řeknu totéž o všech uměních, která procházejí rukama sochařů a jsou druhem kresby, údu malířství; i astrologie a ostatní procházejí ruční prací, ale nejprve jsou myšlenkové, jako je malířství, které je nejprve v mysli svého zkoumatele a nemůže dojít své dokonalosti bez ruční práce.","U tohoto malířství nejprve kladu jeho vědecké a pravé principy: co je stínící těleso, co je stín původní a stín odvozený a co je světlo, totiž tma, světlo, barva, těleso, tvar, poloha, vzdálenost, blízkost, pohyb a klid; a ty se chápou jen myslí, bez ruční práce. A to bude věda o malířství, která zůstává v mysli těch, kdo o ní rozjímají, a z ní se pak rodí provedení, mnohem vznešenější než řečené rozjímání či věda."],"ref":{"s":"Lu","l":33,"st":"","z":false,"raw":"Lu. 33"},"ca":[]},{"id":"s216","o":"Pensieri sulla scienza","c":"LXX","str":96,"ni":"inganno della mente abbandonata a se stessa","nc":"Klam mysli ponechané sobě samé","it":["Nissuna cosa è, che più c’inganni, che ’l nostro judizio."],"cs":["Nic nás neklame víc než náš vlastní úsudek."],"ref":{"s":"Lu","l":65,"st":"","z":false,"raw":"Lu. 65"},"ca":[]},{"id":"s217","o":"Pensieri sulla scienza","c":"LXXI","str":96,"ni":"sul medesimo soggetto","nc":"K téže věci","it":["Il massimo inganno delli omini è nelle loro opinioni."],"cs":["Největší klam lidí tkví v jejich mněních."],"ref":{"s":"C.A","l":153,"st":"v","z":false,"raw":"C. A. 153 v"},"ca":[823,825,828]},{"id":"s218","o":"Pensieri sulla scienza","c":"LXXII","str":96,"ni":"contro la metafisica","nc":"Proti metafyzice","it":["Fuggi i precetti di quelli speculatori, che le loro ragioni non son confermate dalla isperienza."],"cs":["Vyhýbej se poučkám těch spekulantů, jejichž důvody nejsou potvrzeny zkušeností."],"ref":{"s":"B","l":4,"st":"v","z":false,"raw":"B. 4 v"},"ca":[]},{"id":"s219","o":"Pensieri sulla scienza","c":"LXXIII","str":97,"ni":"superiorità degli animali sull’uomo","nc":"Převaha zvířat nad člověkem","it":["L’uomo ha grande discorso, del quale la più parte è vano e falso; li animali l’hanno piccolo, ma è utile e vero; e meglio è la piccola certezza, che la gran bugia."],"cs":["Člověk má velký rozum, jehož větší část je marná a lživá; zvířata mají rozum malý, ale užitečný a pravdivý; a lepší je malá jistota než velká lež."],"ref":{"s":"F","l":96,"st":"v","z":false,"raw":"F. 96 v"},"ca":[]},{"id":"s220","o":"Pensieri sulla scienza","c":"LXXIV","str":97,"ni":"dal dizionario di leonardo","nc":"Z Leonardova slovníku","it":["Sillogismo: parlar dubbioso. Sofismo: parlare confuso, il falso per lo vero. Teorica: scienza sanza pratica."],"cs":["Sylogismus: pochybná řeč. Sofisma: řeč zmatená, nepravda za pravdu. Teorie: věda bez praxe."],"ref":{"s":"T","l":12,"st":"r","z":false,"raw":"T. 12 r"},"ca":[]},{"id":"s221","o":"Pensieri sulla scienza","c":"LXXV","str":97,"ni":"superiorità della scienza della pittura sulla filosofia","nc":"Převaha vědy malířství nad filozofií","it":["La Pittura s’estende nelle superficie, colori e figure di qualunque cosa creata dalla natura, e la Filosofia penetra dentro alli medesimi corpi, considerando in quelli le lor proprie virtù, ma non rimane satisfatta con quella verità, che fa il pittore, che abbraccia in s’ la prima verità di tali corpi, perchè l’occhio meno s’inganna."],"cs":["Malířství se rozprostírá po povrchu, barvách a tvarech každé věci stvořené přírodou, a filozofie proniká dovnitř týchž těles a zkoumá v nich jejich vlastní síly; ale nedojde uspokojení s onou pravdou, jako malíř, který v sobě obsahuje první pravdu těchto těles, neboť oko se klame méně."],"ref":{"s":"C.A","l":79,"st":"r","z":true,"raw":"C. A. 79 r"},"ca":[426,428]},{"id":"s222","o":"Pensieri sulla scienza","c":"LXXVI","str":97,"ni":"non si conosce l’essenza delle cose, ma i loro effetti","nc":"Nepoznáváme podstatu věcí, nýbrž jejich účinky","it":["Che cosa sia elemento. Nè la diffinizione di nessuna quiddità dalli -elementi non è in podestà dell’omo, ma gran parte de’ loro effetti son noti."],"cs":["Co je živel. Definice žádné podstaty živlů není v moci člověka, ale velká část jejich účinků je známa."],"ref":{"s":"C.A","l":79,"st":"r","z":false,"raw":"C. A. 79 r"},"ca":[426,428]},{"id":"s223","o":"Pensieri sulla scienza","c":"LXXVII","str":98,"ni":"come la massa dell’acqua, che circonda la terra, ha forma sferica","nc":"Jak má masa vody, jež obklopuje zemi, kulový tvar","it":["Questa è difficile risposta; ma per questo non resterei di dirne il mio parere. L’acqua, vestita dell’aria, naturalmente desidera stare unita nella sua spera, perchè in tal sito essa si priva di gravità. La qual gravità è dupla, cioè che ’l suo tutto ha gravità attesa al centro delli elementi, la seconda gravità attende al centro d’essa spericità d’acqua; il che se così non fussi, essa farebbe di sè solamente una mezza spera, la qual è quella che sta dal centro in su. Ma di questo non veggo nello umano ingegno modo di darne scienza, ch’a dire, come si dice della calamita che tira il ferro, cioè, che tal virtù è occulta proprietà, delle quali n’è infinite in natura."],"cs":["Na to je těžké odpovědět; ale přesto nepřestanu říci svůj názor. Voda, oděná vzduchem, přirozeně touží zůstat spojena ve své kouli, neboť v takovém místě pozbývá tíže. Tato tíže je dvojí: totiž její celek má tíži směřující ke středu živlů, druhá tíže směřuje ke středu samotné vodní koule; kdyby tomu tak nebylo, utvořila by ze sebe jen polovinu koule, totiž tu, která je od středu nahoru. Ale nevidím v lidském důmyslu způsob, jak o tom podat vědění, leda říci, jak se říká o magnetu, který přitahuje železo, že totiž taková síla je skrytá vlastnost, jichž je v přírodě nekonečně mnoho."],"ref":{"s":"C.A","l":75,"st":"v","z":false,"raw":"C. A. 75 v"},"ca":[408,410]},{"id":"s224","o":"Pensieri sulla scienza","c":"LXXVIII","str":98,"ni":"la divisibilità all’infinito è un’astrazione mentale","nc":"Dělitelnost do nekonečna je abstrakce mysli","it":["Ciò ch’è divisibile in atto è ancora divisibile in potenzia, ma non tutte le quantità, che son divisibili in potenzia fieno divisibili in atto."],"cs":["Co je dělitelné ve skutečnosti, je dělitelné i v možnosti, ale ne všechny veličiny, které jsou dělitelné v možnosti, budou dělitelné ve skutečnosti."],"ref":{"s":"C.A","l":119,"st":"r","z":false,"raw":"C. A. 119 r"},"ca":[652,654]},{"id":"s225","o":"Pensieri sulla scienza","c":"LXXIX","str":99,"ni":"l’infinito non si può abbracciare colla ragione","nc":"Nekonečno nelze obsáhnout rozumem","it":["Qual’e quella cosa, che non si dà e s’ella si dessi non sarebbe? Egli è lo infinito, il quale, se si potesse dare, sarebbe limitato e finito, perchè ciò, che si po’ dare ha termine colla cosa, che la circuisce ne’ sua stremi, e ciò che non si po’ dare è quella cosa, che non ha termini."],"cs":["Co je ta věc, která se nedá, a kdyby se dala, nebyla by? Je to nekonečno, které, kdyby se mohlo dát, bylo by ohraničené a konečné, neboť co se dá dát, má hranici s věcí, jež je obklopuje na jeho krajích, a co se dát nedá, je ta věc, která nemá hranic."],"ref":{"s":"C.A","l":113,"st":"v","z":false,"raw":"C. A. 113. v"},"ca":[623,625,626]},{"id":"s226","o":"Pensieri sulla scienza","c":"LXXX","str":99,"ni":"sul medesimo soggetto","nc":"K téže věci","it":["De anima. Il moto della terra contro alla terra, ricalcando quella, poco si move la parte percossa.","L’acqua percossa dall’acqua fa circuii dintorno al loco percosso;","Per lunga distanza la voce in fra l’aria;","Più lunga in fra ’l foco;","Più la mente in fra l’universo, ma perchè l’è finita non s’astende in fra lo ’nfinito."],"cs":["O duši. Pohyb země proti zemi, která ji stlačí, pohne udeřenou částí jen málo.","Voda udeřená vodou dělá kruhy kolem místa úderu;","na dlouhou vzdálenost hlas ve vzduchu;","ještě delší v ohni;","ještě dál mysl ve vesmíru, ale protože je konečná, nesahá do nekonečna."],"ref":{"s":"H","l":67,"st":"v","z":false,"raw":"H. 67 v"},"ca":[]},{"id":"s227","o":"Pensieri sulla scienza","c":"LXXXI","str":99,"ni":"la finalità delle cose trascende la mente umana","nc":"Účel věcí přesahuje lidskou mysl","it":["O speculatore delle cose, non ti laudare di conoscere le cose, che ordinariamente, per sè medesima la natura, per sua ordini, naturalmente conduce; ma rallegrati di conoscere il fine di quelle cose, che son disegnate dalla mente tua!"],"cs":["Ó zkoumateli věcí, nechval se, že znáš věci, které příroda obvykle sama od sebe, svými řády, přirozeně vede; ale raduj se, že znáš účel těch věcí, které jsou navrženy tvou myslí!"],"ref":{"s":"G","l":47,"st":"r","z":false,"raw":"G. 47 r"},"ca":[]},{"id":"s228","o":"Pensieri sulla scienza","c":"LXXXII","str":100,"ni":"gli antichi si sono proposti dei problemi insolubili","nc":"Staří si kladli neřešitelné otázky","it":["Or guarda, o lettore, quello che noi potremo credere ai nostri antichi, i quali hanno voluto definire che cosa sia anima e vita, cose improvabili, quando quelle, che con isperienzia ognora si possono chiaramente conoscere e provare, sono per tanti secoli ignorate e falsamente credute! L’occhio, che così chiaramente fa sperienzia del suo offizio, è insino ai mia tempi, per infiniti autori, stato difinito in un modo; trovo per isperienzia essere ’n un altro."],"cs":["Pohleď tedy, čtenáři, co můžeme věřit našim předkům, kteří chtěli definovat, co je duše a život, věci nedokazatelné, když ty, které lze zkušeností kdykoli jasně poznat a dokázat, byly po tolik staletí neznámé a mylně chápané! Oko, které tak jasně zakouší svůj úkon, bylo až do mých časů nesčetnými autory definováno jedním způsobem; já zkušeností shledávám, že je jinak."],"ref":{"s":"C.A","l":119,"st":"r","z":false,"raw":"C. A. 119 r"},"ca":[652,654]},{"id":"s229","o":"Pensieri sulla scienza","c":"LXXXIII","str":100,"ni":"limiti alla definizione dell’anima","nc":"Meze definice duše","it":["Ancora che lo ingegno umano faccia invenzioni varie, rispondendo con vari strumenti a un medesimo fine, mai esso troverà invenzione più bella, nè più facile, nè più breve della natura, perchè nelle sue invenzioni nulla manca e nulla è superfluo; e non va con contrappesi, quando essa fa le membra atte al moto nelli corpi delli animali, ma vi mette dentro l’anima d’esso corpo componitore.","Questo discorso non va qui, ma si richiede nella composizion delli corpi animati. E il resto della definizione dell’anima lascio nelle menti de’ frati, padri de’ popoli, li quali per inspirazione sanno tutti li segreti.","Lascio star le lettere incoronate, perchè son somma verità."],"cs":["Ač lidský důmysl činí rozličné vynálezy, odpovídaje různými nástroji témuž účelu, nikdy nenalezne vynález krásnější, snazší ani stručnější, než má příroda, neboť v jejích vynálezech nic nechybí a nic není zbytečné; a nepracuje s protizávažími, když činí údy v tělech zvířat schopné pohybu, nýbrž vkládá do nich duši toho těla, jež je skládá.","Tato úvaha sem nepatří, ale je třeba jí při skladbě oduševnělých těl. A zbytek definice duše přenechávám myslím mnichů, otců lidu, kteří ze vnuknutí znají všechna tajemství.","Písma korunovaná nechávám stranou, neboť jsou nejvyšší pravdou."],"ref":{"s":"R","l":837,"st":"","z":false,"raw":"R. 837"},"ca":[],"rr":"W. An. IV. 184 a"},{"id":"s230","o":"Pensieri sulla scienza","c":"LXXXIV","str":101,"ni":"contro gli ingegni impazienti","nc":"Proti netrpělivým duchům","it":["Gli abbreviatoli delle opere fanno ingiuria alla cognizione e allo amore, conciò sia che l’amore di qualunque cosa è figliolo d’essa cognizione.","L’amore è tanto più fervente, quanto la cognizione è più certa, la qual certezza nasce dalla cognizione integrale di tutte quelle parti, le quali, essendo insieme unite, compongono il tutto di quelle cose, che debbono essere amate.","Che vale a quel che per abbreviare le parti di quelle cose, che lui fa professione di darne integral notizia, che lui lascia indietro la maggior parte delle cose, di che il tutto è composto?","Gli è vero che la impazienza, madre della stoltizia, è quella che lauda la brevità, come se questi tali non avessino tanto di vita, che li servisse a potere avere una intera notizia d’un sol particolare, come è un corpo umano! e poi vogliono abbracciare la mente di Dio, nella quale s’include l’universo, caratando e minuzzando quella in infinite parti, come l’avessino a notomizzare.","O stoltizia umana! non t’avvedi tu che tu sei stato con teco tutta la tua età, e non hai ancora notizia di quella cosa, che tu più possiedi, cioè della tua pazzia? e vuoi poi, colla moltitudine dei sofistichi, ingannare te e altri, sprezzando le matematiche scienze, nelle qual si contiene la verità, notizia delle cose che in lor si contengono; e vuoi poi scorrere ne’ miracoli e scrivere ch’hai notizia di quelle cose, di che la mente umana non è capace, e non si possono dimostrare per nessuno esemplo naturale; e ti pare avere fatto miraculi, quando tu hai guastato una opera d’alcuno ingegno speculativo; e non t’avvedi, che tu cadi nel medesimo errore che fa quello, che denuda la pianta dell’ornamento de’ sua rami, pieni di fronde, miste con li odoriferi fiori e frutti.","Come fece Giustino, abbreviatone delle Storie scritte da Trogo Pompeo, — il quale scrisse ornatamente tutti li eccellenti fatti delli sua antichi, li quali eran pieni di mirabilissimi ornamenti; — e’ compose una cosa ignuda, ma sol degna d’ingegni impazienti, li quali pare lor perder tanto di tempo, quanto quello è, che è adoperato utilmente, cioè neìli studi delle opere di natura e delle cose umane.","Ma stieno questi tali in compagnia delle bestie; nelli lor cortigiani, sieno cani e altri animali pien di rapina e accompagnansi con loro correndo sempre dietro! e seguitino l’innocenti animali, che, con la fame, alli tempi delle gran nevi, ti vengono alle case, dimandandoti limosina, come a lor tutore!"],"cs":["Zkracovatelé děl křivdí poznání i lásce, neboť láska k jakékoli věci je dcerou poznání.","Láska je tím vroucnější, čím je poznání jistější, a tato jistota se rodí z úplného poznání všech těch částí, které, jsouce spojeny, skládají celek těch věcí, jež mají být milovány.","K čemu je tomu, kdo kvůli zkracování částí oněch věcí, o nichž se zavazuje podat úplnou zprávu, vynechá větší část věcí, z nichž se celek skládá?","Je pravda, že netrpělivost, matka hlouposti, je ta, která chválí stručnost, jako by takoví lidé neměli dost života, aby jim stačil k úplnému poznání jediné zvláštní věci, jako je lidské tělo! A pak chtějí obsáhnout mysl Boží, v níž je obsažen vesmír, vážíce ji na karáty a drobíce ji na nekonečně mnoho částí, jako by ji měli pitvat.","Ó lidská hloupost! Nevidíš, že jsi byla sama se sebou celý svůj věk, a ještě nemáš poznání té věci, kterou nejvíc vlastníš, totiž svého bláznovství? A chceš pak se zástupem sofistů klamat sebe i jiné, pohrdajíc matematickými vědami, v nichž je obsažena pravda, poznání věcí, které jsou v nich obsaženy; a chceš se pak pouštět do zázraků a psát, že máš poznání těch věcí, kterých lidská mysl není schopna a které nelze dokázat žádným příkladem z přírody; a zdá se ti, že jsi vykonala zázraky, když jsi zkazila dílo nějakého hloubavého ducha; a nevidíš, že upadáš do téhož omylu jako ten, kdo obnažuje rostlinu od ozdoby jejích větví, plných listí, promísených s vonnými květy a plody.","Tak učinil Justinus, zkracovatel Dějin, které sepsal Trogus Pompeius – jenž ozdobně vylíčil všechny vynikající činy svých předků, plné nejpodivuhodnějších ozdob –, a složil věc nahou, hodnou jen netrpělivých duchů, jimž se zdá, že ztrácejí tolik času, kolik ho bylo užitečně vynaloženo, totiž na studium děl přírody a věcí lidských.","Ale ať jsou takoví lidé ve společnosti zvířat; ať jejich dvořany jsou psi a jiná zvířata plná dravosti, ať se s nimi družují a ustavičně běhají za nimi! A ať pronásledují nevinná zvířata, která za hladu, v časech velkých sněhů, přicházejí k tvým domům a prosí tě o almužnu jako svého ochránce!"],"ref":{"s":"R","l":1210,"st":"","z":false,"raw":"R. 1210"},"ca":[],"rr":"W. An. III. 241 a"},{"id":"s231","o":"Pensieri sulla scienza","c":"LXXXV","str":103,"ni":"della vita del pittore nel suo studio","nc":"O životě malíře v jeho dílně","it":["Acciò che la prosperità del corpo non guasti quella dello ingegno, il pittore overo disegnatore debbe essere solitario, e massime quando è intento alle ispeculazioni e considerazioni, che, continuamente apparendo dinanzi agli occhi, dànno materia alla memoria, d’esser bene riservate.","E se tu sarai solo tu sarai tutto tuo, e so sarai accompagnato da un solo compagno sarai mezzo tuo, e tanto meno, quanto sarà maggiore la indescrizione della tua pratica; e se sarai con più caderai in più simile inconveniente. E se tu volessi dire: — io farò a mio modo, io mi tirerò in parte, per potere meglio speculare le forme delle cose naturali —; dico questo potersi mal fare, perchè non potresti fare, ch’assa’ spesso non prestassi orecchi alle loro ciancie, e, non si potendo servire a due signori, tu faresti male l’uffizio della compagnia e peggio 4 effetto della speculazione dell’arte; e se tu dirai: — io mi tirerò tanto in parte, che le loro parole non perveniranno e non mi daranno impaccio—; io in questa parte ti dico, che tu sarai tenuto matto; ma vedi che, così facendo, tu saresti pur solo?"],"cs":["Aby blahobyt těla nezkazil blaho ducha, má být malíř či kreslíř osamělý, a zvláště když je zaujat úvahami a rozjímáním, které, ustavičně se mu zjevujíce před očima, dávají paměti látku, aby byly dobře uchovány.","Budeš-li sám, budeš celý svůj, a budeš-li v doprovodu jediného druha, budeš napůl svůj, a tím méně, čím větší bude nerozvážnost tvého obcování; a budeš-li s více lidmi, upadneš do ještě větší takové nesnáze. A kdybys chtěl říci: „Udělám to po svém, uchýlím se stranou, abych mohl lépe zkoumat tvary přírodních věcí,“ pravím, že to lze dělat jen špatně, neboť bys nemohl zabránit tomu, abys velmi často nenastavoval ucho jejich tlachání; a protože nelze sloužit dvěma pánům, plnil bys špatně povinnost společnosti a ještě hůř dílo zkoumání umění; a řekneš-li: „Uchýlím se tak daleko stranou, že jejich slova ke mně nedolehnou a nebudou mě rušit,“ v tom ti pravím, že budeš považován za blázna; ale nevidíš, že bys tak jednaje byl přece sám?"],"ref":{"s":"Ash.I","l":27,"st":"v","z":false,"raw":"Ash. I. 27 v"},"ca":[]},{"id":"s232","o":"Pensieri sulla scienza","c":"LXXXVI","str":104,"ni":"consigli al pittore","nc":"Rady malíři","it":["Lo ingegno del pittore vol essere a similitudine dello specchio, il quale sempre si trasmuta nel colore di quella cosa, che ha per obbietto, e di tante similitudini s’empie quante sono le cose, che li sono contrapposte.","Adunque conoscendo tu, pittore, non poter essere bono se non se’ universale maestro di contraffare, colla tua arte, tutte le qualità delle forme, che produce la natura, le quali non saprai fare se non le vedi, e ritenerle nella mente; onde, andando tu per campagne, fa che ’l tuo giudizio si volti a vari obbietti, e di mano in mano riguardare or questa cosa ora quell’altra, facendo un fascio di varie cose elette e scelte in fra le men bone.","E non fare come alcun pittore; i quali, stanchi con la lor fantasia, dismettono l’opera e fanno esercizio coll’andare a solazzo, riserbandosi una stanchezza nella mente, la quale non che vegghino o ponghin mente varie cose, ma spesse volte, scontrando li amici o parenti, essendo da quelli salutati, non che li vedino o sentino, non altrementi sono conosciuti, come s’elli scontrassino altrettant’aria."],"cs":["Duch malíře má být podoben zrcadlu, které se vždy proměňuje v barvu té věci, kterou má před sebou, a naplňuje se tolika podobami, kolik je věcí, jež jsou postaveny proti němu.","Víš-li tedy, malíři, že nemůžeš být dobrý, nejsi-li všestranným mistrem v napodobování svým uměním všech druhů tvarů, které plodí příroda – a ty nebudeš umět udělat, jestliže je nevidíš a neuchováš je v mysli –, pak, když chodíš po krajině, hleď, aby se tvůj úsudek obracel k rozličným předmětům a postupně pozoroval hned tuto věc, hned onu, a dělej si svazek rozličných věcí vybraných a vyvolených z méně dobrých.","A nedělej jako někteří malíři, kteří, unaveni svou obrazotvorností, odkládají dílo a dávají si cvičení procházkou pro potěšení, nesouce si v mysli únavu, která nejenže nevidí ani nevnímá různé věci, ale často, potkají-li přátele či příbuzné a jsou jimi pozdraveni, nejenže je nevidí ani neslyší, ale poznávají je o nic víc, než kdyby potkali pouhý vzduch."],"ref":{"s":"Ash.II","l":1,"st":"r","z":false,"raw":"Ash. II. 1 r"},"ca":[]},{"id":"s233","o":"Pensieri sulla scienza","c":"LXXXVII","str":105,"ni":"altro consiglio","nc":"Jiná rada","it":["Il pittore deve essere solitario e considerare ciò ch’esso vede, e parlare con seco, eleggendo le parti più eccellenti delle spezie di qualunque cosa lui vede, facendo a similitudine dello specchio, il quale si trasmuta in tanti colori, quanti sono quelli delle cose, che se li pongono dinanzi. E facendo così, lui parrà essere seconda Natura."],"cs":["Malíř má být osamělý a uvažovat o tom, co vidí, a rozmlouvat sám se sebou, vybíraje nejvýtečnější části z podob každé věci, kterou vidí, a jednaje po způsobu zrcadla, které se proměňuje v tolik barev, kolik je barev věcí, jež jsou před ně postaveny. A bude-li tak činit, bude se zdát, že je druhou přírodou."],"ref":{"s":"Lu","l":58,"st":"","z":false,"raw":"Lu. 58"},"ca":[]},{"id":"s234","o":"Pensieri sulla scienza","c":"LXXXVIII","str":106,"ni":"consiglio","nc":"Rada","it":["La mente del pittore si deve al continuo trasmutare in tanti discorsi, quante sono le figure delli obbietti notabIII, che dinanzi gli appariscano; e a quelle fermar il passo, e notarli, e fare sopra esse regole, considerando il loco e le circostanze, e lumi e ombre."],"cs":["Mysl malíře se má ustavičně proměňovat v tolik úvah, kolik je tvarů pozoruhodných předmětů, které se před ním objevují; a u nich se zastavit a zaznamenat je a vyvozovat z nich pravidla, uvažuje místo a okolnosti, světla a stíny."],"ref":{"s":"L","l":53,"st":"","z":false,"raw":"L. 53"},"ca":[]},{"id":"s235","o":"Pensieri sulla scienza","c":"LXXXIX","str":106,"ni":"vita del pittore filosofo ne’ paesi","nc":"Život malíře filozofa na venkově","it":["Al pittore è necessario la matematica appartenente a essa pittura e la privazione de’ compagni, che son alieni dalli loro studi, e cervello mutabile secondo la varietà delli obbietti, che dinanzi se li oppongono, e remoto da altre cure.","E s’è nella contemplazione e definizione d’un caso, come accade quando l’obbietto muove il senso, allora di tali casi si deve giudicare quale è di più faticosa definizione, e quello seguitare insino alla sua ultima chiarezza, e poi seguitare la definizione dell’altro.","E sopra tutto essere di mente eguale a la superfizie dello specchio, la quale si trasmuta in tanti vari colori, quanti sono li colori delli sua obbietti; e le sue compagnie abbino similitudine con lui in tali studi, e, non le trovando, usi con sè medesimo nelle sue contemplazioni, che infine non troverà più utile compagnia."],"cs":["Malíř potřebuje matematiku příslušející malířství a odloučení od druhů, kteří jsou cizí jeho studiím, a mozek proměnlivý podle rozmanitosti předmětů, jež se před ním stavějí, a prostý jiných starostí.","A je-li v rozjímání a definování nějakého případu, jak se stává, když předmět pohne smyslem, pak je třeba z takových případů posoudit, který je nejobtížnější definovat, a sledovat jej až do jeho konečné jasnosti, a teprve potom pokračovat v definici dalšího.","A především mít mysl rovnou povrchu zrcadla, který se proměňuje v tolik různých barev, kolik je barev jeho předmětů; a jeho společníci ať se mu v takových studiích podobají, a nenajde-li je, ať se obírá sám se sebou ve svých rozjímáních, neboť nakonec nenajde užitečnější společnost."],"ref":{"s":"C.A","l":181,"st":"v","z":false,"raw":"C. A. 181 v"},"ca":[989,991]},{"id":"s236","o":"Pensieri sulla scienza","c":"XC","str":107,"ni":"necessità della analisi","nc":"Nezbytnost rozboru","it":["Noi conosciamo chiaramente, che la vista è delle veloci operazioni che sia, e in un punto vede infinite forme, nientedimeno non comprende se non è una cosa per volta. Poniamo caso: tu, lettore, guarderai in una occhiata tutta questa carta scritta, e subito giudicherai, questa essere piena di varie lettere, ma non cognoscerai in questo tempo, che lettere sieno, nè che voglian dire; onde ti bisogna fare a parola a parola, verso per verso, a voler avere notizia d’esse lettere: ancora, se vorrai montare a l’altezza d’un edifizio ti converrà salire a grado a grado, altrementi fia impossibile pervenire alla sua altezza.","E così dico a te, il quale la Natura volge a quest’arte, se vogli avere vera notizia delle forme delle cose, comincierai alle particule di quelle, e non andare alla seconda, se prima non hai bene nella memoria e nella pratica la prima; e se altro farai, getterai via il tempo e veramente allungherai assai lo studio. E ricordoti ch’impari primo la diligenza, che la prestezza."],"cs":["Jasně víme, že zrak je z nejrychlejších činností, jaké jsou, a v jednom okamžiku vidí nekonečně mnoho tvarů, a přesto chápe jen jednu věc najednou. Dejme tomu: ty, čtenáři, přehlédneš jedním pohledem celý tento popsaný list a hned usoudíš, že je plný různých písmen, ale v tu chvíli nepoznáš, jaká písmena to jsou ani co chtějí říci; proto musíš postupovat slovo za slovem, řádek za řádkem, chceš-li poznat ta písmena; a také chceš-li dosáhnout výšky nějaké budovy, musíš stoupat stupeň za stupněm, jinak bude nemožné dojít až k její výšce.","A tak pravím tobě, kterého příroda obrací k tomuto umění: chceš-li mít pravé poznání tvarů věcí, začneš od jejich drobných částí a nepůjdeš k druhé, dokud nemáš dobře v paměti a v praxi tu první; a budeš-li dělat jinak, promrháš čas a věru studium značně prodloužíš. A připomínám ti, abys se nejprve naučil pečlivosti, a teprve potom rychlosti."],"ref":{"s":"Ash.I","l":28,"st":"r","z":false,"raw":"Ash. I. 28 r"},"ca":[]},{"id":"s237","o":"Pensieri sulla scienza","c":"XCI","str":108,"ni":"carattere delle opere di leonardo","nc":"Povaha Leonardových spisů","it":["Cominciato in Firenze in casa Piero di Braccio Martelli addi 22 di marzo 1508; e questo fia un raccolto sanza ordine, tratto di molte carte, le quali io ho qui copiate, sperando poi metterle per ordine alli lochi loro, secondo le materie di che esse tratteranno; e credo che, avanti ch’io sia al fine di questo, io ci avrò a riplicare una medesima cosa più volte; sì che, lettore, non mi biasimare, perchè le cose son molte e la memoria non le può riservare e dire: — questa non voglio scrivere, perchè dinanzi la scrissi —; e se io non volessi cadere in tale errore, sarebbe necessario che, per ogni caso ch’io volessi copiare, sicchè per non replicarlo, io avessi sempre a rileggere tutto il passato, e massime stando co’ lunghi intervalli di tempo allo scrivere da una volta all’altra."],"cs":["Započato ve Florencii v domě Piera di Braccio Martelliho dne 22. března 1508; a bude to sbírka bez pořádku, vybraná z mnoha listů, které jsem sem opsal v naději, že je potom uspořádám na jejich místa podle látek, o nichž budou pojednávat; a věřím, že než dojdu na konec, budu tu muset opakovat jednu a tutéž věc vícekrát; proto mě, čtenáři, nehaň, neboť věcí je mnoho a paměť je nemůže uchovat a říci: „Tohle nechci psát, protože jsem to napsal už dříve“; a kdybych nechtěl upadnout do takového omylu, bylo by nutné, abych u každého případu, který bych chtěl opsat, abych jej neopakoval, musel vždy znovu přečíst všechno předchozí, a zvláště když mezi jednotlivým psaním ubíhají dlouhé časové přestávky."],"ref":{"s":"R","l":4,"st":"","z":false,"raw":"R. 4"},"ca":[],"rr":"Br. M. 1 a"},{"id":"s238","o":"Pensieri sulla scienza","c":"XCII","str":109,"ni":"suo desiderio insaziabile di conoscere","nc":"Jeho neukojitelná touha po poznání","it":["Non fa sì gran mugghio il tempestoso mare, quando il settentrionale aquilone lo ripercote, colle schiumose onde, fra Scilla e Cariddi; nè Stromboli o Mongibello, quando le sulfuree fiamme, per forza rompendo e aprende il gran monte, fulminano per l’aria pietre, terra, insieme coll’uscita e vomitata fiamma; nè quando le infocate caverne di Mongibello, rivomitando il male tenuto elemento, spigniendolo alla sua regione, con furia cacciano innanzi qualunque ostacolo s’interpone alla sua impetuosa furia.... E tirato dalla mia bramosa voglia, vago di vedere la gran commistione delle varie e strane forme fatte dalla artifiziosa natura, raggiratomi alquanto in fra gli ombrosi scogli, pervenni all’entrata d’una gran caverna, dinanzi alla quale, — restando alquanto stupefatto e ignorante di tal cosa, — piegato le mie rene in arco, e ferma la stanca mano sopra il ginocchio, colla destra mi feci tenebra alle abbassate e chiuse ciglia. E spesso piegandomi in qua e in là per vedere dentro vi discernessi alcuna cosa, questo vietatomi per la grande oscurità, che là entro era, — e stato alquanto, — subito si destarono in me due cose: paura e desiderio; paura per la minacciosa oscura spelonca, desiderio per vedere se là entro fussi alcuna miracolosa cosa."],"cs":["Tak velký řev nevydává bouřlivé moře se svými zpěněnými vlnami mezi Skyllou a Charybdou, když je bičuje severní vichr Aquilo; ani Stromboli či Mongibello, když sirné plameny, násilím rozrážejíce a otevírajíce velkou horu, metají vzduchem kameny a zemi spolu s vyrážejícím a vyvrhovaným plamenem; ani když rozžhavené jeskyně Mongibella, vyvrhujíce znovu špatně držený živel a ženouce jej do jeho říše, zuřivě vyhánějí před sebou každou překážku, která se staví do cesty jeho prudké zuřivosti… A puzen svou dychtivou touhou, toužící spatřit velikou směsici rozmanitých a podivných tvarů, jež stvořila umná příroda, když jsem se chvíli toulal mezi stinnými skalisky, přišel jsem ke vchodu do veliké jeskyně, před níž – zůstav chvíli ohromen a nevědoucí, co je to za věc – shrbil jsem záda do oblouku, opřel unavenou ruku o koleno a pravicí jsem si zastínil sklopené a přimhouřené řasy. A často se nakláněje sem a tam, abych uvnitř něco rozeznal, což mi znemožňovala velká tma, jež tam uvnitř byla, – a když jsem tak chvíli stál, – náhle se ve mně probudily dvě věci: strach a touha; strach před hrozivou temnou slujou, touha uvidět, zda by tam uvnitř nebylo něco zázračného."],"ref":{"s":"R","l":1339,"st":"","z":false,"raw":"R. 1339"},"ca":[],"rr":"Br. M. 155 a"},{"id":"s239","o":"Pensieri sulla natura","c":"I","str":111,"ni":"proemio","nc":"Předmluva","it":["Vedendo io non potere pigliare materia di grande utilità o diletto, perche li omini, innanti a me nati, hanno preso per loro tutti l'utili e necessari temi, farò come colui, il quale, per povertà, ghignel' ultimo alla fiera, e, non potendo d’altro fornirsi, piglia tutte cose già da altri viste, e non accettate, ma rifiutate per la loro poca valetudine.","Io questa disprezzata e rifiutata mercanzia, rimanente de’ molti compratori, metterò sopra la mia debole soma, e con quella, non per le grosse città, ma povere ville andrò distribuendo, e pigliando tal premio, qual merita la cosa da me data."],"cs":["Vida, že nemohu zvolit látku velkého užitku či potěšení, neboť lidé, kteří se narodili přede mnou, si vzali všechna užitečná a potřebná témata, učiním jako ten, kdo pro chudobu přijde na trh poslední, a nemoha se zásobit ničím jiným, vezme všechny věci, které už jiní viděli a nepřijali, nýbrž odmítli pro jejich malou cenu.","Já toto opovrhované a odmítnuté zboží, pozůstatek po mnoha kupcích, naložím na svůj slabý náklad a s ním budu chodit a rozdávat je ne po velkých městech, nýbrž po chudých vesnicích, a brát takovou odměnu, jakou si zaslouží věc mnou daná."],"ref":{"s":"C.A","l":119,"st":"r","z":false,"raw":"C. A. 119 r"},"ca":[652,654]},{"id":"s240","o":"Pensieri sulla natura","c":"II","str":112,"ni":"natura e scienza","nc":"Příroda a věda","it":["La natura è piena d’infinite ragioni, che non furono mai in isperienza."],"cs":["Příroda je plná nekonečných zákonitostí, které nikdy nebyly ve zkušenosti."],"ref":{"s":"I","l":18,"st":"r","z":false,"raw":"I. 18 r"},"ca":[]},{"id":"s241","o":"Pensieri sulla natura","c":"III","str":112,"ni":"leggi necessarie dominano i fatti della natura","nc":"Nutné zákony vládnou přírodním dějům","it":["La necessità è maestra e tutrice della natura.","La necessità è tema e inventrice della natura, è freno e regola eterna."],"cs":["Nutnost je učitelkou a poručnicí přírody.","Nutnost je námětem a vynálezkyní přírody, je uzdou a věčným pravidlem."],"ref":{"s":"R","l":1135,"st":"","z":false,"raw":"R. 1135"},"ca":[],"rr":"S. K. M. III. 49 a"},{"id":"s242","o":"Pensieri sulla natura","c":"IV","str":112,"ni":"la rispondenza degli effetti alla potenza della loro cagione e necessaria","nc":"Soulad účinků se silou jejich příčiny je nutný","it":["Ogni corpo sperico di densa e resistente superfice, mosso da pari potenza, farà tanto movimento con sua balzi, causati da duro e solido smalto, quanto a gettarlo libero per l’aria.","O mirabile giustizia di te, Primo Motore, tu non Lai voluto mancare a nessuna potenza l’ordine e qualità de’ sua necessari effetti! Conciò sia che una potenza deve cacciare 100 braccia una cosa vinta da lei, e quella nel suo obbedire trova intoppo: hai ordinato, che la potenza del colpo ricausi novo movimento, il quale, per diversi balzi, recuperi la intera somma del suo debito viaggio. E se tu misurerai la via fatta da detti balzi, tu troverai essere di tale lunghezza, qual sarebbe a trarre, con la medesima forza, una simil cosa libera per l’aria."],"cs":["Každé kulové těleso s hutným a pevným povrchem, pohnuté stejnou silou, vykoná svými odskoky, způsobenými tvrdou a pevnou dlažbou, tolik pohybu, jako kdyby bylo vrženo volně vzduchem.","Ó podivuhodná spravedlnosti tvá, první hybateli, nechtěl jsi, aby žádné síle chyběl řád a jakost jejích nutných účinků! Neboť má-li síla vyhnat do vzdálenosti 100 loket věc jí přemoženou, a ta při své poslušnosti narazí na překážku, ustanovil jsi, aby síla úderu znovu vyvolala nový pohyb, který různými odskoky získá zpět celý úhrn své povinné dráhy. A změříš-li dráhu vykonanou těmito odskoky, shledáš, že má takovou délku, jakou by měla, kdyby byla stejnou silou vržena podobná věc volně vzduchem."],"ref":{"s":"A","l":24,"st":"r","z":false,"raw":"A. 24 r"},"ca":[]},{"id":"s243","o":"Pensieri sulla natura","c":"V","str":113,"ni":"le leggi della natura sono imprescindibili","nc":"Přírodní zákony jsou neporušitelné","it":["Natura non rompe sua legge."],"cs":["Příroda neporušuje svůj zákon."],"ref":{"s":"E","l":43,"st":"v","z":false,"raw":"E. 43 v"},"ca":[]},{"id":"s244","o":"Pensieri sulla natura","c":"VI","str":113,"ni":"sul medesimo soggetto","nc":"K téže věci","it":["La natura è costretta dalla ragione della sua legge, che in lei infusamente vive."],"cs":["Příroda je vázána zákonitostí svého zákona, který v ní vrozeně žije."],"ref":{"s":"C","l":23,"st":"v","z":false,"raw":"C. 23 v"},"ca":[]},{"id":"s245","o":"Pensieri sulla natura","c":"VII","str":113,"ni":"l’effetto succede alla causa necessariamente","nc":"Účinek nutně následuje příčinu","it":["Quando alcuna cosa, cagione dell’altra, induce per suo movimento alcuno effetto, e’ bisogna che ’l movimento dell’effetto séguiti il movimento della cagione."],"cs":["Když nějaká věc, příčina jiné, vyvolá svým pohybem nějaký účinek, musí pohyb účinku následovat pohyb příčiny."],"ref":{"s":"C.A","l":337,"st":"v","z":false,"raw":"C. A. 337 v"},"ca":[1841,1843,1844]},{"id":"s246","o":"Pensieri sulla natura","c":"VIII","str":113,"ni":"il miracolo sta nella rispondenza dell’effetto alla sua causa","nc":"Zázrak spočívá v souladu účinku s jeho příčinou","it":["Qui le figure, qui li colori, qui tutte le spezie delle parti dell’universo son ridotte in un punto, e quel punto e di tanta maraviglia!","O mirabile e stupenda necessità, tu costringi, colla tua legge, tutti li effetti, pei brevissima via, a partecipare delle lor cause!","Questi sono li miracoli!","Scrivi nella tua Notomia, come, in tanto minimo spazio, l’immagine possa rinascere e ricomporsi nella sua dilatazione."],"cs":["Zde jsou tvary, zde barvy, zde jsou všechny podoby částí vesmíru staženy do jednoho bodu, a ten bod je tak podivuhodný!","Ó podivuhodná a úžasná nutnosti, ty svým zákonem nutíš všechny účinky, aby nejkratší cestou měly účast na svých příčinách!","To jsou ty zázraky!","Napiš ve své Anatomii, jak se v tak nepatrném prostoru může obraz znovu zrodit a znovu složit ve své plné šíři."],"ref":null,"ca":[]},{"id":"s247","o":"Pensieri sulla natura","c":"IX","str":114,"ni":"ogni cosa obbedisce alla propria legge","nc":"Každá věc poslouchá svůj vlastní zákon","it":["Esempio della saetta fra' nuvoli. — O potente e già animato strumento dell’artifiziosa natura, a te non valendo le tue gran forze, ti conviene abbandonare la tranquilla vita, e obbedire alla legge, che Iddio e ’l Tempo diede alla genitrice natura!","Oh! quante volte furono vedute le impaurite schiere de’ delfini e de’ gran tonni fuggire dall’empia tua furia; e tu, che, col veloce tremor dell’ali e colla forcelluta coda, fulminando, generavi nel mare subita tempesta, con gran busse e sommersione di navili, con grande ondamento, empiendo gli scoperti liti degli impauriti e sbigottiti pesci!","—"],"cs":["Příklad blesku mezi mračny. – Ó mocný a kdysi oživený nástroji umné přírody, když ti tvé velké síly nepomohly, musíš opustit poklidný život a poslechnout zákon, který Bůh a Čas dali rodičce přírodě!","Ó, kolikrát byla vídána vyděšená hejna delfínů a velkých tuňáků prchat před tvou krutou zuřivostí; a ty, jenž jsi rychlým chvěním křídel a rozeklaným ocasem, metaje blesky, vyvolával na moři náhlou bouři, s velkými nárazy a potápěním lodí, s mohutným vlněním, a zaplňoval obnažené břehy vystrašenými a zděšenými rybami!","–"],"ref":{"s":"R","l":156,"st":"r","z":false,"raw":"R. 156 r"},"ca":[],"rr":"E. 15 a"},{"id":"s248","o":"Pensieri sulla natura","c":"X","str":115,"ni":"passività e attività","nc":"Trpnost a činnost","it":["Molte volte una medesima cosa è tirata da due violenze: necessità e potenza. L’acqua piove, e la terra l’assorbisce per necessità d’omore; il sole la svelle non per necessità, ma per potenza."],"cs":["Mnohokrát je táž věc tažena dvěma násilími: nutností a mocí. Voda prší a země ji vsakuje z nutnosti vláhy; slunce ji vytrhuje nikoli z nutnosti, nýbrž mocí."],"ref":{"s":"T","l":39,"st":"r","z":false,"raw":"T. 39 r"},"ca":[]},{"id":"s249","o":"Pensieri sulla natura","c":"XI","str":115,"ni":"provvidenza della natura nella conformazione del corpo umano","nc":"Prozřetelnost přírody ve stavbě lidského těla","it":["Perchè l’occhio è finestra dell’anima ella è sempre con timore di perderlo, in modo tale ch’essendoli mossa una cosa dinanzi, che dia subito spavento all’omo, quello colle mani non soccorre il core, fonte della vita, nè ’l capo, ricettaculo del signore de’ sensi, nè audito, nè odorato o gusto, anzi subito lo spaventato senso: non bastando chiudere li occhi con sua coperchi serrati con somma forza, che subito lo rivolge in contraria parte; non sicurando ancora, vi pone la mano, e l’altra distende, facendo antiguardia contro al sospetto suo.","Ancora, la natura ha ordinato, che l’occhio de l’omo per sè medesimo col coperchio (si chiuda), acciò che, non sendo da esso dormiente guardato, d’alcuna cosa non sia offeso."],"cs":["Protože oko je oknem duše, je duše stále ve strachu, aby o ně nepřišla, a to tak, že pohne-li se před ním něco, co člověka náhle poleká, nechrání člověk rukama srdce, zdroj života, ani hlavu, sídlo pána smyslů, ani sluch, čich či chuť, nýbrž ihned polekaný smysl: nestačí mu zavřít oči víčky sevřenými vší silou, ale hned je odvrátí na opačnou stranu; a ještě si není jist, i položí na ně ruku a druhou natáhne, čině předstráž proti tomu, čeho se obává.","Dále příroda zařídila, aby se oko člověka samo od sebe zavíralo víčkem, aby, když je spící nehlídá, nebylo ničím poraněno."],"ref":{"s":"C.A","l":116,"st":"r","z":false,"raw":"C. A. 116 r"},"ca":[636,638]},{"id":"s250","o":"Pensieri sulla natura","c":"XII","str":116,"ni":"provvidenzialità della dilatazione e restringimento della pupilla","nc":"Prozřetelnost rozšiřování a zužování zornice","it":["La pupilla dell’occhio si muta in tante varie grandezze, guante son le va» eia delle chiarezze e oscurità delti oblnetll, che dinanzi se le rappresentano.","In questo caso la natura ha riparato alia virtù visiva, quando ella è offesa dalla soperchia luce, di ristrignere la pupilla dell’ occhio, e, quando è offesa dalle diverse oscurità, d’allargare essa luce a similitudine della bocca della borsa. E fa qui la natura, come quel che ha troppo lume alla sua abitazione, che serra una mezza finestra, e più o men, secondo la necessità quando viene la notte, esso apre tutta essa finestra, per vedere meglio dentro a detta abitazione. E usa qui la natura una continua equazione, col continuo temperare e ragguagliare, col crescere la pupilla e diminuirla a proporzione delle predette oscurità o chiarezze, che dinanzi al continuo se le rappresentano."],"cs":["Zornice oka se mění v tolik různých velikostí, kolik je rozdílů jasu a temnoty předmětů, které se před ní objevují.","V tomto případě příroda opatřila zrakovou schopnost tak, že když je zraňována přílišným světlem, zúží zornici oka, a když je zraňována rozličnou temnotou, rozšíří ten otvor pro světlo po způsobu ústí měšce. A činí tu příroda jako ten, kdo má ve svém obydlí příliš mnoho světla a zavře půl okna, víc či méně podle potřeby, a když přijde noc, otevře celé okno, aby lépe viděl uvnitř toho obydlí. A užívá tu příroda ustavičného vyrovnávání, ustavičně mírníc a vyvažujíc, zvětšujíc zornici a zmenšujíc ji úměrně řečeným temnotám či jasům, které se před ní ustavičně objevují."],"ref":{"s":"D","l":5,"st":"r","z":false,"raw":"D. 5 r"},"ca":[]},{"id":"s251","o":"Pensieri sulla natura","c":"XIII","str":117,"ni":"contro coloro che si arrogano di correggere la natura","nc":"Proti těm, kdo si osobují opravovat přírodu","it":["L’atto del tagliare la narice ai cavalli è cosa meritevole di riso. E questi stolti osservan questa usanza, quasi come se credessino la natura avere mancato ne’ necessarie cose, per le quali li omini abbiano a essere sua correttori. Ell’ha fatti i due busi del naso, i quali, ciascuno per se, è per la metà della larghezza della canna de’ polmoni, donde esala l’anelito, e, quando essi busi non fussino, la bocca sarebbe abbastanza a esso abbondevole anelito. E se tu mi dicessi: — perchè ha fatto questa natura le narici alli animali, se l’alitare per la bocca è soffiziente? — io ti risponderei, che le narici sono fatte per essere usate, quando la bocca è in esercizio di masticare il suo cibo."],"cs":["Prořezávání nozder koním je věc k smíchu. A tito hlupáci dodržují ten zvyk, jako by věřili, že příroda selhala v nutných věcech, takže by lidé měli být jejími opravovateli. Ona udělala dva otvory v nose, z nichž každý sám o sobě má polovinu šíře průdušnice, kudy vychází dech, a kdyby těch otvorů nebylo, stačila by k tomu hojnému dechu ústa. A kdybys mi řekl: „Proč tedy příroda udělala zvířatům nozdry, když dýchání ústy stačí?“, odpověděl bych ti, že nozdry jsou udělány k tomu, aby se jich užívalo, když ústa jsou zaměstnána žvýkáním potravy."],"ref":{"s":"C.A","l":76,"st":"r","z":false,"raw":"C. A. 76 r"},"ca":[412,414]},{"id":"s252","o":"Pensieri sulla natura","c":"XIV","str":117,"ni":"sul fenomeno della spinta delle radici","nc":"O jevu tlaku kořenů","it":["L’albero in qualche parte scorticato, la natura, che a esso provvede, volta a essa iscorticazione molto maggior somma di notritivo omore, che in alcuno altro loco; in modo che, per lo primo detto mancamento, li cresce molto più grossa la scorza, che in alcun altro loco. Ed è tanto movente ess’omore, che, giunto al soccorso loco, si leva parte in alto, a uso di balzo di palla, con diversi pullulamenti, o ver germugliamenti, non altrementi ch’una bollente acqua."],"cs":["Je-li strom na některém místě oloupán, příroda, která o něj pečuje, obrací k tomu oloupanému místu mnohem větší množství výživné šťávy než kamkoli jinam, takže kvůli zmíněnému nedostatku mu tam naroste kůra mnohem silnější než kdekoli jinde. A ta šťáva je tak pohyblivá, že když dorazí na místo, kterému má pomoci, zvedne se zčásti vzhůru jako odskok míče, rozličným rašením neboli pučením, ne jinak než vroucí voda."],"ref":null,"ca":[]},{"id":"s253","o":"Pensieri sulla natura","c":"XV","str":118,"ni":"sulla struttura delle ali","nc":"O stavbě křídel","it":["Li timoni, creati nelli omeri che han l'ali delli uccelli, son trovati dalla ingegnosa natura per un comodo piegamento del retto impeto, che spesso accade nel furioso volare delli uccelli; perchè trovò esser molto più comodo, nel retto furore, a piegare una minima parte dell'ala, che il loro tutto."],"cs":["Kormidla, vytvořená v plecích, které nesou křídla ptáků, vynalezla důmyslná příroda pro pohodlné ohnutí přímého náporu, k němuž často dochází při prudkém letu ptáků; neboť shledala, že je při přímém náporu mnohem pohodlnější ohnout nepatrnou část křídla než celé křídlo."],"ref":{"s":"E","l":52,"st":"v","z":false,"raw":"E. 52 v"},"ca":[]},{"id":"s254","o":"Pensieri sulla natura","c":"XVI","str":118,"ni":"sulla disposizione delle foglie nelle piante","nc":"O uspořádání listů na rostlinách","it":["Ha messo la natura la foglia degli ultimi rami di molte piante, che sempre la sesta foglia è sopra la prima, e così segue successivamente, se la regola non è impedita. E questo ha fatto per due utilità d’esse piante: la prima e perchè nascendo il ramo e ’l frutto nell’anno seguente dalla gemella dell’occhio, ch’è sopra in contatto dell’appiccatura della foglia; l’acqua, che bagna tal ramo, possa discendere a nutrire tal gemella, col fermarsi la goccia nella concavità del nascimento di essa foglia. Ed il secondo giovamento è, che nascendo tali rami, l’anno seguente, l’uno non cuopre l’altro, perchè nascono volti a cinque aspetti, li cinque rami."],"cs":["Příroda umístila listy na posledních větvích mnoha rostlin tak, že šestý list je vždy nad prvním, a tak to pokračuje dál, není-li pravidlo porušeno. A to učinila pro dvojí užitek těch rostlin: první je ten, že protože větev a plod v následujícím roce vyrůstají z pupenu v očku, které je nahoře v dotyku s úponem listu, může voda, která takovou větev smáčí, stékat a živit ten pupen, neboť se kapka zastaví v prohlubni, kde list vyrůstá. A druhý prospěch je ten, že když takové větve v následujícím roce vyrůstají, jedna nezakrývá druhou, neboť pět větví vyrůstá obráceno k pěti stranám."],"ref":{"s":"Lu","l":398,"st":"","z":false,"raw":"Lu. 398"},"ca":[]},{"id":"s255","o":"Pensieri sulla natura","c":"XVII","str":119,"ni":"legge universale delle cose","nc":"Všeobecný zákon věcí","it":["Naturalmente ogni cosa desidera mantenersi in suo essere."],"cs":["Přirozeně každá věc touží uchovat se ve svém bytí."],"ref":{"s":"A","l":60,"st":"r","z":false,"raw":"A. 60 r"},"ca":[]},{"id":"s256","o":"Pensieri sulla natura","c":"XVIII","str":119,"ni":"sul medesimo soggetto","nc":"K téže věci","it":["Universalmente tutte le cose desiderano mantenersi in sua natura, onde il corso de l’acqua, che si move, cerca mantenere il suo corso, secondo la potenza della sua cagione, e, se trova contrastante opposizione, finisce la lunghezza del cominciato corso per movimento circulare e retorto."],"cs":["Obecně všechny věci touží uchovat se ve své přirozenosti, a proto tok vody, která se pohybuje, se snaží udržet svůj tok podle síly své příčiny, a narazí-li na odporující překážku, dokončí délku započatého toku krouživým a zakřiveným pohybem."],"ref":null,"ca":[]},{"id":"s257","o":"Pensieri sulla natura","c":"XIX","str":120,"ni":"le cose fuori del loro stato naturale tendono a ritornarvi","nc":"Věci mimo svůj přirozený stav se do něj snaží vrátit","it":["Tutti li elementi, fori del loro naturale sito, desiderano a esso sito ritornare, e massime foco, acqua e terra."],"cs":["Všechny živly, jsou-li mimo své přirozené místo, touží se na to místo vrátit, a zvláště oheň, voda a země."],"ref":{"s":"C","l":26,"st":"v","z":false,"raw":"C. 26 v"},"ca":[]},{"id":"s258","o":"Pensieri sulla natura","c":"XX","str":120,"ni":"legge del minimo sforzo","nc":"Zákon nejmenšího úsilí","it":["Ogni peso desidera cadere al centro per la via più breve."],"cs":["Každá tíže touží padat ke středu nejkratší cestou."],"ref":{"s":"C","l":28,"st":"v","z":false,"raw":"C. 28 v"},"ca":[]},{"id":"s259","o":"Pensieri sulla natura","c":"XXI","str":120,"ni":"ogni parte desidera essere nel suo tutto","nc":"Každá část touží být ve svém celku","it":["Ogni parte ha inclinazion di ricongiugnersi al suo tutto, per fuggire dalla sua imperfezione: l’anima desidera stare col suo corpo, perchè, sanza li strumenti organici di tal corpo, nulla può oprare, nè sentire."],"cs":["Každá část má sklon znovu se spojit se svým celkem, aby unikla své nedokonalosti: duše touží být se svým tělem, neboť bez ústrojných nástrojů toho těla nemůže nic konat ani cítit."],"ref":{"s":"C.A","l":59,"st":"r","z":false,"raw":"C. A. 59 r"},"ca":[328,330,332]},{"id":"s260","o":"Pensieri sulla natura","c":"XXII","str":120,"ni":"suggetto colla forma","nc":"Subjekt a forma","it":["Muovesi l’amato per la cos’amata, come il senso colla sensibile, e con seco s’unisce, e fassi una cosa medesima.","L’opera è la prima cosa che nasce dall’unione. Se la cosa amata è vile, l’amante si fa vile. Quando la cosa unita è conveniente al suo unitore, lì séguita dilettazione e piacere e saddisfazione.","Quando l’amante è giunto all’amato, lì si riposa; quando il peso è posato, lì si riposa. La cosa conosciuta col nostro intelletto...."],"cs":["Milující se pohybuje k milované věci jako smysl k vnímatelnému, spojuje se s ní a stává se jednou a toutéž věcí.","Dílo je první věc, která se rodí ze spojení. Je-li milovaná věc nízká, stává se nízkým i milující. Když je spojená věc přiměřená tomu, kdo ji spojuje, následuje rozkoš, potěšení a uspokojení.","Když milující dospěje k milovanému, tam spočine; když je tíže položena, tam spočine. Věc poznaná naším rozumem…"],"ref":{"s":"T","l":6,"st":"r","z":false,"raw":"T. 6 r"},"ca":[]},{"id":"s261","o":"Pensieri sulla natura","c":"XXIII","str":121,"ni":"legge del minimo sforzo","nc":"Zákon nejmenšího úsilí","it":["Ogni azione naturale è fatta per la via brevissima."],"cs":["Každý přírodní děj probíhá nejkratší cestou."],"ref":{"s":"G","l":74,"st":"v","z":false,"raw":"G. 74 v"},"ca":[]},{"id":"s262","o":"Pensieri sulla natura","c":"XXIV","str":121,"ni":"la stessa","nc":"Týž zákon","it":["Ogni azione naturale è fatta da essa natura, nel più breve modo e tempo che sia possibile."],"cs":["Každý přírodní děj koná příroda sama nejkratším způsobem a v nejkratším čase, jaký je možný."],"ref":{"s":"D","l":4,"st":"r","z":false,"raw":"D. 4 r"},"ca":[]},{"id":"s263","o":"Pensieri sulla natura","c":"XXV","str":121,"ni":"ancora la stessa","nc":"Opět týž zákon","it":["Nessuna azion naturale si può abbreviare. Ogni azion naturale è generata dalla natura nel più brieve modo, che trovar si possa."],"cs":["Žádný přírodní děj nelze zkrátit. Každý přírodní děj je přírodou vytvořen nejkratším způsobem, jaký lze nalézt."],"ref":{"s":"C.A","l":112,"st":"v","z":true,"raw":"C. A. 112 v"},"ca":[619,621]},{"id":"s264","o":"Pensieri sulla natura","c":"XXVI","str":121,"ni":"la natura e variabile in infinito","nc":"Příroda je nekonečně proměnlivá","it":["Ed è tanto dilettevole natura e copiosa nel variare, che infra li alberi della medesima natura non si troverebbe una pianta, ch’appresso somigliassi all’altra, e non che le piante, ma li rami o foglie, o frutti di quelle, non si troverà uno, che precisamente somigli a un altro."],"cs":["A příroda je tak líbezná a hojná v obměňování, že mezi stromy téhož druhu by se nenašla rostlina, která by se zblízka podobala jiné; a nejen rostliny, ale ani z jejich větví, listů či plodů se nenajde jediný, který by se přesně podobal jinému."],"ref":{"s":"C.A","l":112,"st":"v","z":false,"raw":"C. A. 112 v"},"ca":[619,621]},{"id":"s265","o":"Pensieri sulla natura","c":"XXVII","str":122,"ni":"contro gli alchimisti","nc":"Proti alchymistům","it":["I bugiardi interpetri di natura affermano lo argento vivo essere comune semenza a tutti i metalli, non si ricordando che la natura varia le semenze, secondo la diversità delle cose, che essa vuole produrre al mondo."],"cs":["Lživí vykladači přírody tvrdí, že rtuť je společným semenem všech kovů, a nevzpomínají, že příroda obměňuje semena podle rozdílnosti věcí, které chce na svět přivést."],"ref":{"s":"Lu","l":501,"st":"","z":false,"raw":"Lu. 501"},"ca":[]},{"id":"s266","o":"Pensieri sulla natura","c":"XXVIII","str":122,"ni":"ancora sulla varietà della natura","nc":"Opět o rozmanitosti přírody","it":["Se la natura avesse ferma una sola regola nella qualità delle membra, tutti i visi delli omini sarebbono somiglianti in tal modo, che l’uno dall’altro non si potrebbe conoscere; ma ell’ ha ’n tal modo variato i cinque membri del volto, che, ben ch’ell’abbi fatto regola quasi universale alla loro grandezza, lei non l’ha osservata nella qualità, in modo tale che l’un dall’altro chiaramente conoscere si può."],"cs":["Kdyby příroda měla pevně jediné pravidlo pro jakost údů, byly by si všechny lidské tváře tak podobné, že by se jedna od druhé nedala rozeznat; ale ona obměnila pět částí obličeje tak, že ačkoli učinila pro jejich velikost pravidlo téměř všeobecné, nedodržela je v jakosti, takže se jedna od druhé dá jasně rozeznat."],"ref":{"s":"C.A","l":76,"st":"r","z":false,"raw":"C. A. 76 r"},"ca":[412,414]},{"id":"s267","o":"Pensieri sulla natura","c":"XXIX","str":122,"ni":"precetto al pittore","nc":"Pokyn malíři","it":["Dico: le misure universali si debbono osservare nelle lunghezze delle figure, e non nelle grossezze, perchè delle laudabili e maravigliose cose, ch’appariscono nelle opere della natura, è che nissuna opera, in qualunque spezie per se, l’un particulare con precisione si somiglia l’un a l' altro: adunque, tu, imitatore di tal natura, guarda e attendi alla varietà de’ lineamenti."],"cs":["Pravím: všeobecné míry se mají dodržovat v délkách postav, a ne v tloušťkách, neboť k chvályhodným a podivuhodným věcem, které se zjevují v dílech přírody, patří to, že žádné dílo v kterémkoli druhu se svými jednotlivostmi přesně nepodobá jedno druhému; ty tedy, napodobiteli takové přírody, hleď a dbej na rozmanitost rysů."],"ref":{"s":"C.A","l":1119,"st":"r","z":false,"raw":"C. A. 1119 r"},"ca":[]},{"id":"s268","o":"Pensieri sulla natura","c":"XXX","str":123,"ni":"precetto","nc":"Pokyn","it":["Sommo difetto è ne’ maestri, li quali usano replicare li medesimi moti nelle medesime storie, vicini l’uno all’altro, e similmente le bellezze de’ visi essere sempre una medesima; le quali in natura mai si trova essere replicate, in modo che, se tutte le bellezze d’eguale eccellenza ritornassin vive, esse sarebbon maggior numero di popolo, che quello, ch’al nostro secolo si trova; e, siccome in esso secolo nessuno precisamente si somiglia, il medesimo interverrebbe nelle dette bellezze."],"cs":["Největší vadou je u mistrů, kteří mají ve zvyku opakovat tytéž pohyby v týchž výjevech, jeden blízko druhého, a podobně že krása tváří je u nich vždy jedna a táž; ta se však v přírodě nikdy neopakuje, takže kdyby všechny krásy stejné výtečnosti znovu ožily, byly by početnějším lidem, než jaký se nachází v našem věku; a jako se v tomto věku nikdo přesně nepodobá jinému, totéž by se stalo s řečenými krásami."],"ref":{"s":"Lu","l":270,"st":"","z":false,"raw":"Lu. 270"},"ca":[]},{"id":"s269","o":"Pensieri sulla natura","c":"XXXI","str":123,"ni":"vi è una omogeneità di struttura negli esseri animati","nc":"V oduševnělých bytostech je jednotná stavba","it":["Facile cosa è, a chi sa l’omo, farsi poi universale; imperocchè tutti li animali terrestri han similitudine di membra, cioè muscoli e ossa, e nulla si variano, se non in lunghezza o in grossezza, come sarà dimostro nella Notomia; ecci poi li animali d’acqua, che son di molte varietà, de li quali non persuaderò il pictore che vi faccia regola, perche son quasi d’infinite varietà, e così li animali insetti."],"cs":["Je snadné, kdo zná člověka, stát se pak všestranným; neboť všechna suchozemská zvířata mají podobné údy, totiž svaly a kosti, a nijak se neliší, leda v délce či tloušťce, jak bude ukázáno v Anatomii; pak jsou tu vodní živočichové, kteří jsou velmi rozmanití, a o nich nebudu malíře přemlouvat, aby si pro ně dělal pravidlo, protože jsou téměř nekonečně rozmanití, a stejně tak hmyz."],"ref":{"s":"Lu","l":107,"st":"","z":false,"raw":"Lu. 107"},"ca":[]},{"id":"s270","o":"Pensieri sulla natura","c":"XXXII","str":124,"ni":"concetto dell’energia","nc":"Pojem energie","it":["Impeto e impressione di moto trasmutato dal motore nel mobile.","Ogni impressione attende alla permanenza over desidera permanenza.","Che ogni impressione desidera permanenza provasi nella impressione fatta dal sole nell’occhio d’esso risguardatore, e nella impression del sono, fatto dal martello di tal campana percussore.","Ogni impressione desidera permanenza, come ci mostra il simulacro del moto impresso nel mobile."],"cs":["Impetus a vtisk pohybu přenesený z hybatele na pohybované.","Každý vtisk usiluje o trvání čili touží po trvání.","Že každý vtisk touží po trvání, dokazuje vtisk, který slunce způsobí v oku toho, kdo se naň dívá, a vtisk zvuku, který vydá kladivo udeřivší do zvonu.","Každý vtisk touží po trvání, jak nám ukazuje obraz pohybu vtisknutého pohybovanému."],"ref":{"s":"G","l":73,"st":"r","z":true,"raw":"G. 73 r"},"ca":[]},{"id":"s271","o":"Pensieri sulla natura","c":"XXXIII","str":124,"ni":"legge universale","nc":"Všeobecný zákon","it":["Ogni azione bisogna che s’eserciti per moto."],"cs":["Každý děj se musí uskutečňovat pohybem."],"ref":{"s":"G","l":73,"st":"r","z":false,"raw":"G. 73 r"},"ca":[]},{"id":"s272","o":"Pensieri sulla natura","c":"XXXIV","str":124,"ni":"la stessa","nc":"Týž zákon","it":["Il moto è causa d’ogni vita."],"cs":["Pohyb je příčinou veškerého života."],"ref":{"s":"T","l":36,"st":"v","z":false,"raw":"T. 36 v"},"ca":[]},{"id":"s273","o":"Pensieri sulla natura","c":"XXXV","str":125,"ni":"definizione della forza","nc":"Definice síly","it":["Che cosa è la forza?","Forza dico essere una virtù spirituale, una potenza invisibile, la quale, per accidentale esterna violenza, è causata dal moto e collocata e infusa ne’ corpi, i quali sono dal loro naturale uso ritratti, dando a quelli vita attiva di maravigliosa potenza."],"cs":["Co je síla?","Síla, pravím, je duchovní moc, neviditelná schopnost, která je náhodným vnějším násilím způsobena pohybem a uložena a vlita do těles, jež jsou vytržena ze svého přirozeného způsobu, a dává jim činný život podivuhodné moci."],"ref":{"s":"T","l":36,"st":"v","z":false,"raw":"T. 36 v"},"ca":[]},{"id":"s274","o":"Pensieri sulla natura","c":"XXXVI","str":125,"ni":"la stessa","nc":"Táž definice","it":["Che cosa è forza?","Forza dico essere una potenza spirituale, incorporea, invisibile, la quale, con breve vita, si causa nei corpi, che per un’accidentale violenza si trovano fuori del loro essere e riposo naturale."],"cs":["Co je síla?","Síla, pravím, je duchovní, netělesná, neviditelná moc, která s krátkým životem vzniká v tělesech, jež se náhodným násilím ocitnou mimo své přirozené bytí a klid."],"ref":{"s":"H","l":141,"st":"r","z":false,"raw":"H. 141 r"},"ca":[]},{"id":"s275","o":"Pensieri sulla natura","c":"XXXVII","str":125,"ni":"la materia è inerte","nc":"Hmota je netečná","it":["Nessuna cosa insensata per sè si move, ma il suo moto è fatto da altri."],"cs":["Žádná věc bez smyslů se nepohybuje sama od sebe, ale její pohyb je způsoben jiným."],"ref":{"s":"A","l":34,"st":"r","z":false,"raw":"A. 34 r"},"ca":[]},{"id":"s276","o":"Pensieri sulla natura","c":"XXXVIII","str":125,"ni":"legge della trasmissione del moto e della sua equivalenza","nc":"Zákon přenosu pohybu a jeho rovnocennosti","it":["L’impeto è una virtù creata dal moto e trasmutata dal motore al suo mobile, il quale mobile ha tanto di moto, quanto l’impeto ha di vita."],"cs":["Impetus je síla vytvořená pohybem a přenesená z hybatele na jím pohybované těleso, a to těleso má tolik pohybu, kolik má impetus života."],"ref":{"s":"B","l":63,"st":"r","z":false,"raw":"B. 63 r"},"ca":[]},{"id":"s277","o":"Pensieri sulla natura","c":"XXXIX","str":126,"ni":"principio d’inerzia","nc":"Princip setrvačnosti","it":["Ogni moto naturale e continuo desidera conservare suo corso per la linia del suo principio, cioè, in qualunque loco esso si varia, domando principio."],"cs":["Každý přirozený a souvislý pohyb touží zachovat svůj běh po přímce svého počátku; totiž kdekoli se mění, tam to nazývám počátkem."],"ref":{"s":"P","l":74,"st":"v","z":false,"raw":"P. 74 v"},"ca":[]},{"id":"s278","o":"Pensieri sulla natura","c":"XL","str":126,"ni":"origine della forza","nc":"Původ síly","it":["La forza da carestia o dovizia è generata, questa è figliola del moto materiale e nepote del moto spirituale, e madre e origine del peso. E esso peso è finito nell’elemento dell’acqua e terra, e essa forza è infinita, perchè con essa infiniti mondi si moverebbero, se strumenti far si potessero, dove essa forza generare si potesse.","La forza col moto materiale e ’l peso colla percussione son le quattro accidentali potenze, colle quali tutte l’opere de’ mortali hanno loro essere e lor morte.","La forza dal moto spirituale ha origine, il quale moto, scorrendo per le membra degli animali sensibIII, ingrossa i muscoli di quelli, onde, ingrossati, essi muscoli si vengono a raecortare e trarsi dirieto i nervi, che con essi son congiunti; e di qui si causa la forza per le membra umane.","La qualità e quantità delle forze d’uno uomo potrà partorire altra forza, la quale sarà proporzionevolmente tanto maggiore, quanto essa sarà di più lungo moto l’una che l' altra."],"cs":["Síla se rodí z nedostatku nebo z nadbytku; je dcerou hmotného pohybu a vnučkou pohybu duchovního, a matkou a původem tíže. A ta tíže je konečná v živlu vody a země, kdežto síla je nekonečná, neboť by se jí pohnulo nekonečně mnoho světů, kdyby se daly zhotovit nástroje, v nichž by se ta síla mohla zrodit.","Síla s hmotným pohybem a tíže s nárazem jsou čtyři nahodilé moci, jimiž mají všechna díla smrtelníků své bytí i svou smrt.","Síla má původ v duchovním pohybu, který, procházeje údy cítících živočichů, zbytňuje jejich svaly, a ty svaly, zbytnělé, se zkracují a táhnou za sebou šlachy, jež jsou s nimi spojeny; a z toho vzniká síla v lidských údech.","Jakost a množství sil jednoho člověka může zrodit jinou sílu, která bude úměrně o tolik větší, o kolik delší pohyb bude mít jedna než druhá."],"ref":{"s":"E","l":22,"st":"r","z":false,"raw":"E. 22 r"},"ca":[]},{"id":"s279","o":"Pensieri sulla natura","c":"XLI","str":127,"ni":"aspetti vari della forza","nc":"Rozličné podoby síly","it":["La gravità, la forza, e ’l moto accidentale, insieme colla percussione, son le quattro accidentali potenze colle quali tutte l’evidenti opere de’ mortali hanno loro essere e loro morte."],"cs":["Tíže, síla a nahodilý pohyb spolu s nárazem jsou čtyři nahodilé moci, jimiž mají všechna zjevná díla smrtelníků své bytí i svou smrt."],"ref":{"s":"I","l":68,"st":"r","z":false,"raw":"I. 68 r"},"ca":[]},{"id":"s280","o":"Pensieri sulla natura","c":"XLII","str":127,"ni":"ancora del principio d’inerzia","nc":"Ještě o principu setrvačnosti","it":["Ogni moto attende al suo mantenimento, overo: ogni corpo mosso sempre si move, in mentre che la impressione de la potenzia del suo motore in lui si riserva."],"cs":["Každý pohyb usiluje o své zachování, čili: každé pohnuté těleso se stále pohybuje, dokud se v něm uchovává vtisk síly jeho hybatele."],"ref":{"s":"R","l":859,"st":"","z":false,"raw":"R. 859"},"ca":[],"rr":"Br. M. 151 a"},{"id":"s281","o":"Pensieri sulla natura","c":"XLIII","str":127,"ni":"ancora","nc":"Ještě o témž","it":["Ciascun con violenza mantiene suo essere. — E se possibile fussi dare un diametro d’aria a questa spera della terra, a similitudine d’un pozzo, che dall’una all’altra superfizie si mostrassi, e per esso pozzo si lasciassi cadere un corpo grave; ancora che esso corpo si volessi al centro fermare, l’impeto sarebbe quello, che per molti anni glielo vieterebbe."],"cs":["Každý násilím uchovává své bytí. – A kdyby bylo možné provrtat touto zemskou koulí průměr vzduchu na způsob studně, která by se ukazovala od jednoho povrchu k druhému, a do té studně nechat padnout těžké těleso, ačkoli by se to těleso chtělo zastavit ve středu, byl by to impetus, který by mu v tom po mnoho let bránil."],"ref":{"s":"V.U","l":13,"st":"r","z":false,"raw":"V. U. 13 r"},"ca":[]},{"id":"s282","o":"Pensieri sulla natura","c":"XLIV","str":128,"ni":"sulla pitagorica armonia delle sfere celesti","nc":"O pythagorejské harmonii nebeských sfér","it":["Della confregazione de’ cieli, s’ella fa sôno o no.","Ogni sôno si causa dall’aria ripercossa in corpo denso e, s’ella sara fatta da due corpi gravi infra loro, ell’è mediante l’aria, che li circonda, e questa tal confregazione consuma li corpi confregati: adunque seguiterebbe, che li cieli, nella lor confregazione, per non avere aria infra loro, non generassino sono. E se tale confregazione pure avesse verità, essi, in tanti seculi che tali cieli son rivoltati, si sarebbon consumati da tanta immensa velocità fatta in ogni giornata; e se pur facessin sôno esso non si può spandere, perchè il sôno della percissione fatta sotto l’acqua poco si sente, e meno o niente si sentirebbe ne’ corpi densi; ancora: ne’ corpi politi la lor confregazione fa non sôno, il che similmente accadrebbe non farsi sôno nel contatto over confregazione de’ cieli; e, se tali cieli non sono politi nel contatto delle lor confregazioni, seguita essere globulosi e ruvidi, adunque il lor contatto non è continuo, essendo così e’ si genera il vacuo; il quale è concluso non darsi in natura.","Adunque è concluso che confregazione avrebbe consumati li termini di ciascun cielo, e tanto quanto più esso è più veloce in mezzo che inverso i poli, più si consumerebbe in mezzo che da’ poli; e poi più non si confregherebbe, e ’l sôno cesserebbe e i ballerini si fermerebbono, salvo se i cieli l’un girassi a oriente e l’altro a settentrione."],"cs":["O tření nebes, zda vydává zvuk, či ne.","Každý zvuk vzniká ze vzduchu odraženého od hutného tělesa, a je-li způsoben dvěma těžkými tělesy navzájem, děje se to prostřednictvím vzduchu, který je obklopuje; a takové tření opotřebovává třená tělesa; z toho by tedy plynulo, že nebesa při svém tření, protože mezi sebou nemají vzduch, by zvuk nevydávala. A kdyby takové tření přece bylo pravdou, byla by se za tolik staletí, co se ta nebesa otáčejí, opotřebovala tak nesmírnou rychlostí, jaká se děje každého dne; a i kdyby zvuk vydávala, nemohl by se šířit, neboť zvuk nárazu pod vodou je slyšet málo, a ještě méně nebo vůbec ne by byl slyšet v hutných tělesech; dále: u hladkých těles jejich tření zvuk nevydává, a podobně by se stalo, že by se zvuk nevydával při dotyku čili tření nebes; a nejsou-li ta nebesa v dotyku svého tření hladká, plyne z toho, že jsou hrbolatá a drsná, a jejich dotyk tedy není souvislý; a je-li tomu tak, vzniká prázdno, o němž je dovozeno, že v přírodě není.","Je tedy dovozeno, že tření by bylo opotřebovalo okraje každého nebe, a protože je uprostřed rychlejší než u pólů, opotřebovalo by se víc uprostřed než u pólů; a pak by se už netřelo, zvuk by ustal a tanečníci by se zastavili, leda by se jedno nebe otáčelo k východu a druhé k severu."],"ref":{"s":"C.A","l":122,"st":"v","z":false,"raw":"C. A. 122 v"},"ca":[674,676]},{"id":"s283","o":"Pensieri sulla natura","c":"XLV","str":129,"ni":"sulla legge di gravita","nc":"O zákonu tíže","it":["La terra è grave nella sua spera, ma tanto più, quanto essa sarà in elemento più lieve.","Il foco è lieve nella sua spera, ma tanto più, quanto esso sarà in elemento più grave.","Nessuno elemento semplice ha gravità o levità nella sua propria spera."],"cs":["Země je těžká ve své sféře, ale tím víc, čím lehčí živel ji obklopuje.","Oheň je lehký ve své sféře, ale tím víc, čím těžší živel jej obklopuje.","Žádný jednoduchý živel nemá tíži ani lehkost ve své vlastní sféře."],"ref":{"s":"F","l":56,"st":"v","z":false,"raw":"F. 56 v"},"ca":[]},{"id":"s284","o":"Pensieri sulla natura","c":"XLVI","str":129,"ni":"la stessa","nc":"Týž zákon","it":["Il moto fatto da’ corpi gravi verso il comun centro, non è per desiderio che esso corpo abbia in se di trovare tal centro, nè non è per attrazione, ch’esso centro faccia, come calamita, del tirare a se tal peso."],"cs":["Pohyb, který konají těžká tělesa ke společnému středu, není z touhy, kterou by to těleso mělo v sobě, nalézt takový střed, ani z přitažlivosti, jíž by ten střed, jako magnet, táhl k sobě takovou tíži."],"ref":{"s":"F","l":69,"st":"v","z":false,"raw":"F. 69 v"},"ca":[]},{"id":"s285","o":"Pensieri sulla natura","c":"XLVII","str":130,"ni":"la stessa","nc":"Týž zákon","it":["— Il peso perchè non resta nel suo sito?","— Non resta perchè non ha resistenza.","— E donde si moverà?","— Moverassi inverso il centro.","— E perchè non per altre linee?","— Perchè il peso, che non ha resistenzia, discenderà in basso per la via più breve, e ’l più basso sito è il centro del mondo.","— E perchè lo sa così tal peso trovarlo cori tanta brevità?","— Perchè non va — come insensibile — prima vagando per diverse linee."],"cs":["– Proč tíže nezůstává na svém místě?","– Nezůstává, protože nemá oporu.","– A kam se pohne?","– Pohne se ke středu.","– A proč ne po jiných přímkách?","– Protože tíže, která nemá oporu, sestoupí dolů nejkratší cestou, a nejnižší místo je střed světa.","– A jak to, že jej taková tíže umí najít tak nejkratší cestou?","– Protože nejde – jsouc bez smyslů – napřed bloudit po různých přímkách."],"ref":{"s":"R","l":860,"st":"","z":false,"raw":"R. 860"},"ca":[],"rr":"Br. M. 175 a"},{"id":"s286","o":"Pensieri sulla natura","c":"XLVIII","str":130,"ni":"laude del sole","nc":"Chvála slunce","it":["Se guarderai le stelle, sanza razzi (come si fa a vederle per un piccolo foro fatto colla strema punta da la sottile agucchia, e quel posto quasi a toccare l’occhio), tu vedrai esse stelle essere tanto minime, che nulla cosa pare essere minore: e veramente la lunga distanza da loro ragionevole diminuzione, ancora che molte vi sono, che son moltissime volte maggiori che la stella, ciò è la terra coll’acqua.","Ora pensa quel che parrebbe essa nostra stella in tanta distanza, e considera poi quante stelle si metterebbe e per longitudine e latitudine infra esse stelle, le quali sono seminate per esso spazio tenebroso.","Mai non posso fare ch’io non biasimi molti di quelli antichi, li quali dissono, che il sole non avea altra grandezza che quella, che mostra; fra’ quali fu Epicuro, e credo che cavasse tale ragione da un lume posto in questa nostra aria, equidistante al centro; chi lo vede, no ’l vede mai diminuito di grandezza in nessuna distanza."],"cs":["Budeš-li se dívat na hvězdy bez paprsků (jak se to dělá, díváš-li se na ně malým otvorem, udělaným samou špičkou tenké jehly a přiloženým téměř až k oku), uvidíš, že ty hvězdy jsou tak nepatrné, že se nic nezdá menší; a vskutku jim dlouhá vzdálenost dává přiměřené zmenšení, ačkoli je jich tam mnoho, které jsou mnohonásobně větší než naše hvězda, totiž země s vodou.","Nyní pomysli, jak by se jevila tato naše hvězda v takové vzdálenosti, a pak uvaž, kolik hvězd by se vešlo do délky i šířky mezi ty hvězdy, které jsou rozesety po tom temném prostoru.","Nikdy se nemohu zdržet, abych nehaněl mnohé z oněch starých, kteří říkali, že slunce nemá jinou velikost než tu, jakou ukazuje; mezi nimi byl Epikúros, a myslím, že tento důvod vyvodil ze světla umístěného v tomto našem vzduchu, stejně vzdáleného od středu; kdo je vidí, nevidí je nikdy zmenšené na velikosti v žádné vzdálenosti."],"ref":null,"ca":[]},{"id":"s287","o":"Pensieri sulla natura","c":"XLIX","str":131,"ni":"segue la laude","nc":"Pokračování chvály","it":["E le ragioni della sua grandezza e virtù le riservo nel quarto libro. Ma ben mi meraviglio, che Socrate biasimassi questo tal corpo, e che dicessi quello essere a similitudine di pietra infocata; e certo chi lo punì di tal errore poco peccò.","Ma io vorrei avere vocaboli, che mi servissino a biasimare quelli, che voglion laudare più lo adorare gli omini, che tal sole, non vedendo nell’universo corpo di maggiore magnitudine e virtù di quello. E ’l suo lume allumina tutti li corpi celesti, che per l’universo si compartono. Tutte l' anime discendan da lui, perchè il caldo, ch’ è nelli animali vivi, vien dall’anime, e nessuno altro caldo, nè lume è nell' universo, come mostrerò nel quarto libro. E certo costoro, che han voluto adorare li omini per Iddii come Giove, Saturno, Marte e simili han fatto grandissimo errore, vedendo, che, ancora che l’omo fossi grande quanto il nostro mondo, che parrebbe simile a una minima stella, la qual pare un punto nell’universo; e ancora vedendo essi omini mortali e putridi e corruttibili nelle loro sepolture.","La Spera e Marullo laudan con molti altri esso sole."],"cs":["A důvody jeho velikosti a síly si ponechávám pro čtvrtou knihu. Ale věru se divím, že Sókratés hanil takové těleso a říkal, že je podobné rozžhavenému kameni; a jistě ten, kdo jej za takový omyl potrestal, málo pochybil.","Ale přál bych si mít slova, která by mi posloužila k pokárání těch, kdo chtějí víc chválit uctívání lidí než takového slunce, nevidouce ve vesmíru těleso větší velikosti a síly, než je ono. A jeho světlo osvětluje všechna nebeská tělesa, která jsou rozložena po vesmíru. Všechny duše z něho sestupují, neboť teplo, které je v živých tvorech, pochází z duší, a žádné jiné teplo ani světlo ve vesmíru není, jak ukážu ve čtvrté knize. A jistě ti, kdo chtěli uctívat lidi jako bohy, jako Jova, Saturna, Marta a podobné, se dopustili převelikého omylu, vidouce, že i kdyby byl člověk velký jako náš svět, jevil by se podoben nepatrné hvězdě, která se zdá bodem ve vesmíru; a vidouce také, že ti lidé jsou smrtelní, hnijící a pomíjiví ve svých hrobech.","Spera a Marullus spolu s mnoha jinými to slunce chválí."],"ref":{"s":"F","l":5,"st":"r","z":false,"raw":"F. 5 r"},"ca":[]},{"id":"s288","o":"Pensieri sulla natura","c":"L","str":132,"ni":"segue","nc":"Pokračování","it":["Forse Epicuro vide le ombre delle colonne ripercosse nelli antiposti muri essere eguali al diametro della colonna, donde si partìa tale ombra; essendo adunque il concorso dell’ombre parallelo dal suo nascimento al suo fine, li parve da giudicare che il sole ancora lui fosse fronte di tal parallelo, e per conseguenza non essere più grosso di tal colonna, e non s’avvide che tal diminuzione d’ombra era insensibile per la lunga distanza del sole. Se ’l sole fussi minore della terra le stelle di gran parte del nostro emisperio sarebbon sanza lume. (Contro a Epicuro, che dice: tanto e grande il sole quanto e’ pare.)"],"cs":["Snad Epikúros viděl, že stíny sloupů vržené na protější zdi jsou rovny průměru sloupu, od něhož takový stín vycházel; a protože tedy průběh stínů byl rovnoběžný od jeho počátku až do konce, zdálo se mu, že lze usoudit, že i slunce je čelem takové rovnoběžky, a tudíž není větší než takový sloup; a nepovšiml si, že takové zmenšení stínu bylo nepostřehnutelné pro velkou vzdálenost slunce. Kdyby bylo slunce menší než země, byly by hvězdy velké části naší polokoule bez světla. (Proti Epikúrovi, který říká: slunce je tak velké, jak se jeví.)"],"ref":{"s":"F","l":4,"st":"v","z":false,"raw":"F. 4 v"},"ca":[]},{"id":"s289","o":"Pensieri sulla natura","c":"LI","str":133,"ni":"segue","nc":"Pokračování","it":["Dice Epicuro il sole essere tanto quanto esso si dimostra: adunque e’ pare essere un piè, e così l’abbiamo a tenere. Seguirebbe che la luna, quand’ella fa oscurare il sole, il sole non l’avanzerebbe di grandezza come e’ fa; onde, sendo la luna minor del sole, essa luna sarebbe men d’un piede, e per conseguenza, quando il nostro mondo fa oscurare la luna, sarebbe minore d’un dito del piede; con ciò sia, se ’l sole è un piede e la nostra terra fa ombra piramidale inverso la luna, egli è necessario che sia maggiore il luminoso causa della piramide ombrosa, che l’opaco causa d’essa piramide."],"cs":["Epikúros říká, že slunce je tak velké, jak se ukazuje; zdá se tedy být velké jednu stopu, a tak je máme pokládat. Z toho by plynulo, že měsíc, když zatmí slunce, by jej slunce nepřesahovalo velikostí, jak se to děje; a tak, protože měsíc je menší než slunce, byl by měsíc menší než stopa, a v důsledku toho, když náš svět zatmí měsíc, byl by menší než prst u nohy; neboť je-li slunce stopa a naše země vrhá k měsíci jehlanový stín, je nutné, aby svítící těleso, příčina stinného jehlanu, bylo větší než neprůhledné těleso, příčina téhož jehlanu."],"ref":{"s":"F","l":6,"st":"r","z":false,"raw":"F. 6 r"},"ca":[]},{"id":"s290","o":"Pensieri sulla natura","c":"LII","str":133,"ni":"segue","nc":"Pokračování","it":["Misura quanti soli si metterebbe nel corso suo di ventiquattro ore!... E qui si potrà vedere, se Epicuro disse, che ’l sole era tanto grande quanto esso parea, che, — parendo il diametro del sole una misura pedale, e che esso sole entrassi mille volte nel suo corso di ventiquattro ore, — egli avrebbe corso mille piedi, cioè cinquecento braccia, che è un sesto di miglio.","Ora è che ’l corso del sole, infra dì e notte, sarebbe camminato la sesta parte d’un miglio, e questa venerabile lumaca dei sole avrebbe camminato venticinque braccia per ora!"],"cs":["Změř, kolik sluncí by se vešlo do jeho čtyřiadvacetihodinové dráhy!… A zde bude možné vidět, zda Epikúros řekl, že slunce je tak velké, jak se jevilo, že by – jeví-li se průměr slunce na míru stopy a vešlo-li by se to slunce tisíckrát do své čtyřiadvacetihodinové dráhy – urazilo tisíc stop, totiž pět set loket, což je šestina míle.","Vyšlo by tedy, že slunce by za den a noc ušlo šestinu míle, a tento ctihodný slunečný šnek by byl ušel pětadvacet loket za hodinu!"],"ref":{"s":"F","l":8,"st":"r","z":false,"raw":"F. 8 r"},"ca":[]},{"id":"s291","o":"Pensieri sulla natura","c":"LIII","str":134,"ni":"della prova che ’l sole è caldo per natura e non per virtù","nc":"Slunce je teplé svou přirozeností","it":["Del sole. Dicano ehe ’l sole non è caldo, perchè non è di colore di foco, ma è molto più bianco e più chiaro. E a questi si po’ rispondere, che, quando il bronzo liquefatto è più caldo, elli è più simile al color del sole, e, quand’è men caldo, ha più color di foco."],"cs":["O slunci. Říkají, že slunce není teplé, protože nemá barvu ohně, ale je mnohem bělejší a jasnější. A těm lze odpovědět, že když je roztavený bronz nejteplejší, nejvíce se podobá barvě slunce, a když je méně teplý, má více barvu ohně."],"ref":{"s":"F","l":10,"st":"r","z":false,"raw":"F. 10 r"},"ca":[]},{"id":"s292","o":"Pensieri sulla natura","c":"LIV","str":134,"ni":"sul medesimo soggetto","nc":"K téže věci","it":["Provasi il sole, in sua natura, essere caldo — e non freddo, come già s’è detto. —","Lo specchio concavo, essendo freddo, nel ricevere li razzi del foco, li rifrette più caldi, che esso foco.","La palla di vetro, piena d’acqua fredda, manda fori di sè li razzi, presi dal foco, ancora più caldi d’esso foco.","Di queste due dette esperienze seguita, che tal calore dell! razzi, avuti dello specchio o della palla d’acqua fredda, sien caldi per virtù, e non perchè tale specchio o palla sia calda; e ’l simile in questo caso accade del sole passato per essi corpi, che scalda per virtù. E per questo hanno concluso il sole non esser caldo. — Il che per le medesime allegate isperienze si prova esso sole essere caldissimo, per la sperienza detta dello specchio e palla, che, essendo freddi, pigliando i razzi della caldezza del foco, li rendan razzi caldi, perchè la prima causa è calda: e il simile accade del sole, che essendo lui caldo, passando per tali specchi freddi, refrette gran calore.","Non lo splendore del sole scalda, ma il suo natural calore."],"cs":["Dokazuje se, že slunce je svou přirozeností teplé – a ne studené, jak už bylo řečeno.","Duté zrcadlo, ač je studené, odráží při přijímání paprsků ohně paprsky teplejší než ten oheň.","Skleněná koule plná studené vody vysílá ze sebe paprsky přijaté od ohně ještě teplejší než ten oheň.","Z těchto dvou řečených pokusů plyne, že takové teplo paprsků, získaných od zrcadla nebo od koule se studenou vodou, je teplé působením, a ne proto, že by takové zrcadlo či koule byly teplé; a totéž se v tomto případě děje se sluncem, prošlým těmito tělesy, které hřeje působením. A proto dovodili, že slunce není teplé. – Avšak týmiž uvedenými pokusy se dokazuje, že slunce je velmi teplé, a to řečeným pokusem se zrcadlem a koulí, které, ač jsou studené, přijímajíce paprsky tepla ohně, vracejí je jako teplé paprsky, protože první příčina je teplá; a totéž se děje se sluncem, které, jsouc teplé, procházejíc takovými studenými zrcadly, odráží velké teplo.","Nehřeje lesk slunce, nýbrž jeho přirozené teplo."],"ref":{"s":"F","l":34,"st":"v","z":false,"raw":"F. 34 v"},"ca":[]},{"id":"s293","o":"Pensieri sulla natura","c":"LV","str":135,"ni":"propagazione dei raggi nello spazio","nc":"Šíření paprsků prostorem","it":["Passano li razzi solari per la fredda regione dell’aria e non mutan natura, passan per vetri pieni d’acqua fredda e non mancano di lor natura, e, per qualunque loco transparente essi passassino, è come s’elli penetrassino altrettanta aria."],"cs":["Sluneční paprsky procházejí studenou oblastí vzduchu a nemění svou přirozenost, procházejí skly plnými studené vody a nepozbývají své přirozenosti, a ať by procházely kterýmkoli průhledným místem, je to, jako by pronikaly stejně tolik vzduchu."],"ref":{"s":"F","l":85,"st":"v","z":false,"raw":"F. 85 v"},"ca":[]},{"id":"s294","o":"Pensieri sulla natura","c":"LVI","str":136,"ni":"se le stelle han lume dal sole o da sè","nc":"Mají-li hvězdy světlo od slunce, či samy od sebe","it":["Dicano di avere il lume da sè, allegando, che se Venere e Mercurio non n’avessi il lume da sè, quando esso s’interpone infra l’occhio nostro e ’l sole, esse oscurerebbon tanto d’esso sole, quanto esse ne coprano all’occhio nostro. — E quest’è falso, perch’è provato come l’ombroso, posto nel luminoso, è cinto e coperto tutto da razzi laterali del rimanente di tal luminoso e così, resta invisibile. Come si dimostra, quando il sole è veduto per la ramificazione delle piante sanza foglie in lunga distanzia, essi rami non occupano parte alcuna d’esso sole alli occhi nostri.","Il simile accade a’ predetti pianeti, li quali, ancora che da sè e’ sieno sanza luce, eglino non occupano, com’è detto, parte alcuna del sole all’occhio nostro.","Seconda pruova. Dicano le stelle nella notte parere lucidissime quanto più ci son superiori; e che s’elle non avessin lume da se che l’ombra, che fa la terra, che s’interpone infra loro e ’l sole, le verrebbe a scurare, non vedendo esse, nè sendo vedute dal corpo solare. — Ma questi non n’han considerato, che l’ombra piramidale della luna non n’aggiugne infra troppe stelle, quelle ch’ell’aggiugne, la piramide è tanto diminuita che poco occupa del corpo della stella, e ’l rimanente è alluminato dal sole."],"cs":["Říkají, že mají světlo samy od sebe, a uvádějí, že kdyby Venuše a Merkur neměly světlo samy od sebe, pak když se postaví mezi naše oko a slunce, zatemnily by ze slunce tolik, kolik ho našemu oku zakrývají. – A to je nepravda, neboť je dokázáno, že stinné těleso postavené do svítícího je obklopeno a celé zakryto postranními paprsky zbytku toho svítícího tělesa, a tak zůstává neviditelné. Jak se ukazuje, když je slunce viděno skrze větvoví stromů bez listí ve velké vzdálenosti: ty větve nezakrývají našim očím žádnou část slunce.","Totéž se děje s řečenými planetami, které, ačkoli jsou samy o sobě bez světla, nezakrývají, jak řečeno, našemu oku žádnou část slunce.","Druhý důkaz. Říkají, že hvězdy se v noci zdají tím jasnější, čím jsou nad námi výše; a že kdyby neměly světlo samy od sebe, stín, který vrhá země, jež se staví mezi ně a slunce, by je zatemnil, protože by neviděly sluneční těleso, ani by jím nebyly viděny. – Ale ti neuvážili, že jehlanový stín měsíce [míněn je spíš stín země] nedosáhne k mnoha hvězdám, a u těch, k nimž dosáhne, je jehlan tak zmenšen, že zakryje jen málo z tělesa hvězdy, a zbytek je osvětlen sluncem."],"ref":{"s":"F","l":86,"st":"r","z":false,"raw":"F. 86 r"},"ca":[]},{"id":"s295","o":"Pensieri sulla natura","c":"LVII","str":137,"ni":"la terra è una stella","nc":"Země je hvězda","it":["Tu nel tuo discorso hai a concludere la terra essere una stella quasi simile alla luna, e così proverai la nobiltà del nostro mondo!","E così farai un discorso delle grandezze di molte stelle, secondo li autori."],"cs":["Ty ve svém pojednání musíš dovodit, že země je hvězda téměř podobná měsíci, a tak dokážeš vznešenost našeho světa!","A tak pojednáš o velikostech mnoha hvězd podle autorů."],"ref":{"s":"F","l":57,"st":"r","z":false,"raw":"F. 57 r"},"ca":[]},{"id":"s296","o":"Pensieri sulla natura","c":"LVIII","str":137,"ni":"essa risplende nell’universo","nc":"Září ve vesmíru","it":["Come la terra è una stella. La terra mediante la spera dell’acqua, che in gran parte la veste, — la qual piglia il simulacro del sole e risplende all’universo, sì come fan tutte l’altre stelle, — si dimostra ancora lei essere stella."],"cs":["Jak je země hvězdou. Země se prostřednictvím vodní sféry, která ji z velké části odívá – a ta přijímá obraz slunce a září do vesmíru, tak jako všechny ostatní hvězdy –, rovněž ukazuje jako hvězda."],"ref":{"s":"C.A","l":112,"st":"v","z":true,"raw":"C. A. 112 v"},"ca":[619,621]},{"id":"s297","o":"Pensieri sulla natura","c":"LIX","str":138,"ni":"ordine del provare la terra essere una stella","nc":"Postup důkazu, že země je hvězda","it":["In prima diffinisci l’occhio. Poi mostra come il battere d’alcuna stella viene dall’occhio; e perchè il batter d’esse stelle è più nell’una, che nell’altra; e come li razzi delle stelle nascan dall’occhio. E di’ che, se ’l battere delle stelle fussi, come pare, nelle stelle, che tal battimento mostra d’essere di tanta dilatazione, quant’è il corpo di tale stella; essendo adunque maggior della terra, che tal moto fatto in istante sare’ trovo veloce a raddoppiare la grandezza di tale stella; di poi prova come la superfizie dell’aria, ne’ confini del foco, e la superfizie del foco, nel suo termine, è quella, nella qual penetrando, li razzi solari portan tal similitudine di corpi celesti grandi nel lor levare e porre, e piccole essendo essi nel mezzo del cielo."],"cs":["Nejprve definuj oko. Pak ukaž, jak třpyt některé hvězdy pochází z oka; a proč je třpyt jedné hvězdy větší než druhé; a jak paprsky hvězd vznikají z oka. A řekni, že kdyby třpyt hvězd byl, jak se zdá, v hvězdách, ukazoval by se takový třpyt tak rozlehlý, jak velké je těleso takové hvězdy; a protože je tedy větší než země, byl by takový pohyb vykonaný v okamžiku příliš rychlý na to, aby zdvojnásobil velikost takové hvězdy; potom dokaž, že povrch vzduchu na hranicích ohně a povrch ohně na jeho mezi je ten, jímž pronikajíce nesou sluneční paprsky takový obraz nebeských těles velký při jejich východu a západu, a malý, jsou-li uprostřed nebe."],"ref":{"s":"C.A","l":112,"st":"v","z":true,"raw":"C. A. 112 v"},"ca":[619,621]},{"id":"s298","o":"Pensieri sulla natura","c":"LX","str":138,"ni":"la terra sembra stella ai lontani","nc":"Vzdáleným se země jeví jako hvězda","it":["Il libro mio s’astende a mostrare come l’Ocean, colli altri mari, fa, mediante il sole, splendere il nostro mondo a modo di luna, e a’ più remoti pare stella; e quest’è provo."],"cs":["Má kniha chce ukázat, jak Oceán s ostatními moři působí, že náš svět prostřednictvím slunce září na způsob měsíce a těm nejvzdálenějším se jeví jako hvězda; a to je dokázáno."],"ref":{"s":"C.A","l":112,"st":"v","z":false,"raw":"C. A. 112 v"},"ca":[619,621]},{"id":"s299","o":"Pensieri sulla natura","c":"LXI","str":139,"ni":"la terra non è centro dell’universo","nc":"Země není středem vesmíru","it":["Come la terra non è nel mezzo del cerchio del sole, nè nel mezzo del mondo, ma è ben nel mezzo de’ sua elementi, compagni e uniti con lei; e chi stesse nella luna, quand’ella insieme col sole è sotto a noi, questa nostra terra, coll’elemento dell’acqua, parrebbe e farebbe offizio, tal qual fa la luna a noi."],"cs":["Jak země není uprostřed kruhu slunce ani uprostřed světa, ale je dobře uprostřed svých živlů, které ji provázejí a jsou s ní spojeny; a kdo by stál na měsíci, když je spolu se sluncem pod námi, tomu by se tato naše země se živlem vody jevila a konala by tutéž službu, jakou nám koná měsíc."],"ref":{"s":"F","l":25,"st":"v","z":false,"raw":"F. 25 v"},"ca":[]},{"id":"s300","o":"Pensieri sulla natura","c":"LXII","str":139,"ni":"come in un’età lontana la terra aveva un più vivo splendore","nc":"Jak země v dávném věku zářila živěji","it":["Come la terra, facendo offizio di luna, ha perduto assai del lume antico nel nostro emisperio pel calare delle acque, com’è provato in libro quarto: De mundo e acque."],"cs":["Jak země, konajíc službu měsíce, ztratila na naší polokouli mnoho ze svého dávného světla úbytkem vod, jak je dokázáno ve čtvrté knize: O světě a vodách."],"ref":{"s":"F","l":94,"st":"v","z":false,"raw":"F. 94 v"},"ca":[]},{"id":"s301","o":"Pensieri sulla natura","c":"LXIII","str":139,"ni":"questioni sulla natura della luna","nc":"Otázky o povaze měsíce","it":["1. Nessun lievissimo è opaco.","2. Nessun più lieve sta sotto al men lieve.","3. Se la luna ha sito in mezzo ai sua elementi o no.","E s’ella non ha sito particulare, come la terra, nelli sua elementi, perchè non cade al centro de’ nostri elementi?","E se la luna non è in mezzo alli sua elementi, e non discende, adunque ella è più lieve che altro elemento.","E se la luna è più lieve che altro elemento, perchè è solida e non traspare?"],"cs":["1. Nic nejlehčího není neprůhledné.","2. Nic lehčího není pod méně lehkým.","3. Zda má měsíc místo uprostřed svých živlů, či ne.","A nemá-li zvláštní místo ve svých živlech jako země, proč nepadá do středu našich živlů?","A není-li měsíc uprostřed svých živlů a nesestupuje-li, je tedy lehčí než kterýkoli jiný živel.","A je-li měsíc lehčí než kterýkoli jiný živel, proč je pevný a neprůsvitný?"],"ref":{"s":"F","l":41,"st":"v","z":false,"raw":"F. 41 v"},"ca":[]},{"id":"s302","o":"Pensieri sulla natura","c":"LXIV","str":140,"ni":"sulla gravità della luna","nc":"O tíži měsíce","it":["Nessun denso è più lieve che l’aria.","Avendo noi provato come la parte della luna, che risplende è acqua, che specchia il corpo del sole, la quale ci riflette lo splendore da lui ricevuto, e come, se tale acqua fosse sanza onde, ch’ella picciola si dimostrerebbe, ma di splendore quasi simile al sole; al presente bisogna provare, se essa luna è corpo grave o lieve; imperocchè se fusse grave, confessando che dalla terra in su in ogni grado d’altezza s’acquista gradi di levità, — conciò sia che l’acqua è più lieve che la terra; e l’aria che l’acqua, e ’l foco che l’aria e così seguitando successivamente, - e’ parrebbe che, se la luna avesse densità, com’ella ha, ch’ella avesse gravità, e, avendo gravità, che lo spazio, ove essa si trova, non la potesse sostenere, e per conseguenza avesse a discendere inverso il centro dell’universo e congiugnersi colla terra, e se non lei almanco le sue acque avessino, a cadere, e spogliarla di sè, e cadere inverso il centro, e lasciar di sè la luna spogliata, e sanza lustro; onde, non seguitando quel che di lei la ragione ci promette, egli è manifesto segno, che tal luna è vestita de’ sua elementi, cioè acqua, aria e foco, e così in sè per se si sostenga in quello spazio, come fa la nostra terra coi sua elementi in quest’altro spazio, e che tale offizio facciano le cose gravi ne’ sua elementi, qual fanno l’altre cose gravi nelli elementi nostri."],"cs":["Nic hutného není lehčí než vzduch.","Když jsme dokázali, že ta část měsíce, která září, je voda, jež zrcadlí těleso slunce a odráží k nám lesk od něho přijatý, a že kdyby ta voda byla bez vln, jevila by se malá, ale leskem téměř podobná slunci, je nyní třeba dokázat, zda je měsíc těleso těžké, či lehké; neboť kdyby byl těžký – připouštíme-li, že od země vzhůru se s každým stupněm výšky nabývá stupňů lehkosti, protože voda je lehčí než země, vzduch lehčí než voda a oheň lehčí než vzduch, a tak dál postupně –, zdálo by se, že má-li měsíc hutnost, jakou má, má i tíži, a má-li tíži, že by jej prostor, v němž se nachází, nemohl udržet, a v důsledku toho by musel sestoupit ke středu vesmíru a spojit se se zemí; a ne-li on sám, aspoň jeho vody by musely spadnout a obnažit jej, padat ke středu a zanechat měsíc obnažený a bez lesku; a protože se neděje to, co nám o něm slibuje rozum, je to zjevné znamení, že takový měsíc je oděn svými živly, totiž vodou, vzduchem a ohněm, a tak se sám o sobě udržuje v onom prostoru, jako to činí naše země se svými živly v tomto druhém prostoru, a že těžké věci v jeho živlech konají tutéž službu, jakou konají jiné těžké věci v našich živlech."],"ref":{"s":"F","l":69,"st":"v","z":false,"raw":"F. 69 v"},"ca":[]},{"id":"s303","o":"Pensieri sulla natura","c":"LXV","str":141,"ni":"sul medesimo soggetto","nc":"K téže věci","it":["La luna densa e grave come sta, la luna?"],"cs":["Měsíc hutný a těžký – jak se drží, ten měsíc?"],"ref":{"s":"R","l":892,"st":"","z":false,"raw":"R. 892"},"ca":[],"rr":"Br. M. 94 a"},{"id":"s304","o":"Pensieri sulla natura","c":"LXVI","str":141,"ni":"i mondi gravitano in seno ai propri elementi","nc":"Světy tíhnou v lůně svých vlastních živlů","it":["Il rossume ovver tuorlo dell’ovo sta in mezzo al suo albume sanza discendere d’alcuna parte, ed è più lieve o più grave o eguale a’ esso albume; e, s’egli è più lieve, egli dovrebbe sorgere sopra tutto l’albume e fermarsi in contatto della scorza d’esso uovo e, s’elli è più grave dovrebbe discender, e, s’elli è eguale, così potrebbe stare nell’un delli stremi come in mezzo o di sotto."],"cs":["Žloutek vejce zůstává uprostřed svého bílku a nikam neklesá, a je buď lehčí, nebo těžší, nebo stejně těžký jako ten bílek; a je-li lehčí, měl by vystoupit nad celý bílek a zastavit se v dotyku se skořápkou vejce, a je-li těžší, měl by klesnout, a je-li stejný, mohl by se držet stejně dobře na jednom z krajů jako uprostřed nebo dole."],"ref":{"s":"R","l":902,"st":"","z":false,"raw":"R. 902"},"ca":[],"rr":"Leic. 2 a"},{"id":"s305","o":"Pensieri sulla natura","c":"LXVII","str":142,"ni":"il calore come principio della vita","nc":"Teplo jako počátek života","it":["Il caldo è cagione del movimento dell’umido, e ’l freddo lo ferma, come si vede la region fredda, che ferma i nuvoli nell’aria.","Dov’è vita è calore; dov’è calore vitale e movimento d’omore."],"cs":["Teplo je příčinou pohybu vlhkosti a chlad ji zastavuje, jak vidíme na studené oblasti, která zastavuje mraky ve vzduchu.","Kde je život, je teplo; kde je životní teplo, je pohyb šťáv."],"ref":{"s":"K","l":1,"st":"r","z":false,"raw":"K. 1 r"},"ca":[]},{"id":"s306","o":"Pensieri sulla natura","c":"LXVIII","str":142,"ni":"la terra è un grande vivente","nc":"Země je velký živý tvor","it":["Nessuna cosa nasce in loco, dove non sia vita sensitiva, vegetativa e razionale: nascono le penne sopra li uccelli, e si mutano ogni anno; nascono li peli sopra li animali e ogni anno si mutano, salvo alcuna parte, come li peli delle barbe de’ lioni e gatti e simili; nascono l’erbe sopra li prati e le foglie sopra li alberi, e ogni anno in gran parte si rinnovano; adunque potremo dire, la terra avere anima vegetativa, e che la sua carne sia la terra, li sua ossi sieno li ordini delle collegazioni de’ sassi, di che si compongono ie montagne, il suo tenerume sono li tufi, il suo sangue sono le vene delle acque, il lago del sangue, che sta dintorno al core, è il mare oceano, il suo alitare e ’l crescere e discrescere del sangue per li polsi, e così, nella terra è il flusso e riflusso del mare, e ’l caldo dell’anima del mondo è il fuoco, ch’è infuso per la terra, e la residenza dell’anima vegetativa sono li fochi, che per diversi lochi della terra spirano in bagni e in miniere di solfi e in vulcani, a Mon Gibello di Sicilia e altri lochi assai."],"cs":["Nic se nerodí na místě, kde není život smyslový, vegetativní a rozumový: ptákům rostou peří a každý rok se mění; zvířatům rostou chlupy a každý rok se mění, kromě některých částí, jako jsou chlupy vousů lvů, koček a podobných; na loukách roste tráva a na stromech listí a každý rok se z velké části obnovují; můžeme tedy říci, že země má duši vegetativní a že jejím masem je hlína, jejími kostmi řady spojených skal, z nichž se skládají hory, jejími chrupavkami tufy, její krví žíly vod; jezero krve, které je kolem srdce, je oceán; její dýchání a vzrůstání a opadání krve v tepnách je na zemi příliv a odliv moře; a teplem duše světa je oheň, který je vlit do země, a sídlem vegetativní duše jsou ohně, které na různých místech země vydechují v lázních, v sirných dolech a v sopkách, na Mongibellu na Sicílii a na mnoha jiných místech."],"ref":{"s":"R","l":896,"st":"","z":false,"raw":"R. 896"},"ca":[],"rr":"Br. M. 94 b"},{"id":"s307","o":"Pensieri sulla natura","c":"LXIX","str":143,"ni":"paragone dell’uomo e del mondo. cominciamento del trattato de l’acqua","nc":"Přirovnání člověka a světa. Začátek pojednání o vodě","it":["L’omo è detto da li antiqui mondo minore, e certo la dizione d’esso nome è bene collocata imperò che, sì come l’omo è composto di terra, acqua, aria e foco, questo corpo della terra e il simigliante. Se l’omo ha in sè ossa, sostenitori e armadura della carne, il mondo ha i sassi sostenitori della terra; se l’omo ha in sè il lago del sangue, dove cresce e discresce il polmone, nello alitare, il corpo della terra ha il suo oceano mare, il quale, ancora lui, cresce e discresce ogni sei ore per lo alitare del mondo; se dal detto lago di sangue dirivan vene, che si vanno ramificando per lo corpo umano, similmente il mare oceano empie il corpo de la terra d’infinite vene d’acqua. Manca al corpo della terra i nervi, i quali non vi sono, perche i nervi sono fatti al proposito del movimento, e, il mondo sendo di perpetua stabilità, non v’accade movimento, e, non v’accadendo movimento, i nervi non vi sono necessari. Ma in tutte l’altre cose sono molto simili."],"cs":["Člověk je od starých nazýván malým světem, a jistě je to jméno dobře zvoleno, neboť jako je člověk složen ze země, vody, vzduchu a ohně, podobně je tomu s tímto tělesem země. Má-li člověk v sobě kosti, opory a zbroj masa, má svět skály, opory země; má-li člověk v sobě jezero krve, v němž plíce při dýchání vzrůstají a opadají, má těleso země svůj oceán, který také vzrůstá a opadá každých šest hodin dýcháním světa; vycházejí-li z řečeného jezera krve žíly, které se rozvětvují po lidském těle, podobně oceán naplňuje těleso země nesčetnými žilami vody. Tělesu země chybějí šlachy, které tam nejsou, neboť šlachy jsou učiněny pro pohyb, a protože svět je věčně stálý, nedochází v něm k pohybu, a protože k pohybu nedochází, nejsou tam šlachy potřeba. Ale ve všech ostatních věcech jsou si velmi podobní."],"ref":{"s":"C.A","l":80,"st":"r","z":false,"raw":"C. A. 80 r"},"ca":[432,434]},{"id":"s308","o":"Pensieri sulla natura","c":"LXX","str":144,"ni":"l’acqua","nc":"Voda","it":["Il corpo della terra, a similitudine dei corpi delli animali, è tessuto di ramificazione di vene, le quali son tutte insieme congiunte, e son costituite a nutrimento e vivificazione d’essa terra e de’ sua creati."],"cs":["Těleso země je, podobně jako těla zvířat, protkáno rozvětvením žil, které jsou všechny navzájem spojeny a jsou určeny k výživě a oživování té země a jejích tvorů."],"ref":{"s":"A","l":55,"st":"v","z":false,"raw":"A. 55 v"},"ca":[]},{"id":"s309","o":"Pensieri sulla natura","c":"LXXI","str":144,"ni":"l’acqua è il sangue e la linfa del mondo","nc":"Voda je krví a mízou světa","it":["L’acqua, che surge ne’ monti è il sangue, che tien viva essa montagna, e, forata in essa o per traverso essa vena, la natura, aiutatrice de’ sua vivi, sendo abbondante nell’aumento di volere riparare il mancamento del versato umore, quivi con curioso soccorso abbonda; a similitudine del loco percosso nell’omo, e’ si vede, per lo soccorso fatto, multiplicare il sangue sotto alla pelle, in modo di sgonfiamento, per sopperire al loco infecto; similmente la vite, sendo tagliata nell’alta stremità, manda la natura dall’infime radice all’altezza somma del loco tagliato il suo umore, e quello, essendo versato, essa non l’abbandona di vitale umore, insino al fine della sua vita."],"cs":["Voda, která vyvěrá v horách, je krev, která udržuje horu při životě; a je-li v ní ta žíla provrtána nebo přeťata, příroda, pomocnice svých živých, hojně se snažíc nahradit úbytek vylité šťávy, tam se starostlivou pomocí hojně přispěje; podobně jako na udeřeném místě u člověka vidíme, jak se poskytnutou pomocí rozmnožuje krev pod kůží v podobě otoku, aby nahradila postižené místo; podobně réva, je-li uříznuta na horním konci, posílá příroda od nejspodnějšího kořene až k nejvyššímu místu řezu svou šťávu, a když se vylévá, neopouští ji příroda bez životní šťávy až do konce jejího života."],"ref":{"s":"R","l":970,"st":"","z":false,"raw":"R. 970"},"ca":[],"rr":"Leic. 33 b"},{"id":"s310","o":"Pensieri sulla natura","c":"LXXII","str":145,"ni":"sul medesimo soggetto","nc":"K téže věci","it":["L’acqua è proprio quella, che per vitale umore di questa arida terra è dedicata; e quella causa, che la move per le sue ramificate vene, contro al natural corso delle cose gravi, è proprio quella, che move li umori in tutte le spezie de’ corpi animali."],"cs":["Voda je právě ta, která je určena jako životní šťáva této vyprahlé země; a ta příčina, která ji pohání jejími rozvětvenými žilami proti přirozenému běhu těžkých věcí, je právě ta, která pohání šťávy ve všech druzích zvířecích těl."],"ref":{"s":"H","l":77,"st":"r","z":false,"raw":"H. 77 r"},"ca":[]},{"id":"s311","o":"Pensieri sulla natura","c":"LXXIII","str":145,"ni":"l’acqua sui monti","nc":"Voda na horách","it":["L’acqua, vitale omore della terrestre macchina, mediante il suo natural calore si move."],"cs":["Voda, životní šťáva pozemského stroje, se pohybuje svým přirozeným teplem."],"ref":{"s":"R","l":965,"st":"","z":false,"raw":"R. 965"},"ca":[],"rr":"Br. M. 236 b"},{"id":"s312","o":"Pensieri sulla natura","c":"LXXIV","str":145,"ni":"trasformazioni dovute all’acqua","nc":"Proměny způsobené vodou","it":["L’acqua è ’l vetturale della natura."],"cs":["Voda je povozníkem přírody."],"ref":{"s":"H","l":95,"st":"r","z":false,"raw":"H. 95 r"},"ca":[]},{"id":"s313","o":"Pensieri sulla natura","c":"LXXV","str":146,"ni":"della vibrazion della terra","nc":"O chvění země","it":["Li corsi subterranei delle acque, sì come quelli, che son fatti in fra l’aria e la terra, son quelli, che al continuo consumano e profondano li letti delli lor corsi.","La terra, levata dalli fiumi, si scarica nelle ultime parti delli lor corsi, ovvero la terra, levata da li alti corsi de’ fiumi, si scarica nell’ultime bassezze delli lor moti.","Dove l’acque dolci pullulano, nella superfice del mare, è manifesto prodigio della creazione d’una isola, la qual si scoprirà tanto più tardi o più presto, quanto la quantità dell’acqua, che surge, sarà di minore o maggior quantità.","E questa tale isola si genera dalla quantità della terra o consumazion de’ sassi, che fa il corso sotterraneo dell’acqua per li lochi, dond’ella discorre."],"cs":["Podzemní toky vod, stejně jako ty, které tekou mezi vzduchem a zemí, jsou ty, které ustavičně vymílají a prohlubují koryta svých toků.","Zemina, odnesená řekami, se ukládá v posledních částech jejich toků, čili zemina odnesená horními toky řek se ukládá v posledních nížinách jejich pohybu.","Kde na hladině moře vyvěrají sladké vody, je to zjevné znamení vzniku ostrova, který se odkryje tím později či dříve, čím menší či větší bude množství vyvěrající vody.","A takový ostrov vzniká z množství zeminy či z rozrušení skal, které způsobuje podzemní tok vody v místech, kudy protéká."],"ref":{"s":"K","l":2,"st":"r","z":false,"raw":"K. 2 r"},"ca":[]},{"id":"s314","o":"Pensieri sulla natura","c":"LXXVI","str":146,"ni":"vaste trasformazioni nel passato e nell’avvenire","nc":"Rozsáhlé proměny v minulosti a v budoucnosti","it":["Come le rive del mare al continuo acquistano terreno inverso il mezzo del mare.","Come li scogli o promontori de mari al continuo minano, e si consumano.","Come i mediterranei scopriranno i lor fondi all’aria, e sol riserberanno il canale al maggior fiume, che dentro vi metta, il quale correrà all’Oceano, e ivi verserà lo sue acque, insieme con quelle di tutti i fiumi, che con esso s’accompagnano."],"cs":["Jak břehy moře ustavičně získávají půdu směrem ke středu moře.","Jak se útesy či výběžky moří ustavičně podemílají a rozrušují.","Jak vnitrozemská moře odkryjí svá dna vzduchu a zachovají jen koryto největší řece, která do nich ústí, a ta poteče do Oceánu a tam vylije své vody spolu s vodami všech řek, které ji provázejí."],"ref":{"s":"G","l":49,"st":"v","z":false,"raw":"G. 49 v"},"ca":[]},{"id":"s315","o":"Pensieri sulla natura","c":"LXXVII","str":147,"ni":"l’acqua nei fiumi","nc":"Voda v řekách","it":["In fra le potenti cagioni de’ terrestri danni a me pare, che i fiumi, colle ruinose innondazioni, tengano il principato; e non è il foco, come alcuni han voluto, imperocchè il foco termina sua voragine, dove manca il nutrimento; il movimento dell’acqua, ch’è mantenuto dalle inclinate valli, ancora lui termina e more insieme coll’ultima bassezza nella valle; ma il foco è causato dal nutrimento e ’l moto dell’acqua dalla bassezza. Il nutrimento del foco è disunito, e disunito e separato fia il danno, e il foco more, dove manca il nutrimento. La declinazione delle valli è unita, e unito fia il danno, col ruinoso corso del fiume, finchè, in compagnia delle sue valli, finirà nel mare, universale bassezza e unico riposo delle peregrinanti acque dei fiumi.","Ma con quale lingua o con quale vocaboli potrò io esprimere e dire le nefande mine, li incredibili dirupamenti, le inesorabili rapacità, fatte da’ diluvi de’ superbi fiumi? Come potrò io dire? — Certo io non mi sento bastevole a tanta dimostrazione; ma pure con quell’aiuto, che mi dà la speranza, m’ingegnerò riferire il modo del dannificare, contro ai quali diripanti fiumi non vale alcuno umano riparo."],"cs":["Mezi mocnými příčinami pozemských škod se mi zdá, že řeky se svými zhoubnými záplavami drží prvenství; a není to oheň, jak někteří tvrdili, neboť oheň ukončí svou zhoubu, kde mu chybí potrava; pohyb vody, udržovaný svahy údolí, také končí a umírá spolu s nejnižším místem údolí; ale oheň je způsobován potravou a pohyb vody spádem. Potrava ohně je roztroušená, a roztroušená a oddělená bude i škoda, a oheň umírá, kde chybí potrava. Sklon údolí je souvislý, a souvislá bude i škoda se zhoubným tokem řeky, dokud spolu se svými údolími neskončí v moři, všeobecné nížině a jedinému odpočinku putujících vod řek.","Ale jakým jazykem či jakými slovy budu moci vyjádřit a vylíčit hanebné zkázy, neuvěřitelná sesutí, neúprosné dravosti, způsobené povodněmi pyšných řek? Jak to budu moci vylíčit? – Věru necítím se dostatečným k takovému vylíčení; ale přece s pomocí, kterou mi dává naděje, pokusím se popsat způsob ničení, proti němuž, když se řeky řítí, neplatí žádná lidská ochrana."],"ref":{"s":"R","l":953,"st":"","z":false,"raw":"R. 953"},"ca":[],"rr":"Leic. 20 a"},{"id":"s316","o":"Pensieri sulla natura","c":"LXXVIII","str":148,"ni":"su una conchiglia fossile","nc":"O zkamenělé lastuře","it":["O tempo, veloce predatore delle create cose, quanti re, quanti popoli hai tu disfatti, e quante mutazioni di stati e vari casi sono seguiti, dopochè la maravigliosa forma di questo pesce qui morì per le cavernose e ritorte interiora.... Ora, disfatto dal tempo, paziente giaci in questo chiuso loco; colle spolpate e ignude ossa hai fatto armadura e sostegno al soprapposto monte!"],"cs":["Ó čase, rychlý lupiči stvořených věcí, kolik králů, kolik národů jsi zničil a kolik proměn států a rozličných příhod nastalo od té doby, co podivuhodná podoba této ryby zde zemřela v jeskynních a zakřivených útrobách… Nyní, zničena časem, trpělivě ležíš na tomto uzavřeném místě; svými ohlodanými a obnaženými kostmi jsi učinila zbroj a oporu hoře nad sebou!"],"ref":{"s":"R","l":954,"st":"","z":false,"raw":"R. 954"},"ca":[],"rr":"Leic. 27 b"},{"id":"s317","o":"Pensieri sulla natura","c":"LXXIX","str":148,"ni":"basta un piccolo segno per ricostruire l’intero passato","nc":"Malé znamení stačí k poznání celé minulosti","it":["Perchè molto son più antiche le cose che le lettere, non è maraviglia se alli nostri giorni non apparisce scrittura delli predetti mari essere occupatori di tanti paesi; e se pure alcuna scrittura apparìa le guerre, l’incendi, li diluvi dell’acque, le mutazioni delle lingue e delle leggi hanno consumato ogni antichità: ma a noi bastano le testimonianze delle cose nate nelle acque salse, ritrovarsi nelli alti monti, lontani dalli mari d’allora."],"cs":["Protože věci jsou mnohem starší než písmo, není divu, že se v našich dnech neobjevuje žádný záznam o tom, že řečená moře zaujímala tolik zemí; a i kdyby se nějaký záznam objevil, války, požáry, potopy vod, proměny jazyků a zákonů pohltily všechnu starobylost; ale nám stačí svědectví věcí zrozených ve slaných vodách, že se nacházejí na vysokých horách, vzdálených od tehdejších moří."],"ref":{"s":"R","l":955,"st":"","z":false,"raw":"R. 955"},"ca":[875,876],"rr":"C. A. 162 b"},{"id":"s318","o":"Pensieri sulla natura","c":"LXXX","str":149,"ni":"del diluvio e de’ nicchi marini","nc":"O potopě a mořských lasturách","it":["Se tu dirai che li nicchi, che per li confini d1 Italia lontano dalli mari, in tanta altezza si veggono alli nostri tempi, siano stati per causa del Diluvio, che lì li lasciò; io ti rispondo che, credendo tu che tal Diluvio superasse il più alto monte 7 cubiti, — come scrisse chi li misurò, — tali nicchi, che sempre stanno vicini ai liti del mare, e’ dovriano restare sopra tali montagne, e non sì poco sopra le radici de’ monti, per tutto a una medesima altezza, a suoli a suoli. E se tu dirai, che, essendo tali nicchi vaghi di stare vicini alli liti marini, e che, crescendo in tanta altezza, che li nicchi si partirono da esso lor primo sito, e seguitarono l’accrescimento delle acque insino alla lor somma altezza; qui si risponde che, sendo il nicchio animale di non più veloce moto che si sia la lumaca, fori dell’acqua, — e qualche cosa più tarda, perchè non nuota, anzi si fa un solco ove s’appoggia,— camminerà il dì dalle 3 alle 4 braccia. Adunque questo, con tale moto, non sarà camminato dal mare Adriano insino in Monferrato di Lombardia, che v’è 250 miglia di distanza in 40 giorni — come disse chi tenne conto d’esso tempo.","E se tu dici che l’onde ve li portarono, essi per la lor grossezza, non si reggono, se non sopra il suo fondo; e se questo non mi concedi, confessami almeno ch’elli aveano a rimanere nelle cime de’ piu alti monti e ne’ laghi, che infra li monti si serrano: come lago di Lario o di Como e ’l Maggiore e di Fiesole e di Perugia e simili.","E se tu dirai che li nicchi son portati dall’onde, essendo vòti e morti, io dico che, dove andavano li morti, poco si rimovevano da’ vivi, e in queste montagne sono trovati tutti i vivi, che si cognoscono, che sono colli gusci appaiati, e sono in un filo dove, non è nessun de’ morti, e poco più alto è trovato, dove eran gettati dall’onde tutti li morti colle loro scorze separate, appresso a dove li fiumi cascavano in mare in gran profondità. E se li nicchi fussero stati portati dal torbido Diluvio, essi si sarebbero misti separatamente l’un dall’altro, infra ’l fango e non con ordinati gradi a suoli, come alli nostri tempi si vede.","A costor si risponderà che s’è tale influenza d’animali, non potrebbero accadere in una sola linea se non animali di medesima sorte e età, e non il vecchio col giovane, e non alcun col coperchio e l’altro essere sanza sua copritura, e non l’uno esser rotto e l’altro intero, e non l’uno ripieno di rena marina, e rottame minuto e grosso d’altri nicchi dentro alli nicchi interi, che lì son rimasti aperti, e non le bocche de’ granchi sanza il rimanente dei suo tutto, e non li nicchi d’altre specie appiccati con loro in forma d’animale, che sopra di quelli si movesse, perchè ancora resta il vestigio del suo andamento sopra la scorza, che lui già, a uso di tarlo, sopra il legname andò consumando; non si troverebbero infra loro ossa e denti di pesce, li quali alcuni dimandano saette e altri lingue di serpenti, e non si troverebbero tanti membri di diversi animali insieme uniti, se lì da’ liti marini gittati non fussino.","E ’l diluvio lì non li avrebbe portati, perchè le cose gravi più dell’acqua, non stanno a galla sopra l’acqua, e le cose predette non sarìano in tanta altezza, se già a nuoto ivi sopra dell’acque portate non furono, la qual cosa è impossibile per la lor gravezza.","Dove le vallate non ricevono le acque salse del mare, quivi i nicchi mai non si vedono, come manifesto si vede nella gran valle d’Arno di sopra alla Gonfolina, sasso per antico unito con Monte Albano in forma d’altissimo argine, il quale tenea ringorgato tal fiume in modo che, prima che versasse nel mare, il quale era dopo ai piedi di tal sasso, componea due grandi laghi, de’ quali il primo è, dove oggi si vede fiorire la città di Fiorenze insieme con Prato e Pistoia, e Monte Albano seguiva il resto dell’argine insin dove oggi è posto Serravalle. Dal Val d’Arno di sopra insino Arezzo si creava un secondo lago, il quale nell’antidetto lago versava le sue acque, chiuso circa dove oggi si vede Girone, e occupava tutta la detta valle di sopra per ispazio di quaranta miglia di lunghezza. Questa valle riceve sopra il suo fondo tutta la terra portata dall’acqua da quella intorbidata, la quale ancora si vede a’ piedi di Prato Magno restare altissima, dove li fiumi non l’hanno consumata, e infra essa terra si vedono le profonde segature de’ fiumi, che quivi son passati, li quali discendono dal gran monte di Prato Magno, nelle quali segature non si vede vestigio alcuno di nicchi o di terra marina. Questo lago si congiugnea col lago di Perugia.","Gran somma di nicchi si vede, dove li fiumi versano in mare, benchè in tali siti l’acque non sono tanto salse per la mistion dell’acque dolci, che con quelle s’uniscono. E ’l segno di ciò si vede dove per antico li Monti Appennini versavano li lor fiumi nel mare Adriano, li quali in gran parte mostrano infra li monti gran somma di nicchi, insieme coll’azzurrigno terreno di mare, e tutti li sassi, che di tal loco si cavano, son pieni di nicchi.","Il medesimo si conosce avere fatto Arno, quando cadea dal sasso della Gonfolina nel mare, che dopo quella non troppo basso si trovava, perchè a quelli tempi superava l’altezza di San Miniato al Tedesco, perchè nelle somme altezze di quello si vedono le ripe piene di nicchi e ostriche dentro alle sue mura; non si distesero li nicchi inverso Val di Nievole, perchè l’acque dolci d’Arno in là non si astendeano.","Come li nicchi non si partirono dal mare per Diluvio, perchè l’acque, che diverso la terra venivano, ancora che essi tirassino il mare inverso la terra, esse eran quelle, che percuoteano il suo fondo, perchè l’acqua, che viene di verso la terra, ha più corso che quella del mare, e per conseguenza è più potente, entra sotto l’altra acqua del mare, e rimove il fondo, e accompagna con seco tutte le cose mobili, che in quella trova, come son i predetti nicchi e altre simili cose, e quanto l’acqua, che vien di terra, è più torbida che quella del mare, tanto più si fa potente e grave che quella.","Adunque io non ci vedo modo di tirare i predetti nicchi tanto infra terra, se quivi nati non fussino!","Se tu mi dicessi il fiume Era, che passa per la Francia, nell’accrescimento del mare, si copre più di ottanta miglia di paese, perchè è loco di gran pianura, e ’l mare s’alza circa braccia venti, e nicchi si vengono a trovare in tal pianura, discosta dal mare esse ottanta miglia; qui si risponde che ’l flusso e riflusso ne’ nostri mediterranei mari non fanno tanta varietà, perchè in Genovese non varia nulla, a Venezia paco, in Africa poco, e dove poco varia poca occupa di paese.","Dico, che il Diluvio non potè portare le cose nate dal mare alli monti, se già il mare gonfiando non creasse innondazione insino alli lochi sopradetti, la qual gonfiazione accadere non può, perchè si darebbe vacuo.","E se tu dicessi: — l’aria quivi riempirebbe;— noi abbiamo concluso il grave non si sostenere sopra il lieve, onde per necessità si conclude, esso diluvio essere causato dall’acque piovane; e, se così è, tutte esse acque corrono al mare, e non corre il mare alle montagne; e se elle corrono al mare esse spingono li nicchi dal lito del mare, e non li tirano a sè.","E se tu dicessi: — poichè ’l mare alzò per l’acque piovane, portò essi nicchi a tale altezza; — già abbiamo detto, che le cose più gravi dell’acqua non notan sopra di lei, ma stanno ne’ fondi, dalli quali non si rimovono, se non per causa di percussion d’onda.","E se tu dirai, che l’onde le portassino in tali lochi alti, noi abbiamo provato, che l’onde nella gran profondità tornano in contrario, nel fondo, al moto di sopra, la qual cosa si manifesta per lo intorbidare del mare dal terreno tolto vicino alli liti.","Muovesi la cosa più lieve che l’acqua insieme colla sua onda, ed è lasciata nel più alto sito della riva dalla più alta onda. Muovesi la cosa più grave che l’acqua sospinta dalla sua onda nella superfizie ed al fondo suo. E per queste due conclusioni, che ai lochi sua saran provati a pieno, noi concludiamo, che l’onda superfiziale non può portare nicchi, per essere più grevi che l’acqua.","Quando il diluvio avesse avuto a portare li nicchi trecento e quattrocento miglia distanti dalli mari, esso li avrebbe portati misti con diverse nature, insieme ammontati: e noi vediamo in tal distanza l’ostriche tutte insieme e le conchiglie, e li pesci calamai, e tutti li altri nicchi, che stanno insieme a congregazione, essere trovati tutti insieme morti; e li nicchi solitari trovarsi distanti l’uno dall’altro, come nei liti marittimi tutto il giorno vediamo!","E se noi troviamo l’ostriche insieme apparentate grandissime, infra le quali assai vedi quelle, che hanno ancora il coperchio congiunto, a significare che qui furono lasciate dal mare che ancor viveano, quando fu tagliato lo stretto di Gibilterra.","Vedesi in nelle montagne di Parma e Piacenza le moltitudini di nicchi e coralli intarlati, ancora appiccati alli sassi, dei quali, quand’io facevo il gran cavallo di Milano, me ne fu portato un gran sacco nella mia fabbrica da certi villani, che in tal loco furon trovati, fra li quali ve n’era assai delli conservati nella prima bontà....","Trovansi sotto terra e sotto li profondi cavamenti de’ lastroni, li legnami delle travi lavorati, fatti già neri, li quali furon trovati a mio tempo in quel di Castel Fiorentino, e questi, in tal loco profondo, v’erano prima che la litta, gittata dall’Arno nel mare, che quivi copriva, fusse abbandonata in tant’altezza, e che le pianure del Casentino fussin tanto abbassate dal terren, che hanno al continuo di li sgomberato.","E se tu dicessi tali nicchi essere creati e creano a continuo in simili lochi per la natura del sito e de’ cieli, che quivi influisce; questa tale opinione non sta in cervelli di troppo discorso, perchè quivi s’enumerali li anni del loro accrescimento sulla loro scorza, e se ne vedono piccoli e grandi, i quali sanza cibo non crescerebbero, e non si cibarebbero sanza moto,’ e quivi movere non si poteano.","Come nelle falde, infra l’una e l’altra, si trovano ancora li andamenti delli lombrichi, che camminavano infra esse, quando non erano ancora asciutte.","Come tutti li fanghi marini ritengono ancora de’ nicchi, ed è petrificato il nicchio insieme col fango.","Della stoltizia e semplicità di quelli, che vogliono che tali animali fussino, alli lochi distanti dai mari, portati dal Diluvio.","Come altra setta d’ignoranti affermano la natura o i cieli averli in tali lochi creati per influssi celesti, come in quelli non si trovassino l’ossa de’ pesci cresciuti con lunghezza di tempo, come nelle scorze de’ nicchi e lumache non si potesse annumerare li anni o i mesi della lor vita, come nelle corna de’ buoi e de’ castroni, e nella ramificazione delle piante, che non furono mai tagliate in alcuna parte!","E avendo con tali segni dimostrato la lunghezza della lor vita essere manifesta, ecco bisogna confessare, che tali animali non vivino sanza moto, per cercare il loro cibo, e in loro non si vede strumenti da penetrare la terra e ’l sasso, ove si trovano rinchiusi.","Ma in che modo si potrebbe trovare in una gran lumaca i rottami e parte di molt’altre sorte di nicchi di varia natura, se ad essa, sopra de’ liti marini già morta, non li fussino state gettate dalle onde del mare, come dell’altre cose lievi, che esso getta a terra?","Perchè si trova tanti rottami e nicchi interi fra falda e falda di pietra, se già quella sopra del lido non fusse stata ricoperta da una terra rigettata dal mare, la qual poi si venne petrificando?","E se ’l diluvio predetto li avesse in tali siti dal mare portato, tu troveresti essi nicchi in sul termine d’una sola falda e non al termine di molte.","Devonsi poi annumerare le annate delli anni, che ’l mare multiplicava le falde dell’arena e fango, portatoli da’ fiumi vicini, e ch’elli scaricava in sui liti sua; e se tu volessi dire, che più diluvi fussino stati a produrre tali falde e nicchi infra loro, e’ bisognerebbe, che ancora tu affermassi ogni anno essere un tal diluvio accaduto.","E se tu vuoi dire, che tale diluvio fu quello, che portò tali nicchi fuor de’ mari centinaia di miglia, questo non può accadere, essendo stato esso diluvio per causa di pioggie: — perchè naturalmente le pioggie spingono i fiumi, insieme colle cose da loro portate, inverso il mare, e non tirano inverso de’ monti, le cose morte, da’ liti marittimi.","E se tu dicessi che ’l diluvio poi s’alzò colle sue acque sopra de’ monti, il moto del mare fu sì tardo, col cammino suo contro al corso de’ fiumi, che non avrebbe sopra di sè tenute a noto le cose più gravi di lui, e, se pur l’avesse sostenute, esso nel calare l’avrebbe lasciate in diversi lochi seminate. Ma come accomoderemo noi li coralli, li quali inverso Monteferrato in Lombardia essersi tutto dì trovati intarlati, appiccati alli scogli, scoperti dalla corrente de’ fiumi? E li detti scogli sono tutti coperti di parentadi e famiglie d’ostriche, le quali noi sappiamo che non si movono, ma stan sempre appiccate coll’un de’ gusci al sasso, e l’altro aprono per cibarsi d’animaluzzi, che notan per l’acque, li quali, credendo trovar bona pastura, diventano cibo del predetto nicchio.","Non si trova l’arena mista coll’aliga marina essersi petrificata, poichè l’aliga, che la tramezzava, venne meno. E di questa scopre tutto il giorno il Po nelle ruine delle sue ripe."],"cs":["Řekneš-li, že lastury, které jsou v naší době vidět na hranicích Itálie daleko od moří v tak velké výšce, se tam dostaly kvůli potopě, která je tam zanechala, odpovídám ti, že věříš-li, že ta potopa převýšila nejvyšší horu o 7 loket – jak napsal ten, kdo je změřil –, měly by takové lastury, které se vždy drží blízko mořských břehů, zůstat nahoře na těch horách, a ne tak nízko nad úpatím hor, všude v jedné a téže výšce, vrstvu po vrstvě. A řekneš-li, že ty lastury, toužíce zůstat blízko mořských břehů, když voda vystoupila do takové výše, opustily své první místo a následovaly vzestup vod až do jejich nejvyšší výšky, odpovídá se, že lastura je živočich, který se mimo vodu nepohybuje rychleji než hlemýžď – a je ještě o něco pomalejší, protože neplave, nýbrž si dělá brázdu, o kterou se opírá –, a ujde za den 3 až 4 lokte. S takovým pohybem by tedy neušla od Jaderského moře až do Monferrata v Lombardii, kam je vzdálenost 250 mil, za 40 dní – jak řekl ten, kdo ten čas počítal.","A říkáš-li, že je tam přinesly vlny, ty se pro svou tíži neudrží jinde než na jejich dně; a nepřipustíš-li mi to, přiznej mi aspoň, že měly zůstat na vrcholcích nejvyšších hor a v jezerech, která jsou sevřena mezi horami, jako je jezero Lario čili Komské, Maggiore, jezero u Fiesole a u Perugie a podobná.","A řekneš-li, že lastury byly přineseny vlnami, když byly prázdné a mrtvé, pravím, že kam šly mrtvé, tam se jen málo vzdalovaly od živých, a v těchto horách se nacházejí všechny živé, které poznáme podle toho, že mají skořápky spojené v páru, a jsou v jedné vrstvě, kde není žádná z mrtvých; a o něco výše se nachází místo, kam vlny vyhazovaly všechny mrtvé s jejich oddělenými skořápkami, blízko míst, kde řeky padaly do moře do velké hloubky. A kdyby lastury byly přineseny kalnou potopou, byly by se smíchaly jednotlivě jedna od druhé v bahně, a ne v uspořádaných stupních po vrstvách, jak je vidíme v naší době.","Těm se odpoví, že je-li to takový příval živočichů, nemohli by se v jediné linii nacházet než živočichové téhož druhu a věku, a ne starý s mladým, a ne jeden s víčkem a druhý bez své přikrývky, a ne jeden rozbitý a druhý celý, a ne jeden naplněný mořským pískem a drobnými i hrubými úlomky jiných lastur uvnitř celých lastur, které tam zůstaly otevřené, a ne klepeta krabů bez zbytku jejich celku, a ne lastury jiných druhů k nim přichycené v podobě živočicha, který se po nich pohyboval, neboť dosud zůstává stopa jeho pochodu na skořápce, kterou on, jako červotoč dřevo, postupně rozhlodával; nenacházely by se mezi nimi kosti a zuby ryb, které někteří nazývají střelami a jiní hadími jazyky, a nenacházelo by se tolik údů rozličných živočichů spojených dohromady, kdyby tam nebyly vyhozeny z mořských břehů.","A potopa by je tam nebyla přinesla, protože věci těžší než voda neplavou na vodě, a řečené věci by nebyly v takové výšce, leda by tam byly přineseny plovoucí po vodách, což je pro jejich tíži nemožné.","Kde údolí nepřijímají slané vody moře, tam lastury nikdy nevidíme, jak je zjevně vidět ve velkém údolí Arna nad Gonfolinou, skalou kdysi spojenou s Monte Albanem v podobě převysoké hráze, která držela tu řeku vzdutou tak, že než se vlila do moře, které bylo tehdy u paty té skály, tvořila dvě velká jezera, z nichž první je tam, kde dnes vidíme kvést město Florencii spolu s Pratem a Pistoií, a Monte Albano tvořil zbytek hráze až tam, kde dnes leží Serravalle. Od horního Valdarna až k Arezzu se tvořilo druhé jezero, které vlévalo své vody do jezera předchozího, uzavřené zhruba tam, kde dnes vidíme Girone, a zaujímalo celé řečené horní údolí v délce čtyřiceti mil. Toto údolí přijímá na své dno všechnu zeminu přinesenou vodou, jí zakalenou, a ta je dosud vidět na úpatí Pratomagna jako převysoká vrstva tam, kde ji řeky nevymlely; a v té zemině jsou vidět hluboké zářezy řek, které tudy prošly a sestupují z velké hory Pratomagno, a v těch zářezech není vidět žádná stopa lastur ani mořské zeminy. Toto jezero se spojovalo s jezerem u Perugie.","Velké množství lastur je vidět tam, kde řeky ústí do moře, ačkoli na takových místech vody nejsou tak slané kvůli příměsi sladkých vod, které se s nimi spojují. A znamení toho je vidět tam, kde kdysi Apeniny vlévaly své řeky do Jaderského moře; ty z velké části ukazují mezi horami velké množství lastur spolu s modravou mořskou zeminou, a všechny kameny, které se z takového místa lámou, jsou plné lastur.","Totéž, jak víme, způsobilo Arno, když padalo ze skály Gonfoliny do moře, které bylo za ní nepříliš nízko, neboť v těch dobách převyšovalo výšku San Miniata al Tedesco; neboť na jeho nejvyšších místech jsou vidět svahy plné lastur a ústřic uvnitř jeho hradeb; lastury se nerozšířily směrem k Val di Nievole, protože sladké vody Arna tam nedosahovaly.","Jak lastury neodešly z moře potopou, neboť vody, které přicházely od země, ačkoli táhly moře k zemi, byly to ony, které bily do jeho dna, protože voda, která přichází od země, má větší proud než voda mořská, a je tudíž mocnější; vniká pod ostatní mořskou vodu, hýbe dnem a unáší s sebou všechny pohyblivé věci, které v něm nalézá, jako jsou řečené lastury a jiné podobné věci; a čím je voda přicházející od země kalnější než mořská, tím je mocnější a těžší než ona.","Nevidím tedy způsob, jak dostat řečené lastury tak daleko do vnitrozemí, kdyby se tam nebyly zrodily!","Kdybys mi řekl, že řeka Era, která protéká Francií, při vzestupu moře zaplavuje přes osmdesát mil krajiny, protože je to místo veliké roviny, a moře stoupá asi o dvacet loket, a lastury se nacházejí na té rovině vzdálené od moře oněch osmdesát mil, odpovídá se, že příliv a odliv v našich středozemních mořích nečiní tak velké výkyvy, neboť u Janova se nemění nic, v Benátkách málo, v Africe málo, a kde se mění málo, tam zaujme málo krajiny.","Pravím, že potopa nemohla přinést věci zrozené v moři do hor, leda by moře, vzdouvajíc se, způsobilo záplavu až na řečená místa; a takové vzdutí nastat nemůže, protože by vzniklo prázdno.","A kdybys řekl: „Vzduch by to místo vyplnil“ – dovodili jsme, že těžké se neudrží nad lehkým, z čehož se nutně dovozuje, že ta potopa byla způsobena dešťovými vodami; a je-li tomu tak, všechny ty vody tečou do moře, a ne moře do hor; a tečou-li do moře, odstrkují lastury od mořského břehu, a netáhnou je k sobě.","A kdybys řekl: „Když moře stouplo dešťovými vodami, přineslo ty lastury do takové výšky“ – už jsme řekli, že věci těžší než voda na ní neplavou, nýbrž zůstávají na dně, z něhož se nehnou, leda nárazem vlny.","A řekneš-li, že vlny je donesly na taková vysoká místa, dokázali jsme, že vlny se ve velké hloubce u dna vracejí opačně, než je pohyb nahoře, což se ukazuje na zakalování moře zeminou vzatou poblíž břehů.","Věc lehčí než voda se pohybuje spolu s její vlnou a je zanechána na nejvyšším místě břehu nejvyšší vlnou. Věc těžší než voda se pohybuje, postrkována její vlnou, na povrchu i u jejího dna. A z těchto dvou závěrů, které budou na svých místech plně dokázány, vyvozujeme, že povrchová vlna nemůže nést lastury, protože jsou těžší než voda.","Kdyby byla potopa měla přenést lastury tři sta a čtyři sta mil od moří, byla by je přinesla smíšené rozličných druhů, nahromaděné dohromady; a my vidíme v takové vzdálenosti ústřice všechny pohromadě, i mušle, i sépie a všechny ostatní lastury, které žijí pospolu v hejnech, nalezené všechny pohromadě mrtvé; a lastury samotářské nalezené daleko jedna od druhé, jak to denně vidíme na mořských březích!","A nacházíme-li ústřice spolu spříbuzněné, převeliké, mezi nimiž vidíš mnoho takových, které mají ještě připojené víčko, je to znamením, že je tam zanechalo moře, když ještě žily, v době, kdy byl proražen Gibraltarský průliv.","Vidíme v horách u Parmy a Piacenzy množství lastur a korálů provrtaných červy, dosud přichycených ke skalám; z nich, když jsem dělal velkého koně v Miláně, mi jistí venkované přinesli do mé dílny velký pytel, který byl na takovém místě nalezen, a mezi nimi bylo mnoho zachovaných v původní kvalitě…","Nacházejí se pod zemí a v hlubokých lomech kamenných desek opracovaná trámová dřeva, již zčernalá, která byla za mých časů nalezena v kraji Castelfiorentina; a ta byla na tak hlubokém místě dříve, než naplavenina, vržená Arnem do moře, které tam sahalo, byla zanechána v takové výšce a než byly roviny Casentina tak sníženy zeminou, kterou z nich ustavičně odnáší.","A kdybys řekl, že takové lastury byly a ustavičně jsou tvořeny na podobných místech přirozeností místa a nebes, která tam působí, takové mínění se neudrží v hlavách příliš rozumných, neboť tam lze napočítat léta jejich růstu na jejich skořápce, a je jich vidět malých i velkých, které by bez potravy nerostly a bez pohybu by se nenasytily, a tam se pohybovat nemohly.","Jak se ve vrstvách, mezi jednou a druhou, dosud nacházejí chodbičky žížal, které se mezi nimi pohybovaly, když ještě nebyly suché.","Jak všechna mořská bahna dosud obsahují lastury a lastura zkameněla spolu s bahnem.","O hlouposti a prostoduchosti těch, kdo chtějí, aby takoví živočichové byli na místa vzdálená od moří přineseni potopou.","Jak jiná sekta nevzdělanců tvrdí, že je příroda či nebesa na takových místech stvořila nebeskými vlivy, jako by se v nich nenacházely kosti ryb, které rostly po dlouhou dobu, jako by se na skořápkách lastur a hlemýžďů nedaly spočítat roky či měsíce jejich života, jako na rozích volů a skopců a na rozvětvení rostlin, které nikdy nebyly na žádném místě přiříznuty!","A když jsme takovými znameními ukázali, že délka jejich života je zjevná, hle, je třeba přiznat, že takoví živočichové nežijí bez pohybu, aby hledali potravu, a nevidíme na nich nástroje k pronikání zemí a kamenem, v nichž se nacházejí uzavřeni.","Ale jak by se mohly ve velkém hlemýždi najít úlomky a části mnoha jiných druhů lastur rozličné povahy, kdyby do něho, už mrtvého na mořských březích, nebyly vhozeny vlnami moře, tak jako jiné lehké věci, které moře vyhazuje na zem?","Proč se nachází tolik úlomků a celých lastur mezi vrstvou a vrstvou kamene, ledaže by vrstva na břehu byla pokryta zeminou vyvrženou mořem, která potom zkameněla?","A kdyby je řečená potopa byla na taková místa přinesla z moře, nalezl bys ty lastury na mezi jediné vrstvy, a ne na mezích mnoha.","Dále je třeba spočítat léta, po která moře rozmnožovalo vrstvy písku a bahna, jež mu přinášely blízké řeky a jež ono ukládalo na své břehy; a kdybys chtěl říci, že takové vrstvy a lastury mezi nimi vytvořilo více potop, musel bys také tvrdit, že taková potopa nastala každý rok.","A chceš-li říci, že to byla taková potopa, která přenesla takové lastury stovky mil z moří, to se stát nemůže, protože ta potopa byla způsobena dešti; – neboť deště přirozeně ženou řeky spolu s věcmi, které nesou, k moři, a netáhnou k horám mrtvé věci z mořských břehů.","A kdybys řekl, že potopa pak vystoupila se svými vodami nad hory, pohyb moře byl při jeho postupu proti proudu řek tak pomalý, že by na sobě neudržel na hladině věci těžší, než je ono samo; a i kdyby je byl udržel, při opadání by je byl zanechal rozeseté na různých místech. Ale jak si vysvětlíme korály, které se u Monferrata v Lombardii denně nacházejí provrtané červy, přichycené ke skaliskům, odkrytým proudem řek? A řečená skaliska jsou celá pokryta příbuzenstvy a rodinami ústřic, o nichž víme, že se nepohybují, ale zůstávají vždy jednou skořápkou přichyceny ke kameni a druhou otevírají, aby se živily drobnými živočichy, kteří plavou vodou a kteří, domnívajíce se, že najdou dobrou pastvu, stanou se potravou řečené lastury.","Což se nenachází písek smíšený s mořskou řasou zkamenělý, když řasa, která jej prostupovala, zmizela? A takový písek denně odkrývá Pád v sesuvech svých břehů."],"ref":{"s":"R","l":984,"st":"","z":false,"raw":"R. 984"},"ca":[],"rr":"Leic. 31 a"},{"id":"s319","o":"Pensieri sulla natura","c":"LXXXIV","str":161,"ni":"de’ nicchi ne’ monti","nc":"O lasturách v horách","it":["E se tu vorrai dire li nicchi esser prodotti dalla natura in essi monti mediante le costellazioni, per qual via mostrerai tal costellazione fare li nicchi di varie grandezze e di diverse età e di varie spezie ’n un medesimo sito?","E come mi mostrerai la ghiara congelata a gradi in diverse altezze delli monti, perchè quivi è di diverse ragioni, ghiare portate di diversi paesi dal corso de’ fiumi in tal sito; e la ghiara non è altro che pezzi di pietra, che han persi li angoli per la lunga rivoluzione e le diverse percussioni e cadute, ch’ell’ha avuto mediante li corsi delle acque, che in tal loco le condusse?","Come proverai il grandissimo numero di varie spezie di foglie congelate nelli alti sassi di tal monte, e l’aliga, erba di mare, stante a diacere mista con nicchi e rena? E così vedrai ogni cosa petrificata insieme con granchi marini, rotti in pezzi, separati e tramezzati da essi nicchi."],"cs":["A chceš-li říci, že lastury jsou v těch horách tvořeny přírodou působením souhvězdí, jakým způsobem ukážeš, že takové souhvězdí tvoří lastury rozličných velikostí, rozličného stáří a rozličných druhů na jednom a témž místě?","A jak mi vysvětlíš štěrk stmelený ve stupních v různých výškách hor, když je tam štěrk různého druhu, přinesený z různých krajů tokem řek na takové místo; a štěrk není nic jiného než kusy kamene, které ztratily hrany dlouhým valením a rozličnými nárazy a pády, jež prodělaly tokem vod, které je na takové místo přivedly?","Jak vysvětlíš převeliké množství rozličných druhů listů stmelených ve vysokých skalách takové hory a řasu, mořskou trávu, ležící smíšenou s lasturami a pískem? A tak uvidíš všechno zkamenělé spolu s mořskými kraby, rozlámanými na kusy, oddělenými a proloženými těmi lasturami."],"ref":{"s":"F","l":80,"st":"r","z":false,"raw":"F. 80 r"},"ca":[]},{"id":"s320","o":"Pensieri sulla natura","c":"LXXXV","str":162,"ni":"sulla stratificazione geologica e contro il diluvio","nc":"O geologickém vrstvení a proti potopě","it":["Per le due linee de’ nicchi bisogna dire che la terra per sdegno s’attuffasse sotto il mare a fare il primo suolo, poi il Diluvio fece il secondo!"],"cs":["Kvůli dvěma vrstvám lastur by se muselo říci, že se země ze vzteku ponořila pod moře, aby vytvořila první vrstvu, a pak potopa vytvořila druhou!"],"ref":{"s":"R","l":994,"st":"","z":false,"raw":"R. 994"},"ca":[],"rr":"Br. M. 156 b"},{"id":"s321","o":"Pensieri sulla natura","c":"LXXXVI","str":162,"ni":"dubitazione","nc":"Pochybnost","it":["Movesi qui un dubbio, e questo è se ’l diluvio venuto al tempo di Noè fu universale o no, e qui parrà di no per le ragioni, che si assegneranno. Noi nella Bibbia abbiam che il predetto diluvio fu composto di 40 dì e 40 nocte di continua e universa pioggia, e che tal pioggia alzò di sei gomiti sopra al più alto monte dell’universo; e se così fu, che la pioggia fussi universale, ella vestì di sè la nostra terra di figura sperica, e la superfizie sperica ha ogni sua parte egualmente distante al centro della sua spera; onde la spera dell’acqua trovandosi nel modo della detta condizione, elli è impossivile che l’acqua sopra di lei si mova, perchè l’acqua in sè non si move, s’ella non discende; adunque l’acqua di tanto diluvio come si partì, se qui è provato non aver moto? E s’ella si partì, come si mosse, se ella non andava allo in su? E qui mancano le ragioni naturali, onde bisogna per soccorso di tal dubitazione, chiamare il miracolo per aiuto, o dire che tale acqua fu vaporata dal calor del sole."],"cs":["Vyvstává zde pochybnost, a ta je, zda potopa, která přišla v době Noemově, byla všeobecná, či ne; a zde se bude zdát, že nebyla, z důvodů, které budou uvedeny. V Bibli máme, že řečená potopa sestávala ze 40 dní a 40 nocí ustavičného a všeobecného deště a že ten déšť vystoupil o šest loket nad nejvyšší horu světa; a bylo-li tomu tak, že déšť byl všeobecný, oděl naši zemi sebou v kulovém tvaru, a kulový povrch má každou svou část stejně vzdálenou od středu své koule; a protože se vodní koule nacházela v takovém stavu, je nemožné, aby se voda na ní pohybovala, neboť voda se sama sebou nepohybuje, leda když sestupuje; jak tedy odtekla voda tak velké potopy, když je zde dokázáno, že neměla pohyb? A jestliže odtekla, jak se pohnula, když nešla vzhůru? A zde chybějí přirozené důvody, a proto je třeba na pomoc této pochybnosti přivolat zázrak, anebo říci, že ta voda se vypařila žárem slunce."],"ref":{"s":"C.A","l":155,"st":"r","z":false,"raw":"C. A. 155 r"},"ca":[834,836,838,840]},{"id":"s322","o":"Pensieri sulla natura","c":"LXXXVII","str":163,"ni":"quale sarà il termine della vita nel mondo","nc":"Jaký bude konec života na světě","it":["Riman lo elemento dell’acqua rinchiuso infra li cresciuti argini de’ fiumi, e si vede il mare infra la cresciuta terra; e la circundatrice aria, avendo a fasciare e circonscrivere la mollificata macchina della terra, la sua; grossezza, che stava fra l’acqua e lo elemento del foco, rimarrà molto ristretta e privata della bisognosa acqua. I fiumi rimarranno senza le loro acque, la fertile terra non manderà più leggere fronde, non fieno più i campi adornati dalle ricascanti piante; tutti li animali non trovando da pascere le fresche erbe, morranno; e mancherà il cibo ai rapaci lioni e lupi e altri animali, che vivono di ratto; e agli omini, dopo molti ripari, converrà abbandonare la loro vita, e mancherà la generazione umana.","A questo modo la fertile e fruttuosa terra, abbandonata, rimarrà arida e sterile; e, pel rinchiuso omore dell’acqua (rinchiusa nel suo ventre) e per la vivace natura, osserverà alquanto dello suo accrescimento, tanto che, passata la fredda e sottile aria, sia costretta a terminare collo elemento del foco: allora la sua superfìce rimarrà in riarsa cenere, e questo fia il termine della terrestre natura."],"cs":["Živel vody zůstane uzavřen mezi vzrostlými břehy řek a moře bude vidět mezi vzrostlou zemí; a obklopující vzduch, maje ovinout a obepnout změkčený stroj země, jeho tloušťka, která byla mezi vodou a živlem ohně, zůstane velmi zúžená a zbavená potřebné vody. Řeky zůstanou bez svých vod, úrodná země už nevydá lehké listí, pole už nebudou zdobena svěšenými rostlinami; všechna zvířata, nenacházejíce k pastvě svěží byliny, zemřou; a nedostane se potravy dravým lvům a vlkům a jiným zvířatům, která žijí z loupeže; a lidé budou po mnoha marných obranách nuceni opustit svůj život, a lidské pokolení zanikne.","Tímto způsobem úrodná a plodná země, opuštěná, zůstane vyprahlá a neplodná; a uzavřenou vláhou vody (uzavřené v jejím lůně) a svou živou přirozeností si ještě zachová trochu svého růstu, dokud, když pomine studený a řídký vzduch, nebude nucena hraničit s živlem ohně; tehdy její povrch zůstane spáleným popelem, a to bude konec pozemské přírody."],"ref":{"s":"R","l":995,"st":"","z":false,"raw":"R. 995"},"ca":[],"rr":"Leic. 20 a"},{"id":"s323","o":"Pensieri sulla natura","c":"LXXXVIII","str":165,"ni":"la terra immersa nell’acqua per la lenta consumazione de’ monti","nc":"Země ponořená ve vodě pomalým rozrušováním hor","it":["Perpetui son li bassi lochi del fondo del mare, e il contrario son le cime de’ monti, seguita che la terra si farà sperica e tutta coperta dall’acque, e sarà inabitabile."],"cs":["Nízká místa mořského dna jsou trvalá a opakem jsou vrcholky hor; z toho plyne, že se země stane kulovou a celá pokrytou vodami, a bude neobyvatelná."],"ref":{"s":"F","l":52,"st":"v","z":false,"raw":"F. 52 v"},"ca":[]},{"id":"s324","o":"Pensieri sulla natura","c":"LXXXIX","str":165,"ni":"le leggi meccaniche dominano i fenomeni inorganici e organici","nc":"Mechanické zákony vládnou jevům neústrojným i ústrojným","it":["La scienza strumentale, over macchinale, è nobilissima e sopra tutte l’altre utilissima, conciò sia che mediante quella tutti li corpi animati, che hanno moto fanno tutte loro operazioni; i quali moti nascono dal centro della lor gravità, che è posto in mezzo a parti di pesi diseguali, e ha questo carestia e dovizia di muscoli ed etiam lieva e contra lieva."],"cs":["Věda o nástrojích čili o strojích je nejvznešenější a nade všechny ostatní nejužitečnější, neboť jejím prostřednictvím konají všechna oduševnělá tělesa, která mají pohyb, všechny své úkony; a tyto pohyby vycházejí ze středu jejich tíže, který je umístěn uprostřed částí nestejných vah, a má to nedostatek i hojnost svalů a také páku a protipáku."],"ref":{"s":"V.U","l":3,"st":"r","z":false,"raw":"V. U. 3 r"},"ca":[]},{"id":"s325","o":"Pensieri sulla natura","c":"XC","str":165,"ni":"possibilità che ha l’uomo d’imitare strumentalmente l’uccello volante","nc":"Možnost, aby člověk nástrojem napodobil letícího ptáka","it":["L’uccello è strumento oprante per legge matematica, il quale strumento è in potestà dell’omo poterlo fare con tutti li sua moti, ma non con tanta potenza; ma solo s’astende nella potenza del bilicarsi. Adunque direm che tale strumento, composto per l’omo, non li manca se non l’anima dello uccello, la quale anima bisogna, che sia contraffatta dall’anima dell’omo.","L’anima alle membra delli uccelli, sanza dubbio, obbidirà meglio a’ bisogni di quelle, che a quelle non farebbe l’anima dell’omo, da esse separato, e massimamente ne’ moti di quasi insensibili bilicazioni; ma poi che alle molte sensibili varietà di moti noi vediamo l’uccello provvedere, noi possiamo, per tale esperienza, giudicare, che le forze sensibili potranno essere note alla cognizione dell’omo, e che esso largamente potrà provvedere alla ruina di quello strumento, del quale lui s’è fatto anima e guida."],"cs":["Pták je nástroj pracující podle matematického zákona, a ten nástroj je v moci člověka zhotovit se všemi jeho pohyby, ale ne s takovou silou; jeho síla však sahá jen k udržování rovnováhy. Řekneme tedy, že takovému nástroji, sestrojenému člověkem, nechybí nic než duše ptáka, a tu duši je třeba napodobit duší člověka.","Duše v údech ptáků bude bezpochyby lépe poslouchat jejich potřeby, než by je poslouchala duše člověka, od nich oddělená, a zvláště při pohybech téměř nepostřehnutelného vyvažování; ale protože vidíme, že pták dovede čelit mnoha postřehnutelným rozdílům pohybů, můžeme z takové zkušenosti usoudit, že postřehnutelné síly budou moci být známy poznání člověka a že on bude moci hojně zabránit zřícení toho nástroje, jehož se stal duší a vůdcem."],"ref":{"s":"F","l":52,"st":"r","z":false,"raw":"F. 52 r"},"ca":[]},{"id":"s326","o":"Pensieri sulla natura","c":"XCI","str":166,"ni":"ricordo, che ritorna all’anima del vinci mentre scrive sul volo del nibbio","nc":"Vzpomínka na luňáka","it":["Questo scriver sì distintamente del nibbio par che sia mio destino, perchè ne la prima ricordazione della mia infanzia e’ mi parea che, essendo io in culla, che un nibbio venissi a me, e mi aprissi la bocca colla sua coda, e molte volte mi percotessi con tal coda dentro alle labbra."],"cs":["Psát tak podrobně o luňáku je, zdá se, mým osudem, neboť v první vzpomínce mého dětství se mi zdálo, že když jsem byl v kolébce, přiletěl ke mně luňák, otevřel mi ústa svým ocasem a mnohokrát mě tím ocasem udeřil mezi rty."],"ref":{"s":"C.A","l":161,"st":"r","z":false,"raw":"C. A. 161 r"},"ca":[866,868]},{"id":"s327","o":"Pensieri sulla natura","c":"XCII","str":167,"ni":"perchè li piccoli uccelli non volano in grande altezza, ne li grandi uccelli si dilettano volare in basso","nc":"Proč malí ptáci nelétají vysoko","it":["Nasce per causa che li piccoli uccelli, essendo sanza piume, non reggano alla immensa freddezza della grande altura dell’aria, nella quale li avvoltoi e le aquile e altri grossi uccelli, ben piumosi e vestiti di molti gradi di penne.","Ancora li uccelli piccoli, con deboli e scempie ali, si sostengano in questa aria bassa, che è grossa, e non si sosterrebbono nell’aria sottile, che poco resista."],"cs":["Pochází to z toho, že malí ptáci, jsouce bez peří, nesnesou nesmírný chlad velké výšky vzduchu, v níž jsou supi, orli a jiní velcí ptáci, dobře opeření a odění mnoha vrstvami per.","Dále se malí ptáci se slabými a jednoduchými křídly udrží v tomto nízkém vzduchu, který je hustý, a neudrželi by se v řídkém vzduchu, který málo vzdoruje."],"ref":{"s":"H","l":89,"st":"v","z":false,"raw":"H. 89 v"},"ca":[]},{"id":"s328","o":"Pensieri sulla natura","c":"XCIII","str":167,"ni":"facciamo nostra vita coll’altrui morte","nc":"Žijeme ze smrti jiných","it":["In nella cosa morta riman vita dissensata, la quale, ricongiunta alli stomachi dei vivi, ripiglia vita sensitiva e ’ntellettiva."],"cs":["V mrtvé věci zůstává život bez smyslů, který, spojen znovu se žaludky živých, nabývá opět života smyslového a rozumového."],"ref":null,"ca":[]},{"id":"s329","o":"Pensieri sulla natura","c":"XCIV","str":167,"ni":"come il corpo dell’animale al continuo more e rinasce","nc":"Jak tělo živočicha ustavičně umírá a znovu se rodí","it":["Il corpo di qualunque cosa, la qual si nutrica, al continuo more e al continuo rinasce, perchè entrare non po’ nutrimento, se non in quelli lochi, dove il passato nutrimento è spirato; e s’elli è spirato, elli più non ha vita; e se tu non li rendi nutrimento eguale al nutrimento partito, allora la vita manca di sua valetudine; e se tu li levi esso nutrimento, la vita in tutto resta distrutta. Ma se tu ne rendi tanto quanto se ne distrugge alla giornata, allora tanto rinasce di vita, quanto se ne consuma, a similitudine del lume della candela col nutrimento datoli dall’omore d’essa candela: il quale lume ancora lui al continuo con velocissimo soccorso restaura di sotto, quanto di sopra se ne consuma morendo; e di splendida luce si converte, morendo, in tenebroso fumo, la qual morte è continua, siccome è continuo esso fumo, e la continuità di tal fumo è eguale al continuato nutrimento; e in istante tutto il lume è morto e tutto rigenerato, insieme col moto del nutrimento suo."],"cs":["Tělo každé věci, která se živí, ustavičně umírá a ustavičně se znovu rodí, neboť potrava nemůže vstoupit jinam než do těch míst, kde předchozí potrava vydechla; a jestliže vydechla, nemá už život; a nevrátíš-li mu potravu rovnou potravě odešlé, pak život pozbývá své síly; a odejmeš-li mu tu potravu, život je zcela zničen. Ale vrátíš-li mu tolik, kolik se ho denně zničí, pak se znovu zrodí tolik života, kolik se ho spotřebuje, podobně jako světlo svíce s potravou, kterou mu dává lůj té svíce: i to světlo ustavičně s nejrychlejší pomocí obnovuje zdola, kolik se ho nahoře umíráním spotřebuje; a ze zářivého světla se umíráním mění v temný dým, a ta smrt je nepřetržitá, jako je nepřetržitý ten dým, a nepřetržitost toho dýmu se rovná nepřetržité potravě; a v okamžiku je celé světlo mrtvé a celé znovu zrozené spolu s pohybem jeho potravy."],"ref":null,"ca":[]},{"id":"s330","o":"Pensieri sulla natura","c":"XCV","str":168,"ni":"circolazione della materia","nc":"Koloběh hmoty","it":["L’omo e li animali sono proprio transito e condotto di cibo, sepoltura di animali, albergo de’ morti, guaina di corruzione, facendo a sè vita dell’altrui morte."],"cs":["Člověk a zvířata jsou vlastně průchodem a rourou potravy, hrobem zvířat, útulkem mrtvých, pochvou zkázy, tvoříce si život ze smrti jiných."],"ref":{"s":"R","l":483,"st":"","z":false,"raw":"R. 483"},"ca":[],"rr":"Ash. I. 18 a"},{"id":"s331","o":"Pensieri sulla natura","c":"XCVI","str":169,"ni":"sullo stesso soggetto","nc":"K téže věci","it":["Guarda il lume e considera la sua bellezza. Batti l’occhio e riguardalo: ciò che di lui tu vedi, prima non era e, ciò che di lui era, più non è.","Chi è quel che lo rifà, se ’l fattore al continuo muore?"],"cs":["Pohleď na plamen a uvaž jeho krásu. Mrkni okem a pohleď na něj znovu: co z něho vidíš, předtím nebylo, a co z něho bylo, už není.","Kdo je ten, kdo jej znovu tvoří, když tvůrce ustavičně umírá?"],"ref":{"s":"F","l":49,"st":"v","z":false,"raw":"F. 49 v"},"ca":[]},{"id":"s332","o":"Pensieri sulla natura","c":"XCVII","str":169,"ni":"ancora sullo stesso soggetto","nc":"Opět k téže věci","it":["Anassagora. Ogni cosa vien da ogni cosa, ed ogni cosa si fa ogni cosa, e ogni cosa torna in ogni cosa, perchè ciò ch’è nelli elementi è fatto da essi elementi."],"cs":["Anaxagorás. Každá věc pochází z každé věci, a každá věc se stává každou věcí, a každá věc se vrací v každou věc, neboť co je v živlech, je učiněno z těch živlů."],"ref":{"s":"C.A","l":376,"st":"v","z":false,"raw":"C. A. 376 v"},"ca":[2095,2097]},{"id":"s333","o":"Pensieri sulla natura","c":"XCVIII","str":169,"ni":"sulla esistenza della morte e del dolore nel mondo","nc":"O existenci smrti a bolesti na světě","it":["La natura pare qui in molti o di molti animali stata più presto crudele matrigna che madre, o d’alcuni non matrigna, ma pietosa madre."],"cs":["Příroda se zde zdá být mnohým nebo pro mnohá zvířata spíše krutou macechou než matkou, nebo některým ne macechou, nýbrž soucitnou matkou."],"ref":{"s":"R","l":846,"st":"","z":false,"raw":"R. 846"},"ca":[],"rr":"S. K. M. III. 74 a"},{"id":"s334","o":"Pensieri sulla natura","c":"XCIX","str":169,"ni":"sul medesimo soggetto","nc":"K téže věci","it":["Perchè la natura non ordinò, che l’uno animale non vivesse della morte dell’altro?","La natura, essendo vaga e pigliando piacere del creare e fare continue vite e forme, perchè conosce, che sono accrescimento della sua terrestre materia, è volonterosa e più presta nel suo creare, che ’l tempo col consumare, e però ha ordinato, che molti animali siano cibo l’uno dell’altro: e, non soddisfacendo questo a simile desiderio, spesso manda fuora certi avvelenati e pestilenti vapori, sopra le gran moltiplicazioni e congregazioni d’animali e massime sopra gli omini, che fanno grande accrescimento, perchè altri animali non si cibano di loro; e tolte via le cagioni mancheranno li effetti.","Adunque, questa terra cerca di mancare di sua vita, desiderando la continua moltiplicazione.","Per la tua assegnata e demonstrata ragione spesso li effetti somigliano le loro cagioni: gli animali sono esemplo della vita mondiale."],"cs":["Proč příroda nezařídila, aby jedno zvíře nežilo ze smrti druhého?","Příroda, jsouc dychtivá a mající zalíbení v tvoření a činění ustavičných životů a tvarů, neboť ví, že jsou rozmnožením její pozemské hmoty, je ochotnější a rychlejší ve svém tvoření, než je čas ve svém ničení; a proto zařídila, aby mnohá zvířata byla potravou jedno druhému; a když to takové touze nestačí, často vysílá jakési otrávené a morové výpary na velká rozmnožení a shromáždění zvířat, a zvláště na lidi, kteří se velice rozmnožují, protože se jimi jiná zvířata neživí; a odstraníš-li příčiny, ustanou účinky.","Tato země tedy usiluje o pozbytí svého života, toužíc po ustavičném rozmnožování.","Podle tvého uvedeného a dokázaného důvodu se účinky často podobají svým příčinám: zvířata jsou obrazem života světa."],"ref":{"s":"R","l":1219,"st":"","z":false,"raw":"R. 1219"},"ca":[],"rr":"Br. M. 156 b"},{"id":"s335","o":"Pensieri sulla natura","c":"C","str":170,"ni":"desiderio di disfarsi nelle cose e negli esseri","nc":"Touha věcí a bytostí po vlastním rozpadu","it":["Or vedi, la speranza e ’l desiderio del ripatriarsi e ritornare nel primo caso, fa a similitudine della farfalla al lume, e l’uomo, che con continui desideri sempre con festa aspetta la nuova primavera e sempre la nuova state, sempre e nuovi mesi e nuovi anni, parendogli che le desiderate cose, venendo, sieno troppo tarde, e’ non s’avvede, che desidera la sua disfazione!...","Ma questo desiderio è la quintessenza, spirito degli elementi, che, trovandosi rinchiusa per l’anima dello umano corpo, desidera sempre ritornare al suo mandatario. E vo’ che sappi, che questo medesimo desiderio è quella quintessenza, compagnia della natura, e l’uomo è modello dello mondo.","E questo uomo ha una somma pazzia che sempre stenta per non stentare, e la vita a lui fugge sotto speranza, di godere i beni con somma fatica acquistati."],"cs":["Hle, naděje a touha vrátit se do vlasti a do prvního stavu počínají si jako můra u světla; a člověk, který s ustavičnými tužbami vždy s radostí očekává nové jaro a vždy nové léto, vždy nové měsíce a nové roky, zdá-li se mu, že vytoužené věci přicházejí příliš pozdě, nevidí, že touží po svém vlastním rozkladu!…","Ale tato touha je kvintesence, duch živlů, která, ocitajíc se uzavřena jako duše lidského těla, touží vždy vrátit se k tomu, kdo ji vyslal. A chci, abys věděl, že tatáž touha je ona kvintesence, družka přírody, a člověk je obrazem světa.","A tento člověk má nejvyšší bláznovství, že se stále lopotí, aby se nemusel lopotit, a život mu utíká v naději, že bude užívat statků nabytých nejvyšší námahou."],"ref":{"s":"R","l":1187,"st":"","z":false,"raw":"R. 1187"},"ca":[],"rr":"S. K. M. III. 77 a"},{"id":"s336","o":"Pensieri sulla natura","c":"CI","str":171,"ni":"come i sensi sono offiziali dell’anima","nc":"Jak jsou smysly úředníky duše","it":["L’anima pare risiedere nella parte judiziale, e la parte judiziale pare essere nel loco, dove concorrono tutti i sensi, il quale è detto senso comune, e non è tutta per tutto il corpo, come molti hanno creduto; anzi tutta in nella parte, imperocchè, se ella fusse tutta per tutto e tutta in ogni parte, non era necessario li strumenti de’ sensi fare in fra loro uno medesimo concorso a uno solo loco, anzi bastava che l’occhio operasse l’uffizio del sentimento sulla sua superfizie e non mandare, per la via delli nervi ottici, la similitudine delle cose vedute al senso, che l’anima, alla sopra detta ragione, le poteva comprendere in essa superfizie dell’occhio. E similmente al senso dell’udito bastava solamente la voce risonasse nelle concave porosità dell’osso petroso, che sta dentro all’orecchio, e non fare da esso osso al senso comune altro transito, dove essa s’abbocca, e abbia a discorrere al comune giudizio.","Il senso dell’odorato ancora lui si vede essere dalla necessita costretto a concorreire a detto judizio; il tatto passa per le corde forate, ed è portato a esso senso, le quali corde si vanno spargendo, con infinita ramificazione, in nella pelle, che circonda le corporee membra e visceri.","Le corde perforate portano il comandamento e sentimento delli membri offiziali, le quali corde e nervi, infra i muscoli e le coste, comandano a quelli il movimento; quelli ubbidiscono e tale obbedienza si mette in atto collo sgonfiare, imperocchè ’l sgonfiare raccorta le loro lunghezze e tirasi dirieto i nervi, i quali si tessono per le particule de’ membri, essendo infusi nelli stremi de’ diti, portano al senso la cagione del loro contatto.","I nervi coi loro muscoli servono alle corde, come i soldati a’ condottieri, e le corde servono al senso comune come i condottieri al capitano; adunque la giuntura delli ossi obbedisce al nervo, e ’l nervo al muscolo e ’l muscolo alla corda e la corda al senso comune, e ’l senso comune è sedia dell’anima, e la memoria è sua munizione e la imprensiva è sua referendaria."],"cs":["Duše, zdá se, sídlí v soudné části, a soudná část, zdá se, je na místě, kde se sbíhají všechny smysly, které se nazývá společný smysl; a není celá v celém těle, jak mnozí věřili, nýbrž celá v té části, neboť kdyby byla celá v celém a celá v každé části, nebylo by třeba, aby se nástroje smyslů sbíhaly navzájem do jednoho a téhož místa; spíše by stačilo, aby oko vykonávalo úkon vnímání na svém povrchu a neposílalo cestou zrakových nervů podobu viděných věcí smyslu, neboť duše by je podle výše řečeného důvodu mohla pochopit na tom povrchu oka. A podobně by pro smysl sluchu stačilo, aby hlas zazněl v dutých pórech skalní kosti, která je uvnitř ucha, a nečinit z té kosti ke společnému smyslu žádný jiný průchod, kde se s ním setká a má přejít ke společnému soudu.","Také smysl čichu, jak vidíme, je nutností donucen sbíhat se k řečenému soudu; hmat prochází dutými strunami a je přenášen k tomu smyslu, a ty struny se rozbíhají s nekonečným rozvětvením v kůži, která obklopuje tělesné údy a vnitřnosti.","Duté struny přinášejí rozkaz a vjem údům, které konají své úřady, a tyto struny a nervy mezi svaly a žebry jim rozkazují pohyb; ony poslouchají a taková poslušnost se uskutečňuje zduřením, neboť zduření zkracuje jejich délky a táhne za sebou nervy, které se proplétají částečkami údů, a jsouce vlity do konců prstů, přinášejí smyslu příčinu jejich doteku.","Nervy se svými svaly slouží strunám jako vojáci velitelům, a struny slouží společnému smyslu jako velitelé hejtmanovi; kloub kostí tedy poslouchá nerv, a nerv sval, a sval strunu, a struna společný smysl; a společný smysl je sídlem duše, paměť je její zbrojnicí a vnímavost její zpravodajkou."],"ref":{"s":"R","l":838,"st":"","z":false,"raw":"R. 838"},"ca":[],"rr":"W. An. II. 202 a"},{"id":"s337","o":"Pensieri sulla natura","c":"CII","str":173,"ni":"meccanismo della sensazione","nc":"Mechanismus vjemu","it":["II senso comune è quello, che giudica le cose a lui date da li altri sensi.","Il senso comune è mosso mediante le cose a lui date da li cinque sensi.","E essi sensi si movono mediante li obbietti, e questi obbietti, mandando le lor similitudini a’ cinque sensi, da quelli san transferiti alla imprensiva e da quella al comune senso; e lì, sendo judicate, sono mandate alla memoria, nella quale sono, mediante la loro potenza, più o meno riservate.","I cinque sensi sono questi: vedere, udire, toccare, gustare, odorare.","Li antichi speculatori hanno concluso, che quella parte del giudizio, che è data all’omo, sia causata da uno strumento, al quale riferiscano li altri cinque, mediante la imprensiva, e a detto strumento hanno senso essere situato in mezzo il capo. E questo nome di senso comune dicano, solamente, perchè è comune judice de li altri cinque sensi, cioè vedere, udire, toccare, gustare e odorare. Il senso comune si move mediante la imprensiva, ch’è posta in mezzo in fra lui e i sensi. La imprensiva si muove mediante la similitudine delle cose a lei date da li strumenti superfiziali, cioè i sensi, i quali sono posti in mezzo, infra le cose esteriori e la imprensiva, e similmente i sensi si movano mediante li obbietti. La similitudine delle circustanti cose mandano, le loro similitudine a’ sensi, e’ sensi le trasferiscono alla imprensiva, la imprensiva la manda al senso comune, e da quello sono stabilite nella memoria, e lì sono più o meno ritenute, secondo la importanza o potenza della cosa data.","Quello senso è più veloce nel suo offizio, il quale è più vicino alla imprensiva; il qual è l’occhio, superiore e principe de li altri, del quale solo tratteremo, e li altri lascieremo, per non ci allungare dalla nostra materia."],"cs":["Společný smysl je ten, který soudí věci, jež mu dávají ostatní smysly.","Společný smysl je uváděn v pohyb věcmi, které mu dává pět smyslů.","A tyto smysly jsou uváděny v pohyb předměty, a ty předměty, posílajíce své podoby pěti smyslům, jsou od nich přeneseny do vnímavosti a od ní do společného smyslu; a tam, když jsou posouzeny, jsou poslány do paměti, v níž jsou podle své síly více či méně uchovány.","Pět smyslů je těchto: zrak, sluch, hmat, chuť, čich.","Staří zkoumatelé dovodili, že ta část soudnosti, která je dána člověku, je způsobena jedním nástrojem, k němuž se ostatních pět vztahuje prostřednictvím vnímavosti, a o tom nástroji soudili, že je umístěn uprostřed hlavy. A jméno společný smysl mu dávají jen proto, že je společným soudcem ostatních pěti smyslů, totiž zraku, sluchu, hmatu, chuti a čichu. Společný smysl je uváděn v pohyb vnímavostí, která je umístěna uprostřed mezi ním a smysly. Vnímavost je uváděna v pohyb podobou věcí, které jí dávají povrchové nástroje, totiž smysly, které jsou umístěny uprostřed mezi vnějšími věcmi a vnímavostí, a podobně jsou smysly uváděny v pohyb předměty. Okolní věci posílají své podoby smyslům a smysly je přenášejí do vnímavosti, vnímavost je posílá společnému smyslu, a odtud jsou upevněny v paměti, a tam jsou více či méně uchovány podle důležitosti či síly dané věci.","Ten smysl je ve svém úkonu nejrychlejší, který je nejblíže vnímavosti; a to je oko, nejvyšší a kníže ostatních, o němž jediném budeme pojednávat, a ostatní ponecháme stranou, abychom se příliš nevzdalovali od své látky."],"ref":{"s":"C.A","l":90,"st":"r","z":false,"raw":"C. A. 90 r"},"ca":[486,488]},{"id":"s338","o":"Pensieri sulla natura","c":"CIII","str":175,"ni":"sui movimenti automatici","nc":"O samočinných pohybech","it":["La natura ha ordinati nell’omo i muscoli uffiziali, tiratori de’ nervi, i quali possino movere le membra, secondo la volontà e desiderio del comun senso, a similitudine delli uffiziali stribuiti da uno signore per varie province e città, i quali in essi lochi rappresentano e obbediscano alla volontà d’esso signore. E quello ufiziale, che più in un solo caso abbi obbedito alle concessione fattoli di bocca dal suo signore, farà poi per sè, nel medesimo caso, cosa, che non si partirà dalla volontà d’esso signore.","Così si vede spesse volte fare alle dita, che imparando, con somma obbedienza, la cosa sopra uno strumento, le quali li sieno comandate dal giudizio, dopo esso imparare, le sonerà sanza ch’esso giudizio v’attenda.","I muscoli, che movano le gambe, non fanno ancora l’offizio loro, sanza che l’omo lo sappi?"],"cs":["Příroda zřídila v člověku úřední svaly, které tahají za nervy a mohou pohybovat údy podle vůle a touhy společného smyslu, podobně jako úředníci rozdělení pánem po různých provinciích a městech, kteří na těch místech zastupují a poslouchají vůli toho pána. A ten úředník, který v jednom a témž případě vícekrát uposlechl příkazů, jež mu pán dal ústně, učiní potom sám od sebe v témž případě věc, která se nebude odchylovat od vůle toho pána.","Tak to často vidíme dělat prsty, které, když se s nejvyšší poslušností učí na nějakém nástroji věci, jež jim přikazuje soud, po tom naučení je zahrají, aniž by na to soud dbal.","Nekonají snad svaly, které pohybují nohama, svůj úkon, aniž by o tom člověk věděl?"],"ref":{"s":"C.A","l":119,"st":"r","z":false,"raw":"C. A. 119 r. 176"},"ca":[652,654]},{"id":"s339","o":"Pensieri sulla natura","c":"CIV","str":176,"ni":"come i nervi operano qualche volta per loro, sanza comandamento delli altri offiziali dell’anima","nc":"Nervy jednající samy","it":["Questo chiaramente apparisce, imperocchè tu vedrai movere ai paralitici e a’ freddolosi e assiderati le loro tremanti membra, come testa e mani, sanza licenza dell’anima, la quale anima, con tutte sue forze, non potrà vietare a essi membri che non tremino. Questo medesimo accade nel malcaduco e ne’ membra tagliati, come code di lucierte."],"cs":["To se zřetelně ukazuje, neboť uvidíš, jak se ochrnutým a zimomřivým a zkřehlým hýbou jejich třesoucí se údy, jako hlava a ruce, bez svolení duše, a tato duše se všemi svými silami nedokáže těm údům zabránit, aby se netřásly. Totéž se děje při padoucnici a u uťatých údů, jako jsou ocasy ještěrek."],"ref":{"s":"R","l":839,"st":"","z":false,"raw":"R. 839"},"ca":[],"rr":"W. An. II. 202 b"},{"id":"s340","o":"Pensieri sulla natura","c":"CV","str":176,"ni":"come l’uomo tende a riprodurre se stesso nelle proprie opere","nc":"Jak člověk ve svých dílech napodobuje sám sebe","it":["Sommo difetto è de’ pittori replicare li medesimi moti, i medesimi volti e maniere di panni in una medesima istoria, e fare la maggiore parte de’ volti, che somigliano al loro maestro. La qual cosa m’ha molte volte dato ammirazione, perchè n’ho conosciuto alcuno, che in tutte le sue figure parea avervisi ritratto al naturale. E in quelle si vede li atti e li modi del loro fattore.","E, s’egli è pronto nel parlare e ne’ modi, le sue figure sono il simile in prontitudine, e se ’l maestro è divoto, il simile paiano le figure con lor colli torti, e, se ’l maestro è dappoco, le sue figure paiono la pigrizia ritratta al naturale, e, se ’l maestro è sproporzionato, le figure sue son simIII, e, s’egli è pazzo, nelle sue istorie si dimostra largamente, le quali sono nemiche di conclusione e non stanno attente alla loro operazione, anzi chi guarda in qua e chi in là, come se sognassino; e così, segue ciascun accidente in pittura il proprio accidente del pittore.","E avendo io più volte considerato la causa di tal difetto, mi pare, che sia da giudicare, che quella anima, che regge e governa ciascun corpo, si è quella che fa il nostro giudizio innanzi sia il proprio giudizio nostro. Adunque ella ha condotto tutta la figura dell’omo, com’ella ha giudicato quello stare bene, o col naso lungo o corto o camuso, e così li ha fermo la sua altezza e figura, ed è di tanta potenza questo tal giudizio ch’egli move le braccia al pittore, e fagli replicare se medesimo, parendo a essa anima, che quello sia il vero modo di figurare l’omo, e, chi non fa come lui, faccia errore. E, s’ella trova alcuno, che simigli al suo corpo, ch’ell’ha composto, ella l’ama e s’innamora di quello, e per questo molti s’innamorano e toglian moglie, che simiglia a lui, e spesso li figlioli, che nascano di tali, simigliano ai loro genitori."],"cs":["Největší vadou malířů je opakovat tytéž pohyby, tytéž tváře a způsoby řas v jednom a témž výjevu a dělat většinu tváří tak, že se podobají jejich mistrovi. Tomu jsem se mnohokrát podivoval, neboť jsem poznal kohosi, kdo se zdál ve všech svých postavách vypodobnit sám sebe podle života. A v nich je vidět posunky a způsoby jejich tvůrce.","A je-li on hbitý v řeči a v chování, jsou jeho postavy podobně hbité; a je-li mistr pobožný, takové se zdají i postavy s nakloněnými šíjemi; a je-li mistr nedbalý, zdají se jeho postavy lenost vypodobněná podle života; a je-li mistr nesouměrný, jsou jeho postavy takové též; a je-li pošetilý, ukazuje se to hojně v jeho výjevech, které jsou nepřáteli souvislosti a nevěnují se svému dění, nýbrž jeden hledí sem a druhý tam, jako by snili; a tak každá vlastnost v malbě následuje vlastnost malíře.","A když jsem vícekrát uvažoval o příčině této vady, zdá se mi, že je třeba soudit, že duše, která řídí a spravuje každé tělo, je ta, jež tvoří náš úsudek dříve, než je to náš vlastní úsudek. Ona tedy vytvořila celou postavu člověka tak, jak usoudila, že je to dobře, ať s nosem dlouhým, či krátkým, či tupým, a tak mu ustálila jeho výšku i podobu; a tento její úsudek má takovou moc, že hýbe malíři pažemi a dává mu opakovat sebe sama, neboť se té duši zdá, že to je pravý způsob, jak zobrazit člověka, a kdo nedělá jako ona, že chybuje. A najde-li někoho, kdo se podobá tělu, jež ona složila, miluje ho a zamiluje se do něho; a proto se mnozí zamilují a berou si ženy, které se jim podobají, a děti, jež se z takových rodí, se často podobají svým rodičům."],"ref":{"s":"Lu","l":108,"st":"","z":false,"raw":"Lu. 108"},"ca":[]},{"id":"s341","o":"Pensieri sulla natura","c":"CVI","str":178,"ni":"un istinto naturale dell’uomo lo guida a cercare se stesso nelle cose e negli esseri","nc":"Člověk hledá sám sebe ve věcech","it":["Deve il pittore fare la sua figura sopra la regola d’un corpo naturale, il quale comunemente sia di proporzione laudabile; oltre di questo far misurare se medesimo e vedere, in che parte la sua persona varia assai o poco da quella antidetta laudabile, e, fatta questa notizia, deve riparare con tutto il suo studio, di non incorrere ne’ medesimi mancamenti, nelle figure da lui operate, che nella persona sua si trova.","E sappi, che con questo vizio ti bisogna sommamente pugnare, conciò sia ch’egli è mancamento, ch’è nato insieme col giudizio: perchè l’anima maestra del tuo corpo è quella, ch’è il tuo proprio giudizio, e volentieri si diletta nelle opere simili a quella, ch’ella operò nel comporre del suo corpo. E di qui nasce, che non è sì brutta figura di femmina, che non trovi qualche amante — se già non fussi mostruosa.","Sì che ricordati intendere i mancamenti, che sono nella tua persona, e da quelli ti guarda nelle figure, che da te si compongono."],"cs":["Malíř má dělat svou postavu podle pravidla přirozeného těla, které by mělo obecně chvályhodnou souměrnost; kromě toho má dát změřit sám sebe a zjistit, v které části se jeho osoba více či méně liší od oné řečené chvályhodné; a když toto pozná, má se vší pílí bránit, aby v postavách, které tvoří, neupadal do týchž nedostatků, jaké se nacházejí na jeho osobě.","A věz, že s touto vadou musíš co nejvíce bojovat, protože je to nedostatek, který se zrodil spolu s úsudkem: neboť duše, paní tvého těla, je tvým vlastním úsudkem a ráda se kochá v dílech podobných tomu, jež vytvořila, když skládala své tělo. A odtud pochází, že není tak ošklivé ženské postavy, aby nenašla nějakého milovníka – leda by byla zrůdná.","Pamatuj tedy, abys poznal nedostatky, které jsou na tvé osobě, a vyvaruj se jich v postavách, jež skládáš."],"ref":{"s":"Lu","l":109,"st":"","z":false,"raw":"Lu. 109"},"ca":[]},{"id":"s342","o":"Pensieri sulla natura","c":"CVII","str":179,"ni":"consiglio al pittore","nc":"Rada malíři","it":["Quel pittore, che arà goffe mani, le farà simili nelle sua opere, e quel medesimo li ’nterverrà in qualunque membro, se ’l lungo studio non glielo vieta. Adunque tu, pittore, guarda bene quella parte, che hai più brutta nella tua persona, e ’n quella col tuo studio fa bono riparo, imperò che, se sarai bestiale, le tue figure saranno il simile e sanza ingegnio, e similmente ogni parte di bono e di tristo, che hai in te, si dimostrerà in parte nelle tue figure."],"cs":["Malíř, který bude mít neohrabané ruce, udělá je podobné ve svých dílech, a totéž se mu přihodí s kterýmkoli údem, nezabrání-li mu v tom dlouhé studium. Ty tedy, malíři, dobře pozoruj tu část, kterou máš na své osobě nejošklivější, a v té svým studiem učiň dobrou nápravu; neboť budeš-li hovadný, budou tvé postavy takové též a bez důvtipu, a podobně se každá dobrá i špatná stránka, kterou v sobě máš, zčásti ukáže ve tvých postavách."],"ref":{"s":"A","l":23,"st":"r","z":false,"raw":"A. 23 r"},"ca":[]},{"id":"s343","o":"Pensieri sulla natura","c":"CVIII","str":179,"ni":"sugli stessi soggetti","nc":"K témuž","it":["Questo accade, che il giudicio nostro è quello, che move la mano alla creazione de’ lineamenti d’esse figure, per diversi aspetti, insino a tanto ch’esso si satisfaccia; e perchè esso giudicio è una delle potenze dell’anima nostra, con quella essa compose la forma del corpo, dov’essa abita, secondo il suo volere. Onde avendo co’ le mani a rifare un corpo umano volontieri rifà quel corpo, di ch’essa fu prima inventrice, e di qui nasce che, chi s’innamora, volentieri s’innamorano di cose a loro simiglianti."],"cs":["Děje se to proto, že náš úsudek je to, co hýbe rukou při vytváření obrysů těch postav v rozličných podobách, dokud není uspokojen; a protože tento úsudek je jednou z mohutností naší duše, složila jím ona tvar těla, v němž přebývá, podle své vůle. Má-li tedy rukama znovu vytvořit lidské tělo, ráda znovu vytváří to tělo, jehož byla původně vynálezkyní; a odtud pochází, že ten, kdo se zamilovává, rád se zamilovává do věcí sobě podobných."],"ref":{"s":"Lu","l":499,"st":"","z":false,"raw":"Lu. 499"},"ca":[]},{"id":"s344","o":"Pensieri sulla natura","c":"CIX","str":180,"ni":"sulla natura dei sensi","nc":"O povaze smyslů","it":["Quattro sono le potenze: memoria e intelletto, lascibili e concupiscibili.","Le due prime son ragionevoli e l’altre sensuali.","De’ cinque sensi: vedere, udire, odorato sono di poca proibizione, tatto e gusto no.","L’odorato mena con seco il gusto nel cane e altri golosi animali."],"cs":["Čtyři jsou mohutnosti: paměť a rozum, vznětlivé a žádostivé.","První dvě jsou rozumové a ostatní smyslové.","Z pěti smyslů: zrak, sluch a čich lze jen málo zakázat, hmat a chuť nikoli.","Čich vede s sebou chuť u psa a jiných mlsných zvířat."],"ref":{"s":"T","l":7,"st":"v","z":false,"raw":"T. 7 v"},"ca":[]},{"id":"s345","o":"Pensieri sulla natura","c":"CX","str":180,"ni":"problema dei sogni","nc":"Záhada snů","it":["Perchè vede più certa la cosa l’occhio ne’ sogni, che colla imaginazione stando desto?"],"cs":["Proč oko vidí věc ve snech jistěji než obrazotvorností za bdění?"],"ref":{"s":"R","l":1114,"st":"","z":false,"raw":"R. 1114"},"ca":[],"rr":"Leic. 22 b"},{"id":"s346","o":"Pensieri sulla natura","c":"CXI","str":180,"ni":"giudizi incoscienti","nc":"Nevědomé soudy","it":["La pupilla dell’occhio, stante all’aria, in ogni grado di moti fatti dal sole, muta gradi di magnitudine.","E, in ogni grado di magnitudine, una medesima cosa veduta si dimostrerà di diverse grandezze, benchè spesse volte il paragone delle cose circostanti non lascino discernere tale mutazione d’una sola cosa, che si risguardi."],"cs":["Zornice oka, vystavená vzduchu, mění při každém stupni pohybu slunce stupně své velikosti.","A při každém stupni velikosti se jedna a táž viděná věc ukáže v rozličných velikostech, ačkoli srovnání s okolními věcmi často nedovolí rozeznat takovou změnu jediné věci, na niž se hledí."],"ref":null,"ca":[]},{"id":"s347","o":"Pensieri sulla natura","c":"CXII","str":181,"ni":"- inganno dei sensi","nc":"Klam smyslů","it":["L’occhio, nelle debite distanze e debiti mezzi, meno s’inganna nel suo uffizio, che nissun altro senso, perchè (non) vede se non per linee rette, che compongono la piramide, che si fa base dell’obbietto, e la conduce a esso occhio, come intendo provare.","Ma l’orecchio forte s’inganna nelli siti e distanze delli suoi obbietti, perchè non vengono le spezie a lui per rette linee, come quelle dell’occhio, ma per linee tortuose e riflesse, e molte sono le volte che le remote paiano più vicine, che le propinque, mediante li transiti di tali spezie; benchè la voce di eco sol per linee rette si riferisce a esso senso.","L’odorato meno si certifica del sito, donde si causa un’odore; ma il gusto e il tatto, che toccano l’obbietto, han sola notizia di esso tatto."],"cs":["Oko se při náležitých vzdálenostech a náležitých prostředích ve svém úřadu klame méně než kterýkoli jiný smysl, protože vidí jen přímými liniemi, které skládají jehlan, jehož základnou je předmět a který jej vede k oku, jak hodlám dokázat.","Ale ucho se silně klame v polohách a vzdálenostech svých předmětů, protože obrazy k němu nepřicházejí přímými liniemi jako k oku, nýbrž liniemi křivolakými a odraženými, a mnohokrát se stává, že vzdálené se zdají bližší než blízké, kvůli cestám těchto obrazů; ačkoli hlas ozvěny se k tomuto smyslu donáší jen přímými liniemi.","Čich se ještě méně ujistí o místě, odkud vůně pochází; ale chuť a hmat, které se předmětu dotýkají, mají vědomí jen o tomto dotyku."],"ref":{"s":"Lu","l":2,"st":"","z":false,"raw":"Lu. 2"},"ca":[]},{"id":"s348","o":"Pensieri sulla natura","c":"CXIII","str":182,"ni":"sul tempo","nc":"O čase","it":["Benchè il tempo sia annumerato in fra le continue quantità, esso, per essere invisibile e sanza corpo, non cade integralmente sotto la geometrica potenza, la quale lo divide per figure e corpi d’infinita varietà, come continuo nelle cose visibili e corporee far si vede; ma sol co’ sua primi principi si conviene, cioè col punto e colla linia: il punto nel tempo è da essere equiparato al suo istante, e la linea, ha similitudine colla lunghezza d’una quantità d’un tempo, e, siccome i punti son principio e fine della predetta linea, così li instanti son termine e principio di qualunque dato spazio di tempo, e se la linea è divisibile in infinito, lo spazio d’un tempo di tal divisione non è alieno, e se le parti divise della linea sono proporzionabili infra se, ancora le parti del tempo saranno proporzionabili infra loro."],"cs":["Ačkoli je čas počítán mezi spojité veličiny, přesto, protože je neviditelný a bez těla, nespadá celý pod moc geometrie, která jej dělí na útvary a tělesa nekonečné rozmanitosti, jak to vidíme u spojitého ve věcech viditelných a tělesných; ale shoduje se s ní jen svými prvními počátky, totiž s bodem a s čárou: bod v čase je třeba přirovnat k jeho okamžiku a čára má podobnost s délkou určitého množství času; a jako body jsou počátkem a koncem řečené čáry, tak okamžiky jsou koncem a počátkem kteréhokoli daného úseku času; a je-li čára dělitelná do nekonečna, ani úsek času není takovému dělení cizí; a jsou-li rozdělené části čáry mezi sebou úměrné, budou i části času mezi sebou úměrné."],"ref":{"s":"R","l":916,"st":"","z":false,"raw":"R. 916"},"ca":[],"rr":"Br. M. 173 b"},{"id":"s349","o":"Pensieri sulla natura","c":"CXIV","str":182,"ni":"sul concetto del tempo","nc":"O pojmu času","it":["Scrivi la qualità del tempo separata dalla geometrica."],"cs":["Popiš povahu času odděleně od geometrické."],"ref":{"s":"R","l":917,"st":"","z":false,"raw":"R. 917"},"ca":[],"rr":"Br. M. 176 a"},{"id":"s350","o":"Pensieri sulla natura","c":"CXV","str":183,"ni":"sul concetto del nulla","nc":"O pojmu ničeho","it":["Il minore punto naturale è maggiore di tutti i punti matematici, e questo si pruova perchè il punto naturale è quantità continua, e ogni continuo è divisibile in infinito, e il punto matematico è indivisibile, perchè non è quantità.","Ogni quantità continua intellettualmente è divisibile in infinito.","Infra le grandezze delle cose, che sono infra noi, l’essere del Nulla tiene il principato, e ’l suo offizio s’estende infra le cose, che non hanno l’essere, e la sua essenza risiede appresso del tempo, infra ’l preterito e ’l futuro — e nulla possiede del presente.","Questo Nulla ha la sua parte eguale al tutto e ’l tutto alla parte e ’l divisibile allo indivisibile, e tal somma produce nella sua partizione come nella multiplicazione e nel suo sommare quanto nel sottrarre, come si dimostra appresso delli aritmetici dello suo decimo carattere, che rappresenta esso Nulla. E la podestà sua non si estende infra le cose di natura. [Quello che è detto Niente si ritrova solo nel tempo e nelle parole: nel tempo si trova infra ’l preterito e ’l futuro, e nulla ritiene del presente, e così, infra le parole, delle cose che si dicono, che non sono o che sono impossibili.]","Appresso dei tempo il Nulla risiede infra ’l preterito e ’l futuro, e niente possiede del presente, e apresso di natura e’ s’accompagna infra le cose impossibili. Onde per quel ch’è detto e’ non ha l’essere, imperò che, dove fusse il nulla, sarebbe dato il vacuo."],"cs":["Nejmenší přirozený bod je větší než všechny body matematické, a to se dokazuje tím, že přirozený bod je spojitá veličina a každé spojité je dělitelné do nekonečna, kdežto matematický bod je nedělitelný, protože není veličinou.","Každá spojitá veličina je v myšlení dělitelná do nekonečna.","Mezi velikostmi věcí, které jsou mezi námi, má bytí Ničeho prvenství, a jeho úřad se vztahuje na věci, které nemají bytí, a jeho podstata přebývá u času, mezi minulým a budoucím – a z přítomného nemá nic.","Toto Nic má svou část rovnou celku a celek části a dělitelné nedělitelnému, a dává týž součet při dělení jako při násobení a při sčítání jako při odčítání, jak ukazují počtáři svou desátou číslicí, která toto Nic představuje. A jeho moc se nevztahuje na věci přírody. [To, čemu se říká Nic, se nachází jen v čase a ve slovech: v čase se nachází mezi minulým a budoucím a nic si nezachovává z přítomného; a tak mezi slovy u věcí, o nichž se říká, že nejsou nebo že jsou nemožné.]","U času přebývá Nic mezi minulým a budoucím a z přítomného nemá nic, a u přírody se druží k věcem nemožným. Proto podle toho, co bylo řečeno, nemá bytí; neboť kde by bylo nic, byla by dána prázdnota."],"ref":{"s":"R","l":918,"st":"","z":false,"raw":"R. 918"},"ca":[],"rr":"Br. M. 191 a"},{"id":"s351","o":"Pensieri sulla morale","c":"I","str":185,"ni":"gli studi di leonardo","nc":"Leonardova studia","it":["Io scopro alli omini l’origine della prima o forse seconda cagione del loro essere."],"cs":["Odhaluji lidem původ první, nebo snad druhé příčiny jejich bytí."],"ref":{"s":"R","l":841,"st":"","z":false,"raw":"R. 841"},"ca":[],"rr":"W. An. IV. 151 b"},{"id":"s352","o":"Pensieri sulla morale","c":"II","str":185,"ni":"proemio della sua anatomia","nc":"Předmluva k jeho anatomii","it":["E tu, che dici esser meglio il vedere fare l’anatomia, che vedere tali disegni, diresti bene, se fusse possibile vedere tutte queste cose, che in tali disegni si dimostrano, in una sola figura; nella quale, con tutto il tuo ingegno, non vedrai e non avrai la notizia, se non d’alquante poche vene; delle quali io, per averne vera e piena notizia, ho disfatti piu di dieci corpi umani, distruggendo ogni altri membri, consumando con minutissime particule tutta la carne, che d’intorno a esse vene si trovava, sanza insanguinarle, se non d’insensibile insanguinamento delle vene capillari. E un sol corpo non bastava a tanto tempo, che bisognava procedere di mano in mano in tanti corpi, che si finisca la intera cognizione; la qual replicai due volte per vedere le differenze.","E se tu avrai l’amore a tal cosa, tu sarai forse impedito dallo stomaco; e se questo non ti impedisce, tu sarai forse impedito dalla paura coll’abitare nelli tempi notturni in compagnia di tali morti squadrati e scorticati, e spaventevoli a vederli; e se questo non t’impedisce, forse ti mancherà il disegno bono, il quale s’appartiene a tal figurazione.","E se tu avrai il disegno, e’ non sarà accompagnato dalla prospettiva; e se sarà accompagnato, e’ ti mancherà l’ordine delle dimostrazion geometriche e l’ordine delle calculazion delle forze e valimento de’ muscoli; e forse ti mancherà la pazienza, chè tu non sarai diligente.","Delle quali, se in me tutte queste cose sono state o no, i centoventi libri da me composti no daran sentenza del sì o del no, nelli quali non sono stato impedito nè d’avarizia o negligenza, ma sol dal tempo. Vale."],"cs":["A ty, který říkáš, že je lepší vidět provádět pitvu než vidět takové kresby, měl bys pravdu, kdyby bylo možné vidět všechny ty věci, které se v těchto kresbách ukazují, na jediné postavě; na ní však se vším svým důvtipem neuvidíš a nepoznáš nic než několik málo žil; abych o nich nabyl pravého a plného poznání, rozebral jsem přes deset lidských těl, ničil všechny ostatní údy a odstraňoval po nejdrobnějších částečkách všechno maso, které se kolem těch žil nacházelo, aniž bych je zakrvácel, leda nepostřehnutelným krvácením vlásečnic. A jedno jediné tělo nestačilo na tak dlouhou dobu, takže bylo třeba postupovat od jednoho k druhému v tolika tělech, až se dosáhne úplného poznání; a to jsem dvakrát opakoval, abych viděl rozdíly.","A budeš-li mít k té věci lásku, snad ti bude překážet žaludek; a nebude-li ti překážet ten, snad ti bude překážet strach z pobývání v nočních hodinách ve společnosti takových mrtvých, rozčtvrcených a stažených z kůže, na něž je hrůza pohledět; a nebude-li ti překážet ani to, snad ti bude chybět dobrá kresba, jaká k takovému zobrazování přísluší.","A budeš-li mít kresbu, nebude ji provázet perspektiva; a bude-li ji provázet, bude ti chybět řád geometrických důkazů a řád výpočtu sil a síly svalů; a snad ti bude chybět trpělivost, takže nebudeš pečlivý.","Zda všechny tyto věci ve mně byly, či nikoli, o tom vynese rozsudek, ano či ne, sto dvacet knih, které jsem složil a v nichž mi nepřekážela ani lakota, ani nedbalost, nýbrž jen čas. Vale."],"ref":{"s":"R","l":796,"st":"","z":false,"raw":"R. 796"},"ca":[],"rr":"W. An. IV. 167 a"},{"id":"s353","o":"Pensieri sulla morale","c":"III","str":187,"ni":"passaggio dalla anatomia all’etica","nc":"Přechod od anatomie k etice","it":["Adunque qui, con 12 figure intere, ti sarà mostro la Cosmografia del minor mondo col medesimo ordine, che innanzi a me fu fatto da Tolomeo nella sua Cosmografia . E così dividerò poi quello in membra, come lui divise il tutto in provincie; e poi dirò l’uffizio delle parti per ciascun verso, mettendoti dinanzi alli occhi la notizia di tutta la figura e valitudine dell’omo, in quanto a moto locale, mediante le sue parti.","E così piacesse al Nostro Autore, che io potessi dimostrare la natura delli omini e loro costumi, nel modo che io descrivo la sua figura."],"cs":["Zde ti tedy bude dvanácti celými postavami ukázána Kosmografie menšího světa v témž pořádku, jaký přede mnou učinil Ptolemaios ve své Kosmografii. A tak ji potom rozdělím na údy, jako on rozdělil celek na provincie; a potom povím o úřadu částí ze všech stran a postavím ti před oči poznání celé postavy a schopnosti člověka, pokud jde o pohyb z místa na místo, prostřednictvím jeho částí.","A kéž by se tak zalíbilo Našemu Tvůrci, abych mohl ukázat povahu lidí a jejich mravy tak, jak popisuji jejich postavu."],"ref":{"s":"R","l":793,"st":"","z":false,"raw":"R. 793"},"ca":[],"rr":"S. K. M. II.1 72 a"},{"id":"s354","o":"Pensieri sulla morale","c":"IV","str":187,"ni":"conseguenze etiche che discendono dagli studi anatomici","nc":"Etické důsledky anatomických studií","it":["E tu, o omo, che consideri in questa mia fatica l’opere mirabili della natura, se giudicherai essere cosa nefanda il distruggerla, or pensa essere cosa nefandissima il tôrre la vita all’omo; del quale, se questa sua composizione ti pare di maraviglioso artifizio, pensa questa essere nulla rispetto all’anima, che in tale architettura abita, e veramente, quale essa si sia, ella è cosa divina: sicchè lasciala abitare nella sua opera a suo beneplacito, o non volere che la tua ira o malignità distrugga una tanta vita, che veramente, chi non la stima, non la merita.","Poichè così mal volentieri si parte dal corpo, e ben credo, che ’l suo pianto e dolore non sia sanza cagione."],"cs":["A ty, člověče, který v této mé práci pozoruješ obdivuhodná díla přírody, budeš-li soudit, že je to věc ohavná ji ničit, pomysli, že je věc nejohavnější brát člověku život; zdá-li se ti tato jeho stavba obdivuhodným umem, pomysli, že je to nic proti duši, která v takové architektuře přebývá; a opravdu, ať je jakákoli, je to věc božská: nech ji tedy přebývat v jejím díle podle její libosti a nechtěj, aby tvůj hněv nebo zloba zničily tak veliký život, neboť vpravdě, kdo si ho neváží, ten si ho nezaslouží.","Vždyť tak nerada opouští tělo, a věřím dobře, že její pláč a bolest nejsou bez příčiny."],"ref":{"s":"An.A","l":2,"st":"r","z":false,"raw":"An. A. 2 r"},"ca":[]},{"id":"s355","o":"Pensieri sulla morale","c":"V","str":188,"ni":"il metodo sperimentale e sue conseguenze sull'agire umano","nc":"Experimentální metoda a její důsledky pro lidské jednání","it":["Queste regole son cagione di farti conoscere il vero dal falso, la qual cosa fa che li omini si promettano le cose possibili e con più moderanza, e che tu non ti veli d’ignoranza, che farebbe, che, non avendo effetto, tu t’abbi con disperazione a darti malinconia."],"cs":["Tato pravidla způsobují, že poznáváš pravdivé od nepravdivého, což vede k tomu, že si lidé slibují věci možné a s větší mírou, a že se nezahaluješ nevědomostí, která by způsobila, že by ses, když se nic nepovede, musel v zoufalství oddávat trudnomyslnosti."],"ref":{"s":"C.A","l":119,"st":"r","z":false,"raw":"C. A. 119 r"},"ca":[652,654]},{"id":"s356","o":"Pensieri sulla morale","c":"VI","str":188,"ni":"limiti imposti da leonardo alla scienza","nc":"Meze, které Leonardo klade vědě","it":["Come molti stiano con istrumento alquanto sotto l'acqua; come e perchè io non scrivo il mio modo di star sotto l’acqua, quanto io posso star sanza mangiare; e questo non pubblico o divolgo per le male nature delli omini, li quali userebbono li assassinamenti ne’ fondi de’ mari, col rompere i navili in fondo, e sommergerli, insieme colli omini, che vi son dentro, e benchè io insegni delli altri, quelli non son di pericolo, perchè di sopra all’acqua apparisce la bocca della canna, onde alitano, posta sopra otri o sughero."],"cs":["Jak mnozí vydrží s nástrojem nějakou dobu pod vodou; jak a proč nepopisuji svůj způsob, jak zůstat pod vodou tak dlouho, jak dlouho vydržím bez jídla; a to nezveřejňuji ani nerozšiřuji kvůli zlé povaze lidí, kteří by páchali vraždy na mořském dně tím, že by prorážely lodi u dna a potápěli je i s lidmi, kteří jsou v nich; a ačkoli učím jiné způsoby, ty nejsou nebezpečné, protože nad vodou se objevuje ústí trubice, kterou se dýchá, umístěné na měchu nebo korku."],"ref":{"s":"R","l":1,"st":"","z":false,"raw":"R. 1"},"ca":[],"rr":"Leic. 22 b"},{"id":"s357","o":"Pensieri sulla morale","c":"VII","str":189,"ni":"contro la necromanzia","nc":"Proti nekromancii","it":["Delli discorsi umani stoltissimo è da essere riputato quello, il qual s’astende alla credulità della Negromanzia, sorella della Alchimia, partoritrice delle cose semplici e naturali; ma è tanto più degna di riprensione che l’Alchimia, quanto ella non partorisce alcuna cosa se non simile a sè, cioè bugia.","Il che non interviene nella Alchimia, la quale è ministratrice de’ semplici prodotti della natura; il quale uffizio fatto esser non può da essa natura, perchè in lei non sono strumenti organici, colli quali essa possa operare quel che adopera l’uomo mediante le mani, che in tale uffizio ha fatti i vetri ecc.","Ma essa Negromanzia, stendardo o vero bandiera volante mossa dal vento, è guidatrice della stolta moltitudine, la quale al continuo testimonia, collo abbaiamento, l’infiniti effetti di tale arte; e vanno empiuti i libri, affermando che l’incanti e spiriti adoperino, e sanza lingua parlino, e sanza strumenti organici, sanza i quali parlar non si può, parlino, e portino gravissimi pesi, faccino tempestare e piovere, e che li omini si convertino in gatti, lupi e altre bestie, benchè in bestia prima entran quelli, che tal cosa affermano.","E certo se tale Negromanzia fusse in essere, come dalli bassi ingegni è creduto, nessuna cosa è sopra la terra, che al danno e servizio dell’omo fusse di tanta valetudine: perchè, se fusse vero che in tale arte si avesse potenza di far turbare la tranquilla serenità dell’aria, convertendo quella in notturno aspetto, e far le corruscazioni o venti, con spaventevoli toni e folgori scorrenti infrale teneb re, e con impetuosi venti ruinare li alti edilizi, e diradicare le selve, e con quelle percuotere li eserciti, e quelli rompendo e atterrando, e oltr’a questo le dannose tempeste privando li cultori del premio delle lor fatiche: — o qual modo di guerra può essere, che con tanto danno possa offendere il suo nemico di aver podestà di privarlo delle sue raccolte? qual battaglia marittima può essere, che si assomigli a quella di colui, che comanda alli venti, e fa le fortune rovinose e sommergitnci di qualunque armata? Certo quel che comanda a tali impetuose potenze sarà signore delli popoli, e nessuno umano ingegno potrà resistere alle sue dannose forze. Li occulti tesori e gemme riposti nel corpo della terra fieno a costui tutti manifesti. Questo si farà portare per l’aria dall’oriente all’occidente e per tutti li oppositi aspetti dell’universo....","Ma perchè mi voglio più oltre estendere? qual e quella cosa, che per tale artifizio far non si possa? — quasi nessuna, eccetto il levarsi la morte. — E s’ell’è vera, perchè non è restata infra li omini, che tanto la desiderano, non avendo riguardo a nessuna deità?","E so che infiniti ce n’è, che, per soddisfare a un suo appetito, ruinerebbero Iddio con tutto l’universo.","E, s’ella non è rimasta infra li omini, essendo a lui tanto necessaria, essa non fa mai, nè mai è per dovere essere: per la deffinizion dello spirito, il quale è invisibile in corpo; e dentro alli elementi non sono cose incorporee, perchè dove non è corpo è vacuo, e ’l vacuo non si dà dentro alli elementi, perchè subito sarebbe dall’elemento riempiuto."],"cs":["Z lidských úvah je třeba pokládat za nejpošetilejší tu, která se dává do víry v Nekromancii, sestru Alchymie, rodičky věcí prostých a přirozených; ale je tím víc hodna pokárání než Alchymie, že nerodí nic jiného než sobě podobné, totiž lež.","To se nestává u Alchymie, která je služebnicí prostých plodů přírody; tento úřad nemůže vykonávat sama příroda, protože v ní nejsou ústrojné nástroje, jimiž by mohla dělat to, co dělá člověk pomocí rukou, který v tomto úřadu vyrobil skla atd.","Ale tato Nekromancie, korouhev neboli prapor vlající ve větru, je vůdkyní pošetilého davu, který neustále svým štěkotem dosvědčuje nesčetné účinky tohoto umění; a plní se jimi knihy, tvrdící, že kouzla a duchové působí, a bez jazyka mluví, a bez ústrojných nástrojů, bez nichž mluvit nelze, mluví, a nosí převeliká břemena, působí bouře a déšť, a že se lidé proměňují v kočky, vlky a jiná zvířata; ačkoli do zvířete vstupují nejprve ti, kdo takovou věc tvrdí.","A jistě, kdyby taková Nekromancie existovala, jak věří lidé nízkého ducha, nebylo by na zemi ničeho, co by ke škodě i ke službě člověka mělo takovou moc: neboť kdyby bylo pravda, že se v takovém umění má moc rozvířit klidnou jasnost vzduchu a proměnit ji v noční podobu, působit blesky či větry s hrozivými hromy a bleskem probíhajícím tmou, a prudkými větry bořit vysoké budovy a vyvracet lesy a jimi bít vojska, rozbíjet je a srážet k zemi, a kromě toho škodlivými bouřemi připravovat rolníky o odměnu jejich práce: – ó jaký způsob války může být, který by tak velkou škodou mohl zasáhnout nepřítele, než mít moc připravit ho o jeho úrodu? Jaká námořní bitva se může vyrovnat bitvě toho, kdo poroučí větrům a působí zhoubné bouře, jež potápějí kterékoli loďstvo? Jistě ten, kdo poroučí takovým prudkým mocnostem, bude pánem národů a žádný lidský důvtip nebude moci odolat jeho zhoubným silám. Skryté poklady a drahokamy uložené v těle země mu budou všechny zjevné. Ten se dá nosit vzduchem od východu na západ a do všech protilehlých končin vesmíru…","Ale proč bych se chtěl rozšiřovat dále? Co je to, co by se takovým umem nedalo učinit? – Téměř nic, kromě odvrácení smrti. – A je-li pravdivá, proč nezůstala mezi lidmi, kteří po ní tolik touží, aniž by brali ohled na jakékoli božstvo?","A vím, že je nesčetně těch, kteří by, aby ukojili svou chtivost, zničili Boha i s celým vesmírem.","A jestliže nezůstala mezi lidmi, ač je jim tolik potřebná, nikdy nebyla a nikdy nebude: podle definice ducha, který je neviditelný v těle; a uvnitř živlů nejsou věci netělesné, protože kde není tělo, je prázdnota, a prázdnota uvnitř živlů dána není, protože by ji živel ihned vyplnil."],"ref":{"s":"R","l":1213,"st":"","z":false,"raw":"R. 1213"},"ca":[],"rr":"W. An. II. 242 b"},{"id":"s358","o":"Pensieri sulla morale","c":"VIII","str":192,"ni":"delli spiriti","nc":"O duších","it":["Abbiamo insin qui dirieto a questa faccia detto, come la diffinizion dello spirinto è: — una potenza congiunta al corpo, perchè per sè medesimo reggere non si può, nè pigliare alcuna sorte di moto locale. — E se tu dirai che per sè si regga; questo essere non può, dentro alli elementi, perchè, se lo spinto e quantità incorporea, questa tal quantità è detta vacuo, e il vacuo non si dà in natura, e, dato che si desse, subito sarebbe riempiuto dalla ruina di quell’elemento, nel qual il vacuo si generasse.","Adunque, per la definizione del peso, che dice: — la gravità è una potenza accidentale, creata d’alcuno elemento tirato o sospinto nell’altro; - sèguita, che nessuno elemento non pesando nel medesimo elemento, e’ pesa nell’elemento superiore, ch’è più lieve di lui, come si vede: la parte dell’acqua non ha gravità o levità più che l’altra acqua, ma se tu la tirerai nell’aria, allora ella acquisterà gravezza, la qual gravezza per sè sostener non si può; onde li è necessario la ruina, e così cade infra l’acqua in quel loco, ch’è vacuo d’essa acqua. Tale accaderebbe nello spirito, stando infra li elementi, che al continuo genererebbe vacuo in quel tale elemento, dove lui si trovasse, per la qual cosa li sarebbe necessario la continua fuga inverso il celo, insinchè uscito fusse di tali elementi."],"cs":["Řekli jsme dosud na rubu tohoto listu, že definice ducha je: – mohutnost spojená s tělem, protože sama o sobě se udržet nemůže ani nabýt jakéhokoli druhu pohybu z místa na místo. – A řekneš-li, že se udrží sama o sobě, to uvnitř živlů být nemůže, protože je-li duch netělesná veličina, říká se takové veličině prázdnota, a prázdnota v přírodě dána není, a i kdyby byla dána, hned by ji vyplnilo zhroucení toho živlu, v němž by se prázdnota zrodila.","Tedy podle definice tíže, která praví: – tíže je nahodilá mohutnost, vzniklá tím, že je nějaký živel vtažen nebo vtlačen do jiného; – z toho plyne, že žádný živel neváží v témž živlu, ale váží v živlu vyšším, který je lehčí než on, jak je vidět: část vody nemá tíži ani lehkost víc než ostatní voda, ale vytáhneš-li ji do vzduchu, nabude tíže, a tato tíže se sama o sobě nemůže udržet; proto je jí nezbytné padnout, a tak padá do vody na to místo, které je té vody prázdné. Totéž by se stalo duchu, kdyby byl mezi živly: neustále by v tom živlu, v němž by se nacházel, plodil prázdnotu, a proto by musel ustavičně prchat k nebi, dokud by z těch živlů nevyšel."],"ref":null,"ca":[]},{"id":"s359","o":"Pensieri sulla morale","c":"IX","str":193,"ni":"se lo spirito tiene corpo infra li elementi","nc":"Zda duch nabývá těla mezi živly","it":["Abbiam provato, come lo spirito non può per sè stare infra li elementi, sanza corpo, nè per sè si può movere, per moto volontario, se non è allo in su. Ma al presente diremo, come, pigliando corpo d’aria tale spirito, è necessario che s’infonda infra essa aria, perchè s’elli stesse unito, e’ sarebbe separato, e caderebbe alla generazion del vacuo, come di sopra è detto. Adunque è necessario che, a volere restare infra l’aria, che esso s’infonda in una quantità d’aria, e, se si mista coll’aria, elli seguita due inconvenienti, cioè, che elli levifica quella quantità dell’aria, dove esso si mista, per la qual cosa l’aria levificaia per sè vola in alto, e non resta infra l’aria più grossa di lei; e oltre a questo tal virtù spirituale sparsa si disunisce, e altera sua natura, per la qual cosa esso manca della prima virtù.","Aggiugnesi un terzo inconveniente, e questo è, che tal corpo d’aria, preso dallo spirito, è sottoposto alla penetrazion dei venti, li quali al continuo disuniscono e stracciano le parti unite dell’aria, quelle rivolgendo e raggirando intra l’altra aria. Adunque lo spirito in tale aria infuso, sarebbe smembrato, o vero sbranato e rotto, insieme collo sbranamento dell’aria, nella qual s’infuse."],"cs":["Dokázali jsme, že duch nemůže sám o sobě bez těla setrvávat mezi živly, ani se sám o sobě pohybovat volním pohybem, leda vzhůru. Nyní však povíme, že vezme-li takový duch tělo ze vzduchu, musí se v tom vzduchu rozlít; neboť kdyby zůstal soudržný, byl by oddělen a propadl by plození prázdnoty, jak je řečeno výše. Chce-li tedy zůstat ve vzduchu, musí se rozlít v určitém množství vzduchu; a smísí-li se se vzduchem, vyplývají z toho dvě nesnáze, totiž že zlehčí to množství vzduchu, s nímž se mísí, a proto zlehčený vzduch sám vzlétne vzhůru a nezůstane v hustším vzduchu, než je on; a kromě toho se tato duchovní síla rozptýlením rozpojí a změní svou povahu, a tím pozbude své původní síly.","Přidává se třetí nesnáz, a to, že takové tělo ze vzduchu, které duch na sebe vzal, je vystaveno pronikání větrů, které ustavičně rozpojují a rvou spojené části vzduchu, převracejí je a víří v ostatním vzduchu. Duch rozlitý v takovém vzduchu by tedy byl rozčleněn, čili roztrhán a rozbit, spolu s roztrháním vzduchu, v němž se rozlil."],"ref":{"s":"R","l":1214,"st":"","z":false,"raw":"R. 1214"},"ca":[],"rr":"W. An. II. 242 a"},{"id":"s360","o":"Pensieri sulla morale","c":"X","str":194,"ni":"se lo spirito, avendo preso corpo d’aria, si può per se muovere o no","nc":"Duch se vzdušným tělem","it":["Impossibile è che lo spirito, infuso a una quantità d’aria, possa movere essa aria; e questo si manifesta per la passata, dove dice: — lo spirito levifica quella quantità dell’aria, nella quale esso s’infonde. — Adunque tale aria si leverà in alto sopra l’altra aria, e sarà moto fatto dell’aria per la sua levità e non per moto volontario dello spirito e, se tale aria si scontra nel vento, per la 3 di questo, essa aria sarà mossa dal vento e non dallo spirito, in lei infuso."],"cs":["Je nemožné, aby duch rozlitý v určitém množství vzduchu mohl tím vzduchem hýbat; a to je zřejmé z předešlé věty, kde se praví: – duch zlehčuje to množství vzduchu, v němž se rozlije. – Takový vzduch se tedy zvedne nad ostatní vzduch, a bude to pohyb vzduchu způsobený jeho lehkostí, a ne volním pohybem ducha; a narazí-li takový vzduch na vítr, bude podle třetí věty tohoto pojednání pohnut větrem, a ne duchem v něm rozlitým."],"ref":{"s":"R","l":1215,"st":"","z":false,"raw":"R. 1215"},"ca":[],"rr":"W. An. II. 201 b"},{"id":"s361","o":"Pensieri sulla morale","c":"XI","str":195,"ni":"se lo spirito può parlare o no","nc":"Zda duch může mluvit, či ne","it":["Volendo mostrare, se lo spirito può parlare o no, è necessario in prima definire ciie cosa è voce, e come si genera: e diremo in questo modo: — la voce è movimento d’aria conficcata in corpo denso o ’l corpo denso confricato nell’aria (che è il medesimo), la qual confricazione di denso con raro condensa il raro, e fassi resistenza; e ancora il veloce raro nel tardo raro si condensano l’uno e l’altro ne’ contatti, e fanno suono e grandissimo strepito. — È il suono, overo mormorio, fatto dal raro che si muove nel raro, con mediocre movimento, come la gran fiamma, generatrice di suoni infra l’aria; è il grandissimo strepito fatto di raro con raro, quando il veloce raro penetra in mobile raro, come la fiamma del foco uscita dalla bombarda e percossa infra l’aria, e ancora la fiamma uscita dal nuvolo, (che) percuote l’aria nella generazion delle saette.","Adunque diremo, che lo spirito non possa generar voce sanza movimento d’aria, e aria in lui non è, nè la può cacciare da sè, se egli non l’ha; e se voi movere quella, nella quale lui è infuso, egli è necessario che lo spirito moltiplichi, e moltiplicar non può, se lui non ha quantità, per la 4 che dice: — nessuno raro si move, se non ha loco stabile, donde lui pigli movimento, e massimamente avendosi a movere lo elemento nello elemento, il quale non si move da sè, se non per vaporazione uniforme al centro della cosa vaporata, come accade nella spugna ristretta nella mano, che sta sotto l’acqua, dalla qual l’acqua fugge, per qualunque verso, con egual movimento per le fessure interposte infra le dita della man, che dentro a sè la strignie. —","Se lo spirito ha voce articulata, e se lo spirito può essere audito.","E che cosa è audire e vedere: l’onda della voce va per l’aria, come le spezie delli obbietti vanno all’occhio."],"cs":["Chceme-li ukázat, zda duch může mluvit, či ne, je nejprve třeba definovat, co je hlas a jak vzniká; a řekneme takto: – hlas je pohyb vzduchu třeného o husté těleso nebo hustého tělesa třeného o vzduch (což je totéž); toto tření hustého s řídkým zhušťuje řídké a vzniká odpor; a také rychlé řídké a pomalé řídké se vzájemně zhušťují v dotyku a působí zvuk a převeliký hřmot. – Zvuk čili šum vzniká, když se řídké pohybuje v řídkém mírným pohybem, jako velký plamen, jenž ve vzduchu plodí zvuky; převeliký hřmot vzniká z řídkého s řídkým, když rychlé řídké proniká do pohyblivého řídkého, jako plamen ohně vyšlý z bombardy a narážející do vzduchu, a také plamen vyšlý z mračna, který naráží do vzduchu při vzniku blesků.","Řekneme tedy, že duch nemůže vytvořit hlas bez pohybu vzduchu, a vzduch v něm není, ani ho nemůže ze sebe vypudit, nemá-li ho; a chce-li pohnout tím, v němž je rozlit, je nutné, aby se duch rozmnožil, a rozmnožit se nemůže, nemá-li velikost, podle čtvrté věty, která praví: – žádné řídké se nepohne, nemá-li pevné místo, od něhož by nabralo pohyb, a zvláště má-li se pohybovat živel v živlu, který se sám od sebe nepohne, leda vypařováním stejnoměrným ke středu vypařované věci, jako se to děje u houby stisknuté v ruce pod vodou, z níž voda uniká na všechny strany stejným pohybem skulinami mezi prsty ruky, která ji v sobě svírá. –","Zda má duch článkovaný hlas a zda duch může být slyšen.","A co je slyšet a vidět: vlna hlasu jde vzduchem, tak jako obrazy předmětů jdou k oku."],"ref":{"s":"B","l":4,"st":"v","z":true,"raw":"B. 4 v"},"ca":[]},{"id":"s362","o":"Pensieri sulla morale","c":"XII","str":196,"ni":"sul medesimo soggetto","nc":"K témuž","it":["O matematici fate lume a tale errore!","Lo spirito non ha voce, perche dov’è voce è corpo, e dove è corpo è occupazion di loco, il quale impedisce all’occhio il vedere delle cose poste dopo tale loco: adunque tal corpo empie di sè tutta la circostante aria, cioè con le sua spezie."],"cs":["Ó matematikové, osviťte tento omyl!","Duch nemá hlas, protože kde je hlas, je tělo, a kde je tělo, je zaujetí místa, které brání oku vidět věci položené za tímto místem: takové tělo tedy sebou naplňuje všechen okolní vzduch, totiž svými obrazy."],"ref":{"s":"B","l":4,"st":"v","z":true,"raw":"B. 4 v"},"ca":[]},{"id":"s363","o":"Pensieri sulla morale","c":"XIII","str":197,"ni":"sul medesimo soggetto","nc":"K témuž","it":["Non po’ essere voce, dove non è movimento o percussione d’aria, non po’ essere percussione d’essa aria, dove non è strumento, non po’ essere strumento incorporeo. Essendo così, uno spirito non po’ avere nè voce, nè forma, nè forza, e, se piglierà corpo, non potrà penetrare, nè entrare, dove li usci sono serrati. E se alcuno dicessi: — per aria congregata e ristretta insieme lo spirito piglia i corpi di varie forme, e per quello strumento parla e move con forza; — a questa parte dico, che, dove non è nervi e ossa, non po’ essere forza operata, in nessuno movimento, fatto da gl’imaginati spiriti."],"cs":["Nemůže být hlas tam, kde není pohyb nebo náraz vzduchu; nemůže být náraz toho vzduchu tam, kde není nástroj; nemůže být nástroj netělesný. Je-li tomu tak, duch nemůže mít ani hlas, ani tvar, ani sílu, a vezme-li na sebe tělo, nebude moci proniknout ani vejít tam, kde jsou dveře zavřené. A kdyby někdo řekl: – ze vzduchu shromážděného a stlačeného dohromady bere duch těla rozličných tvarů a tímto nástrojem mluví a silou hýbe; – k tomu pravím, že kde nejsou šlachy a kosti, nemůže být vyvinuta síla v žádném pohybu, který by učinili domnělí duchové."],"ref":{"s":"B","l":4,"st":"v","z":false,"raw":"B. 4 v"},"ca":[]},{"id":"s364","o":"Pensieri sulla morale","c":"XIV","str":197,"ni":"studi sulla fisonomia","nc":"Studie o fyziognomice","it":["Della fallace Fisonomia e Chiromanzia non mi astenderò, perchè in loro non è verità, e questo si manifesta, perchè tali chimere non hanno fondamenti scientifici.","Ver è che li segni de’ volti mostrano in parte la natura degli uomini, li lor vizi e complessioni, ma nel volto:","a) Li segni, che separano le guance da’ labbri della bocca, e le nari del naso, e casse degli occhi, sono evidenti, se sono uomini allegri e spesso ridenti; e quelli, che poco li segnano, sono uomini operatori della cogitazione.","b) E quelli, ch’hanno le parti del viso di gran rilievo e profondità, sono uomini bestiali e iracondi, con poca ragione.","c) E quelli, ch’hanno le linee interposte infra le ciglia forte evidenti, sono iracondi.","d) E quelli, che hanno le linee trasversali della fronte forte lineate, sono uomini copiosi di lamentazioni occulte o palesi. — E così si po’ dire di molte parti. —","Ma della mano? Tu troverai grandissimi eserciti essere morti ’n una medesima ora di coltello, che nessun segno della mano è simile l’uno all’altro; e così in un naufragio."],"cs":["O klamné Fyziognomice a Chiromancii se nebudu šířit, protože v nich není pravdy, a to je zřejmé, neboť takové chiméry nemají vědecké základy.","Pravda je, že rysy tváří zčásti ukazují povahu lidí, jejich neřesti a založení, ale ve tváři:","a) Rýhy, které oddělují tváře od rtů úst, a chřípí nosu a důlky očí, jsou zřetelné, jsou-li to lidé veselí a často se smějící; a ti, u nichž jsou málo vyznačené, jsou lidé oddaní přemýšlení.","b) A ti, kteří mají části obličeje velmi vystouplé a hluboké, jsou lidé hovadní a prchliví, s malým rozumem.","c) A ti, kteří mají čáry mezi obočím silně zřetelné, jsou prchliví.","d) A ti, kteří mají příčné čáry na čele silně vryté, jsou lidé plní skrytého či zjevného naříkání. – A tak se dá říci o mnoha částech. –","Ale co ruka? Najdeš převeliká vojska, která zahynula v jedné a téže hodině mečem, a žádné znamení ruky není jedno druhému podobné; a stejně tak při ztroskotání lodi."],"ref":null,"ca":[]},{"id":"s365","o":"Pensieri sulla morale","c":"XV","str":198,"ni":"contro i ricercatori del moto perpetuo","nc":"Proti hledačům věčného pohybu","it":["L’acqua, che pel fiume si move, o ell’è chiamata, o ell’è cacciata, o ella si move da sè; s’ella è chiamata, o vo’ dirò addimandata, quale è esso addimandatore? s’ella è cacciata, chi è quel che la caccia? s’ella si move da sè, ella mostra d’avere discorso: il che nelli corpi di continua mutazione di forma è impossibile avere discorso, perchè in tali corpi non è giudizio."],"cs":["Voda, která se pohybuje řekou, je buď volána, nebo hnána, nebo se pohybuje sama od sebe; je-li volána, čili, abych tak řekl, přivolávána, kdo je ten, kdo ji přivolává? Je-li hnána, kdo je ten, kdo ji žene? Pohybuje-li se sama od sebe, ukazuje, že má rozvahu: a mít rozvahu je u těles, která ustavičně mění tvar, nemožné, protože v takových tělesech není úsudku."],"ref":{"s":"K","l":101,"st":"v","z":false,"raw":"K. 101 v"},"ca":[]},{"id":"s366","o":"Pensieri sulla morale","c":"XVI","str":199,"ni":"segue","nc":"Pokračování","it":["L’acqua da sè non ha fermezza, e da se non si move, s’ella non discende.","L’acqua per sè non si ferma, s’elìa non è contenuta."],"cs":["Voda sama o sobě nemá pevnost a sama od sebe se nepohybuje, nesestupuje-li.","Voda se sama o sobě nezastaví, není-li něčím obsažena."],"ref":{"s":"F","l":30,"st":"v","z":false,"raw":"F. 30 v"},"ca":[]},{"id":"s367","o":"Pensieri sulla morale","c":"XVII","str":199,"ni":"sul medesimo soggetto","nc":"K témuž","it":["O speculatori dello continuo moto quanti vani disegni, in simile cerca, avete creato! accompagnatevi colli cercatori dell’oro."],"cs":["Ó vy, kdo bádáte o ustavičném pohybu, kolik marných návrhů jste při takovém hledání vytvořili! Přidejte se k hledačům zlata."],"ref":{"s":"R","l":1206,"st":"","z":false,"raw":"R. 1206"},"ca":[],"rr":"S. K. M. II.2 67 a"},{"id":"s368","o":"Pensieri sulla morale","c":"XVIII","str":199,"ni":"avvertimento","nc":"Výstraha","it":["Non si debbe desiderare lo impossibile."],"cs":["Nemá se toužit po nemožném."],"ref":{"s":"E","l":31,"st":"v","z":false,"raw":"E. 31 v"},"ca":[]},{"id":"s369","o":"Pensieri sulla morale","c":"XIX","str":199,"ni":"contro le scienze occulte","nc":"Proti tajným vědám","it":["Voglio far miracoli! Abbi men che li altri omini più quieti: e quelli, che vogliono arricchirsi in un dì, vivon del lungo tempo in gran povertà, come interviene e interverrà in eterno alli alchimisti, cercatori di creare oro e argento, e all’ingegnieri, che vogliono che l’acqua morta dia vita motiva a sè medesima con continuo moto, e al sommo stolto negromante e incantatore."],"cs":["Chci dělat zázraky! – Budeš mít méně než ostatní, klidnější lidé: a ti, kdo chtějí zbohatnout za den, žijí dlouhý čas ve velké chudobě, jak se děje a bude dít navěky alchymistům, hledačům, kteří chtějí stvořit zlato a stříbro, a inženýrům, kteří chtějí, aby mrtvá voda sama sobě dala pohybový život ustavičným pohybem, a nejvyššímu hlupákovi, nekromantovi a zaklínači."],"ref":{"s":"R","l":796,"st":"","z":false,"raw":"R. 796"},"ca":[],"rr":"W. An. IV. 167 a"},{"id":"s370","o":"Pensieri sulla morale","c":"XX","str":200,"ni":"contro i medici","nc":"Proti lékařům","it":["Omini son eletti per medici di malattie da loro non conosciute."],"cs":["Lidé jsou voleni za lékaře nemocí, které neznají."],"ref":{"s":"R","l":797,"st":"","z":false,"raw":"R. 797"},"ca":[],"rr":"W. An. II. 36 a"},{"id":"s371","o":"Pensieri sulla morale","c":"XXI","str":200,"ni":"ancora","nc":"Ještě","it":["Ogni omo desidera far capitale per dare a’ medici, distruttori di vite.","Adunque devono esser ricchi."],"cs":["Každý člověk touží nashromáždit jmění, aby je dal lékařům, ničitelům životů.","Musí tedy být bohatí."],"ref":{"s":"R","l":100,"st":"","z":true,"raw":"R. 100"},"ca":[],"rr":"A. 8 b"},{"id":"s372","o":"Pensieri sulla morale","c":"XXII","str":200,"ni":"ancora","nc":"Ještě","it":["E ingegnati di conservare la sanità, la qual cosa tanto più ti riuscirà, quanto più da’ fisici ti guarderai, perchè le sue composizioni son di specie d’Alchimia, della quale non è men numero di libri, ch’esista di Medicina."],"cs":["A snaž se uchovat zdraví, což se ti tím spíš podaří, čím víc se budeš varovat fyziků, neboť jejich směsi jsou jakýmsi druhem Alchymie, o níž není o nic méně knih, než kolik jich existuje o Medicíně."],"ref":{"s":"R","l":100,"st":"","z":true,"raw":"R. 100"},"ca":[],"rr":"A. 8 b"},{"id":"s373","o":"Pensieri sulla morale","c":"XXIII","str":201,"ni":"funzione del dolore nella vita animale","nc":"Úloha bolesti v životě živočichů","it":["La natura ha posto, nel moto dell’omo, tutte quelle parti dinanzi, le quali percuotendo, l’omo abbia a sentire doglia; e questo si sente ne’ fusi delle gambe e nella fronte e naso: ed è fatto a conservazione dell’omo, inperó che, se tale dolore non fussi preparato in essi membri, certo le molte percussioni, in tali membra ricevute, sarebbero causa della lor destruzione."],"cs":["Příroda umístila v pohybu člověka dopředu všechny ty části, při jejichž nárazu má člověk pocítit bolest; a to se pociťuje na holeních nohou a na čele a nose: a je to učiněno k zachování člověka, neboť kdyby v těch údech nebyla taková bolest připravena, jistě by mnohé nárazy, které tyto údy utrží, byly příčinou jejich zničení."],"ref":{"s":"R","l":100,"st":"","z":false,"raw":"R. 100"},"ca":[],"rr":"A. 8 b"},{"id":"s374","o":"Pensieri sulla morale","c":"XXIV","str":201,"ni":"perchè le piante non hanno il dolore","nc":"Proč rostliny necítí bolest","it":["Se la natura ha ordinato la doglia, nell’anime vegetative col moto, per conservazione delli strumenti, i quali pel moto si potrebbono diminuire e guastare; l’anime vegetative sanza moto non hanno a percotere ne’ contra sè posti obietti, onde la doglia non è necessaria nelle piante, onde rompendole non sentono dolore, come quelle delli animali."],"cs":["Jestliže příroda zřídila bolest u vegetativních duší spojených s pohybem k zachování nástrojů, které by se pohybem mohly umenšit a poškodit, vegetativní duše bez pohybu nemusejí narážet do předmětů postavených proti nim; proto bolest není u rostlin nutná, a proto když je lámeš, necítí bolest jako ty u zvířat."],"ref":{"s":"H","l":60,"st":"r","z":false,"raw":"H. 60 r"},"ca":[]},{"id":"s375","o":"Pensieri sulla morale","c":"XXV","str":202,"ni":"funzione delle passioni a conservazion della vita","nc":"Úloha vášní při zachování života","it":["Lussuria è causa della generazione.","Gola è mantenimento della vita.","Paura over timore è prolungamento di vita.","Dolore è salvamento dello strumento."],"cs":["Smilnost je příčinou plození.","Obžerství je udržováním života.","Strach čili bázeň je prodlužováním života.","Bolest je ochranou nástroje."],"ref":{"s":"H","l":32,"st":"r","z":false,"raw":"H. 32 r"},"ca":[]},{"id":"s376","o":"Pensieri sulla morale","c":"XXVI","str":202,"ni":"animosità e paura","nc":"Odvaha a strach","it":["Sì come l’animosità è pericolo di vita, così la paura è sicurtà di quella."],"cs":["Jako je odvaha nebezpečím pro život, tak je strach jeho jistotou."],"ref":{"s":"C.A","l":76,"st":"r","z":false,"raw":"C. A. 76 r"},"ca":[412,414]},{"id":"s377","o":"Pensieri sulla morale","c":"XXVII","str":202,"ni":"il corpo è specchio dell’anima","nc":"Tělo je zrcadlem duše","it":["Chi vole vedere come l’anima abita nel suo corpo, guardi come esso corpo usa la sua cotidiana abitazione; cioè, se quella è sanza ordine e confusa, disordinato e confuso fia il corpo tenuto dalla su’ anima."],"cs":["Kdo chce vidět, jak duše přebývá ve svém těle, ať se podívá, jak to tělo užívá svého každodenního obydlí; totiž je-li ono bez pořádku a zmatené, neuspořádané a zmatené bude tělo, které jeho duše spravuje."],"ref":{"s":"C.A","l":76,"st":"r","z":false,"raw":"C. A. 76 r"},"ca":[412,414]},{"id":"s378","o":"Pensieri sulla morale","c":"XXVIII","str":202,"ni":"indipendenza dell’anima dalla materia corporea","nc":"Nezávislost duše na tělesné hmotě","it":["L’anima mai si può corrompere nella corruzione del corpo, ma fa a similitudine del vento, ch’è causa del sono dell’organo, che, guastandosi una canna, non resultava per quella del vôto buono effetto."],"cs":["Duše se nikdy nemůže porušit při porušení těla, ale děje se s ní podobně jako s větrem, který je příčinou zvuku varhan: když se jedna píšťala pokazí, nevzniká v ní z větru dobrý účinek [vítr sám však trvá]."],"ref":{"s":"H","l":33,"st":"v","z":true,"raw":"H. 33 v"},"ca":[]},{"id":"s379","o":"Pensieri sulla morale","c":"XXIX","str":203,"ni":"la memoria","nc":"Paměť","it":["Ogni danno lascia dispiacere nella ricordazione, salvo che ’l sommo danno, cioè la morte, che uccide essa ricordazione insieme colla vita."],"cs":["Každá škoda zanechává v rozpomínání zármutek, kromě škody nejvyšší, totiž smrti, která zabíjí rozpomínání spolu se životem."],"ref":{"s":"H","l":33,"st":"v","z":false,"raw":"H. 33 v"},"ca":[]},{"id":"s380","o":"Pensieri sulla morale","c":"XXX","str":203,"ni":"lo spirito è dominatore","nc":"Duch je vládcem","it":["Il corpo nostro è sottoposto al cielo, e lo cielo è sottoposto allo spirito."],"cs":["Naše tělo je podřízeno nebi a nebe je podřízeno duchu."],"ref":null,"ca":[]},{"id":"s381","o":"Pensieri sulla morale","c":"XXXI","str":203,"ni":"ragione e senso","nc":"Rozum a smysly","it":["I sensi sono terrestri, e la ragione sta fuori di quelli, quando contempla."],"cs":["Smysly jsou pozemské a rozum stojí mimo ně, když rozjímá."],"ref":{"s":"T","l":33,"st":"r","z":false,"raw":"T. 33 r"},"ca":[]},{"id":"s382","o":"Pensieri sulla morale","c":"XXXII","str":203,"ni":"sentimento e martirio","nc":"Cit a mučednictví","it":["Dov’è più sentimento, lì è più, ne’ martiri, gran martire."],"cs":["Kde je více citu, tam je v mukách větší mučednictví."],"ref":{"s":"T","l":23,"st":"v","z":false,"raw":"T. 23 v"},"ca":[]},{"id":"s383","o":"Pensieri sulla morale","c":"XXXIII","str":203,"ni":"la virtù è il vero bene dell’uomo","nc":"Ctnost je pravým dobrem člověka","it":["Non si dimanda ricchezza quella che si può perdere, la virtù è vero nostro bene, ed è vero premio del suo possessore: lei non si può perdere, lei non ci abbandona, se prima la vita non ci lascia; le robe e le esterne dovizie sempre le tieni con timore, e ispesso lasciano con iscorno e sbeffato il loro possessore, perdendo la possessione."],"cs":["Bohatstvím se nenazývá to, co lze ztratit; ctnost je naše pravé dobro a je pravou odměnou svého vlastníka: tu nelze ztratit, ta nás neopustí, dokud nás dříve neopustí život; statky a vnější hojnost držíš vždy se strachem a často opouštějí svého vlastníka s hanbou a posměchem, když o své jmění přijde."],"ref":{"s":"Ash.I","l":34,"st":"v","z":false,"raw":"Ash. I. 34 v"},"ca":[]},{"id":"s384","o":"Pensieri sulla morale","c":"XXXIV","str":204,"ni":"la brevità del tempo è una illusione della mente","nc":"Krátkost času je klamem mysli","it":["A torto si lamentali li omini della fuga del tempo, incolpando quello di troppa velocità, non s’accorgendo quello esser di bastevole transito; ma bona memoria, di che la natura ci ha dotati, ci fa che ogni cosa lungamente passata ci pare esser presente."],"cs":["Neprávem si lidé stěžují na útěk času a obviňují jej z přílišné rychlosti, aniž si uvědomují, že jeho běh je dostatečný; ale dobrá paměť, kterou nás příroda obdařila, způsobuje, že každá věc dávno minulá se nám zdá přítomná."],"ref":{"s":"C.A","l":76,"st":"r","z":false,"raw":"C. A. 76 r"},"ca":[412,414]},{"id":"s385","o":"Pensieri sulla morale","c":"XXXV","str":204,"ni":"illusioni della mente e del senso","nc":"Klamy mysli a smyslů","it":["Il giudizio nostro non giudica le cose, fatte in varie distanzie di tempo, nelle debite e proprie lor distanzie, perchè molte cose passate di molti anni parranno propinque e vicine al presente, e molte cose vicine parranno antiche, insieme coll’antichità della nostra gioventù; e così fa l’occhio infra le cose distanti, che, per essere alluminate dal sole, paiano vicine all’occhio, e molte cose vicine paiano distanti."],"cs":["Náš úsudek neposuzuje věci, které se staly v rozličných časových vzdálenostech, v jejich náležitých a vlastních vzdálenostech, protože mnohé věci, které minuly před mnoha lety, se budou zdát blízké a sousedící s přítomností, a mnohé věci blízké se budou zdát dávné, spolu s dávností našeho mládí; a tak činí i oko mezi vzdálenými věcmi, které, jsouce osvětleny sluncem, se zdají oku blízké, a mnohé věci blízké se zdají vzdálené."],"ref":{"s":"C.A","l":29,"st":"v","z":false,"raw":"C. A. 29 v"},"ca":[161,163]},{"id":"s386","o":"Pensieri sulla morale","c":"XXXVI","str":204,"ni":"ideando un orologio a piombo","nc":"Při navrhování hodin s olověným závažím","it":["Non ci manca modi, nè vie di compartire e misurare questi nostri miseri giorni, i quali ci debba ancor piacere di non spenderli e trapassargli indarno e sanza alcuna loda, e sanza lasciare di sè alcuna memoria nelle menti de’ mortali. Acciò che questo nostro misero corso non trapassi indarno."],"cs":["Nechybějí nám způsoby ani cesty, jak rozvrhnout a měřit tyto naše ubohé dny, jež bychom měli rádi nepromarnit a nepromrhat nadarmo a bez jakékoli chvály a bez zanechání jakékoli vzpomínky na sebe v myslích smrtelníků. Aby tento náš ubohý běh nepominul nadarmo."],"ref":{"s":"C.A","l":12,"st":"r","z":false,"raw":"C. A. 12 r"},"ca":[82,84]},{"id":"s387","o":"Pensieri sulla morale","c":"XXXVII","str":205,"ni":"la vita virtuosa","nc":"Ctnostný život","it":["L’età, che vola, discorre nascostamente, e inganna altrui; e niuna cosa è più veloce che gli anni, e chi semina virtù fama raccoglie."],"cs":["Věk, který letí, ubíhá skrytě a klame druhé; a žádná věc není rychlejší než léta, a kdo seje ctnost, sklízí slávu."],"ref":{"s":"C.A","l":71,"st":"v","z":false,"raw":"C. A. 71 v"},"ca":[389,391]},{"id":"s388","o":"Pensieri sulla morale","c":"XXXVIII","str":205,"ni":"epigramma","nc":"Epigram","it":["O dormiente, che cosa è sonno? Il sonno ha similitudine colla morte; o perchè non fai adunque tale opra, che, dopo la morte, tu abbi similitudine di perfetto vivo, che, vivendo, farti, col sonno, simile ai tristi morti?"],"cs":["Ó spáči, co je spánek? Spánek se podobá smrti; ó proč tedy nekonáš takové dílo, abys byl po smrti podoben dokonale živému, místo abys za živa byl spánkem podoben ubohým mrtvým?"],"ref":{"s":"C.A","l":76,"st":"r","z":false,"raw":"C. A. 76 r"},"ca":[412,414]},{"id":"s389","o":"Pensieri sulla morale","c":"XXXIX","str":205,"ni":"l’attimo è fuggevole","nc":"Okamžik je prchavý","it":["L’acqua, che tocchi de’ fiumi, è l’ultima, di quella che andò e la prima di quella che viene: così il tempo presente."],"cs":["Voda řek, které se dotýkáš, je poslední z té, která odtekla, a první z té, která přichází: tak i přítomný čas."],"ref":{"s":"T","l":34,"st":"r","z":false,"raw":"T. 34 r"},"ca":[]},{"id":"s390","o":"Pensieri sulla morale","c":"XL","str":205,"ni":"nobiltà del lavoro","nc":"Ušlechtilost práce","it":["La vita bene spesa lunga è."],"cs":["Život dobře strávený je dlouhý."],"ref":{"s":"T","l":34,"st":"r","z":false,"raw":"T. 34 r"},"ca":[]},{"id":"s391","o":"Pensieri sulla morale","c":"XLI","str":206,"ni":"la vita laboriosa","nc":"Pracovitý život","it":["Sì come una giornata bene spesa dà lieto dormire, così una vita bene usata dà lieto morire."],"cs":["Jako dobře strávený den dává radostný spánek, tak dobře užitý život dává radostné umírání."],"ref":{"s":"T","l":27,"st":"r","z":false,"raw":"T. 27 r"},"ca":[]},{"id":"s392","o":"Pensieri sulla morale","c":"XLII","str":206,"ni":"il tempo distruggitore","nc":"Čas ničitel","it":["O tempo, consumatore delle cose, e o invidiosa antichità, tu distruggi tutte le cose! e consumate tutte le cose dai duri denti della vecchiezza, a poco a poco, con lenta morte! Elena, quando si specchiava, vedendo le vizze grinze del suo viso, fatto per la vecchiezza, piagne e pensa seco, perchè fu rapita due volte.","O tempo consumatore delle cose, e o invidiosa antichità, per la quale tutte le (cose) sono consumate!"],"cs":["Ó čase, stráviteli věcí, a ó závistivé stáří, ty ničíš všechny věci a stravuješ všechny věci tvrdými zuby stárnutí, pomalu, pozvolnou smrtí! Helena, když se zhlížela v zrcadle a viděla zvadlé vrásky své tváře, způsobené stářím, pláče a v duchu přemítá, proč byla dvakrát unesena.","Ó čase, stráviteli věcí, a ó závistivé stáří, jímž jsou všechny věci stráveny!"],"ref":{"s":"Lu","l":77,"st":"","z":true,"raw":"Lu. 77"},"ca":[]},{"id":"s393","o":"Pensieri sulla morale","c":"XLIII","str":206,"ni":"di quelli che biasimano chi disegna alle feste e chi ’nvestiga l’opere di dio","nc":"Kreslení o svátcích","it":["Sono infra ’l numero delli stolti una certa setta detti ipocriti, ch’al continuo studiano d’ingannare sè e altri, ma più altri, che sè: ma invero ingannano più loro stessi, che gli altri. E questi son quelli, che riprendono li pittori, li quali studiano li giorni delle feste, nelle cose appartenenti alla vera cognizione di tutte le figure, ch’hanno le opere di Natura, e, con sollecitudine, s’ingegnano d’acquistare la cognizione di quelle, quanto a loro sia possibile.","Ma tacciano tali reprensori, questo è ’l modo di conoscere l’Operatore di tante mirabili cose, e quest’è ’l modo d’amare un tanto Inventore! Che ’nvero il grande amore nasce dalla gran cognizione della cosa, che si ama: e se tu non la conoscerai, poco o nulla la potrai amare; e se tu l’ami per il bene, che t’aspetti da lei, e non per la somma sua virtù, tu fai come ’l cane, che mena la coda, e fa festa, alzandosi verso colui, che li po’ dare un osso. Ma se conoscesse la virtù di tale omo, l’amarebbe assai più — se tal virtù fussi al suo proposito."],"cs":["Mezi počtem hlupáků je jistá sekta zvaná pokrytci, kteří se ustavičně snaží klamat sebe i jiné, ale víc jiné než sebe: ve skutečnosti však klamou víc sami sebe než jiné. A to jsou ti, kdo kárají malíře, kteří ve sváteční dny studují věci týkající se pravého poznání všech tvarů, jež mají díla Přírody, a s horlivostí se snaží získat jejich poznání, nakolik je jim to možné.","Ale ať zmlknou takoví kárači: toto je způsob, jak poznat Původce tolika obdivuhodných věcí, a toto je způsob, jak milovat tak velikého Vynálezce! Neboť vpravdě velká láska se rodí z velkého poznání věci, kterou milujeme: a nebudeš-li ji znát, budeš ji moci milovat málo nebo vůbec; a miluješ-li ji pro dobro, které od ní očekáváš, a ne pro její nejvyšší ctnost, děláš jako pes, který vrtí ocasem a raduje se a vzpíná se k tomu, kdo mu může dát kost. Ale kdyby poznal ctnost takového člověka, miloval by ho mnohem víc – kdyby se mu ta ctnost hodila."],"ref":{"s":"Lu","l":77,"st":"","z":false,"raw":"Lu. 77"},"ca":[]},{"id":"s394","o":"Pensieri sulla morale","c":"XLIV","str":207,"ni":"preghiera","nc":"Modlitba","it":["Io t’ubbidisco, Signore, prima per l’amore, che ragionevolmente portare ti debbo, secondariamente, che tu sai abbreviare o prolungare la vita alli omini."],"cs":["Poslouchám tě, Pane, předně z lásky, kterou ti rozumně mám prokazovat, a za druhé proto, že umíš lidem život zkrátit nebo prodloužit."],"ref":{"s":"R","l":1132,"st":"","z":false,"raw":"R. 1132"},"ca":[],"rr":"S. K. M. III. 64 b"},{"id":"s395","o":"Pensieri sulla morale","c":"XLV","str":207,"ni":"orazione","nc":"Modlitba","it":["Tu, o Iddio, ci vendi tutti li beni per prezzo di fatica."],"cs":["Ty, ó Bože, nám prodáváš všechna dobra za cenu námahy."],"ref":{"s":"R","l":1133,"st":"","z":false,"raw":"R. 1133"},"ca":[],"rr":"W. An. IV. 172 a"},{"id":"s396","o":"Pensieri sulla morale","c":"XLVI","str":208,"ni":"contro i cattivi religiosi","nc":"Proti špatným duchovním","it":["E molti fecen bottega, ingannando la stolta moltitudine, e, se nessun si scoprìa conoscitore de’ loro inganni, essi gli puniano."],"cs":["A mnozí si z toho udělali kšeft a klamali pošetilý dav, a jestliže se někdo ukázal jako znalec jejich podvodů, trestali ho."],"ref":{"s":"T","l":68,"st":"","z":false,"raw":"T. 68"},"ca":[]},{"id":"s397","o":"Pensieri sulla morale","c":"XLVII","str":208,"ni":"ancora","nc":"Ještě","it":["Farisei frati santi vol dire."],"cs":["Farizeové – to chce říci svatí mniši."],"ref":null,"ca":[]},{"id":"s398","o":"Pensieri sulla morale","c":"XLVIII","str":208,"ni":"tutto è stato detto","nc":"Všechno už bylo řečeno","it":["Nulla può essere scritto per nuovo ricercare."],"cs":["Nic nemůže být napsáno, co by bylo nově vybádáno."],"ref":{"s":"T","l":14,"st":"r","z":true,"raw":"T. 14 r"},"ca":[]},{"id":"s399","o":"Pensieri sulla morale","c":"XLIX","str":208,"ni":"comparazione della pazienza","nc":"Přirovnání o trpělivosti","it":["La pazienza fa contra alle ingiurie non altrimenti che si faccino i panni contra del freddo; imperò che, se ti multiplicherai di panni secondo la multiplicazione del freddo, esso freddo nocere non ti potrà; similmente alle grandi ingiurie cresci la pazienza, esse ingiurie offendere non ti potranno la tua mente."],"cs":["Trpělivost působí proti křivdám ne jinak, než působí šaty proti zimě; neboť budeš-li si přidávat šatů podle toho, jak přibývá zimy, ta zima ti nebude moci uškodit; podobně proti velkým křivdám zvětšuj trpělivost, a ty křivdy nebudou moci zranit tvou mysl."],"ref":{"s":"C.A","l":117,"st":"v","z":false,"raw":"C. A. 117 v"},"ca":[643,645,647]},{"id":"s400","o":"Pensieri sulla morale","c":"L","str":208,"ni":"consigli al parlatore","nc":"Rady řečníkovi","it":["Sempre le parole, che non soddisfano all’orecchio dello auditore, li danno tedio over rincrescimento: e ’l segno di ciò vedrai, spesse volte tali auditori essere copiosi di sbadigli. Adunque tu, che parli dinanzi a omini, di chi tu cerchi benivolenza, quando tu vedi tali prodigi di rincrescimento, abbrevia il tuo parlare o tu muta ragionamento; e se altramente farai, allora, in loco della desiderata grazia, tu acquisterai odio e inimicizia.","E se vuoi vedere di quel che un si diletta, sanza udirlo parlare, parla a lui mutando diversi ragionamenti, e quel dove tu lo vedi stare intento, sanza sbadigliamenti o storcimenti di ciglia o altre varie azioni, sta certo che quella cosa, di che si parla, è quella, di che lui si diletta."],"cs":["Slova, která neuspokojují ucho posluchače, mu vždy působí nudu čili omrzelost: a znamení toho uvidíš v tom, že takoví posluchači často hojně zívají. Ty tedy, který mluvíš před lidmi, jejichž přízeň hledáš, když vidíš taková znamení omrzelosti, zkrať svou řeč nebo změň téma; a budeš-li jednat jinak, získáš místo žádané přízně nenávist a nepřátelství.","A chceš-li zjistit, v čem si kdo libuje, aniž bys ho slyšel mluvit, mluv k němu a střídej rozličná témata; a u kterého ho uvidíš pozorně naslouchat, bez zívání či svraštění obočí či jiných rozličných projevů, buď si jist, že ta věc, o níž se mluví, je ta, v níž si libuje."],"ref":{"s":"G","l":49,"st":"r","z":false,"raw":"G. 49 r"},"ca":[]},{"id":"s401","o":"Pensieri sulla morale","c":"LI","str":209,"ni":"consiglio, miseria e giudizio","nc":"Rada, bída a úsudek","it":["Ecci una cosa, che, quanto più se n’ha bisogno, più si rifiuta: e questo è il consiglio, mal volontieri ascoltato, da chi ha più bisogno, cioè dagl’ignoranti.","Ecci una cosa, che, quanto più n’hai paura e più la fuggi, più te l’avvicini: e questo è la miseria, che quanto più la fuggi, più ti farai misero e sanza riposo.","Quando l’opera sia pari col giudizio, quello è tristo segno, in quel giudizio; e quando l’opera supera il giudizio, questo è pessimo, com’accade a chi si maraviglia d’avere sì ben operato; e quando il giudizio supera l’opera, questo è perfetto segno; e se gli è giovane, in tal disposizione, sanza dubbio questo fia eccellente operatore, ma fia componitore di poche opere. Ma fieno di qualità, che fermeranno gli uomini con admirazione, a contemplar le sue perfezioni."],"cs":["Je jedna věc, která se tím víc odmítá, čím víc je jí zapotřebí: a to je rada, nerada slyšená od těch, kdo jí nejvíc potřebují, totiž od nevědomých.","Je jedna věc, ke které se tím víc přibližuješ, čím víc se jí bojíš a čím víc před ní prcháš: a to je bída, neboť čím víc před ní prcháš, tím víc se učiníš ubohým a bez odpočinku.","Když je dílo na úrovni úsudku, je to v tom úsudku špatné znamení; a když dílo převyšuje úsudek, je to nejhorší, jak se stává tomu, kdo se diví, že tak dobře pracoval; a když úsudek převyšuje dílo, je to dokonalé znamení; a je-li v takovém rozpoložení mladík, bude to bezpochyby vynikající tvůrce, ale bude skladatelem málo děl. Ta však budou takové jakosti, že zastaví lidi v obdivu, aby rozjímali o jejich dokonalostech."],"ref":{"s":"C.A","l":80,"st":"v","z":false,"raw":"C. A. 80 v"},"ca":[433,435]},{"id":"s402","o":"Pensieri sulla morale","c":"LII","str":210,"ni":"sentenze, proverbi e simboli","nc":"Výroky, přísloví a symboly","it":["Nessuna cosa è da temere più che la sozza fama.","Questa sozza fama à nata da vizi.","Comparazione. Un vaso rotto crudo, rotto, si pub riformare, ma il cotto no.","Il vóto nasce, quando la speranza more.","Non è sempre bono quel ch’è bello.... E in questo errore sono i belli parlatori, sanza alcuna sentenza.","Chi vuole essere ricco in un di, è impiccato in un anno.","La memoria de’ beni fatti, appresso l’ingratitudine, è fragile.","Reprendi l’amico in segreto, e laudalo in palese.","Chi teme i pericoli, non perisce per quegli.","Tale è ’l mal, che non mi noce, quale è ’l ben, che non mi giova.","Chi altri offende, sé non sicura.","Non essere bugiardo del preterito.","La stoltizia è scudo della menzogna, come la improntitudine della povertà.","Dov’è libertà, non è regola.","Ecci una cosa quanto più se n’ha di bisogno manco si stima, è il consiglio.","Mal fai se laudi e peggio se riprendi la cosa, quando ben tu non la intendi.","Ti ghiacciano le parole in bocca, e faresti gelatina in Mongibello.","Le minacceo solo sono arme dello imminacciato.","Dimanda consiglio a chi ben si corregge.","Giustizia vol potenza, intelligenza e volontà, e si assomiglia al re delle ave.","Chi non punisce il male, comanda che si facci.","Chi piglia la biscia per la coda, quella poi lo morde.","Chi cava la fossa, quella gli ruina addosso.","Chi non raffrena la voluttà, con le bestie s’accompagni.","Non si po’ avere maggior nè minore signoria, che quella di sè medesimo.","Chi poco pensa, molto erra.","Più facilmente si contesta al principio, che al fine.","Nessuno consiglio è più leale, che quello che si dà dalle navi, che sono in pericolo.","Aspetti danno quel, che si regge per giovane in consiglio.","Tu cresci in reputazione, come il pane in mano a’ putti.","Non po’ essere bellezza e utilità? come appare nelle fortezze e nelli omini.","Chi non teme, spesso è pien di danni, spesso si pente.","Se tu avessi il corpo secondo la virtù, tu non caperesti in questo mondo.","Dov’entra la ventura, la ’nvidia vi pone lo assedio, e la combatte; e dond’ella si parte, vi lascia il dolore e pentimento.","Le bellezze con le bruttezze paiono più potenti l’una per l’altra.","Raro cade chi ben cammina.","Oh miseria umana, di quante cose per danari ti fai servo!","Sommo danno è, quando l’opinione avanza l’opera.","Tanto è a dire ben d’un tristo, quanto a dire male d’un bono.","La verità fa qui, che la bugia affligga lo lingue bugiarde.","Chi non stima la vita, non la merita.","Cosa bella mortal passa e non dura.","Fatica fugge, colla fama in braccio, quasi occultata.","L’oro in verghe, s’affinisce nel foco.","Spola: tanto mi moverò che la tela fia finita.","Ogni torto si dirizza.","Di lieve cosa nasciesi gran ruina.","Al cimento si conosce il fine oro.","Tal fia il getto, qual fia la stampa.","Chi scalza il muro, quello gli cade addosso.","Chi taglia la pianta, quella si vendica colla sua mina.","L’edera è di lunga vita.","Al traditore la morte è vita, perchè, se usa gii altri, non gli è creduto.","Quando fortuna viene, prendil’a man salva, dinanzi dico, perchè dirieto è calva.","Constanzia: non chi comincia, ma quel che persevera.","Impedimento non mi piega.","Ogni impedimento è distrutto dal rigore.","Non si volta chi a stella è fisso."],"cs":["Ničeho se není třeba bát víc než špatné pověsti.","Tato špatná pověst se rodí z neřestí.","Přirovnání. Rozbitou nádobu z nepálené hlíny lze přetvořit, ale vypálenou ne.","Slib se rodí, když umírá naděje.","Ne vždy je dobré to, co je krásné… A v tomto omylu jsou krasořečníci bez jakékoli myšlenky.","Kdo chce být bohatý za den, bude za rok oběšen.","Vzpomínka na prokázaná dobrodiní je vedle nevděku křehká.","Kárej přítele v soukromí a chval ho veřejně.","Kdo se bojí nebezpečí, nezahyne jimi.","Takové je zlo, které mi neškodí, jako dobro, které mi neprospívá.","Kdo uráží jiné, nezabezpečí sebe.","Nebuď lhářem o minulém.","Hloupost je štítem lži, jako nestoudnost štítem chudoby.","Kde je svoboda, není pravidla.","Je jedna věc, které si tím méně vážíme, čím víc jí potřebujeme: je to rada.","Špatně děláš, chválíš-li, a hůř, káráš-li věc, když jí dobře nerozumíš.","Slova ti mrznou v ústech, a na Etně bys dělal rosol.","Hrozby jsou jen zbraní ohroženého.","Žádej o radu toho, kdo se dobře napravuje.","Spravedlnost vyžaduje moc, rozum a vůli a podobá se králi včel.","Kdo netrestá zlo, přikazuje, aby se dělo.","Kdo bere hada za ocas, toho pak uštkne.","Kdo kope jámu, tomu se zřítí na hlavu.","Kdo nekrotí rozkoš, ať se druží s hovady.","Nelze mít větší ani menší vládu, než je vláda nad sebou samým.","Kdo málo přemýšlí, mnoho chybuje.","Snáze se odporuje na začátku než na konci.","Žádná rada není poctivější než ta, kterou si dávají lodi, jež jsou v nebezpečí.","Ať čeká škodu ten, kdo se v radě řídí mladíkem.","Rosteš v pověsti jako chléb v rukou dětí.","Nemůže být krása i užitečnost? Jak se ukazuje na pevnostech a na lidech.","Kdo se nebojí, je často plný škod a často lituje.","Kdybys měl tělo podle své ctnosti, nevešel by ses na tento svět.","Kam vstoupí štěstí, tam Závist položí obležení a bojuje s ním; a odkud odchází, tam zanechává bolest a lítost.","Krásy a ošklivosti se zdají jedna vedle druhé mocnější.","Zřídka upadne, kdo dobře kráčí.","Ó lidská bído, kolika věcem se pro peníze stáváš otrokem!","Nejvyšší škoda je, když mínění předbíhá dílo.","Říkat dobře o ničemném je totéž jako říkat zle o dobrém.","Pravda zde způsobuje, že lež trápí lživé jazyky.","Kdo si neváží života, nezaslouží si ho.","Krásná věc smrtelná pomíjí a netrvá.","Námaha prchá se slávou v náručí, téměř skrytá.","Zlato v prutech se tříbí v ohni.","Člunek: budu se pohybovat tak dlouho, až bude tkanina hotova.","Každá křivda se napraví.","Z lehké věci se rodí velká zkáza.","Ve zkoušce se pozná ryzí zlato.","Jaká bude forma, takový bude odlitek.","Kdo podkopává zeď, na toho spadne.","Kdo kácí strom, tomu se pomstí svým pádem.","Břečťan je dlouhověký.","Zrádci je smrt životem, protože i kdyby jednal s jinými [poctivě], nikdo mu nevěří.","Když štěstí přijde, chop je pevnou rukou, zepředu, pravím, neboť vzadu je lysé.","Stálost: ne ten, kdo začíná, ale ten, kdo vytrvá.","Překážka mě neohne.","Každou překážku zničí neústupnost.","Neobrací se, kdo je upřen ke hvězdě."],"ref":{"s":"Ash.II","l":22,"st":"v","z":true,"raw":"Ash. II. 22 v"},"ca":[]},{"id":"s403","o":"Pensieri sulla morale","c":"LIII","str":214,"ni":"la verità","nc":"Pravda","it":["Il foco distrugge la bugia, cioè il sofistico, e rende la verità, scacciando le tenebre.","Il foco è da essere messo per consumatore d’ogni sofistico e scopritore e dimostratore di verità, perchè lui è luce, scacciatore delle tenebre, occultatrici d’ogni essenzia.","Il foco distrugge ogni sofistico, cioè lo inganno, e sol mantiene la verità, cioè l’oro.","La verità al fine non si cela: non val simulazione.","Simulazione è frustrata, avanti a tanto giudice.","La bugìa mette maschera.","Nulla occulta sotto il sole.","Il foco è messo per la verità, perchè distrugge ogni sofistico e bugìa, e la maschera per la falsità e bugìa, occultatrici del vero."],"cs":["Oheň ničí lež, totiž falšované, a vrací pravdu, zahánějíc tmu.","Oheň je třeba zobrazit jako ničitele všeho falšovaného a odhalovatele a ukazatele pravdy, protože je světlem, zahánějícím tmu, která skrývá každou podstatu.","Oheň ničí všechno falšované, totiž klam, a zachovává jen pravdu, totiž zlato.","Pravda se nakonec neskryje: přetvářka neplatí.","Přetvářka je zmařena před tak velikým soudcem.","Lež si nasazuje masku.","Nic skrytého pod sluncem.","Oheň je zobrazen místo pravdy, protože ničí všechno falšované a lež, a maska místo falešnosti a lži, které skrývají pravdu."],"ref":{"s":"Ash.II","l":22,"st":"v","z":true,"raw":"Ash. II. 22 v"},"ca":[]},{"id":"s404","o":"Pensieri sulla morale","c":"LIV","str":215,"ni":"il ben fare","nc":"Dobré konání","it":["Prima privato di moto che stanco di giovare, mancherà prima il moto che ’l giovamento.","Prima morte che stanchezza. Non mi sazio di servire. Non mi stanco nel giovare.","Tutte le opere non son per istancarmi.","È motto da carnovale. Sine lassitudine.","Mani, nelle quali fioccan ducati e pietre preziose, queste mai si stancano di servire, ma tal servizio è sol per sua utilità e non è al nostro proposito. Natura così mi dispone, naturalmente."],"cs":["Spíše zbaven pohybu než unaven prospíváním: dříve dojde pohyb než prospívání.","Spíše smrt než únava. Nenasytím se sloužením. Neunavím se prospíváním.","Všechna díla mě neunaví.","Je to heslo pro masopust. Sine lassitudine.","Ruce, do nichž se sypou dukáty a drahé kameny, ty se nikdy neunaví sloužit, ale taková služba je jen pro jejich užitek a nepatří k našemu záměru. Příroda mě tak uzpůsobuje, přirozeně."],"ref":{"s":"Ash.II","l":22,"st":"v","z":true,"raw":"Ash. II. 22 v"},"ca":[]},{"id":"s405","o":"Pensieri sulla morale","c":"LV","str":216,"ni":"la ingratitudine","nc":"Nevděk","it":["Sia fatto in mano alla ingratitudine.","Il legno notrica il foco che lo consuma.","Quando apparisce il sole che scaccia le tenebre in comune, tu spegni il lume, che te le scacciava in particolare, a tua necessità e commodità."],"cs":["Ať je to dáno do ruky Nevděku.","Dřevo živí oheň, který ho stravuje.","Když se objeví slunce, které zahání tmu všem společně, zhasneš světlo, které ti ji zahánělo zvlášť, pro tvou potřebu a pohodlí."],"ref":{"s":"Ash.II","l":22,"st":"v","z":true,"raw":"Ash. II. 22 v"},"ca":[]},{"id":"s406","o":"Pensieri sulla morale","c":"LVI","str":216,"ni":"la invidia","nc":"Závist","it":["La ’nvidia effonde colla fitta infamia cioè col detrarre, la qual cosa spaventa la virtù.","Questa Invidia si figura colle fiche verso il cielo, perchè, se potesse, userebbe le sue forze contro a Dio. Fassi colla maschera in volto di bella dimostrazione. Fassi ch’ella è ferita nella vista da palma e olivo, fassi ferito l’orecchio di lauro e mirto, a significare che vittoria o verità l’offendono. Fassile uscire molte folgori a significare il suo mal dire. Fassi magra e secca, perchè è sempre in continuo struggimento, fassile il core roso da un serpente enfiante. Fassile un turcasso, e fe treccie lingue, perchè spesso con quella offende. Fassile una pelle dì liopardo, perchè quello per invidia ammazza il leone, con inganno. Fassile un vaso in mano pien di fiori, e sia quello pien di scorpioni e rospi o altri veneni. Fassile cavalcare la Morte, perchè la Invidia, non morendo, mai languisce: a signoreggiare; fassile la briglia carica di diverse armi, perchè tutti strumenti della morte.","Subito che nasce la virtù quella partorisce contra sè la Invidia, e prima fia il corpo sanza l’ombra, che la virtù sanza la Invidia."],"cs":["Závist zraňuje vylhanou hanou, totiž pomluvou, a to děsí ctnost.","Tato Závist se zobrazuje, jak ukazuje fík k nebi, protože kdyby mohla, použila by svých sil proti Bohu. Dělá se s maskou krásného vzezření na tváři. Dělá se tak, že je raněna na zraku palmou a olivou, dělá se raněná na uchu vavřínem a myrtou, na znamení, že vítězství a pravda ji zraňují. Dělá se, jak z ní vychází mnoho blesků, na znamení jejího zlořečení. Dělá se hubená a vyschlá, protože je ustavičně v trápení, dělá se jí srdce hlodané nadmutým hadem. Dělá se jí toulec a šípy jsou jazyky, protože jimi často uráží. Dělá se jí kůže levhartí, protože levhart ze závisti lstí zabíjí lva. Dělá se jí do ruky nádoba plná květů, a ta ať je plná štírů a ropuch či jiných jedů. Dělá se, jak jede na Smrti, protože Závist, neumírajíc, nikdy nepřestává panovat; dělá se jí uzda obtížená rozličnými zbraněmi, protože to jsou všechno nástroje smrti.","Jakmile se ctnost zrodí, plodí proti sobě Závist; a dříve bude tělo bez stínu než ctnost bez Závisti."],"ref":{"s":"Ash.II","l":22,"st":"v","z":true,"raw":"Ash. II. 22 v"},"ca":[]},{"id":"s407","o":"Pensieri sulla morale","c":"LVII","str":217,"ni":"la fama","nc":"Sláva","it":["La Fama sola si leva al cielo, perchè le cose virtudiose sono amiche a Dio; la Infamia sotto sopra figurare si debbe, perchè tutte sue operazioni son contrarie a Dio, e inverso l’inferi si dirizzano.","Alla Fama si de’ dipignere tutta la persona piena di lingue, in iscambio di penne, e ’n forma d’uccello."],"cs":["Sláva jediná se zvedá k nebi, protože ctnostné věci jsou Bohu přátelské; Hanbu je třeba zobrazovat vzhůru nohama, protože všechna její konání jsou Bohu protivná a směřují k peklu.","Slávě se má namalovat celá postava plná jazyků místo per, a v podobě ptáka."],"ref":{"s":"Ash.II","l":22,"st":"v","z":false,"raw":"Ash. II. 22 v"},"ca":[]},{"id":"s408","o":"Pensieri sulla morale","c":"LVIII","str":217,"ni":"piacere e dolore","nc":"Rozkoš a strast","it":["Questo si è il Piacere insieme col Dispiacere e figuransi binati, perchè mai l’uno è spiccato dall’altro; fannosi colle schiene voltate, perchè son contrari l’uno all’altro; fannosi fondati sopra un medesimo corpo, perchè hanno un medesimo fondamento: imperocchè il fondamento del Piacere si è la fatica col Dispiacere, il fondamento del Dispiacere si sono i vari e lascivi piaceri. E però qui si figura colla canna nella man destra, ch’è vana e sanza forza, e le punture fatte con quella son venenose. Mettonsi (le canne) in Toscana al sostegno de’ letti, a significare che quivi si fanno i vani sogni, e quivi si consuma gran parte della vita, quivi si gitta di molto utile tempo, cioè quel della mattina, chè la mente è sobria e riposata, e così il corpo atto a ripigliare nove fatiche; ancora lì si pigliano molti vani piaceri e colla mente, imaginando cose impossibili a sè, e col corpo, pigliando que’ piaceri, che spesso son cagione di mancamento di vita; sicchè per questo si tiene la canna per tali fondamenti."],"cs":["Toto je Rozkoš spolu se Strastí, a zobrazují se jako dvojčata, protože nikdy není jedna oddělena od druhé; dělají se otočené zády, protože jsou si navzájem protivné; dělají se založené na jednom a témž těle, protože mají jeden a týž základ: neboť základem Rozkoše je námaha se Strastí a základem Strasti jsou rozličné a chlípné rozkoše. A proto se zde zobrazuje s rákosem v pravé ruce, který je dutý a bez síly, a rány jím způsobené jsou jedovaté. V Toskánsku se (rákosy) dávají jako podpěra loží, na znamení, že tam se sní marné sny a tam se stráví velká část života, tam se zahodí mnoho užitečného času, totiž ranního, kdy je mysl střízlivá a odpočatá, a tak i tělo schopné pustit se do nových prací; také se tam užívá mnoha marných rozkoší, jak myslí, když si představuje věci pro sebe nemožné, tak tělem, když užívá těch rozkoší, které bývají často příčinou ztráty života; a proto se rákos drží jako takový základ."],"ref":{"s":"R","l":1196,"st":"","z":false,"raw":"R. 1196"},"ca":[],"rr":"S. K. M. II.2 24 a"},{"id":"s409","o":"Pensieri sulla morale","c":"LIX","str":218,"ni":"inferiorità fisiologica dell’uomo","nc":"Fyziologická méněcennost člověka","it":["Ho trovato nella composizione del corpo umano, che, come in tutte le composizioni delli animali, esso è di più ottusi e grossi sentimenti: così è composto di strumento manco ingegnoso e di lochi manco capaci a ricevere la virtù de’ sensi.","Ho veduto nella spezie leonina il senso dell’odorato avere parte della sustanzia del celabro, e discendere le narici, capace riccettaculo contro al senso dello odorato, il quale entra infra gran numero di saccoli cartilaginosi, con assai vie, contro all’avvenimento del predetto celabro. Li occhi della spezie leonina hanno gran parte della lor testa per lor ricettacolo, e li nervi ottici, immediate congiugnersi col celabro; il che alli omini si vede in contrario, perchè le casse delli occhi sono una piccola parte del capo, e li nervi ottici sono sottili e lunghi, e deboli, e, per debole operazione, si vede poco il dì e peggio la notte, e li predetti animali vedono (più) in nella notte che ’l giorno; e ’l segno se ne vede, perche predano di notte e dormono il giorno, come fanno ancora li uccelli notturni."],"cs":["Shledal jsem ve stavbě lidského těla, že ze všech staveb živočichů má nejtupější a nejhrubší smysly: je totiž složeno z méně důmyslného nástroje a z míst méně schopných přijímat sílu smyslů.","Viděl jsem u lvího rodu, že smysl čichu má podíl na hmotě mozku a že nozdry sestupují jako prostorná schránka pro smysl čichu, který vstupuje do velkého počtu chrupavčitých váčků s mnoha cestami vstříc řečenému mozku. Oči lvího rodu mají za schránku velkou část své hlavy a zrakové nervy se bezprostředně spojují s mozkem; u lidí je vidět opak, protože očnice jsou malou částí hlavy a zrakové nervy jsou tenké, dlouhé a slabé, a pro slabou činnost se ve dne vidí málo a v noci hůř, kdežto řečená zvířata vidí v noci (víc) než ve dne; a znamení toho je vidět v tom, že loví v noci a ve dne spí, jako to dělají i noční ptáci."],"ref":{"s":"R","l":827,"st":"","z":false,"raw":"R. 827"},"ca":[],"rr":"W. An. IV. 173 a"},{"id":"s410","o":"Pensieri sulla morale","c":"LX","str":219,"ni":"sua inferiorità etica","nc":"Jeho mravní méněcennost","it":["Come tu hai descritto il Re delli animali — ma io meglio direi dicendo Re delle bestie, essendo tu la maggiore, — perchè non li hai uccisi, acciò che possino poi darti li lor figlioli in benefizio della tua gola, colla quale tu hai tentato farti sepoltura di tutti li animali?","E più oltre direi se ’l dire il vero mi fusse integramente lecito. Ma non usciamo delle cose umane, dicendo una somma scellerataggine, la qual non accade nelli animali terrestri: imperocchè in quelli non si trovano animali, che mangino della loro specie, se non per mancamento di celabro, (in poche infra loro e de’ madri, come infra li omini, benchè non sieno in tanto numero), e questo non accade se non nelli animali rapaci, come nella spezie leonina, e pardi, pantere, cervieri, gatti e simili, li quali alcuna volta si mangiano i figlioli....","Ma tu, oltre alli figlioli, ti mangi il padre, madre, fratello e amici e non ti basta questi, che tu vai a caccia per le altrui isole, pigliando li altri omini e questi, mezzo nudi li testiculi, fai ingrassare e te li cacci giù per la gola. Or non produce la natura tanti semplici, che tu ti possa saziare? e, se non ti contenti de’ semplici, non puoi tu con le mistion di quelli fare infiniti composti, come scrisse il Platina e li altri autori di gola?"],"cs":["Když jsi popsal Krále zvířat – ale já bych řekl lépe, kdybych řekl Krále hovad, neboť ty jsi největší z nich –, proč jsi je nezabil, aby ti potom mohli dávat svá mláďata ke prospěchu tvého jícnu, jímž ses pokusil učinit sebe hrobem všech zvířat?","A řekl bych ještě víc, kdyby mi bylo zcela dovoleno říkat pravdu. Ale nevyjděme z věcí lidských a řekněme jednu nejvyšší ohavnost, která se nestává u suchozemských zvířat: neboť mezi nimi se nenacházejí zvířata, která by žrala svůj vlastní druh, leda z nedostatku rozumu (u několika z nich, a to matky, jako mezi lidmi, ač ne v takovém počtu); a to se nestává jinde než u dravých zvířat, jako u lvího rodu, u pardů, panter, rysů, koček a podobných, které někdy žerou svá mláďata…","Ale ty kromě dětí jíš otce, matku, bratra a přátele, a to ti nestačí, takže jdeš na lov na cizí ostrovy, chytáš jiné lidi, a ty, s uřezanými varlaty, dáváš vykrmit a cpeš si je do chřtánu. Copak příroda nerodí tolik prostých bylin, aby ses mohl nasytit? A nestačí-li ti prosté, nemůžeš z jejich směsí dělat nekonečné složeniny, jak psal Platina a jiní spisovatelé o mlsání?"],"ref":{"s":"R","l":844,"st":"","z":false,"raw":"R. 844"},"ca":[],"rr":"W. An. III. 241 a"},{"id":"s411","o":"Pensieri sulla morale","c":"LXI","str":221,"ni":"classificazione di leonardo","nc":"Leonardova klasifikace","it":["UOMO — la descrizione dell’omo, nella qual si contengono quelli, che son quasi di simile spezie, come babbuino, scimmia e simIII, che son molti."],"cs":["ČLOVĚK – popis člověka, v němž jsou obsaženi ti, kdo jsou téměř podobného druhu, jako pavián, opice a podobní, kterých je mnoho."],"ref":{"s":"R","l":816,"st":"","z":false,"raw":"R. 816"},"ca":[],"rr":"W. An. IV. 173 b"},{"id":"s412","o":"Pensieri sulla morale","c":"LXII","str":221,"ni":"l’uomo come animale","nc":"Člověk jako živočich","it":["Dello andare dell’omo. L’andare dell’omo è sempre a uso dell’universale andare delli animali di quattro piedi, imperocchè siccome essi movono i loro piedi in croce a uso del trotto del cavallo, così l’omo in croce si move le sue quattro membra, cioè se caccia innanzi il piè destro, per camminare, egli caccia innanzi con quello il braccio sinistro, e sempre così sèguita."],"cs":["O chůzi člověka. Chůze člověka je vždy podle obecné chůze čtyřnohých zvířat; neboť jako ona pohybují nohama křížem po způsobu klusu koně, tak i člověk pohybuje křížem svými čtyřmi údy, totiž vykročí-li při chůzi vpřed pravou nohou, posune s ní vpřed levou paži, a tak to jde stále."],"ref":{"s":"C.A","l":292,"st":"r","z":false,"raw":"C. A. 292 r"},"ca":[1590]},{"id":"s413","o":"Pensieri sulla morale","c":"LXIII","str":221,"ni":"dagli animali all’uomo vi è un lento trapasso","nc":"Od zvířat k člověku vede pozvolný přechod","it":["Fa uno particulare trattato nella descrizione de’ movimenti delli animali di quattro piedi, infra li quali è l’omo, che ancora lui nella infanzia va con quattro piedi."],"cs":["Udělej zvláštní pojednání o popisu pohybů čtyřnohých zvířat, mezi něž patří člověk, který také v dětství chodí po čtyřech."],"ref":{"s":"E","l":16,"st":"r","z":false,"raw":"E. 16 r"},"ca":[]},{"id":"s414","o":"Pensieri sulla morale","c":"LXIV","str":221,"ni":"l’evoluzione della moda","nc":"Vývoj módy","it":["Alli miei giorni mi ricordo aver visto, nella mia puerizia, li omini e piccoli e grandi avere tutti li stremi de’ vestimenti frappati in tutte le parti sì da capo, come da piè e da lato; e ancora parve tanto bella invenzione, a quell’età, che frappavano ancora le dette frappe, e portavano li cappucci in simile modo e le scarpe e le creste frappate, che uscivano dalle principali cuciture delli vestimenti, di vari colori.","Di poi vidi le scarpe, berrette, scarselle, armi, — che si portano per offendere, — i collari de’ vestimenti, li stremi de’ giubboni da piedi, le code de’ vestimenti, e in effetto infino alle bocche, di chi volean parer belli, erano appuntate di lunghe e acute punte.","Nell’altra età cominciorno a crescere le maniche e eran talmente grandi, che ciascuna per se era maggiore della veste; poi cominciorno a alzare li vestimenti intorno al collo tanto, ch’alla fine copersono tutto il capo; poi cominciorno a spogliarlo in modo, che i panni non potevano essere sostenuti dalle spalle, perchè non vi si posavan sopra.","Poi cominciorno a slungare sì li vestimenti, che al continuo gli uomini avevano le braccia cariche di panni, per non li pestare co’ piedi; poi vennero in tanta stremità, che vestivano solamente fino a’ fianchi e alle gomita, e erano sì stretti, che da quelli pativano gran supplicio e molti ne crepavano di sotto; e li piedi sì stretti, che le dita d’essi si soprapponevano l' uno all’altro, e caricavansi di calli."],"cs":["Za svých dnů si pamatuji, že jsem v dětství viděl lidi malé i velké, jak mají všechny okraje oděvů vykrajované do cípů na všech stranách, nahoře i dole i po boku; a ještě se v onom věku zdál ten vynález tak krásný, že vykrajovali i ty cípy, a stejným způsobem nosili kápě a boty a vykrajované hřebínky rozličných barev, které vycházely z hlavních švů oděvů.","Potom jsem viděl boty, čepice, měšce, zbraně – které se nosí k útoku –, límce oděvů, dolní okraje kabátců, vlečky oděvů, a vskutku až po ústa těch, kdo chtěli vypadat krásně, opatřené dlouhými a ostrými špicemi.","V jiném věku začaly růst rukávy a byly tak veliké, že každý sám byl větší než šat; potom začali zvedat oděvy kolem krku tolik, až nakonec zakryly celou hlavu; potom ho začali obnažovat tak, že šaty nemohly být neseny rameny, protože na nich neležely.","Potom začali oděvy tak prodlužovat, že lidé měli ustavičně paže obtížené látkou, aby po ní nešlapali; potom došli do takové krajnosti, že se oblékali jen po boky a po lokty, a šaty byly tak těsné, že jimi trpěli velká muka a mnozí v nich praskali; a nohy tak sevřené, že se jim prsty překrývaly jeden přes druhý a pokrývaly se mozoly."],"ref":{"s":"Lu","l":541,"st":"","z":false,"raw":"Lu. 541"},"ca":[]},{"id":"s415","o":"Pensieri sulla morale","c":"LXV","str":223,"ni":"un discepolo di leonardo: giacomo","nc":"Leonardův žák Giacomo","it":["A dì 23 d’aprile 1490 cominciai questo libro, e ricominciai il cavallo.","Jacomo venne a stare con meco il dì della Maddalena nel 1490, d’età d’anni 10.","Il secondo dì li feci tagliare due camice, uno paro di calze e un giubbone, e, quando mi posi i dinari a lato per pagare dette cose, lui mi rubò detti dinari della scarsella, e mai fu possibile farlielo confessare, ben ch’io n’avessi vera certezza. — Lire 4.","Il dì seguente andai a cena con Jacomo Andrea, e detto Jacomo cenò per due e fece male per quattro, imperocchè ruppe tre ampolle, versò il vino e, dopo questo, venne a cena dove me.","Item, a dì 7 di settembre rubò uno graffio di valuta di 12 soldi a Marco, che stava co’ meco, il quale era d’argento, e tolseglielo dal suo studiolo e, poi che detto Marco n’ebbi assai cerco, lo trovò nascosto in nella cassa di detto Jacomo — Lire 1 s. di L. 2.","Item, a dì 26 di gennaro seguente, essendo io in casa di Messer Galeazzo da Sanseverino a ’rdinare la festa della sua giostra, e spogliandosi certi staffieri, per provarsi alcune veste d’omini salvatichi, ch’a detta festa accadeano, Jacomo s’accostò alla scarsella d’uno di loro, la qual era in sul letto con altri panni, e tolse quelli dinari, che dentro vi trovò. — Lire 2 s. di L. 4.","Item, essendomi da maestro Agostino da Pavia, donato in detta casa una pelle turchesca da fare uno paro di stivaletti, esso Jacomo, infra uno mese, me la rubò e vendella a un acconciatore di scarpe per 20 soldi de’ qua’ dinari, secondo che lui propio mi confessò, ne comprò anici, confetti. Lire 2.","Item, ancora a dì 2 d’aprile, lasciando Gian Antonio uno graffio d’argento sopra uno suo disegno, esso Jacomo glielo rubò, il quale era di valuta di soldi 24. Lire 1 s. di L. 4.","Il primo anno un mantello: Lire 2; camice 6: Lire 4; 3 giubboni: Lire 6; 4 para di calze: Lire 7 s. di L. 8; vestito foderato: L. 5; 24 para di scarpe: L. 6 s. d. L. 5;una berretta L. 1; in cinti, stringhe,... L. 1."],"cs":["Dne 23. dubna 1490 jsem začal tuto knihu a znovu jsem začal koně.","Jacomo ke mně přišel bydlet na den svaté Magdalény roku 1490, ve věku 10 let.","Druhý den jsem mu dal ušít dvě košile, jedny punčochy a kabátec, a když jsem si dal peníze stranou, abych ty věci zaplatil, ukradl mi ty peníze z měšce, a nikdy nebylo možné přimět ho, aby se přiznal, ačkoli jsem o tom měl pravou jistotu. – Lire 4.","Následujícího dne jsem šel na večeři s Jacomem Andreou a řečený Jacomo jedl za dva a natropil škody za čtyři, neboť rozbil tři láhve, rozlil víno a potom přišel k večeři tam, kde jsem byl já.","Item, 7. září ukradl Marcovi, který bydlel u mne, rydlo v ceně 12 soldů, které bylo stříbrné, a vzal mu je z jeho pracovny; a když je řečený Marco dlouho hledal, našel je ukryté v truhle řečeného Jacoma. – Lire 1 s. di L. 2.","Item, 26. ledna následujícího, když jsem byl v domě pana Galeazza da Sanseverino a chystal slavnost jeho klání a jistí podkoní se svlékali, aby si zkusili nějaké šaty divých mužů, které k té slavnosti patřily, přiblížil se Jacomo k měšci jednoho z nich, který ležel na posteli s jinými šaty, a vzal ty peníze, které v něm našel. – Lire 2 s. di L. 4.","Item, když mi v témž domě mistr Agostino da Pavia daroval tureckou kůži na jedny vysoké boty, řečený Jacomo mi ji během měsíce ukradl a prodal ji ševci za 20 soldů, a za ty peníze, jak se mi sám přiznal, koupil anýz a cukrovinky. Lire 2.","Item, ještě 2. dubna, když Gian Antonio nechal stříbrné rydlo na jedné své kresbě, řečený Jacomo mu je ukradl; mělo cenu 24 soldů. Lire 1 s. di L. 4.","První rok plášť: Lire 2; košile 6: Lire 4; 3 kabátce: Lire 6; 4 páry punčoch: Lire 7 s. di L. 8; šat s podšívkou: L. 5; 24 párů bot: L. 6 s. d. L. 5; jedna čepice L. 1; za pásky, tkanice… L. 1."],"ref":{"s":"C","l":15,"st":"r","z":false,"raw":"C. 15 r"},"ca":[]},{"id":"s416","o":"Pensieri sulla morale","c":"LXVI","str":225,"ni":"leonardo analizzatore dell’uomo","nc":"Leonardo jako pozorovatel člověka","it":["Tutti i mali, che sono e che furono, essendo messi in opera da costui, non saddisfarebbono al desiderio del suo iniquo animo. I’ non potrei, con lunghezza di tempo, descrivervi la natura di costui."],"cs":["Všechna zla, která jsou a která byla, kdyby je tento člověk uvedl v čin, by neukojila touhu jeho nepravé duše. Nemohl bych vám ani za dlouhý čas vylíčit povahu tohoto člověka."],"ref":{"s":"R","l":1358,"st":"","z":true,"raw":"R. 1358"},"ca":[],"rr":"W. An. III. 241 a"},{"id":"s417","o":"Pensieri sulla morale","c":"LXVII","str":225,"ni":"frammento di lettera a giuliano de’ medici","nc":"Zlomek dopisu Giulianu de’ Medici","it":["Tanto mi son rallegrato, Illustrissimo mio Signore, del desiderato acquisto di vostra sanità, che quasi il male mio da me s’è fuggito. Ma assai mi rincresce il non avere io potuto satisfare alli desidèri di Vostra Eccellenza, mediante la malignità di cotesto ingannatore tedesco; per il quale, non ho lasciato indirieto cosa alcuna, colla quale io abbia creduto fargli piacere. E secondariamente invitarlo ad abitare e vivere con meco, per la qual cosa io vedrei al continuo l’opera, che lui facesse e con facilità ricorreggerei li errori, e oltre di questo imparerebbe la lingua italiana, mediante la quale lui con facilità potrebbe parlare sanza interprete; e li sua dinari li furon sempre dati innanzi al tempo. Di poi, la richiesta di costui fu di avere li modelli finiti di legname, com’ellino aveano a essere di ferro, e’ quali volea portare nel suo paese. La qual cosa io li negai dicendoli, di’ io li darei in disegno la larghezza, lunghezza e grossezza e figura di ciò, ch’olii avesse a fare; e così restammo mal volontieri.","La seconda cosa fu, che si fece un’altra bottega, e morse e strumenti, dove dormiva e quivi lavorava per altri; dipoi andava a desinare co’ Svizzeri della guardia, dove sta gente sfaccendata, della qual cosa lui tutti li vinceva. E ’l più delle volte se n’andavano due o tre di loro, colli scoppietti, ammazzavano uccelli per le anticaglie, e questo durava insino a sera.","E, se io mandavo Lorenzo a sollecitarli lavoro, lui si crucciava e diceva, che non volea tanti maestri sopra capo, e che il lavorar suo era per la guardaroba di Vostra Eccellenza. E passò due mesi, e così seguitava, e indi trovando Gian Niccolò della guardaroba, domandailo se ’l Tedesco avea finito l’opere del Magnifico, e lui mi disse non esser vero, ma che solamente li avea dato a nettar dua scoppietti. Di poi, facendolo io sollecitare, lui lasciò la bottega, e perdè assai tempo nel fare un’altra morsa e lime e altri strumenti a vite, e quivi lavorava mulinelli da torcere seta, li quali nascondeva, quando un de’ mia v’entrava, e con mille bestemmie e rimbrotti: in modo che nessun de’ mia voleva più entrare.","Al fine ho trovato, come questo maestro Giovanni delli Specchi e quello, che ha fatto il tutto per due cagioni: e la prima, perchè lui ha avuto a dire, che la venuta mia qui li ha tolto la conversazione di Vostra Signoria.... L’altra è che la stanza di quest’omini.... disse convenirsi a lui per lavorare li specchi, e di questo n’ha fatto dimostrazione, che, oltre al farmi costui nimico, li ha fatto vendere ogni suo e lasciare a lui la sua bottega, nella quale lavora con molti lavoranti assai specchi per mandare alle fiere."],"cs":["Tolik jsem se zaradoval, můj nejjasnější Pane, z žádoucího nabytí vašeho zdraví, že má vlastní nemoc ode mne téměř utekla. Ale velmi mě mrzí, že jsem nemohl vyhovět přáním Vaší Excelence kvůli zlomyslnosti toho německého podvodníka; kvůli němu jsem nezanedbal nic, čím jsem věřil, že mu udělám radost. A za druhé jsem ho pozval, aby bydlel a žil se mnou, čímž bych ustavičně viděl práci, kterou by dělal, a snadno bych opravoval chyby, a kromě toho by se naučil italský jazyk, s jehož pomocí by snadno mohl mluvit bez tlumočníka; a jeho peníze mu byly vždy dány předem. Potom tento člověk žádal, aby dostal hotové modely ze dřeva, tak jak měly být ze železa, a ty chtěl odnést do své země. To jsem mu odepřel a řekl mu, že mu dám na výkrese šířku, délku, tloušťku a tvar toho, co by měl dělat; a tak jsme zůstali v nevoli.","Druhá věc byla, že si zřídil jinou dílnu a svěráky a nástroje tam, kde spal, a tam pracoval pro jiné; potom chodil obědvat se Švýcary z gardy, kde jsou lidé bez zaměstnání, v čemž je všechny překonával. A nejčastěji odcházeli dva nebo tři z nich s ručnicemi a stříleli ptáky mezi starými zříceninami, a to trvalo až do večera.","A posílal-li jsem Lorenza, aby ho popohnal k práci, zlobil se a říkal, že nechce mít nad hlavou tolik mistrů a že jeho práce je pro šatnici Vaší Excelence. A uplynuly dva měsíce a tak to pokračovalo; a pak, když jsem potkal Gian Niccola ze šatnice, zeptal jsem se ho, zda Němec dokončil díla pro Vznešeného, a on mi řekl, že to není pravda, ale že mu dal jen vyčistit dvě ručnice. Potom, když jsem ho dal popohánět, opustil dílnu a ztratil mnoho času výrobou dalšího svěráku a pilníků a jiných nástrojů se šrouby, a tam dělal navíjedla ke kroucení hedvábí, která skrýval, když tam vešel někdo z mých, a s tisícerým klením a láním: takže nikdo z mých tam už nechtěl vstoupit.","Nakonec jsem zjistil, že tento mistr Giovanni od zrcadel je ten, kdo to všechno způsobil, a to ze dvou příčin: první, protože musel říkat, že můj příchod sem mu vzal společnost Vaší Milosti…; druhá je, že místnost těchto lidí… prý patří jemu, aby v ní dělal zrcadla, a to dokázal tím, že kromě toho, že mi z toho člověka udělal nepřítele, přiměl ho prodat všechno, co měl, a nechat mu svou dílnu, v níž s mnoha dělníky dělá velké množství zrcadel, aby je posílal na trhy."],"ref":{"s":"R","l":1358,"st":"","z":true,"raw":"R. 1358"},"ca":[],"rr":"W. An. III. 241 a"},{"id":"s418","o":"Pensieri sulla morale","c":"LXVIII","str":227,"ni":"i miseri studiosi con che speranza e’ possono aspettare premio di lor virtù?","nc":"Naděje ubohých učenců","it":["E in questo caso io so, che io ne acquisterò non pochi nemici, conciò sia che nessun crederà, ch’io possa dire di lui; perchè pochi son quelli a chi i sua vizi dispiacciano, anzi solamente a quegli uomini li dispiacciono, che son di natura contrari a tali vizi; e molti odiano li padri, e guastan le amicizie de’ reprensori de1 sua vizi, e non vogliono esempli contrari a essi, nè nessuno uman consiglio.","E, se alcuno se ne trova virtuoso e bono, non lo scacciate da voi, fategli onore, acciò che non abbia a fuggirsi da voi e ridursi nelli eremi o spelonche o altri lochi soletari, per fuggirsi dalle vostre insidie; e, se alcun di questi tali si trova, fateli onore, perchè questi sono li vostri Iddii terrestri, questi meritan da voi le statue e li simulacri....","Ma ben vi ricordo, che li lor simulacri non sien da voi mangiati, come ancora in alcuna regione dell’India, chè quando li simulacri operano alcuno miraculo, secondo loro, li sacerdoti li tagliano in pezzi (essendo di legno) e ne danno a tutti quelli del paese — non sanza premio. — E ciascun raspa sottilmente la sua parte, e mette sopra la prima vivanda che mangiano, e così tengono per fede aversi mangiato il suo Santo, e credono che lui li guardi poi da tutti li pericoli.","Che ti pare omo qui della tua specie? sei tu così savio come tu ti tieni? son queste cose da esser fatte da omini?"],"cs":["A v tomto případě vím, že si tím získám nemálo nepřátel, protože nikdo nebude věřit, že bych mohl mluvit o něm; neboť málo je těch, jimž by se jejich neřesti nelíbily, ba nelíbí se jen těm lidem, kteří jsou svou povahou takovým neřestem protivní; a mnozí nenávidí otce a kazí si přátelství s těmi, kdo kárají jejich neřesti, a nechtějí příklady jim opačné ani žádnou lidskou radu.","A najde-li se mezi nimi někdo ctnostný a dobrý, nevyhánějte ho od sebe, prokazujte mu čest, aby nemusel před vámi prchat a uchylovat se do pouští nebo jeskyní či jiných osamělých míst, aby unikl vašim úkladům; a najde-li se někdo takový, prokazujte mu čest, protože to jsou vaši pozemští Bohové, ti si od vás zaslouží sochy a obrazy…","Ale dobře vám připomínám, abyste jejich obrazy nejedli, jako se to děje v jistém kraji Indie, kde když obrazy učiní nějaký zázrak, podle jejich mínění, kněží je rozsekají na kusy (neboť jsou ze dřeva) a rozdají je všem v kraji – ne bez odměny. – A každý jemně oškrábe svůj díl a nasype ho na první jídlo, které jí, a tak pevně věří, že snědl svého Světce, a věří, že ho potom chrání přede všemi nebezpečími.","Co se ti zde zdá, člověče, o tvém druhu? Jsi tak moudrý, za jakého se pokládáš? Jsou to věci, které mají dělat lidé?"],"ref":null,"ca":[]},{"id":"s419","o":"Pensieri sulla morale","c":"LXIX","str":229,"ni":"dialogo fra il cervello e lo spirito, che in esso abitava","nc":"Rozhovor mezi mozkem a duchem, který v něm přebýval","it":["Il quale spirito ritrova il cerebro, donde partito s’era; con alta voce, con tali parole mosse:","— O felice, o avventurato spirito, donde partisti! io ho questo uomo, a male mio grado, ben conosciuto. Questo è riccetto di villania, questo è proprio ammunizione di somma ingratitudine, in compagnia di tutti i vizi.","Ma che vo io con parole indarno affaticandomi? La somma de’ peccati solo in lui trovati sono. E, se alcuno infra loro si trova, che alcuna bontà possegga, non altrimenti, come che me, dalli altri uomini trattati sono; e in effetto io ho questa conclusione, ch’è male s’elli sono nimici, e peggio s’elli son amici."],"cs":["Tento duch znovu nalezne mozek, odkud byl odešel; mocným hlasem pronesl tato slova:","– Ó šťastný, ó blažený duchu, odkud jsi odešel! Poznal jsem tohoto člověka dobře, ke své veliké nelibosti. Je to útulek sprostoty, je to vpravdě zásobárna nejvyššího nevděku ve společnosti všech neřestí.","Ale proč se marně namáhám slovy? Úhrn hříchů se nachází jen v něm. A najde-li se mezi nimi někdo, kdo má nějakou dobrotu, není s nimi od ostatních lidí zacházeno jinak než se mnou; a vskutku docházím k tomuto závěru, že je zle, jsou-li nepřáteli, a hůř, jsou-li přáteli."],"ref":{"s":"R","l":1355,"st":"","z":false,"raw":"R 1355"},"ca":[],"rr":"W. XXXI"},{"id":"s420","o":"Pensieri sulla morale","c":"LXX","str":229,"ni":"frammento di lettera","nc":"Zlomek dopisu","it":["Io ho uno, che, per aversi di me promesso cose assai men che debite, essendo rimasto ingannato del suo presuntuoso desiderio, ha tentato di tormi tutti li amici; e perchè li ha trovati savi e non leggeri al suo volere, mi ha minacciato, che trovate le annunziazioni,che mi torrà i benefattori; onde io ho di questo informato Vostra Signoria, acciò che, volendo questi seminare li usati scandali, non trovi terreno atto a seminare i pensieri e li atti della sua mala natura. - Che, tentando lui fare di Vostra Signoria strumento della sua iniqua e malvagia natura, rimanga ingannato di suo desiderio."],"cs":["Mám tu jednoho, který, protože si ode mne sliboval věci zdaleka ne náležité a zůstal zklamán ve své opovážlivé touze, pokusil se mi vzít všechny přátele; a protože je shledal moudrými a nepovolnými jeho vůli, vyhrožoval mi, že vymyslí donášky a vezme mi mé dobrodince; proto jsem o tom zpravil Vaši Milost, aby tento člověk, chtěl-li by rozsévat své obvyklé pohoršení, nenašel půdu vhodnou k zasetí myšlenek a činů své zlé povahy. – Aby, pokusí-li se učinit z Vaší Milosti nástroj své nepravé a zlovolné povahy, zůstal zklamán ve své touze."],"ref":{"s":"C.A","l":380,"st":"r","z":false,"raw":"C. A. 380 r"},"ca":[2110,2112]},{"id":"s421","o":"Difesa della pittura","c":"I","str":231,"ni":"proemio","nc":"Předmluva","it":["Con debita lamentazione si dole la Pittura, per essere lei scacciata dal numero delle arti liberali, conciossiachè essa sia vera figliola della natura e operata da più degno senso.","Ond’è a torto, o scrittori, l’avete lasciata fuori del numero di dette arti liberali, conciossiachè questa, non che alle opere di natura, ma ad infinite attende, che la natura mai le creò."],"cs":["S náležitým nářkem si stěžuje Malířství, že bylo vyhnáno z počtu svobodných umění, ačkoli je pravou dcerou přírody a vykonává se nejvznešenějším smyslem.","Proto jste je neprávem, ó spisovatelé, ponechali mimo počet řečených svobodných umění, neboť se věnuje nejen dílům přírody, ale nekonečně mnoha dílům, která příroda nikdy nestvořila."],"ref":{"s":"Lu","l":27,"st":"","z":false,"raw":"Lu. 27"},"ca":[]},{"id":"s422","o":"Difesa della pittura","c":"II","str":231,"ni":"perchè la pittura non è connumerata nelle scienze?","nc":"Proč malířství není počítáno mezi vědy?","it":["Perchè gli scrittori non hanno avuto notizia della scienza della Pittura, non hanno possuto descriverne i gradi e parti di quella, e lei medesima non si dimostra col sue fine nelle parole, essa è restata, mediante l’ignoranza, indietro alle predette scienze non mancando per questo di sua divinità.","E veramente non sanza cagione non l’hanno nobilitata, perchè per sè medesima si nobilita, sanza l’aiuto delle altrui lingue, non altrementi che si facciano l’eccellenti opere di natura. E se i pittori non hanno di lei descritto e ridottala in scienza, non è colpa della Pittura, e ella non è per questo meno nobile, poscia che pochi pittori fanno professione di lettere, perchè la lor vita non basta a intendere quella.","Per questo, avremo noi a dire, che le virtù dell’erbe, pietre, piante non sieno in essere, perchè li omini non le abbiano conosciute? — Certo no; ma diremo esse erbe restarsi in sè nobIII, sanza lo aiuto delle lingue o lettere umane."],"cs":["Protože spisovatelé neměli o vědě Malířství povědomí, nemohli popsat její stupně a části; a protože ona sama se svým cílem neprojevuje ve slovech, zůstala kvůli nevědomosti pozadu za řečenými vědami, aniž by tím pozbyla své božskosti.","A vpravdě ne bez příčiny ji nepovznesli, protože se povznáší sama sebou, bez pomoci cizích jazyků, ne jinak, než se povznášejí znamenitá díla přírody. A jestliže ji malíři nepopsali a neuvedli do podoby vědy, není to vina Malířství, a není proto méně vznešené, neboť málo malířů se zabývá písemnictvím, protože jejich život nestačí k tomu, aby je pochopili.","Máme snad proto říci, že síly bylin, kamenů a rostlin nejsou, protože je lidé nepoznali? – Jistě ne; ale řekneme, že ty byliny zůstávají samy v sobě vznešené bez pomoci lidských jazyků či písma."],"ref":{"s":"Lu","l":34,"st":"","z":false,"raw":"Lu. 34"},"ca":[]},{"id":"s423","o":"Difesa della pittura","c":"III","str":232,"ni":"la pittura è scienza universale","nc":"Malířství je všeobecná věda","it":["Quella scienza è più utile, della quale il suo frutto è più comunicabile, e così, per contrario, è meno utile ch’è meno comunicabile.","La Pittura ha il suo fine comunicabile a tutte le generazioni dell’universo, perche il suo fine e subbietto della virtù visiva, e non passa per l’orecchio al senso comune, col medesimo modo che vi passa per il vedere.","Dunque questa non ha bisogno d’interpreti di diverse lingue, come hanno le lettere, e sùbito ha saddisfatto all’umana spezie, non altrementi che si facciano le cose prodotte dalla natura. E non che alla spezie umana, ma agli altri animali: come si è manifestato in una pittura, imitata da uno padre di famiglia, alla quale facean carezze li piccioli figliuoli, che ancora erano nelle fasce, e similmente il cane e gatta della medesima casa, ch’era cosa meravigliosa a considerare tale spettacolo."],"cs":["Ta věda je užitečnější, jejíž plod je sdělitelnější, a tak naopak je méně užitečná ta, která je méně sdělitelná.","Malířství má svůj cíl sdělitelný všem pokolením vesmíru, protože jeho cíl je předmětem zrakové mohutnosti a nepřechází uchem do společného smyslu týmž způsobem, jakým tam přechází zrakem.","Nepotřebuje tedy tlumočníky z různých jazyků, jako je potřebuje písemnictví, a ihned uspokojí lidský rod, ne jinak, než to činí věci zrozené přírodou. A nejen lidský rod, ale i jiná zvířata: jak se ukázalo na obraze, na němž byl vypodobněn otec rodiny, jejž laskaly malé děti, které byly ještě v plenkách, a podobně pes a kočka z téhož domu, takže bylo obdivuhodné na takovou podívanou pohledět."],"ref":{"s":"Lu","l":7,"st":"","z":false,"raw":"Lu. 7"},"ca":[]},{"id":"s424","o":"Difesa della pittura","c":"IV","str":233,"ni":"la pittura non si può divulgare","nc":"Malířství nelze rozmnožovat","it":["Le scienze, che sono imitabIII, sono in tal modo, che con quelle il discepolo si fa eguale all’autore, e similmente fa il suo frutto. Queste sono utili allo imitatore, ma non sono di tanta eccellenza, quanto sono quelle, che non si possono lasciare per eredità, come l’altre sustanze.","Infra le quali la Pittura è la prima. Questa non s’insegna a chi natura no ’l concede, come fan le Matematiche, delle quali tanto ne piglia il discepolo, quanto il maestro gli ne legge; questa non si copia, come si fa le lettere, che tanto vale la copia, quanto l’origine; questa non s’impronta, come si fa la Scultura, della quale tal è l'impressa, qual è l’origine, in quanto alla virtù dell’opera; questa non fa infiniti figliuoli, come fa li libri stampati. Questa sola si resta nobile, questa sola onora il suo autore, o resta preziosa ed unica, e non partorisce mai figlioli eguali a sè. E tal singolarità la fa più eccellente che quelle, che per tutto sono pubblicate.","Or non vediamo noi li grandissimi re dell’Oriente andare velati e coperti, credendo diminuire la fama loro col pubblicare e divulgare le loro presenze? or non si vede le pitture, rappresentatrici delle divine Deità, esser al continuo tenute coperte con copriture di grandissimi prezzi? e quando si scoprano, prima si fa grandi solennità ecclesiastiche di vari canti con diversi suoni; e, nello scoprire, la gran moltitudine de’ popoli, che quivi concorrono, immediate si gettano a terra, quelle adorando e pregando, per cui tale pittura è figurata, dell’acquisto della perduta sanità e della eterna salute, non altrementi, che se tale Idea fusse lì presente in vita?","Questo non accade in nessun’altra scienza od altra umana opera. E se tu dirai, questa non esser virtù del pittore, ma propria virtù della cosa imitata; si risponderà, che in questo caso la mente de li omini po’ saddisfare, standosi nel letto, e non andare ne’ lochi faticosi e pericolosi, ne’ pellegrinaggi, come al continuo far si vede.","Ma, se pure tal pellegrinaggi al continuo sono in essere, chi li move, sanza necessità? Certo tu confesserai essere tale simulacro, il quale far non po’ tutte le scritture, che figurar potessino in effigie ed in virtù tal Idea. Dunque pare, ch’essa Idea ami tal pittura, ed ami chi l’ama e riverisce, e si diletti d’essere adorata più in quella, che in altra figura di lei imitata, e per quella faccia grazia e doni di salute, — secondo il credere di quelli, che in tal loco concorrono."],"cs":["Vědy, které lze napodobit, jsou takové, že jimi se žák vyrovná autorovi a podobně nese plod. Ty jsou užitečné napodobiteli, ale nejsou tak znamenité jako ty, které nelze zanechat dědictvím jako jiné statky.","Mezi nimi je Malířství první. To se nenaučí ten, komu to příroda nedopřeje, jak je tomu u Matematiky, z níž žák pobere tolik, kolik mu mistr přednese; to se nekopíruje, jako se kopíruje písmo, kde opis má tutéž cenu jako originál; to se neotiskuje, jak se to dělá u Sochařství, kde otisk je takový jako originál, pokud jde o kvalitu díla; to neplodí nekonečně mnoho dětí jako tištěné knihy. Ono jediné zůstává vznešené, ono jediné ctí svého tvůrce a zůstává vzácné a jedinečné a nikdy neporodí děti sobě rovné. A taková jedinečnost ho činí znamenitějším než ty, které jsou všude zveřejňovány.","Copak nevidíme, že nejmocnější králové Orientu chodí zahaleni a zakryti v domnění, že by zveřejňováním a rozšiřováním své přítomnosti zmenšili svou slávu? Copak nevidíme, že obrazy, představující božská Božstva, jsou ustavičně drženy zakryté pokrývkami převeliké ceny? A když se odkrývají, konají se nejprve velké církevní slavnosti s rozličnými zpěvy a různou hudbou; a při odkrytí se veliké množství lidu, které se tam sbíhá, ihned vrhá na zem, klaní se a modlí k tomu, kdo je na takovém obraze zobrazen, o navrácení ztraceného zdraví a o věčné spasení, ne jinak, než kdyby ta Idea byla přítomna živá?","To se neděje u žádné jiné vědy ani jiného lidského díla. A řekneš-li, že to není zásluha malíře, ale vlastní moc napodobené věci, odpoví se, že v takovém případě by se mysl lidí mohla uspokojit, i kdyby zůstali ležet v posteli, a nemuseli by chodit na namáhavá a nebezpečná místa, na poutě, jak je ustavičně vidět.","Ale jestliže takové poutě ustavičně existují, kdo je pohání, bez nutnosti? Jistě přiznáš, že je to takový obraz, jaký nemohou vytvořit všechna písma, která by tu Ideu mohla zobrazit v podobě i v moci. Zdá se tedy, že ta Idea miluje takový obraz a miluje toho, kdo jej miluje a ctí, a těší se, že je uctívána spíše v něm než v jiné své napodobenině, a skrze něj uděluje milost a dary zdraví – podle víry těch, kdo se na takové místo sbíhají."],"ref":{"s":"Lu","l":8,"st":"","z":false,"raw":"Lu. 8"},"ca":[]},{"id":"s425","o":"Difesa della pittura","c":"V","str":235,"ni":"come la pittura avanza tutte l’opere umane per sottile speculazione appartenente a quella","nc":"Malířství předčí všechna lidská díla","it":["L’occhio, che si dice finestra dell’anima, è la principale via, donde il comune senso può più copiosamente e magnificamente considerare le infinite opere di natura; e l’orecchio è il secondo, il quale si fa nobile per le cose racconte, le quali ha veduto rocchio.","Se voi, storiografi o poeti o altri matematici, non avessi coll’occhio viste le cose, male le potreste riferire per le scritture; e se tu, poeta, figurerai una storia colla pittura della penna, e ’l pittore col pennello la farà di più facile saddisfazione, e men tediosa a essere compresa. Se tu dimanderai la pittura muta poesia, ancora il pittore potrà dire del poeta orba pittura. Or guarda: — quale è più dannoso morso o cieco o muto? — Se ’l poeta è libero, come ’l pittore, nelle invenzioni, le sue finzioni non sono di tanta saddisfazione a li omini, quanto le pitture, perchè, se la Poesia s’astende con le parole ii figurare forme, atti e siti, il pittore si move, colle proprie similitudine de le forme, il contrattare esse forme. Or guarda: qual’è più propinquo all’omo, ’l nome d’omo o la similitudine d’esso omo? — Il nome dell’omo si varia in vari paesi, e la forma non ò mutata se non da morte.","Se voi dicessi: — la Poesia è più eterna—; per questo io dirò essere più eterne l’opere d’un calderaio, che il tempo più le conserva che le yostre o nostre opere, nientedimeno e di poca fantasia, e la Pittura si po’, dipignendo sopra rame con colori di vetro, fare molto più eterna.","Noi per arte possiamo essere detti nipoti a Dio. Se la Poesia s’astende in filosofia morale e questa in filosofia naturale; se quella descrive l’operazione della mente, che considera, questa colla mente opera ne’ movimenti; se quella spaventa i popoli con le infernali finzioni, questa colle medesime cose in atto fa il simile. Pongasi il poeta a figurare una bellezza, una fierezza, una cosa nefanda e brutta, una mostruosa, col pittore; faccia a suo modo, come vuole, tramutazione di forme, che il pittore non saddisfassi più. Non s’è egli viste pitture avere tanta conformità colla cosa vera, ch’ell’ha ingannato omini e animali?"],"cs":["Oko, které se nazývá oknem duše, je hlavní cestou, kterou může společný smysl nejhojněji a nejvelkolepěji pozorovat nekonečná díla přírody; a ucho je druhé, a to se stává vznešeným skrze vyprávěné věci, které vidělo oko.","Kdybyste vy, dějepisci nebo básníci nebo jiní matematici, neviděli věci okem, těžko byste je mohli líčit v písemnostech; a jestliže ty, básníku, zobrazíš příběh malbou pera, malíř jej štětcem učiní snáze uspokojivým a méně únavným k pochopení. Nazveš-li malířství němou poezií, může i malíř nazvat poezii slepým malířstvím. Nuže pohleď: – co je škodlivější zrůda, slepá, nebo němá? – Je-li básník ve vynálezech svobodný jako malíř, nepůsobí jeho výmysly lidem takové uspokojení jako malby; neboť jestliže se Poezie snaží slovy zobrazit tvary, posunky a polohy, malíř se dává do toho, aby tyto tvary napodobil vlastními podobami tvarů. Nuže pohleď: co je člověku bližší, jméno člověka, nebo podoba toho člověka? – Jméno člověka se v různých zemích mění, a tvar nemění nic než smrt.","Kdybyste řekli: – Poezie je trvalejší –, pak řeknu, že trvalejší jsou díla kotláře, neboť je čas zachovává lépe než vaše či naše díla, a přece jsou málo vynalézavá; a Malířství lze, maluje-li se na měď sklovitými barvami, učinit mnohem trvalejším.","Uměním můžeme být nazváni Božími vnuky. Jestliže se Poezie rozpíná do morální filosofie, toto do filosofie přírodní; jestliže ona popisuje činnost mysli, která rozjímá, toto myslí působí v pohybech; jestliže ona děsí národy pekelnými výmysly, toto činí totéž týmiž věcmi uvedenými v čin. Ať se básník pustí s malířem do zobrazení krásy, divokosti, věci ohavné a ošklivé, věci zrůdné; ať po svém, jak chce, proměňuje tvary, malíř uspokojí víc. Copak nebylo vidět malby, které se tolik shodovaly se skutečnou věcí, že oklamaly lidi i zvířata?"],"ref":{"s":"Ash.I","l":19,"st":"v","z":false,"raw":"Ash. I. 19 v"},"ca":[]},{"id":"s426","o":"Difesa della pittura","c":"VI","str":237,"ni":"la pittura crea la realtà","nc":"Malířství tvoří skutečnost","it":["Tal proporzione è dall’immaginazione a l’effetto, qual’è dall’ombra al corpo ombroso, e la medesima proporzione è dalla Poesia alla Pittura. Perche la Poesia pon le sue cose nell’imaginazione di lettere, e la Pittura le dà realmente fori dell’occhio, dal quale occhio riceve le similitudini non altrementi, che s’elle fussino naturali; e la Poesia le dà sanza essa similitudine, e non passano all’imprensiva per la via della virtù visiva, come la Pittura."],"cs":["Takový poměr je mezi představou a skutečností, jaký je mezi stínem a stínícím tělesem, a týž poměr je mezi Poezií a Malířstvím. Neboť Poezie klade své věci do představivosti písmeny, kdežto Malířství je podává skutečně vně oka, od něhož oko přijímá podoby ne jinak, než kdyby byly přirozené; a Poezie je podává bez této podoby a nepřecházejí do vnímavosti cestou zrakové mohutnosti jako Malířství."],"ref":{"s":"Lu","l":2,"st":"","z":false,"raw":"Lu 2"},"ca":[]},{"id":"s427","o":"Difesa della pittura","c":"VII","str":238,"ni":"rappresentazione e descrizione","nc":"Zobrazení a popis","it":["La Pittura rappresenta al senso, con più verità e certezza, le opere di natura, che non fanno le parole o le lettere, ma le lettere rappresentano con più verità le parole, che non fa la Pittura. Ma diremo essere più mirabile quella scienza, che rappresenta l’opere di natura, che quella, che rappresenta l’opere dell’operatore, cioè l’opere degli uomini, che sono le parole, com’è la Poesia e simili, che passano per la umana lingua."],"cs":["Malířství představuje smyslu díla přírody pravdivěji a jistěji, než to činí slova nebo písmena, ale písmena představují slova pravdivěji, než to činí Malířství. Řekneme však, že obdivuhodnější je ta věda, která představuje díla přírody, než ta, která představuje díla tvůrce, totiž díla lidí, jimiž jsou slova, jako je Poezie a podobné, které procházejí lidským jazykem."],"ref":{"s":"Lu","l":7,"st":"","z":false,"raw":"Lu. 7"},"ca":[]},{"id":"s428","o":"Difesa della pittura","c":"VIII","str":238,"ni":"eccellenza dell’occhio","nc":"Vznešenost oka","it":["L’occhio, dal quale la bellezza dell’universo è specchiata dalli contemplanti, è di tanta eccellenza, che chi consente alla sua perdita, si priva della rappresentazione di tutte l’opere della natura, per la veduta delle quali l’anima sta contenta nelle umane carceri, mediante gli occhi, per li quali essa anima si rappresenta tutte le varie cose di natura; ma chi li perde, lascia essa anima in una oscura prigione, dove si perde ogni speranza di riveder il sole, luce di tutt’il mondo. E quanti son quelli, a chi le tenebre notturne sono in somm’odio, ma ancora ch’elle sieno di breve vita! Oh! che farebbono questi, quando tali tenebre fussino compagne della vita loro?","Certo, non è nissuno, che non volesse più tosto perdere l’audito o l’odorato, che l’occhio, la perdita del quale audire consente la perdita di tutte le scienze, ch’hanno termine nelle parole; e sol fa questo per non perdere la bellezza del mondo, la quale consiste nella superfizie de’ corpi, sì accidentali come naturali, li quali si riflettono nell’occhio umano."],"cs":["Oko, jímž se krása vesmíru zrcadlí těm, kdo ji pozorují, je tak znamenité, že kdo svolí k jeho ztrátě, připraví se o obraz všech děl přírody, jejichž pohledem je duše spokojena v lidském žaláři, skrze oči, jimiž si tato duše představuje všechny rozmanité věci přírody; ale kdo je ztratí, zanechá tu duši v temném vězení, kde se ztrácí každá naděje znovu uvidět slunce, světlo celého světa. A kolik je těch, jimž je noční tma v nejvyšší nenávisti, ačkoli má krátký život! Ó, co by dělali tito, kdyby taková tma byla družkou jejich života?","Jistě není nikoho, kdo by raději neztratil sluch nebo čich než oko; kdo souhlasí se ztrátou sluchu, souhlasí se ztrátou všech věd, které končí ve slovech; a činí to jen proto, aby neztratil krásu světa, která spočívá v povrchu těles, jak nahodilých, tak přirozených, jež se odrážejí v lidském oku."],"ref":{"s":"Lu","l":24,"st":"","z":false,"raw":"Lu. 24"},"ca":[]},{"id":"s429","o":"Difesa della pittura","c":"IX","str":239,"ni":"il pittore va direttamente alla natura","nc":"Malíř jde přímo k přírodě","it":["La Pittura serve a più degno senso, che la Poesia, e fa con più verità le figure delle opere di natura, che il poeta; e sono molto più degne l’opere di natura che le parole, che sono l’opere dell’omo, perchè tal proporzione è dalle opere de li uomini a quelle della natura, qual è quella, ch’è da l’omo a Dio. Adunque è più degna cosa l’imitar le cose di natura, che sono le vere similitudini in fatto, che con parole imitare li fatti e parole de li omini.","E se tu, poeta, vuoi descrivere l’opere di natura co’ la tua semplice professione, fingendo diversi siti e forme di varie cose, tu sei superato dal pittore con infinita proporzione di potenza; ma se vuoi vestirti de l’altrui scienze, separate da essa poesia, elle non sono tue, come Astrologia, Retorica, Teologia, Filosofia, Geometria, Aritmetica e simili. Tu non sei allora più poeta, tu ti trasmuti, e non sei più quello, di che qui si parla. Or non vedi tu, che se tu vuoi andare alla natura, che tu vi vai con mezzi di scienze, fatte d’altrui sopra li effetti di natura? E il pittore per sè, sanza aiuto di scienziati o d’altrui mezzi, va immediate all’imitazione d’esse opere di natura.","Con questa si muovono li amanti verso li simulacri della cosa amata, a parlare coll’imitate pitture; con questa si muovono popoli, con infervorati voti, a ricercare li simulacri delli Iddii, e non a vedere le opere de’ poeti, che con parole figurino li medesimi Iddii; con questa si ingannano li animali. Già vid’io una pittura, che ingannava il cane, mediante la similitudine del suo padrone, alla quale esso cane faceva grandissima festa; e similmente ho visto i cani baiare e voler mordere i cani dipinti; e una scimmia fare infinite pazzie contro ad un’altra scimmia dipinta; ho veduto le rondini volare e posarsi sopra li ferri dipinti, che sportano fuori delle finestre de li edilìzi."],"cs":["Malířství slouží vznešenějšímu smyslu než Poezie a vytváří postavy děl přírody pravdivěji než básník; a díla přírody jsou mnohem vznešenější než slova, která jsou díly člověka, protože takový poměr je mezi díly lidí a díly přírody, jaký je mezi člověkem a Bohem. Je tedy vznešenější věcí napodobovat věci přírody, které jsou skutečnými podobami ve skutečnosti, než slovy napodobovat činy a slova lidí.","A chceš-li ty, básníku, popsat díla přírody svým prostým uměním, vymýšleje rozličné polohy a tvary rozmanitých věcí, překoná tě malíř nekonečným poměrem moci; ale chceš-li se odít do cizích věd, oddělených od samé poezie, nejsou tvoje, jako Astrologie, Rétorika, Teologie, Filosofie, Geometrie, Aritmetika a podobné. Pak už nejsi básník, proměňuješ se a už nejsi tím, o němž se zde mluví. Copak nevidíš, že chceš-li jít k přírodě, jdeš k ní prostředky věd, které vytvořili jiní o účincích přírody? A malíř sám o sobě, bez pomoci učenců či cizích prostředků, jde bezprostředně k napodobení těchto děl přírody.","Díky němu se milenci obracejí k obrazům milované bytosti, aby mluvili s napodobenými malbami; díky němu se národy s horoucími sliby vydávají hledat obrazy Bohů, a ne vidět díla básníků, kteří slovy zobrazují tytéž Bohy; díky němu se klamou zvířata. Viděl jsem již obraz, který klamal psa podobou jeho pána, a pes mu dělal převelikou radost; a podobně jsem viděl psy štěkat a chtít kousat namalované psy; a opici dělat nesčetná bláznovství proti jiné namalované opici; viděl jsem vlaštovky létat a sedat na namalované železné tyče, které vyčnívají z oken budov."],"ref":{"s":"Lu","l":14,"st":"","z":false,"raw":"Lu. 14"},"ca":[]},{"id":"s430","o":"Difesa della pittura","c":"X","str":241,"ni":"potenza espressiva della pittura","nc":"Výrazová síla malířství","it":["Non vede l’imaginazione cotal eccellenza, qual vede l’occhio, perchè l’occhio riceve le spezie overo similitudini delli obbietti, e dalli alla imprensiva, e da essa imprensiva al senso comune, e lì è giudicata. Ma la imaginazione non esce fuori da esso senso comune, se non in quanto essa va alla memoria, e lì si ferma e muore, se la cosa imaginata, non è di molta eccellenza. E in questo caso si ritrova la Poesia nella mente overo imaginativa del poeta, il quale finge le medesime cose del pittore, per le quali finzioni egli vuole equipararsi a esso pittore, ma invero ei n’è molto rimoto, come di sopra è dimostrato. Adunque in tal caso di finzione, diremo con verità esser tal proporzione dalla scienza della Pittura alla Poesia, qual è dal corpo alla sua ombra derivativa, e ancora maggior proporzione, conciossiachè l'ombra di tal corpo almeno entra per l’occhio al senso comune, ma la imaginazione di tal corpo non entra in esso senso, ma lì nasce, nell' occhio tenebroso. Oh! che differenza è a imaginare tal luce nell’occhio tenebroso, al vederla in atto fuori delle tenebre!","Se tu, poeta, figurerai la sanguinosa battaglia, mista con la oscura e tenebrosa aria, mediante il fumo delle spaventevoli e mortali macchine, mista con la spessa polvere, intorbidatrice de l’aria, e la paurosa fuga de li miseri spaventati dalla orribile morte; in questo caso il pittore ti supera, perchè la tua penna fia consumata, innanzi che tu descriva appieno quel, che immediate il pittore ti rappresenta co’ la sua scienza. E la tua lingua sarà impedita dalla sete e il corpo dal sonno e fame, prima che tu con parole dimostri quello, che in un istante il pittore ti dimostra. Nella qual pittura non manca altro, che l’anima delle cose finte, e in ciascun corpo è l’integrità di quella parte, che per un sol aspetto può dimostrarsi, il che lunga e tediosissima cosa sarebbe alla poesia a ridire tutti li movimenti de li operatori di tal guerra, e le parti delle membra e lor ornamenti, delle quali cose la pittura finita, con gran brevità e verità, ti pone innanzi; e a questa tal dimostrazione non manca, se non il romore delle macchine, e le grida de li spaventanti vincitori, e le grida e pianti de li spaventati, le quali cose ancora il poeta non può rappresentare al senso dell’audito. Diremo adunque la Poesia essere scienza, che sommamente opera nelli orbi, e la Pittura fare il medesimo nelli sordi. Essa tanto resta più degna che la Poesia, quanto ella serve a miglior senso.","Solo il vero uffizio del poeta è fingere parole di gente, che insieme parlino, e sol queste rappresenta al senso dell’audito tanto come naturali, perchè in sè sono naturali create dall’umana voce, e, in tutte l’altre consequenzie, è superato dal pittore. Ma molto più sanza comparazione son le varietà, in che s’astende la Pittura, che quelle, in che s’astendono le parole, perchè infinite cose farà il pittore, che le parole non le potrà nominare, per non aver vocaboli appropriati a quelle. Or non vedi tu, che, se ’l pittore voi fingere animali o diavoli nell’inferno, con quanta abbondanzia d’invenzione egli trascorre?","E già intervenne a me fare una pittura, che rappresentava una cosa divina, la quale comperata dall’amante di quella, volle levarne la rappresentazione di tal deità, per poterla baciare sanza sospetto. Ma infine la coscienza vinse li sospiri e la libidine, e fu forza, ch’ei se la levasse di casa. Or va tu, poeta, descrivi una bellezza sanza rappresentazioni di cosa viva, e desta li uomini con quella a tali desideri! Se tu dirai: — io ti descriverò l’inferno o ’l paradiso, e altre delizie o spaventi —; il pittore ti supera, perchè ti metterà innanzi cose, che, tacendo, diranno tali delizie, o ti spaventeranno, e ti movono l’animo a fuggire. Move più presto li sensi la pittura, che la poesia. E se tu dirai, che con le parole tu leverai un popolo in pianto o in riso; io ti dirò, che non sei tu che muove, egli è l’oratore, e è ’l riso. Uno pittore fece una pittura, che, chi la vedeva, sùbito sbadigliava, e tanto replicava tale accidente, quanto si teneva l’occhi alla pittura, la quale ancora lei era finta a sbadigliare.","Altri hanno dipinto atti libidinosi e tanto lussuriosi, ch’hanno incitati li risguardatori di quella alla medesima festa, il che non farà la Poesia. E se tu scriverai la figura d’alcuni Dei, non sarà tale scrittura nella medesima venerazione che la Idea dipinta, perchè a tale pittura sarà fatto di continuo voti e diverse orazioni, e a quella concorreranno varie generazioni di diverse provincie e per li mari orientali. E da tali si dimanderà soccorso a tal pittura e non alla scrittura.","Qual è colui, che non voglia prima perdere l’audito, l’odorato e ’l tatto, che ’l vedere? Perchè, chi perde il vedere, è com’uno, ch’è cacciato dal mondo, perchè egli più no ’l vede, nè nessuna cosa. E questa vita è sorella della morte."],"cs":["Představivost nevidí takovou znamenitost, jakou vidí oko, protože oko přijímá obrazy čili podoby předmětů a podává je vnímavosti a od té vnímavosti společnému smyslu, a tam se posuzují. Ale představivost nevychází ven z toho společného smyslu, leda pokud jde do paměti, a tam se zastaví a umírá, není-li představená věc velmi znamenitá. A v tomto případě se nachází Poezie v mysli čili obrazotvornosti básníka, který si vymýšlí tytéž věci jako malíř a chce se těmito výmysly vyrovnat malíři, ale vpravdě je mu velmi vzdálen, jak bylo ukázáno výše. V takovém případě výmyslu tedy řekneme po pravdě, že takový poměr je mezi vědou Malířství a Poezií, jaký je mezi tělesem a jeho odvozeným stínem, a ještě větší, neboť stín takového tělesa aspoň vstupuje okem do společného smyslu, ale představa takového tělesa do toho smyslu nevstupuje, nýbrž tam se rodí, v temném oku. Ó, jaký je rozdíl představovat si takové světlo v temném oku a vidět je skutečně mimo tmu!","Jestliže ty, básníku, zobrazíš krvavou bitvu, smíšenou s temným a zachmuřeným vzduchem od dýmu strašných a smrtících strojů, smíšenou s hustým prachem, jenž kalí vzduch, a s bázlivým útěkem ubožáků vyděšených hroznou smrtí, v tomto případě tě malíř překoná, protože tvé pero bude opotřebováno dříve, než plně popíšeš to, co ti malíř svou vědou představí okamžitě. A tvůj jazyk bude spoután žízní a tělo spánkem a hladem dříve, než slovy ukážeš to, co ti malíř ukáže v okamžiku. V takové malbě nechybí nic než duše zobrazených věcí, a v každém těle je úplnost té části, která se může ukázat jediným pohledem; bylo by pro poezii dlouhou a nanejvýš únavnou věcí vylíčit všechny pohyby účastníků takové války a části údů a jejich ozdoby, což vše ti hotová malba s velkou stručností a pravdivostí předkládá; a takovému zobrazení nechybí nic než hluk strojů a křik děsivých vítězů a křik a pláč vyděšených, a ty věci ani básník nemůže představit smyslu sluchu. Řekneme tedy, že Poezie je věda, která nejvíce působí u slepých, a Malířství činí totéž u hluchých. O to je však vznešenější než Poezie, oč lepšímu smyslu slouží.","Jediným pravým úřadem básníka je vymýšlet slova lidí, kteří spolu mluví, a jedině ta představuje smyslu sluchu jako přirozená, protože sama o sobě jsou přirozená, vytvořená lidským hlasem; a ve všech ostatních ohledech je překonán malířem. Ale nesrovnatelně víc je rozmanitostí, na něž se vztahuje Malířství, než těch, na něž se vztahují slova, protože malíř udělá nekonečně mnoho věcí, které slova nebudou moci pojmenovat, protože pro ně nemají vhodné výrazy. Copak nevidíš, s jakou hojností vynalézavosti se malíř rozběhne, chce-li vymyslet zvířata nebo ďábly v pekle?","A již se mi přihodilo, že jsem udělal obraz, který představoval věc božskou; a ten, kdo jej koupil a do něhož se zamiloval, chtěl z něho odstranit znaky božství, aby jej mohl líbat bez obav. Ale nakonec svědomí přemohlo vzdechy a chtíč, a musel jej odstranit ze svého domu. Nuže jdi, básníku, popiš krásu bez zobrazení živé věci a probuď jí v lidech takové touhy! Řekneš-li: – popíšu ti peklo nebo ráj a jiné rozkoše či hrůzy –, malíř tě překoná, protože ti předloží věci, které mlčky vysloví takové rozkoše nebo tě vyděsí a pohnou tvou duší k útěku. Malířství hýbe smysly rychleji než poezie. A řekneš-li, že slovy přiměješ lid k pláči nebo k smíchu, řeknu ti, že nejsi to ty, kdo hýbe, je to řečník, a je to smích. Jeden malíř udělal obraz, a kdo jej viděl, hned zíval, a tak dlouho se to opakovalo, dokud měl oči upřené na obraz, na němž byla i postava namalovaná, jak zívá.","Jiní malovali chlípné a tak smyslné výjevy, že podnítili své diváky k témuž veselí, což Poezie nesvede. A popíšeš-li postavu nějakých Bohů, nebude takové písmo v téže úctě jako namalovaná Idea, protože takovému obrazu budou ustavičně skládány sliby a rozličné modlitby a budou se k němu sbíhat rozličná pokolení z různých krajin i přes východní moře. A ti budou o pomoc prosit takový obraz, a ne písmo.","Kdo je ten, kdo by raději neztratil sluch, čich a hmat než zrak? Neboť kdo ztratí zrak, je jako ten, kdo je vyhnán ze světa, protože už ho nevidí, ani žádnou věc. A takový život je sestrou smrti."],"ref":{"s":"Lu","l":16,"st":"","z":true,"raw":"Lu. 16"},"ca":[]},{"id":"s431","o":"Difesa della pittura","c":"XI","str":245,"ni":"importanza dell’occhio nella vita animale","nc":"Význam oka v životě živočichů","it":["Maggior danno ricevono li animali per la perdita del vedere, che dell’audire, per più cagioni,- e prima, che mediante il vedere il cibo è ritrovato, donde si debbe nutrire, il quale è necessario a tutti gli animali; e ’l secondo, che per il vedere si comprende il bello delle cose create, massime delle cose, ch’inducono all’amore, nel quale il cieco nato non può pigliare per lo audito, perchè mai non ebbe notizia, che cosa fusse bellezza d’alcuna cosa. Restagli l’audito, per il quale solo intende le voci e parlare umano, nel quale è i nomi di tutte le cose, a chi è dato il suo nome. Sanza la saputa d’essi nomi ben si può vivere lieto, come si vede nelli sordi nati, cioè li muti, che mediante il disegno, il quale è più de’ muti, si dilettano."],"cs":["Větší škodu utrpí živočichové ztrátou zraku než sluchu, a to z více příčin: za prvé, že pomocí zraku se nachází potrava, jíž se mají živit a která je nezbytná všem živočichům; a za druhé, že zrakem se chápe krása stvořených věcí, zvláště věcí, které vedou k lásce, a tu slepý od narození nemůže pojmout sluchem, protože nikdy neměl povědomí, co je krása nějaké věci. Zůstává mu sluch, jímž jediným rozumí hlasům a lidské řeči, v níž jsou jména všech věcí, jimž bylo dáno jejich jméno. Bez znalosti těchto jmen lze dobře žít vesele, jak je vidět u hluchých od narození, totiž u němých, kteří se těší z kresby, jež je věcí němých nejvíce."],"ref":{"s":"Lu","l":16,"st":"","z":false,"raw":"Lu. 16"},"ca":[]},{"id":"s432","o":"Difesa della pittura","c":"XII","str":246,"ni":"la pittura è una poesia muta","nc":"Malířství je němá poezie","it":["Qual poeta con parole ti metterà innanzi, o amante, la vera effigie della tua idea con tanta verità, qual farà il pittore? Qual fia quello, che ti dimostrerà siti de fiumi, boschi, valli e campagne, dove si rappresenti li tuoi passati piaceri, con più verità del pittore?","E se tu dici: - la Pittura è una Poesia muta per sè, se non v’è chi dica o parli per lei, quello ch’ella rappresenta —; or non vedi tu, che ’l tuo libro si trova in peggior grado? Perchè ancora ch’egli abbia un uomo, che parli per lui, non si vede niente della cosa, di che si parla, come si vederà di quello, che parla per le pitture; le quali pitture, se saranno ben proporzionati li atti co’ li loro accidenti mentali, saranno intese, come se parlassino."],"cs":["Který básník ti slovy předloží, ó milenče, pravou podobu tvé představy s takovou pravdivostí, jako to učiní malíř? Kdo to bude, kdo ti ukáže polohy řek, lesů, údolí a polí, kde se zpodobují tvé minulé radosti, pravdivěji než malíř?","A řekneš-li: – Malířství je samo o sobě němá Poezie, není-li tu nikdo, kdo by za něj řekl nebo vyslovil, co představuje –, copak nevidíš, že tvá kniha je na tom hůř? Neboť i když má člověka, který za ni mluví, není vidět nic z věci, o níž se mluví, jako je vidět u toho, kdo mluví za malby; a tyto malby, budou-li posunky dobře úměrné jejich duševním hnutím, budou pochopeny, jako by mluvily."],"ref":{"s":"Lu","l":18,"st":"","z":false,"raw":"Lu. 18"},"ca":[]},{"id":"s433","o":"Difesa della pittura","c":"XIII","str":247,"ni":"segue della pittura e poesia","nc":"Dále o malířství a poezii","it":["La Pittura è una Poesia, che si vede e non si sente, e la Poesia è una Pittura, che si sente e non si vede. Adunque queste due Poesie, o vuoi dire due Pitture, hanno scambiati li sensi, per li quali esse dovrebbono penetrare all’intelletto. Perchè, se l’una e l’altra è Pittura, de’ passare al senso comune per il senso più nobile, cioè l’occhio; e se l’una e l’altra è Poesia, esse hanno a passare per il senso meno nobile, cioè l’audito.","Adunque daremo la Pittura al giudizio del sordo nato, e la Poesia sarà giudicata dal cieco nato; e, se la Pittura sarà figurata con li movimenti appropriati alli accidenti mentali delie figure, che operano in qualunque caso, sanza dubbio il sordo nato intenderà le operazioni e l’intenzioni degli operatori, ma il cieco nato non intenderà mai cosa che dimostri il poeta, la qual faccia onore a essa Poesia; conciossiachè della nobili sue parti è il figurare li gesti e li componimenti delle istorie e li siti ornati e dilettevoli, con le trasparenti acque, per le quali si vede li verdeggianti fondi delli suoi corsi, scherzare le onde sopra prati e minute ghiare, coll’erbe, che con lor si mischiano, insieme con li sguizzanti pesci, e simili descrizioni, le quali si potrebbono così dire ad un sasso, come ad un cieco nato; perchè mai vide nessuna cosa, di che si compone la bellezza del mondo, cioè luce, tenebre, colore, corpo, figura, sito, remozione, propinquità, moto e quiete, le quali son dieci ornamenti della natura.","Ma il sordo, avendo perso il senso meno nobile, ancora ch’egli abbia insieme persa la loquela, perchè mai udì parlare, mai potè imparare alcun linguaggio, ma questo intenderà bene ogni accidente, che sia nelli corpi umani, meglio che un che parli e che abbia audito, e similmente conoscerà le opere de’ pittori e quello, che in esse si rappresenti, e a che tali figure siano appropriate."],"cs":["Malířství je Poezie, kterou je vidět a není slyšet, a Poezie je Malířství, které je slyšet a není vidět. Tyto dvě Poezie, čili chceš-li dvě Malířství, si tedy vyměnily smysly, jimiž by měly pronikat k rozumu. Neboť jsou-li obě Malířstvím, mají přecházet do společného smyslu nejvznešenějším smyslem, totiž okem; a jsou-li obě Poezií, mají přecházet méně vznešeným smyslem, totiž sluchem.","Dáme tedy Malířství k posouzení hluchému od narození a Poezii bude posuzovat slepý od narození; a bude-li Malířství zobrazeno s pohyby přiměřenými duševním hnutím postav, které jednají v jakékoli situaci, hluchý od narození bezpochyby porozumí činům a úmyslům jednajících, ale slepý od narození nikdy neporozumí věci, kterou básník ukazuje a která by dělala Poezii čest; neboť k jejím vznešeným částem patří zobrazovat posunky a skladby příběhů a krajiny ozdobné a líbezné, s průzračnými vodami, jimiž je vidět zelenající se dna jejich toků, jak vlny laškují nad loukami a drobnými oblázky, s bylinami, které se s nimi mísí, spolu s mrskajícími se rybami, a podobné popisy, které by se daly říkat kameni stejně jako slepému od narození; neboť nikdy neviděl žádnou z věcí, z nichž se skládá krása světa, totiž světlo, tmu, barvu, těleso, tvar, polohu, vzdálenost, blízkost, pohyb a klid, což je deset ozdob přírody.","Ale hluchý, ztratil-li méně vznešený smysl, ač zároveň ztratil i řeč, protože nikdy neslyšel mluvit a nikdy se nemohl naučit žádný jazyk, porozumí přesto dobře každému hnutí, které je v lidských tělech, lépe než ten, kdo mluví a slyšel, a podobně pozná díla malířů a to, co se v nich zobrazuje, a k čemu jsou takové postavy přiměřeny."],"ref":{"s":"Lu","l":20,"st":"","z":false,"raw":"Lu. 20"},"ca":[]},{"id":"s434","o":"Difesa della pittura","c":"XIV","str":248,"ni":"segue","nc":"Pokračování","it":["La Pittura è una Poesia muta, e la Poesia è una Pittura cieca, e l’una e l’altra va imitando la natura, quanto è possibile alle lor potenze, e per l’una e per l’altra si può dimostrare molti morali costumi, come fece Apelle colla sua Calunnia.","Ma della Pittura, perche serve all’occhio, senso più nobile, ne risulta una proporzione armonica; cioè che, siccome molte varie voci, insieme aggiunte ad un medesimo tempo, ne risulta una proporzione armonica, la quale contenta tanto il senso dell’udito, che li auditori restano, con stupente ammirazione, quasi semivivi; ma molto più farà le proporzionali bellezze d’un angelico viso, posto in pittura, dalla quale proporzionalità ne risulta un’armonico concento, il quale serve all’occhio in uno medesimo tempo, che si faccia dalla musica all’orecchio. E se tale armonia delle bellezze sarà mostrato all’amante di quella, di che tali bellezze sono imitate, sanza dubbio esso resterà con istupenda ammirazione e gaudio incomparabile e superiore a tutti l’altri sensi.","Ma della Poesia,— la quale s’abbia a stendere alla figurazione d’una perfetta bellezza, con la figurazione particulare di ciascuna parte, della quale si compone in pittura la predetta armonia, — non ne risulta altra grazia, che si facessi a far sentir nella musica ciascuna voce per se sola in vari tempi, delle quali non si comporrebbe alcun concento, come se volessimo mostrare un volto a parte a parte, sempre ricoprendo quelle, che prima si mostrarno, delle quali dimostrazioni l’oblivione non lascia comporre alcuna proporzionalità d’armonia, perchè l’occhio non le abbraccia co’ la sua virtù visiva a un medesimo tempo.","Il simile accade nelle bellezze di qualunque cosa finta dal poeta, de le quali, per essere le sue parti dette separatamente in separati tempi, la memoria non riceve alcuna armonia."],"cs":["Malířství je němá Poezie a Poezie je slepé Malířství, a obojí napodobuje přírodu, nakolik je to v jejich silách, a obojím lze ukázat mnohé mravy, jako to učinil Apellés svou Pomluvou.","Ale z Malířství, protože slouží oku, smyslu vznešenějšímu, vzniká harmonická úměrnost; totiž jako z mnoha rozličných hlasů spojených najednou vzniká harmonická úměrnost, která tolik uspokojuje smysl sluchu, že posluchači zůstávají v užaslém obdivu jakoby polomrtví, tím víc to učiní úměrné krásy andělské tváře zachycené na malbě, z jejíž úměrnosti vzniká harmonický souzvuk, který slouží oku v jednom a témž okamžiku, jako to činí hudba uchu. A bude-li taková harmonie krás ukázána milenci té, jejíž krásy jsou napodobeny, nepochybně zůstane v úžasném obdivu a v radosti nesrovnatelné a převyšující všechny ostatní smysly.","Ale z Poezie – má-li se pustit do zobrazení dokonalé krásy zobrazováním každé jednotlivé části, z nichž se v malbě skládá řečená harmonie – nevzniká jiný půvab, než jaký by vznikl, kdyby se v hudbě dal slyšet každý hlas sám o sobě v různých časech, z nichž by se nesložil žádný souzvuk; jako kdybychom chtěli ukazovat tvář po částech a vždy zakrývat ty, které se ukázaly předtím; z takových ukázek nedovolí zapomnění složit žádnou harmonickou úměrnost, protože je oko neobsáhne svou zrakovou mohutností v jednom a témž čase.","Totéž se děje s krásami kterékoli věci vymyšlené básníkem, z nichž paměť nepřijme žádnou harmonii, protože jejich části jsou vysloveny odděleně v oddělených časech."],"ref":{"s":"Lu","l":21,"st":"","z":true,"raw":"Lu. 21"},"ca":[]},{"id":"s435","o":"Difesa della pittura","c":"XV","str":250,"ni":"la pittura si presenta all’occhio nel suo tutto in istante","nc":"Malířství se oku ukazuje celé v okamžiku","it":["La Pittura immediate ti si rappresenta con quella dimostrazione, per la quale il suo fattore l’ha generata, e dà quel piacere al senso massimo, qual dare possa alcuna cosa creata dalla natura. E in questo caso, il poeta, che manda le medesime cose al comun senso per la via dell’audito, minor senso, non dà all’occhio altro piacere, che se un sentissi raccontar una cosa.","Or vedi, che differenza è dall’audir raccontare una cosa, che dà piacere all’occhio con lunghezza di tempo, o vederla con quella prestezza che si vedono le cose naturali. E ancorchè le cose de’ poeti sieno con lungo intervallo di tempo lette, spesse sono le volte, ch’elle non sono intese, e bisogna farli sopra diversi comenti, de’ quali rarissime volte tali comentatori intendono qual fusse la mente del poeta; e molte volte i lettori non leggono, se non piccola parte delle loro opere, per disagio di tempo. Ma l’opera del pittore immediate è compresa dalli suoi riguardatori."],"cs":["Malířství se ti představí bezprostředně takovým projevem, jakým je jeho tvůrce zplodil, a dává nejvyššímu smyslu takovou rozkoš, jakou může dát kterákoli věc stvořená přírodou. A v tomto případě básník, který posílá tytéž věci společnému smyslu cestou sluchu, smyslu nižšího, nedává oku jinou rozkoš, než jako kdyby někdo slyšel vyprávět nějakou věc.","Nuže pohleď, jaký je rozdíl slyšet vyprávět o věci, která dává oku rozkoš za dlouhý čas, nebo ji vidět s takovou rychlostí, s jakou se vidí věci přírodní. A ačkoli se věci básníků čtou s dlouhým odstupem času, často se stává, že nejsou pochopeny a je třeba k nim psát rozličné komentáře, z nichž jen nanejvýš zřídka komentátoři pochopí, jaký byl úmysl básníka; a mnohokrát čtenáři přečtou jen malou část jejich děl pro nedostatek času. Ale dílo malíře je jeho diváky pochopeno bezprostředně."],"ref":{"s":"Lu","l":22,"st":"","z":false,"raw":"Lu. 22"},"ca":[]},{"id":"s436","o":"Difesa della pittura","c":"XVI","str":251,"ni":"segue","nc":"Pokračování","it":["La Pittura ti rappresenta in un subita la sua essenza nella virtù visiva e per il proprio mezzo, donde la imprensiva riceve li obbietti naturali, e ancora nel medesima tempo, nel quale si compone l’armonica proporzionalità delle parti, che compongono il tutto, che contenta il senso; e la Poesia riferisce il medesimo, ma con mezzo meno degno de l’occhio, il quale porta nell’imprensiva più confusamente e con più tardita le figurazioni delle cose nominate, che non fa l’occhio, vero mezzo intra l’obbietto e l’imprensiva, il quale immediate conferisce con somma verità le vere superfizie e figure di quel, che dinanzi se gli appresenta; delle quali ne nasce la proporzionalità detta armonia, che con dolce concento contenta il senso, non altrementi, che si facciano le proporzionalità di diverse voci al senso dello udito, il quale ancora è men degno, che quello dell’occhio, perchè tanto, quanto ne nasce, tanto ne more, e è si veloce nel morire, come nel nascere. Il che intervenire non può nel senso del vedere; perchè, se tu rappresenterai all’occhio una bellezza umana, composta di proporzionalità di belle membra, esse bellezze non sono sì mortali, nè si presto si struggono, come fa la musica, anzi, ha lunga permanenza, e ti si lascia vedere e considerare; e non rinasce, come fa la musica nel molto sonare, nè t’induce fastidio, anzi t’innamora, e è causa, che tutti li sensi insieme con l’occhio, la vorrebbero possedere, e pare, che a gara voglian combattere con l’occhio. Pare, che la bocca, s’è la bocca, se la vorrebbe per sè in corpo; l’orecchio piglia piacere d’audire le sue bellezze; il senso del tatto la vorrebbe penetrare per tutti i suoi meati; il naso ancora vorrebbe ricevere l’aria, ch’al continuo di lei spira.","Ma la bellezza di tale armonia il tempo in pochi anni la distrugge, il che non accade in tal bellezza imitata dal pittore, perchè il tempo lungamente la conserva; e l’occhio, inquanto al suo uffizio, piglia il vero piacere di tal bellezza dipinta, qual si facessi della bellezza viva; mancagli il tatto, il quale si fa maggior fratello nel medesimo tempo, il quale, poichè avrà avuto il suo intento, non impedisce la ragione del considerare la divina bellezza. E in questo caso la pittura, imitata da quella, in gran parte supplisce: il che supplire non potrà la descrizione del poeta, il quale in questo caso si vole equiparare al pittore, ma non s’avvede, che le sue parole, nel far menzione delle membra di tal bellezza, il tempo le divide l’una dall’altra, v’inframmetto l’oblivione, e divide le proporzioni, le quali lui, sanza gran prolissità, non può nominare; e non potendole nominare, esso non può comporne l’armonica proporzionalità, la quale è composta di divine proporzioni. E per questo un medesimo tempo, nel quale s’inchiude la speculazione d’una bellezza dipinta, non può dare una bellezza descritta, e fa peccato contro natura quel, che si de’ mettere per l’occhio, a volerlo mettere per l’orecchio. Lasciavi entrare l’uffizio della Musica, e non vi mettere la scienza della Pittura, vera imitatrice delle naturali figure di tutte le cose.","Chi ti move, o omo, ad abbandonare le proprie tue abitazioni della città, e lasciare li parenti e amici, e andare in lochi campestri per monti e valli, se non la naturale bellezza del mondo, la quale, se ben consideri, sol col senso del vedere fruisci? e se il poeta vole in tal caso chiamarsi anco lui pittore, perchè non pigliavi tali siti descritti dal poeta, e startene in casa sanza sentire il superchio calore del sole? oh! non t’era questo più utile e men fatica, perchè si fa al fresco e sanza moto e pericolo di malattia? Ma l’anima non potea fruire il benefizio de li occhi, finestre delle sue abitazioni, e non potea ricevere le spezie de li allegri siti, non potea vedere l’ombrose valli rigate dallo scherzare delli serpeggianti fiumi, non potea vedere li vari fiori, che con loro colori fanno armonia all’occhio, e così tutte le altre cose, che ad esso occhio rappresentare si possono. Ma se il pittore, nelii freddi e rigidi tempi dell’inverno, ti pone innanzi li medesimi paesi dipinti ed altri, ne’ quali tu abbi ricevuto li tuoi piaceri; se appresso a qualche fonte, tu possi rivedere te, amante con la tua amata, nelli fioriti prati, sotto le dolci ombre delle verdeggianti piante, non riceverai tu altro piacere, che a udire tale effetto descritto dal poeta?","Qui risponde il poeta, e cede alle sopra dette ragioni, ma dice, che supera il pittore, perchè lui fa parlare e ragionare li omini con diverse finzioni, nelle quali ei finge cose, che non sono; e che commuoverà li omini a pigliare le armi; e che descriverà il cielo, le stelle e la natura e le arti e ogni cosa. Al quale si risponde, che nessuna di queste cose, di che egli parla, è sua professione propria, ma che, s’ei vuol parlare e orare, è da persuadere che in questo egli è vinto dall’oratore; e se parla di Astrologia, che lo ha rubato all’astrologo; e di Filosofia al filosofo; e che in effetto la Poesia non ha propria sedia, nè la merita altramente che di un merciaio ragunatore di mercanzie, fatte da diversi artigiani.","Quando il poeta cessa del figurare colle parole quel che in natura è un fatto, allora il poeta non si fa eguale al pittore, perchè se il poeta, lasciando tal figurazione, e’ descrive lo parole ornate e persuasive di colui a chi esso vole far parlare, allora egli si fa oratore, e non è più poeta, nè è pittore; e se lui parla de’ cieli, egli si fa astrologo; e filosofo e teologo parlando delle cose di natura e di Dio; ma, se esso ritorna alla figurazione di qualunque cosa, e1 si farebbe emulo al pittore, se potesse saddisfare all’occhio in parole come fa il pittore.","Ma la deità della scienza della Pittura considera le opere, così umane, come divine, le quali sono terminate dalle loro superfizie, cioè linee de’ termini de’ corpi, con le quali ella comanda allo scultore la perfezione delle sue statue. Questa col suo principio, cioè il disegno, insegna all’architettore a fare, che il suo edifizio si renda grato all’occhio; questa alli componitori di diversi vasi; questa alli orefici, tessitori, recamatori: questa ha trovato li caratteri, con li quali si esprimono li diversi linguaggi; questa ha dato li caratteri alli aritmetici: questa ha insegnata la figurazione alla Geometria; questa insegna alli prospettivi e astrolaghi e alli macchinatori e ingegneri."],"cs":["Malířství ti představí naráz svou podstatu ve zrakové mohutnosti, a to vlastním prostředkem, jímž vnímavost přijímá přírodní předměty, a ještě v tomtéž čase, v němž se skládá harmonická úměrnost částí, které tvoří celek, jenž uspokojuje smysl; a Poezie podává totéž, ale prostředkem méně důstojným než oko, který přináší do vnímavosti zmateněji a pomaleji zobrazení jmenovaných věcí, než to činí oko, pravý prostředník mezi předmětem a vnímavostí, které bezprostředně a s nejvyšší pravdivostí podává pravé povrchy a tvary toho, co se před ním objeví; z nich se rodí úměrnost zvaná harmonie, která sladkým souzvukem uspokojuje smysl, ne jinak, než to činí úměrnosti rozličných hlasů smyslu sluchu, který je však méně důstojný než smysl oka, protože jak rychle se v něm rodí, tak rychle v něm umírá, a je stejně rychlý v umírání jako v rození. To se nemůže stát ve smyslu zraku; neboť představíš-li oku lidskou krásu složenou z úměrnosti krásných údů, tyto krásy nejsou tak smrtelné, ani se tak rychle nerozplývají, jako to činí hudba, nýbrž mají dlouhé trvání a dávají se ti vidět a pozorovat; a nerodí se znovu, jako to činí hudba při mnohém hraní, ani tě neomrzí, nýbrž tě zamilují a jsou příčinou, že všechny smysly spolu s okem by ji chtěly mít, a zdá se, že chtějí o závod bojovat s okem. Zdá se, že ústa, jsou-li to ústa, by ji chtěla mít pro sebe v těle; ucho má potěšení slyšet o jejích krásách; smysl hmatu by ji chtěl proniknout všemi jejími póry; i nos by chtěl přijímat vzduch, který z ní ustavičně dýchá.","Ale krásu takové harmonie zničí čas za několik let, což se nestává s takovou krásou napodobenou malířem, protože tu čas dlouho zachovává; a oko, pokud jde o jeho úřad, má z takové namalované krásy pravou rozkoš, jako by ji mělo z krásy živé; chybí mu hmat, který se zároveň stává větším bratrem a který, jakmile dosáhne svého, nebrání rozumu v rozjímání božské krásy. A v tomto případě malba, napodobená podle ní, z velké části to nahradí: a to nebude moci nahradit popis básníka, který se v tomto případě chce malíři vyrovnat, ale nepostřehne, že jeho slova, když zmiňuje údy takové krásy, odděluje čas jedno od druhého, vkládá mezi ně zapomnění a rozděluje úměrnosti, které on bez velké rozvláčnosti nemůže pojmenovat; a nemůže-li je pojmenovat, nemůže z nich složit harmonickou úměrnost, která je složena z božských úměr. A proto jeden a týž čas, v němž je obsaženo pozorování namalované krásy, nemůže dát krásu popsanou; a hřeší proti přírodě ten, kdo chce vkládat uchem to, co se má vkládat okem. Tam nech vstoupit úřad Hudby a nevkládej tam vědu Malířství, pravou napodobitelku přirozených tvarů všech věcí.","Co tě pohání, ó člověče, opouštět vlastní obydlí ve městě a nechávat příbuzné a přátele a chodit do venkovských míst po horách a údolích, ne-li přirozená krása světa, jíž, dobře-li uvážíš, požíváš jen smyslem zraku? A chce-li se v tomto případě i básník nazývat malířem, proč jsi nevzal takové krajiny popsané básníkem a nezůstal doma, aniž bys cítil přílišný žár slunce? Ó, nebylo by ti to užitečnější a méně namáhavé, protože se to děje v chládku a bez pohybu a nebezpečí nemoci? Ale duše by nemohla požívat dobrodiní očí, oken svých obydlí, a nemohla by přijímat obrazy veselých krajin, nemohla by vidět stinná údolí brázděná laškováním hadovitě se vinoucích řek, nemohla by vidět rozmanité květy, které svými barvami tvoří oku harmonii, a tak všechny ostatní věci, které lze oku představit. Ale jestliže ti malíř v chladných a krutých dobách zimy předloží tytéž namalované krajiny a jiné, v nichž ses těšil ze svých radostí; jestliže u nějakého pramene můžeš znovu uvidět sebe, milence se svou milou, na rozkvetlých lukách, pod sladkými stíny zelenajících se stromů, nebudeš mít jinou rozkoš, než když slyšíš takový výjev popsaný básníkem?","Zde odpovídá básník a ustupuje výše řečeným důvodům, ale říká, že překonává malíře, protože nechává lidi mluvit a rozmlouvat v rozličných výmyslech, v nichž si vymýšlí věci, které nejsou; a že pohne lidi, aby se chopili zbraní; a že popíše nebe, hvězdy a přírodu a umění a všechno. Tomu se odpovídá, že žádná z těchto věcí, o nichž mluví, není jeho vlastním oborem, ale že chce-li mluvit a řečnit, je třeba ho přesvědčit, že v tom je poražen řečníkem; a mluví-li o Astrologii, že ji ukradl astrologovi, a Filosofii filosofovi; a že vskutku Poezie nemá vlastního sídla a nezaslouží si je jinak než jako kramář, sběratel zboží zhotoveného rozličnými řemeslníky.","Když básník přestane zobrazovat slovy to, co je v přírodě skutečností, pak se básník malíři nevyrovná; neboť jestliže básník opustí takové zobrazování a popisuje ozdobná a přesvědčivá slova toho, koho chce nechat mluvit, stává se řečníkem a už není básníkem ani malířem; a mluví-li o nebesích, stává se astrologem, a filosofem a teologem, mluví-li o věcech přírody a Boha; ale vrátí-li se k zobrazování jakékoli věci, stal by se soupeřem malíře, kdyby dokázal uspokojit oko slovy, jako to činí malíř.","Ale božskost vědy Malířství pozoruje díla lidská i božská, která jsou ohraničena svými povrchy, totiž liniemi obrysů těles, jimiž přikazuje sochaři dokonalost jeho soch. Ono svým základem, totiž kresbou, učí stavitele, jak učinit, aby byla jeho stavba oku milá; ono učí tvůrce rozličných nádob; ono zlatníky, tkalce, vyšívače; ono vynalezlo písmena, jimiž se vyjadřují rozličné jazyky; ono dalo číslice počtářům; ono naučilo Geometrii zobrazování; ono učí perspektiváře a astrology a strojníky a inženýry."],"ref":{"s":"H","l":658,"st":"","z":false,"raw":"H. 658"},"ca":[]},{"id":"s437","o":"Difesa della pittura","c":"XVII","str":257,"ni":"come la scienza dell’astrologia nasce dall’occhio, perchè mediante quello è generata","nc":"Jak se věda astrologie rodí z oka, neboť je jím zplozena","it":["Nessuna parte è nell’Astrologia, che non sia ufficio delle linee visuali e della Prospettiva, figliuola della Pittura — perchè il pittore è quello, che, per necessità della sua arte, ha partorito essa Prospettiva, e non si può fare sanza linee, dentro alle quali linee s’inchiudono tutte le varie figure de’ corpi, generate dalla natura, sanza le quali l’arte del geometra è orba.","E se ’l geometra riduce ogni superficie, circondata da linee, alla figura del quadrato e ogni corpo alla figura del cubo, e l’Aritmetica fa il simile con le sue radici cube e quadrate; queste due scienze non s’astendono, se non alla notizia della quantità continua e discontinua, ma della qualità non si travagliano, la quale è bellezza delle opere di natura e ornamento del mondo."],"cs":["Není v astrologii jediné části, která by nebyla úkolem zrakových paprsků a perspektivy, dcery malířství – neboť malíř je ten, kdo z nutnosti svého umění zplodil samu perspektivu, a ta se neobejde bez linií, v nichž jsou uzavřeny všechny rozmanité tvary těles zrozených přírodou a bez nichž je umění geometra slepé.","A převádí-li geometr každou plochu ohraničenou liniemi na tvar čtverce a každé těleso na tvar krychle a aritmetika činí totéž se svými odmocninami třetími a druhými, pak se tyto dvě vědy vztahují jen k poznání veličiny spojité a nespojité, avšak kvalitou se nezabývají – a ta je krásou díla přírody a ozdobou světa."],"ref":{"s":"Lu","l":17,"st":"","z":false,"raw":"Lu. 17"},"ca":[]},{"id":"s438","o":"Difesa della pittura","c":"XVIII","str":257,"ni":"parla il poeta col pittore","nc":"Básník rozmlouvá s malířem","it":["Dice il poeta, che la sua scienza è invenzione e misura, e questo è il semplice corpo di poesia, invenzione di materia e misura nei versi, che ei riveste poi di tutte le scienze. Al quale risponde il pittore, l’avere li medesimi obblighi nella scienza della’ Pittura, cioè invenzione e misura; invenzione nella materia, che lui debbe fingere, e misura nelle cose dipinte, acciocchè non sieno sproporzionate; ma che ei non si veste di tali tre scienze, anzi che l’altro in gran parte si vestono della Pittura, come l’Astrologia, che nulla fa sanza la Prospettiva, la quale è principal membro d’essa Pittura, — cioè l’Astrologia matematica, non dico della fallace giudiciale (perdonemi, chi, per mezzo delli sciocchi, ne vive!)","Dice il poeta, che descrive una cosa, che ne rappresenta un’altra piena di belle sentenze. Il pittore dico aver in arbitrio di far il medesimo, e in questa parte anco egli è poeta. E se ’l poeta dice di far accendere li omini ad amare, ch’è cosa principale della spezie di tutti l’animali, il pittore ha potenza di fare il medesimo, tanto più, che lui mette innanzi all’amante la propria effigie della cosa amata, il quale spesso fa con quella, baciandola e parlandole, quello, che non farebbe colle medesime bellezze, portate innanzi dallo scrittore; e tanto più supera gl’ingegni de li omini, che l’induce ad amare e innamorarsi di pittura, che non rappresenta alcuna donna viva.","E se il poeta serve al senso per la via dell’orecchio, il pittore per l’occhio più degno senso. Ma io non voglio da questi tali altro, se non che uno bono pittore figuri il furore d’una battaglia, e che ’l poeta ne scriva un altro, e che sieno messi in pubblico da compagnia; vedrai i veditori dove più si fermeranno, dove più considereranno, dove si darà più laude, e quale saddisferà meglio. Certo la pittura, di gran lunga più utile e bella, più piacerà. Poni iscritto il nome di Dio in uno loco, e ponevi la sua figura a riscontro, vedrai quale fia più reverita. Se la Pittura abbraccia in se tutte le forme della natura, voi non avete se non è i nomi, i quali non sono universali come le forme. Se voi avete li effetti delle dimostrazioni, noi abbiamo le dimostrazioni delli effetti.","Tolgasi uno poeta, che descriva le bellezze d’una donna al suo innamorato, togli uno pittore che la figuri, vedrai dove la natura volterà più il giudicatore innamorato. Certo il cimento delle cosa dovrebbe lasciare dare la sentenza alla sperienza. Voi avete messa la pittura infra l’arti meccaniche; certo, se i pittori fussino atti a laudare collo scrivere l’opere loro, come voi, io dubito non diacerebbe in sì vile cognome. Se voi la chiamate meccanica, perchè è per manuale che le mani figurano quel che trovano nella fantasia, voi pittori disegnate con la penna manualmente quello che nello ingegno vostro si trova. E se voi dicessi essere meccanica, perchè si fa a prezzo; chi cade in questo errore, se errore si po’ chiamare, più di voi? Se voi leggete per li Studi, non andate voi a chi più vi premia? Fate voi alcuna opera, sanza qualche premio? benchè questo non dico per biasimare simili opinioni, perchè ogni fatica aspetta premio, o potrà dire uno poeta: — io farò una finzione, che significa cosa grande. — Questo medesimo farà il pittore, come fece Apello la Calunnia."],"cs":["Básník praví, že jeho věda je vynalézavost a míra a že to je prosté tělo poezie: vynalézání látky a míra ve verších, které pak odívá do všech věd. Na to mu malíř odpovídá, že má tytéž povinnosti ve vědě malířské, totiž vynalézavost a míru: vynalézavost v látce, kterou má vymyslet, a míru ve věcech malovaných, aby nebyly nesouměrné; avšak že on se do takových tří věd neodívá, nýbrž naopak ostatní se z velké části odívají malířstvím, jako astrologie, jež nic nezmůže bez perspektivy, která je předním údem malířství – myslím ovšem astrologii matematickou, nikoli onu klamnou hvězdopravnou (ať mi odpustí ten, kdo z ní díky hlupákům žije!).","Básník praví, že popisuje jednu věc, která představuje jinou, plnou krásných myšlenek. Já pravím, že malíř má na vůli činit totéž, a v tom je i on básníkem. A tvrdí-li básník, že dokáže roznítit lidi k lásce, což je věc hlavní pro rod všech živočichů, má malíř moc učinit totéž, a tím spíše, že staví milujícímu před oči skutečnou podobu milované věci; a ten s ní často činí – líbá ji a mluví k ní –, co by nečinil s týmiž krásami, jež mu předložil spisovatel; a tak velice přemáhá lidské duše, že je přiměje milovat a zamilovat se do malby, která nepředstavuje žádnou živou ženu.","A slouží-li básník smyslu cestou ucha, malíř slouží oku, smyslu ušlechtilejšímu. Nežádám však od takových lidí nic jiného, než aby dobrý malíř zobrazil zuřivost bitvy a básník aby jinou popsal a aby byly obě vystaveny veřejně vedle sebe: uvidíš, kde se diváci zastaví déle, co budou víc zkoumat, čemu se dostane více chvály a co je lépe uspokojí. Jistě se malba, daleko užitečnější a krásnější, bude líbit více. Napiš na jedno místo jméno Boží a postav naproti jeho obraz: uvidíš, čemu se dostane větší úcty. Jestliže malířství objímá všechny tvary přírody, vy nemáte nic než jména, a ta nejsou všeobecná jako tvary. Máte-li vy účinky důkazů, my máme důkazy účinků.","Ať básník popíše krásu ženy jejímu milenci a ať ji malíř zobrazí – uvidíš, kam příroda zamilovaného soudce spíše obrátí. Jistě by se mělo nechat zkoušce věcí, aby rozsudek vynesla zkušenost. Zařadili jste malířství mezi umění mechanická; jistě, kdyby malíři byli tak schopni chválit písmem svá díla jako vy, pochybuji, že by leželo pod tak nízkým jménem. Nazýváte-li je mechanickým proto, že je ruční, neboť ruce zobrazují, co nacházejí v obrazotvornosti, i vy kreslíte perem rukama, co se nachází ve vašem duchu. A kdybyste řekli, že je mechanické, protože se dělá za peníze – kdo upadá do tohoto omylu, lze-li to omylem nazvat, více než vy? Přednášíte-li na učeních, nechodíte k tomu, kdo vás nejlépe odmění? Děláte nějaké dílo bez nějaké odměny? Ač to neříkám, abych takové názory hanil, neboť každá námaha čeká odměnu. Či může básník říci: „Udělám smyšlenku, která znamená něco velikého.“ Totéž udělá malíř, jako to učinil Apellés s Pomluvou."],"ref":{"s":"Ash.I","l":13,"st":"r","z":false,"raw":"Ash. I. 13 r"},"ca":[]},{"id":"s439","o":"Difesa della pittura","c":"XIX","str":260,"ni":"risposta del re mattia ad un poeta che gareggiava con un pittore","nc":"Odpověď krále Matyáše básníkovi, který soupeřil s malířem","it":["Portando, il dì del natale del re Mattia, un poeta un’opera fattagli in laude del giorno, ch’esso re era nato, a beneficio del mondo, e un pittore gli presentò un ritratto della sua innamorata; sùbito il Re rinchiuse il libro del poeta, e voltossi alla pittura, e a quella fermò la vista con grande ammirazione.","Allora il poeta, forte sdegnato, disse: — o re, leggi, leggi, e sentirai cosa di maggior sustanzia, che una muta pittura! —","Allora il re, sentendosi riprendere del riguardar cose mute, disse: «o poeta, taci, chè non sai ciò che ti dica; questa pittura serve a miglior senso che la tua, la qual è da orbi. Dammi cosa che io la possa vedere e toccare, e non che solamente la possa udire, e non biasimare la mia elezione deell’avermi io messo la tua opera sotto il gomito, e questa del pittore tengo con le due mani, dandola alli miei occhi, perchè le mani da lor medesime hanno tolto a servire a più. degno senso, che non è l’audire. E io per me giudico, che tale proporzione sia della scienza del pittore a quella del poeta, qual è dalli suoi sensi, de’ quali questi si fanno obbietti.","» Non sai tu che la nostra anima è composta d’armonia, e armonia non s’ingenera se non in istanti, nei quali le proporzionalità delli obbietti si fan vedere o udire? Non vedi, che nella tua scienza non è proporzionalità creata in istante, anzi l’una parto nasce dall’altra successivamente, o non nasce la succedente, se l’antecedente non muore?","» Per questo giudico la tua invenzione essere assai inferiore a quella del pittore, solo perchè da quella non componesi proporzionalità armonica. Essa non contenta la mente dell’auditore o veditore, come fa la proporzionalità delle bellissime membra, componitrici delie divine bellezze di questo viso, che m’è dinanzi, le quali in un medesimo tempo tutte ’nsieme giunte, mi danno tanto piacere colla divina loro proporzione, che null’altra cosa giudico esser sopra la terra fatta dall’uomo, che dar lo possa maggiore.»"],"cs":["Když v den narozenin krále Matyáše přinesl básník dílo složené na chválu dne, v němž se král ke prospěchu světa narodil, a malíř mu daroval portrét jeho milé, král ihned zavřel básníkovu knihu, obrátil se k malbě a upřel na ni zrak s velikým obdivem.","Tu básník, velmi rozhořčen, řekl: „Ó králi, čti, čti, a uslyšíš věc větší podstaty než nějaká němá malba!“","Tu král, cítě se kárán, že hledí na věci němé, řekl: „Ó básníku, mlč, neboť nevíš, co mluvíš; tato malba slouží lepšímu smyslu než tvé dílo, které je pro slepé. Dej mi věc, kterou mohu vidět a dotknout se jí, a ne takovou, kterou mohu jen slyšet; a nehaň mou volbu, že jsem tvé dílo odložil pod loket, kdežto toto malířovo držím oběma rukama a nastavuji je svým očím; neboť ruce samy od sebe se daly do služeb ušlechtilejšího smyslu, než je sluch. A já sám soudím, že takový poměr je mezi vědou malířovou a vědou básníkovou, jaký je mezi jejich smysly, jejichž předmětem se stávají.","Nevíš, že naše duše je složena ze souzvuku a že souzvuk se rodí jen v okamžicích, v nichž se úměrnosti předmětů dávají vidět nebo slyšet? Nevidíš, že v tvé vědě nevzniká úměrnost v okamžiku, nýbrž jedna část se rodí z druhé postupně a následující se nezrodí, dokud předcházející nezemře?","Proto soudím, že tvá vynalézavost je daleko nižší než malířova, jen proto, že se z ní neskládá souzvučná úměrnost. Neuspokojuje mysl posluchače ani diváka tak, jako úměrnost překrásných údů, skladatelek božských krás této tváře, která je přede mnou; ty mi, spojeny všechny dohromady v jednom a témž čase, působí svou božskou úměrností tolik potěšení, že soudím, že není na zemi jiné věci, lidmi zhotovené, která by mohla dát větší.“"],"ref":{"s":"Lu","l":27,"st":"","z":false,"raw":"Lu. 27"},"ca":[]},{"id":"s440","o":"Difesa della pittura","c":"XX","str":262,"ni":"altezza del mondo visibile","nc":"Vznešenost viditelného světa","it":["Non è sì insensato giudizio che, se gli è proposto qual è più da eleggere o stare in perpetue tenebre o voler perder l’audito, che sùbito non dica voler più tosto perdere l’audito insieme con l’odorato, prima che restar cieco.","Perchè chi perde il vedere, perde la bellezza del mondo con tutte le forme delle cose create, e il sordo sol perde il suono fatto dal moto dell’aria percossa, ch’è minima cosa nel mondo. Tu, che dici la scienza essere tanto più nobile, quant’essa s’astende in più degno subbietto, e per questo più vale una falsa immaginazione dell’essenza di Dio, che una immaginazione d’una cosa men degna; e per questo diremo, la Pittura, la quale solo s’astende nell’opere d’Iddio essere più degna della Poesia, che solo si astende in bugiarde finzioni de l’opere umane."],"cs":["Není tak nerozumného úsudku, aby – kdyby mu bylo předloženo, co raději zvolit, zda trvalou tmu, nebo ztrátu sluchu – hned neřekl, že raději ztratí sluch spolu s čichem, než aby zůstal slepý.","Neboť kdo ztratí zrak, ztratí krásu světa se všemi tvary stvořených věcí, a hluchý ztrácí jen zvuk vzniklý pohybem udeřeného vzduchu, což je na světě věc nepatrná. Ty, který říkáš, že věda je tím ušlechtilejší, čím ušlechtilejšího předmětu se týká, a že proto má větší cenu mylná představa o podstatě Boží než představa o věci méně důstojné – proto řekneme, že malířství, které se týká jen děl Božích, je důstojnější než poezie, jež se týká jen lživých smyšlenek lidských děl."],"ref":{"s":"Lu","l":27,"st":"","z":false,"raw":"Lu. 27"},"ca":[]},{"id":"s441","o":"Difesa della pittura","c":"XXI","str":263,"ni":"arguizione del poeta contro ’l pittore","nc":"Básníkův argument proti malíři","it":["— Tu dici, o pittore, che la tua arte è adorata, ma non imputare a te tal virtù, ma alla cosa, di che tal pittura è rappresentatrice. —","Qui il pittore risponde: — o tu, poeta, che ti fai ancora tu imitatore, perchè non rappresenti con le tue parole cose, che le lettere tue, contenitrici d’esse parole, ancora loro sieno adorate? —","Ma la natura ha più favorito il pitture che ’l poeta, e meritamente l’opere del favorito debbono essere più onorate, che di quello che non è in favore.","Adunque, laudiamo quello che con le parole saddisfa all’audito, e quel che con la pittura saddisfa al contento del vedere; ma tanto meno quel delle parole, quanto elle sono accidentali e create da minor autore, che l’opere di natura, di che ’l pittore è imitatore.","La qual natura è terminante dentro alle figure della lor superficie."],"cs":["„Říkáš, malíři, že tvé umění je uctíváno; nepřičítej však tu přednost sobě, nýbrž věci, kterou ta malba představuje.“","Na to malíř odpovídá: „Ó ty, básníku, který se také činíš napodobitelem, proč nepředstavuješ svými slovy věci takové, aby i tvá písmena, jež ta slova obsahují, byla uctívána?“","Avšak příroda zvýhodnila malíře více než básníka, a právem mají být díla zvýhodněného ctěna více než díla toho, kdo v přízni není.","Chvalme tedy toho, kdo slovy uspokojuje sluch, i toho, kdo malbou uspokojuje potěchu zraku; avšak toho se slovy tím méně, oč jsou slova nahodilá a stvořená menším původcem, než jsou díla přírody, jejímž napodobitelem je malíř.","Tato příroda je ohraničena uvnitř tvarů svých povrchů."],"ref":{"s":"Lu","l":26,"st":"","z":false,"raw":"Lu. 26"},"ca":[]},{"id":"s442","o":"Difesa della pittura","c":"XXII","str":264,"ni":"conclusione infra il poeta e il pittore","nc":"Závěr mezi básníkem a malířem","it":["Poi che noi abbiamo concluso, la Poesia esser in sommo grado di comprensione alli ciechi, e che la Pittura fa il medesimo alli sordi, noi diremo, tanto più valere la Pittura che la Poesia, quanto la Pittura serve a miglior senso e più nobile, che la Poesia; la qual nobiltà è provata esser tripla alla nobiltà di tre altri sensi, perchè è stato eletto di volere piuttosto perdere l’audito e odorato e tatto, che ’l senso del vedere.","Perchè, chi perde il vedere, perde la veduta e bellezza dell’universo, e resta a similitudine di un che sia chiuso in vita in una sepoltura, nella quale abbia moto e vita.","Or non vedi tu, che l’occhio abbraccia la bellezza di tutto il mondo? Egli è capo dell’Astrologia; egli fa la Cosmografia; esso tutte le umane arti consiglia e corregge; move l’omo a diverse parti del mondo; questo è principe delle Matematiche; le sue scienze sono certissime; questo ha misurato l’altezze e grandezze delle stelle; questo ha trovato gli elementi e loro siti; questo ha fatto predire le cose future, mediante il corso delle stelle; questo l’Architettura e Prospettiva, questo la divina Pittura ha generata. O eccellentissimo sopra tutte l’altre cose create da Dio! quali laudi fien quelle, ch’esprimere possino la tua nobiltà? quali popoli, quali lingue saranno quelle, che appieno possino descrivere la tua vera operazione?","Questa è finestra dell’umano corpo, per la quale l’anima specula e fruisce la bellezza del mondo; per questo l’anima si contenta della umana carcere, e, sanza questo, esso umano carcere è suo tormento; e per questo l’industria umana ha trovato il fuoco, mediante il quale l’occhio riacquista quello, che prima li tolsero le tenebre. Questo ha ornato la natura coll’agricoltura e dilettevoli giardini.","Ma che bisogna, ch’io m’astenda in sì alto e lungo discorso? qual è quella cosa, che per lui non si faccia? Ei move li omini dall’Oriente all’Occidente; questo ha trovato la navigazione; e in questo supera la natura, che li semplici naturali sono finiti, e l’opere, che l’occhio comanda alle mani, sono infinite, come dimostra il pittore nelle finzioni d’infinite forme d’animali e erbe, piante e siti."],"cs":["Když jsme dospěli k závěru, že poezie je v nejvyšší míře srozumitelná slepým a že malířství činí totéž hluchým, řekneme, že malířství má o tolik větší cenu než poezie, oč lepšímu a ušlechtilejšímu smyslu slouží než poezie; a tato ušlechtilost je prokázána jako trojnásobná oproti ušlechtilosti tří jiných smyslů, neboť bylo zvoleno raději ztratit sluch, čich a hmat než smysl zraku.","Neboť kdo ztratí zrak, ztratí pohled na vesmír a jeho krásu a zůstane podoben tomu, kdo je zaživa zavřen v hrobě, v němž má pohyb a život.","Což nevidíš, že oko objímá krásu celého světa? Ono je hlavou astrologie; ono tvoří kosmografii; ono radí všem lidským uměním a opravuje je; ono pohání člověka do různých končin světa; ono je knížetem matematických věd; jeho vědy jsou nejjistější; ono změřilo výšky a velikosti hvězd; ono nalezlo živly a jejich místa; ono umožnilo předpovídat budoucí věci z běhu hvězd; ono zplodilo architekturu a perspektivu, ono zplodilo božské malířství. Ó ty nejvznešenější nade všechny ostatní věci stvořené Bohem! Jaké chvály by mohly vyjádřit tvou ušlechtilost? Jaké národy, jaké jazyky by mohly plně popsat tvé pravé působení?","Ono je oknem lidského těla, jímž duše zří a užívá krásy světa; kvůli němu se duše spokojí s lidským žalářem, a bez něho je jí tento lidský žalář mukou; a kvůli němu lidská důmyslnost nalezla oheň, jehož pomocí oko znovu nabývá toho, co mu předtím vzala tma. Ono ozdobilo přírodu zemědělstvím a líbeznými zahradami.","Ale proč bych se měl pouštět do tak vznešeného a dlouhého výkladu? Která věc se neděje jeho zásluhou? Ono žene lidi z Východu na Západ; ono nalezlo plavbu po moři; a v tom předčí přírodu, že prosté přírodniny jsou konečné, kdežto díla, která oko poroučí rukám, jsou nekonečná, jak dokazuje malíř ve smyšlenkách nesčetných podob živočichů a bylin, rostlin a krajin."],"ref":null,"ca":[]},{"id":"s443","o":"Difesa della pittura","c":"XXIII","str":266,"ni":"come la musica si dee chiamare sorella e minore della pittura","nc":"Proč se má hudba nazývat mladší sestrou malířství","it":["La Musica non è da essere chiamata altro, che sorella della Pittura, conciossiachè essa è subbietto dell’audito, secondo senso all’occhio, e compone armonia con la congiunzione delle sue parti proporzionali, operate nel medesimo tempo, costrette a nascere e morire in uno o più tempi armonici; li quali tempi circondano la proporzionalità de’ membri, di che tale armonia si compone, non altrementi, che si faccia la linea circonferenziale le membra, di che si genera la bellezza umana.","Ma la Pittura eccelle e signoreggia la Musica, perchè essa non more immediate dopo la sua creazione, come fa la sventurata Musica, anzi resta in essere, e ti si dimostra in vita, quel che in fatto è, una sola superfizie.","O maravigliosa scienza, tu riservi in vita le caduche bellezze de’ mortali, le quali hanno più permanenza, che le opere di natura, le quali al continuo sono variate dal tempo, che le conduce alla debita vecchiezza! e tale scienza ha tale proporzione con la divina natura, quale hanno le sue opere con le opere di essa natura, e per questo è adorata."],"cs":["Hudbu nelze nazvat jinak než sestrou malířství, neboť je předmětem sluchu, smyslu druhého po oku, a skládá souzvuk spojením svých úměrných částí, provozovaných v témže čase a nucených rodit se a umírat v jednom či více souzvučných časech; tyto časy obklopují úměrnost údů, z nichž se onen souzvuk skládá, nejinak než obvodová linie obklopuje údy, z nichž se rodí lidská krása.","Ale malířství vyniká nad hudbou a vládne jí, neboť neumírá hned po svém stvoření jako nešťastná hudba, nýbrž trvá v bytí a ukazuje se ti jako živé, ač je ve skutečnosti jedinou plochou.","Ó podivuhodná vědo, ty uchováváš naživu pomíjivé krásy smrtelníků, které tak mají větší trvalost než díla přírody, jež čas ustavičně proměňuje a vede k náležitému stáří! A tato věda má k božské přírodě takový poměr, jaký mají její díla k dílům samé přírody, a proto je uctívána."],"ref":{"s":"Lu","l":29,"st":"","z":false,"raw":"Lu. 29"},"ca":[]},{"id":"s444","o":"Difesa della pittura","c":"XXIV","str":267,"ni":"pittura e musica","nc":"Malířství a hudba","it":["Quella cosa è più degna, che saddisfa a miglior senso: adunque la Pittura saddisfattrice al senso del vedere, è più nobile della Musica, che solo saddisfa all’audito.","Quella cosa è più nobile, che ha più eternità; adunque la Musica, che si va consumando, mentre ch’ella nasce, è men degna della Pittura, che con vetri si fa eterna.","Quella cosa, che contiene in sè più universalità e varietà di cose, quella fia detta di più eccellenza: adunque la Pittura è da essere proposta a tutte le operazioni; perchè è contenitrice di tutte le forme, che sono, e di quelle, che non sono in natura, è più da essere magnificata e esaltata, che la musica, che solo attende alla voce.","Con questa si fa i simulacri alli Dii; dintorno a questa si fa il culto divino, il quale è ornato con la Musica, a questa servente; con questa si dà copia alli amanti della causa de’ loro amori; con questa si riserva le bellezze, le quali il tempo e la genitrice natura fa fuggitive; con questa noi riserviamo le similitudini degli omini famosi. E se tu dicessi: — la Musica s’eterna con lo scriverla —; il medesimo facciamo noi qui colle lettere.","Adunque, poichè tu hai messa la Musica infra le arti liberali, o tu vi metti questa, tu ne levi quella.","E se tu dicessi: — li omini vili l’adoprano —; e così è guasta la Musica da chi non la sa.","Se tu dirai: — le scienze non meccaniche sono le mentali —; io dirò che la pitturale mentale, e ch’ella, — siccome la Musica e Geometria consideran le proporzioni delle quantità continue, e l’Aritmetica delle discontinue, — questa considera tutte le quantità continue e le qualità delle proporzioni d’ombre e lumi e distanze, nella sua Prospettiva."],"cs":["Ta věc je důstojnější, která uspokojuje lepší smysl; tedy malířství, které uspokojuje smysl zraku, je ušlechtilejší než hudba, jež uspokojuje jen sluch.","Ta věc je ušlechtilejší, která má větší věčnost; tedy hudba, která se stravuje, zatímco se rodí, je méně důstojná než malířství, jež se sklem stává věčným.","Ta věc, která v sobě obsahuje více všeobecnosti a rozmanitosti věcí, budiž nazvána znamenitější; tedy malířství má být postaveno nade všechny činnosti, neboť obsahuje všechny tvary, které v přírodě jsou, i ty, které nejsou, a má být více velebeno a vyvyšováno než hudba, která se zabývá jen hlasem.","Jím se zhotovují sochy bohům; kolem něho se koná bohoslužba, jež je zdobena hudbou, která mu slouží; jím se milencům dává podoba příčiny jejich lásky; jím se uchovávají krásy, které čas a matka příroda činí prchavými; jím uchováváme podoby slavných mužů. A kdybys řekl: „Hudba se zvěčňuje tím, že se zapíše“ – totéž zde činíme my písmem.","Protože jsi tedy hudbu zařadil mezi svobodná umění, buď tam zařaď i toto, nebo odtamtud vyřaď ono.","A kdybys řekl: „Provozují je nízcí lidé“ – i hudbu kazí ten, kdo jí nerozumí.","Řekneš-li: „Nemechanické vědy jsou ty duševní“, řeknu já, že malířství je duševní a že – tak jako hudba a geometrie zkoumají poměry veličin spojitých a aritmetika nespojitých – ono zkoumá všechny veličiny spojité i kvality poměrů stínů a světel a vzdáleností ve své perspektivě."],"ref":null,"ca":[]},{"id":"s445","o":"Difesa della pittura","c":"XXV","str":269,"ni":"parla il musico col pittore","nc":"Hudebník rozmlouvá s malířem","it":["Dice il musico, che la sua scienza è da essere equiparata a quella del pittore, perchè essa compone un corpo di molte membra, del quale lo speculatore contempla tutta la sua grazia, in tanti tempi armonici, quanti sono li tempi nelli quali essa nasce e more; e con quelli tempi trastulla con grazia l’anima, che risiede nel corpo del suo contemplante.","Ma il pittore risponde e dice, che il corpo, composto delle umane membra, non dà di se piacere a’ tempi armonici, nelli quali essa bellezza abbia a nascere e morire, ma lo fa permanente per moltissimi anni, e è di tanta eccellenza, ch’ella riserva in vita quella armonia delle proporzionate membra, le quali natura con tutte sue forze conservar non potrebbe.","Quante pitture hanno conservato il simulacro di una divina bellezza, cbe il tempo o morte in breve ha distrutto il suo naturale esempio; e è restata più degna l’opera del pittore, che della natura sua maestra!","Se tu, o musico, dirai che la Pittura è meccanica per essere operata coll’esercizio delle mani; e la Musica è operata con la bocca, ma non pel conto del senso del gusto, come la mano (non pel) senso del tatto.","Meno degne sono ancora le parole che’ fatti. Ma tu scrittore delle scienze, non copî tu con mano, scrivendo ciò che sta nella mente, come fa il pittore?","E se tu dicessi, la Musica essere composta di proporzione; ho io, con questa medesima, sèguito la Pittura, come mi vedrai."],"cs":["Hudebník praví, že jeho věda má být postavena na roveň vědě malířově, neboť skládá těleso z mnoha údů, jehož celý půvab pozorovatel nazírá v tolika souzvučných časech, v kolika se rodí a umírá; a těmito časy půvabně obveseluje duši, která sídlí v těle toho, kdo ji nazírá.","Ale malíř odpovídá a praví, že těleso složené z lidských údů nedává potěšení v souzvučných časech, v nichž by se ta krása měla rodit a umírat, nýbrž ji činí trvalou po velmi mnoho let; a je tak vynikající, že uchovává naživu onen souzvuk úměrných údů, který by příroda se všemi svými silami zachovat nedokázala.","Kolik maleb zachovalo obraz božské krásy, jejíž přirozený vzor čas nebo smrt brzy zničily; a dílo malířovo zůstalo důstojnější než dílo přírody, jeho učitelky!","Řekneš-li, hudebníku, že malířství je mechanické, protože se provádí prací rukou – i hudba se provádí ústy, avšak ne kvůli smyslu chuti, tak jako ruka ne kvůli smyslu hmatu.","Méně důstojná jsou také slova než činy. Ale ty, spisovateli věd, což neopisuješ rukou, když píšeš, co je ti v mysli, tak jako to činí malíř?","A kdybys řekl, že hudba je složena z úměrnosti – touž úměrností jsem se řídil i já v malířství, jak uvidíš."],"ref":{"s":"Lu","l":30,"st":"","z":false,"raw":"Lu. 30"},"ca":[]},{"id":"s446","o":"Difesa della pittura","c":"XXVI","str":270,"ni":"conclusione del poeta, pittore e musico","nc":"Závěr o básníkovi, malíři a hudebníkovi","it":["Tal differenza è in quanto alla figurazione delle cose corporee dal pittore al poeta, quant’è dalli corpi smembrati alli uniti: perchè il poeta, nel descrivere la bellezza o bruttezza di qualunque corpo, te lo dimostra a membro a membro e in diversi tempi, e il pittore tel fa vedere tutto in un tempo.","Il poeta non può porre colle parole la vera figura delle membra, di che si compone un tutto, come il pittore, il quale tel pone innanzi con quella verità, ch’è possibile in natura. E al poeta accade il medesimo, come al musico, che canta solo un canto composto di quattro cantori; e canta prima il canto, poi il tenore, e così seguita il contralto e poi il basso: e di costui non risulta la grazia della proporzionalità armonica, la quale si rinchiude in tempi armonici. E fa esso poeta a similitudine di un bel volto, il quale ti si mostra a membro a membro, che, così facendo, non rimarresti mai saddisfatto della sua bellezza, la quale solo consiste nella divina proporzionalità delle predette membra insieme composte, le quali solo in un tempo compongono essa divina armonia, di esso congiunto di membra, che spesso tolgono la libertà posseduta a chi le vede.","E la Musica ancora fa, nel suo tempo armonico, le soavi melodie, composte delle sue varie voci, dalle quali il poeta è privato della loro discrezione armonica; e, benchè la Poesia entri pel senso dell’audito alla sedia del giudizio, siccome la Musica, esso poeta non può descrivere l’armonia della Musica, perchè non ha podestà in un medesimo tempo di dire diverse cose, come la proporzionalità armonica della Pittura, composta di diverse membra in un medesimo tempo, la dolcezza delle quali sono giudicate in un medesimo tempo, così in comune, come in particolare. In comune in quanto allo intento del composto, in particolare, in quanto allo intento de’ componenti, di che si compone esso tutto; e per questo il poeta resta, in quanto alla figurazione delle cose corporee, molto indietro al pittore, e delle cose invisibili rimane indietro al musico.","Ma, s’esso poeta toglie in prestito l’aiuto delle altre scienze, potrà comparire alle fiere come gli altri mercanti, portatori di diverse cose, fatte da più inventori: e fa questo il poeta, quando si impresta l’altrui scienza come dell’oratore, filosofo, astrologo, cosmografo e simili, le quali scienze sono in tutto separate dal poeta. Adunque questo è un sensale, che giunge insieme diverse persone a fare una conclusione di un mercato; e, se tu vorrai trovare il proprio ufficio del poeta, tu troverai non essere altro, che un ragunatore di cose rubate a diverse scienze, colle quali egli fa un composto bugiardo, o vuoi, con più onesto dire, un composto finto. — E in questa tal finzione libera esso poeta s’è equiparato al pittore, ch’è la più debole parte della pittura."],"cs":["Co se týče zobrazování tělesných věcí, je mezi malířem a básníkem takový rozdíl jako mezi tělesy rozčleněnými a celistvými: neboť básník ti při popisu krásy či ošklivosti kteréhokoli těla ukazuje úd po údu a v různých časech, kdežto malíř ti dá vidět vše najednou.","Básník nemůže slovy podat pravý tvar údů, z nichž se skládá celek, jako malíř, který ti jej staví před oči s takovou pravdivostí, jaká je v přírodě možná. A básníkovi se děje totéž co hudebníkovi, který by sám zpíval zpěv složený pro čtyři zpěváky a zazpíval nejprve sopránový hlas, pak tenor, a tak dále alt a potom bas: z jeho zpěvu nevzejde půvab souzvučné úměrnosti, jež je uzavřena v souzvučných časech. A básník počíná si podobně jako s krásnou tváří, která by se ti ukazovala úd po údu: tak bys nikdy nebyl uspokojen její krásou, jež spočívá jen v božské úměrnosti řečených údů spojených dohromady; jen ty v jednom čase skládají onen božský souzvuk spojení údů, který často bere tomu, kdo je vidí, svobodu, jíž dosud vládl.","A hudba také tvoří ve svém souzvučném čase líbezné melodie složené z rozmanitých hlasů, jejichž souzvučného rozlišení je básník zbaven; a ačkoli poezie vstupuje smyslem sluchu do sídla soudu stejně jako hudba, nemůže básník popsat souzvuk hudby, neboť nemá moc říkat v jednom a témž čase různé věci, jako je tomu u souzvučné úměrnosti malířství, složené z různých údů v jednom a témž čase, jejichž sladkost se posuzuje v jednom a témž čase, jak v celku, tak jednotlivě: v celku co do záměru celku, jednotlivě co do záměru složek, z nichž se celek skládá. A proto básník zůstává, co se týče zobrazování tělesných věcí, daleko za malířem a co se týče věcí neviditelných, zůstává za hudebníkem.","Vypůjčí-li si však básník pomoc jiných věd, bude se moci objevit na trzích jako ostatní kupci, kteří přinášejí rozmanité věci zhotovené mnoha vynálezci; a to činí básník, když si vypůjčuje cizí vědu, například řečníka, filozofa, astrologa, kosmografa a podobných, a tyto vědy jsou od básníka zcela odděleny. Je tedy dohazovačem, který svádí dohromady různé lidi, aby uzavřeli obchod; a budeš-li chtít nalézt vlastní úkol básníka, shledáš, že není ničím jiným než sběračem věcí ukradených různým vědám, z nichž činí lživou směs, nebo chceš-li to říci slušněji, směs smyšlenou. A v této svobodné smyšlence se básník vyrovnal malíři, což je nejslabší část malířství."],"ref":{"s":"Lu","l":32,"st":"","z":false,"raw":"Lu. 32"},"ca":[]},{"id":"s447","o":"Difesa della pittura","c":"XXVII","str":273,"ni":"causa della inferiorità in cui è tenuta la pittura","nc":"Příčina podceňování malířství","it":["Per fingere le parole la Poesia supera la Pittura, e per fingere fatti la Pittura supera la Poesia, e quella proporzione ch’è da’ fatti alle parole, tal è dalla Pittura ad essa Poesia, perchè i fatti sono subbietta dell’occhio, e le parole subbietto dell’orecchio; e così li sensi hanno la medesima proporzione in fra loro, quali hanno li loro obbietti infra sè medesimi, e per questa giudico la Pittura essere superiore alla Poesia.","Ma per non sapere li suoi operatori dire la sua ragione è restata lungo tempo sanza avvocati; perchè lei non parla, ma per se si dimostra e termina ne’ fatti, e la Poesia finisce in parole, con le quali, come boriosa, sè stessa lauda."],"cs":["V předstírání slov předčí poezie malířství a v předstírání činů předčí malířství poezii; a jaký poměr je mezi činy a slovy, takový je mezi malířstvím a poezií, neboť činy jsou předmětem oka a slova předmětem ucha; a tak smysly mají mezi sebou týž poměr, jaký mají jejich předměty mezi sebou samými; a proto soudím, že malířství stojí výše než poezie.","Ale protože ti, kdo je provozují, nedovedou vyložit jeho důvody, zůstalo dlouho bez obhájců; neboť ono nemluví, nýbrž ukazuje se samo sebou a končí v činech, kdežto poezie končí ve slovech, jimiž se jako chlubivá sama chválí."],"ref":{"s":"Lu","l":46,"st":"","z":false,"raw":"Lu. 46"},"ca":[]},{"id":"s448","o":"Il pittore e la pittura","c":"I","str":274,"ni":"vastità del campo della pittura","nc":"Šíře pole malířství","it":["Ciò ch’è visibile è connumerato nella scienza della pittura."],"cs":["Všechno, co je viditelné, je zahrnuto ve vědě malířství."],"ref":{"s":"Lu","l":438,"st":"","z":false,"raw":"Lu. 438"},"ca":[]},{"id":"s449","o":"Il pittore e la pittura","c":"II","str":274,"ni":"origine della pittura","nc":"Původ malířství","it":["Come la prima pittura fu sol d’una linia, la quale circondava l’ombra dell’omo, fatta dal sole ne’ muri."],"cs":["Jak první malba byla jen jedinou linií, která obkreslovala stín člověka vržený sluncem na zeď."],"ref":{"s":"Ash.I","l":17,"st":"r","z":false,"raw":"Ash. I. 17 r"},"ca":[]},{"id":"s450","o":"Il pittore e la pittura","c":"III","str":274,"ni":"come ’l pittore e signore d’ogni sorte di gente e di tutte le cose","nc":"Jak je malíř pánem všech druhů lidí a všech věcí","it":["Se ’l pittore vuol vedere bellezze, che lo innamorino, egli n’è Signore di generarle; e se vuol vedere cose mostruose, che spaventino, o che sieno buffonesche e risibili, o veramente compassionevoli, ei n’è Signore e Dio; e se vuol generare siti e deserti, lochi ombrosi o foschi, ne’ tempi caldi, esso li figura, e così lochi caldi, ne’ tempi freddi. Se vuol valli, se vuole delle alte cime de’ monti scoprire gran campagna, e se vuole, dopo quelle, vedere l’orizzonte del mare, egli n’è Signore, e se delle basse valli vuol vedere gli alti monti o de li alti monti le basse valli e spiaggie. E in effetto ciò ch’è nell’universo per essenza, frequenza o immaginazione, esso lo ha prima nella mente e poi nelle mani; e quelle sono di tanta eccellenza, che in pari tempi generano una proporzionata armonia in un solo sguardo, qual fanno le cose."],"cs":["Chce-li malíř vidět krásy, které by ho uchvátily láskou, má moc je zplodit; a chce-li vidět věci obludné, které děsí, nebo šaškovské a k smíchu, nebo vpravdě politováníhodné, je jejich pánem a bohem; a chce-li zplodit krajiny a pouště, místa stinná či šerá v horkých časech, zobrazí je, a stejně tak místa horká v časech studených. Chce-li údolí, chce-li z vysokých vrcholů hor shlížet na širou rovinu a chce-li za ní spatřit obzor moře, je toho pánem; a stejně tak chce-li z nízkých údolí vidět vysoké hory, nebo z vysokých hor nízká údolí a pobřeží. A vskutku cokoli je ve vesmíru podstatou, výskytem či představou, má on nejprve v mysli a potom v rukou; a ty jsou tak vynikající, že v témže čase plodí v jediném pohledu úměrný souzvuk, jako to činí věci samy."],"ref":{"s":"Lu","l":13,"st":"","z":false,"raw":"Lu. 13"},"ca":[]},{"id":"s451","o":"Il pittore e la pittura","c":"IV","str":275,"ni":"la pittura è una seconda creazione","nc":"Malířství je druhé stvoření","it":["Chi biasima la Pittura, biasima la natura, perchè l’opere del pittore rappresentano l’opere d’essa natura, e per questo il detto biasimatore ha carestia di sentimento."],"cs":["Kdo haní malířství, haní přírodu, neboť díla malířova představují díla samé přírody; a proto má onen haněč nedostatek soudnosti."],"ref":{"s":"Lu","l":9,"st":"","z":false,"raw":"Lu. 9"},"ca":[]},{"id":"s452","o":"Il pittore e la pittura","c":"V","str":275,"ni":"come il pittore non è laudabile se quello non è universale","nc":"Malíř si nezaslouží chvály, není-li všestranný","it":["Alcuni si po’ chiaramente dire che s’ingannano, i quali chiamano bono maestro quello pittore, il quale sol fa bene una testa o una figura. Certo e’ non è gran fatto che studiando una sola cosa tutt’il tempo della sua vita, che non ne venga a qualche perfezione.","Ma conoscendo noi, che la pittura abbraccia e contiene in se tutte le cose, che produce la natura, e che conduce l’accidentale operazione degli omini, e in ultimo ciò che si po’ comprendere con gli occhi, mi pare uno tristo maestro quello, che solo una figura fa bene.","Or non vedi tu quanti e quali atti sieno fatti dalli omini? non vedi quanti diversi animali e così, alberi e erbe, fiori, varietà di siti montuosi e piani, fonti, fiumi, città, edifizì pubblici e privati, strumenti opportuni a l’uso umano, vari abiti e ornamenti e arti?","Tutte queste cose appartengano d’essere di pari operazione e bontà usate da quello, che tu vogli chiamare bon pittore."],"cs":["O některých lze jasně říci, že se mýlí, když nazývají dobrým mistrem malíře, který dělá dobře jen hlavu nebo postavu. Jistě není nic velkého, když ten, kdo celý svůj život studuje jedinou věc, v ní dojde k nějaké dokonalosti.","Víme však, že malířství objímá a obsahuje v sobě všechny věci, které plodí příroda a které vytváří nahodilá činnost lidí, a konečně všechno, co lze obsáhnout očima; proto se mi zdá ubohým mistrem ten, kdo dělá dobře jen jednu postavu.","Což nevidíš, kolik a jakých úkonů lidé konají? Nevidíš, kolik je rozmanitých zvířat, a rovněž stromů a bylin, květin, rozmanitých krajin horských i rovinných, pramenů, řek, měst, veřejných i soukromých staveb, nástrojů vhodných k lidské potřebě, rozmanitých oděvů, ozdob a řemesel?","Všechny tyto věci musí ten, koho chceš nazvat dobrým malířem, ovládat se stejnou zručností a dokonalostí."],"ref":{"s":"Ash.I","l":25,"st":"v","z":false,"raw":"Ash. I. 25 v"},"ca":[]},{"id":"s453","o":"Il pittore e la pittura","c":"VI","str":276,"ni":"il pittore e la natura","nc":"Malíř a příroda","it":["Il dipintore disputa e gareggia con la natura."],"cs":["Malíř se s přírodou pře a soupeří."],"ref":{"s":"R","l":520,"st":"","z":false,"raw":"R. 520"},"ca":[],"rr":"Ash. I. 15 a"},{"id":"s454","o":"Il pittore e la pittura","c":"VII","str":276,"ni":"come chi sprezza la pittura non ama la filosofia della natura","nc":"Kdo pohrdá malířstvím, nemiluje filozofii přírody","it":["Se tu sprezzerai la Pittura, la quale è sola imitatrice di tutte l’opere evidenti di natura, per certo tu sprezzerai una sottile invenzione, la quale con filosofica e sottile speculazione considera tutte le qualità delle forme, arie e siti, piante, animali, erbe e fiori, le quali sono cinte d’ombra e lume. E veramente questa è scienza e legittima figlia di natura, perchè la Pittura è partorita da essa natura. Ma, per dire più corretto, diremo nipote di natura, perchè tutte le cose evidenti sono state partorite dalla natura, delle quali cose partorite è nata la Pittura. Adunque rettamente la dimanderemo nipote di natura e parente di Dio."],"cs":["Budeš-li pohrdat malířstvím, které jediné napodobuje všechna zjevná díla přírody, jistě budeš pohrdat jemným vynálezem, který s filozofickým a jemným uvažováním zkoumá všechny vlastnosti tvarů, ovzduší a krajin, rostlin, zvířat, bylin a květin, jež jsou obklopeny stínem a světlem. A vpravdě je to věda a zákonitá dcera přírody, neboť malířství je zrozeno samou přírodou. Ale abychom řekli správněji, nazveme je vnučkou přírody, protože všechny zjevné věci byly zrozeny přírodou a z těchto zrozených věcí se zrodilo malířství. Právem je tedy nazveme vnučkou přírody a příbuznou Boha."],"ref":{"s":"Ash.I","l":20,"st":"r","z":false,"raw":"Ash. I. 20 r"},"ca":[]},{"id":"s455","o":"Il pittore e la pittura","c":"VIII","str":277,"ni":"come nell’opere d’importanza l’omo non si de’ fidare tanto della sua memoria, che non degni ritrarre di naturale","nc":"Kreslit podle přírody, ne zpaměti","it":["Quel maestro, il quale si desse d’intendere di potere riservare in sè tutte le forme e li effetti della natura, certo mi parrebbe questo essere ornato di molta ignoranza, con ciò sia cosa che detti effetti son infiniti, e la memoria nostra non è di tanta capacità, che basti.","Adunque tu, pittore, guarda che la cupidità del guadagno, non superi in te l’onore dell’arte, che ’l guadagno dell’onore è molto maggiore, che l’onore delle ricchezze. Sì che per queste e altre ragioni, che si potrebbon dire, attenderai prima col disegno a dare con dimostrativa forma all’occhio la intenzione e la invenzione fatta in prima nella tua imaginativa; di poi va levando o ponendo tanto che tu ti saddisfaccia; di poi fa acconciare omini vestiti o nudi, nel modo ch’in sull’opera hai ordinato, e fa che per misura e grandezza, sottoposta alla Prospettiva, che non passi niente de l’opera, che bene non sia consigliata dalla ragione e dalli effetti naturali: e questa fia la via a farti onorare della tua arte."],"cs":["Mistr, který by si namlouval, že dokáže uchovat v sobě všechny tvary a účinky přírody, by se mi jistě zdál ozdoben velikou nevědomostí, neboť řečené účinky jsou nekonečné a naše paměť nemá tak velikou kapacitu, aby stačila.","Hleď tedy, malíři, aby v tobě touha po zisku nepřemohla čest umění, neboť zisk cti je mnohem větší než čest bohatství. A tak z těchto a jiných důvodů, které by se daly uvést, budeš se nejprve kresbou snažit podat oku v názorné podobě záměr a vynález, který vznikl nejprve v tvé obrazotvornosti; potom ubírej či přidávej, dokud nebudeš spokojen; potom dej postavit lidi oblečené či nahé tak, jak jsi to na díle uspořádal, a dbej, aby co do míry a velikosti, podřízené perspektivě, neprošlo nic z díla, co by nebylo dobře poradeno rozumem a přírodními účinky: a to bude cesta, jak dosáhnout pocty svým uměním."],"ref":{"s":"Ash.I","l":26,"st":"r","z":false,"raw":"Ash. I. 26 r"},"ca":[]},{"id":"s456","o":"Il pittore e la pittura","c":"IX","str":278,"ni":"del giudicare la tua pittura","nc":"O posuzování vlastní malby","it":["Noi sappiamo chiaro che li errori si conoscono più in altrui opere, che nelle sue, e spesso, riprendendo li altrui piccioli errori, ignorerai i tua grandi. E per fuggire simile ignoranza, fa che prima sia bono prospettivo, di poi abbi intera notizia delle misure dell’omo e d’altri animali, e ancora bono architetto, cioè in quanto s’appartiene alla forma delli ediiìzî e dell’altre cose, che sono sopra la terra, che sono infinite forme. Di quante più avrai notizia, più fia laudabile la tua operazione, e in quelle che tu non hai pratica non recusare il ritrarle di naturale."],"cs":["Dobře víme, že chyby se poznávají snáze v cizích dílech než ve vlastních, a často, když káráš malé chyby druhých, přehlédneš své velké. A abys se vyhnul takové nevědomosti, buď nejprve dobrým znalcem perspektivy, potom měj úplnou znalost mír člověka i jiných zvířat a buď také dobrým architektem, totiž pokud jde o tvar budov a ostatních věcí, které jsou na zemi a mají nekonečně mnoho tvarů. Čím více jich budeš znát, tím chvályhodnější bude tvá práce; a ty, v nichž nemáš praxi, neodmítej kreslit podle přírody."],"ref":{"s":"Ash.I","l":28,"st":"r","z":false,"raw":"Ash. I. 28 r"},"ca":[]},{"id":"s457","o":"Il pittore e la pittura","c":"X","str":279,"ni":"come ’l pittore debb’esser vago d’audire, nel fare dell’opera sua, il giudizio d’ogn’omo","nc":"Malíř má při práci na svém díle rád slyšet úsudek každého","it":["Certamente non è da recusare, in mentre che l’omo dipigne, il giudizio di ciascuno; imperocchè noi conosciamo chiaro, che l’omo, benchè non sia pittore, avrà notizia della forma dell’altro omo, e ben giudicherà s’egli è gobbo, o ha una spalla alta o bassa, o s’egli ha gran bocca o naso od altri mancamenti. — E se noi conosciamo alli omini potere con verità giudicare l’opera della natura, quanto maggiormente ci converrà confessare questi potere giudicare i nostri errori, chè sappiamo quanto l’omo s’inganna nelle sue opere, e se non lo conosci in te, consideralo in altrui, e farai profitto degli altrui errori.","Sì che sia vago con pazienza udire l’altrui opinioni; e considera bene e pensa bene, se ’l biasimatore ha cagione o no di biasimarti: e se trovi di sì, racconcia; e se trovi di no, fagli vista non l’aver inteso o tu li dimostra per ragione, s’egli è omo che tu stimi, la ragione come lui s’inganna."],"cs":["Jistě se nemá, dokud člověk maluje, odmítat úsudek kohokoli; neboť dobře víme, že člověk, i když není malířem, zná tvar jiného člověka a dobře posoudí, je-li hrbatý, má-li jedno rameno výš nebo níž, má-li velká ústa či nos nebo jiné vady. A víme-li, že lidé mohou po pravdě posuzovat dílo přírody, tím spíše musíme přiznat, že mohou posuzovat i naše chyby; neboť víme, jak se člověk ve svých dílech mýlí, a nepoznáváš-li to na sobě, pozoruj to na druhých a budeš mít užitek z cizích chyb.","Buď tedy ochoten trpělivě naslouchat cizím názorům; a dobře uvaž a promysli, má-li haněč důvod tě hanit, či nikoli: shledáš-li, že ano, naprav to; shledáš-li, že ne, dělej, jako bys mu nerozuměl, anebo mu, je-li to člověk, jehož si vážíš, rozumově dokaž, v čem se mýlí."],"ref":{"s":"Ash.I","l":26,"st":"r","z":false,"raw":"Ash. I. 26 r"},"ca":[]},{"id":"s458","o":"Il pittore e la pittura","c":"XI","str":280,"ni":"della trista scusazione fatta da quelli che falsa — e indegnamente si fanno chiamare pittori","nc":"O falešných malířích","it":["Ecci una certa generazione di pittori, i quali, per loro poco studio, bisogna che vivano sotto la bellezza d’oro e d’azzurro, i quali, con somma stoltizia, allegano non mettere in opera le bone cose per li tristi pagamenti, che saprebbono ancora ben loro fare come un altro, quando l fussino bene pagati. Or vedi gente istolte! non sanno questi tali tenère qualche opera bona, dicendo: — questa è da bon premio; e questa è da mezzano; e questa è di sorte —; e mostrare d’avere opera da ogni premio."],"cs":["Je jistý druh malířů, kteří pro své nedostatečné studium musejí žít pod krásou zlata a azuru a kteří s největší pošetilostí tvrdí, že nedávají do díla dobré věci kvůli špatnému placení, ale že by je uměli udělat dobře jako kdokoli jiný, kdyby byli dobře zaplaceni. Hle, jací pošetilci! Takoví nedovedou mít po ruce nějaké dobré dílo a říci: „Toto je za vysokou cenu, toto za střední a toto za lacinou“ – a ukázat, že mají díla za každou cenu."],"ref":{"s":"Ash.I","l":25,"st":"r","z":true,"raw":"Ash. I. 25 r"},"ca":[]},{"id":"s459","o":"Il pittore e la pittura","c":"XII","str":280,"ni":"come lo specchio è ’l maestro de’ pittori","nc":"Zrcadlo je učitelem malířů","it":["Quando vuoi vedere, se la tua pittura tutta insieme ha conformità con la cosa ritratta di naturale, abbi uno specchio, e favvi dentro specchiare la cosa viva, e paragona la cosa specchiata con la tua pittura, e considera bene, se ’l subbietto de l’una e l’altra similitudine ha conformità insieme.","E sopra tutto lo specchio si de’ pigliare per suo maestro, cioè lo specchio piano, imperocchè su la sua superfizie le cose hanno similitudine con la pittura in molte parti.","Cioè, tu vedi la pittura fatta sopra un piano dimostrare cose, che paiono rilevate, e lo specchio sopra uno piano fa quel medesimo; la pittura è una sola superfizie, e lo specchio quel medesimo; la pittura è impalpabile, in quanto che quello, che pare fondo e spiccato, non si po’ circondare co’ le mani, e lo specchio fa il simile; lo specchio e la pittura mostra la similitudine delle cose circondate da ombra e lume; l’una e l’altra pare assai di là dalla sua superfizie.","E se tu conosci, che lo specchio, per mezzo de’ lineamenti e ombre e lumi, ti fa parere le cose dispiccate, e avendo tu fra li tuoi colori l’ombre e lumi più potenti che quelli dello specchio, certo, se tu li saprai ben comporre insieme, la tua pittura parrà ancora lei una cosa naturale, vista in uno grande specchio."],"cs":["Chceš-li vidět, zda tvá malba jako celek odpovídá věci zobrazené podle přírody, vezmi zrcadlo, nech v něm zrcadlit živou věc a srovnej zrcadlený obraz se svou malbou a dobře uvaž, zda si předmět obou podob vzájemně odpovídá.","A především je třeba vzít si za učitele zrcadlo, totiž zrcadlo rovné, neboť na jeho ploše se věci v mnohém podobají malbě.","Vidíš totiž, že malba provedená na rovině ukazuje věci, které se zdají vystouplé, a zrcadlo na rovině činí totéž; malba je jediná plocha a zrcadlo také; malba je nehmatatelná, neboť to, co se zdá oblé a oddělené, nelze obejmout rukama, a zrcadlo je na tom stejně; zrcadlo i malba ukazují podobu věcí obklopených stínem a světlem; jedno i druhé se zdá sahat daleko za svou plochu.","A poznáváš-li, že zrcadlo ti pomocí obrysů, stínů a světel dává věci zdánlivě vystupovat, a máš-li mezi svými barvami stíny a světla mocnější než zrcadlo, jistě, dokážeš-li je dobře sestavit, bude se i tvá malba zdát věcí přirozenou, viděnou ve velikém zrcadle."],"ref":{"s":"Ash.I","l":24,"st":"v","z":false,"raw":"Ash. I. 24 v"},"ca":[]},{"id":"s460","o":"Il pittore e la pittura","c":"XIII","str":282,"ni":"precetto al pittore","nc":"Pravidlo pro malíře","it":["Ogni ramo e ogni frutto nasce sopra il nascimento della sua foglia, la quale li scusa madre col porgergli l’acqua delle pioggie e l’umidità della rugiada, che li cade la notte di sopra, e molte volte li toglie li superchi calori delli raggi del sole.","Adunque tu, pittore, che non hai tali regole, per fuggire il biasimo delli intendenti, sii vago di ritrarre ogni tua cosa di naturale, e non disprezzare lo studio, come fanno i guadagnatori."],"cs":["Každá větev a každý plod vyrůstá nad místem, kde vyrůstá jeho list, který mu je matkou tím, že mu podává vodu dešťů a vláhu rosy, jež na něj v noci padá shora, a mnohdy mu odnímá přílišný žár slunečních paprsků.","Ty tedy, malíři, který taková pravidla neznáš, abys unikl hanění znalců, kresli rád každou svou věc podle přírody a nepohrdej studiem, jak to činí ti, kdo jdou jen po výdělku."],"ref":{"s":"K","l":110,"st":"v","z":true,"raw":"K. 110 v"},"ca":[]},{"id":"s461","o":"Il pittore e la pittura","c":"XIV","str":282,"ni":"la pittura è un discorso figurato","nc":"Malba je řeč v obrazech","it":["Li omini e le parole son fatti, e tu, pittore, non sapendo operare le tue figure, tu se’ come l’oratore, che non sa adoperare le parole sue."],"cs":["Lidé a slova jsou činy, a ty, malíři, nedovedeš-li zacházet se svými postavami, jsi jako řečník, který nedovede zacházet se svými slovy."],"ref":{"s":"K","l":110,"st":"v","z":false,"raw":"K. 110 v"},"ca":[]},{"id":"s462","o":"Il pittore e la pittura","c":"XV","str":282,"ni":"ordine dello studio","nc":"Pořádek studia","it":["Il giovane debbe prima imparare Prospettiva; poi le misure d’ogni cosa; poi di mano di bon maestro, per suefarsi a bone membra; poi di naturale, per confermarsi le ragioni delle cose imparate; poi vedere a uno tempo di mano di diversi maestri; poi fare abito al mettere in pratica e operare l’arte."],"cs":["Mladík se má nejprve naučit perspektivu; potom míry všech věcí; potom kreslit podle díla dobrého mistra, aby si navykl na dobré údy; potom podle přírody, aby si potvrdil důvody naučených věcí; potom zhlédnout po nějaký čas díla různých mistrů; potom si navyknout uvádět umění do praxe a provozovat je."],"ref":{"s":"Ash.I","l":17,"st":"v","z":false,"raw":"Ash. I. 17 v"},"ca":[]},{"id":"s463","o":"Il pittore e la pittura","c":"XVI","str":283,"ni":"— sullo stesso soggetto","nc":"Na totéž téma","it":["Dico, che prima si debbe imparare le membra e sua travagliamenti, e finita tal notizia si debbe seguitare li atti secondo li accidenti, che accadano all’omo, e terzo comporre le storie, lo studio delle quali sarà fatto dalli atti naturali, fatti a caso mediante li loro accidenti; e porli mente per le strade, piazze e campagne, e notarli con brieve descrizione di liniamenti: cioè che per una testa si faccia uno O e per uno braccio una linia retta e piegata, e ’l simile si faccia delle gambe e busto; e poi tornando alla casa fare tali ricordi in perfetta forma.","Dice l’avversario, che per farsi pratico e fare opere assai, ch’elli è meglio che ’l tempo primo dello studio sia messo in ritrarre vari componimenti, fatti per carte o muri per diversi maestri, e in quelli si fa pratica veloce e bono abito. Al quale si risponde, che questo abito sarebbe bono, essendo fatto sopra opere di boni componimenti e di studiosi maestri; e perchè questi tali maestri son sì rari, che pochi se ne trova, è più sicuro andare alle cose naturali, che a quelle d’esso naturale con gran peggioramento imitate, e fare triste abito, perchè chi può andare alla fonte non vada al vaso."],"cs":["Pravím, že se nejprve mají poznat údy a jejich pohyby, a po této znalosti má následovat poznání postojů podle příhod, které člověka potkávají, a za třetí skládání výjevů; jejich studium se bude dít podle přirozených postojů, vzniklých náhodou v důsledku jejich příhod; a ty je třeba sledovat na ulicích, náměstích a v polích a zaznamenávat je stručným náčrtem obrysů: totiž aby se za hlavu udělalo O a za paži přímá a ohnutá čára, a podobně ať se udělají nohy a trup; a pak se po návratu domů mají tyto záznamy zpracovat v dokonalé podobě.","Odpůrce praví, že aby člověk získal praxi a udělal mnoho děl, je lépe, aby první doba studia byla věnována kreslení rozmanitých kompozic, které různí mistři provedli na papíře nebo na zdech, a že v nich člověk získá rychlou praxi a dobrý návyk. Na to se odpovídá, že tento návyk by byl dobrý, kdyby vznikal na dílech dobře komponovaných a od pilných mistrů; a protože takoví mistři jsou tak vzácní, že se jich najde málo, je bezpečnější jít k věcem přírodním než k těm, které přírodu napodobují s velkým zhoršením, a osvojit si špatný návyk; neboť kdo může jít k prameni, ať nechodí ke džbánu."],"ref":{"s":"C.A","l":196,"st":"v","z":false,"raw":"C. A. 196 v"},"ca":[1055,1057]},{"id":"s464","o":"Il pittore e la pittura","c":"XVII","str":284,"ni":"del modo dello imparare bene a comporre insieme le figure nelle storie","nc":"Jak se dobře naučit skládat postavy ve výjevech","it":["Quando tu avrai imparato bene di Prospettiva, e avrai a mente tutte le membra e corpi delle cose, sia vago ispesse volte, nel tuo andarti a sollazzo, vedere e considerare i siti e li atti delli omini in nel parlare, in nel contendere o ridere o zuffare insieme, che atti fieno in loro, e che atti facciano i circostanti, i spartitori o veditori d’esse cose; e quelli notare con brievi segni, in questa forma, su un tuo picciolo libretto. Il quale tu debbi sempre portar con teco, e sia di carte tinte, acciò non l’abbi a scancellare, ma mutare di vecchio in un novo, che queste non sono cose da essere scancellate, anzi con grande diligenza riserbate, perchè gli è tante le infinite forme e atti delle cose, che la memoria non è capace a ritenerle, onde queste ti serberai come tuoi autori e maestri."],"cs":["Až se dobře naučíš perspektivu a budeš mít v paměti všechny údy a těla věcí, hleď častokrát, když se půjdeš projít pro potěšení, pozorovat a zkoumat postavení a postoje lidí, když spolu mluví, přou se, smějí se nebo se perou: jaké postoje mají oni a jaké postoje dělají okolostojící, ti, kdo je rozdělují, i ti, kdo se na to dívají; a ty zaznamenávej stručnými znaménky, v této podobě, do své malé knížky. Tu máš nosit vždycky s sebou a ať je z natíraných listů, abys z ní nemusel nic vymazávat, nýbrž vyměnil starou za novou; neboť to nejsou věci, které se mají mazat, nýbrž s velikou pečlivostí uchovávat, protože nekonečných tvarů a postojů věcí je tolik, že je paměť nedokáže udržet; proto si je uchovej jako své vzory a učitele."],"ref":{"s":"C.A","l":27,"st":"v","z":false,"raw":"C. A. 27 v"},"ca":[153,155]},{"id":"s465","o":"Il pittore e la pittura","c":"XVIII","str":285,"ni":"dello studiare in sino quando ti desti o innanzi t’addormenti nel letto, allo scuro","nc":"O studiu v posteli potmě, když se probudíš nebo než usneš","it":["Ho in me provato essere di non poca utilità, quando ti trovi allo scuro nel letto, andare co’ la imaginativa, ripetendo li liniamenti superfiziali delle forme per l’addietro studiate o altre cose notabili, da sottile speculazione comprese; ed è questo proprio un atto laudabile e utile a confermarsi le cose nella memoria."],"cs":["Sám jsem si vyzkoušel, že je nemalým užitkem, když ležíš potmě v posteli, procházet v obrazotvornosti a opakovat si vnější obrysy tvarů dříve studovaných nebo jiné pozoruhodné věci pochopené jemným uvažováním; a je to vskutku chvályhodný úkon, užitečný k upevnění věcí v paměti."],"ref":null,"ca":[]},{"id":"s466","o":"Il pittore e la pittura","c":"XIX","str":285,"ni":"modo d’aumentare e destare lo ’ngiegno a varie invenzioni","nc":"Jak probudit důvtip","it":["Non resterò però di mettere infra questi precetti una nova invenzione di speculazione, la quale, benchè paia piccola e quasi degna di riso, non di meno è di grande utilità a destare lo ’ngegnio a varie invenzioni: e questo è, se tu riguarderai in alcuni muri imbrattati di varie macchie o pietre di vari misti, se avrai a invencionare qualche sito, potrai lì vedere similitudine di diversi paesi, ornati di montagne, fiumi, sassi, alberi, pianure, grandi valli e colli in diversi modi; ancora vi potrai vedere diverse battaglie e atti pronti di figure, strane arie di volti e abiti e infinite cose, le quali tu potrai ridurre integra e bona torma. E interviene in simili muri e misti come del sôn di campane, che ne’ loro tocchi vi troverai ogni nome e vocabolo, che tu imaginerai.","Io ho già veduto nelli nuvoli e muri macchie, che mi hanno desto a belle invenzioni di varie cose, le quali macchie, ancora che integralmente fussino in sè private di perfezione di qualunque membro, non mancavano di perfezione nelli loro movimenti o altre azioni."],"cs":["Neopomenu však mezi tato pravidla vložit nový vynález uvažování, který, ač se zdá malý a téměř k smíchu, je přesto velmi užitečný k probouzení důvtipu k rozmanitým nápadům: totiž když se zadíváš na nějaké zdi pošpiněné rozmanitými skvrnami nebo na kameny rozmanitých směsí, budeš-li mít vymýšlet nějakou krajinu, uzříš tam podobu různých krajů, ozdobených horami, řekami, skalami, stromy, rovinami, velikými údolími a pahorky nejrůznějšího druhu; uzříš tam také rozmanité bitvy a živé postoje postav, podivné výrazy tváří a oděvy a nekonečně mnoho věcí, které budeš moci převést do celistvé a dobré podoby. A s takovými zdmi a směsmi se to má jako se zvukem zvonů, v jejichž úderech uslyšíš každé jméno a slovo, jaké si představíš.","Už jsem v oblacích a na zdech viděl skvrny, které mě probudily k pěkným nápadům rozmanitých věcí; a tyto skvrny, ačkoli samy v sobě úplně postrádaly dokonalost jakéhokoli údu, nepostrádaly dokonalost ve svých pohybech či jiných úkonech."],"ref":{"s":"I","l":22,"st":"v","z":false,"raw":"I. 22 v"},"ca":[]},{"id":"s467","o":"Il pittore e la pittura","c":"XX","str":286,"ni":"la stanza del pittore","nc":"Malířova světnice","it":["Le stanze overo abitazioni piccole ravvialn lo ’ngegno, e le grandi lo sviano."],"cs":["Malé světnice čili příbytky usměrňují ducha, velké jej rozptylují."],"ref":{"s":"Ash.I","l":16,"st":"r","z":false,"raw":"Ash. I. 16 r"},"ca":[]},{"id":"s468","o":"Il pittore e la pittura","c":"XXI","str":286,"ni":"l’idea e la pratica dell’arte","nc":"Představa a provozování umění","it":["Tristo è quel maestro, del quale l’opera avanza il giudizio suo, e quello si dirizza alla perfezione dell’arte, del quale l’opera è superata dal giudizio."],"cs":["Ubohý je ten mistr, jehož dílo předbíhá jeho úsudek; a k dokonalosti umění se ubírá ten, jehož dílo je překonáváno úsudkem."],"ref":{"s":"Lu","l":57,"st":"","z":false,"raw":"Lu. 57"},"ca":[]},{"id":"s469","o":"Il pittore e la pittura","c":"XXII","str":287,"ni":"progresso indefinito dell’arte","nc":"Neustálý pokrok umění","it":["Tristo è quel discepolo, che non avanza il suo maestro."],"cs":["Ubohý je ten žák, který nepředstihne svého mistra."],"ref":{"s":"R","l":498,"st":"","z":false,"raw":"R. 498"},"ca":[],"rr":"S. K. M. III. 24 b"},{"id":"s470","o":"Il pittore e la pittura","c":"XXIII","str":287,"ni":"quel pittore, che non dubita, poco acquista","nc":"Malíř, který nepochybuje, málo získá","it":["Quando l’opera supera il giudizio de l’operatore, esso operante poco acquista; e quando il giudizio supera l’opera, essa opera mai finisce di migliorare, se l’avarizia non l’impedisce."],"cs":["Když dílo překonává úsudek tvůrce, tvůrce málo získá; a když úsudek překonává dílo, dílo se nikdy nepřestane zlepšovat, nebrání-li tomu lakota."],"ref":{"s":"Lu","l":35,"st":"","z":true,"raw":"Lu. 35"},"ca":[]},{"id":"s471","o":"Il pittore e la pittura","c":"XXIV","str":287,"ni":"precetti sulla pittura","nc":"Pravidla o malířství","it":["E tu, pittore, studia di fare le tue opere ch’abbino a tirare a sè li sua veditori, e quelli fermare con grande ammirazione e dilettazione; e non tirarli e poi scacciarli, come fa l’aria a quel, che, nelli tempi notturni, salta ignudo dal letto a contemplare la qualità d’essa aria nubilosa o serena, che immediate, scacciato dal freddo di quella, ritorna nel letto, donde prima si tolse. Ma fa le opere tue simili a quell’aria, che, ne’ tempi caldi, tira gli omini de li lor letti, e gli ritiene con dilettazione a prendere lo estivo fresco; e non voler essere prima pratico che dotto, e che l’avarizia vinca la gloria, che di tal arte meritamente s’acquista.","Non vedi tu che, infra le umane bellezze, il viso bellissimo ferma li viandanti e non i loro ricchi ornamenti? E questo dico a te, che con oro o altri ricchi fregi adorni le tue figure. Non vedi tu isplendenti bellezze della gioventù diminuire di loro eccellenza per li eccessivi e troppo culti ornamenti? Non hai tu visto le montanare, involte ne gl’inculti e poveri panni, acquistare maggior bellezza, che quelle, che sono ornate?","Non usare le affettate conciature o capellature di teste, dove, appresso delli goffi cervelli, un sol capello posto più d’un lato che dall’altro, colui che lo tiene, se ne promette grand’infamia, credendo che li circostanti abbandonino ogni lor primo pensiero, e solo di quel parlino, e solo quello riprendano. E questi tali han sempre per lor consigliero lo specchio e il pettine, e il vento è loro capital nemico, sconciatore delli azzimati capegli.","Fa tu dunque alle tue teste li capegli scherzare insieme col finto vento, intorno alti giovanili volti e, con diverso revoltare, graziosamente ornarli; e non far come quelli che gl’impiastrano con colla, e fanno parere i visi, come se fussino invetriati.... Umane pazzie in aumentazione, delle quali non bastano li naviganti a condurre dalle orientali parti le gomme arabiche, per riparare che ’l vento non vari l’equalità delle sue chiome, chè di più vanno ancora investigando!..."],"cs":["A ty, malíři, snaž se dělat svá díla tak, aby k sobě přitahovala své diváky a zadržela je s velikým obdivem a potěšením; a ne aby je přitáhla a potom vyhnala, jako to činí vzduch s tím, kdo v noci vyskočí nahý z postele, aby se podíval, jaký je vzduch, zda zamračený, či jasný, a ihned, vyhnán jeho chladem, se vrací do postele, z níž předtím vstal. Ale dělej svá díla podobná onomu vzduchu, který v horkých časech láká lidi z jejich postelí a s potěšením je zdržuje, aby se nadýchali letního chládku; a nechtěj být dříve zběhlým než učeným a nedopusť, aby lakota přemohla slávu, které se v tomto umění právem nabývá.","Nevidíš, že mezi lidskými krásami zastavuje pocestné přepěkná tvář, a ne jejich bohaté ozdoby? A to říkám tobě, který zdobíš své postavy zlatem či jinými bohatými ozdobami. Nevidíš, jak zářivé krásy mládí ztrácejí na své znamenitosti přílišnými a příliš strojenými ozdobami? Neviděl jsi horalky, zahalené v neupravených a chudých šatech, nabývat větší krásy než ty, které jsou nastrojené?","Nepoužívej strojené účesy a vlasové úpravy hlav, kde u hloupých hlav jediný vlas položený víc na jednu stranu než na druhou slibuje tomu, kdo jej nosí, velikou hanbu, neboť věří, že okolostojící zanechají všech svých dřívějších myšlenek a budou mluvit jen o tom a jen to kárat. A takoví mají za rádce vždy zrcadlo a hřeben a vítr je jejich úhlavním nepřítelem, neboť jim cuchá vyfintěné vlasy.","Ty tedy nech u svých hlav vlasy pohrávat si s předstíraným větrem kolem mladistvých tváří a rozmanitým zvlněním je půvabně zdobit; a nedělej jako ti, kdo je slepují klihem a dávají tvářím vypadat, jako by byly zasklené.... Lidská pošetilost roste, a k ní nestačí mořeplavci přivážet z východních krajů arabskou gumu, aby zabránili větru narušit rovnost jejich kadeří, neboť stále ještě pátrají po dalším!..."],"ref":{"s":"Lu","l":35,"st":"","z":true,"raw":"Lu. 35"},"ca":[]},{"id":"s472","o":"Paragone della pittura con la scultura","c":"","str":289,"ni":"I","nc":"Malířství a sochařství I","it":["Adoperandomi io non meno in Scoltura, che in Pittura, e facendo l’una e l’altra ’n un medesimo grado, mi pare, con picciola imputazione, potere dare sentenza quale sia di maggiore ingegno e difficultà e perfezione l’una, che l’altra. Prima, la Scoltura è sottoposta a certi lumi, cioè di sopra, e la pittura porta per tutto con seco lume e ombra; e ’l lume e l’ombra è la importanza adunque della Scoltura. Lo scultore in questo caso è aiutato dalla natura del rilievo, che lo genera per sè, e ’l pittore per accidentale arte lo fa ne’ lochi, dove ragionevolmente lo farebbe la natura. Lo scultore non si può diversificare nelle varie nature de’ colori delle cose; la Pittura non manca in parte alcuna. Le prospettive delli scultori non paiono niente vere; quelle del pittore paiono a centinaia di miglia di là dall’opera. La Prospettiva aerea è lontana dalla loro opera, non possono figurare i corpi trasparenti, non possano figurare i luminosi, non linee riflesse, non corpi lucidi come specchi e simili cose lustranti, non nebbie, non tempi oscuri e infinite cose, che non si dicono per non tediare.","Ciò ch’ell’ha è che la è più resistente al tempo, benchè ha simile resistenza la pittura fatta sopra rame grosso coperto di smalto bianco, e sopra quello dipinto con colori di smalto, e rimesso in fuoco, e fatto cuocere. Questa per eternità avanza la scoltura. Potran dire che dove fanno un errore non esserli facile il racconciare. Questo è tristo argomento a voler provare, che una ismemorataggine irremediabile faccia l’opera più degna. Ma vi dirò bene che lo ingegno del maestro sia più difficile a racconciare, che fa simili errori, che non è racconciare l’opera da quello guasta. Noi sappiamo bene, che quello, che sarà pratico e bono, non farà simili errori, anzi con buone regole andrà levando tanto poco per volta, che ben conducerà sua opera. Ancora, lo scultore, se fa di terra o cera, può levare e porre, e quand’è terminata, con facilità si getta di bronzo, e questa è l’ultima operazione e la più permanente, ch’abbia la Scoltura, imperocchè quella, ch’è sola di marmo, è sottoposta, alla rovina, che non la ’n bronzo.","Adunque quella pittura fatta in rame che si può, con i metodi della Pittura, levare e porre, è pari abbronzo, che quando facevi prima l’opera di cera, ancor si poteva lei levare e porre. — Se questa scoltura di bronzo è eterna, questa di rame o di vetro è eternissima; se il bronzo rimane nero e brutto, questa è piena di vari e vaghi colori e d’infinite varietà, delle quale come di sopra è, se tu volessi dire solamente della pittura fatta in tavola, di questa son io contento dare la sentenza con la Scoltura, dicendo così: — come la Pittura è più bella e di più fantasia © più copiosa, e la Scoltura più durabile, e altro non ha. —","La Scoltura con poca fatica mostri quel che ’n la pittura pare cosa miracolosa a far parere palpabili le cose impalpabili, rilevate le cose piane, lontane le cose vicine! In effetto la Pittura è ornata d’infinite speculazioni, che la Scoltura non l’adopera."],"cs":["Protože se zabývám sochařstvím neméně než malířstvím a provozuji obojí ve stejné míře, zdá se mi, že mohu bez velkého nařčení vynést soud, které z nich vyžaduje víc důvtipu, je obtížnější a dokonalejší. Předně: sochařství je podřízeno jistým světlům, totiž světlu shora, kdežto malířství nese světlo a stín všude s sebou; a světlo a stín jsou tedy tím podstatným pro sochařství. Sochaři v tomto případě pomáhá povaha plastického tvaru, který jej vytváří sám od sebe, kdežto malíř jej vytváří nahodilým uměním na místech, kde by jej rozumně vytvořila příroda. Sochař nemůže obměňovat rozmanité povahy barev věcí; malířství nechybí v žádné části nic. Perspektivy sochařů se nezdají ani trochu pravé; perspektivy malíře se zdají sahat na sta mil za dílo. Vzdušná perspektiva je jejich dílu vzdálena; nemohou zobrazit průhledná tělesa, nemohou zobrazit tělesa svítící, ani odražené paprsky, ani lesklá tělesa jako zrcadla a podobné třpytivé věci, ani mlhy, ani zamračené počasí a nekonečno věcí, o nichž nemluvím, abych neomrzel.","Co má, je to, že lépe odolává času, ačkoli podobnou odolnost má malba provedená na silné mědi pokryté bílým smaltem, na niž se maluje smaltovými barvami a pak se znovu vloží do ohně a vypálí. Ta věčností předčí sochařství. Mohou říci, že kde udělají chybu, není jim snadné ji napravit. To je ubohý argument, chce-li se jím dokázat, že nenapravitelná nepozornost činí dílo důstojnějším. Ale řeknu vám, že spíše je těžké napravit ducha mistra, který takové chyby dělá, než napravit dílo, které zkazil. Dobře víme, že ten, kdo bude zběhlý a dobrý, takové chyby dělat nebude, nýbrž podle dobrých pravidel bude ubírat pokaždé tak málo, že své dílo dobře dovede ke konci. Dále: sochař, pracuje-li v hlíně nebo vosku, může ubírat i přidávat, a když je dílo hotové, snadno se odlije do bronzu; a to je poslední úkon sochařství a ten nejtrvalejší, neboť socha, která je jen z mramoru, podléhá zkáze, kdežto bronzová ne.","Tedy ona malba na mědi, na níž lze způsoby malířství ubírat i přidávat, je rovna bronzu, neboť i když jsi dílo dělal nejprve z vosku, dalo se ubírat i přidávat. Je-li tato bronzová socha věčná, tato na mědi či na skle je nejvěčnější; zůstává-li bronz černý a ošklivý, tato je plná rozmanitých a líbezných barev a nekonečné rozmanitosti; o čemž platí, co bylo řečeno výše. Kdybys chtěl mluvit jen o malbě provedené na desce, jsem ochoten vynést soud mezi ní a sochařstvím a říci takto: malířství je krásnější, má více fantazie a je bohatší, a sochařství je trvanlivější, a nic jiného nemá.","Ať sochařství s malou námahou ukáže, co se v malířství zdá zázračnou věcí: dát věcem nehmatatelným zdání hmatatelnosti, věcem plochým plastičnost, věcem blízkým dálku! Vskutku je malířství ozdobeno nekonečnými úvahami, jichž sochařství neužívá."],"ref":null,"ca":[]},{"id":"s473","o":"Paragone della pittura con la scultura","c":"","str":292,"ni":"II","nc":"Malířství a sochařství II","it":["La Scoltura non è scienza, ma arte meccanicissima, perchè genera sudore e fatica corporale al suo operatore, e solo bastano, a tale artista, le semplici misure de’ membri e la natura delli movimenti e posate, e così, in sè finisce, dimostrando all’occhio quel, che quello è, e non dà di sè alcuna ammirazione al suo contemplante, come fa la Pittura, che in una piana superfizie, pei forza di scienza, dimostra le grandissime campagne co’ lontani orizzonti."],"cs":["Sochařství není věda, nýbrž umění nanejvýš mechanické, neboť působí tomu, kdo je provozuje, pot a tělesnou námahu; a takovému umělci stačí prosté míry údů a povaha pohybů a postojů; a tak v sobě končí, ukazujíc oku to, co je, a nevzbuzuje v tom, kdo je nazírá, žádný obdiv, jako to činí malířství, které na rovné ploše silou vědy ukazuje převeliké roviny se vzdálenými obzory."],"ref":null,"ca":[]},{"id":"s474","o":"Paragone della pittura con la scultura","c":"","str":292,"ni":"III","nc":"Malířství a sochařství III","it":["Tra la Pittura e la Scoltura non trovo altra differenza, se non che lo scultore conduce le sue opere con maggior fatica di corpo, che il pittore, e il pittore conduce le opere sue con maggior fatica di mente.","Provasi così esser vero, conciossiachè lo scultore, nel fare la sua opera, fa per forza di braccia e di percussione a consumare il marmo o altra pietra soverchia, ch’eccede la figura, che dentro a quella si rinchiudo con esercizio meccanicissimo, accompagnato spesse volte da gran sudore, composto di polvere e convertito in fango, con la faccia impastata e tutto infarinato di polvere di marmo, che pare un fornaio, e coperto di minute scaglie, che pare gli sia fioccato addosso, e l’abitazione imbrattata e piena di scaglie e di polvere di pietre.","Il che tutto al contrario avviene al pittore, parlando di pittori e scultori eccellenti. Imperocchè il pittore con grande agio siede dinanzi alla sua opera, ben vestito, e muove il lievissimo pennello con li vaghi colori. È ornato di vestimenti come a lui piace, e è l’abitazione sua piena di vaghe pitture e pulita; e accompagnata spesse volte di musiche o lettori di varie e belle opere, le quali — sanza strepito di martelli o altro rumore misto — sono con gran piacere udite."],"cs":["Mezi malířstvím a sochařstvím nenacházím jiný rozdíl, než že sochař provádí svá díla s větší tělesnou námahou než malíř a malíř provádí svá díla s větší námahou ducha.","Že je tomu tak, se dokazuje takto: sochař při práci na svém díle musí silou paží a údery odstraňovat mramor nebo jiný nadbytečný kámen, který přesahuje postavu v něm uzavřenou, a to prací nanejvýš mechanickou, často provázenou velkým potem, smíšeným s prachem a proměněným v bláto, s tváří zamazanou a celý zaprášený mramorovým prachem, takže vypadá jako pekař, a pokrytý drobnými úlomky, jako by na něj napadal sníh; a příbytek má zašpiněný a plný úlomků a kamenného prachu.","S malířem se děje pravý opak – mluvím o vynikajících malířích a sochařích. Neboť malíř sedí v naprostém pohodlí před svým dílem, dobře oblečen, a pohybuje přelehkým štětcem s líbeznými barvami. Je oděn do šatů, jak se mu líbí, a jeho příbytek je plný líbezných maleb a čistý; a často je provázen hudbou nebo předčítači rozmanitých a krásných děl, jimž se – bez hřmotu kladiv či jiného smíšeného hluku – s velkým potěšením naslouchá."],"ref":{"s":"Lu","l":36,"st":"","z":false,"raw":"Lu. 36"},"ca":[]},{"id":"s475","o":"Paragone della pittura con la scultura","c":"","str":293,"ni":"IV","nc":"Malířství a sochařství IV","it":["Nessuna comparazione è dallo ingegno e artificio e discorso della Pittura a quello della Scoltura, che non s’impaccia della Prospettiva, causata dalla virtù della materia e non dall’artefice.","E se lo scultore dice non poter racconciare la materia levata di soperchio alla stia opera, come può il pittore; qui si risponde che quel che troppo leva, poco intende, e non è maestro. — Perchè se lui ha in potestà le misure, egli non leverà quello che non deve; adunque diremo tal difetto essere dell1 operatore e non della materia.","Ma di questi non parlo, perchè non sono maestri, ma guastatori di marmi.","Li maestri non si fidano nel giudizio dell’occhio, perchè sempre inganna, come prova, chi voi dividere una linea in due parti eguali, a giudizio di occhio, che spesso la sperienza lo inganna; onde per tale sospetto li buoni giudici sempre temono, il che non fanno l’ignoranti, e per questo, colla notizia della misura di ciascuna lunghezza, grossezza e larghezza de’ membri sempre si vanno al continuo governando, e così facendo, non levano più del dovere.","Ma la Pittura è di maraviglioso artificio, tutta di sottilissime speculazioni, delle quali in tutto la Scoltura n’è privata, per essere di brevissimo discorso.","Rispondesi allo scultore, che dice, che la sua scienza è più permanente che la Pittura, che tal permanenza è virtù della materia sculta e non dello scultore, e in questa parte lo scultore non se lo debbe attribuire a sua gloria, ma lasciarla alla natura, creatrice di tale materia."],"cs":["Není srovnání mezi důvtipem, umem a uvažováním malířství a sochařství, které se nezabývá perspektivou, ta je v něm způsobena vlastností hmoty, a ne umělcem.","A říká-li sochař, že nemůže napravit hmotu, kterou ze svého díla odebral nadbytečně, jak to může malíř, odpovídá se, že kdo ubere příliš, málo rozumí a není mistr. Neboť má-li v moci míry, neubere, co nemá; řekneme tedy, že taková vada je vadou tvůrce, a ne hmoty.","O takových však nemluvím, protože to nejsou mistři, nýbrž kaziči mramoru.","Mistři nedůvěřují úsudku oka, protože vždy klame, jak dokazuje ten, kdo chce rozdělit čáru na dvě stejné části od oka, neboť zkušenost ukazuje, že se často mýlí; proto z takového podezření se dobří soudci vždy obávají, což nevědomí nedělají; a proto se ustavičně řídí znalostí míry každé délky, tloušťky a šířky údů, a tak činíce, neuberou víc, než mají.","Avšak malířství je podivuhodným uměním, celé z nejjemnějších úvah, jichž je sochařství zcela zbaveno, neboť vyžaduje jen velmi krátké uvažování.","Sochaři, který říká, že jeho věda je trvalejší než malířství, se odpovídá, že tato trvalost je vlastností vytesané hmoty, a ne sochaře, a v této věci si ji sochař nemá přičítat ke své slávě, nýbrž přenechat ji přírodě, stvořitelce této hmoty."],"ref":null,"ca":[]},{"id":"s476","o":"Paragone della pittura con la scultura","c":"","str":295,"ni":"V","nc":"Malířství a sochařství V","it":["La Pittura è di maggior discorso mentale e di maggiore artificio e meraviglia che la Scoltura, perciocchè necessità costringe la mente del pittore a trasmutarsi nella propria mente di natura, e che sia interprete infra essa natura e l’arte, comentando con quella le cause delle sue dimostrazioni, costrette dalla sua legge; e in che modo le similitudini delli obbietti circostanti all’occhio concorrino colli veri simulacri alla popilla dell’occhio; e infra li obbietti eguali in grandezza quale si dimostrerà maggiore a esso occhio; e infra li colori eguali qual si dimostrerà più o meno oscuro o più o meno chiaro; e infra le cose di eguale bassezza quale si dimostrerà più o men bassa; o di quelle, che sono poste in altezza eguale, quale si dimostrerà più o meno alta; e delli obbietti eguali posti in varie distanze, perchè si dimostreranno men noti l’un che l’altro.","E tale arte abbraccia e restringe in sè tutte le cose visibili, il che far non può la povertà della Scoltura, cioè: li colori di tutte le cose e loro diminuzioni; questa figura le cose trasparenti, e lo scultore ti mostrerà le naturali, sanza suo artifizio; il pittore ti mostrerà varie distanze con variamenti del colore, dall’aria interposta fra li obbietti e l’occhio; egli le nebbie per le quali con difficoltade penetrano le spezie delli obbietti; egli le pioggie, che mostrano dopo se li nuvoli con monti e valli; egli la polvere, che mostrano in sè e dopo sè li combattenti di essa motori; egli li fumi più o meno densi; questo ti mostrerà li pesci scherzanti infra la superfizie delle acque e il fondo suo; egli le pulite ghiare con varî colori posarsi sopra le lavate arene del fondo de’ fiumi, circondati dalle ondeggianti erbe, dentro alla superfizie dell’acqua; egli le stelle in diverse altezze sopra di noi e così, altri innumerabili effetti, alli quali la Scoltura non aggiunge."],"cs":["Malířství vyžaduje víc duševního uvažování a víc umu a je podivuhodnější než sochařství, neboť nutnost nutí mysl malířovu, aby se proměnila v samu mysl přírody a byla tlumočnicí mezi přírodou a uměním, vykládajíc s ní příčiny jejích projevů, podřízených jejímu zákonu: jakým způsobem se podoby předmětů obklopujících oko sbíhají se skutečnými obrazy do zornice oka; a který z předmětů stejně velikých se oku ukáže větší; a která z barev stejných se ukáže více či méně tmavá nebo více či méně světlá; a která z věcí stejně nízko položených se ukáže více či méně nízko; nebo která z těch, jež jsou ve stejné výšce, se ukáže více či méně vysoko; a proč se předměty stejné, položené v různých vzdálenostech, ukáží jeden méně zřetelně než druhý.","A toto umění objímá a shrnuje v sobě všechny viditelné věci, čehož chudoba sochařství nedokáže: totiž barvy všech věcí a jejich slábnutí; ono zobrazuje věci průhledné, kdežto sochař ti ukáže věci přirozené bez vlastního umu; malíř ti ukáže různé vzdálenosti proměnami barvy, způsobenými vzduchem mezi předměty a okem; on mlhy, jimiž jen s obtíží pronikají obrazy předmětů; on deště, za nimiž se ukazují mraky s horami a údolími; on prach, v němž a za nímž se ukazují bojovníci, kteří jej zvířili; on dýmy více či méně husté; on ti ukáže ryby, jak si hrají mezi hladinou vod a jejich dnem; on uhlazené oblázky rozmanitých barev, jak spočívají na omytém písku na dně řek, obklopené vlnícími se bylinami pod hladinou vody; on hvězdy v různých výškách nad námi a tak i jiné nesčetné účinky, na něž sochařství nedosáhne."],"ref":null,"ca":[]},{"id":"s477","o":"Paragone della pittura con la scultura","c":"VI","str":296,"ni":"conclusione","nc":"Závěr","it":["Manca la Scoltura della bellezza de’ colori, manca della prospettiva de’ colori, manca della prospettiva e confusione de’ termini delle cose remote all’occhio, imperocchè cosi farà cognito li termini delle cose propinque, come delle remote; non farà l’aria, interposta, infra l’obbietto remoto e l’occhio, occupare più esso obbietto, come le figure velate, che mostrano la nuda carne sott’i veli, a quella anteposti; non farà la minuta ghiara di varî colori, sotto la superfizie delle trasparenti acque."],"cs":["Sochařství postrádá krásu barev, postrádá perspektivu barev, postrádá perspektivu a splývání obrysů věcí vzdálených oku, neboť učiní stejně zřetelnými obrysy věcí blízkých jako vzdálených; nedokáže, aby vzduch vložený mezi vzdálený předmět a oko zastíral tento předmět víc, jako zahalené postavy, které ukazují nahé tělo pod závoji, jež jsou před ně předloženy; nedokáže vytvořit drobné oblázky rozmanitých barev pod hladinou průzračných vod."],"ref":null,"ca":[]},{"id":"s478","o":"I paesi","c":"I","str":301,"ni":"un effetto di nubi sul lago maggiore","nc":"Mraky nad Lago Maggiore","it":["Io sono già stato a vedere tal multiplicaziono di arie, e già sopra a Milano, inverso lago Maggiore, vidi una nuvola in forma di grandissima montagna, piena di scogli infocati, perchè li raggi del sole, che già era all'orizzonte, che rosseggiava, la tigneano del suo colore. E questa tal nuvola attraeva a se tutti li nuvoli piccioli, che intorno le stavano; e la nuvola grande non si movea di suo loco, anzi riservò nella sua sommità il lume del sole insino a una ora e mezzo di notte, tant’era la sua immensa grandezza; e infra due ore di notte generò sì gran venti, che fu cosa stupenda e inaudita."],"cs":["Už jsem pozoroval takové hromadění vzduchu a jednou nad Milánem směrem k Lago Maggiore jsem viděl mrak v podobě převeliké hory, plné žhnoucích útesů, neboť paprsky slunce, které už bylo na obzoru a červenalo se, jej barvily svou barvou. A tento mrak přitahoval k sobě všechny malé mráčky, které kolem něho byly; a veliký mrak se nehnul ze svého místa, nýbrž uchoval na svém vrcholu světlo slunce až do půldruhé hodiny po setmění, tak nesmírná byla jeho velikost; a do dvou hodin po setmění zplodil tak veliké větry, že to bylo úžasné a neslýchané."],"ref":{"s":"R","l":1021,"st":"","z":false,"raw":"R. 1021"},"ca":[],"rr":"Leic. 28 a"},{"id":"s479","o":"I paesi","c":"II","str":302,"ni":"un’ascensione al monte rosa","nc":"Výstup na Monte Rosa","it":["Dico, l’azzurro, in che si mostra l’aria, non essere suo proprio colore, ma e causato da umidità calda, vaporata in minutissimi e insensibili atomi, la quale piglia dopo se la percussion de’ raggi solari, e tassi luminosa sotto la oscurità delle immense tenebre della regione del fuoco, che di sopra le fa coperchio.","E questo vedrà, come vid’io, chi andrà sopra Momboso, giogo dell’Alpi che dividono la Francia dalla Italia, la qual montagna ha la sua base che partorisce li quattro fiumi, che rigan per quattro aspetti contrari tutta l’Europa: e nessuna montagna ha la sua base in simile altezza.","Questa si leva in tanta altura, che quasi passa tutti li nuvoli, e raro volte vi cade neve, ma sol grandine di state, quando li nuvoli sono nella maggiore altezza; e questa grandine vi si conserva in modo, che, se non fosso la rarità del cadervi e del montarvi nuvoli, che non accade due volte in una età, egli vi sarebbe altissima quantità di diaccio, innalzato dalli gradi della grandine. Il quale di mezzo Luglio vi trovai grossissimo; e vidi l’aria sopra di me tenebrosa; e ’l sole, che percotea la montagna, essere più luminoso quivi assai, che nelle basse pianure, perchè minor grossezza d’aria s’interponea in fra la cima d’esso monte e ’l sole."],"cs":["Pravím, že modř, v níž se vzduch jeví, není jeho vlastní barvou, nýbrž je způsobena teplou vlhkostí, odpařenou v nejdrobnějších a nepostřehnutelných atomech, která přijímá za sebou úder slunečních paprsků a stává se světlou pod temnotou nesmírných temnot oblasti ohně, jež ji shora přikrývá jako víko.","A to uvidí, jak jsem to viděl já, ten, kdo vystoupí na Momboso, hřbet Alp, které oddělují Francii od Itálie; tato hora má úpatí, z něhož se rodí čtyři řeky, jež na čtyři protilehlé strany zavlažují celou Evropu; a žádná hora nemá své úpatí v takové výšce.","Tato hora se zvedá do takové výše, že přesahuje téměř všechny mraky, a sníh tam padá zřídka, nýbrž jen v létě kroupy, když jsou mraky v největší výšce; a tyto kroupy se tam uchovávají tak, že kdyby nebylo vzácnosti, s jakou tam padají a mraky tam stoupají, což se nestane ani dvakrát za lidský věk, byla by tam převeliká spousta ledu, navršeného z vrstev krup. Ten jsem tam v polovině července nalezl velmi silný; a viděl jsem vzduch nad sebou temný a slunce, které dopadalo na horu, tam mnohem jasnější než v nízkých rovinách, neboť mezi vrcholem té hory a sluncem se vkládala menší tloušťka vzduchu."],"ref":{"s":"R","l":300,"st":"","z":false,"raw":"R. 300"},"ca":[],"rr":"Leic. 4 a"},{"id":"s480","o":"I paesi","c":"III","str":303,"ni":"traccia","nc":"Osnova","it":["Descrivi i paesi con vento e con acqua, e con tramontare e levare del sole."],"cs":["Popiš krajiny s větrem a s vodou a se západem a východem slunce."],"ref":{"s":"R","l":471,"st":"","z":false,"raw":"R. 471"},"ca":[],"rr":"Br. M. 172 b"},{"id":"s481","o":"I paesi","c":"IV","str":303,"ni":"altra traccia","nc":"Jiná osnova","it":["Descrivi uno vento terrestre e marittimo, descrivi una pioggia."],"cs":["Popiš vítr na pevnině a na moři, popiš déšť."],"ref":{"s":"R","l":605,"st":"","z":false,"raw":"R. 605"},"ca":[],"rr":"Br. M. 169 a"},{"id":"s482","o":"I paesi","c":"V","str":303,"ni":"varie colorazioni del mare","nc":"Rozmanité zbarvení moře","it":["Il mare ondeggiante non ha colore universale, ma chi lo vede di terra ferma, è di colore oscuro, e tanto più oscuro, quant’egli è più vicino all’orizzonte, e vedevi alcuni chiarori over lustri, che si movono con tardità a uso di pecore bianche nelli armenti; e chi vede il mare stando in alto mare lo vede azzurro. E questo nasce, che da terra il mare pare oscuro, perchè tu vedi in lui l’onde, che specchiano la oscurità della terra; e d’alto mare paiono azzurre, perche tu vedi nell’onde l’aria azzurra, da tali onde specchiata."],"cs":["Zvlněné moře nemá jednotnou barvu; ale tomu, kdo je vidí z pevniny, je tmavé, a tím tmavší, čím je blíže obzoru, a vidíš na něm jakési světlé záblesky čili lesky, které se pomalu pohybují jako bílé ovce ve stádech; a kdo vidí moře na širém moři, vidí je modré. A to vzniká tím, že z pevniny se moře zdá tmavé, protože v něm vidíš vlny, které zrcadlí temnotu země; a na širém moři se vlny zdají modré, protože ve vlnách vidíš modrý vzduch, který se v nich zrcadlí."],"ref":{"s":"Lu","l":237,"st":"","z":false,"raw":"Lu. 237"},"ca":[]},{"id":"s483","o":"I paesi","c":"VI","str":304,"ni":"la vegetazione di un colle","nc":"Vegetace pahorku","it":["Quell’erbe e piante saranno di color tanto più pallido, quanto il terreno che le nutrisce è più magro e carestioso d’umore: il terreno è più carestioso e magro sopra li sassi, di che si compongono li monti. E li alberi saranno tanto minori e più sottili, quanto essi si fanno più vicini alla sommità de’ monti: e il terreno è tanto più magro, quanto s’avvicina più alle predette sommità de’ monti; e tanto più abbondante il terreno è di grassezza, quanto esso è più propinquo alle concavità delle valli.","Adunque tu, pittore, mostrerai nelle sommità de’ monti li sassi, di che esso si compone, in gran parte scoperti di terreno, e l’erbe, che vi nascono, minute e magre e in gran parte impallidite e secche, per carestia d’umore, e l’arenosa e magra terra si veda trasparire infra le pallide erbe; e le minute piante, stentate e invecchiate in minima grandezza, con corte e spesse ramificazioni e con poche foglie, scoprendo in gran parte le rugginenti e aride radici, tessute con le falde e rotture delli rugginosi scogli, nate dalli ceppi, storpiati dalli uomini e da’ venti; e in molte parti si vegga li scogli superare li colli de li alti monti, vestiti di sottile e pallida ruggine; e in alcuna parte dimostrare li lor veri colori scoperti, mediante la percussione delle folgori del cielo, il corso delle quali, non sanza vendetta di tali scogli, spesso son impedite.","E quanto più discendi alle radici de’ monti, le piante saranno più vigorose e spesse di rami e di foglie; e le lor verdure di tante varietà, quanto sono le specie delle piante, di che tal selve si compongono, delle quali la ramificazione è con diversi ordini e diverse spessitudini di rami e di foglie e diverse figure e altezze: e alcuni con istrette ramificazioni, come il cipresso; e similmente degli altri con ramificazioni sparse e dilatabili, com’è la quercia e il castagno e simili; alcuni con minutissime foglie; altri con rare, coni’ è il ginepro e ’l platano e simili; alcune quantità di piante, insieme nate, divise da diverse grandezze di spazi e altre unite, sanza divisioni di parti o altri spazi."],"cs":["Byliny a rostliny budou mít barvu tím bledší, čím je půda, která je živí, chudší a nuznější na vláhu; a půda je nejnuznější a nejchudší na skalách, z nichž se skládají hory. A stromy budou tím menší a tenčí, čím blíže se dostávají k vrcholům hor; a půda je tím chudší, čím více se blíží k řečeným vrcholům hor; a tím bohatší na úrodnost je půda, čím je blíže prohlubním údolí.","Ty tedy, malíři, ukážeš na vrcholech hor skály, z nichž se skládají, z velké části obnažené od půdy, a byliny, které tam rostou, drobné a hubené a z velké části zbledlé a suché pro nedostatek vláhy; a ať je mezi bledými bylinami vidět prosvítat písčitou a hubenou zemi; a drobné rostlinky, zakrslé a zestárlé v nepatrné velikosti, s krátkými a hustými větvemi a s málo listy, odhalující z velké části rezavé a vyprahlé kořeny, propletené s vrstvami a puklinami rezavých útesů, vyrůstající z pařezů zmrzačených lidmi a větry; a na mnoha místech ať je vidět útesy převyšující pahorky vysokých hor, oděné tenkou a bledou rzí, a místy ukazující své pravé barvy, odhalené údery nebeských blesků, jejichž běh tyto útesy často zadržují, ne bez pomsty na sobě.","A čím více sestupuješ k úpatí hor, tím budou rostliny statnější a hustší ve větvích a listech; a jejich zeleň bude tak rozmanitá, kolik je druhů rostlin, z nichž se tyto lesy skládají; jejich větvení má různé uspořádání a různou hustotu větví a listů a různé tvary a výšky: některé mají úzké větvení jako cypřiš, a podobně jiné mají větvení rozložité a rozpínavé, jako dub, kaštan a podobné; některé mají nejdrobnější listy, jiné řídké, jako jalovec, platan a podobné; některé skupiny rostlin, vyrostlé pospolu, jsou odděleny různě velkými mezerami, a jiné jsou spojené, bez rozdělení na části či jiných mezer."],"ref":{"s":"Lu","l":806,"st":"","z":false,"raw":"Lu. 806"},"ca":[]},{"id":"s484","o":"I paesi","c":"VII","str":306,"ni":"del modo del figurare una notte","nc":"Jak zobrazit noc","it":["Quella cosa ch’è privata interamente di luce è tutta tenebre. Essendo la notte in simile condizione, e tu vi vogli figurare una storia, farai che, sendovi ’l grande foco, che quella cosa ch’è più propinqua di detto foco più si tinga nel suo colore, perchè quella cosa ch’è più vicina all’obbietto, più partecipa della sua natura. E facendo il foco pendere in colore rosso, farai tutte le cose alluminate da quello ancora loro rosseggiare e quelle che sono più lontane a detto foco più sien tinte del colore nero della notte. Le figure, che sono fra te e ’l foco, appariscano scure nella oscurità della notte e non della chiarezza del foco, e quelle che si trovano dai lati sieno mezze oscure e mezze rosseggianti, e quelle che si possono vedere dopo i termini delle fiamme saranno tutte alluminate di rosseggiante lume in campo nero.","In quanto alli atti, farai quelli che li sono presso, farsi scudo colle mani e con mantegli, a riparo del superchio calore, e, torto col volto in contraria parte, mostrare fuggire da quelli più lontani; farai gran parte di loro farsi colle mani riparo al li occhi offesi da superchio splendore."],"cs":["Věc, která je zcela zbavena světla, je celá tmou. Je-li noc v takovém stavu a chceš-li v ní zobrazit výjev, učiníš, aby tam byl velký oheň a aby se věc nejbližší tomuto ohni nejvíce zbarvila jeho barvou, neboť věc, která je předmětu nejblíže, má nejvíce účast na jeho povaze. A když necháš oheň hrát do červena, učiníš, aby se i všechny věci jím osvětlené červenaly, a ty, které jsou od řečeného ohně vzdálenější, ať jsou více zbarveny černou barvou noci. Postavy, které jsou mezi tebou a ohněm, ať se jeví tmavé temnotou noci, a ne ozářené jasem ohně; a ty, které jsou po stranách, ať jsou napůl tmavé a napůl červenající; a ty, které lze vidět za okraji plamenů, budou celé osvětleny červeným světlem na černém pozadí.","Co se týče postojů, učiníš, aby se ti, kdo jsou blízko, chránili rukama a plášti před přílišným žárem a s tváří odvrácenou na opačnou stranu ukazovali, že prchají; ty vzdálenější učiníš z velké části tak, že si rukama chrání oči oslněné přílišným jasem."],"ref":{"s":"Ash.I.A","l":8,"st":"v","z":false,"raw":"Ash. I. A 8 v"},"ca":[]},{"id":"s485","o":"I paesi","c":"VIII","str":307,"ni":"come si dee figurar una fortuna","nc":"Jak se má zobrazit bouře","it":["Se vuoi figurare bene una fortuna, considera e poni bene i sua effetti, quando il vento, soffiando sopra la superfizie del mare e della terra, rimove e porta con seco quelle cose, che non sono ferme, colla universal marea.","E per ben figurare questa fortuna, farai in prima i nuvoli spezzati e rotti dirizzarsi per lo corso del vento, accompagnati dall’arenosa polvere, levata da’ liti marini, e rami e foglie levati per la potenza del furore del vento, isparsi per l’aria, e in compagnia di quelle molte altre leggere cose. Li alberi e l’erbe piegate a terra quasi mostrarsi volere seguire il corso dei venti, coi rami storti fuor del naturale corso e le scompigliate e racconciate foglie. Gli omini, che lì si trovano, parte caduti e rivolti per li panni e per la polvere, quasi sieno sconosciuti; e quelli, che restano ritti, sieno dopo qualche albero abbracciati a quelli, perchè il vento non li strascini; altri con le mani a li occhi per la polvere, chinati a terra, e i panni e capegli diretti al corso del vento. Il mare turbato e tempestoso sia pieno di retrosi, e schiuma in fra le elevate onde, e ’l vento levare infra la combattuta aria della schiuma più sottile a uso di spessa e avviluppata nebbia. I navilî, che dentro vi sono, alcuni ve ne farai con la vela rotta, e i brani d’essa ventilando infra l’aria in compagnia d’alcuna corda rotta; alcuni alberi rotti, caduti, col navilio intraversato e rotto infra le tempestose onde; certi omini gridanti abbracciare il rimanente del navilio; farai i nuvoli cacciati dagl’impetuosi venti, battuti nell’alte cime delle montagne, fare a quegli avviluppati retrosi, a similitudine dell’onde percosse nelli scogli. L’aria spaventosa per le oscure tenebre fatte nell’aria dalla polvere, nebbia e nuvoli folti."],"cs":["Chceš-li dobře zobrazit bouři, uvaž a dobře podej její účinky, kdy vítr, vanoucí nad hladinou moře a země, odstraňuje a nese s sebou ty věci, které nejsou pevné, spolu s celým mořským přívalem.","A abys dobře zobrazil tuto bouři, učiníš nejprve roztrhané a rozervané mraky, jak se ženou ve směru větru, provázeny písčitým prachem, zdviženým z mořských břehů, a větve a listí, zdvižené silou zuřícího větru a roztroušené vzduchem, a s nimi mnoho jiných lehkých věcí. Stromy a byliny ať jsou ohnuty k zemi, jako by chtěly následovat běh větrů, s větvemi zkroucenými mimo přirozený směr a s listím rozcuchaným a obráceným. Lidé, kteří se tam nacházejí, ať jsou zčásti popadaní a zamotaní do šatů a zaprášení, až skoro k nepoznání; a ti, kdo zůstali stát, ať se za nějakým stromem drží v objetí, aby je vítr neodvlekl; jiní s rukama u očí kvůli prachu, sehnutí k zemi, a šaty a vlasy obrácené ve směru větru. Rozbouřené a bouřlivé moře ať je plné vírů a pěny mezi vzedmutými vlnami a ať vítr zvedá do rozbouřeného vzduchu tu nejjemnější pěnu jako hustou a spletenou mlhu. Z lodí, které jsou na moři, učiníš některé s roztrženou plachtou a její cáry vlající ve vzduchu spolu s nějakým přetrženým lanem; některé stěžně zlomené, padlé, s lodí převrácenou napříč a rozbitou mezi bouřlivými vlnami; nějaké lidi s křikem objímající zbytky lodi; učiníš mraky hnané prudkými větry, jak naráží na vysoké vrcholy hor a tvoří tam spletené víry, podobně jako vlny tříštící se o útesy. Vzduch ať je hrozivý temnotou, kterou ve vzduchu tvoří prach, mlha a husté mraky."],"ref":{"s":"Ash.I","l":21,"st":"r","z":false,"raw":"Ash. I. 21 r"},"ca":[]},{"id":"s486","o":"I paesi","c":"IX","str":308,"ni":"modo di figurare una battaglia","nc":"Jak zobrazit bitvu","it":["Farai in prima il fumo dell’artiglieria, mischiato in fra l’aria, insieme con la polvere, mossa dal movimento de’ cavalli e de’ combattitori. La quale mistione userai così: la polvere, perchè è cosa terrestre e ponderosa, e ben che per la sua sottilità facilmente si levi e mischi infra l’aria, niente di meno volentieri ritorna in basso, e il suo sommo montare è fatto dalla parte più sottile, adunque il meno fia veduta, e parrà quasi di colore d’aria; il fumo, che si mischia in fra l’aria impolverata, quanto più s’alza a certa altezza, parrà oscura nuvola, e vederassi ne le sommità più espeditamente il fumo, che la polvere.","Il fumo penderà in colore alquanto azzurro, e la polvere terrà il suo colore: dalla parte che viene il lume, parrà questa mistione d’aria, fumo e polvere molto più lucida, che dalla opposita parte; i combattitori quanto più fieno infra detta turbolenza, meno si vedranno e meno differenza fia dai loro lumi alle loro ombre.","Farai rosseggiare i volti e le persone e l’aria e li scoppettieri insieme co’ vicini, e detto rossore quanto più si parte dalla sua cagione, più si perda; e le figure, che sono in fra te e ’l lume, essendo lontane, parranno scure in campo chiaro, e le loro gambe, quanto più s’apresseran alla terra, men fieno vedute, perchè la polvere è li più grossa e più spessa.","E se farai cavalli correnti fuori della turba, falli nuvoletti di polvere distanti l’uno dall’altro, quanto po’ essere lo ’ntervallo de’ salti fatti dal cavallo, e quello nuvolo, ch’è più lontano da detto cavallo, men si vegga, anzi sia alto, sparso e raro, e più presso sia più evidente e minore e più denso.","L’aria sia piena di saettume di diverse ragioni: chi monti, chi discenda, qual sia per linea piana; e le ballotte delli scoppietti sieno accompagnate d’alquanto fumo dirieto al lor corso.","E le prime figure farai polverose, i capegli e ciglia e altri lochi piani, atti a sostenere la polvere. Farai i vincitori correnti co’ capegli, e altre cose leggiere, sparse al vento: con le ciglia basse e’ caccia i contrari membri innanzi, cioè se manderà’ innanzi il piè destro che ’l braccio stanco ancor lui venga innanzi. E se farai alcuno caduto fara’gli il segno dello sdrucciolare su per la polvere, condotto in sanguinoso fango, e dintorno alla mediocre liquidezza della terra farai vedere istampite le pedate degli omini e cavalli di lì passati.","Farai alcuno cavallo strascinare morto il suo signore, e dirieto a quello lasciare per la polvere e fango il segno dello strascinato corpo; farai li vinti e battuti pallidi colle ciglia alte nella lor congiunzione, e la carne,, che resta sopra loro, sia abbondante di dolenti crespe. Le fauci del naso sieno con alquante grinze partite in arco dalle narici e terminate nel principio dell’occhio; le narici alte, cagion di dette pieghe; le labbra arcate scoprano i denti di sopra. I denti spartiti in modo di gridare con lamento. L’una delle mani faccia scudo ai paurosi occhi, voltando il dirieto inverso il nimico, l’altra stia a terra a sostenere il levato busto. Altri farai gridanti colla bocca sbarrata e fuggenti; fara’ molte sorte d’arme in fra i piedi de’ combattitori come scudi rotti, lancie, spade rotte, altre simili cose; farai omini morti, alcuni ricoperti mezzi dalla polvere, altri tutta la polvere, che si mischia coll’uscito sangue, convertirsi in rosso fango, e vedere il sangue del su’ colore correre con torto corso dal corpo alla polvere; altri morendo strignere i denti o travolgere gli occhi, strignere le pugna alla persona e le gambe storte. Potrebbesi vedere alcuno disarmato e abbattuto dal nemico volgersi al nemico, con morsi e graffi fare crudele e aspra vendetta; potresti vedere alcuno cavallo leggero correre coi crini sparsi al vento, correre in fra i nemici, e co’ piedi fare molto danno; vedresti alcuno storpiato, caduto in terra farsi copritura col suo scudo, e ’l nemico, chinato in basso, fare forza di dare morte a quello.","Potrebbesi vedere molti omini caduti in un gruppo sopra uno caval morto. Vederai alcuni vincitori lasciare il combattere e uscire dalla moltitudine nettandosi co le due mani li occhi e le guancie ricoperte di fango, fatte da lagrimare degli occhi per l’amor della polvere. Vederesti le squadre del soccorso stare pien di speranza e sospetto, co’ le ciglia aguzze, facendo a quelle ombra con le mani, e riguardare infra la folta e confusa caligine dell’essere attenti al comandamento del capitano; e simile, il capitano col bastone levato e corrente inverso il soccorso, mostrare a quelli la parte dove di loro è carestìa; e alcun fiume dentro cavalli correnti riempiendo la circustante acqua di turbolenza di onde di schiuma e d’acqua confusa, saltante infra l’aria e tra le gambe e corpi de’ cavalli. E non fare nessun loco piano, se non le pedate ripiene di sangue."],"cs":["Učiníš nejprve dým dělostřelectva, smíšený se vzduchem spolu s prachem, zvířeným pohybem koní a bojovníků. Tuto směs podáš takto: prach, protože je věcí zemitou a těžkou, a ačkoli se pro svou jemnost snadno zvedá a mísí se vzduchem, přece se ochotně vrací dolů, a nejvýše stoupá jeho nejjemnější část; ta tedy bude nejméně vidět a bude se zdát téměř barvy vzduchu. Dým, který se mísí se zaprášeným vzduchem, se bude zdát tím víc tmavým mrakem, čím výše vystoupí do jisté výšky, a ve výškách bude dým vidět zřetelněji než prach.","Dým bude hrát poněkud do modra a prach si zachová svou barvu; ze strany, odkud přichází světlo, se bude tato směs vzduchu, dýmu a prachu zdát mnohem jasnější než ze strany protější; bojovníci, čím dále budou v této vřavě, tím méně budou vidět a tím menší bude rozdíl mezi jejich světly a stíny.","Učiníš, aby se červenaly tváře a postavy a vzduch i střelci z ručnic spolu s těmi, kdo jsou poblíž; a tato červeň ať se tím více ztrácí, čím více se vzdaluje od své příčiny; a postavy, které jsou mezi tebou a světlem, budou-li vzdálené, se budou zdát tmavé na světlém pozadí, a jejich nohy, čím blíže budou zemi, tím méně budou vidět, neboť prach je tam hrubší a hustší.","A učiníš-li koně vybíhající z davu, udělej jim obláčky prachu vzdálené jeden od druhého tak, jak velký může být rozestup koňových skoků; a ten oblak, který je od řečeného koně nejdále, ať je nejméně vidět, nýbrž ať je vysoko, rozptýlený a řídký, a ten bližší ať je zřetelnější, menší a hustší.","Vzduch ať je plný šípů různého druhu: jeden ať stoupá, jiný klesá, jiný letí vodorovně; a kule z ručnic ať provází za jejich letem trochu dýmu.","A postavy v popředí učiníš zaprášené ve vlasech, v obočí a na jiných rovných místech, schopných prach udržet. Vítěze učiníš běžící, s vlasy a jinými lehkými věcmi rozevlátými ve větru, se staženým obočím; a ať vysunují vpřed protilehlé údy, totiž vysune-li vpřed pravou nohu, ať jde vpřed i levá paže. A učiníš-li někoho padlého, udělej mu stopu po uklouznutí v prachu, proměněném v krvavé bláto; a kolem v napůl rozbředlé zemi ukážeš otisky šlépějí lidí a koní, kteří tudy prošli.","Učiníš nějakého koně, jak vleče svého mrtvého pána a zanechává za sebou v prachu a blátě stopu vlečeného těla; poražené a pobité učiníš bledé, s obočím zdviženým u kořene nosu, a kůže nad ním ať je plná bolestných vrásek. Strany nosu ať mají několik vrásek, které obloukem vycházejí od chřípí a končí u začátku oka; chřípí zdvižené, což je příčinou řečených záhybů; rty prohnuté do oblouku ať odhalují horní zuby; zuby rozevřené jako při nářku a křiku. Jedna z rukou ať je štítem vystrašeným očím a obrací hřbet k nepříteli, druhá ať je na zemi a podpírá zdvižený trup. Jiné učiníš křičící s doširoka otevřenými ústy a prchající; učiníš mnoho druhů zbraní mezi nohama bojovníků, jako rozbité štíty, kopí, zlomené meče a jiné podobné věci; učiníš mrtvé, některé napůl zasypané prachem, u jiných ať se všechen prach, mísící se s vyteklou krví, mění v rudé bláto, a ať je vidět krev její barvy, jak křivolace stéká z těla do prachu; jiní ať v umírání zatínají zuby nebo převracejí oči, tisknou pěsti k tělu a mají zkroucené nohy. Bylo by možné vidět někoho odzbrojeného a nepřítelem sraženého, jak se k nepříteli obrací a kousáním a škrábáním vykonává krutou a trpkou pomstu; mohl bys vidět nějakého lehkého koně, jak běží s hřívou rozevlátou ve větru, běží mezi nepřátele a kopyty působí velkou škodu; viděl bys nějakého zmrzačeného, padlého na zem, jak se kryje svým štítem, a nepřítele, sehnutého dolů, jak se snaží jej usmrtit.","Bylo by možné vidět mnoho lidí padlých v jednom chumlu na mrtvém koni. Uvidíš některé vítěze, jak opouštějí boj a vycházejí z množství, utírajíce si oběma rukama oči a tváře pokryté blátem, které vzniklo slzením očí kvůli prachu. Viděl bys zálohy, jak stojí plny naděje i obav, s přimhouřeným obočím, zastiňujíce si je rukama, a hledí do husté a zmatené mlhy, pozorny k rozkazu velitele; a podobně velitele, jak se zdviženou holí běží k záloze a ukazuje jí místo, kde je jí třeba; a nějakou řeku a v ní cválající koně, jak plní okolní vodu zmítáním vln, pěny a zvířené vody, která stříká do vzduchu a mezi nohy a těla koní. A nedělej žádné místo rovné, leda šlépěje plné krve."],"ref":{"s":"Ash.I","l":30,"st":"v","z":false,"raw":"Ash. I. 30 v"},"ca":[]},{"id":"s487","o":"I paesi","c":"X","str":313,"ni":"figurazione del diluvio","nc":"Zobrazení potopy","it":["L’aria era oscura per la spessa pioggia, la qual, con obbliqua discesa, piegata dal trasversal corso de’ venti, faceva onde di sè per l’aria, non altrementi che far si vegga alla polvere, ma sol si variava perchè tale innondazicne era traversata dalli liniamenti, che fanno le gocciole dell’acqua, che discende. Ma il colore suo era dato dal fuoco, generato dalle saette fenditrici e squarciatrici delli nuvoli, i vampi delle quali percoteano e aprivano li gran pelaghi delle riempiute valli, li quali aprimenti mostravano nelli lor vertici le piegate cime delle piante. E Nettuno si vedea in mezzo alle acque col tridente, e vedeasi Eolo colli sua venti ravvilluppare notanti piante diradicate, miste colle immense onde.","L’orizzonte, con tutto lo emisperio, era turbo e focoso, per le ricevute vampe delle continue’ saette. Vedevansi li omini e li uccelli, che riempivan di sè li grandi alberi, scoperti dalle dilatate onde, componitrici delli colli, circondatori delli gran baratri."],"cs":["Vzduch byl temný hustým deštěm, který šikmým pádem, ohýbaný příčným během větrů, tvořil ve vzduchu vlny, nejinak než jak to lze vidět u prachu; jen se lišil tím, že tento příval byl protínán čarami, které tvoří kapky padající vody. Ale jeho barvu mu dával oheň, zrozený blesky, jež štípaly a rozdíraly mraky; jejich výšlehy dopadaly na veliká jezera zaplavených údolí a otevíraly je, a tato rozevření ukazovala ve svých hlubinách ohnuté vrcholky stromů. A Neptun byl vidět uprostřed vod s trojzubcem a bylo vidět Aiola, jak se svými větry zamotává plovoucí vykořeněné stromy, smíšené s nesmírnými vlnami.","Obzor s celou polokoulí byl kalný a ohnivý od výšlehů neustálých blesků. Bylo vidět lidi a ptáky, kteří sebou naplňovali veliké stromy, jež vyčnívaly nad rozlité vlny, tvořící pahorky kolem velikých propastí."],"ref":{"s":"G","l":6,"st":"v","z":false,"raw":"G. 6 v"},"ca":[]},{"id":"s488","o":"I paesi","c":"XI","str":314,"ni":"segue","nc":"Pokračování","it":["Vedeasi la oscura e nebulosa aria essere combattuta dal corso di diversi venti, e avviluppati dalla continua pioggia e misti colla gragnuola, li quali or qua ora là portavano infinita ramificazione delle stracciate piante, miste con infinite foglie. Dintorno vedeasi le antiche piante diradicate e stracciate dal furor de’ venti. Vedovasi le ruine de’ monti, già scalzati dal corso de’ lor fiumi, minare sopra i medesimi fiumi e chiudere le loro valli; li quali fiumi ingorgati allagavano, e sommergevano le moltissime terre, colli lor popoli.","Ancora avresti potuto vedere, nelle sommità di molti monti, essere insieme ridotte molte varie spezie d’animali, spaventati e ridotti al fin dimesticamente, in compagnia de’ fuggiti omini e donne colli lor figlioli. E le campagne coperte d’acqua mostravan le sue onde in gran parte coperte di tavole, lettiere, barche, altri vari strumenti, fatti dalla necessità e paura della morte, sopra li quali eran donne, omini colli lor figlioli misti, con diverse lamentazioni e pianti, spaventati dal furor de’ venti, li quali con grandissima fortuna rivolgevan l’acque sottosopra insieme colli morti, da quella annegati. E nessuna cosa più lieve che l’acqua era che non fussi coperta di diversi animali, i quali, fatti tregua, stavano insieme con paurosa collegazione, infra’ quali eran lupi, volpi, serpi e d’ogni sorte, fuggitori dalla morte. E tutte l’onde percuotitrici de’ lor lidi, combattevan quelli, colle varie percussioni di diversi corpi annegati, le percussioni de’ quali uccidevano quelli, alli quali era restato vita.","Alcune congregazioni d’omini avresti potuti vedere, le quali con armata mano difendevano li piccioli siti, che loro eran rimasti, da lioni, lupi e animali rapaci, che quivi cercavan lor salute. Oh! quanti romori spaventevoli si sentivan per l’aria scura, percossa dal furore de’ tuoni e delle folgori, da quelli scacciate, — che per quella rugosamente scorrevano, percotendo ciò che s’opponea al suo corso! Oh! quanti avresti veduti colle proprie mani chiudersi li orecchi per schifare l’immensi romori, fatti per la tenebrosa aria dal furore de’ venti misti con pioggia, tuoni celesti e furore di saette!","Altri, non bastando loro il chiudere delli, occhi, ma colle proprie mani ponendo quelle l’una sopra dell’altra, più se li coprivano, per non vedere il crudele strazio fatto della umana spezie dall’ira di Dio. - Oh! quanti lamenti e quanti spaventati si gettavano dalli scogli! Vedeasi le grandi ramificazioni delle gran quercie, cariche d’omini, esser portate per l’aria dal furore delli impetuosi venti.","Quante eran le barche volte sotto sopra, e quelle intere e quelle in pezzi esservi sopra gente, travagliandosi per loro scampo, con atti e movimenti dolorosi, pronosticanti di spaventevole morte. Altri con movimenti disperati si toglievano la vita, disperandosi di non potere sopportare tal dolore: de’ quali alcuni si gittavano dalli alti scogli, altri si stringevano la gola colle proprie mani, alcuni pigliavan li propri figlioli, e con grande rapidità li sbattevan interi, alcuni colle proprie sue armi si ferivano e uccidean sè medesimi, altri gittandosi ginocchioni si raccomandavan a Dio. Oh! quante madri piangevano i sua annegati figlioli, quelli tenendo sopra le ginocchia, alzando le braccia aperte in verso il cielo, e con voci, composte di diversi urlamenti, riprendevan l’ira delli Dei; altri, colle man giunte e le dita insieme tessute, mordevano, e con sanguinosi morsi quel divoravan, piegandosi col petto alle ginocchia per lo immenso e insopportabile dolore.","Vedeansi li armenti delli animali, come cavalli, buoi, capre, pecore, esser già attorniati dalle acque e essere restati in isola nell’alte cime de’ monti, già restrigniersi insieme, e quelli del mezzo elevarsi in alto, e camminare sopra delli altri, e fare infia loro gran zuffe, de’ quali assai ne morivan per carestia di cibo.","E già li uccelli si posavan sopra li omini e altri animali, non trovando più terra scoperta che non fusse occupata da’ viventi; già la fame, ministra della morte, avea tolto la vita a gran parte delli animali; quando li corpi morti già levificati si levavano dal fondo delle profonde acque e surgevano in alto. E infra le combattenti onde, sovra le quali si sbattevano l’un nell’altro, e, come balle piene di vento, risaltavan indirieto dal sito della lor percussione, questi si facevan base de’ predetti morti. E sopra queste maledizioni si vedea l’aria coperta di oscuri nuvoli, divisi dalli serpeggianti moti delle infuriate saette del cielo, alluminanti or qua or là infra la oscurità delle tenebre.","Vedesi il moto dell’aria mediante il moto della polvere, mossa dal corso del cavallo, il moto della quale è tanto veloce a riempiere il vacuo, che di sè lascia nell’aria, che di se lo vestiva, quanto è la velocità di tal cavallo a fuggirsi dalla predetta aria.","E ti parrà forse potermi riprendere dell’avere io figurato le vie fatte per l’aria dal moto del vento, conciò sia che ’l vento per se non si vede infra l’aria. A questa parte si risponde, che non il moto del vento, ma il moto delle cose da lui portate è sol quel che per l’aria si vede.","Tenebre, vento, fortuna di mare, diluvio d’acqua, selve infocate, pioggia, saette del cielo, terremoti e ruina di monti, spianamenti di città.","Venti revertiginosi, che portano acqua, rami di piante e omini infra l’aria.","Rami stracciati da’ venti, misti col corso de’ venti, con gente di sopra.","Piante rotte, cariche di gente.","Navi rotte in pezzi, battute in iscogli.","Delli armenti, grandine, saette, venti revertiginosi.","Gente che sien sopra piante, che non si posson sostenere, alberi e scogli, torri, còlli pien di gente, barche, tavole, madie e altri strumenti da natare, còlli coperti d’uomini e donne o animali, e saette da’ nuvoli, che alluminino le cose.","Sia imprima figurata la cima d’un aspro monte con alquanta valle circustante alla sua base, e ne’ lati di questo si veda la scorza del terreno levarsi insieme colle minute radici di piccoli sterpi, e spogliar di sè gran parte delli circonstanti scogli; rovinosa discenda di tal dirupamento; con turbolenza del corso vada percuotendo e scalzando le ritorte e globulenti radici delle gran piante, e quelle ruinando sotto sopra. E le montagne, denudandosi, scoprano le profonde fessure, fatte in quelle dalli antichi terremoti; e li piedi delle montagne sieno in gran parte rincalzati e vestiti delle ruine delli arbusti precipitati da’ lati dell’alte cime de’ predetti monti, i quali sien misti con fango, radici, rami d’alberi, con diverse foglie, infuse infra esso fango e terra e sassi.","E le ruine d’alcuni monti sien discese nella profondità d’alcuna valle, e facciansi argine della ringorgata acqua del suo fiume, la quale argine, già rotta, scorra con grandissime onde, delle quali le massime percuotino, e ruinino le mura delle città e ville di tal valle. E le ruine degli alti edifizì delle predette città levino gran polvere, l’acqua si levi in alto in forme di fumo, ed in ravviluppati, nuvoli si movano contro alla discendente pioggia.","Ma la ringorgata acqua si vada raggirando pel pelago, che dentro a sè la rinchiude, e con ritrosi revertiginosi in diversi obbietti, percuotendo e risaltando in aria colla fangosa schiuma, poi ricadendo e facendo riflettere in aria l’acqua percossa. E le onde circolari, che si fuggono dal loco della percussione, camminando col suo impeto in traverso, sopra del moto dell’altre onde circolari, che contra di loro si muovono, e, dopo la fatta percussione, risalgano in aria, sanza spiccarsi dalle lor basi.","E all’uscita, che l’acqua fa di tal pelago, si vede le disfatte onde distendersi inverso la loro uscita, dopo la quale, cadendo over discendendo infra l’aria, acquista peso e moto impetuoso, dopo il quale, penetrando la percossa acqua, quella apre, e penetra con furore alla percussione del fondo, dal quale poi riflettendo, risalta inverso la superfizie del pelago, accompagnata dall’aria, che con lei si sommerse, e questa resta nella uscita colla schiuma, mista con legnami e altre cose più lievi che l’acqua, intorno alle quali si dà principio all’onde, che tanto più crescono in circuito, quanto più acquistano di moto: il qual moto le fa tanto più basse quanto ell’acquistano più larga base, e per questo sono poco evidenti nel lor consumamento. Ma, se l’onde ripercotono in vari obbietti, allora elle risaltano indirieto sopra l’avvenimento dell’altre onde, osservando l’accrescimento della medesima curvità, ch’ell’avrebbero acquistato nell’osservazione del già principiato moto.","Ma la pioggia nel discendere de’ sua nuvoli è del medesimo color d’essi nuvoli, cioè della sua parte ombrosa, se già li razzi solari non li penetrassino: il che se così fusse, la pioggia si dimostrerebbe di minore oscurità che esso nuvolo. E se li gran pesi delle massime ruine delli gran monti o d’altri magni edifizi, in lor ruine, percuoteranno li gran pelaghi dell’acque, allora risalterà gran quantità d’acqua infra l’aria, il moto della quale sarà fatto per contrario aspetto a quello che fece il moto del percussore dell’acque, cioè l’angolo della riflession, e fia simile all’angolo della incidenza.","Delle cose portate dal corso delle acque, quella si discosterà più dalle opposite rive, che fia più grave over di maggior quantità. Li ritrosi delle acque nelle sue parti sono tanto più veloci, quanto elle son più vicine al suo centro. La cima delle onde del mare discende dinanzi alle lor basi, battendosi e confregandosi sopra le globulenze della sua faccia: e tal confregazione, trita in minute particule della discendente acqua, la qual, convertendosi in grossa nebbia, si mischia nelli corsi de’ venti a modo di ravviluppato fumo e revoluzion di nuvoli, e la leva al fine infra l’aria, e si converte in nuvoli. Ma la pioggia, che discende infra l’aria, nell’essere combattuta e percossa dal corso de’ venti, si fa rara o densa, secondo la rarità o densità d’essi venti, e per questo si genera infra l’aria una innovazione di trasparenti, fatti dalla discesa della pioggia che è vicina all’occhio, che la vede. L’onde del mare, che percuotono l’obliquità de’ monti, che con lui combinano, saranno schiumose, con velocità contro al dosso de’ detti colli, e nel tornare indirieto si scontrano nell’avvenimento della seconda onda, e dopo il gran loro strepito tornan, con grande innondazione, al mare, donde si partirono.","Gran quantità di popoli, d’uomini e d’animali diversi si vedean scacciati dell’accrescimento del diluvio inverso le cime de’ monti, vicini alle predette acque.","Onde del mare di Piombino, tutte d’acqua schiumosa.","Dell’acqua che risalta; de’ venti di Piombino; a Piombino ritrosi di venti e di pioggia con rami e alberi misti coll’aria; votamenti dell’acqua, che piove nelle barche."],"cs":["Bylo vidět, jak temný a mlhavý vzduch zmítá běh různých větrů, zamotaných do neustálého deště a smíšených s krupobitím, které hned sem, hned tam nesly nekonečné spousty větví roztrhaných stromů, smíšených s nesčetným listím. Kolem bylo vidět staré stromy vyrvané i s kořeny a roztrhané zuřivostí větrů. Bylo vidět sutě hor, podemletých už během jejich řek, jak se řítí do týchž řek a zavírají jejich údolí; a tyto zahrazené řeky se rozlévaly a zatopovaly převeliký počet měst i s jejich lidem.","Také bys byl mohl vidět, jak se na vrcholech mnoha hor shromáždilo mnoho rozmanitých druhů zvířat, vyděšených a nakonec zkrocených, ve společnosti uprchlých mužů a žen s jejich dětmi. A pole pokrytá vodou ukazovala své vlny z velké části pokryté prkny, lůžky, čluny a jinými rozmanitými nástroji, zhotovenými z nouze a ze strachu před smrtí; na nich byly ženy a muži s dětmi pospolu, s rozličným nářkem a pláčem, vyděšeni zuřivostí větrů, které převelikou bouří obracely vody vzhůru nohama i s mrtvými, kteří v nich utonuli. A nebylo věci lehčí než voda, která by nebyla pokryta rozmanitými zvířaty; ta uzavřela příměří a byla pospolu v ustrašeném spojenectví – mezi nimi vlci, lišky, hadi a tvorové všeho druhu, prchající před smrtí. A všechny vlny, bijící do jejich břehů, je zasypávaly rozmanitými údery různých utonulých těl, a tyto údery zabíjely ty, jimž ještě zůstal život.","Mohl bys vidět některé hloučky lidí, kteří se zbraní v ruce bránili malá místa, jež jim zůstala, před lvy, vlky a dravými zvířaty, která tam hledali spásu. Ach, jaké hrozné hřmoty se rozléhaly temným vzduchem, bitým zuřivostí hromů a blesků, jimi vrhaných, jež jím drsně probíhaly a bily do všeho, co se stavělo do cesty jejich běhu! Ach, kolik bys jich viděl, jak si vlastníma rukama zacpávají uši, aby unikli nesmírnému hluku, který v temném vzduchu působila zuřivost větrů smíšených s deštěm, nebeskými hromy a zuřivostí blesků!","Jiní, jimž nestačilo zavřít oči, si je ještě zakrývali vlastníma rukama, kladouce jednu přes druhou, aby neviděli kruté zničení, které na lidském rodu působil hněv Boží. Ach, kolik nářků, a kolik vyděšených se vrhalo ze skal! Bylo vidět veliké větve mohutných dubů, obtížené lidmi, jak je zuřivost prudkých větrů nese vzduchem.","Kolik bylo člunů převrácených vzhůru dnem, jak celých, tak rozbitých na kusy, a na nich lidé, kteří se namáhali o svou záchranu s bolestnými posunky a pohyby, věštícími hroznou smrt. Jiní si v zoufalých pohybech brali život, zoufajíce si, že nemohou snést takovou bolest: z nich se někteří vrhali z vysokých skal, jiní si vlastníma rukama svírali hrdlo, někteří chápali své vlastní děti a s velikou prudkostí je roztříštili, někteří se vlastními zbraněmi zraňovali a zabíjeli, jiní, vrhajíce se na kolena, se poroučeli Bohu. Ach, kolik matek oplakávalo své utonulé děti, držíce je na kolenou, zvedajíce rozpjaté paže k nebi, a hlasy složenými z rozličného kvílení kárálo hněv bohů; jiní s rukama sepjatýma a s prsty do sebe propletenými si je kousali a krvavými kousnutími rozdírali, sklánějíce se hrudí ke kolenům pro nesmírnou a nesnesitelnou bolest.","Bylo vidět stáda zvířat, jako koně, voly, kozy, ovce, už obklíčená vodami a zůstavší jako na ostrově na vysokých vrcholech hor, jak se už tisknou k sobě a ta uprostřed se zvedají vzhůru a šlapou po ostatních a svádějí mezi sebou veliké rvačky; a mnoho z nich hynulo pro nedostatek potravy.","A už ptáci usedali na lidi a jiná zvířata, nenacházejíce už žádnou nezakrytou zemi, která by nebyla obsazena živými; už hlad, služebník smrti, vzal život velké části zvířat; když tu se mrtvá těla, již nadlehčená, zvedala ze dna hlubokých vod a vynořovala se vzhůru. A mezi zmítajícími se vlnami, na nichž narážela jedno do druhého a jako míče plné větru odskakovala zpět od místa svého nárazu, stávala se tato těla podložkou řečeným mrtvým. A nad těmito kletbami bylo vidět vzduch pokrytý temnými mraky, rozdělenými hadovitými pohyby rozzuřených nebeských blesků, osvětlujících hned sem, hned tam temnotu tmy.","Pohyb vzduchu je vidět prostřednictvím pohybu prachu, zvířeného během koně; jeho pohyb, jímž vyplňuje prázdno, které kůň zanechává ve vzduchu, jenž jej obestíral, je tak rychlý, jako je rychlost toho koně, s níž se vzdaluje od řečeného vzduchu.","A snad se ti bude zdát, že mě můžeš kárat, že jsem zobrazil dráhy, které ve vzduchu vytváří pohyb větru, ačkoli vítr sám o sobě ve vzduchu vidět není. Na to se odpovídá, že ve vzduchu není vidět pohyb větru, nýbrž jen pohyb věcí, které nese.","Tma, vítr, mořská bouře, potopa vod, hořící lesy, déšť, nebeské blesky, zemětřesení a zřícení hor, srovnání měst se zemí.","Vířivé větry, které nesou vzduchem vodu, větve stromů a lidi.","Větve urvané větry, smíšené s během větrů, a na nich lidé.","Zlámané stromy, obtížené lidmi.","Lodi rozbité na kusy, mrštěné na útesy.","O stádech, krupobití, blescích, vířivých větrech.","Lidé, kteří jsou na stromech, jež je nemohou unést; stromy a útesy, věže, pahorky plné lidí, čluny, prkna, díže a jiné nástroje k plování, pahorky pokryté muži a ženami či zvířaty, a blesky z mraků, které osvětlují věci.","Nejprve budiž zobrazen vrchol drsné hory s jakýmsi údolím kolem jejího úpatí a na jejích úbočích ať je vidět, jak se půdní kůra zvedá spolu s drobnými kořínky malých keříků a obnažuje velkou část okolních útesů; ať se tento sesuv zhoubně řítí dolů; a ať v prudkém běhu bije do zkroucených a hlíznatých kořenů velikých stromů, podemílá je a převrací vzhůru nohama. A hory, obnažujíce se, ať odhalují hluboké trhliny, které v nich způsobila dávná zemětřesení; a úpatí hor ať jsou z velké části zasypána a pokryta troskami keřů, zřícených z úbočí vysokých vrcholů řečených hor, smíšenými s blátem, kořeny, větvemi stromů s rozličným listím, vmíšenými do toho bláta, hlíny a kamení.","A sutě některých hor ať se zřítily do hloubky nějakého údolí a vytvořily hráz vzduté vodě jeho řeky; a ta hráz, již protržená, ať se valí převelikými vlnami, z nichž ty největší ať bijí do zdí měst a vesnic toho údolí a boří je. A trosky vysokých budov řečených měst ať zvedají veliký prach, voda ať se zvedá vzhůru v podobě dýmu a ve spletených mracích ať se pohybuje proti padajícímu dešti.","Ale vzdutá voda ať krouží po jezeře, které ji v sobě uzavírá, a s vířivými proudy naráží na různé předměty a odráží se do vzduchu s bahnitou pěnou, potom opět padá a nechává odraženou vodu odskakovat do vzduchu. A kruhové vlny, které utíkají od místa nárazu, ať se svým náporem ženou napříč přes pohyb jiných kruhových vln, jež se pohybují proti nim, a po nárazu ať vyskakují do vzduchu, aniž se odtrhnou od svých základen.","A u výtoku, kterým voda z takového jezera vychází, je vidět rozbité vlny, jak se rozprostírají směrem k výtoku; za ním voda, padajíc čili klesajíc vzduchem, nabývá tíhy a prudkého pohybu, načež proniká vodou, do níž narazí, rozevírá ji a s prudkostí proniká až k nárazu o dno; od něho se pak odráží a vyskakuje k hladině jezera, provázena vzduchem, který se s ní ponořil; a ten zůstává u výtoku s pěnou, smíšenou s dřevem a jinými věcmi lehčími než voda, kolem nichž začínají vlny, které tím více rostou do kruhu, čím více nabývají pohybu; a tento pohyb je činí tím nižšími, čím širší základnu získávají, a proto jsou v době svého zániku málo zřetelné. Ale narážejí-li vlny na různé předměty, tu se odrážejí zpět proti přicházejícím dalším vlnám a zachovávají přírůstek téhož zakřivení, jakého by nabyly, kdyby zachovaly již započatý pohyb.","Ale déšť má při padání ze svých mraků tutéž barvu jako tyto mraky, totiž barvu jejich stinné strany, ledaže by jimi pronikaly sluneční paprsky; kdyby tomu tak bylo, jevil by se déšť méně temný než sám mrak. A narazí-li veliké tíhy největších sutí velikých hor nebo jiných mohutných staveb při jejich zřícení do velikých vodních ploch, tu vyšplíchne do vzduchu veliké množství vody, jehož pohyb bude mít směr opačný, než měl pohyb toho, co do vody narazilo; totiž úhel odrazu bude podobný úhlu dopadu.","Z věcí, které nese proud vod, se nejvíce vzdálí od protějších břehů ta, která bude těžší čili větší. Víry vod jsou ve svých částech tím rychlejší, čím jsou blíže svému středu. Hřebeny mořských vln padají před jejich základnami, bijí a třou se o vypukliny jejich povrchu; a toto tření rozmělní padající vodu na drobné částečky, ta se mění v hustou mlhu, mísí se s během větrů jako spletený dým a vířící mraky, a ten ji nakonec zvedá do vzduchu a mění se v mraky. Ale déšť, který padá vzduchem, je-li zmítán a bit během větrů, stává se řídkým či hustým podle řídkosti či hustoty těch větrů; a tím vzniká ve vzduchu střídání průhledností, způsobené padáním deště, který je blízko oku, jež jej vidí. Mořské vlny, které bijí do svahů hor, s nimiž se stýkají, budou zpěněné, rychle se vrhnou proti hřbetu těch pahorků, a při návratu zpět se srazí s přicházející druhou vlnou a po velikém hřmotu se vrátí s velikou záplavou do moře, odkud vyšly.","Bylo vidět veliké množství lidu, lidí a rozmanitých zvířat, hnaných stoupáním potopy k vrcholům hor, blízkých řečeným vodám.","Vlny moře u Piombina, celé ze zpěněné vody.","O vodě, která odskakuje; o větrech u Piombina; u Piombina víry větrů a deště s větvemi a stromy smíšenými se vzduchem; vylévání vody, která prší do člunů."],"ref":{"s":"R","l":327,"st":"","z":false,"raw":"R. 327"},"ca":[],"rr":"W. P. 3"},{"id":"s489","o":"I paesi","c":"XII","str":323,"ni":"l’isola di cipro","nc":"Ostrov Kypr","it":["Dalli meridionali lidi di Cilicia si vede per australe la bell’isola di Cipro, la qual fu regno della dea Venere, e molti, incitati dalla sua bellezza, hanno rotte le loro navi e sartie infra li scogli, circondati dalle vertiginose onde. Quivi la bellezza del dolce colle invita i vagabondi naviganti a recrearsi infra le sue fiorite verdure, fra le quali i venti raggirandosi empiono l’isola e ’l circostante mare di soavi odori.... Oh! quante navi quivi già son sommerse! oh! quanti navili rotti negli scogli! Quivi si potrebbero vedere innumerabili navili, chi è rotto e mezzo coperto dall’arena, chi si mostra da poppa e chi da prua, chi da carena e chi da costa, — e parrà a similitudine d’un Giudizio, che voglia risuscitare navili morti, tant’è la somma di quelli, che copre tutto il lito settentrionale. Quivi i venti d’aquilone, resonando, fan vari e paurosi soniti."],"cs":["Z jižních břehů Kilíkie je vidět k jihu krásný ostrov Kypr, který byl královstvím bohyně Venuše; a mnozí, zlákáni jeho krásou, roztříštili své lodi a lanoví mezi útesy obklopenými vířícími vlnami. Zde krása líbezného pahorku zve bloudící mořeplavce, aby si odpočinuli v jeho kvetoucí zeleni, mezi níž víří větry a naplňují ostrov i okolní moře sladkými vůněmi.... Ach, kolik lodí se zde už potopilo! Ach, kolik lodí se roztříštilo o útesy! Zde by bylo možné vidět nesčetné lodi: jedna je rozbitá a napůl zasypaná pískem, jiná vyčnívá zádí a jiná přídí, jiná kýlem a jiná bokem – a bude to vypadat jako Soud, který chce vzkřísit mrtvé lodi, tak velký je jejich počet, jenž pokrývá celé severní pobřeží. Zde severní větry hučí a vydávají rozmanité a strašidelné zvuky."],"ref":{"s":"C.A","l":211,"st":"v","z":true,"raw":"C. A. 211 v"},"ca":[1123,1124]},{"id":"s490","o":"Il viaggio in Oriente","c":"","str":324,"ni":"divisione del libro","nc":"Rozvržení knihy","it":["La predica e persuasione di fede.","La súbita inondazione insino al fine suo.","La ruina della città.","La morte del popolo e disperazione.","La caccia del predicatore e la sua liberazione e benivolenza.","Il danno ch’ella fece.","Ruine di neve.","Trovata del profeta.","La profezia sua.","Allagamento delle parti basse di Erminia occidentale, li scolamenti delle quali erano per la tagliata di monte Tauro.","Come il novo profeta (mostra) questa ruina è fatta al suo proposito."],"cs":["Kázání a přesvědčování k víře.","Náhlá povodeň až do svého konce.","Zkáza města.","Smrt lidu a zoufalství.","Pronásledování kazatele, jeho vysvobození a přízeň.","Škoda, kterou způsobila.","Sesuvy sněhu.","Nalezení proroka.","Jeho proroctví.","Zaplavení nížin západní Arménie, jejichž odtok vedl průrvou v hoře Tauru.","Jak nový prorok (ukazuje), že tato zkáza se stala podle jeho předpovědi."],"ref":{"s":"C.A","l":211,"st":"v","z":true,"raw":"C. A. 211 v"},"ca":[1123,1124]},{"id":"s491","o":"Il viaggio in Oriente","c":"","str":325,"ni":"descrizione del monte tauro e del fiume eufrates","nc":"Popis hory Tauru a řeky Eufratu","it":["Al Diodaridi Soria, locotenente del sacro Soltano di Babilonia.","Il nuovo accidente, accaduto in queste nostre parti settentrionali, il quale son certo, che non solamente a te, ma a tutto l’universo darà terrore, (il quale) successivamente ti sarà detto per ordine, mostrando prima l’effetto e poi la causa.","Ritrovandomi io in queste parti d’Erminia, a dare con amore e sollecitudine opra a quello uffizio, pel quale tu mi mandasti, e nel dare principio in quelle parti, che a me pareano essere più al proposito nostro, entrai nella città di Calindra, vicina ai nostri confini.","Questa città è posta nelle ispiagge di quella parte del monte Tauro, che è divisa dall’Eufrates, e riguarda i corni del gran monte Tauro per ponente.","Questi corni son di tanta altura, che par che tocchino il cielo, che nell’universo non è parte terrestre più alta della sua cima, e sempre 4 ore innanzi dì è percossa dai razzi del sole in oriente; e per l’essere lei di pietra bianchissima, essa forte risplende e fa l’uffizio a questi Ermini, come farebbe un bel lume di luna nel mezzo delle tenebre; e per la sua grande altura, essa passa le somme altezze de’ nugoli per ispazio di 4 miglia a linia retta. Questa cima è veduta di gran parte dell’occidente alluminata dal sole dopo il suo tramontare insino alla terza parte della notte, ed è quella che appresso di voi ne’ tempi sereni abbiam già giudicato essere una cometa, e pare a noi nelle tenebre della notte mutarsi in varie figure, e quando dividersi in due o in tre parti, e quando Iqnga, e quando corta; e questo nasce per li nuvoli, che ne l’orizzonte del cielo s’interpongono in fra parte d’esso monte e ’l sole; e, per tagliare loro essi razzi solari, il lume del monte è interrotto con vari spazi di nugoli, e però è di figura variabile nel suo splendore.","Perchè il monte risplende nella sua cima la metà o ’l terzo della notte, e pare una cometa a quelli di ponente, dopo la sera, e innanzi dì a quelli di levante.","Perchè essa cometa par di variabile figura in modo, che ora è tonda, or lunga, e or divisa in due o in tre parti, e ora unita, e quando si perde, e quando si rivede."],"cs":["Diodariovi Sýrie, místodržiteli posvátného sultána babylonského.","Nová událost, která se přihodila v těchto našich severních končinách a která, jsem si jist, naplní hrůzou nejen tebe, ale celý svět, ti bude postupně vypravována popořadě; nejprve ukážu účinek a potom příčinu.","Když jsem se nacházel v těchto končinách Arménie, abych s láskou a péčí konal úřad, pro který jsi mě vyslal, a začínal v těch místech, která se mi zdála nejvhodnější pro náš záměr, vstoupil jsem do města Kalindry, blízko našich hranic.","Toto město leží na úbočích té části hory Tauru, kterou odděluje Eufrat, a hledí k západu na rohy velikého Tauru.","Tyto rohy jsou tak vysoké, že se zdá, jako by se dotýkaly nebe, neboť na světě není místa na zemi vyššího než jeho vrchol; a vždy čtyři hodiny před svítáním je na východě zasažen slunečními paprsky; a protože je z nejbělejšího kamene, silně září a slouží těmto Arménům tak, jako by jim sloužilo krásné světlo měsíce uprostřed tmy; a pro svou velikou výšku převyšuje nejvyšší výšky mraků o čtyři míle v přímé linii. Tento vrchol je vidět z velké části západu osvětlený sluncem po jeho západu až do třetiny noci; a je to ten, o kterém jsme se u vás za jasných časů už domnívali, že je kometou; a zdá se nám, že se ve tmě noci mění v rozmanité podoby, hned se dělí na dvě či tři části, hned je dlouhý, hned krátký; a to vzniká mraky, které se na obzoru nebe vkládají mezi část té hory a slunce; a protože přetínají sluneční paprsky, je světlo hory přerušováno různými mezerami mraků, a proto má ve svém lesku proměnlivou podobu.","Proč hora svítí na svém vrcholu polovinu či třetinu noci a zdá se kometou těm na západě po večeru a těm na východě před svítáním.","Proč má tato kometa tak proměnlivou podobu, že je hned kulatá, hned dlouhá, hned rozdělená na dvě či tři části, hned spojená, hned se ztrácí a hned je znovu vidět."],"ref":{"s":"C.A","l":211,"st":"v","z":true,"raw":"C. A. 211 v"},"ca":[1123,1124]},{"id":"s492","o":"Il viaggio in Oriente","c":"","str":327,"ni":"figura del monte tauro","nc":"Podoba hory Tauru","it":["Non sono, o Diodario, da essere da te imputato di pigrizia, come le tue rampogne par che accennino, ma lo isfrenato amore, il quale ha creato il benefizio, ch’io posseggo da te, è quello che m’ha costretto con somma sollecitudine a cercare e con diligenza a ’nvestigare la causa di sì grande e stupendo effetto; la qual cosa non sanza tempo ha potuto avere effetto. Ora, per farti ben soddisfatto della causa di sì grande effetto, è necessario ch’io ti mostri la forma del sito, e poi verrò allo effetto, col quale, credo, rimarrai soddisfatto.","Non ti dolere, o Diodario, del mio tardare a dar risposta alla tua desiderosa richiesta, perchè queste cose, di che tu mi richiedesti, son di natura, che non sanza processo di tempo si possono bene esprimere, e massime perchè a voler mostrare la causa di sì grande effetto, bisogna discrivere con bona forma la natura del sito, e mediante quella tu potrai poi con facilità soddisfarti della predetta richiesta.","Io lascierò indirieto la descrizione della forma dell’Asia Minore, e che mare o terre sien quelle, che terminino la figura della sua quantità, perchè so che la diligenza e sollecitudine de’ tua studi non t’hanno di tal notizia privato, e verrò a denotare la vera figura di Taurus monte, il quale è quello ch’è causatore di sì stupenda e dannosa maraviglia, il quale serve alla espedizione del nostro proposito.","Questo monte Tauro è quello che appresso di molti è detto essere il giogo del monte Caucaso; ma avendo voluto ben chiarirmi, ho voluto parlare con alquanti di quelli, che abitano sopra del mar Caspio, i quali mostrano che, benchè i monti loro abbino il medesimo nome, questi son di maggiore altura, e però confermano quello sia il vero monte Caucaso, perche Caucaso in lingua scitica voi dire somma altezza. E invero non ci è notizia che l’Oriente nè l’Occidente, abbia monte di sì grande altura, e la pruova che così sia è che li abitatori de’ paesi, che li stanno per ponente, veggono i razzi del sole, che allumina insino alla quarta parte della maggior notte parte della sua cima, e ’l simile fa a quelli paesi, che li stanno per oriente."],"cs":["Nemáš mě, Diodario, obviňovat z lenosti, jak se zdá, že naznačují tvé výčitky; nýbrž bezuzdná láska, kterou ve mně zrodilo dobrodiní, jehož se mi od tebe dostává, mě přiměla, abych s největší péčí hledal a pilně zkoumal příčinu tak velikého a úžasného účinku; a to se nemohlo uskutečnit bez času. Nyní, abych tě o příčině tak velikého účinku dobře uspokojil, je nutné, abych ti ukázal podobu místa, a potom přejdu k účinku, jímž, myslím, budeš uspokojen.","Nermuť se, Diodario, nad mým otálením s odpovědí na tvou toužebnou žádost, neboť věci, na které ses mě tázal, jsou takové povahy, že je nelze dobře vyjádřit bez plynutí času; a zvláště proto, že chce-li se ukázat příčina tak velikého účinku, je třeba náležitě popsat povahu místa, a jejím prostřednictvím pak budeš moci snadno nalézt uspokojení své řečené žádosti.","Ponechám stranou popis podoby Malé Asie a jaká moře či země ohraničují tvar jejího rozsahu, neboť vím, že píle a horlivost tvých studií tě o takovou znalost nepřipravily; a přejdu k vylíčení pravé podoby hory Tauru, která je původcem tak úžasného a zhoubného divu a která poslouží k provedení našeho záměru.","Tato hora Taurus je ta, o níž mnozí říkají, že je hřbetem pohoří Kavkazu; ale protože jsem si to chtěl dobře ujasnit, chtěl jsem mluvit s některými z těch, kdo bydlí nad Kaspickým mořem; ti ukazují, že ačkoli jejich hory nesou totéž jméno, tyto jsou vyšší, a proto potvrzují, že toto je pravý Kavkaz, neboť Kavkaz znamená ve skytském jazyce nejvyšší výška. A vskutku není známo, že by Východ či Západ měl horu tak veliké výšky; a důkazem, že je tomu tak, je to, že obyvatelé krajů, které leží na západ od ní, vidí sluneční paprsky osvětlovat část jejího vrcholu až do čtvrtiny nejdelší noci; a totéž se děje krajům, které leží na východ od ní."],"ref":null,"ca":[]},{"id":"s493","o":"Il viaggio in Oriente","c":"","str":329,"ni":"qualità e quantità del monte tauro","nc":"Povaha a velikost hory Tauru","it":["L’ombra di questo giogo del Tauro è di tanta altura, che quando di mezzo Giugno il sole è a mezzogiorno, la sua ombra s’astende insino al principio della Sarmazia, che son giornate 12, e a mezzo Dicembre s’astende insino ai monti Iperborei, che è viaggio d’un mese inverso tramontana; e sempre la sua parte opposita al vento che soffia è piena di nuvoli e nebbie, perchè il vento, che s’apre nella percussione del sasso, dopo esso sasso si viene a richiudere, e in tal modo porta con seco i nuvoli da ogni parte e lasciali nella lor percussione, e sempre è priva di percussione di saette per la gran moltitudine di nugoli, che lì son ricettati, onde il sasso è tutto fracassato e pien di gran ruine.","Questa nelle sue radici è abitata da ricchissimi popoli, ed è piena di bellissime fonti e fiumi e fertile e abbondante d’ogni bene, e massime nelle parti che riguardano a mezzogiorno; ma quando se n’è montata circa a 3 miglia, si comincia a trovare le selve de’ grandi abeti, pini, faggi e altri simili alberi; dopo questi per ispazio di altre 3 miglia, si truova praterie e grandissime pasture; e tutto il resto, insino al nascimento del monte Tauro, sono nevi eterne, che mai per alcun tempo si partono, che s’astendono all’altezza di circa 14 miglia in tutto. Da questo nascimento del Tauro, insino all’altezza d’un miglio non passano mai i nuvoli, che qui abbiamo 15 miglia, che sono circa a 5 miglia d’altezza per linia retta, e altrettanto o circa, troviamo essere la cima delli corni del Tauro, ne’ quali, dal mezzo in su, si comincia a trovare aria, che riscalda, e non vi si sente soffiamenti di venti, ma nessuna cosa ci può troppo vivere; quivi non nasce cosa alcuna, salvo alcuni uccelli rapaci, che covano nell’alte fessure del Tauro, e discendono poi sotto i nuvoli a fare le lor prede sopra i monti erbosi. — Questo è tutto sasso semplice, cioè da’ nuvoli in su, ed è sasso candidissimo, e in sulla alta cima non si po’ andare per l’aspra e pericolosa sua salita.","Essendomi io più volte con lettere rallegrato teco della tua prospera fortuna, al presente so che, come amico, ti contristerai con meco del misero stato, nel quale mi trovo, e questo è che ne’ giorni passati sono stato in tanti affanni, paure, pericoli e danno, insieme con questi miseri paesani, che avevamo d’avere invidia ai morti: e certo io non credo, che, poichè gli elementi con lor separazione disfeciono il gran Caos, che essi riunissino lor forza, anzi rabbia, a fare tanto nocimento alli omini, quanto al presente da noi s’è veduto e provato; in modo ch’io non posso imaginare che cosa si possa più accrescere a tanto male, il quale noi provammo in spazio di dieci ore.","In prima fummo assaliti e combattuti dall’impeto e furore de’ venti, e a questo s’aggiunsero le ruine delli gran monti di neve, i quali hanno ripieno tutte queste valli e conquassato gran parte della nostra città. E, non si contentando di questo, la fortuna, con subiti diluvi d’acque, ebbe a sommergere tutta la parte bassa di questa città; oltre di questo s’aggiunse una sùbita pioggia, anzi ruinosa tempesta piena d’acqua, sabbia, fango e pietre, insieme avviluppate con radici, sterpi e ciocchi di varie piante, e ogni cosa scorrendo per l’aria, discendea sopra di noi; e in ultimo uno incendio di fuoco parea condotto non che da’ venti, ma da diecimila diavoli, che ’l portassino, il quale ha abbruciato e disfatto tutto questo paese, e ancora non vi è cessato.","E que’ pochi, che siamo restati, siamo rimasti con tanto sbigottimento e tanta paura che appena, come balordi, abbiamo ardire di parlare l’uno coll’altro. Avendo abbandonato ogni nostra cura, ci stiamo insieme uniti in certe ruine di chiese, insieme misti maschi e femmine, piccoli e grandi, a modo di torme di capre. I vicini per pietà ci hanno soccorso di vettovaglie, i quali eran prima nostri nimici, e se non fusse soccorso di vettovaglia, tutti saremmo molti di fame.","Ora vedi come ci troviamo! E tutti questi mali son niente a comparazione di quelli, che in breve tempo ne son promessi.","So che, come amico, ti contristerai del mio male, come già, con lettere, ti mostrai con effetto rallegrarmi del tuo bene.","Vedevasi gente, che con gran sollecitudine apparecchiavan vettovaglia sopra diverse sorta di navili, fatti brevissimi per la necessità.","Li lustri dell’onde non si dimostravano in que’ luoghi, dove le tenebrose pioggie colli lor nuvoli refrettevano.","Ma dove le vampe generate dalle celesti saette refrettevano, si vedeva tanti lustri fatti da’ simulacri de’ lor vampi, quant’eran l’onde che a li occhi de’ circustanti potean refrettere.","Tanto crescevano il numero de’ simulacri fatti da vampi delle saette sopra l’onde dell’acqua, quanto cresceva la distanzia delli occhi lor risguardatori, — com’è provato nella descrizione dello splendore della luna.","E così diminuiva tal numero di simulacri, quanto più si avvicinavano agli occhi che li vedeano, — com’è provato nella definizione dello splendore della luna, e del nostro orizzonte marittimo, quando il sole vi refrette co’ sua razzi, e che l’occhio che riceve tal refressione sia lontano dal predetto mare."],"cs":["Stín tohoto hřbetu Tauru je tak vysoký, že když je v polovině června slunce v poledni, sahá jeho stín až k počátku Sarmatie, což je dvanáct dní cesty, a v polovině prosince sahá až k Hyperborejským horám, což je měsíc cesty k severu; a jeho strana odvrácená od vanoucího větru je vždy plná mraků a mlh, neboť vítr, který se při nárazu na skálu rozdělí, se za skálou opět uzavírá, a tak s sebou přináší mraky ze všech stran a zanechává je v místě svého nárazu; a ustavičně je bita blesky [v originále doslova „je prostá úderů blesků“] pro velké množství mraků, které se tam shromažďují, takže skála je celá rozbitá a plná velikých sutí.","U svého úpatí je obývána převelice bohatými národy a je plná překrásných pramenů a řek, úrodná a hojná na každé dobro, zvláště na stranách obrácených k jihu; ale když se vystoupí asi tři míle, začínají se nacházet lesy velikých jedlí, borovic, buků a jiných podobných stromů; za nimi se v rozsahu dalších tří mil nacházejí louky a převeliké pastviny; a všechno ostatní až k počátku hory Tauru jsou věčné sněhy, které nikdy v žádnou dobu neodtávají a sahají celkem do výše asi čtrnácti mil. Od tohoto počátku Tauru až do výše jedné míle mraky nikdy nevystupují; tak tu máme patnáct mil, což je asi pět mil výšky v přímé linii; a právě tolik či přibližně tolik shledáváme, že měří vrchol rohů Tauru, v nichž se od poloviny výše začíná nacházet vzduch, který hřeje, a není tam cítit vanutí větrů; ale nic tam nemůže dlouho žít; nic se tam nerodí kromě několika dravých ptáků, kteří hnízdí ve vysokých rozsedlinách Tauru a potom sestupují pod mraky, aby lovili kořist nad travnatými horami. Je to celé holá skála, totiž od mraků vzhůru, a je to skála nejbělejší; a na vysoký vrchol nelze vystoupit pro jeho drsný a nebezpečný výstup.","Když jsem se s tebou už mnohokrát v dopisech radoval z tvého příznivého osudu, vím, že nyní budeš jako přítel se mnou truchlit nad bídným stavem, v němž se nacházím; a ten je takový, že jsem v minulých dnech spolu s těmito ubohými venkovany zakusil tolik útrap, strachu, nebezpečí a škod, že jsme museli závidět mrtvým; a jistě nevěřím, že by se od té doby, co živly svým oddělením rozložily veliký Chaos, byly znovu spojily svou silou, ba vzteklostí, aby lidem způsobily tolik škody, jako jsme nyní viděli a zakusili my; takže si nedovedu představit, co by se ještě mohlo přidat k tak velikému zlu, které jsme zakusili během deseti hodin.","Nejprve nás napadla a zmítala prudkost a zuřivost větrů; k tomu se přidaly laviny z velikých sněžných hor, které zaplnily všechna tato údolí a rozmetaly velkou část našeho města. A nespokojujíc se tím, osud náhlými povodněmi vod zatopil celou dolní část tohoto města; nad to se přidal náhlý liják, ba zhoubná bouře plná vody, písku, bahna a kamení, spletených dohromady s kořeny, keři a pařezy rozmanitých stromů; a všechno to letělo vzduchem a padalo na nás; a nakonec požár ohně, jako by jej nenesly jen větry, ale deset tisíc ďáblů, spálil a zničil celý tento kraj a dosud neustal.","A my, těch několik, kdo zůstali naživu, jsme zůstali v takovém zděšení a takovém strachu, že sotva, jako omámení, máme odvahu promluvit jeden s druhým. Opustivše všechnu svou péči, zdržujeme se pospolu v jakýchsi troskách kostelů, muži i ženy, malí i velcí, smíšeni dohromady jako stáda koz. Sousedé, kteří byli dříve našimi nepřáteli, nám ze soucitu přispěli potravinami; a nebýt té pomoci v potravinách, byli bychom všichni zemřeli hladem.","Hle tedy, jak jsme na tom! A všechna tato zla nejsou nic ve srovnání s těmi, která jsou nám v krátké době předpovídána.","Vím, že jako přítel budeš truchlit nad mým neštěstím, tak jako jsem ti už v dopisech skutečně projevil radost z tvého štěstí.","Bylo vidět lidi, kteří s velkým spěchem nakládali potraviny na rozličné druhy plavidel, zhotovených z nouze velmi narychlo.","Lesky vln se neukazovaly na těch místech, kde se odrážely temné deště se svými mraky.","Ale tam, kde se odrážely výšlehy zrozené nebeskými blesky, bylo vidět tolik lesků, vytvořených obrazy jejich výšlehů, kolik bylo vln, které je mohly odrážet do očí přihlížejících.","Počet obrazů vytvořených výšlehy blesků na vlnách vody rostl tou měrou, jakou rostla vzdálenost očí, které na ně hleděly – jak je dokázáno v popisu měsíčního lesku.","A tento počet obrazů tím více ubýval, čím více se blížily k očím, které je viděly – jak je dokázáno ve vymezení měsíčního lesku a našeho mořského obzoru, když se na něm odrážejí sluneční paprsky a oko, které tento odraz přijímá, je od řečeného moře daleko."],"ref":{"s":"C.A","l":211,"st":"v","z":true,"raw":"C. A. 211 v"},"ca":[1123,1124]},{"id":"s494","o":"Le figure","c":"I","str":335,"ni":"la pittura espressiva","nc":"Výrazná malba","it":["La pittura, over le figure dipinte, debbono essere fatte in modo tale, che i riguardatori d’esse possano con facilità conoscere, mediante le loro attitudini, il concetto dell’animo loro. E se tu hai a fare parlare un omo dabbene, fare che li atti sua sieno compagni delle bone parole; e similmente se tu hai a figurare uno omo bestiale, fallo co’ movimenti fieri, gittando le braccia contro all’auditore, e la testa col petto, sportato fori de’ piedi, accompagnino le mani del parlatore: a similitudine del muto che, vedendo due parlatori, benchè esso sia privato dell’audito, niente di meno, mediante li effetti e li atti d’essi parlatori, lui comprende il tema della loro disputa.","Io vidi già in Firenze uno sordo accidentale, il quale se tu li parlavi forte, lui non ti intendea, e parlando piano, sanza suono di voce, lui t’intendea solo per lo menar delle labbra. Or mi potresti dir: — non mena le labbra uno, che parla forte, come piano? e menandole l’uno come l’altro, non sarà inteso l’altro come l’uno? — A questa parte io lascio dare la sentenza alla sperienza: fa parlare uno piano e poi forte, e pon mente le labbra."],"cs":["Malba neboli malované postavy mají být udělány tak, aby z nich diváci mohli snadno poznat podle jejich postojů myšlenku jejich duše. A máš-li zobrazit, jak mluví počestný muž, postarej se, aby jeho posunky doprovázely dobrá slova; a podobně máš-li zobrazit surového muže, udělej ho s divokými pohyby, s pažemi vrženými proti posluchači, a ať hlava s hrudí, vysunutá před nohy, doprovází ruce mluvčího: na způsob němého, který, vidí-li dva lidi rozmlouvat, ačkoli je zbaven sluchu, přesto z projevů a posunků těch mluvčích pochopí téma jejich sporu.","Viděl jsem kdysi ve Florencii jednoho, kdo ohluchl následkem nemoci; když jsi na něj mluvil hlasitě, nerozuměl ti, a když jsi mluvil potichu, bez zvuku hlasu, rozuměl ti jen podle pohybu rtů. Nyní bys mi mohl říci: – Což nehýbe rty ten, kdo mluví hlasitě, stejně jako ten, kdo mluví potichu? A hýbe-li jimi jeden jako druhý, nebude se rozumět jednomu jako druhému? – O tom nechávám rozhodnout zkušenost: dej někoho mluvit potichu a pak nahlas a sleduj jeho rty."],"ref":{"s":"C.A","l":139,"st":"r","z":false,"raw":"C. A. 139 r"},"ca":[760,762,764]},{"id":"s495","o":"Le figure","c":"II","str":336,"ni":"avvertimento al pittore","nc":"Upozornění malíři","it":["Poni mente per le strade, sul fare della sera, i volti d’omini e donne, quando è cattivo tempo, quanta grazia e dolcezza si vede in loro!"],"cs":["Všímej si na ulicích, když se snáší večer a je nevlídné počasí, tváří mužů a žen – kolik půvabu a něhy je v nich vidět!"],"ref":{"s":"Ash.I","l":21,"st":"r","z":false,"raw":"Ash. I. 21 r"},"ca":[]},{"id":"s496","o":"Le figure","c":"III","str":336,"ni":"la pittura deve mostrare la passione della figura dipinta","nc":"Malba má ukázat vášeň zobrazené postavy","it":["Il bono pittore ha da dipingere due cose principali, cioè l’omo e il concetto della mente sua. Il primo è facile, il secondo difficile, perchè s’ha a figurare con gesti e movimenti delle membra, e questo è da essere imparato dalli muti, che meglio ’l fanno, che alcun’altra sorte di omini."],"cs":["Dobrý malíř má malovat dvě hlavní věci, totiž člověka a myšlenku jeho mysli. To první je snadné, to druhé obtížné, neboť se to musí zobrazit gesty a pohyby údů, a tomu je třeba se učit od němých, kteří to umějí lépe než kterýkoli jiný druh lidí."],"ref":{"s":"Lu","l":180,"st":"","z":false,"raw":"Lu. 180"},"ca":[]},{"id":"s497","o":"Le figure","c":"IV","str":337,"ni":"come il muto è maestro del pittore","nc":"Jak je němý učitelem malíře","it":["Le figure delli omini abbiano atti propri alla loro operazione in modo che, vedendoli, tu intendi quello che per loro si pensa o dice; li quali saranno bene imparati da ch’imiterà li moti delli muti, li quali parlano con movimenti delle mani e degli occhi e ciglia e di tutta la persona, nel voler esprimere il concetto dell’animo loro.","E non ti ridere di me, perchè io ti propongo un precettore sanza lingua, il quale t’abbia a insegnare quell’arte, che lui non sa fare, perchè meglio t’insegnerà co’ fatti, che tutti li altri con le parole. E non sprezzare tal consiglio, perchè loro sono li maestri de’ movimenti, e intendono da lontano di quel che uno parla, quando egli accomoda li moti delle mani con le parole."],"cs":["Postavy lidí ať mají posunky odpovídající jejich činnosti tak, abys při pohledu na ně porozuměl, co si myslí nebo co říkají; těm se dobře naučí ten, kdo bude napodobovat pohyby němých, kteří mluví pohyby rukou, očí, obočí a celého těla, když chtějí vyjádřit myšlenku své duše.","A nesměj se mi, že ti navrhuji učitele bez jazyka, který tě má naučit umění, jež sám neovládá, neboť tě naučí lépe činy, než všichni ostatní slovy. A nepohrdej takovou radou, neboť oni jsou mistry pohybů a z dálky rozumějí tomu, o čem kdo mluví, když přizpůsobuje pohyby rukou svým slovům."],"ref":{"s":"Lu","l":115,"st":"","z":false,"raw":"Lu. 115"},"ca":[]},{"id":"s498","o":"Le figure","c":"V","str":337,"ni":"il pregio della pittura sta nella rispondenza del segno al significato","nc":"Hodnota malby spočívá v souladu znaku s významem","it":["Farai le figure in tale atto, il quale sia soffiziente a dimostrare quel che la figura ha nell’animo, altrimenti la tua arte non fia laudabile."],"cs":["Postavy budeš dělat v takovém postoji, který postačí k vyjádření toho, co má postava v duši; jinak tvé umění nebude chvályhodné."],"ref":{"s":"Ash.I","l":20,"st":"r","z":false,"raw":"Ash. I. 20 r"},"ca":[]},{"id":"s499","o":"Le figure","c":"VI","str":338,"ni":"segue","nc":"Pokračování","it":["Come la figura non fia laudabile se in quella non apparisce atto, ch’esprima la passione dell’anima.","Quella figura è più laudabile, che con l’atto meglio esprime la passione del suo animo."],"cs":["Že postava nebude chvályhodná, není-li v ní patrný posunek, který vyjadřuje vášeň duše.","Ta postava je chvályhodnější, která posunkem lépe vyjadřuje vášeň své duše."],"ref":{"s":"Ash.I","l":27,"st":"r","z":false,"raw":"Ash. I. 27 r"},"ca":[]},{"id":"s500","o":"Le figure","c":"VII","str":338,"ni":"varietà infinita nell’espressione dei sentimenti","nc":"Nekonečná rozmanitost ve vyjádření citů","it":["Tanti son vari li movimenti delli omini, quanto sono le varietà delli accidenti, che discorrono per le loro menti; e ciascuno accidente in sè move più o meno essi uomini, secondo che saranno di maggiore o di minore potenza e secondo l’età, perch’altro moto farà, sopra un medesimo caso, un giovane ch’un vecchio."],"cs":["Pohyby lidí jsou tak rozmanité, jak rozmanitá jsou hnutí, jež procházejí jejich myslí; a každé hnutí samo o sobě pohne těmi lidmi více či méně podle toho, jak velkou bude mít sílu, a podle věku, neboť jiný pohyb udělá při téže události mladík a jiný stařec."],"ref":{"s":"Lu","l":373,"st":"","z":false,"raw":"Lu. 373"},"ca":[]},{"id":"s501","o":"Le figure","c":"VIII","str":338,"ni":"le età dell’uomo","nc":"Věky člověka","it":["Come si deono figurare l’età dell’omo, cioè: infanzia, puerizia, adolescenza, gioventù, vecchiezza, decrepitudine.","Come i vecchi devono essere fatti con pigri e lenti movimenti, e gambe piegate ne le ginocchia, quando stanno fermi, e pie’ e pari, distanti l’uno dall’altro, schiene declinanti in basso, la testa innanzi inclinata, e le braccia non troppo distese.","Come le donne si deono figurare con atti vergognosi, gambe insieme strette, braccia raccolte insieme, teste basse e piegate in traverso.","Come le vecchie si debbon figurare ardite e pronte a rabbiosi movimenti, a uso di furie infernali, e i movimenti deono apparire più pronti nelle braccia e teste, che nelle gambe.","I putti piccioli con atti pronti e storti, quando seggano, e, nello stare ritti, atti timidi e paurosi."],"cs":["Jak se mají zobrazovat věky člověka, totiž: útlé dětství, dětství, dospívání, mládí, stáří a sešlost věkem.","Že starci se mají dělat s líným a pomalým pohybem a s nohama pokrčenýma v kolenou, když stojí, s chodidly vedle sebe a od sebe vzdálenými, se zády skloněnými dolů, s hlavou nakloněnou dopředu a s pažemi ne příliš nataženými.","Že ženy se mají zobrazovat se stydlivými posunky, s nohama těsně u sebe, s pažemi složenými, s hlavami skloněnými a nakloněnými na stranu.","Že stařeny se mají zobrazovat smělé a pohotové k zuřivým pohybům, na způsob pekelných fúrií, a pohyby mají být živější v pažích a hlavách než v nohou.","Malé děti s živými a kroucenými posunky, když sedí, a když stojí, s posunky ostýchavými a bázlivými."],"ref":{"s":"Ash.I","l":17,"st":"v","z":false,"raw":"Ash. I. 17 v"},"ca":[]},{"id":"s502","o":"Le figure","c":"IX","str":339,"ni":"del figurare uno che parli infra più persone","nc":"O zobrazení toho, kdo mluví mezi více lidmi","it":["Usera’ fare quello, che tu vuoi che infra molte persone parli, di considerare la materia di che lui ha a trattare, e d’accomodare ivi li atti appartenenti a essa materia: cioè se l’è materia persuasiva, che li atti sieno al proposito, se l’è materia dichiarativa per diverse ragioni, che quello che dice pigli colle sue due dita della mano destra uno dito de la mano sinistra, avendone serrate le due minori, e col viso rivolto verso il popolo, con la bocca alquanto aperta, che paia che parli; e, se lui sedeva, che paia che si sollevi alquanto ritto e innanzi con la testa; e se lo fai in piè fallo alquanto chinarsi col petto e la testa inverso il popolo.","Il quale figurerai lì tacito e attento, tutti riguardare l’oratore in volto con atti ammirativi, e fare le bocche d’alcuno vecchio, per maraviglia delle audite sentenze, tenere la bocca con le sua streme basi, tirarsi dirieto molte pieghe de le guancie, e con le ciglia alte ne le giunture, le quali creino molte pieghe per la fronte; alcuni sedenti colle dita della mano insieme tessute tenervi dentro lo stanco ginocchio; altri con l’uno ginocchio sopra l’altro, sul quale tenga la man, che dentro a se riceva il gomito, del quale la sua mano vada a sostenere il mento barbuto d’alcuno chinato vecchio."],"cs":["U toho, o kom chceš, aby mluvil mezi mnoha lidmi, si zvykni uvážit látku, o níž má pojednávat, a přizpůsobit mu posunky k té látce náležející: totiž je-li to látka přesvědčovací, ať jsou posunky tomu přiměřené; je-li to látka vykládaná z různých důvodů, ať ten, kdo mluví, uchopí dvěma prsty pravé ruky jeden prst ruky levé, maje oba menší prsty sevřené, a s tváří obrácenou k lidu, s ústy poněkud pootevřenými, aby se zdálo, že mluví; a jestliže seděl, ať se zdá, že se poněkud zvedá a vysouvá hlavu kupředu; a děláš-li ho stojícího, udělej ho poněkud skloněného hrudí a hlavou k lidu.","Ten lid zobrazíš tichý a pozorný, všichni ať hledí řečníkovi do tváře s posunky obdivu; a některému starci udělej ústa tak, že v úžasu nad slyšenými výroky drží ústa se staženými koutky, tváře se mu táhnou dozadu do mnoha vrásek a obočí je zvednuté v místě, kde se stýká, takže vytváří mnoho vrásek na čele; někteří sedící ať mají prsty rukou propletené a drží v nich levé koleno; jiní ať mají jedno koleno přes druhé a na něm ruku, do níž se opírá loket, jehož ruka podpírá vousatou bradu nějakého shrbeného starce."],"ref":{"s":"Ash.I","l":21,"st":"r","z":false,"raw":"Ash. I. 21 r"},"ca":[]},{"id":"s503","o":"Le figure","c":"X","str":340,"ni":"appunti sulla composizione del cenacolo","nc":"Poznámky ke kompozici Poslední večeře","it":["Uno, che beveva, lascia la zaina nel suo sito, e volge la testa inverso il proponitore.","Un altro tesse le dita delle sue mani insieme, e con rigide ciglia si volta al compagno; l’altro, colle mani aperte, mostra le palme di quelle, e alza la spalla inverso li orecchi, e fa la bocca della maraviglia.","Un altro parla nell’orecchio all’altro, e quello che l’ascolta si torce inverso lui, e gli porge li orecchi, tenendo un coltello nell’una mano e nell’altra il pane, mezzo diviso da tal coltello. L’altro, nel voltarsi, tenendo un coltello in mano, versa con tal mano una zaina sopra della tavola.","L’altro posa le mani sopra della tavola e guarda, l’altro soffia nel boccone, l’altro si china per vedere il proponitore, e fassi ombra colla mano alli occhi, l’altro si tira indirieto a quel che si china, e vede il proponitore infra ’l muro e ’l chinato."],"cs":["Jeden, který pil, nechává číši na jejím místě a obrací hlavu k tomu, kdo promlouvá.","Jiný proplétá prsty svých rukou a se strnulým obočím se obrací k druhovi; další s otevřenýma rukama ukazuje jejich dlaně, zvedá ramena k uším a otvírá ústa v úžasu.","Jiný mluví druhému do ucha, a ten, kdo poslouchá, se k němu natáčí a nastavuje mu ucho, drže v jedné ruce nůž a v druhé chléb napůl rozříznutý tím nožem. Další, když se otáčí, drže v ruce nůž, převrhne tou rukou číši na stůl.","Další klade ruce na stůl a hledí, další fouká do sousta, další se naklání, aby viděl na toho, kdo promlouvá, a stíní si rukou oči, další se odtahuje za toho, kdo se naklání, a vidí toho, kdo promlouvá, mezi zdí a nakloněným."],"ref":{"s":"R","l":666,"st":"","z":false,"raw":"R. 666"},"ca":[],"rr":"S. K. M. II.2 1 b"},{"id":"s504","o":"Le figure","c":"XI","str":341,"ni":"come si deve fare una figura irata","nc":"Jak se má dělat rozhněvaná postava","it":["Alla figura irata farai tenere uno per li capegli, e ’l capo storto a terra, e con uno de’ ginocchi sul costato, e col braccio destro levare il pugno in alto: questo abbia li capegli elevati, le ciglie basse e strette, i denti stretti, e i due stremi d’accanto della bocca arcati; il collo grosso e dinanzi, per lo chinarsi al nimico, sia pieno di grinze."],"cs":["Rozhněvanou postavu udělej, jak drží někoho za vlasy, s hlavou zkroucenou k zemi, jedním kolenem mu klečí na boku a pravou paží zvedá pěst do výšky: ta ať má vlasy zježené, obočí stažené dolů a k sobě, zuby zaťaté a oba koutky úst prohnuté do oblouku; krk tlustý a vpředu, jak se sklání k nepříteli, plný vrásek."],"ref":{"s":"Ash.I","l":29,"st":"r","z":false,"raw":"Ash. I. 29 r"},"ca":[]},{"id":"s505","o":"Le figure","c":"XII","str":342,"ni":"come si figura uno disperato","nc":"Jak se zobrazuje zoufalec","it":["Al disperato farai darsi d’un coltello, e colle mani aversi stracciato i vestimenti, e sia una d’esse mani in opera a stracciarsi la ferita; e farailo co’ piè distanti e le gambe alquanto piegate e la persona similmente inverso terra, con capegli stracciati e sparsi.","La nera faccia, sul primo oggetto, è molto orribile e spaventosa a riguardare, e massime l’ingrottati e rossi occhi, posti sotto le paurose e scure ciglia, da fare rannuvolare il tempo e tremare la terra. E, credimi, che non è sì fiero omo che, dove voltava li infocati occhi, che volentieri non mettesse ali per fuggire, che Lucifero infernale parìa volto angelico a comparazione di quello. Il naso arricciato, con l’ampie nari, de’ quali uscivan molte e grandi setole, sotto le quali era l’arricciata bocca, colle grosse labbra, da le stremità de’ quali era pelo a uso delle gatte e denti gialli. Avanza sopra i corpi de li omini a cavallo dal dosso de’ piedi, in sù.","E rincrescendole il molto (pazientare), volta l’ira in furore, cominciò co’ piè, dimenati da la furia delle possenti gambe, a entrare fra la turba, e con calci gettava li omini per l’aria, i quali cadeano non altramente sopra gli altri omini, come se stata fussino una spessa grandine. E molti furon quelli, che, morendo, dettò morte; e questa crudeltà durò, finchè la polvere mossa da’ gran piedi, levata nell’aria, costrinse questa furia infernale a ritirarsi indirieto. E noi seguitammo la fuga.","Oh! quanti varî assalimenti furono usati contro a questa indiavolata, a la quale ogni offesa era niente! Oh! misere genti, a voi non vale le inespugnabili fortezze, a voi non l’alte mura de la città, a voi non l’essere in moltitudine, non le case o palazzi, non v’è restato se non le piccole buche e cave sotterranee, a modo di granchi o grilli o simili animali: trovate salute e vostro scampo!","Oh quante infelici madri e padri furono private de’ lor figlioli! Oh quante misere femmine private de la lor compagnia! Certo certo, caro mio Benedetto, io non credo che, poi che ’l mondo fu creato, fusse mai visto un lamento, un pianto pubblico esser fatto con tanto terrore.","Certo, in questo caso la spezie umana ha da invidiare ogni altra generazione d’animali: imperocchè se l’aquila vince per potenza li altri uccelli, il meno non sono vinti per velocità di volo, onde le rondini, colla lor prestezza, scampano dalla rapina del merlo; i delfini con lor veloce fuga scampano da la rapina de le balene e de’ gran capidogli; ma, noi miseri!, non ci vale alcuna fuga, imperocchè questa, con lento passo, vince di gran lunga il corso d’ogni veloce corsiero. Non so che mi dire o che mi fare, e’ mi pare tuttavia a notare a capo chino per la gran gola, e rimanere con confusa morte sepolto nel gran ventre.","Caduto il fiero gigante, per la cagione della insanguinata e fangosa terra, parve che cadesse una montagna, onde la campagna, squassata di terremoto, è spavento a Plutone infernale. E, per la gran percossa, ristette sulla piana terra alquanto stordito, e sùbito il popolo, credendo fusse morto di qualche saetta — tornata la gran turba — a guisa di formiche, che scorrono a furia, correndo per il corpo del caduto robore — così questi scorrendo per l’ampie membra, laceravanle con spesse ferite.","Onde risentito il gigante e sentendosi quasi coperto dalla moltitudine, sùbito sentesi cuocere per le punture — mise un mugghio, che parve fusse uno spaventoso tuono, e posto le sue mani in terra e levato il pauroso volto, e postosi una delle mani in capo trovosselo pieno d’uomini appiccati a’ capegli a similitudine de’ minuti animali, che fra quegli sogliono nascere; onde, scuotendo il capo, gli omini lancia non altramente per l’aria, che si faccia la grandine, quando va con furor di venti, e trovossi molti di questi uomini esser morti, da quegli, che gli stavano sopra ritti, coi piedi calpestando. — E tenendosi a’ capegli e ingegnandosi nascondere fra quegli, facevano a similitudine de’ marinai, quando è fortuna, che corrono su per le corde, per abbassarle a poco vento. —","Nuove delle cose di Levante? Sappi come nel mese di Giugno è apparuto un gigante che vien dalla deserta Libia:.... a similitudine delle formiche furiando.... su per l’arbore abbattuto dalla scure del rigido villano.","Questo gigante era nato nel Mont’Atalante, ed era un eroe, e ebbe a contrastare cogli Egizi e Arabi, Medi e Persi, viveva in mare delle balene, de’ gran capidogli e de’ navilî.","Marte temendo della vita, s’era fuggito sotto la (sedia) di Giove....","E per la gran caduta parve la provincia tutta tremasse."],"cs":["Zoufalce udělej, jak se bodá nožem a rukama si roztrhal šaty, a ať jedna z těch rukou právě rozdírá ránu; a udělej ho s chodidly od sebe a s nohama poněkud pokrčenýma a s tělem rovněž skloněným k zemi, s vlasy rozcuchanými a rozházenými.","Černá tvář je na první pohled velmi hrozná a děsivá k pohledu, a zvláště zapadlé a rudé oči, posazené pod strašným a temným obočím, až se z toho zatahuje nebe a třese země. A věř mi, že není tak smělého muže, který by, kam obrátil ty ohnivé oči, rád nepřipjal křídla, aby utekl, neboť pekelný Lucifer by se ve srovnání s ním zdál mít tvář andělskou. Nos ohrnutý, se širokými chřípími, z nichž vyrůstalo mnoho velkých štětin, pod nimi ohrnutá ústa s tlustými rty, na jejichž koncích byly chlupy jako u koček, a žluté zuby. Nad těla mužů na koních vyčníval od nártů nahoru.","A když ho omrzelo dlouhé (snášení), obrátil se jeho hněv v zuřivost a začal nohama, poháněnými zuřivostí mocných noh, vnikat do zástupu a kopanci metal do vzduchu lidi, kteří padali na ostatní nejinak, než kdyby to bylo husté krupobití. A mnoho bylo těch, které připravil o život; a ta krutost trvala, dokud prach zvířený obrovskýma nohama a vznesený do vzduchu nedonutil tu pekelnou zuřivost couvnout. A my jsme pokračovali v útěku.","Ó, kolik rozličných útoků bylo podniknuto proti tomu ďábelskému stvoření, jemuž byla každá rána ničím! Ó, ubozí lidé, nic vám nepomohou nedobytné pevnosti, nic vysoké hradby města, nic to, že je vás množství, ani domy či paláce; nezbylo vám nic než malé díry a podzemní dutiny, na způsob krabů či cvrčků nebo podobných živočichů: tam hledejte spásu a své útočiště!","Ó, kolik nešťastných matek a otců bylo připraveno o své děti! Ó, kolik ubohých žen přišlo o své druhy! Věru, věru, milý můj Benedetto, nevěřím, že od stvoření světa byl kdy spatřen takový nářek, takový veřejný pláč provázený tolikerou hrůzou.","Věru, v tomto případě musí lidský rod závidět každému jinému druhu zvířat: neboť jestliže orel mocí přemáhá ostatní ptáky, aspoň ti menší nejsou přemoženi rychlostí letu, a tak vlaštovky svou hbitostí unikají dravosti dřemlíka; delfíni svým rychlým útěkem unikají dravosti velryb a velkých vorvaňů; ale nám ubohým nepomůže žádný útěk, neboť on pomalým krokem daleko předčí běh každého rychlého oře. Nevím, co říci ani co dělat, a pořád se mi zdá, že plavu se skloněnou hlavou tím velikým hrdlem a zůstávám zmatenou smrtí pohřben v obrovském břiše.","Když ten divoký obr padl, uklouznuv na krví zbrocené a bahnité zemi, zdálo se, jako by padala hora, takže krajina otřesená jako zemětřesením nahnala strach i pekelnému Plutonovi. A tou velkou ranou zůstal na rovné zemi chvíli omráčen, a hned lid, domnívaje se, že ho zabil nějaký blesk – když se ten velký zástup vrátil – na způsob mravenců, kteří zuřivě pobíhají po kmeni poraženého dubu – tak i tito, pobíhajíce po jeho širých údech, rvali je hustými ranami.","Tu se obr probral, a cítě se málem pokryt tím množstvím, hned ucítil, jak ho bodnutí pálí – vydal řev, který zněl jako strašlivý hrom; opřel ruce o zem, zvedl hrůzostrašnou tvář, sáhl si jednou rukou na hlavu a nalezl ji plnou lidí zachycených ve vlasech na způsob drobných živočichů, kteří se v nich obvykle rodí; načež, potřásaje hlavou, metal lidi do vzduchu nejinak, než se děje s krupobitím, když se žene se zuřivostí větrů, a mnoho z těch lidí bylo nalezeno mrtvých, ušlapaných nohama těch, kteří na nich stáli. – A držíce se vlasů a snažíce se v nich ukrýt, počínali si jako námořníci za bouře, kteří šplhají po lanech, aby stáhli plachty a nastavili větru méně. –","Novinky o věcech na Východě? Věz, že v měsíci červnu se objevil obr, který přichází z pusté Libye:.... na způsob mravenců, kteří zuřivě pobíhají.... po kmeni stromu poraženém sekerou drsného venkovana.","Tento obr se narodil v pohoří Atlas a byl to hrdina; musel bojovat s Egypťany a Araby, Médy a Peršany, živil se v moři velrybami, velkými vorvani a loďmi.","Mars, boje se o život, utekl pod (stolec) Jovův....","A tím velkým pádem se zdálo, že se třásla celá provincie."],"ref":{"s":"C.A","l":96,"st":"v","z":true,"raw":"C. A. 96 v"},"ca":[527,529]},{"id":"s506","o":"Profezie","c":"I","str":349,"ni":"profezia","nc":"Proroctví","it":["Vedrassi la specie leonina colle unghiate branche aprire la terra, e nelle fatte spelonche seppellire sè insieme colli altri animali a sè sottoposti.","Usciranno dalla terra animali vestiti di tenebre, i quali, con maravigliosi assalti, assaliranno l’umana generazione, e quella da feroci morsi fia, con confusione di sangue, da essi divorata.","Ancora, scorrerà per l’aria la nefanda specie volatile, la quale assalirà li omini e li animali, e di quelli si ciberanno con gran gridore: empieranno i loro ventri di vermiglio sangue.","Vedrassi il sangue uscire dalle stracciate carni, rigare le superfiziali parti delli omini.","Verrà alli omini tal crudele malattia, che colle proprie unghie si stracceranno le loro carni — sarà la rogna.","Vedrassi le piante rimanere sanza foglie, e i fiumi fermare i loro corsi.","L’acqua del mare si leverà sopra l’alte cime de’ monti, verso il cielo, e ricaderà sopra alle abitazioni delli omini — cioè per nuvoli.","Vederà i maggiori alberi delle selve essere portati dal furor de’ venti dall’Oriente all’Occidente — cioè per mare.","Li omini getteranno via le proprie vettovaglie — cioè seminando."],"cs":["Bude vidět lví plémě, jak drápatými tlapami otvírá zemi a ve vyhloubených slujích pohřbívá sebe spolu s ostatními zvířaty, jež jsou mu podřízena.","Ze země vyjdou zvířata oděná tmou, která podivuhodnými útoky napadnou lidské pokolení, a to bude od nich krutými kousnutími za prolévání krve pozřeno.","Též se bude vzduchem nést ohavné létavé plémě, které napadne lidi i zvířata a bude se jimi živit s velkým křikem: naplní si břicha rudou krví.","Bude vidět krev, jak vytéká z rozdrásaného masa a brázdí povrch lidských těl.","Přijde na lidi tak krutá nemoc, že si vlastními nehty budou drásat maso – bude to svrab.","Bude vidět, jak rostliny zůstávají bez listí a řeky zastavují svůj tok.","Mořská voda se zvedne nad vysoké vrcholky hor, k nebi, a znovu dopadne na lidská obydlí – totiž v podobě mračen.","Uvidíš největší stromy lesů unášené zuřivostí větrů od Východu k Západu – totiž po moři.","Lidé budou zahazovat vlastní potraviny – totiž při setí."],"ref":{"s":"C.A","l":143,"st":"r","z":true,"raw":"C. A. 143 r"},"ca":[778]},{"id":"s507","o":"Profezie","c":"II","str":350,"ni":"de’ fanciulli che stanno legati nelle fascie","nc":"O nemluvňatech zavinutých do povijanů","it":["O città marine! io veggo in voi i vostri cittadini, così femmine come maschi, essere istrettamente da forti legami, colle braccia e gambe, esser legati da gente, che non intenderanno i nostri linguaggi; e sol vi potrete isfogare li vostri dolori e perduta libertà mediante i lagrimosi pianti e li sospiri e lamentazione in fra voi medesimi, chè chi vi lega non v’intenderà, nè voi loro intenderete."],"cs":["Ó přímořská města! Vidím ve vás vaše občany, ženy i muže, pevně spoutané silnými pouty na rukou i nohou, svázané lidmi, kteří nebudou rozumět naší řeči; a své bolesti a ztracenou svobodu si budete moci vylít jen v slzavém pláči, ve vzdeších a nářcích mezi sebou, neboť ten, kdo vás svazuje, vám nebude rozumět, ani vy jemu."],"ref":{"s":"C.A","l":143,"st":"r","z":false,"raw":"C. A. 143 r"},"ca":[778]},{"id":"s508","o":"Profezie","c":"III","str":351,"ni":"de’ putti che tettano","nc":"O kojencích","it":["Molti Franceschi, Domenichi e Benedetti mangeranno quel che da altri altre volte vicinamente è stato mangiato, che staranno molti mesi avanti che possano parlare."],"cs":["Mnoho Františků, Dominiků a Benediktů bude jíst to, co jiní jindy a nedávno jedli, a potrvá mnoho měsíců, než budou moci mluvit."],"ref":{"s":"I","l":67,"st":"r","z":false,"raw":"I. 67 r"},"ca":[]},{"id":"s509","o":"Profezie","c":"IV","str":351,"ni":"il dormire sopra le piume dell’uccelli","nc":"Spaní na ptačím peří","it":["Molta turba fia quella che, dimenticato loro essere e nome, staran come morte sopra le spoglie delli altri morti."],"cs":["Velký bude zástup těch, kteří, zapomenuvše své bytí i jméno, budou ležet jako mrtví na pozůstatcích jiných mrtvých."],"ref":{"s":"C.A","l":362,"st":"r","z":true,"raw":"C. A. 362 r"},"ca":[2016,2018]},{"id":"s510","o":"Profezie","c":"V","str":351,"ni":"dello scriver lettere da un paese a un altro","nc":"O psaní dopisů z jedné země do druhé","it":["Parleransi li omini di remotissimi paesi l’uno all’altro, e risponderansi."],"cs":["Lidé z nejvzdálenějších zemí spolu budou mluvit a budou si odpovídat."],"ref":{"s":"C.A","l":362,"st":"r","z":false,"raw":"C. A. 362 r"},"ca":[2016,2018]},{"id":"s511","o":"Profezie","c":"VI","str":351,"ni":"delle putte maritate","nc":"O vdávaných dívkách","it":["Vedrassi ai padri donare le lor figliole alla lussuria delli omini, e premiare, e abbandonare ogni passata guardia — quando si maritano le putte."],"cs":["Bude vidět, jak otcové dávají své dcery chlípnosti mužů, a ještě je za to odměňují, a opouštějí všechnu dřívější ostražitost – když se dívky vdávají."],"ref":{"s":"I","l":64,"st":"r","z":false,"raw":"I. 64 r"},"ca":[]},{"id":"s512","o":"Profezie","c":"VII","str":351,"ni":"delle dote delle fanciulle","nc":"O věnech dívek","it":["E dove prima la gioventù femminina non si potea difendere dalla lussuria e rapina de’ maschi, nè per guardie di parenti, nè fortezze di mura; verrà tempo che bisognerà, che padre e parenti d’esse fanciulle le paghino di gran prezzo chi voglia dormire con loro, ancorachè esse sien ricche, nobili e bellissime.","Certo e’ par qui che la natura voglia spegnere la umana specie, come cosa inutile al mondo e guastatrice di tutte le cose create."],"cs":["A kde se dříve mladé ženy nemohly ubránit chlípnosti a dravosti mužů ani strážemi příbuzných, ani pevností zdí, přijde čas, kdy otec a příbuzní těch dívek budou muset za velkou cenu platit tomu, kdo s nimi bude chtít spát, třebaže jsou bohaté, urozené a překrásné.","Věru se tu zdá, že příroda chce vyhubit lidský rod jako věc světu neužitečnou a ničitelku všech stvořených věcí."],"ref":{"s":"C.A","l":362,"st":"v","z":false,"raw":"C. A. 362 v"},"ca":[2019,2020]},{"id":"s513","o":"Profezie","c":"VIII","str":352,"ni":"dello spegnere il lume a chi va al letto","nc":"O zhášení světla před spaním","it":["Molti, per mandare fòri il fiato con troppa prestezza, perderanno il vedere e in breve tutti i sentimenti."],"cs":["Mnozí, protože příliš prudce vypustí dech, ztratí zrak a brzy všechny smysly."],"ref":{"s":"C.A","l":362,"st":"r","z":false,"raw":"C. A. 362 r"},"ca":[2016,2018]},{"id":"s514","o":"Profezie","c":"IX","str":352,"ni":"del sognare","nc":"O snění","it":["Andranno li omini, e non si moveranno; parleranno con chi non si trova; sentiranno chi non parla."],"cs":["Lidé budou chodit, a nepohnou se; budou mluvit s tím, kdo tu není; budou slyšet toho, kdo nemluví."],"ref":{"s":"C.A","l":145,"st":"r","z":false,"raw":"C. A. 145 r"},"ca":[784,786]},{"id":"s515","o":"Profezie","c":"X","str":352,"ni":"ancora del sognare","nc":"Ještě o snění","it":["Alli omini parrà vedere nel cielo nove ruine; parrà in quello levarsi a volo, e da quello fuggire con paura le fiamme, che di lui discendano; sentiran parlare li animali, di qualunque sorta, il linguaggio umano; scorreranno immediate colla lor persona in diverse parti del mondo, sanza moto; vedranno nelle tenebre grandissimi splendori. — Oh! maraviglia della umana spezie! Qual frenesia t’ha sì condotto? Parlerai cogli animali di qualunque spezie, e quelli con teco in linguaggio umano. Vedratti cadere di grandi alture, sanza tuo danno. I torrenti t’accompagneranno."],"cs":["Lidem se bude zdát, že vidí na nebi nové zkázy; bude se jim zdát, že se k němu vznášejí v letu a že z něho se strachem prchají před plameny, které z něho sestupují; uslyší zvířata všeho druhu mluvit lidskou řečí; budou se ve vlastní osobě okamžitě přenášet do různých částí světa, a bez pohybu; uvidí ve tmě převeliké jasy. – Ó, divný lidský rode! Jaké šílenství tě k tomu přivedlo? Budeš mluvit se zvířaty všeho druhu a ona s tebou lidskou řečí. Uvidíš se padat z velkých výšek bez úhony. Bystřiny tě budou provázet."],"ref":null,"ca":[]},{"id":"s516","o":"Profezie","c":"XI","str":353,"ni":"dell’ombra che si move coll’uomo","nc":"O stínu, který se pohybuje s člověkem","it":["Vedrannosi forme e figure d’uomini e d’animali, che seguiranno essi animali o omini, dovunque fuggiranno: e tal fia il moto di lui qual è dell’altro, ma parrà cosa mirabile delle varie grandezze in che essi si trasmutano."],"cs":["Bude vidět tvary a podoby lidí a zvířat, které budou ta zvířata či lidi následovat, kamkoli prchnou: a pohyb jednoho bude jako pohyb druhého, ale podivuhodné se bude zdát, do jak rozličných velikostí se proměňují."],"ref":{"s":"C.A","l":362,"st":"r","z":false,"raw":"C. A. 362 r"},"ca":[2016,2018]},{"id":"s517","o":"Profezie","c":"XII","str":353,"ni":"dell’ombra che fa l’omo di notte col lume","nc":"O stínu, který vrhá člověk v noci při světle","it":["Appariranno grandissime figure in forma umana, le quali quanto più le ti farai vicino, più diminuiranno la loro immensa magnitudine."],"cs":["Objeví se převeliké postavy v lidské podobě, které čím blíže k nim přistoupíš, tím více budou zmenšovat svou nesmírnou velikost."],"ref":{"s":"K","l":50,"st":"v","z":false,"raw":"K. 50 v"},"ca":[]},{"id":"s518","o":"Profezie","c":"XIII","str":353,"ni":"dell’ombra del sole e dello specchiarsi nell’acqua in un medesimo tempo","nc":"O stínu od slunce a zrcadlení ve vodě zároveň","it":["Vedrassi molte volte l’uno omo diventare tre, e tutti lo seguono: e spesso l’uno, il più certo, l’abbandona."],"cs":["Mnohokrát bude vidět, jak se z jednoho člověka stanou tři a všichni ho následují; a často ho ten jeden, nejjistější, opouští."],"ref":{"s":"A","l":362,"st":"r","z":false,"raw":"A. 362 r"},"ca":[]},{"id":"s519","o":"Profezie","c":"XIV","str":354,"ni":"delle lingue de’ diversi popoli","nc":"O jazycích různých národů","it":["Verrà a tale la generazione umana, che non si intenderà il parlare l’uno dell’altro — cioè un tedesco con un turco."],"cs":["Lidské pokolení dospěje tak daleko, že si jeden nebude rozumět s řečí druhého – totiž Němec s Turkem."],"ref":{"s":"I","l":64,"st":"r","z":false,"raw":"I. 64 r"},"ca":[]},{"id":"s520","o":"Profezie","c":"XV","str":354,"ni":"de’ soldati a cavallo","nc":"O jezdcích na koních","it":["Molti saran veduti portati da grandi animali, con veloce corso, alla ruina della sua vita e prestissima morte. Per l’aria e per la terra saranno veduti animali di diversi colori portarne con furore li omini alla distruzione di lor vita."],"cs":["Mnozí budou viděni, jak je velká zvířata rychlým během nesou ke zkáze jejich života a k nejrychlejší smrti. Vzduchem i po zemi bude vidět zvířata různých barev, jak zuřivě nesou lidi ke zničení jejich života."],"ref":{"s":"C.A","l":362,"st":"r","z":false,"raw":"C. A. 362 r"},"ca":[2016,2018]},{"id":"s521","o":"Profezie","c":"XVI","str":354,"ni":"de’ segatori","nc":"O pilařích","it":["Saranno molti, che si moveran l’uno contra dell’altro, tenendo in mano il tagliente ferro; questi non si faranno intra loro altro nocimento, che di stanchezza, perchè quanto l’uno si caccerà innanzi, tanto l’altro si ritirerà indirieto. Ma tristo chi si inframmetterà in mezzo, perchè al fine rimarrà tagliato in pezzi."],"cs":["Bude mnoho těch, kteří se budou pohybovat jeden proti druhému, držíce v ruce ostré železo; ti si navzájem neublíží jinak než únavou, protože o kolik se jeden posune vpřed, o tolik druhý ustoupí zpět. Ale běda tomu, kdo se vloží mezi ně, neboť nakonec zůstane rozřezán na kusy."],"ref":{"s":"C.A","l":362,"st":"r","z":false,"raw":"C. A. 362 r"},"ca":[2016,2018]},{"id":"s522","o":"Profezie","c":"XVII","str":354,"ni":"de’ zappatori","nc":"O kopáčích","it":["Molti fien quegli, che scorticando la madre, le arrovescieranno la sua pelle addosso — i lavoratori della terra."],"cs":["Mnoho bude těch, kteří stahujíce kůži své matce, obrátí jí tu kůži naruby – rolníci."],"ref":{"s":"I","l":64,"st":"r","z":false,"raw":"I. 64 r"},"ca":[]},{"id":"s523","o":"Profezie","c":"XVIII","str":355,"ni":"del seminare","nc":"O setí","it":["Allora la gran parte delli omini, che resteran vivi, gitteran fuori delle lor case le serbate vettovaglie in libera preda delli uccelli e animali terrestri, sanza curarsi d’esse in parte alcuna."],"cs":["Tehdy velká část lidí, kteří zůstanou naživu, vyhází ze svých domů schované potraviny ptákům a zvířatům na zemi za volnou kořist, aniž by o ně jakkoli dbali."],"ref":{"s":"C.A","l":362,"st":"r","z":true,"raw":"C. A. 362 r"},"ca":[2016,2018]},{"id":"s524","o":"Profezie","c":"XIX","str":355,"ni":"le terre lavorate","nc":"Zoraná pole","it":["Vedrassi voltare la terra sotto sopra, e riguardare l’oppositi emisferi, e scoprire le spelonche a ferocissimi animali."],"cs":["Bude vidět, jak se země obrací vzhůru nohama, hledí k protilehlým polokoulím a odkrývá doupata nejdivočejších zvířat."],"ref":{"s":"C.A","l":362,"st":"r","z":false,"raw":"C. A. 362 r"},"ca":[2016,2018]},{"id":"s525","o":"Profezie","c":"XX","str":355,"ni":"i calzolari","nc":"Ševci","it":["Li omini vederanno con piacere disfare, e rompere l’opere loro."],"cs":["Lidé budou s potěšením přihlížet, jak se jejich díla rozpadají a trhají."],"ref":{"s":"R","l":1312,"st":"","z":false,"raw":"R. 1312"},"ca":[],"rr":"S. K. M. II.2 3 a"},{"id":"s526","o":"Profezie","c":"XXI","str":355,"ni":"del segare delle erbe","nc":"O sekání trávy","it":["Spegneransi innumerabili vite, e farassi sopra la terra innumerabili buche."],"cs":["Uhasne nesčetně životů a na zemi vznikne nesčetně děr."],"ref":{"s":"R","l":1311,"st":"","z":false,"raw":"R. 1311"},"ca":[],"rr":"S. K. M. II.2 35"},{"id":"s527","o":"Profezie","c":"XXII","str":355,"ni":"del grano e altre semenze","nc":"O obilí a jiných semenech","it":["Getteranno li omini fori delle lor proprie case quelle vettovaglie, le quali eran dedicate a sostentar la lor vita."],"cs":["Lidé budou vyhazovat ze svých vlastních domů ty potraviny, které byly určeny k udržení jejich života."],"ref":{"s":"R","l":1310,"st":"","z":false,"raw":"R. 1310"},"ca":[],"rr":"Br. M. 212"},{"id":"s528","o":"Profezie","c":"XXIII","str":356,"ni":"del battere il grano","nc":"O mlácení obilí","it":["Li omini batteranno aspramente chi fia causa di lor vita — batteranno il grano."],"cs":["Lidé budou krutě bít toho, kdo je příčinou jejich života – budou mlátit obilí."],"ref":{"s":"I","l":65,"st":"r","z":false,"raw":"I. 65 r"},"ca":[]},{"id":"s529","o":"Profezie","c":"XXIV","str":356,"ni":"de’ giocatori","nc":"O hráčích míče","it":["Le pelli delli animali removeranno li omini, con gran gridori e bestemmie, dal lor silenzio — le balle da giuocare."],"cs":["Kůže zvířat vyburcují lidi z jejich ticha k velkému křiku a klení – míče na hraní."],"ref":{"s":"I","l":64,"st":"v","z":false,"raw":"I. 64 v"},"ca":[]},{"id":"s530","o":"Profezie","c":"XXV","str":356,"ni":"del suono della piva","nc":"O hře na dudy","it":["Il vento, passato per le pelli delli animali, farà saltare li omini — cioè la piva, che fa lo saltare."],"cs":["Vítr, procházející kůžemi zvířat, přiměje lidi skákat – totiž dudy, při nichž se tančí."],"ref":{"s":"I","l":65,"st":"r","z":false,"raw":"I. 65 r"},"ca":[]},{"id":"s531","o":"Profezie","c":"XXVI","str":356,"ni":"de’ dadi","nc":"O kostkách","it":["Vedrannosi l’ossa de’ morti, con veloce moto, trattare la fortuna del suo motore — i dadi."],"cs":["Bude vidět kosti mrtvých, jak rychlým pohybem rozhodují o štěstí toho, kdo jimi hýbe – kostky."],"ref":{"s":"I","l":65,"st":"r","z":false,"raw":"I. 65. r"},"ca":[]},{"id":"s532","o":"Profezie","c":"XXVII","str":356,"ni":"de’ battuti e scoreggiati","nc":"O flagelantech, kteří se bičují","it":["Li omini si nasconderanno sotto le scorze delle scorticate erbe, e, quivi gridando, si daran martiri, con battimenti di membra, a sè medesimi."],"cs":["Lidé se budou skrývat pod kůrou ze stažených bylin a tam s křikem budou sami sobě působit muka bitím do údů."],"ref":{"s":"C.A","l":362,"st":"r","z":false,"raw":"C. A. 362 r"},"ca":[2016,2018]},{"id":"s533","o":"Profezie","c":"XXVIII","str":357,"ni":"le lingue de’ porci e vitelli nelle budelle","nc":"Vepřové a telecí jazyky ve střevech","it":["Oh! cosa spòrca, che si vedrà l’uno animale aver la lingua in culo all’altro."],"cs":["Ó, jaká sprostota: bude vidět, jak jedno zvíře má jazyk v zadku druhého."],"ref":{"s":"C.A","l":362,"st":"r","z":false,"raw":"C. A. 362 r"},"ca":[2016,2018]},{"id":"s534","o":"Profezie","c":"XXIX","str":357,"ni":"de’ villani in camicia che lavorano","nc":"O sedlácích, kteří pracují v košili","it":["Verranno tenebre in mezzo l’Oriente, le quali con tanta oscurità tigneranno il cielo, che copre l’Italia."],"cs":["Uprostřed Východu nastane tma, která takovou temnotou zbarví nebe, jež se klene nad Itálií."],"ref":{"s":"R","l":1297,"st":"","z":true,"raw":"R. 1297"},"ca":[],"rr":"Br. M. 42 b"},{"id":"s535","o":"Profezie","c":"XXX","str":357,"ni":"de’ barbieri","nc":"O holičích","it":["Tutti li omini si fuggiranno in Africa."],"cs":["Všichni lidé utečou do Afriky."],"ref":{"s":"R","l":1297,"st":"","z":true,"raw":"R. 1297"},"ca":[],"rr":"Br. M. 42 b"},{"id":"s536","o":"Profezie","c":"I","str":357,"ni":"tiran le bombarde","nc":"Voli táhnou bombardy","it":["I buoi fieno in gran parte causa delle ruine delle città, e similemente cavalli e bufoli."],"cs":["Voli budou z velké části příčinou zkázy měst, a podobně koně a buvoli."],"ref":{"s":"R","l":1297,"st":"","z":false,"raw":"R. 1297"},"ca":[],"rr":"Br. M. 42 b"},{"id":"s537","o":"Profezie","c":"II","str":357,"ni":"de’ buoi che si mangiano,","nc":"O volech, které jíme","it":["Mangeranno i padron delle possessioni i lor propri lavoratori."],"cs":["Majitelé statků budou jíst své vlastní pracovníky."],"ref":{"s":"C.A","l":362,"st":"r","z":false,"raw":"C. A. 362 r"},"ca":[2016,2018]},{"id":"s538","o":"Profezie","c":"III","str":358,"ni":"delli asini bastonati","nc":"O bitých oslech","it":["O natura trascurata, perche ti se’ fatta parziale, facendoti ai tua figli d’alcuni pietosa e benigna madre, ad altri crudelissima e dispietata matrigna? Io veggo i tua figlioli esser dati in altrui servitù, sanza mai benefizio alcuno; e in loco di remunerazione de’ fatti benefizi, esser pagati di grandissimi martiri; e spender sempre la lor vita in benefizio del suo malefattore."],"cs":["Ó nedbalá přírodo, proč jsi tak nespravedlivá, že jsi některým ze svých dětí soucitnou a laskavou matkou, jiným nejkrutější a nemilosrdnou macechou? Vidím tvé děti vydané do cizí služby, a to bez jakékoli odměny; a místo odplaty za prokázaná dobrodiní jsou spláceny převelikými mukami; a celý svůj život vynakládají ku prospěchu svého trýznitele."],"ref":{"s":"C.A","l":143,"st":"r","z":false,"raw":"C. A. 143 r"},"ca":[778]},{"id":"s539","o":"Profezie","c":"IV","str":358,"ni":"delli asini","nc":"O oslech","it":["Le molte fatiche saran remunerate di fame, di sete, di disagio e di mazzate e di punture e bestemmie e gran villanie."],"cs":["Velké námahy budou odměněny hladem, žízní, strádáním a ranami holí, bodáním, klením a velkými urážkami."],"ref":{"s":"C.A","l":362,"st":"r","z":false,"raw":"C. A. 362 r"},"ca":[2016,2018]},{"id":"s540","o":"Profezie","c":"V","str":358,"ni":"delle campanelle de’ muli che stanno presso ai loro orecchi","nc":"O rolničkách mul, které jim visí u uší","it":["Sentirassi in molte parte dell’Europa strumenti di varie magnitudini far diverse armonie, con grandissime fatiche di chi più presso l’ode."],"cs":["V mnoha částech Evropy bude slyšet nástroje různých velikostí, jak hrají rozličné harmonie k velikému trápení toho, kdo je slyší nejblíže."],"ref":{"s":"C.A","l":362,"st":"r","z":false,"raw":"C. A. 362 r"},"ca":[2016,2018]},{"id":"s541","o":"Profezie","c":"VI","str":358,"ni":"de’ muli che portano le ricche some dell’argento e oro","nc":"O mulách, které nesou bohaté náklady stříbra a zlata","it":["Molti tesori e gran ricchezze saranno appresso alti animali di quattro piedi, i quali le porteranno in diversi lochi."],"cs":["Mnoho pokladů a velkých bohatství bude u vysokých čtyřnohých zvířat, která je ponesou na různá místa."],"ref":{"s":"L","l":91,"st":"r","z":false,"raw":"L. 91 r"},"ca":[]},{"id":"s542","o":"Profezie","c":"VII","str":359,"ni":"de’ capretti","nc":"O kůzlatech","it":["Ritornerà il tempo d’Erode, perchè l’innocenti figliuoli saranno tolti alle loro balie, e da crudeli omini, di gran ferite, moriranno."],"cs":["Vrátí se čas Herodův, neboť nevinné děti budou odňaty svým kojným a zemřou krutými lidmi na velké rány."],"ref":{"s":"R","l":1313,"st":"","z":false,"raw":"R. 1313"},"ca":[],"rr":"S. K. M. II.2 69 a"},{"id":"s543","o":"Profezie","c":"VIII","str":359,"ni":"delle pecore, vacche, capre e simili","nc":"O ovcích, kravách, kozách a podobných zvířatech","it":["A innumerabili saran tolti i loro piccoli figlioli, e quelli scannati, e crudelissimamente squartati."],"cs":["Nesčetným budou odňaty jejich malé děti, a ty budou podřezány a nejkrutěji rozčtvrceny."],"ref":{"s":"C.A","l":143,"st":"r","z":false,"raw":"C. A. 143 r"},"ca":[778]},{"id":"s544","o":"Profezie","c":"IX","str":359,"ni":"delle gatte che mangiano i topi","nc":"O kočkách, které jedí myši","it":["A voi, città dell’Africa, si vedrà i vostri nati essere squarciati nelle proprie case da crudelissimi e rapaci animali del paese vostro."],"cs":["Vám, města Afriky, se stane, že bude vidět, jak jsou vaši potomci rozsápáni ve vlastních domech nejkrutějšími a dravými zvířaty vaší země."],"ref":{"s":"C.A","l":143,"st":"r","z":false,"raw":"C. A. 143 r"},"ca":[778]},{"id":"s545","o":"Profezie","c":"X","str":359,"ni":"le api che fanno la cera delle candele","nc":"Včely, které dělají vosk na svíce","it":["Sarà annegato chi fa il lume al culto divino.","E quelli, che pascono l’erbe, faran della notte giorno — sevo."],"cs":["Utopen bude ten, kdo dělá světlo pro bohoslužbu.","A ti, kdo se pasou na trávě, udělají z noci den – lůj."],"ref":{"s":"R","l":1297,"st":"","z":false,"raw":"R. 1297"},"ca":[],"rr":"Br. M. 42 b"},{"id":"s546","o":"Profezie","c":"XI","str":359,"ni":"dell’api","nc":"O včelách","it":["E a molti altri saran tolte le munizioni e lor cibi, e crudelmente, da gente sanza ragione, saranno sommersi e annegati. O giustizia di Dio, perchè non ti desti a vedere così malmenare i tua creati!"],"cs":["A mnohým jiným budou odňaty zásoby a jejich potrava, a budou krutě od lidí bez rozumu potopeni a utopeni. Ó spravedlnosti Boží, proč neprocitneš, abys viděla, jak se takto týrá tvé tvorstvo!"],"ref":{"s":"C.A","l":143,"st":"r","z":false,"raw":"C. A. 143 r"},"ca":[778]},{"id":"s547","o":"Profezie","c":"XII","str":360,"ni":"delle formiche","nc":"O mravencích","it":["Molti popoli fien quelli, che nasconderan sè e sua figlioli e vettovaglie dentro alle oscure caverne; e lì, nelli lochi tenebrosi, ciberan sè e sua famiglia per molti mesi, sanza altro lume accidentale o naturale."],"cs":["Mnoho bude národů, které ukryjí sebe, své děti a potraviny v temných jeskyních; a tam, v temných místech, budou živit sebe i svou rodinu po mnoho měsíců bez jakéhokoli světla, ať umělého, či přirozeného."],"ref":{"s":"C.A","l":143,"st":"r","z":false,"raw":"C. A. 143 r"},"ca":[778]},{"id":"s548","o":"Profezie","c":"XIII","str":360,"ni":"delle mosche e altri insetti","nc":"O mouchách a jiném hmyzu","it":["Usciranno li omini dalle sepolture, convertiti in uccelli, e assaliranno li altri omini togliendo loro il cibo dalle proprie mani e mense — le mosche."],"cs":["Lidé vyjdou z hrobů, proměnění v ptáky, a napadnou ostatní lidi, berouce jim jídlo z vlastních rukou a stolů – mouchy."],"ref":{"s":"I","l":64,"st":"r","z":false,"raw":"I. 64 r"},"ca":[]},{"id":"s549","o":"Profezie","c":"XIV","str":360,"ni":"delle civette o gufi con che s’uccella alla pania","nc":"O sýčcích či výrech, s nimiž se chytají ptáci na lep","it":["Molti periranno di fracassamento di testa, e salteranno loro li occhi in gran parte della testa, per causa d’animali paurosi usciti dalle tenebre."],"cs":["Mnozí zahynou rozbitím hlavy a oči jim vyskočí daleko z hlavy kvůli strašlivým zvířatům, která vyšla z temnot."],"ref":{"s":"C.A","l":362,"st":"r","z":false,"raw":"C. A. 362 r"},"ca":[2016,2018]},{"id":"s550","o":"Profezie","c":"XV","str":360,"ni":"delle biscie portate dalle cicogne","nc":"O hadech, které nesou čápi","it":["Vedrassi in grandissima altezza dell’aria lunghissimi serpi combattere colli uccelli."],"cs":["V převeliké výšce vzduchu bude vidět převelice dlouhé hady, jak bojují s ptáky."],"ref":{"s":"C.A","l":127,"st":"v","z":false,"raw":"C. A. 127 v"},"ca":[701,703]},{"id":"s551","o":"Profezie","c":"XVI","str":361,"ni":"i pesci lessi","nc":"Vařené ryby","it":["Li animali d’acqua moriranno nelle bollenti acque."],"cs":["Vodní živočichové zemřou ve vroucích vodách."],"ref":{"s":"C.A","l":362,"st":"r","z":false,"raw":"C. A. 362 r"},"ca":[2016,2018]},{"id":"s552","o":"Profezie","c":"XVII","str":361,"ni":"de’ pesci che si mangiano non nati","nc":"O rybách, které se jedí nenarozené (jikry)","it":["Infinita generazione si perderà per la morte delle grandi."],"cs":["Nesčetné pokolení zahyne smrtí těch velkých."],"ref":{"s":"C.A","l":362,"st":"r","z":false,"raw":"C. A. 362 r"},"ca":[2016,2018]},{"id":"s553","o":"Profezie","c":"XVIII","str":361,"ni":"de’ nicchi e chiocciole che sono ributtate dal mare, che marciscono dentro ai lor gocci","nc":"O lasturách vyvržených mořem","it":["Oh! quanti fien quelli, che, poichè fien morti, marciranno nelle lor proprie case, empiendo le circostanti parti piene di fetulente puzzo!"],"cs":["Ó, kolik bude těch, kteří po své smrti budou hnít ve vlastních domech a naplní okolí páchnoucím puchem!"],"ref":{"s":"I","l":67,"st":"r","z":false,"raw":"I. 67 r"},"ca":[]},{"id":"s554","o":"Profezie","c":"XIX","str":361,"ni":"dell’ova che sendo mangiate non possono fare i pulcini","nc":"O vejcích, z nichž se po snědení nemohou vylíhnout kuřata","it":["Oh! quanti fien quegli, ai quali sarà proibito il nascere."],"cs":["Ó, kolik bude těch, jimž bude zakázáno narodit se!"],"ref":{"s":"C.A","l":36,"st":"","z":false,"raw":"C. A. 36"},"ca":[198,200,202,204]},{"id":"s555","o":"Profezie","c":"XX","str":361,"ni":"delle taccole e stornelli","nc":"O kavkách a špačcích","it":["Quelli che si fideranno abitare appresso di lui, che saranno gran turbe, questi tutti moriranno di crudele morte, e si vedran i padri e le madri, d’insieme colle sue famiglie, esser da crudeli animali divorati e morti."],"cs":["Ti, kdo se odváží bydlet u něho, a bude jich velký zástup, ti všichni zemřou krutou smrtí, a bude vidět otce a matky i s jejich rodinami, jak je kruté šelmy zabíjejí a pojídají."],"ref":null,"ca":[]},{"id":"s556","o":"Profezie","c":"XXI","str":362,"ni":"delle api","nc":"O včelách","it":["Vivono a popoli insieme, sono annegate per torle il miele: molti e grandissimi popoli saranno annegati nelle lor proprie case."],"cs":["Žijí pospolu v národech a topí se, aby se jim vzal med: mnoho převelikých národů bude utopeno ve vlastních domech."],"ref":{"s":"R","l":1329,"st":"","z":false,"raw":"R. 1329"},"ca":[],"rr":"W. XXX"},{"id":"s557","o":"Profezie","c":"I","str":362,"ni":"delle noci e ulive e ghiande e castagne e simili","nc":"O ořeších, olivách, žaludech, kaštanech a podobných plodech","it":["Molti figlioli da dispietate bastonate fien tolti delle proprie braccia delle lor madri, e gittati in terra, e poi lacerati."],"cs":["Mnoho dětí bude nemilosrdnými ranami holí vyrváno z náruče jejich vlastních matek, hozeno na zem a pak rozdrásáno."],"ref":{"s":"C.A","l":143,"st":"v","z":false,"raw":"C. A. 143 v"},"ca":[779]},{"id":"s558","o":"Profezie","c":"II","str":362,"ni":"de’ noci battuti","nc":"O otloukaných ořešácích","it":["Quelli che avranno fatto meglio saranno più battuti, e i sua figliuoli tolti e scorticati, overo spogliati, e rotte e fracassate le sue ossa."],"cs":["Ti, kdo se nejlépe činili, budou nejvíc biti, a jejich děti jim budou vzaty a staženy z kůže čili obnaženy a jejich kosti zlámány a rozdrceny."],"ref":{"s":"I","l":65,"st":"v","z":false,"raw":"I. 65. v"},"ca":[]},{"id":"s559","o":"Profezie","c":"III","str":363,"ni":"l’ulive che cadono dagli ulivi dannoci olio che fa lume","nc":"O olivách a oleji, který svítí","it":["Discenderà con furia diverso la terra chi ci darà nutrimento e luce."],"cs":["Prudce sestoupí k zemi ten, kdo nám dá potravu i světlo."],"ref":{"s":"C.A","l":362,"st":"r","z":false,"raw":"C. A. 362 r"},"ca":[2016,2018]},{"id":"s560","o":"Profezie","c":"IV","str":363,"ni":"de’ legnami che bruciano","nc":"O dřevu, které hoří","it":["Li alberi e arbusti delle gran selve si convertiranno in cenere."],"cs":["Stromy a keře velkých lesů se promění v popel."],"ref":{"s":"C.A","l":362,"st":"r","z":false,"raw":"C. A. 362 r"},"ca":[2016,2018]},{"id":"s561","o":"Profezie","c":"V","str":363,"ni":"delli alberi che nutriscono i nesti","nc":"O stromech, které živí rouby","it":["Vedrannosi i padri e le madri fare molto più giovamento ai figliastri, che ai lor veri figlioli."],"cs":["Bude vidět, jak otcové a matky prokazují mnohem víc dobrého nevlastním dětem než svým pravým dětem."],"ref":null,"ca":[]},{"id":"s562","o":"Profezie","c":"I","str":363,"ni":"della sola delle scarpe che son di bue","nc":"O podrážkách bot, které jsou z hovězí kůže","it":["E si vedrà in gran parte del paese camminare sopra le pelli delli grandi animali."],"cs":["A ve velké části země bude vidět, jak se chodí po kůžích velkých zvířat."],"ref":{"s":"C.A","l":362,"st":"r","z":false,"raw":"C. A. 362 r"},"ca":[2016,2018]},{"id":"s563","o":"Profezie","c":"II","str":364,"ni":"de’ crivelli fatti di pelle d’animali","nc":"O sítech z kůže zvířat","it":["Vedrassi il cibo degli animali- passar dentro alle lor pelli per ogni parte, salvo che per la bocca, e penetrare dall’opposta parte insino alla piana terra."],"cs":["Bude vidět, jak potrava zvířat prochází jejich kůžemi všude, jen ne ústy, a proniká opačnou stranou až na rovnou zem."],"ref":{"s":"C.A","l":362,"st":"r","z":false,"raw":"C. A. 362 r"},"ca":[2016,2018]},{"id":"s564","o":"Profezie","c":"III","str":364,"ni":"delle lanterne","nc":"O lucernách","it":["Le feroci corna de’ possenti tori difenderanno la luce notturna dall’impetuoso furor de’ venti."],"cs":["Divoké rohy mocných býků budou chránit noční světlo před prudkou zuřivostí větrů."],"ref":{"s":"F","l":64,"st":"v","z":false,"raw":"F. 64 v"},"ca":[]},{"id":"s565","o":"Profezie","c":"IV","str":364,"ni":"delle medesime","nc":"O lucernách též","it":["I buoi, colle lor corna, difenderanno il foco dalla sua morte — la lanterna."],"cs":["Voli svými rohy budou chránit oheň před jeho smrtí – lucerna."],"ref":{"s":"A","l":362,"st":"r","z":false,"raw":"A. 362 r"},"ca":[]},{"id":"s566","o":"Profezie","c":"V","str":364,"ni":"delle maniche de’ coltelli fatte di corna di castrone","nc":"O střenkách nožů z beraního rohu","it":["Nelle corna delli animali si vedranno taglienti ferri, colli quali si toglie la vita a molti della loro specie."],"cs":["V rozích zvířat bude vidět ostrá železa, jimiž se bere život mnohým z jejich druhu."],"ref":{"s":"C.A","l":362,"st":"r","z":false,"raw":"C. A. 362 r"},"ca":[2016,2018]},{"id":"s567","o":"Profezie","c":"VI","str":364,"ni":"delli archi fatti colli corni de’ buoi","nc":"O lucích z volských rohů","it":["Molti fien quelli che, per causa delle bovine corna, moriranno di dolente morte."],"cs":["Mnoho bude těch, kteří kvůli volským rohům zemřou bolestnou smrtí."],"ref":{"s":"C.A","l":362,"st":"v","z":false,"raw":"C. A. 362 v"},"ca":[2019,2020]},{"id":"s568","o":"Profezie","c":"VII","str":365,"ni":"delle piume ne’ letti","nc":"O peří v postelích","it":["Li animali volatili sosterran l’omini colle lor proprie penne."],"cs":["Létaví živočichové budou nést lidi svými vlastními pery."],"ref":{"s":"C.A","l":362,"st":"r","z":false,"raw":"C. A. 362 r"},"ca":[2016,2018]},{"id":"s569","o":"Profezie","c":"VIII","str":365,"ni":"del pettine nel telaio","nc":"O paprsku na tkalcovském stavu","it":["Molte volte la cosa disunita fia causa di grande unizione — cioè il pettine, fatto dalla disunita canna, unisce le fila nella seta."],"cs":["Mnohokrát bude věc rozdělená příčinou velkého spojení – totiž paprsek, udělaný z rozštěpené třtiny, spojuje nitě v hedvábí."],"ref":{"s":"F","l":65,"st":"r","z":false,"raw":"F. 65 r"},"ca":[]},{"id":"s570","o":"Profezie","c":"IX","str":365,"ni":"il filatoio da seta","nc":"Soukací stroj na hedvábí","it":["Sentirassi le dolenti grida, le alte strida, le rauche e infocate voci di quei che fieno con tormento spogliati, e al fine lasciati ignudi e sanza moto: e questo fia per causa del motore, che tutto volge."],"cs":["Bude slyšet bolestný nářek, hlasité ječení, chraplavé a rozpálené hlasy těch, kdo budou s mukami svlékáni a nakonec ponecháni nazí a bez hnutí: a to bude kvůli hybateli, který vším otáčí."],"ref":{"s":"C.A","l":362,"st":"r","z":false,"raw":"C. A. 362 r"},"ca":[2016,2018]},{"id":"s571","o":"Profezie","c":"X","str":365,"ni":"del lino che fa la cura delle genti","nc":"O lnu, který slouží lidem","it":["Saran reveriti e onorati, e con reverenzia e amore ascoltati li sua precetti, di chi prima fusse legato, sdraiato, e martirizzato da molte e diverse battiture."],"cs":["Ctěny a váženy a s úctou a láskou poslouchány budou rady toho, kdo byl předtím svázán, natažen a mučen mnoha a rozličnými údery."],"ref":{"s":"C.A","l":362,"st":"r","z":false,"raw":"C. A. 362 r"},"ca":[2016,2018]},{"id":"s572","o":"Profezie","c":"XI","str":365,"ni":"del manico della scure","nc":"O topůrku sekery","it":["Le selve partoriranno figlioli, che fiano causa della lor morte - il manico della scure."],"cs":["Lesy porodí děti, které budou příčinou jejich smrti – topůrko sekery."],"ref":{"s":"F","l":64,"st":"v","z":false,"raw":"F. 64 v"},"ca":[]},{"id":"s573","o":"Profezie","c":"XII","str":366,"ni":"il bastone ch’è morto","nc":"Hůl, která je mrtvá","it":["Il movimento de’ morti farà fuggire, con dolore e pianto e con grida, molti vivi."],"cs":["Pohyb mrtvých přiměje mnoho živých utíkat s bolestí, pláčem a křikem."],"ref":{"s":"C.A","l":362,"st":"r","z":false,"raw":"C. A. 362 r"},"ca":[2016,2018]},{"id":"s574","o":"Profezie","c":"XIII","str":366,"ni":"de’ lacciuoli e trappole","nc":"O osidlech a pastech","it":["Molti morti si moveran con furia, e piglieranno, e legheranno i vivi, e servirannogli a’ lor nemici circa la lor morte e distruzione."],"cs":["Mnoho mrtvých se prudce pohne a pochytá a sváže živé a předá je jejich nepřátelům k jejich smrti a zkáze."],"ref":{"s":"C.A","l":362,"st":"r","z":false,"raw":"C. A. 362 r"},"ca":[2016,2018]},{"id":"s575","o":"Profezie","c":"XIV","str":366,"ni":"del moto dell’acque che portano i legnami che son morti","nc":"O proudící vodě, která nese mrtvé dřevo","it":["Corpi sanz’anima per sè medesimi si moveranno, e porteran con seco innumerabile generazione di morti, togliendo le ricchezze a’ circustanti viventi."],"cs":["Těla bez duše se budou sama od sebe pohybovat a ponesou s sebou nesčetné pokolení mrtvých a budou brát bohatství okolním živým."],"ref":{"s":"A","l":362,"st":"r","z":true,"raw":"A. 362 r"},"ca":[]},{"id":"s576","o":"Profezie","c":"XV","str":366,"ni":"dei carri e navi","nc":"O vozech a lodích","it":["Vedrassi i morti portare i vivi — i carri e navi in diverse parti."],"cs":["Bude vidět mrtvé nést živé – vozy a lodi na různá místa."],"ref":{"s":"I","l":66,"st":"r","z":false,"raw":"I. 66 r"},"ca":[]},{"id":"s577","o":"Profezie","c":"XVI","str":366,"ni":"delle casse che riserrano molti tesori","nc":"O truhlách, které skrývají mnoho pokladů","it":["Troverassi dentro a de’ noci e delli alberi e altre piante tesori grandissimi, i quali lì stanno occulti, e ben guardati."],"cs":["V ořešácích, ve stromech a jiných rostlinách se najdou převeliké poklady, které jsou tam skryty a dobře střeženy."],"ref":null,"ca":[]},{"id":"s578","o":"Profezie","c":"XVII","str":367,"ni":"del navigare","nc":"O plavbě","it":["Vedrassi li alberi delle gran selve di Taurus e di Sinai, Apennino e Atlante scorrere per l’aria da oriente a occidente, da aquilone a meridie; e porteranno per l’aria gran moltitudine d’omini.","Oh! quanti vóti! oh! quanti morti! oh! quanta separazion d’amici! di parenti! e quanti fien quelli, che non rivedranno più le lor provincie, nè le lor patrie, e che moriranno sanza sepoltura, colle lor ossa sparse in diversi siti del mondo!"],"cs":["Bude vidět stromy velkých lesů Tauru a Sinaje, Apenin a Atlasu, jak se ženou vzduchem od východu na západ, od severu k jihu; a ponesou vzduchem velké množství lidí.","Ó, kolik slibů! Ó, kolik mrtvých! Ó, kolik odloučení přátel a příbuzných! A kolik bude těch, kdo už neuvidí své kraje ani svou vlast a zemřou bez pohřbu, s kostmi rozesetými po různých místech světa!"],"ref":{"s":"C.A","l":362,"st":"v","z":false,"raw":"C. A. 362 v"},"ca":[2019,2020]},{"id":"s579","o":"Profezie","c":"XVIII","str":367,"ni":"del navigare","nc":"O plavbě","it":["Saranno gran venti, per li quali le cose orientali si faranno occidentali; e quelle di mezzodì, in gran parte miste col corso de’ venti, seguirannolo per lunghi paesi."],"cs":["Budou velké větry, jimiž se věci východní stanou západními; a věci jižní, z velké části stržené během větrů, je budou následovat dalekými zeměmi."],"ref":{"s":"C.A","l":362,"st":"v","z":false,"raw":"C. A. 362 v"},"ca":[2019,2020]},{"id":"s580","o":"Profezie","c":"XIX","str":367,"ni":"de’ navili che annegano","nc":"O lodích, které tonou","it":["Vedrannosi grandissimi corpi, sanza vita, portare con furia moltitudine d’omini alla distruzione di lor vita."],"cs":["Bude vidět převeliká těla bez života, jak zuřivě nesou množství lidí ke zkáze jejich života."],"ref":{"s":"C.A","l":362,"st":"r","z":false,"raw":"C. A. 362 r"},"ca":[2016,2018]},{"id":"s581","o":"Profezie","c":"XX","str":367,"ni":"li animali che van sopra le terre andando in zoccolo","nc":"Tvorové, kteří chodí po zemi v dřevácích","it":["Saran sì grandi i fanghi, che li omini andranno sopra l’alberi de’ loro paesi."],"cs":["Bláto bude tak veliké, že lidé budou chodit po stromech svých krajů."],"ref":{"s":"C.A","l":362,"st":"r","z":false,"raw":"C. A. 362 r"},"ca":[2016,2018]},{"id":"s582","o":"Profezie","c":"XXI","str":368,"ni":"delle baghe","nc":"O kozích měších na víno","it":["Le capre condurranno il vino alle città."],"cs":["Kozy budou vozit víno do měst."],"ref":{"s":"R","l":1317,"st":"","z":false,"raw":"R. 1317"},"ca":[],"rr":"S. K. M. II.2 12 a"},{"id":"s583","o":"Profezie","c":"XXII","str":368,"ni":"del parasole","nc":"O slunečníku","it":["La percussione della spera del sole apparirà cosa che, chi la crederà coprire, sarà coperto da lei."],"cs":["Úder slunečního kotouče se ukáže být věcí, kterou kdo bude chtít zakrýt, bude jí sám zakryt."],"ref":{"s":"C.A","l":362,"st":"r","z":true,"raw":"C. A. 362 r"},"ca":[2016,2018]},{"id":"s584","o":"Profezie","c":"X","str":368,"ni":"de’ sassi convertiti in calcina de’ quali si murano le prigioni","nc":"O kamenech přeměněných ve vápno, kterým se zdí vězení","it":["Molti, che fieno disfatti dal fuoco innanzi a questo tempo, torranno la libertà a molti uomini."],"cs":["Mnozí, kteří budou před tímto časem rozloženi ohněm, vezmou svobodu mnoha lidem."],"ref":null,"ca":[]},{"id":"s585","o":"Profezie","c":"II","str":368,"ni":"dello specchiare le mura delle città nell’acqua de’ lor fossi","nc":"O zrcadlení městských hradeb ve vodě jejich příkopů","it":["Vedrannosi l’alte mura delle gran città sotto sopra ne’ loro fossi."],"cs":["Bude vidět vysoké hradby velkých měst vzhůru nohama v jejich příkopech."],"ref":{"s":"C.A","l":362,"st":"r","z":false,"raw":"C. A. 362 r"},"ca":[2016,2018]},{"id":"s586","o":"Profezie","c":"III","str":368,"ni":"dei forni","nc":"O pecích","it":["A molti fia tolto il cibo di bocca — ai forni."],"cs":["Mnohým bude vzato jídlo z úst – pecím."],"ref":{"s":"I","l":66,"st":"r","z":false,"raw":"I. 66 r"},"ca":[]},{"id":"s587","o":"Profezie","c":"IV","str":369,"ni":"ancora dei forni","nc":"Ještě o pecích","it":["A quelli, che si imboccheranno per l’altrui mani, fia loro tolto il cibo di bocca — il forno."],"cs":["Těm, jimž jídlo vkládají do úst cizí ruce, bude jídlo z úst vzato – pec."],"ref":{"s":"I","l":66,"st":"r","z":false,"raw":"I. 66 r"},"ca":[]},{"id":"s588","o":"Profezie","c":"V","str":369,"ni":"del mettere e trarre il pane dalla bocca del forno","nc":"O sázení chleba do ústí pece a jeho vytahování","it":["Per tutte le città e terre e castelli e case si vedrà, per desiderio di mangiare, trarre il proprio cibo di bocca l’uno all’altro, sanza poter fare difesa alcuna."],"cs":["Ve všech městech, zemích, hradech a domech bude vidět, jak z touhy po jídle berou jeden druhému vlastní jídlo z úst, aniž by se kdo mohl jakkoli bránit."],"ref":{"s":"C.A","l":362,"st":"r","z":false,"raw":"C. A. 362 r"},"ca":[2016,2018]},{"id":"s589","o":"Profezie","c":"VI","str":369,"ni":"delle fornaci di mattoni e calcina","nc":"O pecích na cihly a vápno","it":["Al fine la terra si farà rossa per lo infocamento di molti giorni, e le pietre si convertiranno in cenere."],"cs":["Nakonec země zrudne žárem mnoha dnů a kameny se promění v popel."],"ref":{"s":"C.A","l":362,"st":"r","z":false,"raw":"C. A. 362 r"},"ca":[2016,2018]},{"id":"s590","o":"Profezie","c":"VII","str":369,"ni":"delle armi da offendere","nc":"O útočných zbraních","it":["L’umane opere fien cagione di lor morte — le spade e lance."],"cs":["Lidská díla budou příčinou jejich smrti – meče a kopí."],"ref":{"s":"I","l":64,"st":"v","z":false,"raw":"I. 64 v"},"ca":[]},{"id":"s591","o":"Profezie","c":"VIII","str":369,"ni":"il ferro uscito di sotto terra e morto, e se ne fa l’arme che ha morti tanti uomini","nc":"O železe a zbraních","it":["I morti usciranno di sotto terra, e coi loro fieri movimenti cacceranno dal mondo innumerabili creature umane."],"cs":["Mrtví vyjdou zpod země a svými divokými pohyby vyženou ze světa nesčetná lidská stvoření."],"ref":{"s":"R","l":1297,"st":"","z":false,"raw":"R. 1297"},"ca":[],"rr":"Br. M. 42 b"},{"id":"s592","o":"Profezie","c":"IX","str":370,"ni":"delle spade e lance che per sè mai nuocono a nessuno","nc":"O mečích a kopích, které samy od sebe nikdy nikomu neublíží","it":["Chi per se è mansueto, e sanza alcuna offensione, si farà spaventevole e feroce mediante la trista compagnia, e torrà la vita crudelissimamente a molte genti; e più n’ucciderebbe, se corpi sanz’anima, e usciti dalle spelonche, non li difendessino — cioè le corazze di ferro."],"cs":["Kdo je sám o sobě krotký a nikomu neubližuje, stane se díky zlé společnosti strašným a divokým a nejkrutěji vezme život mnoha lidem; a ještě víc by jich zabil, kdyby je nechránila těla bez duše, vyšlá ze slují – totiž železná brnění."],"ref":{"s":"C.A","l":362,"st":"r","z":false,"raw":"C. A. 362 r"},"ca":[2016,2018]},{"id":"s593","o":"Profezie","c":"X","str":370,"ni":"delle stelle delli sproni","nc":"O hvězdicích ostruh","it":["Per causa delle stelle si vedranno li omini esser velocissimi, al pari di qualunque animale veloce."],"cs":["Díky hvězdám bude vidět lidi nesmírně rychlé, rovné kterémukoli rychlému zvířeti."],"ref":null,"ca":[]},{"id":"s594","o":"Profezie","c":"XI","str":370,"ni":"del fuoco delle bombarde","nc":"O ohni bombard","it":["Oh! quanti grandi edilizi fieno ruinati, per causa del fuoco!"],"cs":["Ó, kolik velkých staveb bude zbořeno kvůli ohni!"],"ref":{"s":"R","l":1297,"st":"","z":false,"raw":"R. 1297"},"ca":[],"rr":"Br. M. 42 b"},{"id":"s595","o":"Profezie","c":"XII","str":370,"ni":"delle bombarde ch’escan della fossa e della forma","nc":"O bombardách, které vycházejí z licí jámy a z formy","it":["Uscirà di sotto terra chi, con ispaventevoli grida, stordirà i circostanti vicini, e col suo fiato farà morire li omini, e ruinare le città e castella."],"cs":["Zpod země vyjde ten, kdo strašlivým řevem ohluší všechny v okolí, svým dechem bude zabíjet lidi a bořit města i hrady."],"ref":null,"ca":[]},{"id":"s596","o":"Profezie","c":"XIII","str":371,"ni":"la pietra del fucile, che fa foco che consuma tutte le some delle leone, con che si disfan le selve; e cuocerassi con esse la carne delle bestie","nc":"Křesací kámen","it":["I gran sassi de’ monti getteran fuoco tale che bruceranno il legname di molte e grandissime selve, e molte fiere selvatiche e domestiche."],"cs":["Velké kameny hor budou metat takový oheň, že spálí dřevo mnoha převelikých lesů a mnoho divokých i domácích zvířat."],"ref":{"s":"R","l":1297,"st":"","z":false,"raw":"R. 1297"},"ca":[],"rr":"Br. M. 42 b"},{"id":"s597","o":"Profezie","c":"XIV","str":371,"ni":"dell’esca","nc":"O troudu","it":["Con pietra e con ferro si renderanno visibili le cose, che prima non si vedeano."],"cs":["Kamenem a železem se zviditelní věci, které předtím nebylo vidět."],"ref":{"s":"C.A","l":362,"st":"r","z":false,"raw":"C. A. 362 r"},"ca":[2016,2018]},{"id":"s598","o":"Profezie","c":"XV","str":371,"ni":"de’ metalli","nc":"O kovech","it":["Uscirà dalle oscure e tenebrose spelonche chi metterà tutta l’umana specie in grandi affanni, pericoli e morte.","A molti seguaci lor, dopo molti affanni, darà diletto; ma chi non fia suo partigiano, morrà con stento e calamità.","Questo commetterà infiniti tradimenti; questo aumenterà e persuaderà li omini tutti alli assassinamenti e latrocini e le perfidie; questo darà sospetto ai sua partigiani; questo torrà lo stato alle città libere; questo torrà la vita a molti; questo travaglierà li omini infra loro con molte arti, inganni e tradimenti.","O animal mostruoso! quanto sarebbe meglio agli omini che tu ti tornassi nell’inferno: per costui rimarran diserte le gran selve delle lor piante; per costui infiniti animali perderanno la vita."],"cs":["Z temných a tmavých slují vyjde ten, kdo uvrhne celé lidské pokolení do velkých útrap, nebezpečí a smrti.","Mnohým svým stoupencům po mnoha útrapách dá potěšení; ale kdo nebude jeho přívržencem, zemře v strádání a neštěstí.","Ten spáchá nesčetné zrady; ten rozmnoží a navede všechny lidi k vraždám, loupežím a věrolomnostem; ten vzbudí podezíravost ve svých přívržencích; ten vezme svobodným městům jejich svobodu; ten vezme život mnohým; ten bude štvát lidi proti sobě mnoha úskoky, podvody a zradami.","Ó obludný tvore! O kolik by bylo pro lidi lepší, kdyby ses vrátil do pekla: kvůli němu zůstanou velké lesy zbaveny svých stromů; kvůli němu nesčetná zvířata přijdou o život."],"ref":{"s":"C.A","l":362,"st":"r","z":false,"raw":"C. A. 362 r"},"ca":[2016,2018]},{"id":"s599","o":"Profezie","c":"XVI","str":372,"ni":"de’ danari e oro","nc":"O penězích a zlatě","it":["Uscirà dalle cavernose spelonche chi farà, con sudore, affaticare tutti i popoli del mondo, con grandi affanni, ansietà, sudori, per essere aiutato da lui."],"cs":["Z jeskynních slují vyjde ten, kdo přiměje všechny národy světa lopotit se v potu tváře, s velkými útrapami, úzkostí a potem, jen aby se jim od něho dostalo pomoci."],"ref":{"s":"C.A","l":36,"st":"r","z":false,"raw":"C. A. 36 r"},"ca":[198,200]},{"id":"s600","o":"Profezie","c":"I","str":372,"ni":"de’ morti che si vanno a sotterrare","nc":"O mrtvých, které nesou pohřbít","it":["I semplici popoli porteran gran quantità di lumi per far lume ne’ viaggi a tutti quelli, che integralmente hanno perso la virtù visiva."],"cs":["Prostí lidé ponesou velké množství světel, aby svítili na cestu všem těm, kdo docela ztratili zrak."],"ref":null,"ca":[]},{"id":"s601","o":"Profezie","c":"II","str":372,"ni":"de li uffizi, funerali e processioni e lumi e campane e compagnia","nc":"O zádušních mších a pohřbech","it":["Agli omini saran fatti grandissimi onori e pompe, sanza lor saputa."],"cs":["Lidem budou prokazovány převeliké pocty a okázalosti, aniž o tom budou vědět."],"ref":{"s":"C.A","l":143,"st":"v","z":false,"raw":"C. A. 143 v"},"ca":[779]},{"id":"s602","o":"Profezie","c":"III","str":373,"ni":"del dì de’ morti","nc":"O Dušičkách","it":["E quanti fien quelli che piangeranno i lor antenati morti, portando lumi a quelli."],"cs":["A kolik bude těch, kdo budou oplakávat své mrtvé předky a nosit jim světla."],"ref":{"s":"C.A","l":362,"st":"v","z":false,"raw":"G. A. 362 v"},"ca":[2019,2020]},{"id":"s603","o":"Profezie","c":"IV","str":373,"ni":"del pianto fatto il venerdì santo","nc":"O pláči na Velký pátek","it":["In tutte le parti d’Europa sarà pianto da gran popoli per la morte d’un solo omo, morto in Oriente."],"cs":["Ve všech částech Evropy budou velké národy plakat pro smrt jediného člověka, který zemřel na Východě."],"ref":{"s":"C.A","l":362,"st":"r","z":false,"raw":"C. A. 362 r"},"ca":[2016,2018]},{"id":"s604","o":"Profezie","c":"V","str":373,"ni":"de’ cristiani","nc":"O křesťanech","it":["Molti, che tengon la fede del figliolo, sol fan templi nel nome della madre."],"cs":["Mnozí, kteří vyznávají víru v Syna, stavějí chrámy jen ve jménu Matky."],"ref":{"s":"C.A","l":145,"st":"r","z":false,"raw":"C. A. 145 r"},"ca":[784,786]},{"id":"s605","o":"Profezie","c":"VI","str":373,"ni":"del turibolo dell’incenso","nc":"O kadidelnici","it":["Quelli che, con vestimenti bianchi, andranno con arroganti movimenti minacciando con metallo e fuoco, chi non faceva lor detrimento alcuno."],"cs":["Ti, kdo v bílých šatech budou chodit s domýšlivými pohyby a hrozit kovem a ohněm tomu, kdo jim nijak neublížil."],"ref":{"s":"R","l":1310,"st":"","z":false,"raw":"R. 1310"},"ca":[],"rr":"Br. M. 212"},{"id":"s606","o":"Profezie","c":"VII","str":373,"ni":"de’ preti che dicono messa","nc":"O kněžích, kteří slouží mši","it":["Molti fien quelli che, per esercitare la lor arte, si vestiran ricchissimamente: e questo parrà esser fatto secondo l’uso de’ grembiali."],"cs":["Mnoho bude těch, kteří se, aby vykonávali své řemeslo, oblečou převelice nádherně: a bude se zdát, že je to po způsobu zástěr."],"ref":{"s":"C.A","l":362,"st":"v","z":false,"raw":"C. A. 362 v"},"ca":[2019,2020]},{"id":"s607","o":"Profezie","c":"VIII","str":373,"ni":"de’ preti che tengono l’ostia in corpo","nc":"O kněžích, kteří mají hostii v těle","it":["Allora tutti quasi i tabernacoli, dove sta il corpus domini, si vedranno manifestamente per se stessi andare per diverse strade del mondo."],"cs":["Tehdy bude vidět, jak téměř všechny svatostánky, v nichž je Tělo Páně, zjevně samy od sebe chodí po různých cestách světa."],"ref":{"s":"I","l":65,"st":"v","z":false,"raw":"I. 65 v"},"ca":[]},{"id":"s608","o":"Profezie","c":"IX","str":374,"ni":"de’ frati confessori","nc":"O mniších zpovědnících","it":["Le sventurate donne, di propria volontà, andranno a palesare agli uomini tutte le loro lussurie e opere vergognose e segretissime."],"cs":["Nešťastné ženy půjdou z vlastní vůle vyjevovat mužům všechny své chlípnosti a hanebné a nejtajnější skutky."],"ref":{"s":"C.A","l":362,"st":"v","z":false,"raw":"C. A. 362 v"},"ca":[2019,2020]},{"id":"s609","o":"Profezie","c":"X","str":374,"ni":"delle pitture de’ santi adorate","nc":"O uctívaných obrazech svatých","it":["Parleranno li omini alli omini, che non sentiranno; avran gli occhi aperti, e non vedranno; parleranno a quelli, e non fia loro risposta; chiederan grazia a chi avrà orecchi, e non ode; faran lume a chi è orbo."],"cs":["Lidé budou mluvit k lidem, kteří neuslyší; budou mít oči otevřené, a nebudou vidět; budou k nim mluvit, a nedostanou odpověď; budou prosit o milost toho, kdo bude mít uši, a neslyší; budou svítit tomu, kdo je slepý."],"ref":{"s":"C.A","l":362,"st":"r","z":false,"raw":"C. A. 362 r"},"ca":[2016,2018]},{"id":"s610","o":"Profezie","c":"XI","str":374,"ni":"delle scolture","nc":"O sochách (krucifixech)","it":["Ohimè! che vedo il Salvatore di novo crocifisso."],"cs":["Běda! Vidím Spasitele znovu ukřižovaného."],"ref":{"s":"I","l":65,"st":"v","z":false,"raw":"I. 65 v"},"ca":[]},{"id":"s611","o":"Profezie","c":"XII","str":374,"ni":"de’ crocefissi venduti","nc":"O prodávaných krucifixech","it":["Io vedo di nuovo venduto e crocifisso Cristo, e martirizzare i sua santi."],"cs":["Vidím znovu prodaného a ukřižovaného Krista a mučené jeho svaté."],"ref":{"s":"I","l":66,"st":"v","z":false,"raw":"I. 66 v"},"ca":[]},{"id":"s612","o":"Profezie","c":"XIII","str":374,"ni":"della religione de’ frati che vivono per li loro santi, morti per assai tempo!","nc":"O řeholi mnichů, kteří žijí ze svých svatých, dávno mrtvých","it":["Quelli che saranno morti, dopo mille anni, fien quelli che daranno le spese a molti vivi."],"cs":["Ti, kdo budou mrtví už tisíc let, budou ti, kdo budou živit mnoho živých."],"ref":{"s":"I","l":66,"st":"v","z":false,"raw":"I. 66 v"},"ca":[]},{"id":"s613","o":"Profezie","c":"XIV","str":375,"ni":"del vendere il paradiso","nc":"O prodávání ráje","it":["Infinita moltitudine venderanno pubblicamente e pacificamente cose di grandissimo prezzo, sanza licenza del padrone di quelle, e che mai non furon loro, nè in lor potestà, e a questo non provvederà la giustizia umana."],"cs":["Nesčetné množství lidí bude veřejně a pokojně prodávat věci nejvyšší ceny bez svolení jejich pána, věci, které nikdy nebyly jejich ani v jejich moci, a lidská spravedlnost proti tomu nic nepodnikne."],"ref":{"s":"C.A","l":362,"st":"v","z":false,"raw":"C. A. 362 v"},"ca":[2019,2020]},{"id":"s614","o":"Profezie","c":"XV","str":375,"ni":"de’ frati che spendendo parole ricevono di gran ricchezze, e danno il paradiso","nc":"O mniších, kteří rozdávají ráj","it":["Le invisibili monete faran trionfare molti spenditori di quelle."],"cs":["Neviditelné mince přinesou triumf mnohým, kdo je utrácejí."],"ref":{"s":"C.A","l":362,"st":"v","z":false,"raw":"C. A. 362 v"},"ca":[2019,2020]},{"id":"s615","o":"Profezie","c":"XVI","str":375,"ni":"delle chiese e abitazion de’ frati","nc":"O kostelech a obydlích mnichů","it":["Assai saranno, che lascieranno li esercizi e le fatiche e povertà di vita e di roba, e andranno abitare nelle ricchezze e trionfanti edilizi, mostrando questo esser il mezzo di farsi amico a Dio."],"cs":["Mnoho bude těch, kteří opustí práci, námahu a chudobu života i majetku a půjdou bydlet do bohatství a skvostných staveb, ukazujíce, že toto je cesta, jak se stát přítelem Božím."],"ref":{"s":"C.A","l":362,"st":"v","z":true,"raw":"C. A. 362 v"},"ca":[2019,2020]},{"id":"s616","o":"Profezie","c":"I","str":376,"ni":"dello sgomberare l’ognissanti","nc":"O stěhování o Všech svatých","it":["Molti abbandoneranno le proprie abitazioni, e porteran seco i sua valsenti, e andranno abitare in altri paesi."],"cs":["Mnozí opustí vlastní příbytky, vezmou s sebou svůj majetek a půjdou bydlet do jiných krajů."],"ref":{"s":"C.A","l":362,"st":"v","z":false,"raw":"C. A. 362 v"},"ca":[2019,2020]},{"id":"s617","o":"Profezie","c":"II","str":376,"ni":"delli omini che dorman nell’asse d’albero","nc":"O lidech, kteří spí na prknech ze stromů","it":["Li omini dormiranno, e mangeranno, e abiteranno infra li alberi, nati nelle selve e campagne."],"cs":["Lidé budou spát, jíst a bydlet mezi stromy zrozenými v lesích a na polích."],"ref":{"s":"C.A","l":145,"st":"r","z":false,"raw":"C. A. 145 r"},"ca":[784,786]},{"id":"s618","o":"Profezie","c":"III","str":376,"ni":"del battere il letto per rifarlo","nc":"O vyklepávání postele při stlaní","it":["Verranno li omini a tanta ingratitudine che, chi darà loro albergo, sanza alcun prezzo, sarà carico di bastonate, in modo che gran parte delle interiora si spigneranno dal loco loro, e s’andranno rivoltanto pel suo corpo."],"cs":["Lidé dospějí k takovému nevděku, že ten, kdo jim poskytne nocleh bez jakékoli platby, bude zasypán ranami holí, takže velká část vnitřností se mu vytlačí z místa a bude se převalovat po jeho těle."],"ref":{"s":"C.A","l":362,"st":"r","z":false,"raw":"C. A. 362 r"},"ca":[2016,2018]},{"id":"s619","o":"Profezie","c":"IV","str":376,"ni":"i medici che vivono de' malati","nc":"Lékaři, kteří žijí z nemocných","it":["Verranno li omini in tanta viltà, che avran di grazia che altri trionfino sopra i loro mali, ovvero della perduta lor vera ricchezza — cioè la sanità."],"cs":["Lidé upadnou do takové ubohosti, že budou vděčni, když budou jiní triumfovat nad jejich neduhy, čili nad ztrátou jejich pravého bohatství – totiž zdraví."],"ref":{"s":"I","l":66,"st":"v","z":false,"raw":"I. 66. v"},"ca":[]},{"id":"s620","o":"Profezie","c":"V","str":377,"ni":"del comune","nc":"O obci","it":["Un meschino sarà soiato e essi soiatori sempre fien sua ingannatori e rubatori, e assassini d’esso meschino."],"cs":["Ubožákovi se bude lichotit a ti lichotníci budou vždy jeho podvodníky, zloději a vrahy toho ubožáka."],"ref":{"s":"C.A","l":36,"st":"r","z":false,"raw":"C. A. 36 r"},"ca":[198,200]},{"id":"s621","o":"Profezie","c":"VI","str":377,"ni":"profezia","nc":"Proroctví (o sněhu v létě)","it":["Porterassi neve distante ne’ lochi caldi, tolta dall’alte cime de’ monti, e si lascierà cadere nelle feste, alle piazze, nel tempo dell’estate."],"cs":["Sníh, vzatý z vysokých vrcholků hor, se bude vozit daleko do teplých míst a bude se nechávat padat při slavnostech na náměstích v letním čase."],"ref":{"s":"G","l":14,"st":"v","z":false,"raw":"G. 14 v"},"ca":[]},{"id":"s622","o":"Profezie","c":"I","str":377,"ni":"della fossa","nc":"O jámě","it":["Staran molti occupati in esercizio a levare di quella cosa, che tanto crescerà, quanto se ne levò."],"cs":["Mnozí budou zaměstnáni prací, při níž budou odebírat z věci, která poroste o tolik, o kolik se z ní odebere."],"ref":{"s":"C.A","l":362,"st":"r","z":false,"raw":"C. A. 362 r"},"ca":[2016,2018]},{"id":"s623","o":"Profezie","c":"II","str":377,"ni":"del peso posto sul piumaccio","nc":"O závaží položeném na polštáři","it":["E a molti corpi nel vedere da lor levar la testa, si vedrà manifestamente crescere, e, rendendo loro la levata testa, immediatamente diminuiscono la grandezza."],"cs":["A u mnoha těl bude zjevně vidět, že když se jim vezme hlava, rostou, a když se jim vzatá hlava vrátí, hned zmenšují svou velikost."],"ref":null,"ca":[]},{"id":"s624","o":"Profezie","c":"III","str":378,"ni":"del pigliare de’ pidocchi","nc":"O chytání vší","it":["E’ saran molti cacciatori d’animali che, quanto più ne piglieranno, manco n’avranno, e così, di converso, più n’avrà quanto men ne piglieranno."],"cs":["Bude mnoho lovců zvířat, kteří čím víc jich nachytají, tím méně jich budou mít, a naopak tím víc jich bude mít ten, kdo jich nachytá méně."],"ref":{"s":"C.A","l":362,"st":"r","z":false,"raw":"C. A. 362 r"},"ca":[2016,2018]},{"id":"s625","o":"Profezie","c":"IV","str":378,"ni":"dell’attignere l'acqua con due secchie a una sola corda","nc":"O nabírání vody dvěma vědry na jediném provaze","it":["E rimarranno occupati molti che, quanto più tireranno in giù la cosa, essa più se ne fuggirà in contrario moto."],"cs":["A mnozí budou zaměstnáni tím, že čím víc budou věc táhnout dolů, tím víc jim bude unikat opačným pohybem."],"ref":{"s":"C.A","l":362,"st":"r","z":false,"raw":"C. A. 362 r"},"ca":[2016,2018]},{"id":"s626","o":"Profezie","c":"I","str":378,"ni":"dell’avaro","nc":"O lakomci","it":["Molti fieno quelli che, con ogni studio e sollecitudine, seguiranno con furia quella cosa, che sempre li ha spaventati, non conoscendo la sua malignità."],"cs":["Mnoho bude těch, kteří se vší pílí a horlivostí budou zuřivě pronásledovat tu věc, která je vždy děsila, neznajíce její zlovolnost."],"ref":{"s":"C.A","l":362,"st":"r","z":false,"raw":"C. A. 362 r"},"ca":[2016,2018]},{"id":"s627","o":"Profezie","c":"II","str":379,"ni":"delli uomini che quanto più invecchiano più si fanno avari, che avendosi a star poco dovrebbero farsi liberali","nc":"O lakotných starcích","it":["Vedransi quelli, che son giudicati di più sperienza e giudizio, quanto egli hanno men bisogno delle cose, con più avidità cercarle e ricercarle."],"cs":["Bude vidět ty, kdo jsou pokládáni za nejzkušenější a nejsoudnější, jak čím méně věcí potřebují, tím chtivěji je hledají a shánějí."],"ref":{"s":"C.A","l":362,"st":"r","z":false,"raw":"C. A. 362 r"},"ca":[2016,2018]},{"id":"s628","o":"Profezie","c":"III","str":379,"ni":"del desiderio di ricchezza","nc":"O touze po bohatství","it":["Li omini perseguiranno quella cosa, della qual più temono, cioè saran miseri, per non venire in miseria."],"cs":["Lidé budou pronásledovat tu věc, které se nejvíc bojí, totiž budou živořit v bídě, aby do bídy nepřišli."],"ref":{"s":"I","l":64,"st":"v","z":false,"raw":"I. 64 v"},"ca":[]},{"id":"s629","o":"Profezie","c":"IV","str":379,"ni":"delle cose che si mangiano, che prima s’uccidono","nc":"O věcech, které jíme a které se předtím zabíjejí","it":["Sarà morto da loro il loro nutritore, e flagellato con spietata morte."],"cs":["Jejich živitel bude jimi zabit a ubičován nemilosrdnou smrtí."],"ref":{"s":"C.A","l":362,"st":"r","z":false,"raw":"C. A. 362 r"},"ca":[2016,2018]},{"id":"s630","o":"Profezie","c":"V","str":379,"ni":"della bocca dell’omo ch’è sepoltura","nc":"O lidských ústech, která jsou hrobem","it":["Usciranno gran romori dalle sepolture di quelli, che son finiti da cattiva e violenta morte."],"cs":["Z hrobů těch, kdo skončili zlou a násilnou smrtí, se budou ozývat velké hluky."],"ref":{"s":"I","l":65,"st":"v","z":false,"raw":"I. 65 v"},"ca":[]},{"id":"s631","o":"Profezie","c":"VI","str":379,"ni":"del cibo stato animato","nc":"O jídle, které bylo živé","it":["Gran parte de’ corpi animati passerà pe’ corpi de gli altri animali, cioè le case disabitate passeran in pezzi per le case abitate, dando a quelle un utile, e portando con seco i sua danni: quest’è, cioè, la vita dell’omo si fa delle cose mangiate, le quali portan con sè la parte dell’omo, ch’è morta."],"cs":["Velká část oduševnělých těl přejde těly jiných živočichů, totiž neobydlené domy přejdou po kusech obydlenými domy, přinášejíce jim užitek a odnášejíce s sebou jejich škody: to jest, život člověka se tvoří ze snědených věcí, které s sebou odnášejí tu část člověka, jež je mrtvá."],"ref":{"s":"C.A","l":145,"st":"r","z":false,"raw":"C. A. 145 r"},"ca":[784,786]},{"id":"s632","o":"Profezie","c":"VII","str":380,"ni":"della vita delli omini che ogni anno si mutano carne","nc":"O životě lidí, kteří si každý rok mění maso","it":["Li omini passeran morti per le sue proprie budelle."],"cs":["Lidé budou mrtví procházet svými vlastními střevy."],"ref":{"s":"R","l":1311,"st":"","z":false,"raw":"R. 1311"},"ca":[],"rr":"S. K. M. II.2 35"},{"id":"s633","o":"Profezie","c":"VIII","str":380,"ni":"della crudeltà dell’omo","nc":"O krutosti člověka","it":["Vedrannosi animali sopra della terra, i quali sempre combatteranno infra loro e con danni grandissimi e, spesso, morte di ciascuna delle parti.","Questi non avran termine nelle lor malignità; per le fiere membra di questi verranno a terra gran parte delli alberi delle gran selve dell’universo; e poich’essi avranno pasciuto, il nutrimento de’ loro desideri sarà di dar morte e affanno e fatiche e guerre e furie a qualunque cosa animata. E per la loro smisurata superbia questi si vorranno levare inverso il cielo, ma la superchia gravezza delle lor membra gli porrà in basso. Nulla cosa resterà sopra la terra, o sotto la terra e l’acqua, che non sia perseguitata, remossa o guasta; e quella delpun paese remossa nell’altro; e ’l corpo di questi si farà sepoltura e transito di tutti i già da lor morti corpi animati.","O mondo! come è che non t’apri a precipitarlo nell’alte fessure de’ tua gran baratri e spelonche, e non mostrare più al cielo sì crudele e spietato mostro?"],"cs":["Bude vidět na zemi zvířata, která spolu budou neustále bojovat s převelikými škodami a často se smrtí každé ze stran.","Ti nebudou znát mezí ve své zlovolnosti; jejich divokými údy padne k zemi velká část stromů velkých lesů celého světa; a až se nasytí, potravou jejich tužeb bude působit smrt, trápení, námahy, války a zuřivost všemu živému. A pro svou nezměrnou pýchu se budou chtít vznést k nebi, ale přílišná tíže jejich údů je udrží dole. Nic nezůstane na zemi ani pod zemí a pod vodou, co by nebylo pronásledováno, vyrváno nebo zničeno; a co je v jedné zemi, bude přeneseno do druhé; a jejich tělo se stane hrobem a průchodem všech oduševnělých těl, která oni zabili.","Ó světe! Jak to, že se neotevřeš a nesvrhneš ho do hlubokých rozsedlin svých velikých propastí a slují a neukazuješ už nebi tak krutou a nemilosrdnou obludu?"],"ref":{"s":"C.A","l":362,"st":"v","z":false,"raw":"C. A. 362 v"},"ca":[2019,2020]},{"id":"s634","o":"Profezie","c":"IX","str":381,"ni":"della lettura de’ buoni libri","nc":"O čtení dobrých knih","it":["Felici fien quelli che presteranno orecchi alle parole de’ morti: — leggere le bone opere, e osservarle."],"cs":["Šťastni budou ti, kdo popřejí sluchu slovům mrtvých: – číst dobrá díla a řídit se jimi."],"ref":{"s":"I","l":64,"st":"r","z":false,"raw":"I. 64 r"},"ca":[]},{"id":"s635","o":"Profezie","c":"X","str":381,"ni":"de’ libri che insegnano precetti","nc":"O knihách, které učí naučením","it":["I corpi sanz’anima ci daranno, con lor sentenzie, precetti utili al ben morire."],"cs":["Těla bez duše nám svými výroky dají užitečná naučení, jak dobře zemřít."],"ref":{"s":"C.A","l":362,"st":"r","z":false,"raw":"C. A 362 r"},"ca":[2016,2018]},{"id":"s636","o":"Profezie","c":"XI","str":381,"ni":"della fama","nc":"O slávě","it":["Le penne leveranno li omini, siccome gli uccelli, inverso il cielo: — cioè per le lettere, fatte da esse penne."],"cs":["Pera pozvednou lidi jako ptáky k nebi: – totiž skrze písmo psané těmi pery."],"ref":{"s":"I","l":64,"st":"v","z":false,"raw":"I. 64 v"},"ca":[]},{"id":"s637","o":"Profezie","c":"XII","str":381,"ni":"delle pelli delli animali che tengono il senso del tatto, che v’è su le scritture","nc":"O pergamenu","it":["Quanto più si parlerà colle pelli, vesti del sentimento, tanto più s’acquisterà sapienza."],"cs":["Čím víc se bude rozmlouvat s kůžemi, oděvy citu, tím víc se nabude moudrosti."],"ref":{"s":"I","l":64,"st":"v","z":false,"raw":"I. 64 v"},"ca":[]},{"id":"s638","o":"Profezie","c":"XIII","str":382,"ni":"della storia","nc":"O dějinách","it":["Le cose disunite svaniranno, e riceveranno in sè tal virtù, cbe renderanno la persa memoria alli omini: — cioè i papiri che son fatti di peli disuniti, e tengono memoria delle cose e fatti delli omini."],"cs":["Věci rozdělené zmizí a přijmou do sebe takovou sílu, že vrátí lidem ztracenou paměť: – totiž papíry, které jsou udělány z rozdělených chlupů a uchovávají paměť věcí a lidských činů."],"ref":{"s":"I","l":65,"st":"v","z":false,"raw":"I. 65 v"},"ca":[]},{"id":"s639","o":"Profezie","c":"XIV","str":382,"ni":"in ogni punto della terra si può fare divisione de’ due emisperi","nc":"V každém bodě země lze vést rozhraní dvou polokoulí","it":["Li omini tutti scambieranno emisperio immediate."],"cs":["Všichni lidé okamžitě vymění polokouli."],"ref":{"s":"C.A","l":362,"st":"r","z":false,"raw":"C. A. 362 r"},"ca":[2016,2018]},{"id":"s640","o":"Profezie","c":"XV","str":382,"ni":"in ogni punto è divisione da oriente a occidente","nc":"V každém bodě je rozhraní mezi východem a západem","it":["Moverannosi tutti li animali da oriente a occidente, e così da aquilone a meriggio scambievolmente, e così di converso."],"cs":["Všichni živočichové se budou pohybovat od východu k západu, a stejně tak navzájem od severu k jihu, a také naopak."],"ref":{"s":"C.A","l":362,"st":"r","z":false,"raw":"C. A. 362 r"},"ca":[2016,2018]},{"id":"s641","o":"Profezie","c":"XVI","str":382,"ni":"degli emisperi, che sono infiniti e da infinite linee son divisi, in modo che sempre ciascuno omo n’ha una d’esse linee infra l’un de’ piedi e l’altro","nc":"O nekonečně mnoha polokoulích","it":["Parleransi, e toccheransi, e abbracceransi li omini, stanti dall’uno all’altro emisperio, intenderansi i loro linguaggi."],"cs":["Lidé budou spolu mluvit, dotýkat se a objímat, ačkoli budou stát jeden na jedné a druhý na druhé polokouli, a budou rozumět svým řečem."],"ref":{"s":"R","l":1297,"st":"","z":true,"raw":"R. 1297"},"ca":[],"rr":"Br. M. 42 b"},{"id":"s642","o":"Profezie","c":"XVII","str":383,"ni":"delle nuvole","nc":"O mracích","it":["Gran parte del mare si fuggirà inverso il cielo e per molto tempo non farà ritorno: — cioè pe’ nuvoli."],"cs":["Velká část moře uteče k nebi a dlouho se nevrátí: – totiž v podobě mračen."],"ref":{"s":"R","l":1297,"st":"","z":false,"raw":"R. 1297"},"ca":[],"rr":"Br. M. 42 b"},{"id":"s643","o":"Profezie","c":"XVIII","str":383,"ni":"la neve che fiocca, che è acqua","nc":"Padající sníh, který je vodou","it":["L’acqua caduta dai nuvoli, ancora in moto sopra le spiagge de’ monti, si fermerà per lungo spazio di tempo sanza fare alcun moto, e questo accaderà in molte e diverse provincie."],"cs":["Voda spadlá z mračen, ještě v pohybu na svazích hor, se na dlouhou dobu zastaví bez jakéhokoli pohybu, a to se stane v mnoha a rozličných krajích."],"ref":{"s":"R","l":1297,"st":"","z":false,"raw":"R. 1297"},"ca":[],"rr":"Br. M. 42 b"},{"id":"s644","o":"Profezie","c":"XIX","str":383,"ni":"la palla della neve rotolando sopra la neve","nc":"Sněhová koule kutálená po sněhu","it":["Molti fien quelli, che cresceran nelle lor ruine."],"cs":["Mnoho bude těch, kteří porostou tím, jak se řítí do zkázy."],"ref":{"s":"R","l":1297,"st":"","z":false,"raw":"R. 1297"},"ca":[],"rr":"Br. M. 42 b"},{"id":"s645","o":"Profezie","c":"XX","str":383,"ni":"delle pioggie, che fanno che i fiumi intorbidati portan via le terre","nc":"O deštích, kvůli nimž kalné řeky odnášejí zemi","it":["Verrà diverso il cielo chi trasmuterà gran parte dell’Africa, che si mostra a esso cielo inverso l’Europa, e quelle di Europa inverso l’Africa; e quelle delle provincie Scitiche si mescoleranno insieme con gran rivoluzione."],"cs":["Od nebe přijde ten, kdo přenese velkou část Afriky, která leží pod tím nebem, do Evropy a země Evropy do Afriky; a země skythských krajů se spolu smísí ve velkém převratu."],"ref":{"s":"C.A","l":362,"st":"r","z":false,"raw":"C. A. 362 r"},"ca":[2016,2018]},{"id":"s646","o":"Profezie","c":"XXI","str":384,"ni":"questo sono li fiumi, che poetano le terre da loro levate dalle montagne, e le scaricano ai marini liti; e dove entra la terra si fugge il mare","nc":"O řekách nesoucích zemi do moře","it":["Le grandissime montagne, ancorachè sieno remote da’ marini liti, scacceranno il mare dal suo sito."],"cs":["Převeliké hory, ačkoli jsou vzdáleny od mořských břehů, vyženou moře z jeho místa."],"ref":{"s":"R","l":1297,"st":"","z":true,"raw":"R. 1297"},"ca":[],"rr":"Br. M. 42 b"},{"id":"s647","o":"Profezie","c":"XXII","str":384,"ni":"dell’acqua, che corre torbida e mista con terra, e della polvere e nebbia mista coll’aria, e del foco misto col suo e altri con ciascuno","nc":"O smíšených živlech","it":["Vedrassi tutti li elementi insieme misti con gran rivoluzione, trascorrere ora inverso il centro del mondo, ora inverso il cielo, e quando dalle parti meridionali scorrere con furia inverso il freddo settentrione, qualche volta dall’oriente inverso l’occidente, e così da questo in quell’altro emisperio."],"cs":["Bude vidět všechny živly smíšené dohromady ve velkém převratu, jak se ženou hned ke středu světa, hned k nebi, a hned z jižních končin zuřivě ke studenému severu, někdy od východu k západu, a tak z této polokoule do oné."],"ref":{"s":"R","l":1297,"st":"","z":false,"raw":"R. 1297"},"ca":[],"rr":"Br. M. 42 b"},{"id":"s648","o":"Profezie","c":"XXIII","str":384,"ni":"il vento d’oriente che scorrerà in ponente","nc":"Východní vítr, který se požene na západ","it":["Vedrannosi le parti orientali discorrere nell’occidentali, e le meridionali in settentrione, avviluppandosi per l’universo con grande strepito e tremore o furore."],"cs":["Bude vidět, jak východní končiny přecházejí do západních a jižní na sever, a víří celým světem s velkým hřmotem a chvěním či zuřivostí."],"ref":null,"ca":[]},{"id":"s649","o":"Profezie","c":"XXIV","str":385,"ni":"della notte che non si conosce alcun colore","nc":"O noci, kdy se nerozezná žádná barva","it":["Verrà a tanto che non si conoscerà differenza in fra’ colori, anzi si faran tutti di nera qualità."],"cs":["Dojde k tomu, že se nebude rozeznávat rozdíl mezi barvami, ba všechny zčernají."],"ref":{"s":"C.A","l":362,"st":"r","z":true,"raw":"C. A. 362 r"},"ca":[2016,2018]},{"id":"s650","o":"Profezie","c":"XXV","str":385,"ni":"del foco","nc":"O ohni","it":["Nascerà di piccolo principio chi si farà con prestezza grande; questo non stimerà alcuna creata cosa, anzi colla sua potenza quasi il tutto avrà in potenza di trasformare il suo essere in un altro."],"cs":["Z malého počátku se zrodí ten, kdo rychle zmohutní; ten nebude dbát žádné stvořené věci, ba svou mocí bude schopen proměnit bytí téměř všeho v bytí jiné."],"ref":{"s":"C.A","l":362,"st":"r","z":false,"raw":"C. A. 362 r"},"ca":[2016,2018]},{"id":"s651","o":"Profezie","c":"XXVI","str":385,"ni":"lo specchio cavo accende il foco col quale si scalda il forno, che ha il fondo, che sta sotto il suo cielo","nc":"O dutém zrcadle","it":["I raggi solari accenderanno il foco in terra, col quale s’infocherà ciò ch’è sotto il cielo, e, ripercossi nel suo impedimento, ritorneranno in basso."],"cs":["Sluneční paprsky zapálí na zemi oheň, jímž se rozžhaví to, co je pod nebem, a odraženy od své překážky se vrátí dolů."],"ref":{"s":"R","l":1297,"st":"","z":false,"raw":"R. 1297"},"ca":[],"rr":"Br. M. 42 b"},{"id":"s652","o":"Profezie","c":"XXVII","str":385,"ni":"traccia","nc":"Náčrt","it":["Restaci il moto, che separa il motore dal mobile."],"cs":["Zbývá nám pohyb, který odděluje hybatele od pohybovaného."],"ref":{"s":"R","l":1297,"st":"","z":false,"raw":"R. 1297"},"ca":[],"rr":"Br. M. 42 b"},{"id":"s653","o":"Profezie","c":"XXVIII","str":386,"ni":"dei pianeti","nc":"O planetách (znameních zvěrokruhu)","it":["E molti terrestri e acquatici animali monteranno fra le stelle: — cioè pianeti."],"cs":["A mnoho suchozemských i vodních zvířat vystoupí mezi hvězdy: – totiž planety."],"ref":{"s":"I","l":66,"st":"r","z":false,"raw":"I. 66 r"},"ca":[]},{"id":"s654","o":"Profezie","c":"XXIX","str":386,"ni":"del consiglio","nc":"O radě","it":["E colui che sarà più necessario a chi avrà bisogno di lui, sarà sconosciuto, cioè più sprezzato."],"cs":["A ten, kdo bude nejpotřebnější tomu, kdo ho bude potřebovat, bude nepoznán, totiž nejvíce opovrhován."],"ref":{"s":"C.A","l":36,"st":"r","z":false,"raw":"C. A. 36 r"},"ca":[198,200]},{"id":"s655","o":"Profezie","c":"XXX","str":386,"ni":"della paura della povertà","nc":"O strachu z chudoby","it":["La cosa malvagia e spaventevole darà di sè tanto timore appresso a delli omini che come matti, credendo fuggirla, concorreranno con veloce moto alle sue smisurate forze."],"cs":["Ta zlá a děsivá věc nažene lidem takový strach, že jako šílení, domnívajíce se, že před ní prchají, poběží rychlým pohybem vstříc její nezměrné moci."],"ref":{"s":"C.A","l":36,"st":"r","z":false,"raw":"C. A. 36 r"},"ca":[198,200]},{"id":"s656","o":"Profezie","c":"XXXI","str":386,"ni":"della bugia","nc":"O lži","it":["Tutte le cose, che nel verno fien nascoste sotto la neve, rimarranno scoperte e palesi nell’estate: - detta per la bugìa, che non può stare occulta."],"cs":["Všechny věci, které budou v zimě skryty pod sněhem, zůstanou v létě odkryty a zjevné: – řečeno o lži, která nemůže zůstat skryta."],"ref":{"s":"I","l":39,"st":"v","z":false,"raw":"I. 39 v"},"ca":[]},{"id":"s657","o":"Facezie","c":"I","str":387,"ni":"di un frate ad un mercante","nc":"O mnichovi a kupci","it":["Usano i frati minori, a certi tempi, alcune loro quaresime, nelle quali essi non mangiano carne ne’ lor conventi; ma in viaggio, perchè essi vivono di limosine, hanno licenzia di mangiare ciò che è posto loro innanzi. Onde, abbattendosi, in detti viaggi, una coppia d’essi frati a un’osteria, in compagnia d’un certo mercantuolo, il quale, essendo a una medesima mensa, alla quale non fu portato, per la povertà dell’osteria, altro che un pollastro cotto; onde esso mercantuolo, vedendo questo essere poco per lui, si volse a essi frati, e disse: — se io ho ben di ricordo, voi non mangiate in tali dì ne’ vostri conventi d’alcuna maniera di carne. — Alle quali parole i frati furono costretti, per la lor regola, sanza altre cavillazioni, a dire ciò essere la verità: onde il mercantuolo ebbe il suo desiderio; e così si mangiò essa pollastra; e i frati feciono il meglio poterono.","Ora, dopo tale desinare, questi commensali si partirono tutti e tre di compagnia; e dopo alquanto di viaggio, trovato un fiume di bona larghezza e profondità, essendo tutti e tre a piedi, — i frati per povertà e l’altro per avarizia, — fu necessario, per l’uso della compagnia, che uno de’ frati, essendo discalzi, passasse sopra i sua omeri esso mercantuolo: onde datoli il frate a serbo i zoccoli, si caricò di tale omo.","Onde accadde che, trovandosi esso frate in mezzo del fiume, esso ancora si ricordò de la sua regola; e fermatosi, a uso di San Cristofano, alzò la testa inverso quello che l’aggravava, e disse: — dimmi un poco, hai tu nissun dinari addosso? — Ben ssi, rispose questo, come credete voi che mia pari mercatante andasse altrementi attorno? — Ohime! disse il frate, la nostra regola vieta, che noi non possiamo portare danari addosso; — e sùbito lo gettò nell’acqua. La qual cosa conosciuta dal mercatante, facetamente la già fatta ingiuria essere vendicata, con piacente riso, pacificamente, mezzo arrossito per vergogna la vendetta sopportò."],"cs":["Menší bratři mají ve zvyku v určitých obdobích držet jakési své posty, kdy ve svých klášterech nejedí maso; ale na cestách, protože žijí z almužen, smějí jíst, co je jim předloženo. Stalo se tedy, že na takové cestě se dva z těch mnichů octli v hospodě ve společnosti jakéhosi kupčíka a seděli s ním u jednoho stolu, na který pro chudobu hospody nepřinesli nic jiného než jedno pečené kuře; kupčík, vida, že je to málo i pro něho samého, obrátil se k mnichům a řekl: – Pamatuji-li si dobře, vy v takové dny ve svých klášterech nejíte žádný druh masa. – Na ta slova byli mniši podle své řehole nuceni bez dalších vytáček přiznat, že je to pravda; a tak kupčík dosáhl svého a kuře snědl sám, a mniši se měli, jak nejlépe mohli.","Po takovém obědě se pak ti stolovníci vydali na cestu všichni tři spolu; a když po nějakém kusu cesty narazili na řeku značné šířky a hloubky, a protože šli všichni tři pěšky – mniši z chudoby a ten druhý z lakoty –, bylo podle zvyku dobrého tovaryšstva nutné, aby jeden z mnichů, jelikož byli bosí, přenesl na svých ramenou toho kupčíka: dal mu tedy mnich své dřeváky do opatrování a naložil si toho muže na záda.","Stalo se pak, že když byl mnich uprostřed řeky, vzpomněl si zase na svou řeholi; zastavil se jako svatý Kryštof, zvedl hlavu k tomu, kdo ho tížil, a řekl: – Pověz mi, máš u sebe nějaké peníze? – Ale ovšem, odpověděl ten, jak si myslíte, že by kupec mého druhu chodil po světě jinak? – Běda! řekl mnich, naše řehole zakazuje, abychom u sebe nosili peníze; – a hned ho shodil do vody. Kupec poznal, že tím byla vtipně pomstěna křivda, kterou sám předtím spáchal, a s úsměvem, pokojně a napůl zardělý hanbou, tu pomstu snesl."],"ref":{"s":"C.A","l":147,"st":"v","z":false,"raw":"C. A. 147 v"},"ca":[795,797]},{"id":"s658","o":"Facezie","c":"II","str":389,"ni":"di un pittore ad un prete","nc":"O malíři a knězi","it":["Andando un prete per la sua parrocchia il sabato santo, dando, com’è usanza, l’acqua benedetta per le case, capitò nella stanza d’un pittore, dove spargendo essa acqua sopra alcuna sua pittura, esso pittore, voltosi indirieto, alquanto scrucciato, disse, perchè facesse tale spargimento sopra le sue pitture. Allora il prete disse essere così, usanza, e ch’era suo debito il fare così, o che faceva bene, e chi fa bene debbe aspettare bene e meglio, che così prometter Dio, e che d’ogni bene, che si faceva in terra, se n’avrebbe di sopra per ogni un cento.","Allora il pittore, aspettato ch’elli uscisse fori, se li fece di sopra alla finestra, e gittò un gran secchione d’acqua addosso a esso prete, dicendo: — ecco che di sopra ti viene per ogni un cento, come tu dicesti che accatterebbe del bene, che mi facevi colla tua acqua santa, colla quale m’hai guasto mezzo le mie pitture. —"],"cs":["Když jednou na Bílou sobotu chodil kněz po své farnosti a, jak je zvykem, kropil domy svěcenou vodou, přišel do dílny jednoho malíře, a když tou vodou pokropil některé jeho obrazy, malíř se otočil, poněkud rozmrzelý, a zeptal se, proč ty jeho obrazy tak kropí. Tu kněz řekl, že je to tak zvykem a že je jeho povinností tak činit, že činí dobře, a kdo činí dobro, má očekávat dobro a ještě větší, neboť tak slibuje Bůh, a že za každé dobro, které se učiní na zemi, se shůry dostane stonásobně.","Tu malíř počkal, až kněz vyjde ven, vyklonil se nad ním z okna a vylil na toho kněze velký škopek vody se slovy: – Hle, tady ti shůry přichází stonásobně, jak jsi říkal, že se dostane za dobro, které jsi mi prokázal svou svěcenou vodou, kterou jsi mi zkazil půlku mých obrazů. –"],"ref":{"s":"C.A","l":117,"st":"r","z":false,"raw":"C. A. 117 r"},"ca":[642,644,646]},{"id":"s659","o":"Facezie","c":"III","str":389,"ni":"motto di un artigiano ad un signore","nc":"Výrok řemeslníka k pánovi","it":["Uno artigiano, andando spesso a visitare uno signore, sanza altro proposito dimandare al quale, il signore domandò quello, che andava facendo. Questo disse, che veniva lì per avere de’ piaceri, che lui aver non potea; perocchè volentieri vedeva omini più potenti di lui, come fanno i popolani, ma che ’l signore non potea vedere, se non omini di men possa di lui: per questo i signori mancano d’esso piacere."],"cs":["Jeden řemeslník chodíval často navštěvovat jednoho pána, aniž by o cokoli žádal; pán se ho tedy zeptal, co tu pořád dělá. Ten řekl, že sem chodí, aby si užil potěšení, jaké pán mít nemůže; neboť on rád vidí lidi mocnější, než je sám, jak to dělají prostí lidé, kdežto pán nemůže vidět nic jiného než lidi menší moci, než je on sám: proto páni takové potěšení postrádají."],"ref":{"s":"R","l":1283,"st":"","z":false,"raw":"R. 1283"},"ca":[],"rr":"S. K. M. III. 58 a"},{"id":"s660","o":"Facezie","c":"IV","str":390,"ni":"bella risposta ad un pitagoreo","nc":"Pěkná odpověď pythagorejci","it":["Uno, volendo provare colla autorità di Pitagora, come altre volte lui era stato al mondo, e uno non li lasciava finire il suo ragionamento; allor costui disse a questo tale: — e per tale segnale, che io altre volte ci fussi stato, io mi ricordo che tu eri mulinaro. — Allora costui, sentendosi mordere colle parole, gli confermò essere vero, che per questo contrassegno lui si ricordava che questo tale era stato l’asino, che gli portava la farina."],"cs":["Jeden chtěl autoritou Pythagorovou dokázat, že už byl jindy na světě, a jiný mu nedával domluvit; tu ten první řekl tomu druhému: – A na důkaz, že jsem tu už jednou byl, si pamatuji, že ty jsi byl mlynář. – Tu ten druhý, cítě se slovy uštknut, mu potvrdil, že je to pravda, neboť podle téhož znamení si vzpomíná, že on byl tím oslem, který mu nosil mouku."],"ref":{"s":"M","l":58,"st":"v","z":false,"raw":"M. 58 v"},"ca":[]},{"id":"s661","o":"Facezie","c":"V","str":390,"ni":"risposta di un pittore","nc":"Odpověď malíře","it":["Fu dimandato un pittore perchè, facendo lui di figure sì belle che eran cose morte, per che causa esso avesse fatti i figlioli sì brutti. Allora il pittore rispose, che le pitture le fece di dì e i figlioli di notte."],"cs":["Jednoho malíře se zeptali, proč, když dělá tak krásné postavy, které jsou přece věcmi mrtvými, udělal tak ošklivé děti. Tu malíř odpověděl, že obrazy dělal ve dne a děti v noci."],"ref":{"s":"M","l":58,"st":"v","z":false,"raw":"M. 58 v"},"ca":[]},{"id":"s662","o":"Facezie","c":"VI","str":391,"ni":"un amico ad un maldicente","nc":"Přítel pomlouvači","it":["Uno lasciò lo usare con uno suo amico, perchè quello spesso li diceva male delli amici sua. Il quale, lasciato l’amico, un dì, dolendosi collo amico, e dopo il molto dolersi, lo pregò che li dicesse quale fusse la cagione, che lo avesse fatto dimenticare tanta amicizia. Al quale esso rispose: — io non voglio più usare con teco per ch’io ti voglio bene, e non voglio che, dicendo tu male ad altri di me tuo amico, che altri abbiano come me a fare trista impressione di te, dicendo tu a quelli male di me tuo amico; onde non usando noi più insieme parrà che noi siamo fatti nimici, e per il dire tu male di me, com’è tua usanza, non sarai tanto da essere biasimato, come se noi usassimo insieme. —"],"cs":["Jeden se přestal stýkat se svým přítelem, protože ten mu často špatně mluvil o jeho přátelích. Opuštěný přítel si mu jednoho dne stěžoval a po dlouhém naříkání ho prosil, aby mu řekl, co je příčinou, že zapomněl na tak velké přátelství. Ten mu odpověděl: – Nechci se s tebou už stýkat, protože tě mám rád a nechci, aby si o tobě ostatní, když jim budeš špatně mluvit o mně, svém příteli, udělali stejně jako já špatné mínění; když se tedy už nebudeme stýkat, bude se zdát, že jsme se stali nepřáteli, a když budeš o mně mluvit špatně, jak je tvým zvykem, nebudeš zasluhovat takovou hanu, jako kdybychom se stýkali. –"],"ref":{"s":"C.A","l":300,"st":"v","z":false,"raw":"C. A. 300 v"},"ca":[1641]},{"id":"s663","o":"Facezie","c":"VII","str":391,"ni":"detto di un infermo","nc":"Výrok nemocného","it":["Sendo uno infermo in articulo di morte, esso sentì battere la porta, e domandato uno de’ sua servi chi era, che batteva l’uscio, esso servo rispose esser una, che si chiamava madonna Bona. Allora l’infermo alzate le braccia ringraziò Dio con alta voce; poi disse ai servi che lasciassero venire presto questa, acciocchè potesse vedere una donna bona innanzi che esso morisse, imperocchè in sua vita mai ne vide nessuna."],"cs":["Když jeden nemocný ležel na smrtelné posteli, uslyšel klepat na dveře, a když se zeptal jednoho ze svých sluhů, kdo to klepe, sluha odpověděl, že jedna, která se jmenuje madonna Bona [bona = dobrá]. Tu nemocný zvedl ruce a hlasitě poděkoval Bohu; pak řekl sluhům, ať ji rychle pustí dovnitř, aby mohl spatřit dobrou ženu dřív, než umře, neboť za celý svůj život žádnou neviděl."],"ref":{"s":"R","l":1290,"st":"","z":false,"raw":"R. 1290"},"ca":[],"rr":"S. K. M. II.2 44 a"},{"id":"s664","o":"Facezie","c":"VIII","str":392,"ni":"detto di un dormiglione","nc":"Výrok spáče","it":["Fu detto a uno che si levasse dal letto, perchè già era levato il sole, e lui rispose: — se io avessi a fare tanto viaggio e faccende quanto lui, ancora io sarei già levato, e però, avendo a fare sì poco cammino, ancora non mi voglio levare. —"],"cs":["Jednomu řekli, aby vstal z postele, protože slunce už je vzhůru, a on odpověděl: – Kdybych měl vykonat tak dlouhou cestu a tolik práce jako ono, také bych už byl vzhůru; ale protože mám ujít tak kratičký kus cesty, ještě se mi vstávat nechce. –"],"ref":{"s":"R","l":1292,"st":"","z":false,"raw":"R. 1292"},"ca":[],"rr":"F. o'"},{"id":"s665","o":"Facezie","c":"IX","str":392,"ni":"arguzia","nc":"Vtip","it":["Uno vedendo una femmina parata a tener tavola in giostra, guardò il tavolaccio, e gridò vedendo la sua lancia: — ohimè! questo è troppo picciol lavorante a sì gran bottega! —"],"cs":["Jeden, vida ženu připravenou nastavit v turnaji štít, pohlédl na ten veliký štít, a pohlédnuv na své kopí, zvolal: – Běda! Na tak velikou dílnu je to příliš malý tovaryš! –"],"ref":{"s":"C.A","l":12,"st":"r","z":true,"raw":"C. A. 12 r"},"ca":[82,84]},{"id":"s666","o":"Facezie","c":"X","str":392,"ni":"risposta ad un motto","nc":"Odpověď na posměšek","it":["Uno vede una grande spada allato a un altro, e dice: — o poverello! ell’è gran tempo ch’io t’ho veduto legato a questa arme: perchè non ti disleghi, avendo le mani disciolte e possiedi libertà? — Al quale costui rispose: — questa è cosa non tua, anzi è vecchia. — Questi, sentendosi mordere, rispose: — io ti conosco sapere sì poche cose in questo mondo, ch’io credevo che ogni divulgata cosa a te fussi per nova. —"],"cs":["Jeden vidí u boku druhého velký meč a říká: – Ó chudáčku! Už dlouho tě vidím přivázaného k té zbrani: proč se neodvážeš, když máš ruce volné a jsi na svobodě? – Ten mu odpověděl: – Ten vtip není tvůj, je starý. – Onen, cítě se uštknut, odpověděl: – Vím, že toho na tomto světě znáš tak málo, že jsem myslel, že i každá obecně známá věc bude pro tebe novinkou. –"],"ref":{"s":"C.A","l":12,"st":"r","z":false,"raw":"C. A. 12 r"},"ca":[82,84]},{"id":"s667","o":"Facezie","c":"XI","str":393,"ni":"facezia ad un vantatore","nc":"Žert na chvastouna","it":["Uno disputando, e vantandosi di saper fare molti vari e belli giochi, un altro de’ circostanti disse: — io so fare uno gioco, il quale farà trarre le brache a chi a me parrà. — Il primo vantatore, trovandosi sanza brache: — che no, disse, che a me non le farai trarre! E vadane un paro di calze. — Il proponitore d’esso gioco, accettato lo ’nvito, improntò più para di brache, e trassele nel volto al mettitore delle calze, e vinse il pegno."],"cs":["Když se jeden přel a chlubil, že umí mnoho rozličných a pěkných kousků, jiný z přítomných řekl: – Já umím kousek, při kterém stáhne spodky, kdo se mi zlíbí. – První chvastoun, který žádné spodky neměl, řekl: – Ale kdepak, mně je stáhnout nedáš! A vsadím se o pár punčoch. – Navrhovatel toho kousku sázku přijal, vypůjčil si několik párů spodků, hodil je do obličeje tomu, kdo vsadil punčochy, a sázku vyhrál. [Slovní hříčka: trarre le brache znamená „stáhnout spodky“ i „hodit spodky“.]"],"ref":{"s":"C.A","l":75,"st":"v","z":false,"raw":"C. A. 75 v"},"ca":[408,410]},{"id":"s668","o":"Facezie","c":"XII","str":393,"ni":"risposta ad un motto","nc":"Odpověď na posměšek","it":["Uno disse a un suo conoscente: — tu hai tutti li occhi trasmutati in istrane colore. — Quello li rispose intervenirli spesso: — ma tu non ci hai posto cura. — E quando ti addivien questo? — Bispose l’altro: — ogni volta ch’e’ mia occhi veggono il tuo viso strano, per la violenza ricevuta da sì gran dispiacere, s’impallidiscono, e mutano in istrano colore. —"],"cs":["Jeden řekl svému známému: – Oči se ti celé zbarvily divnou barvou. – Ten mu odpověděl, že se mu to stává často: – ale tys toho dosud nedbal. – A kdy se ti to stává? – Odpověděl ten druhý: – Pokaždé, když mé oči spatří tvou divnou tvář, pro násilí, jež utrpí tak velkou nelibostí, zblednou a změní se v divnou barvu. –"],"ref":{"s":"C.A","l":75,"st":"v","z":false,"raw":"C. A. 75 v"},"ca":[408,410]},{"id":"s669","o":"Facezie","c":"XIII","str":394,"ni":"la stessa","nc":"Totéž","it":["Uno disse a un altro:— tu hai tutti li occhi mutati in istran colore. —","Quello li rispose: — egli è perchè i mia occhi veggono il tuo viso strano. —"],"cs":["Jeden řekl druhému: – Oči se ti celé zbarvily divnou barvou. –","Ten mu odpověděl: – To proto, že mé oči vidí tvou divnou tvář. –"],"ref":null,"ca":[]},{"id":"s670","o":"Facezie","c":"XIV","str":394,"ni":"motto","nc":"Posměšek","it":["Uno disse, che in suo paese nasceva le più strane cose del mondo. L’altro rispose: — tu che vi se’ nato, confermi ciò esser vero, per la stranezza della tua brutta presenza. —"],"cs":["Jeden řekl, že v jeho zemi se rodí nejdivnější věci na světě. Druhý odpověděl: – Ty, který ses tam narodil, to potvrzuješ divností své ošklivé postavy. –"],"ref":{"s":"C.A","l":75,"st":"v","z":false,"raw":"C. A. 75 v"},"ca":[408,410]},{"id":"s671","o":"Facezie","c":"XV","str":394,"ni":"facezia di un prete","nc":"Žert o knězi","it":["Una lavava i panni, e pel freddo avea i piedi molto rossi; e passandole appresso uno prete, domando, con ammirazione, donde tale rossezza derivassi; al quale la femmina subito rispose che tale effetto accadeva, perchè ella avea sotto il foco. Allora il prete mise mano a quello membro, che lo fece essere più prete che monaca, e, a quella accostandosi, con dolce e sommessiva voce, pregò quella che ’n cortesia li dovessi un poco accendere quella candela."],"cs":["Jedna žena prala prádlo a zimou měla nohy celé červené; a když šel kolem ní kněz, zeptal se s podivem, odkud ta červeň pochází; žena mu hned odpověděla, že je to proto, že má pod sebou oheň. Tu kněz sáhl na ten úd, který z něho dělal spíše kněze než jeptišku, a přistoupiv k ní, sladkým a pokorným hlasem ji prosil, aby mu z laskavosti trochu zapálila tu svíci."],"ref":{"s":"C","l":19,"st":"v","z":false,"raw":"C. 19 v"},"ca":[]},{"id":"s672","o":"Facezie","c":"XVI","str":395,"ni":"facezia","nc":"Žert","it":["Uno, andando a Modana, ebbe a pagare 5 soldi di Lira di gabella della sua persona.","Alla qual cosa cominciato a fare gran romore e ammirazione, attrasse a sè molti circustanti; i quali domandando donde veniva tanta maraviglia, ai quali Maso rispose: — oh! non mi debbo io maravigliare? conciossia che tutto un omo non paghi altro che 5 soldi di Lira, e a Firenze io, solo a metter dentro il c..., ebbi a pagare 10 ducati d’oro, e qui metto il c...., i c.... e tutto il resto per sì piccol dazio. Dio salvi e mantenga tal città, e chi la governa!—"],"cs":["Jeden, když šel do Modeny, musel zaplatit za svou osobu mýto 5 soldů z liry.","Začal nad tím dělat velký povyk a podivovat se, takže kolem sebe shromáždil mnoho přihlížejících; a když se ptali, odkud se bere takový údiv, Maso jim odpověděl: – Ó! Což se nemám divit? Vždyť tady celý člověk neplatí víc než 5 soldů z liry, a ve Florencii jsem já, jen abych tam dostal ten svůj č..., musel zaplatit 10 zlatých dukátů, a tady vnesu č...., k.... a všechno ostatní za tak malé clo. Bůh ochraňuj a zachovej takové město i toho, kdo mu vládne! –"],"ref":{"s":"H","l":37,"st":"r","z":false,"raw":"H. 37 r"},"ca":[]},{"id":"s673","o":"Facezie","c":"XVII","str":395,"ni":"biotto arguto","nc":"Bystrý vtip","it":["Due camminando di notte per dubbiosa via, quello dinanzi fece grande strepito col culo; e disse l’altro compagno: — or veggo io ch’i’ son da te amato. — Come? disse l’altro. — Quel rispose: — tu mi porgi la coreggia, perch’io non caggia, nè mi perda da te.—"],"cs":["Dva šli v noci nejistou cestou, a ten vpředu hlasitě zahřměl zadkem; a druhý řekl: – Teď vidím, že mě máš rád. – Jak to? řekl ten první. – Ten odpověděl: – Podáváš mi řemen, abych neupadl a neztratil se ti. – [Slovní hříčka: coreggia znamená „řemen“ i „prd“.]"],"ref":null,"ca":[]},{"id":"s674","o":"Facezie","c":"XVIII","str":396,"ni":"motto detto da un giovane a un vecchio","nc":"Výrok mladíka ke starci","it":["Dispregiando un vecchio pubblicamente un giovane, mostrando audacemente non temer quello, onde il giovane li rispose che la sua lunga età li faceva migliore scudo che la lingua o la forza."],"cs":["Když jeden stařec veřejně tupil mladíka a troufale dával najevo, že se ho nebojí, mladík mu odpověděl, že jeho dlouhý věk mu je lepším štítem než jazyk nebo síla."],"ref":null,"ca":[]},{"id":"s675","o":"Facezie","c":"XIX","str":396,"ni":"facezia","nc":"Žert","it":["Perchè li Ungheri tengon la croce doppia."],"cs":["Proč mají Uhři dvojitý kříž."],"ref":null,"ca":[]}]};
